window.KANJI_SITE={"meta":{"source":"https://nihongokanji.com/","fetchedAt":"2026-10-26T01:11:19.936Z","usage":"개인 학습용 저장·표시, 재배포 금지","total":2136},"items":{"日":{"id":1,"char":"日","hun":"날 일","meaning":"“날 일”. 하루, 날, 태양","on":"ニチ、ジツ","kun":"ひ、か","explanation":["日는 “태양”의 모습을 본따 그린 상형문자입니다.","“해가 뜨고 지다” -> “하루, 태양”이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/8/"},"一":{"id":2,"char":"一","hun":"한 일","meaning":"“한 일”. 하나, 1","on":"イチ、イツ","kun":"ひと、ひと(つ)","explanation":["一는 “선 하나”로 1을 표현한 상형문자입니다."],"sourceUrl":"https://nihongokanji.com/9/"},"国":{"id":3,"char":"国","hun":"나라 국","meaning":"“나라 국”. 나라, 국가","on":"コク","kun":"くに","explanation":["国 = 囗 + 玉。","囗는 여기서는 “국경, 경계선”을 표현한 모양자입니다.","「玉」는 “구슬, 보석”을 뜻하는 부수입니다(링크 참조).","国는 “국경(囗)으로 귀중한 것(玉)을 둘러싸고 지키다” -> “나라”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/10/"},"会":{"id":4,"char":"会","hun":"모일 회","meaning":"“모일 회”. 모이다, 만나다","on":"カイ、エ","kun":"あ(う)","explanation":["会 = 人 + 云。","人는 여기서는 “하늘”을 그린 모양자입니다.","「云」는 “구름”을 뜻하는 글자입니다(링크 참조).","会는 “하늘(人)의 구름(云)이 만나다” -> “모이다, 만나다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/11/"},"人":{"id":5,"char":"人","hun":"사람 인","meaning":"“사람 인”. 사람","on":"ジン、ニン","kun":"ひと","explanation":["人는 “걷고 있는 사람의 옆모습”을 그린 상형문자입니다."],"sourceUrl":"https://nihongokanji.com/12/"},"年":{"id":6,"char":"年","hun":"해 년","meaning":"“해 년”. 해(year)","on":"ネン","kun":"とし","explanation":["年 = 𠂉 + 㐄。","𠂉는 여기서는 「人」가 변형된 것으로, “사람”을 뜻합니다.","「㐄」는 “발”을 뜻하는 글자입니다(링크 참조).","年는 “사람(𠂉)이 걸음마(㐄)를 떼려면 일 년이 걸린다” -> “한 해”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/13/"},"大":{"id":7,"char":"大","hun":"클 대","meaning":"“클 대”. 크다","on":"ダイ、タイ","kun":"おお、おお(きい)、おお(いに)","explanation":["大는 “양 팔을 벌리고 선 사람”을 그린 상형문자입니다.","“서있는 사람” -> “키가 크다” -> “크다”라는 의미입니다.","참고)","大가 다른 한자의 일부로 쓰일 때는 단순히 “사람”이라는 뜻으로 쓰이는 경우가 많습니다."],"sourceUrl":"https://nihongokanji.com/14/"},"十":{"id":8,"char":"十","hun":"열 십","meaning":"“열 십”. 10","on":"ジュウ、ジッ","kun":"とお、と","explanation":["옛날 중국에서는 막대를 세로로 세워서(│) “10”을 표현했다고 합니다.","거기에 가로선을 더해서 구분하기 쉽게 만든 것이 바로 十입니다."],"sourceUrl":"https://nihongokanji.com/15/"},"二":{"id":9,"char":"二","hun":"두 이","meaning":"“두 이”. 2","on":"ニ","kun":"ふた、ふた(つ)","explanation":["二는 선 두 개로 “2”를 표현한 글자입니다."],"sourceUrl":"https://nihongokanji.com/16/"},"本":{"id":10,"char":"本","hun":"근본 본","meaning":"“근본 본”. 근본, 본질, 본래","on":"ホン","kun":"もと","explanation":["本 = 木 + 一。","木(“나무 목”)은 “나무”를 뜻하는 상용한자입니다.","一는 여기서는 “나무 밑동”을 그린 모양자입니다.","本는 “나무(木)의 밑동(一)” -> “뿌리” -> “근본, 본질, 본래”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/17/"},"中":{"id":11,"char":"中","hun":"가운데 중","meaning":"“가운데 중”. 중간, 가운데","on":"チュウ、ジュウ","kun":"なか","explanation":["中 = 口 +⼁。","中는 “물건(口)의 중심을 꿰뚫다(⼁)” -> “중심, 중간”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/18/"},"長":{"id":12,"char":"長","hun":"길 장","meaning":"“길 장”. 길다","on":"チョウ","kun":"なが(い)","explanation":["長는 “머리가 긴 노인이 지팡이를 짚고 걸어가는 모습”을 그린 상형문자입니다.","“머리가 긴 노인” -> “머리가 길다” -> “길다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/20/"},"出":{"id":13,"char":"出","hun":"날 출","meaning":"“날 출”. 나가다, 내보내다","on":"シュツ、スイ","kun":"で(る)、だ(す)","explanation":["出 = 屮 + 凵。","屮는 여기서는 “새의 발”을 그린 모양자입니다.","凵는 여기서는 “동굴”을 그린 모양자입니다.","出는 “동굴(凵)밖으로 걸어나가는 발(屮)” -> “나가다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/21/"},"三":{"id":14,"char":"三","hun":"셋 삼","meaning":"“셋 삼”. 3","on":"サン","kun":"み、み(つ)、みっ(つ)","explanation":["三는 선 세 개로 “3”을 나타낸 글자입니다."],"sourceUrl":"https://nihongokanji.com/22/"},"時":{"id":15,"char":"時","hun":"때 시","meaning":"“때 시”. 시간","on":"ジ","kun":"とき","explanation":["時 = 日 + 寺。","(의미부) 「日」는 “하루, 태양”을 뜻합니다.","(소리부) 寺(ジ – “절 사”)는 “절, 사찰”을 뜻하는 상용한자입니다.","다만 여기서는 소리부(ジ)의 역할만 하고 있습니다.","時는 “하루(日)” -> “시간”이라는 뜻의 글자입니다(寺는 소리부)."],"sourceUrl":"https://nihongokanji.com/23/"},"行":{"id":16,"char":"行","hun":"다닐 행","meaning":"“다닐 행”. 가다, 행하다, 행(row)","on":"コウ、ギョウ、アン","kun":"い(く)、ゆ(く)、おこな(う)","explanation":["行는 “두 길이 교차하는 사거리”를 그린 상형문자입니다.","“사거리” -> “길을 가다, 이동하다” -> “가다, 행하다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/24/"},"社":{"id":17,"char":"社","hun":"모일 사","meaning":"“모일 사”. 모이다, 단체, 사회, 신사","on":"シャ","kun":"やしろ","explanation":["社 = 礻 + 土。","「礻」는 “종교, 신, 고대의 비석”을 뜻하는 부수입니다(링크 참조).","土(“흙 토”)는 “흙, 땅”을 뜻하는 상용한자입니다.","社는 “토지(土)의 신(礻)에게 제사지내기 위해 모이다” -> “모이다, 단체, 사회, 신사”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/25/"},"見":{"id":18,"char":"見","hun":"볼 견","meaning":"“볼 견”. 보다","on":"ケン","kun":"み(る)、み(える)、み(せる)","explanation":["見 = 目 + 儿。","目(“눈 목”)은 “눈”을 뜻하는 상용한자입니다.","儿는 「人」가 살짝 변형된 것으로, “사람”을 뜻합니다.","見는 “사람(儿)의 눈(目)” -> “보다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/26/"},"月":{"id":19,"char":"月","hun":"달 월","meaning":"“달 월”. 달","on":"ゲツ、ガツ","kun":"つき","explanation":["月는 “초승달”을 본따 그린 상형문자입니다."],"sourceUrl":"https://nihongokanji.com/27/"},"分":{"id":20,"char":"分","hun":"나눌 분","meaning":"“나눌 분”. 나누다, 분(시간 단위), 알다","on":"ブン、フン、ブ","kun":"わ(ける)、わ(かれる)、わ(かる)、わ(かつ)","explanation":["分 = ハ + 刀。","ハ는 여기서는 “무언가가 둘로 쪼개진 모습”을 표현한 모양자입니다.","「刀」(“칼 도”)는 “칼”을 뜻하는 부수입니다(링크 참조).","分는 “칼(刀)로 베어서 둘로 쪼개다(ハ)” -> “나누다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/28/"},"後":{"id":21,"char":"後","hun":"뒤 후","meaning":"“뒤 후”. 뒤, 이후, 나중.","on":"ゴ、コウ","kun":"あと、のち、うし(ろ)、おく(れる)","explanation":["後 = 彳 + 幺 + 夂。","「彳」는 “길”을 뜻하는 부수입니다(링크 참조).","「幺」는 “작다, 어리다”라는 뜻의 글자입니다(링크 참조).","「夂」는 “발”을 뜻하는 부수입니다(링크 참조).","後는 “길(彳)에서 어린아이(幺)가 부모 뒤를 졸졸 따라가다(夂)”라는 뜻입니다.","“뒤를 따라가다” -> “뒤, 나중”이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/29/"},"前":{"id":22,"char":"前","hun":"앞 전","meaning":"“앞 전”. 앞","on":"ゼン","kun":"まえ","explanation":["前 = 䒑 + 月 + 刂。","「刂」는 “칼”을 뜻하는 부수입니다(링크 참조).","「月」는 “고기”를 뜻하는 부수입니다(링크 참조).","䒑는 여기서는 “고기(月)의 앞부분”을 강조하기 위해 쓰인 모양자입니다.","前는 “고기(月)의 앞부분(䒑)을 칼(刂)로 잘라내다” -> “앞”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/30/"},"生":{"id":23,"char":"生","hun":"살 생","meaning":"“살 생”. 살다, 태어나다, 생명","on":"セイ、ショウ","kun":"い(きる)、い(かす)、う(まれる)、う(む)、は(える)、は(やす)、き、なま、い(ける)","explanation":["生는 “새싹이 돋아나는 모습”을 그린 상형문자입니다.","“새싹” -> “생명, 태어나다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/31/"},"五":{"id":24,"char":"五","hun":"다섯 오","meaning":"“다섯 오”. 다섯","on":"ゴ","kun":"いつ、いつ(つ)","explanation":["고대에는 나무막대기를 엇갈려 늘어놓는 식으로 “5”를 표현했다고 합니다.","五는 그 모습을 그대로 본따 그린 상형문자입니다."],"sourceUrl":"https://nihongokanji.com/32/"},"間":{"id":25,"char":"間","hun":"사이 간","meaning":"“사이 간”. 사이, 간격, 틈새","on":"カン、ケン","kun":"あいだ、ま","explanation":["間 = 門 + 日。","門(“문 문”)은 “문”을 뜻하는 상용한자입니다.","「日」는 “태양”을 뜻합니다.","間는 “문틈(門) 사이로 햇빛(日)이 들어오다” -> “사이, 간격, 틈새”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/33/"},"上":{"id":26,"char":"上","hun":"윗 상","meaning":"“윗 상”. 위, 위쪽, 오르다","on":"ジョウ、ショウ","kun":"うえ、うわ、かみ、あ(げる)、あ(がる)、のぼ(る)、のぼ(す)、のぼ(せる)","explanation":["上는 “손가락으로 위쪽을 가리키고 있는 모습”을 그린 지사문자입니다."],"sourceUrl":"https://nihongokanji.com/34/"},"東":{"id":27,"char":"東","hun":"동녘 동","meaning":"“동녘 동”. 동쪽","on":"トウ","kun":"ひがし","explanation":["東 = 木 + 日。","木(“나무 목”)은 “나무”를 뜻하는 상용한자입니다.","「日」는 “태양”을 뜻합니다.","東는 “아침해(日)가 나무(木)에 걸린 모습”을 그린 글자입니다.","“아침해는 동쪽에서 뜬다” -> “동쪽”이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/35/"},"四":{"id":28,"char":"四","hun":"넷 사","meaning":"“넷 사”. 넷","on":"シ","kun":"よ、よん、よ(つ)、よっ(つ)","explanation":["四는 본래 “사람의 콧구멍”을 그린 것으로, 원래 뜻은 “숨쉬다”였습니다.","그러나 이후 4와 발음이 같다는 이유로 “4”라는 뜻으로 쓰이게 된 것입니다.","즉, 四의 모양과 의미 사이에는 아무런 관계도 없습니다."],"sourceUrl":"https://nihongokanji.com/36/"},"今":{"id":29,"char":"今","hun":"이제 금","meaning":"“이제 금”. 지금, 현재","on":"コン、キン","kun":"いま","explanation":["今는 “말하고 있는 입모양”을 그린 상형문자입니다.","“지금 말하는 중” -> “지금”이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/37/"},"新":{"id":30,"char":"新","hun":"새 신","meaning":"“새 신”. 새롭다, 새것, 새로운","on":"シン","kun":"あたら(しい)、あら(た)、にい","explanation":["新 = 立 + 木 + 斤。","立(“설 립”)은 “서다”라는 뜻의 상용한자입니다.","木(“나무 목”)은 “나무”를 뜻하는 상용한자입니다.","「斤」는 “도끼”를 뜻하는 부수입니다(링크 참조).","新는 “우뚝 선(立) 나무(木)를 베어서(斤) 새로운 물건을 만들다” -> “새롭다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/38/"},"金":{"id":31,"char":"金","hun":"쇠 금","meaning":"“쇠 금”. 금, 금속, 쇠, 돈","on":"キン、コン","kun":"かね、かな","explanation":["金는 “산 속에 묻힌 황금”을 그린 상형문자입니다."],"sourceUrl":"https://nihongokanji.com/39/"},"九":{"id":32,"char":"九","hun":"아홉 구","meaning":"“아홉 구”. 아홉","on":"キュウ、ク","kun":"ここの、ここの(つ)","explanation":["九는 본래는 “팔꿈치”를 그린 상형문자입니다.","그러나 이후 발음이 같다는 이유로 “9”라는 뜻으로 쓰이게 된 것입니다.","즉, 九의 모양과 의미 사이에는 아무런 관계도 없습니다.","(숫자를 의미하는 한자들 중에는 이런 것들이 많습니다.)"],"sourceUrl":"https://nihongokanji.com/40/"},"入":{"id":33,"char":"入","hun":"들 입","meaning":"“들 입”. 들어가다, 집어넣다","on":"ニュウ","kun":"はい(る)、い(る)、い(れる)","explanation":["入는 “뾰족한 쐐기”를 그린 상형문자입니다.","“뾰족한 쐐기를 꽂아넣다” -> “들어가다, 넣다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/41/"},"立":{"id":34,"char":"立","hun":"설 립","meaning":"“설 립”. 서다","on":"リツ、リュウ","kun":"た(つ)、た(てる)","explanation":["立는 “양 팔을 벌리고 서있는 사람”을 그린 상형문자입니다.","“서있는 사람” -> “서다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/42/"},"手":{"id":35,"char":"手","hun":"손 수","meaning":"“손 수”. 손","on":"シュ","kun":"て、た","explanation":["手는 “손과 손가락”을 본따 그린 상형문자입니다."],"sourceUrl":"https://nihongokanji.com/43/"},"学":{"id":36,"char":"学","hun":"배울 학","meaning":"“배울 학”. 배우다","on":"ガク","kun":"まな(ぶ)","explanation":["学 = ⺍ ＋ 冖 ＋ 子。","「⺍＋冖」는 “불이 환하게 켜진 집”을 뜻합니다(링크 참조).","子(“아들 자”)는 “아이”를 뜻하는 상용한자입니다.","学는 “아이(子)가 밤늦게까지(⺍＋冖) 열심히 공부하다” -> “배우다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/44/"},"高":{"id":37,"char":"高","hun":"높을 고","meaning":"“높을 고”. 높다","on":"コウ","kun":"たか(い)、たか、たか(まる)、たか(める)","explanation":["高는 “높이 쌓아올려진 누각”을 본따 그린 상형문자입니다.","“높은 누각” -> “높다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/45/"},"円":{"id":38,"char":"円","hun":"둥글 원","meaning":"“둥글 원”. 둥글다, 원","on":"エン","kun":"まる(い)","explanation":["円은 “둥근 가마솥”을 본따 그린 상형문자입니다.","“둥근 가마솥” -> “둥글다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/46/"},"子":{"id":39,"char":"子","hun":"아들 자","meaning":"“아들 자”. 아이","on":"シ、ス","kun":"こ","explanation":["子는 “강보에 싸인 아기”를 그린 상형문자입니다."],"sourceUrl":"https://nihongokanji.com/47/"},"目":{"id":40,"char":"目","hun":"눈 목","meaning":"“눈 목”. 눈","on":"モク、ボク","kun":"め、ま","explanation":["目는 “눈”을 본따 그린 상형문자입니다."],"sourceUrl":"https://nihongokanji.com/48/"},"外":{"id":41,"char":"外","hun":"바깥 외","meaning":"“바깥 외”. 바깥","on":"ガイ、ゲ","kun":"そと、ほか、はず(す)、はず(れる)","explanation":["外 = 夕 + 卜。","夕(“저녁 석”)은 “저녁”을 뜻하는 상용한자입니다.","「卜」는 “점, 점괘”를 뜻하는 부수입니다(링크 참조).","外는 “저녁(夕)에 치는 점(卜)”이라는 뜻입니다.","고대 중국에서는 낮에 점을 치는 것이 관례였다고 합니다.","저녁에 점을 치는 것은 예외적인 경우에 한해서 가능한 일이었습니다.","外는 “저녁에 치는 점” -> “예외” -> “바깥”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/49/"},"言":{"id":42,"char":"言","hun":"말씀 언","meaning":"“말씀 언”. 말, 단어, 말하다","on":"ゲン、ゴン","kun":"い(う)、こと","explanation":["言 = ニ + ニ + 口。","ニ+ニ는 여기서는 “소리(음파)”를 표현한 모양자입니다.","口(“입 구”)는 “입”을 뜻하는 상용한자입니다.","言는 “입(口)에서 퍼져나가는 소리(ニ+ニ)“ -> “말하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/50/"},"八":{"id":43,"char":"八","hun":"여덟 팔","meaning":"“여덟 팔”. 여덟","on":"ハチ","kun":"や、や(つ)、やっ(つ)、よう","explanation":["八는 본래 “사물이 반으로 쪼개진 모습”을 그린 글자입니다.","그러나 이후 발음이 비슷하다는 이유로 “8”이라는 뜻으로 쓰이게 된 것입니다.","즉, 八의 모양과 의미 사이에는 아무런 관계도 없습니다."],"sourceUrl":"https://nihongokanji.com/51/"},"六":{"id":44,"char":"六","hun":"여섯 육","meaning":"“여섯 육”. 여섯","on":"ロク","kun":"む(つ)、むっ(つ)、むい","explanation":["六의 기원에 대해서는 명확히 알려진 바가 없습니다.","숫자를 나타내는 한자 대부분이 그렇듯, 六 또한 한자의 모양과 의미 사이에는 아무런 관계도 없는 글자입니다."],"sourceUrl":"https://nihongokanji.com/52/"},"下":{"id":45,"char":"下","hun":"아래 하","meaning":"“아래 하”. 아래, 아래쪽","on":"カ、ゲ","kun":"した、しも、もと、さ(げる)、さ(がる)、くだ(る)、くだ(す)、くだ(さる)、お(ろす)、お(りる)","explanation":["下는 “손가락으로 아래쪽을 가리키고 있는 모습”을 표현한 지사문자입니다."],"sourceUrl":"https://nihongokanji.com/53/"},"来":{"id":46,"char":"来","hun":"올 래","meaning":"“올 래”. 오다","on":"ライ","kun":"く(る)、きた(る)、きた(す)","explanation":["来는 “동물의 발자국”을 본따 그린 상형문자입니다.","“들짐승이 다가오다” -> “오다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/54/"},"気":{"id":47,"char":"気","hun":"기운 기","meaning":"“기운 기”. 기운, 정신, 기체","on":"キ、ケ","kun":"","explanation":["気 = 气 + 㐅。","气는 “하늘의 구름이 흘러가는 모습”을 그린 모양자입니다.","㐅는 여기서는 단순히 장식으로 더해진 것입니다.","気는 “구름이 흘러가다(气)” -> “기운이 흐르다” -> “기운, 기”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/55/"},"小":{"id":48,"char":"小","hun":"작을 소","meaning":"“작을 소”. 작다","on":"ショウ","kun":"ちい(さい)、こ、お","explanation":["小는 “작은 물방울 세 개가 튀는 모습”을 그린 상형문자입니다.","“작은 물방울 파편들” -> “작다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/56/"},"七":{"id":49,"char":"七","hun":"일곱 칠","meaning":"“일곱 칠”. 일곱","on":"シチ","kun":"なな、なな(つ)、なの","explanation":["七는 본래 “칼로 무언가를 내리치는 모습”을 그린 상형문자입니다.","그러나 이후 발음이 같다는 이유로 “7”이라는 뜻으로 쓰이게 된 것입니다.","즉, 七의 모양과 의미 사이에는 아무런 관계도 없습니다."],"sourceUrl":"https://nihongokanji.com/57/"},"山":{"id":50,"char":"山","hun":"메 산","meaning":"“메 산”. 산","on":"サン","kun":"やま","explanation":["山는 “산”의 모습을 본따 그린 상형문자입니다."],"sourceUrl":"https://nihongokanji.com/58/"},"話":{"id":51,"char":"話","hun":"말씀 화","meaning":"“말씀 화”. 이야기, 대화","on":"ワ","kun":"はな(す)、はなし","explanation":["話 = 言 + 舌。","「言」는 “말하다”라는 뜻입니다.","「舌」는 “혀”를 뜻하는 부수입니다(링크 참조).","話는 “혀(舌)를 움직이며 말하다(言)” -> “이야기, 대화”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/59/"},"多":{"id":52,"char":"多","hun":"많을 다","meaning":"“많을 다”. 많다","on":"タ","kun":"おお(い)","explanation":["多는 “똑같은 물건이 여러 개 쌓여있는 모습”을 그린 상형문자입니다.","“물건이 많이 쌓여있다” -> “많다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/60/"},"安":{"id":53,"char":"安","hun":"편안 안","meaning":"“편안 안”. 편안하다","on":"アン","kun":"やす(い)","explanation":["安 = 宀 + 女。","「宀」는 “집”을 뜻하는 부수입니다(링크 참조).","女(“계집 녀”)는 “여자”를 뜻하는 상용한자입니다.","安는 “안락한 집(宀)안에 앉아있는 여자(女)” -> “편안하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/61/"},"女":{"id":54,"char":"女","hun":"계집 녀","meaning":"“계집 녀”. 여자","on":"ジョ、ニョ、ニョウ","kun":"おんな、め","explanation":["女는 “앉아있는 여자의 옆모습”을 본따 그린 상형문자입니다."],"sourceUrl":"https://nihongokanji.com/62/"},"北":{"id":55,"char":"北","hun":"북녘 북","meaning":"“북녘 북”. 북쪽","on":"ホク","kun":"きた","explanation":["北는 “두 사람이 등을 맞대고 있는 모습”을 그린 상형문자입니다.","“등을 맞대다” -> “등 뒤” -> “북쪽”이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/63/"},"午":{"id":56,"char":"午","hun":"낮 오","meaning":"“낮 오”. 정오","on":"ゴ","kun":"","explanation":["午는 본래 “절굿공이”를 그린 상형문자입니다.","그러나 이후 발음이 같다는 이유로 “정오”라는 뜻으로 쓰이게 된 것입니다.","즉, 午의 모양과 의미 사이에는 아무런 관계도 없습니다."],"sourceUrl":"https://nihongokanji.com/64/"},"百":{"id":57,"char":"百","hun":"일백 백","meaning":"“일백 백”. 100","on":"ヒャク","kun":"","explanation":["百는 “천장에 매달려있는 벌집”을 그린 상형문자입니다.","“벌집 하나에 벌이 100마리는 들어있다” -> “100”이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/65/"},"書":{"id":58,"char":"書","hun":"글 서","meaning":"“글 서”. 글, 쓰다","on":"ショ","kun":"か(く)","explanation":["書 = 聿 + 曰。","「聿」는 “붓을 든 손”을 뜻하는 부수입니다(링크 참조).","「曰」는 “말하다”라는 뜻의 부수입니다(링크 참조).","書는 “붓을 들고(聿) 상대의 말(曰)을 받아적다” -> “글, 쓰다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/66/"},"先":{"id":59,"char":"先","hun":"먼저 선","meaning":"“먼저 선”. 먼저, 앞서","on":"セン","kun":"さき","explanation":["先 = 牛 + 儿。","「𠂒」는 “소”를 뜻하는 글자입니다(링크 참조).","儿는 「人」가 살짝 변형된 것으로, “사람”을 뜻합니다.","先는 “소(𠂒)를 앞세우고 걷는 사람(儿)” -> “앞, 먼저”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/67/"},"名":{"id":60,"char":"名","hun":"이름 명","meaning":"“이름 명”. 이름","on":"メイ、ミョウ","kun":"な","explanation":["名 = 夕 + 口。","夕(“저녁 석”)은 “저녁”을 뜻하는 상용한자입니다.","口(“입 구”)는 “입”을 뜻하는 상용한자입니다.","먼 옛날에는 밤이 되면 불을 밝힐 수단이 없었습니다.","그래서 멀리 있는 사람을 구분하려면, 이름을 불러 확인할 수밖에 없었습니다.","名는 “어두운 밤(夕)에 이름을 불러(口) 상대방을 구분하다” -> “이름”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/68/"},"川":{"id":61,"char":"川","hun":"내 천","meaning":"“내 천”. 강, 하천, 시내","on":"セン","kun":"かわ","explanation":["川는 “강물이 흘러가는 모습”을 그린 상형문자입니다."],"sourceUrl":"https://nihongokanji.com/69/"},"千":{"id":62,"char":"千","hun":"일천 천","meaning":"“일천 천”. 1000","on":"セン","kun":"ち","explanation":["千 = 人 + 一。","「人」는 “사람”을 뜻합니다.","一는 여기서는 단순한 구분선으로 쓰인 것입니다.","고대 중국에서는 人에 선을 하나씩 추가하는 식으로 “천 명” 단위를 표기했다고 합니다.","선 하나면 1000명, 두개면 2000명과 같은 식입니다.","千는 그러한 전통으로부터 유래한 글자입니다."],"sourceUrl":"https://nihongokanji.com/70/"},"道":{"id":63,"char":"道","hun":"길 도","meaning":"“길 도”. 길, 도로","on":"ドウ、トウ","kun":"みち","explanation":["道 = ⻌ + 首。","「⻌」는 “길”을 뜻하는 부수입니다(링크 참조).","「首」는 “머리”를 뜻하는 부수입니다(링크 참조).","여기서는 “머리” -> “우두머리”라는 뜻으로 쓰인 것입니다.","道는 “무리를 이끌며 길(⻌)을 행진하는 우두머리(首)”라는 뜻입니다.","“길을 행진하다” -> “길, 도로”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/71/"},"水":{"id":64,"char":"水","hun":"물 수","meaning":"“물 수”. 물","on":"スイ","kun":"みず","explanation":["水는 “물이 흘러가는 모습”을 그린 상형문자입니다."],"sourceUrl":"https://nihongokanji.com/72/"},"半":{"id":65,"char":"半","hun":"반 반","meaning":"“반 반”. 절반","on":"ハン","kun":"なか(ば)","explanation":["半는 “무언가를 정확히 절반으로 자르는 모습”을 그린 상형문자입니다.","“절반으로 자르다” -> “절반”이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/73/"},"男":{"id":66,"char":"男","hun":"사내 남","meaning":"“사내 남”. 남자","on":"ダン、ナン","kun":"おとこ","explanation":["男 = 田 + 力。","田(“밭 전”)은 “밭”을 뜻하는 상용한자입니다.","力(“힘 력”)은 “힘”을 뜻하는 상용한자입니다.","男는 “밭(田)에서 힘(力)을 써서 농사를 짓는 사람” -> “남자”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/74/"},"西":{"id":67,"char":"西","hun":"서녘 서","meaning":"“서녘 서”. 서쪽","on":"セイ、サイ","kun":"にし","explanation":["西는 “새의 둥지”를 본따 그린 상형문자입니다.","“해가 서쪽으로 지면 새가 둥지로 돌아간다” -> “서쪽”이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/75/"},"電":{"id":68,"char":"電","hun":"번개 전","meaning":"“번개 전”. 전기, 번개","on":"デン","kun":"","explanation":["電 = 雨 + 电。","雨(“비 우”)는 “비”를 뜻하는 상용한자입니다.","「电」는 “번개”를 뜻하는 글자입니다(링크 참조).","電는 “비(雨)가 오고 번개(电)가 내리치다” -> “전기, 번개”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/76/"},"口":{"id":69,"char":"口","hun":"입 구","meaning":"“입 구”. 입","on":"コウ、ク","kun":"くち","explanation":["口는 “벌린 입”을 그린 상형문자입니다."],"sourceUrl":"https://nihongokanji.com/77/"},"少":{"id":70,"char":"少","hun":"적을 소","meaning":"“적을 소”. 적다","on":"ショウ","kun":"すく(ない)、すこ(し)","explanation":["少는 “작은 물방울 네 개가 튀는 모습”을 그린 상형문자입니다(「小」와 유래가 같습니다).","고대 중국에서는 小、少 모두 “작다”라는 뜻으로 쓰였다고 합니다.","그러나 시간이 지나며 少는 “적다”, 小는 “작다”로 뜻이 분리되어 쓰이게 된 것입니다."],"sourceUrl":"https://nihongokanji.com/78/"},"校":{"id":71,"char":"校","hun":"학교 교","meaning":"“학교 교”. 학교","on":"コウ","kun":"","explanation":["校 = 木 + 交。","(의미부) 木(“나무 목”)은 “나무”를 뜻하는 상용한자입니다.","(소리부 겸 의미부) 交(コウ – “사귈 교”)는 “교차하다, 교제하다”라는 뜻의 상용한자입니다.","校는 “나무(木) 밑에서 친구들과 교제하며(交) 많은 것을 배우다” -> “학교”라는 뜻의 글자입니다.","(交는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/79/"},"語":{"id":72,"char":"語","hun":"말씀 어","meaning":"“말씀 어”. 단어, 언어","on":"ゴ","kun":"かた(る)、かた(らう)","explanation":["語 = 言 + 五 + 口。","(의미부) 「言」는 “말하다”라는 뜻입니다.","(의미부) 「口」는 “입”을 뜻합니다.","(소리부) 「五」(ゴ)는 여기서는 소리부의 역할만 하고 있습니다.","語는 “입(口)으로 말하다(言)” -> “단어, 언어”라는 뜻의 글자입니다(五는 소리부)."],"sourceUrl":"https://nihongokanji.com/80/"},"空":{"id":73,"char":"空","hun":"빌 공","meaning":"“빌 공”. 허공, 비어있음","on":"クウ","kun":"そら、から、あ(ける)、あ(く)","explanation":["空 = 穴 + 工。","(의미부) 「穴」는 “구멍”을 뜻하는 부수입니다(링크 참조).","(소리부) 工(コウ、ク – “장인 공”)은 “공작, 가공”을 뜻하는 상용한자입니다.","다만 여기서는 소리부(コウ・ク -> クウ)의 역할만 하고 있습니다.","空는 “텅 빈 구멍(穴)” -> “비어있다”라는 뜻의 글자입니다(工는 소리부)."],"sourceUrl":"https://nihongokanji.com/81/"},"土":{"id":74,"char":"土","hun":"흙 토","meaning":"“흙 토”. 흙, 땅","on":"ド、ト","kun":"つち","explanation":["土는 “땅에 새싹이 돋아난 모습”을 그린 상형문자입니다.","“흙 위에 돋아난 새싹” -> “흙, 땅”이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/82/"},"木":{"id":75,"char":"木","hun":"나무 목","meaning":"“나무 목”. 나무","on":"ボク、モク","kun":"き、こ","explanation":["木는 “나무”의 모습을 본따 그린 상형문자입니다."],"sourceUrl":"https://nihongokanji.com/83/"},"聞":{"id":76,"char":"聞","hun":"들을 문","meaning":"“들을 문”. 듣다","on":"ブン、モン","kun":"き(く)、き(こえる)","explanation":["聞 = 門 + 耳。","門(“문 문”)은 “문”을 뜻하는 상용한자입니다.","耳(“귀 이”)는 “귀”를 뜻하는 상용한자입니다.","聞은 “문(門) 밖에서 나는 소리를 귀기울여(耳) 듣다” -> “듣다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/84/"},"食":{"id":77,"char":"食","hun":"먹을 식","meaning":"“먹을 식”. 먹다","on":"ショク、ジキ","kun":"た(べる)、く(う)、く(らう)","explanation":["食는 “음식이 담긴 식기”를 그린 상형문자입니다.","윗부분은 뚜껑, 중간부분은 음식, 아랫부분은 식기를 표현한 것입니다.","“음식이 담긴 식기” -> “먹다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/85/"},"車":{"id":78,"char":"車","hun":"수레 차(거)","meaning":"“수레 차(거)”. 차량, 수레","on":"シャ","kun":"くるま","explanation":["車는 “수레”의 모습을 본따 그린 상형문자입니다."],"sourceUrl":"https://nihongokanji.com/86/"},"何":{"id":79,"char":"何","hun":"어찌 하","meaning":"“어찌 하”. 무엇(what)","on":"カ","kun":"なに、なん","explanation":["何 = 亻 + 可。","「亻」는 “사람”을 뜻하는 부수입니다(링크 참조).","可는 여기서는”짐보따리”를 표현한 모양자입니다(위 그림 참조).","何는 “짐보따리(可)를 싸들고 집을 떠나는 사람(亻)”을 그린 글자입니다.","집을 떠나는 사람에게는 떠나는 이유가 있을 것입니다.","“떠나는 이유가 무엇이냐” -> “무엇”이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/87/"},"南":{"id":80,"char":"南","hun":"남녘 남","meaning":"“남녘 남”. 남쪽","on":"ナン、ナ","kun":"みなみ","explanation":["南는 “천장에 걸려있는 종”을 그린 상형문자입니다.","“아래로 늘어뜨려진 종” -> “아래쪽” -> “남쪽”이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/88/"},"足":{"id":81,"char":"足","hun":"발 족","meaning":"“발 족”. 발","on":"ソク","kun":"あし、た(りる)、た(る)、た(す)","explanation":["足는 “달리고 있는 사람”을 그린 상형문자입니다.","“달리다” -> “발”이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/89/"},"万":{"id":82,"char":"万","hun":"일만 만","meaning":"“일만 만”. 일만","on":"マン、バン","kun":"","explanation":["万은 본래 “날카로운 칼날”을 그린 상형문자입니다.","그러나 이후 발음이 비슷하다는 이유로 “일만”이라는 뜻으로 쓰이게 된 것입니다.","즉, 万의 모양과 의미 사이에는 아무 관계도 없습니다."],"sourceUrl":"https://nihongokanji.com/90/"},"店":{"id":83,"char":"店","hun":"가게 점","meaning":"“가게 점”. 가게","on":"テン","kun":"みせ","explanation":["店 = 广 + 占。","「广」는 “건물, 집”을 뜻하는 부수입니다(링크 참조).","占(“점령할 점”)은 “점거하다, 점치다”라는 뜻의 상용한자입니다.","店는 “건물(广)을 점거하고(占) 물건을 파는 가게” -> “가게”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/91/"},"毎":{"id":84,"char":"毎","hun":"매양 매","meaning":"“매양 매”. 매번","on":"マイ","kun":"","explanation":["毎 = 𠂉 + 毋。","𠂉는 여기서는 “비녀”를 그린 모양자입니다.","「毋」는 “어머니”를 뜻하는 부수입니다(링크 참조).","毎는 “매일 머리에 비녀(𠂉)를 꽂는 어머니(毋)” -> “매번”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/92/"},"白":{"id":85,"char":"白","hun":"흰 백","meaning":"“흰 백”. 흰색","on":"ハク、ビャク","kun":"しろ、しろ(い)、しら","explanation":["白는 “밝게 타오르는 촛불”을 그린 상형문자입니다.","“밝은 촛불” -> “밝다” -> “흰색”이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/93/"},"古":{"id":86,"char":"古","hun":"옛 고","meaning":"“옛 고”. 오래된","on":"コ","kun":"ふる(い)、ふる(す)","explanation":["古 = 十 + 口。","「十」는 “10”을 뜻합니다.","「口」는 “입”을 뜻합니다.","古는 “아이에게 들려주는 열 가지(十) 옛날 이야기(口)” -> “옛날, 오래된”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/94/"},"天":{"id":87,"char":"天","hun":"하늘 천","meaning":"“하늘 천”. 하늘","on":"テン","kun":"あめ、あま","explanation":["天 = 一 + 大。","「大」는 본래 “사람”을 그린 글자입니다(링크 참조).","一는 여기서는 “하늘”을 그린 모양자입니다.","天는 “사람(大)위의 하늘(一)” -> “하늘”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/95/"},"買":{"id":88,"char":"買","hun":"살 매","meaning":"“살 매”. 사다, 구매하다","on":"バイ","kun":"か(う)","explanation":["買 = 罒 + 貝。","「罒」는 “그물”을 뜻하는 부수입니다(링크 참조).","「貝」는 “돈, 재물”을 뜻하는 부수입니다(링크 참조).","買는 “돈(貝)을 지불하고 그물(罒)을 구매하다” -> “사다, 구매하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/96/"},"週":{"id":89,"char":"週","hun":"돌 주","meaning":"“돌 주”. 1주일(week)","on":"シュウ","kun":"","explanation":["週 = ⻌ + 周。","(의미부) 「⻌」는 “길”을 뜻하는 부수입니다(링크 참조).","(소리부 겸 의미부) 周(シュウ – “두루 주”)는 “둘레, 돌다”라는 뜻의 상용한자입니다.","週는 “길(⻌)을 빙빙 돌다(周)” -> “주기, 순환” -> “1주일”이라는 뜻의 글자입니다.","(周는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/97/"},"母":{"id":90,"char":"母","hun":"어미 모","meaning":"“어미 모”. 어머니","on":"ボ","kun":"はは","explanation":["母는 “여자의 가슴”을 강조해서 그린 상형문자입니다.","“아기에게 젖을 주는 어머니” -> “어머니”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/98/"},"火":{"id":91,"char":"火","hun":"불 화","meaning":"“불 화”. 불","on":"カ","kun":"ひ、ほ","explanation":["火는 “불이 타오르는 모습”을 그린 상형문자입니다."],"sourceUrl":"https://nihongokanji.com/99/"},"花":{"id":92,"char":"花","hun":"꽃 화","meaning":"“꽃 화”. 꽃","on":"カ","kun":"はな","explanation":["花 = 艹 + 化。","(의미부) 「艹」는 “풀”을 뜻하는 부수입니다(링크 참조).","(소리부 겸 의미부) 化(カ – “될 화”)는 “바뀌다, 변하다”라는 뜻의 상용한자입니다.","花는 “새싹(艹)이 자라서(化) 꽃이 되다” -> “꽃”이라는 뜻의 글자입니다.","(化는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/100/"},"右":{"id":93,"char":"右","hun":"오른 우","meaning":"“오른 우”. 오른쪽","on":"ウ、ユウ","kun":"みぎ","explanation":["右 = 𠂇 + 口。","「𠂇」는 “손”을 뜻하는 글자입니다(링크 참조).","「口」는 “입”을 뜻합니다.","右는 “밥 먹을 때(口) 쓰는 손(𠂇)” -> “오른손” -> “오른쪽”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/101/"},"読":{"id":94,"char":"読","hun":"읽을 독","meaning":"“읽을 독”. 읽다","on":"ドク、トク、トウ","kun":"よ(む)","explanation":["読 = 言 + 売。","「言」는 “말하다”라는 뜻입니다.","売(“팔 매”)는 “팔다”라는 뜻의 상용한자입니다.","読는 “물건을 팔고(売) 번 돈을 세다(言)”라는 뜻입니다.","“중얼거리며 돈을 세다” -> “읽다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/102/"},"友":{"id":95,"char":"友","hun":"벗 우","meaning":"“벗 우”. 친구","on":"ユウ","kun":"とも","explanation":["友 = 𠂇 + 又。","「𠂇」는 “손”을 뜻합니다(링크 참조).","「又」는 “손”을 뜻하는 부수입니다(링크 참조).","友는 “서로 손을 맞잡고(𠂇+又) 반갑게 악수하는 친구들” -> “친구”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/103/"},"左":{"id":96,"char":"左","hun":"왼 좌","meaning":"“왼 좌”. 왼쪽","on":"サ","kun":"ひだり","explanation":["左 = 𠂇 + 工。","「𠂇」는 “손”을 뜻하는 글자입니다(링크 참조).","工는 여기서는 그냥 「右」와의 구분을 위해 추가된 장식입니다.","左는 “오른손”을 뜻하는 「右」에서 口만 工로 바꿔서 “왼손”이라는 뜻을 표현한 글자입니다.","“왼손” -> “왼쪽”이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/104/"},"休":{"id":97,"char":"休","hun":"쉴 휴","meaning":"“쉴 휴”. 쉬다, 휴식","on":"キュウ","kun":"やす(む)、やす(まる)、やす(める)","explanation":["休 = 亻 + 木。","「亻」는 “사람”을 뜻하는 부수입니다.","「木」는 “나무”를 뜻합니다.","休는 “나무(木) 그늘에서 쉬는 사람(亻)” -> “쉬다, 휴식”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/105/"},"父":{"id":98,"char":"父","hun":"아비 부","meaning":"“아비 부”. 아버지","on":"フ","kun":"ちち","explanation":["父 = 丿 + 又。","丿는 여기서는 “회초리”를 그린 모양자입니다.","「又」는 “손”을 뜻합니다.","父는 “회초리(丿)를 들고(又) 자식을 훈계하는 엄한 아버지” -> “아버지”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/106/"},"駅":{"id":99,"char":"駅","hun":"역 역","meaning":"“역 역”. 역(station)","on":"エキ","kun":"","explanation":["駅 = 馬 + 尺。","馬(“말 마”)는 “말”을 뜻하는 상용한자입니다.","尺는 여기서는 “기둥에 묶인 말고삐”를 그린 모양자입니다.","駅는 “말(馬)을 묶어두는(尺) 역참” -> “역”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/107/"},"雨":{"id":100,"char":"雨","hun":"비 우","meaning":"“비 우”. 비","on":"ウ","kun":"あめ、あま","explanation":["雨는 “비가 오는 모습”을 그린 상형문자입니다."],"sourceUrl":"https://nihongokanji.com/108/"},"飲":{"id":101,"char":"飲","hun":"마실 음","meaning":"“마실 음”. 마시다","on":"イン","kun":"の(む)","explanation":["飲 = 食 + 欠。","「食」는 “먹다”라는 뜻입니다.","「欠」는 “입을 벌린 사람”을 뜻하는 부수입니다(링크 참조).","飲는 “입을 벌리고(欠) 먹다(食)” -> “마시다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/109/"},"魚":{"id":102,"char":"魚","hun":"물고기 어","meaning":"“물고기 어”. 물고기","on":"ギョ","kun":"うお、さかな","explanation":["魚는 “물고기”를 본따 그린 상형문자입니다."],"sourceUrl":"https://nihongokanji.com/110/"},"耳":{"id":103,"char":"耳","hun":"귀 이","meaning":"“귀 이”. 귀","on":"ジ","kun":"みみ","explanation":["耳는 “귀”를 본따 그린 상형문자입니다."],"sourceUrl":"https://nihongokanji.com/111/"},"同":{"id":104,"char":"同","hun":"한가지 동","meaning":"“한가지 동”. 같다, 동일","on":"ドウ","kun":"おな(じ)","explanation":["同 = 𠔼 + 口。","𠔼는 여기서는 “둥글게 둘러앉은 모습”을 그린 모양자입니다.","「口」는 “입”을 뜻합니다.","同는 “둥글게 둘러앉아(𠔼) 함께 이야기하다(口)”라는 뜻입니다.","“다 같이 이야기하다” -> “같다, 한가지”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/112/"},"事":{"id":105,"char":"事","hun":"일 사","meaning":"“일 사”. 일, 사항, 사건","on":"ジ、ズ","kun":"こと","explanation":["事는 “제사 의식용 도구를 손(⺕)에 쥔 모습”을 그린 상형문자입니다.","고대 사회에서 제사는 대단히 중요한 국가적 행사였습니다.","“중요한 행사” -> “일, 사항, 사건”이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/113/"},"自":{"id":106,"char":"自","hun":"스스로 자","meaning":"“스스로 자”. 자신, 자기","on":"ジ、シ","kun":"みずか(ら)","explanation":["自는 본래 “사람의 코”를 본따 그린 상형문자입니다.","“코” -> “얼굴의 중앙” -> “자기 자신”이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/114/"},"民":{"id":107,"char":"民","hun":"백성 민","meaning":"“백성 민”. 국민, 민족","on":"ミン","kun":"たみ","explanation":["民는 “칼로 노예의 눈을 찌르는 모습”을 그린 상형문자입니다.","고대 중국에서는 노예의 왼쪽 눈을 멀게 해 도망가지 못하게 했다고 합니다.","“눈을 찔린 노예” -> “노예” -> “백성, 국민”이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/115/"},"発":{"id":108,"char":"発","hun":"쏠 발","meaning":"“쏠 발”. 쏘다, 일으키다, 발생하다","on":"ハツ、ホツ","kun":"","explanation":["発 = 癶 + 开。","癶는 여기서는 “화살촉”을 그린 모양자입니다.","开는 여기서는 “활시위(二)에 걸린 화살대(儿)”를 그린 모양자입니다.","発는 “화살(癶)을 쏘다(开)” -> “쏘다” -> “일으키다, 발생하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/116/"},"者":{"id":109,"char":"者","hun":"놈 자","meaning":"“놈 자”. 사람; 행동의 주체","on":"シャ","kun":"もの","explanation":["者 = 耂 + 曰。","「耂」는 “노인”을 뜻하는 부수입니다(링크 참조).","「曰」(“가로 왈”)은 “말하다”라는 뜻의 부수입니다(링크 참조).","者는 “말하고 있는(曰) 노인(耂)” -> “사람, 행동의 주체”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/117/"},"地":{"id":110,"char":"地","hun":"땅 지","meaning":"“땅 지”. 땅, 대지","on":"チ、ジ","kun":"","explanation":["地 = 土 + 也。","「土」는 “흙”을 뜻합니다.","「也」는 어조사(“~이다”, “역시”, “또한” 등등)로서 쓰이는 글자입니다(링크 참조).","地는 “흙(土) + 이다(也)” -> “땅, 대지”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/118/"},"合":{"id":111,"char":"合","hun":"합할 합","meaning":"“합할 합”. 합치다, 들어맞다","on":"ゴウ、ガッ、カッ","kun":"あ(う)、あ(わす)、あ(わせる)","explanation":["合 = 亼 + 口。","亼는 여기서는 “그릇의 뚜껑”을 그린 모양자입니다.","口는 여기서는 “그릇”을 그린 모양자입니다.","合는 “그릇(口)의 뚜껑(亼)을 덮다” -> “합치다, 들어맞다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/119/"},"市":{"id":112,"char":"市","hun":"저자 시","meaning":"“저자 시”. 시장(market), 도시","on":"シ","kun":"いち","explanation":["市 = 亠 + 巾。","亠는 여기서는 “(옷을 걸어놓는) 장대”를 그린 모양자입니다.","「巾」는 “수건, 천”을 뜻하는 부수입니다(링크 참조).","市는 “옷감(巾)이 걸려있는(亠) 옷가게“라는 뜻입니다.","“옷가게가 늘어선 시장” -> “시장, 도시”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/120/"},"業":{"id":113,"char":"業","hun":"업 업","meaning":"“업 업”. 직업, 사업, 일","on":"ギョウ、ゴウ","kun":"わざ","explanation":["業는 “악기를 등에 멘 악사”를 본따 그린 상형문자입니다.","“악기를 들고 다니는 악사” -> “직업, 사업, 일”이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/121/"},"方":{"id":114,"char":"方","hun":"모 방","meaning":"“모 방”. 방향, 방법","on":"ホウ","kun":"かた","explanation":["方는 “소가 끄는 쟁기”를 그린 상형문자입니다.","“소에게 방향을 지시하다” -> “방향, 방법”이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/122/"},"回":{"id":115,"char":"回","hun":"돌 회","meaning":"“돌 회”. 돌다, 회전, 횟수","on":"カイ、エ","kun":"まわ(る)、まわ(す)","explanation":["回는 “회오리가 빙글빙글 도는 모습”을 그린 상형문자입니다."],"sourceUrl":"https://nihongokanji.com/123/"},"場":{"id":116,"char":"場","hun":"마당 장","meaning":"“마당 장”. 장소, 곳","on":"ジョウ","kun":"ば","explanation":["場 = 土 + 昜。","「土」는 “흙, 땅”을 뜻합니다.","「昜」는 “햇볕, 뜨거운 햇살”을 뜻하는 글자입니다(링크 참조).","場는 “햇볕이 내리쬐는(昜) 넓은 땅(土)” -> “장소, 곳”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/124/"},"員":{"id":117,"char":"員","hun":"인원 원","meaning":"“인원 원”. 인원, 점원","on":"イン","kun":"","explanation":["員 = 口 + 貝。","「口」는 “입”을 뜻합니다.","「貝」는 “돈, 재물”을 뜻하는 부수입니다.","員는 “식비(口)와 월급(貝)” -> “인건비” -> “인원, 점원”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/125/"},"開":{"id":118,"char":"開","hun":"열 개","meaning":"“열 개”. 열다","on":"カイ","kun":"ひら(く)、ひら(ける)、あ(く)、あ(ける)","explanation":["開 = 門 + 开。","門(“문 문”)은 “문”을 뜻하는 상용한자입니다.","开는 여기서는 “양손으로 문을 열어젖히는 모습”을 그린 모양자입니다.","開는 “문(門)을 양손으로 열어젖히다(开)” -> “열다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/126/"},"力":{"id":119,"char":"力","hun":"힘 력(역)","meaning":"“힘 력(역)”. 힘","on":"リョク、リキ","kun":"ちから","explanation":["力는 “쟁기”를 본따 그린 상형문자입니다.","“농사를 짓는 쟁기” -> “농사일” -> “힘”이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/127/"},"問":{"id":120,"char":"問","hun":"물을 문","meaning":"“물을 문”. 묻다","on":"モン","kun":"と(う)、と(い)、とん","explanation":["問 = 門 + 口。","(소리부 겸 의미부) 門(モン – “문 문”)은 “문”을 뜻하는 상용한자입니다.","(의미부) 「口」는 “입”을 뜻합니다.","問는 “남의 집에 방문(門)해 질문하다(口)” -> “묻다”라는 뜻의 글자입니다.","(門는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/128/"},"代":{"id":121,"char":"代","hun":"대신할 대","meaning":"“대신할 대”. 대신하다, 시대","on":"ダイ、タイ","kun":"か(わる)、か(える)、よ、しろ","explanation":["代 = 亻 + 弋。","「亻」는 “사람”을 뜻합니다.","「弋」는 “공구, 도구”를 뜻하는 부수입니다(링크 참조).","代는 “목수(亻)가 쓰는 공구(弋)“라는 뜻입니다.","“오래된 공구를 교체하다” -> “대신하다, 대체되다, 세대, 시대”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/129/"},"明":{"id":122,"char":"明","hun":"밝을 명","meaning":"“밝을 명”. 밝다","on":"メイ、ミョウ","kun":"あ(かり)、あか(るい)、あか(るむ)、あか(らむ)、あき(らか)、あ(ける)、あ(く)、あ(くる)、あ(かす)","explanation":["明 = 日 + 月。","「日」는 “해”를 뜻합니다.","「月」는 “달”을 뜻합니다.","明는 “해(日) + 달(月)” -> “밝다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/130/"},"動":{"id":123,"char":"動","hun":"움직일 동","meaning":"“움직일 동”. 움직이다","on":"ドウ","kun":"うご(く)、うご(かす)","explanation":["動 = 重 + 力。","重(“무거울 중”)은 “무겁다”라는 뜻의 상용한자입니다.","「力」는 “힘”을 뜻합니다.","動는 “힘(力)을 써서 무거운(重) 물건을 옮기다” -> “움직이다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/131/"},"京":{"id":124,"char":"京","hun":"서울 경","meaning":"“서울 경”. 수도","on":"キョウ、ケイ","kun":"","explanation":["京는 “기둥 위에 세워진 커다란 건물”을 그린 상형문자입니다.","“커다란 건물들이 늘어선 도시” -> “수도”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/132/"},"通":{"id":125,"char":"通","hun":"통할 통","meaning":"“통할 통”. 통하다, 지나가다","on":"ツウ、ツ","kun":"とお(る)、とお(す)、かよ(う)","explanation":["通 = ⻌ + 甬。","「⻌」는 “길”을 뜻하는 부수입니다.","「甬」는 “종”을 뜻하는 글자입니다(링크 참조).","通는 “속이 텅 비어있는 종(甬)처럼 뻥 뚫린 길(⻌)”이라는 뜻입니다.","“뻥 뚫린 길” -> “통하다, 지나가다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/133/"},"理":{"id":126,"char":"理","hun":"다스릴 리","meaning":"“다스릴 리”. 이치, 진리, 논리","on":"リ","kun":"","explanation":["理 = 𤣩 + 里。","(의미부) 「𤣩」는 “구슬, 보석”을 뜻하는 부수입니다(링크 참조).","(소리부) 「里」(リ)는 “마을”을 뜻하는 부수입니다(링크 참조).","다만 여기서는 소리부의 역할만 하고 있습니다.","理는 “정교하게 세공된, 빛나는 옥구슬(𤣩)” -> “이치, 진리, 논리”라는 뜻의 글자입니다(里는 소리부)."],"sourceUrl":"https://nihongokanji.com/134/"},"体":{"id":127,"char":"体","hun":"몸 체","meaning":"“몸 체”. 몸","on":"タイ、テイ","kun":"からだ","explanation":["体 = 亻 + 本。","「亻」는 “사람”을 뜻합니다.","「本」는 “근본, 본질”을 뜻합니다. 여기서는 “본체”라는 뜻입니다.","体는 “사람(亻)의 본체(本)” -> “몸통, 신체”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/135/"},"田":{"id":128,"char":"田","hun":"밭 전","meaning":"“밭 전”. 밭","on":"デン","kun":"た","explanation":["田는 “가지런히 늘어선 논밭”의 모습을 그린 상형문자입니다."],"sourceUrl":"https://nihongokanji.com/136/"},"主":{"id":129,"char":"主","hun":"주인 주","meaning":"“주인 주”. 주인","on":"シュ、ス","kun":"ぬし、おも","explanation":["主 = 丶 + 王。","王(“임금 왕”)은 “왕”을 뜻하는 상용한자입니다.","丶는 여기서는 “왕관”을 그린 모양자입니다.","主는 “왕관(丶)을 쓴 왕(王)” -> “나라의 주인” -> “주인”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/137/"},"題":{"id":130,"char":"題","hun":"제목 제","meaning":"“제목 제”. 제목, 주제","on":"ダイ","kun":"","explanation":["題 = 是 + 頁。","是(“옳을 시”)는 “옳다, 바르다”라는 뜻의 상용한자입니다.","「頁」는 “머리”를 뜻하는 부수입니다(링크 참조).","題는 “바른(是) 머리(頁)” -> “이마”라는 뜻으로 만들어진 글자입니다.","“이마” -> “얼굴의 제일 앞에 나와 있는 부분” -> “제목, 주제”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/138/"},"首":{"id":131,"char":"首","hun":"머리 수","meaning":"“머리 수”. 머리, 목","on":"シュ","kun":"くび","explanation":["首 = 丷 + 丆 + 目。","「目」는 “눈”을 뜻합니다.","丷+丆는 여기서는 “머리털“을 그린 모양자입니다.","首는 “머리털(丷+丆) + 눈(目)” -> “머리, 목”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/139/"},"意":{"id":132,"char":"意","hun":"뜻 의","meaning":"“뜻 의”. 뜻, 생각, 의미","on":"イ","kun":"","explanation":["意 = 音 + 心。","音(“소리 음”)은 “소리”를 뜻하는 상용한자입니다.","心(“마음 심”)은 “마음”을 뜻하는 상용한자입니다.","意는 “마음(心)의 소리(音)” -> “뜻, 생각, 의미”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/140/"},"不":{"id":133,"char":"不","hun":"아닐 부(불)","meaning":"“아닐 부(불)”. 아니다, 부정","on":"フ、ブ","kun":"","explanation":["不는 “땅속에 뿌리내린 씨앗”을 그린 상형문자입니다.","“아직 싹을 틔우지 못한 씨앗” -> “아니다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/141/"},"作":{"id":134,"char":"作","hun":"지을 작","meaning":"“지을 작”. 만들다","on":"サク、サ","kun":"つく(る)","explanation":["作 = 亻 + 乍。","(의미부) 「亻」는 “사람”을 뜻합니다.","(소리부 겸 의미부) 「乍」(サク・サ)는 “바느질하다”라는 뜻의 글자입니다(링크 참조).","作는 “재봉사(亻)가 바느질(乍)로 옷을 만들다” -> “만들다”라는 뜻의 글자입니다.","(乍는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/142/"},"用":{"id":135,"char":"用","hun":"쓸 용","meaning":"“쓸 용”. 쓰다, 사용하다, 이용하다","on":"ヨウ","kun":"もち(いる)","explanation":["用는 “나무로 만든 울타리”를 본따 그린 상형문자입니다.","“침입자를 막기 위해 울타리를 이용하다” -> “이용하다, 사용하다, 쓰다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/143/"},"度":{"id":136,"char":"度","hun":"법도 도","meaning":"“법도 도”. 정도, 횟수, 제도","on":"ド、ト、タク","kun":"たび","explanation":["度 = 广 + 廿 + 又。","「广」는 “건물, 집”을 뜻하는 부수입니다.","廿는 여기서는 “벽돌”을 그린 모양자입니다.","「又」는 “손”을 뜻하는 부수입니다.","度는 “벽돌(廿)을 쌓아서(又) 집(广)을 짓다“라는 뜻의 글자입니다.","집을 제대로 짓기 위해서는 정교한 측량이 필요합니다.","“정해진 기준대로 정교하게 측량하다” -> “정도, 횟수, 제도, 표준”이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/144/"},"強":{"id":137,"char":"強","hun":"강할 강","meaning":"“강할 강”. 강하다","on":"キョウ、ゴウ","kun":"つよ(い)、つよ(まる)、つよ(める)、し(いる)","explanation":["強 = 弓 + 厶 + 虫。","「弓」는 “활”을 뜻하는 부수입니다(링크 참조).","「厶」는 본래 “팔을 안으로 굽힌 모습”을 그린 글자입니다(링크 참조). 여기서는 “활시위를 잡아당기는 팔”을 표현한 것입니다.","虫(“벌레 충”)은 “벌레”를 뜻하는 상용한자입니다.","強는 “활(弓)을 쏘아(厶) 벌레(虫)를 맞추다”라는 뜻입니다.","“작은 벌레도 쏘아 맞출 정도의 활쏘기 실력” -> “강하다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/145/"},"持":{"id":138,"char":"持","hun":"가질 지","meaning":"“가질 지”. 가지다, 지니다","on":"ジ","kun":"も(つ)","explanation":["持 = 扌 + 土 + 寸。","「扌」는 “손”을 뜻하는 부수입니다(링크 참조).","「寸」는 “손”을 뜻하는 부수입니다.","「土」는 “흙, 땅”을 뜻합니다.","持는 “양 손(扌+寸)에 흙덩이(土)를 가득 집어들다” -> “가지다, 지니다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/146/"},"野":{"id":139,"char":"野","hun":"들 야","meaning":"“들 야”. 들, 벌판","on":"ヤ","kun":"の","explanation":["野 = 里 + 予。","「里」는 “마을”을 뜻합니다.","予(“미리 예”)는 “미리, 앞서”라는 뜻의 상용한자입니다.","野는 “마을(里) 앞(予)의 들판” -> “벌판, 들”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/147/"},"都":{"id":140,"char":"都","hun":"도읍 도","meaning":"“도읍 도”. 대도시, 수도","on":"ト、ツ","kun":"みやこ","explanation":["都 = 者 + ⻏。","「者」는 “사람”을 뜻합니다.","「⻏」는 “도시”를 뜻하는 부수입니다(링크 참조).","都는 “사람(者)이 많이 사는 대도시(⻏)” -> “대도시, 수도”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/148/"},"以":{"id":141,"char":"以","hun":"써 이","meaning":"“써 이”. ~로써, ~부터","on":"イ","kun":"","explanation":["以는 본래 “쟁기로 밭을 가는 사람(人)”을 그린 상형문자입니다.","“도구를 쓰면서부터 농사가 쉬워졌다” -> “~부터, ~로써”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/149/"},"思":{"id":142,"char":"思","hun":"생각 사","meaning":"“생각 사”. 생각하다","on":"シ","kun":"おも(う)","explanation":["思 = 田 + 心。","「田」는 “밭”을 뜻합니다.","心(“마음 심”)은 “마음”을 뜻하는 상용한자입니다.","思는 “농사일(田)에 관한 생각이 마음속(心)을 가득 채우다” -> “생각하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/150/"},"家":{"id":143,"char":"家","hun":"집 가","meaning":"“집 가”. 집","on":"カ、ケ","kun":"いえ、や","explanation":["家 = 宀 + 豕。","「宀」는 “집”을 뜻하는 부수입니다.","「豕」는 “돼지”를 뜻하는 부수입니다(링크 참조).","家는 “돼지(豕)를 키우는 집(宀)” -> “집”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/151/"},"世":{"id":144,"char":"世","hun":"세상 세","meaning":"“세상 세”. 세상, 세계, 세대","on":"セイ、セ","kun":"よ","explanation":["世는 “나뭇가지에 돋아난 새싹들”을 그린 상형문자입니다.","“매년 새로 돋아나는 새싹” -> “세대” -> “세상, 세계”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/152/"},"区":{"id":145,"char":"区","hun":"구역 구","meaning":"“구역 구”. 구역, 구획, 경계","on":"ク","kun":"","explanation":["区는 “네모난 공간(匚)을 네 구역(㐅)으로 나눈 모습”을 그린 글자입니다.","“구역을 나누다” -> “구역, 구획, 경계”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/153/"},"県":{"id":146,"char":"県","hun":"고을 현","meaning":"“고을 현”. 현(일본의 행정 구역)","on":"ケン","kun":"","explanation":["県 = 目 + 𠃊 + 小。","県는 본래 “목매달린 사람”의 모습을 그린 상형문자입니다.","目는 “사람의 머리”, 𠃊는 “목이 매달린 줄”, 小는 “몸통과 팔다리”를 각각 모양자로서 표현한 것입니다.","다만, 현재는 본래 뜻과는 관련없이 단순히 발음만 차용한 행정 구역의 단위로서 쓰이고 있습니다."],"sourceUrl":"https://nihongokanji.com/154/"},"進":{"id":147,"char":"進","hun":"나아갈 진","meaning":"“나아갈 진”. 나아가다, 올라가다","on":"シン","kun":"すす(む)、すす(める)","explanation":["進 = ⻌ + 隹。","「⻌」는 “길”을 뜻합니다.","「隹」는 “새”를 뜻하는 부수입니다(링크 참조).","進는 “길(⻌)을 걸어가는 새(隹)”라는 뜻입니다.","새는 앞으로밖에 걸어갈 수 없다는 특징이 있습니다.","“앞으로만 걷는 새” -> “나아가다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/155/"},"正":{"id":148,"char":"正","hun":"바를 정","meaning":"“바를 정”. 바르다","on":"セイ、ショウ","kun":"ただ(しい)、ただ(す)、まさ","explanation":["正 = 一 + 止。","一는 여기서는 “성문”을 그린 모양자입니다.","「止」는 “발”을 뜻하는 부수입니다(링크 참조).","正는 “성문(一)을 향해 진격하는 발(止)”이라는 뜻입니다.","전쟁을 일으키고 적을 토벌하기 위해서는 정당한 명분이 있어야 합니다.","“정당한 명분” -> “바르다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/156/"},"院":{"id":149,"char":"院","hun":"집 원","meaning":"“집 원”. 관청/학교/병원 등 각종 기관","on":"イン","kun":"","explanation":["院 = ⻖ + 宀 + 元。","「⻖」는 “언덕, 산”을 뜻합니다. 여기서는 “높은 언덕” -> “경계, 담장”이라는 뜻으로 쓰인 것입니다.","「宀」는 “집”을 뜻합니다.","元(“으뜸 원”)은 “으뜸, 근원”을 뜻하는 상용한자입니다.","院는 “높은 담장(⻖)으로 둘러싸인 중요한(元) 집(宀)“ -> “기관”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/157/"},"心":{"id":150,"char":"心","hun":"마음 심","meaning":"“마음 심”. 마음, 의식, 정신","on":"シン","kun":"こころ","explanation":["心는 “심장”을 본따 그린 상형문자입니다.","“심장” -> “마음”이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/158/"},"界":{"id":151,"char":"界","hun":"지경 계","meaning":"“지경 계”. 경계, 범위 안","on":"カイ","kun":"","explanation":["界 = 田 + 介。","「田」는 “밭”을 뜻합니다.","介(“끼일 개”)는 “끼다, 끼이다”라는 뜻의 상용한자입니다.","界는 “논밭(田)들 사이에 끼인(介) 경계선” -> “경계, 범위 안”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/159/"},"産":{"id":152,"char":"産","hun":"낳을 산","meaning":"“낳을 산”. 낳다, 생산하다","on":"サン","kun":"う(む)、う(まれる)、うぶ","explanation":["産 = 产 + 生。","产는 여기서는 「广」이 변형된 것으로, “집, 건물”을 뜻합니다.","「生」는 “태어나다”라는 뜻입니다.","産는 “집(产)에서 아기가 태어나다(生)” -> “낳다, 생산하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/160/"},"教":{"id":153,"char":"教","hun":"가르칠 교","meaning":"“가르칠 교”. 가르치다","on":"キョウ","kun":"おし(える)、おそ(わる)","explanation":["教 = 耂 + 子 + 攵。","「耂」는 “노인”을 뜻합니다.","「子」는 “아이”를 뜻합니다.","「攵」는 “때리다, 치다”라는 뜻의 부수입니다.","教는 “할아버지(耂)가 아이(子)를 회초리로 때리며(攵) 가르치다” -> “가르치다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/161/"},"文":{"id":154,"char":"文","hun":"글월 문","meaning":"“글월 문”. 문장, 문예, 글자","on":"ブン、モン","kun":"ふみ","explanation":["文은 “가슴팍에 커다란 문신이 있는 사람”을 그린 상형문자입니다.","“문신” -> “문양” -> “문자, 문장, 문예”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/162/"},"元":{"id":155,"char":"元","hun":"으뜸 원","meaning":"“으뜸 원”. 근본, 근원, 으뜸","on":"ゲン、ガン","kun":"もと","explanation":["元 = 二 + 儿。","儿는 「人」가 변형된 것으로, “사람”을 뜻합니다.","二는 여기서는 “사람(儿)의 머리”를 강조해서 그린 모양자입니다.","元는 “사람(儿)의 머리(二)” -> “으뜸, 근본, 근원”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/163/"},"重":{"id":156,"char":"重","hun":"무거울 중","meaning":"“무거울 중”. 무겁다, 겹치다","on":"ジュウ、チョウ","kun":"え、おも(い)、かさ(ねる)、かさ(なる)","explanation":["重는 본래 “무거운 봇짐을 진 사람”을 그린 상형문자입니다.","시간이 지나며 왼쪽의 “사람” 부분은 생략되고 오른쪽의 “봇짐” 부분만 남아서 지금의 형태가 된 것입니다.","“무거운 봇짐” -> “무겁다, 겹치다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/164/"},"近":{"id":157,"char":"近","hun":"가까울 근","meaning":"“가까울 근”. 가깝다","on":"キン","kun":"ちか(い)","explanation":["近 = ⻌ + 斤。","「⻌」는 “길”을 뜻합니다.","「斤」는 “도끼”를 뜻합니다.","近는 “길(⻌)에서 도끼(斤)를 든 강도를 만나다”라는 뜻입니다.","“강도가 눈앞에 있다” -> “가깝다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/165/"},"考":{"id":158,"char":"考","hun":"생각할 고","meaning":"“생각할 고”. 생각하다, 깊이 헤아리다, 조사하다","on":"コウ","kun":"かんが(える)","explanation":["考 = 耂 + 丂。","「耂」는 “노인”을 뜻합니다.","丂는 여기서는 “지팡이”를 그린 모양자입니다.","考는 “지팡이를 짚고(丂) 생각에 잠긴 노인(耂)” -> “생각하다, 깊이 헤아리다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/166/"},"画":{"id":159,"char":"画","hun":"그림 화/그을 획","meaning":"“그림 화/그을 획”. 그림/획","on":"ガ、カク","kun":"","explanation":["画는 “논밭(田) 주위에 그어놓은 경계선”을 그린 상형문자입니다.","“논밭 주위에 경계선을 긋다” -> “획, 그리다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/167/"},"海":{"id":160,"char":"海","hun":"바다 해","meaning":"“바다 해”. 바다","on":"カイ","kun":"うみ","explanation":["海 = 氵 + 毎。","「氵」는 “물”을 뜻하는 부수입니다(링크 참조).","「毎」는 본래 “머리에 비녀를 꽂은 어머니”를 그린 글자입니다(링크 참조).","대지나 바다는 흔히 “생명의 어머니”로 비유되곤 합니다.","海는 “생명의 어머니(毎)인 바다(氵)” -> “바다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/168/"},"売":{"id":161,"char":"売","hun":"팔 매","meaning":"“팔 매”. 팔다","on":"バイ","kun":"う(る)、う(れる)","explanation":["売 = 士 + 冖 + 儿。","士는 여기서는 “도자기”를 그린 모양자입니다.","冖는 여기서는 “(노점의) 판매대”를 그린 모양자입니다.","儿는 「人」가 변형된 것으로, “사람”을 뜻합니다.","売는 “도자기(士)를 진열해두고(冖) 파는 노점상(儿)” -> “팔다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/169/"},"知":{"id":162,"char":"知","hun":"알 지","meaning":"“알 지”. 알다, 지혜","on":"チ","kun":"し(る)","explanation":["知 = 矢 + 口。","「矢」는 “화살”을 뜻하는 부수입니다(링크 참조). 여기서는 “화살을 날리다” -> “전달하다”라는 뜻으로 쓰인 것입니다.","「口」는 “입”을 뜻합니다.","知는 “말(口)로 지식을 전달하다(矢)” -> “지식, 알다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/170/"},"集":{"id":163,"char":"集","hun":"모을 집","meaning":"“모을 집”. 모이다, 모으다","on":"シュウ","kun":"あつ(まる)、あつ(める)、つど(う)","explanation":["集 = 隹 + 木。","「隹」는 “새”를 뜻하는 부수입니다.","「木」는 “나무”를 뜻합니다.","集는 “나무(木) 위에 모여앉은 새들(隹)” -> “모이다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/171/"},"別":{"id":164,"char":"別","hun":"다를/나눌 별","meaning":"“다를/나눌 별”. 나누다, 다르다","on":"ベツ","kun":"わか(れる)","explanation":["別 = 𠮠 + 刂。","𠮠는 「冎」가 변형된 것으로, “뼈”를 뜻합니다(링크 참조).","「刂」는 “칼”을 뜻합니다.","別는 “고기에서 뼈(𠮠)를 발라내다(刂)” -> “분리하다, 나누다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/172/"},"物":{"id":165,"char":"物","hun":"물건 물","meaning":"“물건 물”. 물건","on":"ブツ、モツ","kun":"もの","explanation":["物 = 牜 + 勿。","「牜」는 “소”를 뜻하는 부수입니다(링크 참조).","勿는 여기서는 “무언가를 칼로 내리치는 모습”을 그린 모양자입니다.","物는 “소의 뿔(牜)을 칼로 내리쳐(勿) 잘라내다”라는 뜻입니다.","“잘라낸 소의 뿔” -> “물건, 제품”이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/173/"},"引":{"id":166,"char":"引","hun":"끌 인","meaning":"“끌 인”. 당기다","on":"イン","kun":"ひ(く)、ひ(ける)","explanation":["引 = 弓 + 丨。","「弓」는 “활”을 뜻하는 부수입니다.","丨는 여기서는 “활시위”를 그린 모양자입니다.","引는 “활(弓)의 시위(丨)를 당기다” -> “당기다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/174/"},"使":{"id":167,"char":"使","hun":"부릴 사","meaning":"“부릴 사”. 쓰다, 사용하다","on":"シ","kun":"つか(う)","explanation":["使 = 亻 + 吏。","「亻」는 “사람”을 뜻합니다.","吏(“벼슬아치 리”)는 “관리, 벼슬아치”를 뜻하는 상용한자입니다.","使는 “벼슬아치(吏)가 아랫사람(亻)을 부리다” -> “사용하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/175/"},"所":{"id":168,"char":"所","hun":"바 소","meaning":"“바 소”. 곳, 장소","on":"ショ","kun":"ところ","explanation":["所 = 戸 + 斤。","戸(“집 호”)는 “출입구, 문, 집”을 뜻하는 상용한자입니다.","「斤」는 “도끼”를 뜻하는 부수입니다.","所는 “도끼(斤)로 벽을 부수고 출입구(戸)를 만들다”라는 뜻입니다.","“출입할 수 있는 공간” -> “곳, 장소”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/176/"},"品":{"id":169,"char":"品","hun":"물건 품","meaning":"“물건 품”. 물건, 물품","on":"ヒン","kun":"しな","explanation":["品는 “여러 개의 물건을 쌓아놓은 모습”을 그린 상형문자입니다."],"sourceUrl":"https://nihongokanji.com/177/"},"計":{"id":170,"char":"計","hun":"셀 계","meaning":"“셀 계”. 수를 세다, 계산하다","on":"ケイ","kun":"はか(る)、はか(らう)","explanation":["計 = 言 + 十。","「言」는 “말하다”라는 뜻입니다.","「十」는 “10”을 뜻합니다.","計는 “숫자를 10(十)까지 세다(言)” -> “셈, 계산”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/178/"},"死":{"id":171,"char":"死","hun":"죽을 사","meaning":"“죽을 사”. 죽음, 죽다","on":"シ","kun":"し(ぬ)","explanation":["死 = 歹 + 匕。","「歹」는 “시체”를 뜻하는 부수입니다(링크 참조).","「匕」는 “넘어져있는 사람”을 뜻합니다.","死는 “죽어 넘어져(匕) 뼈만 남은 시체(歹)” -> “죽다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/179/"},"特":{"id":172,"char":"特","hun":"특별할 특","meaning":"“특별할 특”. 특별함","on":"トク","kun":"","explanation":["特 = 牜 + 寺。","「牜」는 “소”를 뜻합니다.","寺(ジ – “절 사”)는 “절, 사찰”을 뜻하는 상용한자입니다.","먼 옛날에는 소가 신성한 동물로서 숭배되는 경우가 많았다고 합니다.","特는 “신성한 동물(牜) + 신성한 장소(寺)” -> “특별하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/180/"},"私":{"id":173,"char":"私","hun":"사사로울 사","meaning":"“사사로울 사”. 나, 개인","on":"シ","kun":"わたし、わたくし","explanation":["私 = 禾 + 厶。","「禾」는 “곡식”을 뜻하는 부수입니다(링크 참조).","「厶」는 “사사로운, 개인적인”이라는 뜻의 부수입니다(링크 참조).","私는 “내 소유(厶)의 곡식(禾)” -> “나, 개인”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/181/"},"始":{"id":174,"char":"始","hun":"시작 시","meaning":"“시작 시”. 시작, 시작하다","on":"シ","kun":"はじ(める)、はじ(まる)","explanation":["始 = 女 + 台。","「女」는 “여자”를 뜻합니다.","台(“대 대”)는 “받침대”라는 뜻의 상용한자입니다. 여기서는 “부엌의 도마”를 뜻합니다.","여자아이가 집안일을 배울 수 있는 나이가 되면 가사를 배우게 됩니다.","始는 “여자아이(女)가 부엌일(台)을 배우기 시작하다” -> “시작하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/182/"},"朝":{"id":175,"char":"朝","hun":"아침 조","meaning":"“아침 조”. 아침","on":"チョウ","kun":"あさ","explanation":["朝 = 𠦝 + 月。","「𠦝」는 “떠오르는 아침해”를 그린 글자입니다(링크 참조).","「月」는 “달”을 뜻합니다.","朝는 “막 떠오르는 아침해(𠦝)와 아직 지지 않은 달(月)” -> “아침”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/183/"},"村":{"id":176,"char":"村","hun":"마을 촌","meaning":"“마을 촌”. 마을","on":"ソン","kun":"むら","explanation":["村 = 木 + 寸。","「木」는 “나무”를 뜻합니다.","「寸」는 “손”을 뜻합니다.","村는 “사람의 손(寸)이 닿은 숲속(木)의 마을” -> “마을”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/184/"},"運":{"id":177,"char":"運","hun":"옮길 운","meaning":"“옮길 운”. 옮기다, 운반하다, 나르다, 운/행운","on":"ウン","kun":"はこ(ぶ)","explanation":["運 = ⻌ + 冖 + 車。","「⻌」는 “길”을 뜻합니다.","「車」는 “수레, 차”를 뜻합니다.","冖는 여기서는 “수레 위에 실은 짐”을 그린 모양자입니다.","運는 “짐(冖)을 가득 싣고 길(⻌)을 가는 수레(車)” -> “옮기다, 운반하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/185/"},"終":{"id":178,"char":"終","hun":"마칠 종","meaning":"“마칠 종”. 끝나다, 마지막","on":"シュウ","kun":"お(わる)、お(える)","explanation":["終 = 糸 + 冬。","「糸」는 “실”을 뜻하는 부수입니다(링크 참조).","冬(“겨울 동”)은 “겨울”을 뜻하는 상용한자입니다.","終는 “실(糸)의 끝부분 + 한 해의 마지막 계절(冬)” -> “끝나다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/186/"},"台":{"id":179,"char":"台","hun":"대 대","meaning":"“대 대”. 받침대","on":"ダイ、タイ","kun":"","explanation":["台 = 厶 + 口。","口는 여기서는 “받침대”를 그린 모양자입니다.","厶는 여기서는 단순히 “무언가 올려져있는 모습”을 그린 모양자입니다.","台는 “무언가 올려져있는(厶) 받침대(口)” -> 받침대”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/187/"},"広":{"id":180,"char":"広","hun":"넓을 광","meaning":"“넓을 광”. 넓다","on":"コウ","kun":"ひろ(い)、ひろ(まる)、ひろ(める)、ひろ(がる)、ひろ(げる)","explanation":["広 = 广 + 厶。","「广」는 “건물, 집”을 뜻합니다.","「厶」는 “사사로운, 개인적인”이라는 뜻입니다.","広는 “개인 소유(厶)의 대저택(广)” -> “넓다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/188/"},"住":{"id":181,"char":"住","hun":"살 주","meaning":"“살 주”. 살다, 거주하다","on":"ジュウ","kun":"す(む)、す(まう)","explanation":["住 = 亻 + 主。","「亻」는 “사람”을 뜻합니다.","「主」는 “주인”을 뜻합니다.","住는 “집의 주인(主)인 사람(亻)”이라는 뜻입니다.","“집주인” -> “살다, 거주하다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/189/"},"真":{"id":182,"char":"真","hun":"참 진","meaning":"“참 진”. 참, 진실","on":"シン","kun":"ま","explanation":["真 = 十 + 目 + 一 + ハ。","「目」는 “눈”을 뜻합니다.","十+一+ハ는 여기서는 “눈가의 주름”을 표현한 모양자입니다.","真는 “눈(目)을 찡그리고(十+一+ハ) 자세히 살펴서 진짜를 구분하다” -> “참, 진실”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/190/"},"有":{"id":183,"char":"有","hun":"있을 유","meaning":"“있을 유”. 있다, 가지다","on":"ユウ、ウ","kun":"あ(る)","explanation":["有 = 𠂇 + 月。","「𠂇」는 “손”을 뜻하는 부수입니다.","「月」는 “고기”를 뜻하는 부수입니다(링크 참조).","有는 “고기(月)를 집어든 손(𠂇)”이라는 뜻입니다.","“고기를 든 손” -> “고기가 있다” -> “있다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/191/"},"町":{"id":184,"char":"町","hun":"밭두둑 정","meaning":"“밭두둑 정”. 시가지, 일본의 행정 구역(한국의 “읍”에 해당)","on":"チョウ","kun":"まち","explanation":["町 = 田 + 丁。","(의미부) 「田」는 “밭”을 뜻합니다.","(소리부) 「丁」(チョウ)는 “못”을 뜻하는 글자입니다(링크 참조).","다만 여기서는 소리부의 역할만 하고 있습니다.","町는 “논밭(田)” -> “마을, 시가지”라는 뜻의 글자입니다(丁는 소리부)."],"sourceUrl":"https://nihongokanji.com/192/"},"料":{"id":185,"char":"料","hun":"헤아릴 료","meaning":"“헤아릴 료”. 요금, 재료","on":"リョウ","kun":"","explanation":["料 = 米 + 斗。","米(“쌀 미”)는 “쌀”을 뜻하는 상용한자입니다.","「斗」는 “국자”를 뜻하는 부수입니다(링크 참조).","料는 “국자(斗)로 쌀(米)을 퍼서 양을 계량하다” -> “재료, 요금”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/193/"},"工":{"id":186,"char":"工","hun":"장인 공","meaning":"“장인 공”. 공작, 공정, 가공","on":"コウ、ク","kun":"","explanation":["工는 “목공 작업에 쓰던 기계”를 본따 그린 상형문자입니다.","“목공 작업” -> “공작, 가공, 공정”이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/194/"},"建":{"id":187,"char":"建","hun":"세울 건","meaning":"“세울 건”. 설립하다, 세우다, 건설하다","on":"ケン、コン","kun":"た(てる)、た(つ)","explanation":["建 = 廴 + 聿。","「廴」는 “길”을 뜻하는 부수입니다(링크 참조).","「聿」는 “붓을 든 손”을 뜻합니다.","建는 “도로(廴)의 설계도를 그리다(聿)” -> “설립하다, 세우다, 건설하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/195/"},"急":{"id":188,"char":"急","hun":"급할 급","meaning":"“급할 급”. 급하다, 갑작스럽다","on":"キュウ","kun":"いそ(ぐ)","explanation":["急 = ⺈ + ⺕ + 心。","「⺈」는 “칼”을 뜻하는 부수입니다(링크 참조).","「⺕」는 “손”을 뜻합니다.","「心」는 “마음”을 뜻합니다.","急는 “손(⺕)에 칼(⺈)을 든 강도에게 쫓기는 다급한 마음(心)” -> “급하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/196/"},"止":{"id":189,"char":"止","hun":"그칠 지","meaning":"“그칠 지”. 멈추다, 중지하다","on":"シ","kun":"と(まる)、と(める)","explanation":["止는 “사람의 발”을 본따 그린 상형문자입니다.","“발걸음이 멈추다” -> “멈추다, 중지하다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/197/"},"送":{"id":190,"char":"送","hun":"보낼 송","meaning":"“보낼 송”. 보내다, 전송하다","on":"ソウ","kun":"おく(る)","explanation":["送 = ⻌ + 关。","「⻌」는 “길”을 뜻합니다.","「关」는 “웃음”을 뜻하는 글자입니다(링크 참조)","送는 “떠나는(⻌) 사람을 웃으며(关) 환송하다” -> “보내다, 전송하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/198/"},"切":{"id":191,"char":"切","hun":"끊을 절","meaning":"“끊을 절”. 자르다","on":"セツ、サイ","kun":"き(る)、き(れる)","explanation":["切 = 七 + 刀。","「七」는 본래 “칼로 무언가를 내리치는 모습”을 그린 글자입니다(링크 참조).","「刀」는 “칼”을 뜻합니다.","切는 “칼(刀)로 내리쳐(七) 자르다” -> “자르다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/199/"},"説":{"id":192,"char":"説","hun":"말씀 설","meaning":"“말씀 설”. 설명하다","on":"セツ、ゼイ","kun":"と(く)","explanation":["説 = 言 + 兑。","「言」는 “말하다”라는 뜻입니다.","「兑」는 “진지한 표정을 한 사람”을 뜻하는 글자입니다(링크 참조).","説는 “진지한 얼굴로(兑) 설명하다(言)” -> “설명하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/200/"},"転":{"id":193,"char":"転","hun":"구를 전","meaning":"“구를 전”. 구르다, 돌다, 방향을 전환하다","on":"テン","kun":"ころ(がる)、ころ(げる)、ころ(がす)、ころ(ぶ)","explanation":["転 = 車 + 云。","「車」는 “수레, 차”를 뜻합니다.","「云」는 “구름”을 뜻하는 글자입니다(링크 참조).","転는 “구름(云)이 흐르듯 굴러가는 수레바퀴(車)” -> “구르다, 돌다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/201/"},"研":{"id":194,"char":"研","hun":"갈 연","meaning":"“갈 연”. 갈다, 갈고닦다, 노력하다, 연구하다","on":"ケン","kun":"と(ぐ)","explanation":["研 = 石 + 开。","石(“돌 석”)은 “돌”을 뜻하는 상용한자입니다.","开는 여기서는 “평평한 나무책상”을 그린 모양자입니다.","研는 “평평한 작업대(开) 위에서 돌(石)을 갈다”라는 뜻입니다.","“돌을 열심히 갈다” -> “갈다, 갈고닦다, 노력하다, 연구하다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/202/"},"究":{"id":195,"char":"究","hun":"연구할 구","meaning":"“연구할 구”. 연구하다, 탐구하다","on":"キュウ","kun":"きわ(める)","explanation":["究 = 穴 + 九。","(의미부) 「穴」는 “구멍, 동굴”을 뜻합니다.","(소리부) 「九」(キュウ)는 여기서는 소리부의 역할만 하고 있습니다.","究는 “깊은 동굴(穴) 안을 파고들다” -> “탐구하다, 연구하다”라는 뜻의 글자입니다(九는 소리부)."],"sourceUrl":"https://nihongokanji.com/203/"},"楽":{"id":196,"char":"楽","hun":"즐길 락","meaning":"“즐길 락”. 즐겁다, 편안함, 음악","on":"ガク、ラク","kun":"たの(しい)、たの(しむ)","explanation":["楽 = 冫 + 白 + 冫 + 木。","「木」는 “나무”를 뜻합니다.","白는 여기서는 “거문고”를 그린 모양자입니다.","冫+冫는 여기서는 “(거문고의) 줄”을 그린 모양자입니다.","楽는 “나무(木)로 만든 거문고(冫+白+冫)를 타다” -> “음악, 편안함, 즐겁다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/204/"},"起":{"id":197,"char":"起","hun":"일어날 기","meaning":"“일어날 기”. 일어나다","on":"キ","kun":"お(きる)、お(こる)、お(こす)","explanation":["起 = 走 + 己。","(의미부) 走(“달릴 주”)는 “달리다”라는 뜻의 상용한자입니다.","(소리부 겸 의미부) 「己」(キ)는 “무릎꿇은 사람”을 뜻합니다(링크 참조).","起는 “무릎꿇은 사람(己)이 벌떡 일어나 달리다(走)” -> “일어나다”라는 뜻의 글자입니다.","(己는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/205/"},"着":{"id":198,"char":"着","hun":"붙을 착","meaning":"“붙을 착”. 붙다, 입다","on":"チャク、ジャク","kun":"き(る)、き(せる)、つ(く)、つ(ける)","explanation":["着 = ⺶ + 目。","⺶는 「羊」을 살짝 비튼 것으로, “양”을 뜻합니다(링크 참조).","「目」는 “눈”을 뜻합니다.","着는 “눈(目) 위에 양털(⺶) 모자를 눌러쓰다” -> “입다, 붙다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/206/"},"乗":{"id":199,"char":"乗","hun":"탈 승","meaning":"“탈 승”. 타다, 태우다","on":"ジョウ","kun":"の(る)、の(せる)","explanation":["乗 = 立 + 木。","「立」는 “서다”라는 뜻입니다.","「木」는 “나무”를 뜻합니다.","乗은 “나무(木) 위에 올라타 서다(立)” -> “타다, 태우다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/207/"},"病":{"id":200,"char":"病","hun":"병 병","meaning":"“병 병”. 질병, 아프다","on":"ビョウ、ヘイ","kun":"や(む)、やまい","explanation":["病 = 疒 + 丙。","(의미부) 「疒」는 “질병, 질환”을 뜻하는 부수입니다(링크 참조).","(소리부) 丙(ヘイ)는 “갑을병”의 “병”을 뜻하는 상용한자입니다.","다만 여기서는 소리부의 역할만 하고 있습니다.","病는 “질병(疒)” -> “병, 아프다”라는 뜻의 글자입니다(丙는 소리부)."],"sourceUrl":"https://nihongokanji.com/208/"},"声":{"id":201,"char":"声","hun":"소리 성","meaning":"“소리 성”. 소리","on":"セイ、ショウ","kun":"こえ、こわ","explanation":["声는 “석경”이라는 돌로 만든 아악기를 그린 상형문자입니다.","“석경을 치는 소리” -> “소리”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/209/"},"質":{"id":202,"char":"質","hun":"바탕 질","meaning":"“바탕 질”. 성질, 기질, 물질","on":"シツ、シチ、チ","kun":"","explanation":["質 = 斤 + 斤 + 貝。","「斤」는 “도끼”를 뜻하는 부수입니다.","「貝」는 “돈, 재물”을 뜻하는 부수입니다.","質는 “도끼 두 자루(斤斤)를 담보로 돈(貝)을 빌리다”라는 뜻입니다.","이때, 돈을 빌려주는 사람은 담보로 받는 저당물의 가치를 확인해보아야 할 것입니다.","“저당물의 가치” -> “품질” -> “성질, 기질”이라는 의미입니다.","참고)","質의 본래 뜻이었던 “저당물”이라는 의미는 지금도 人質ひとじち(인질), 質しち屋や(전당포) 등의 단어에 남아서 쓰이고 있습니다."],"sourceUrl":"https://nihongokanji.com/210/"},"待":{"id":203,"char":"待","hun":"기다릴 대","meaning":"“기다릴 대”. 기다리다, 대기하다","on":"タイ","kun":"ま(つ)","explanation":["待 = 彳 + 寺。","「彳」는 “길”을 뜻하는 부수입니다.","寺(ジ – “절 사”)는 “절, 사찰”을 뜻하는 상용한자입니다.","待는 “유명 사찰(寺)에 들어가기 위해 길(彳)에서 줄서서 기다리다” -> “기다리다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/211/"},"試":{"id":204,"char":"試","hun":"시험 시","meaning":"“시험 시”. 시험하다","on":"シ","kun":"こころ(みる)、ため(す)","explanation":["試 = 言 + 弋 + 工。","「言」는 “말하다”라는 뜻입니다.","「弋」는 “공구, 도구”를 뜻하는 부수입니다.","「工」는 “공작, 공정, 가공”을 뜻합니다.","試는 “목공용(工) 공구(弋)의 사용법을 아는지 물어보다(言)” -> “시험해보다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/212/"},"族":{"id":205,"char":"族","hun":"겨레 족","meaning":"“겨레 족”. 가족, 일족, 민족","on":"ゾク","kun":"","explanation":["族 = 𭤨 + 矢。","「𭤨」는 “바람에 나부끼는 깃발”을 뜻하는 글자입니다(링크 참조).","「矢」는 “화살”을 뜻합니다.","族는 “하나의 깃발(𭤨) 아래 뭉친 무장집단(矢)” -> “민족, 일족, 가족”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/213/"},"銀":{"id":206,"char":"銀","hun":"은 은","meaning":"“은 은”. 은(silver)","on":"ギン","kun":"","explanation":["銀 = 金 + 艮。","「金」는 “황금”을 뜻합니다.","「艮」는 “천민”을 뜻하는 부수입니다(링크 참조).","銀은 “금(金)보다 천한(艮) 금속” -> “은”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/214/"},"早":{"id":207,"char":"早","hun":"이를 조","meaning":"“이를 조”. 이르다, (시간적으로) 빠르다","on":"ソウ、サッ","kun":"はや(い)、はや(まる)、はや(める)","explanation":["早 = 日 + 十。","「日」는 “태양”을 뜻합니다.","十는 여기서는 “지평선”을 그린 모양자입니다.","早는 “지평선(十) 위로 해(日)가 막 떠오르는 아침” -> “이른 시간, 이르다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/215/"},"映":{"id":208,"char":"映","hun":"비칠 영","meaning":"“비칠 영”. 비추다, 비치다","on":"エイ","kun":"うつ(る)、うつ(す)、は(える)","explanation":["映 = 日 + 央。","「日」는 “태양”을 뜻합니다.","央(“가운데 앙”)은 “중앙”을 뜻하는 상용한자입니다.","映는 “하늘 중앙(央)에서 세상을 비추는 태양(日)” -> “비추다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/216/"},"親":{"id":209,"char":"親","hun":"친할 친","meaning":"“친할 친”. 부모, 친밀한","on":"シン","kun":"おや、した(しい)、した(しむ)","explanation":["親 = 立 + 木 + 見。","「立」는 “서다”라는 뜻입니다.","「木」는 “나무”를 뜻합니다.","「見」는 “보다”라는 뜻입니다.","親는 “나무(木) 뒤에 서서(立) 아이를 지켜보는(見) 부모” -> “부모, 친밀한”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/217/"},"験":{"id":210,"char":"験","hun":"시험 험","meaning":"“시험 험”. 시험하다, 경험, 효과","on":"ケン、ゲン","kun":"","explanation":["験 = 馬 + 㑒。","(의미부) 馬(“말 마”)는 “말”을 뜻하는 상용한자입니다.","(소리부 겸 의미부) 「㑒」(ケン)은 “뾰족하다, 날카롭다”라는 뜻의 글자입니다(링크 참조).","験은 “말(馬)을 타고 응시하는 무술(㑒) 시험” -> “시험”이라는 뜻의 글자입니다.","(㑒은 소리부(ケン -> ケン・ゲン)도 겸함)"],"sourceUrl":"https://nihongokanji.com/218/"},"働":{"id":211,"char":"働","hun":"일하다, 노동하다(일본에서 만들어진 한자)","meaning":"일하다, 노동하다(일본에서 만들어진 한자)","on":"ドウ","kun":"はたら(く)","explanation":["働 = 亻 + 動。","(의미부) 「亻」는 “사람”을 뜻합니다.","(소리부 겸 의미부) 「動」(ドウ)는 “움직이다”라는 뜻입니다.","働는 “열심히 움직이는(動) 사람(亻)” -> “일하다”라는 뜻의 글자입니다.","(動는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/219/"},"好":{"id":212,"char":"好","hun":"좋을 호","meaning":"“좋을 호”. 사랑하다, 좋아하다","on":"コウ","kun":"この(む)、す(く)","explanation":["好 = 女 + 子。","「女」는 “여자”를 뜻합니다.","「子」는 “아이”를 뜻합니다.","好는 “아기(子)를 꼭 끌어안은 여자(女)” -> “사랑하다, 좋아하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/220/"},"英":{"id":213,"char":"英","hun":"꽃부리/뛰어날 영","meaning":"“꽃부리/뛰어날 영”. 뛰어나다, 영국","on":"エイ","kun":"","explanation":["英 = 艹 + 央。","「艹」는 “풀”을 뜻하는 부수입니다.","央(“가운데 앙”)은 “중앙”을 뜻하는 상용한자입니다.","英는 “잔디밭(艹) 중앙(央)에 홀로 핀 화려한 꽃” -> “뛰어나다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/221/"},"頭":{"id":214,"char":"頭","hun":"머리 두","meaning":"“머리 두”. 머리, 우두머리","on":"トウ、ズ、ト","kun":"あたま、かしら","explanation":["頭 = 豆 + 頁。","(소리부 겸 의미부) 「豆」(トウ、ズ)는 “콩, 둥근 것”을 뜻하는 부수입니다(링크 참조).","(의미부) 「頁」는 “머리”를 뜻하는 부수입니다.","頭는 “둥근(豆) 머리통(頁)” -> “머리”라는 뜻의 글자입니다.","(豆는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/222/"},"低":{"id":215,"char":"低","hun":"낮을 저","meaning":"“낮을 저”. 낮다","on":"テイ","kun":"ひく(い)、ひく(める)、ひく(まる)","explanation":["低 = 亻 + 氐。","(의미부) 「亻」는 “사람”을 뜻합니다.","(소리부 겸 의미부) 「氐」(テイ)는 “낮다”라는 뜻의 글자입니다(링크 참조).","低는 “신분이 낮은(氐) 사람(亻)” -> “낮다”라는 뜻의 글자입니다.","(氐는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/223/"},"医":{"id":216,"char":"医","hun":"의원 의","meaning":"“의원 의”. 의사","on":"イ","kun":"","explanation":["医 = 匚 + 矢。","匚는 여기서는 “(의원의) 집”을 그린 모양자입니다.","「矢」는 “화살”을 뜻합니다.","医는 “화살(矢)에 맞아 다친 사람을 치료하는 곳(匚)” -> “의원, 의사”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/224/"},"仕":{"id":217,"char":"仕","hun":"섬길 사","meaning":"“섬길 사”. 섬기다, 시중들다","on":"シ、ジ","kun":"つか(える)","explanation":["仕 = 亻 + 士。","(의미부) 「亻」는 “사람”을 뜻합니다.","(소리부 겸 의미부) 士(シ – “선비 사”)는 “선비, 무사”를 뜻하는 상용한자입니다.","仕는 “무사(士)의 시중을 드는 시종(亻)” -> “시중들다, 섬기다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/225/"},"去":{"id":218,"char":"去","hun":"갈 거","meaning":"“갈 거”. 떠나가다, 지나가다","on":"キョ、コ","kun":"さ(る)","explanation":["去는 “사람이 문 밖으로 나가는 모습”을 그린 상형문자입니다.","“집을 떠나다” -> “떠나가다, 지나가다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/226/"},"味":{"id":219,"char":"味","hun":"맛 미","meaning":"“맛 미”. 맛, 맛보다, 흥미, 재미","on":"ミ","kun":"あじ、あじ(わう)","explanation":["味 = 口 + 未。","(의미부) 「口」는 “입”을 뜻합니다.","(소리부 겸 의미부) 未(ミ – “아닐 미”)는 “아직, 미숙한”이란 뜻의 상용한자입니다.","味는 “아직(未) 맛보지(口) 못한 음식” -> “맛, 흥미, 재미”라는 뜻의 글자입니다.","(未는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/227/"},"門":{"id":220,"char":"門","hun":"문 문","meaning":"“문 문”. 문","on":"モン","kun":"かど","explanation":["門는 “문”의 모습을 본따 그린 상형문자입니다."],"sourceUrl":"https://nihongokanji.com/228/"},"写":{"id":221,"char":"写","hun":"베낄 사","meaning":"“베낄 사”. 베끼다, 사진","on":"シャ","kun":"うつ(す)、うつ(る)","explanation":["写 = 冖 + 与。","冖는 여기서는 「宀」가 변형된 것으로, “집”을 뜻합니다.","与(“줄 여”)는 “주다”라는 뜻의 상용한자입니다.","写는 “집문서(冖)의 사본을 넘겨주다(与)” -> “등기, 사본” -> “베끼다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/229/"},"字":{"id":222,"char":"字","hun":"글자 자","meaning":"“글자 자”. 글자","on":"ジ","kun":"あざ","explanation":["字 = 宀 + 子。","「宀」는 “집”을 뜻합니다.","「子」는 “아이”를 뜻합니다.","字는 “집(宀)에서 아이(子)가 태어나듯 새로운 한자가 만들어지다” -> “글자”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/230/"},"答":{"id":223,"char":"答","hun":"대답 답","meaning":"“대답 답”. 대답하다","on":"トウ","kun":"こた(える)、こた(え)","explanation":["答 = 𥫗 + 合。","「𥫗」는 “대나무, 대나무 죽간”을 뜻하는 부수입니다(링크 참조).","「合」는 “들어맞다, 합치다”라는 뜻입니다.","答는 “죽간(𥫗)에 쓰인 편지의 내용에 맞게(合) 회답하다” -> “대답하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/231/"},"夜":{"id":224,"char":"夜","hun":"밤 야","meaning":"“밤 야”. 밤","on":"ヤ","kun":"よ、よる","explanation":["夜 = 亠 + 亻 + 月。","亠는 여기서는 「宀」가 살짝 변형된 것으로, “집”을 뜻합니다.","「亻」는 “사람”을 뜻합니다.","오른쪽 하단은 「月」가 변형된 것으로, “달”을 뜻합니다.","夜는 “달(月)이 뜬 밤에 집(亠)에서 자는 사람(亻)” -> “밤”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/232/"},"音":{"id":225,"char":"音","hun":"소리 음","meaning":"“소리 음”. 소리, 음","on":"オン、イン","kun":"おと、ね","explanation":["音는 「言」가 변형되어 만들어진 글자입니다.","“말소리(言)” -> “소리”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/233/"},"注":{"id":226,"char":"注","hun":"부을 주","meaning":"“부을 주”. 쏟다, 집중하다","on":"チュウ","kun":"そそ(ぐ)","explanation":["注 = 氵 + 主。","(의미부) 「氵」는 “물”을 뜻하는 부수입니다.","(소리부) 「主」(シュ)는 여기서는 소리부(シュ -> チュウ)의 역할만 하고 있습니다.","注는 “물(氵)을 쏟아붓다” -> “쏟다, 집중하다”라는 뜻의 글자입니다(主는 소리부)."],"sourceUrl":"https://nihongokanji.com/234/"},"帰":{"id":227,"char":"帰","hun":"돌아갈 귀","meaning":"“돌아갈 귀”. 돌아가다, 돌아오다, 귀가하다","on":"キ","kun":"かえ(る)、かえ(す)","explanation":["帰 = リ + 帚。","リ는 여기서는 “굽어진 길”을 그린 모양자로, “귀갓길”을 뜻합니다.","「帚」는 “빗자루”를 뜻하는 글자입니다(링크 참조).","帰는 “일을 마치고 귀가하는(リ) 남편을 맞이하기 위해 집을 청소(帚)하는 아내”라는 뜻입니다.","“일을 마치고 돌아온 남편” -> “돌아가다, 돌아오다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/235/"},"歌":{"id":228,"char":"歌","hun":"노래 가","meaning":"“노래 가”. 노래, 노래하다","on":"カ","kun":"うた、うた(う)","explanation":["歌 = 哥 + 欠。","哥는 “노래”를 뜻하는 글자입니다.","「欠」는 “입으로 하는 동작”을 뜻합니다.","歌는 “입을 벌리고(欠) 노래하다(哥)” -> “노래하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/236/"},"光":{"id":229,"char":"光","hun":"빛 광","meaning":"“빛 광”. 빛","on":"コウ","kun":"ひか(る)、ひかり","explanation":["光 = 火 + 儿。","「火」는 “불”을 뜻합니다.","儿는 「人」가 변형된 것으로, “사람”을 뜻합니다.","光는 “횃불(火)을 든 사람(儿)” -> “빛나다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/237/"},"悪":{"id":230,"char":"悪","hun":"악할 악/미워할 오","meaning":"“악할 악/미워할 오”. 악, 나쁘다, 미워하다","on":"アク、オ","kun":"わる(い)","explanation":["悪 = 亜 + 心。","亜는 亞가 변형된 것으로, “사방이 꽉 막혀있는 요새”를 그린 모양자입니다.","「心」는 “마음”을 뜻합니다.","悪는 “꽉 닫혀있는(亜) 마음(心)” -> “악하다, 미워하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/238/"},"図":{"id":231,"char":"図","hun":"그림 도","meaning":"“그림 도”. 그림, 지도","on":"ズ、ト","kun":"はか(る)","explanation":["図는 “지도”의 모습을 본따 그린 상형문자입니다.","囗는 “종이”를 표현한 것이고, 안쪽의 선들은 “종이 위에 그려져있는 지도”를 표현한 것입니다."],"sourceUrl":"https://nihongokanji.com/239/"},"室":{"id":232,"char":"室","hun":"집 실","meaning":"“집 실”. 방, 거실, 아내","on":"シツ","kun":"むろ","explanation":["室 = 宀 + 𠫔 + 土。","「宀」는 “집”을 뜻합니다.","「土」는 “흙, 땅”을 뜻합니다.","𠫔는 여기서는 “책상”을 그린 모양자입니다.","室는 “집(宀) 안의 바닥(土)에 놓인 책상(𠫔)” -> “방, 거실”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/240/"},"太":{"id":233,"char":"太","hun":"클 태","meaning":"“클 태”. 크다, 굵다","on":"タイ、タ","kun":"ふと(い)、ふと(る)","explanation":["太는 “크다”를 뜻하는 「大」에 점(丶)을 하나 더 찍어서 “(더더욱) 크다, 굵다”라는 뜻을 표현한 글자입니다."],"sourceUrl":"https://nihongokanji.com/241/"},"歩":{"id":234,"char":"歩","hun":"걸음 보","meaning":"“걸음 보”. 걸음, 걷다","on":"ホ、ブ、フ","kun":"ある(く)、あゆ(む)","explanation":["歩 = 止 + 少。","「止」는 “발”을 뜻합니다.","「少」는 “적다”라는 뜻입니다.","歩는 “어린아이(少)가 아장아장 걷다(止)” -> “걷다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/242/"},"風":{"id":235,"char":"風","hun":"바람 풍","meaning":"“바람 풍”. 바람","on":"フウ、フ","kun":"かぜ、かざ","explanation":["風는 “봉황”의 모습을 그린 상형문자입니다.","“봉황의 날갯짓” -> “바람”이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/243/"},"紙":{"id":236,"char":"紙","hun":"종이 지","meaning":"“종이 지”. 종이","on":"シ","kun":"かみ","explanation":["紙 = 糸 + 氏。","(의미부) 「糸」는 “실”을 뜻합니다.","(소리부) 氏(シ – “성씨 씨”)는 “성씨”를 뜻하는 상용한자입니다.","다만 여기서는 소리부(シ)의 역할만 하고 있습니다.","종이가 없던 시대에는 종종 실로 짠 비단에 글을 써서 남기곤 했습니다.","紙는 “(종이 대신 사용한) 실(糸)로 짠 비단” -> “종이”라는 뜻의 글자입니다(氏는 소리부)."],"sourceUrl":"https://nihongokanji.com/244/"},"黒":{"id":237,"char":"黒","hun":"검을 흑","meaning":"“검을 흑”. 검정","on":"コク","kun":"くろ、くろ(い)","explanation":["黒 = 里 + 灬。","「里」는 “마을”을 뜻합니다.","「灬」는 “불”을 뜻하는 부수입니다(링크 참조).","黒는 “화재(灬)로 검게 불탄 마을(里)” -> “검다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/245/"},"春":{"id":238,"char":"春","hun":"봄 춘","meaning":"“봄 춘”. 봄","on":"シュン","kun":"はる","explanation":["春 = 𡗗 + 日。","𡗗는 여기서는 “새싹이 올라오는 모습”을 그린 모양자입니다.","「日」는 “태양”을 뜻합니다.","春는 “따스한 봄 햇살(日)을 받으며 땅 위로 올라오는 새싹(𡗗)” -> “봄”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/246/"},"赤":{"id":239,"char":"赤","hun":"붉을 적","meaning":"“붉을 적”. 빨강","on":"セキ、シャク","kun":"あか、あか(い)、あか(らむ)、あか(らめる)","explanation":["赤 = 土 + 火。","「土」는 “흙”을 뜻합니다.","「火」는 “불”을 뜻합니다.","赤는 “불(火)처럼 빨간 적토(土)” -> “빨강, 붉다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/247/"},"青":{"id":240,"char":"青","hun":"푸를 청","meaning":"“푸를 청”. 푸르다","on":"セイ、ショウ","kun":"あお、あお(い)","explanation":["青 = 龶 + 月。","(소리부 겸 의미부) 龶는 여기서는 「生」(セイ・ショウ)가 축약된 것으로, “생명, 태어나다”라는 뜻입니다.","(의미부) 「月」는 “달”을 뜻합니다.","青는 “푸른 새싹(生) + 푸른 달(月)” -> “푸르다”라는 뜻의 글자입니다.","(生는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/248/"},"森":{"id":241,"char":"森","hun":"숲 삼","meaning":"“숲 삼”. 숲","on":"シン","kun":"もり","explanation":["森 = 木 + 木 + 木。","「木」는 “나무”를 뜻합니다.","森는 “나무(木)가 울창한 숲” -> “숲”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/249/"},"館":{"id":242,"char":"館","hun":"집 관","meaning":"“집 관”. 큰 건물","on":"カン","kun":"やかた","explanation":["館 = 食 + 官。","(의미부) 「食」는 “먹다”라는 뜻입니다.","(소리부 겸 의미부) 官(カン – “벼슬 관”)은 “관청, 관리”를 뜻하는 상용한자입니다.","館는 “관청(官)의 관리들이 식사하는(食) 커다란 건물” -> “큰 건물”이라는 뜻의 글자입니다.","(官은 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/250/"},"屋":{"id":243,"char":"屋","hun":"집 옥","meaning":"“집 옥”. 지붕, 집","on":"オク","kun":"や","explanation":["屋 = 尸 + 𠫔 + 土。","「尸」는 “지붕, 집”을 뜻하는 부수입니다(링크 참조).","𠫔+土는 여기서는 「室」가 축약된 것으로, “집”을 뜻합니다.","屋는 “집(室) 위의 지붕(尸)” -> “지붕, 집”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/251/"},"色":{"id":244,"char":"色","hun":"빛 색","meaning":"“빛 색”. 색, 색깔, 정욕","on":"ショク、シキ","kun":"いろ","explanation":["色는 “남녀가 성관계를 맺고 있는 모습”을 그린 상형문자입니다.","“성관계 중에 얼굴이 붉어지다” -> “색채, 정욕”이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/252/"},"走":{"id":245,"char":"走","hun":"달릴 주","meaning":"“달릴 주”. 달리다","on":"ソウ","kun":"はし(る)","explanation":["走 = 土 + 止。","「土」는 “흙, 땅”을 뜻합니다.","「止」는 “발”을 뜻합니다.","走는 “땅(土) 위를 달리는 발(止)” -> “달리다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/253/"},"秋":{"id":246,"char":"秋","hun":"가을 추","meaning":"“가을 추”. 가을","on":"シュウ","kun":"あき","explanation":["秋 = 禾 + 火。","「禾」는 “곡식”을 뜻합니다.","「火」는 “불”을 뜻합니다.","秋는 “곡식(禾)이 익는(火) 계절” -> “가을”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/254/"},"林":{"id":247,"char":"林","hun":"수풀 림","meaning":"“수풀 림”. 수풀, 숲","on":"リン","kun":"はやし","explanation":["林 = 木 + 木。","「木」는 “나무”를 뜻합니다.","林는 “나무(木)가 많은 곳” -> “숲”이라는 뜻의 글자입니다.","참고)","林는 「森」에 비해 크기가 조금 작은 숲을 뜻합니다."],"sourceUrl":"https://nihongokanji.com/255/"},"夏":{"id":248,"char":"夏","hun":"여름 하","meaning":"“여름 하”. 여름","on":"カ、ゲ","kun":"なつ","explanation":["夏 = 𦣻 + 夂。","𦣻는 여기서는 「頁」가 축약된 것으로, “머리”를 뜻합니다.","「夂」는 “발”을 뜻합니다.","夏는 “머리(𦣻)부터 발끝(夂)까지 땀으로 푹 젖다” -> “여름”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/256/"},"顔":{"id":249,"char":"顔","hun":"낯 안","meaning":"“낯 안”. 얼굴","on":"ガン","kun":"かお","explanation":["顔 = 彦 + 頁。","彦는 여기서는 “콧수염”을 그린 모양자입니다. 产는 코, 彡는 수염을 각각 표현한 것입니다.","「頁」는 “머리”를 뜻합니다.","顔는 “콧수염(彦)을 기른 얼굴(頁)” -> “얼굴”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/257/"},"短":{"id":250,"char":"短","hun":"짧을 단","meaning":"“짧을 단”. 짧다","on":"タン","kun":"みじか(い)","explanation":["短 = 矢 + 豆。","「矢」는 “화살”을 뜻합니다.","「豆」는 “콩”을 뜻합니다.","短는 “콩알만한(豆) 표적도 화살(矢)로 맞출 수 있을 만큼 짧은 거리” -> “짧다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/258/"},"薬":{"id":251,"char":"薬","hun":"약 약","meaning":"“약 약”. 약, 약재","on":"ヤク","kun":"くすり","explanation":["薬 = 艹 + 楽。","「艹」는 “풀”을 뜻합니다.","「楽」는 “즐겁다, 편안하다”라는 뜻입니다.","薬는 “아픈 사람을 편안하게(楽) 해 주는 약초(艹)” -> “약, 약재”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/259/"},"習":{"id":252,"char":"習","hun":"익힐 습","meaning":"“익힐 습”. 배우다, 익히다","on":"シュウ","kun":"なら(う)","explanation":["習 = 羽 + 白。","羽(“깃 우”)는 “날개, 깃털”을 뜻하는 상용한자입니다.","「白」는 “흰색”을 뜻합니다.","習는 “처음 날갯짓(羽)을 배우는 하얀(白) 아기새” -> “배우다, 익히다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/260/"},"便":{"id":253,"char":"便","hun":"편할 편","meaning":"“편할 편”. 편리하다, 편지, 대소변","on":"ベン、ビン","kun":"たよ(り)","explanation":["便 = 亻 + 更。","「亻」는 “사람”을 뜻합니다.","更(“고칠 경/갱”)은 “고치다, 바꾸다”라는 뜻의 상용한자입니다.","便는 “사람(亻)이 불편한 점을 고쳐서(更) 편안해지다”라는 뜻입니다.","여기서 “불편한 점”이란 “대소변”을 뜻합니다.","“대소변을 해결하고 편안해지다” -> “대소변, 편리하다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/261/"},"洋":{"id":254,"char":"洋","hun":"큰 바다 양","meaning":"“큰 바다 양”. 대양","on":"ヨウ","kun":"","explanation":["洋 = 氵 + 羊。","(의미부) 「氵」는 “물”을 뜻합니다.","(소리부) 「羊」(ヨウ)는 “양”을 뜻하는 부수입니다.","다만 여기서는 소리부(ヨウ)의 역할만 하고 있습니다.","洋는 “물(氵)” -> “대양”이라는 뜻의 글자입니다(羊는 소리부)."],"sourceUrl":"https://nihongokanji.com/262/"},"旅":{"id":255,"char":"旅","hun":"나그네 여","meaning":"“나그네 여”. 여행","on":"リョ","kun":"たび","explanation":["旅 = 𭤨 + 𧘇。","「𭤨」는 “바람에 나부끼는 깃발”을 뜻합니다.","𧘇는 여기서는 「亻」두 개가 합쳐진 것으로, “여러 명의 사람들(亻)”이라는 뜻입니다.","旅는 “군기(𭤨)를 휘날리며 원정을 떠나는 병사들(𧘇)” -> “여행”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/263/"},"軽":{"id":256,"char":"軽","hun":"가벼울 경","meaning":"“가벼울 경”. 가볍다","on":"ケイ","kun":"かる(い)、かろ(やか)","explanation":["軽 = 車 + 圣。","(의미부) 「車」는 “수레, 차”를 뜻합니다.","(소리부 겸 의미부) 「圣」(ケイ)는 “지나가다”라는 뜻의 글자입니다(링크 참조).","軽는 “마차(車)가 가볍게 지나가다(圣)” -> “가볍다”라는 뜻의 글자입니다.","(圣는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/264/"},"池":{"id":257,"char":"池","hun":"못 지","meaning":"“못 지”. 연못","on":"チ","kun":"いけ","explanation":["池 = 氵 + 也。","(의미부) 「氵」는 “물”을 뜻합니다.","(소리부 겸 의미부) 也는 여기서는 「地」(チ)가 축약된 것으로, “땅”을 뜻합니다.","池는 “땅(地) 위의 물웅덩이(氵)” -> “연못”이라는 뜻의 글자입니다.","(也->地는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/265/"},"服":{"id":258,"char":"服","hun":"옷 복","meaning":"“옷 복”. 옷, 복종시키다","on":"フク","kun":"","explanation":["服 = 月 + 卩 + 又。","「月」는 “달”을 뜻합니다.","「卩」는 “무릎꿇은 사람”을 뜻하는 부수입니다(링크 참조).","「又」는 “손”을 뜻합니다.","服는 “밤도둑(月)을 잡아서(又) 무릎꿇리다(卩)“라는 뜻입니다.","“도둑을 잡아 무릎꿇리다” -> “항복/복종시키다”","“감옥에 갇힌 도둑이 입는 죄수복” -> “옷”","이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/266/"},"遠":{"id":259,"char":"遠","hun":"멀 원","meaning":"“멀 원”. 멀다","on":"エン、オン","kun":"とお(い)","explanation":["遠 = ⻌ + 袁。","(의미부) 「⻌」는 “길”을 뜻합니다.","(소리부 겸 의미부) 「袁」(エン)은 “길다, 헐렁하다”라는 뜻의 글자입니다(링크 참조).","遠는 “기나긴(袁) 길(⻌)” -> “멀다”라는 뜻의 글자입니다.","(袁는 소리부(エン -> エン・オン)도 겸함)"],"sourceUrl":"https://nihongokanji.com/267/"},"夕":{"id":260,"char":"夕","hun":"저녁 석","meaning":"“저녁 석”. 저녁","on":"セキ","kun":"ゆう","explanation":["夕는 “초승달”을 본따 그린 상형문자입니다.","“초승달이 뜬 시간” -> “저녁”이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/268/"},"借":{"id":261,"char":"借","hun":"빌릴 차","meaning":"“빌릴 차”. 빌리다","on":"シャク","kun":"か(りる)","explanation":["借 = 亻 + 昔。","(의미부) 「亻」는 “사람”을 뜻합니다.","(소리부 겸 의미부) 昔(シャク – “옛 석”)은 “옛날”을 뜻하는 상용한자입니다.","借는 “남에게(亻) 옛날에(昔) 빌린 돈을 아직도 갚지 못하다“ -> “빌리다”라는 뜻의 글자입니다.","(昔는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/269/"},"曜":{"id":262,"char":"曜","hun":"요일 요","meaning":"“요일 요”. 요일","on":"ヨウ","kun":"","explanation":["曜 = 日 + 羽 + 隹。","「日」는 “하루”를 뜻합니다.","「隹」는 “새”를 뜻합니다.","羽(“깃 우”)는 “날개, 깃털”을 뜻하는 상용한자입니다.","曜는 “매일(日) 아침 홰를 치며(羽) 우는 닭(隹)” -> “매일” -> “요일”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/270/"},"弱":{"id":263,"char":"弱","hun":"약할 약","meaning":"“약할 약”. 약하다","on":"ジャク","kun":"よわ(い)、よわ(る)、よわ(まる)、よわ(める)","explanation":["弱 = 弓 + 冫 + 弓 + 冫。","「弓」는 “활”을 뜻합니다.","「冫」는 “얼음”을 뜻합니다.","弱는 “활(弓)이 얼어서(冫) 망가지다” -> “약해지다, 약하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/271/"},"肉":{"id":264,"char":"肉","hun":"고기 육","meaning":"“고기 육”. 고기","on":"ニク","kun":"","explanation":["肉는 “고기에 칼집을 낸 모습”을 그린 상형문자입니다."],"sourceUrl":"https://nihongokanji.com/272/"},"貸":{"id":265,"char":"貸","hun":"빌릴 대","meaning":"“빌릴 대”. 빌려주다","on":"タイ","kun":"か(す)","explanation":["貸 = 代 + 貝。","(소리부 겸 의미부) 「代」(タイ)는 “대신하다”라는 뜻입니다.","(의미부) 「貝」는 “돈, 재물”을 뜻합니다.","貸는 “돈(貝)을 대신(代) 빌려주다” -> “빌려주다”라는 뜻의 글자입니다.","(代는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/273/"},"堂":{"id":266,"char":"堂","hun":"집 당","meaning":"“집 당”. 전당, 큰 건물","on":"ドウ","kun":"","explanation":["堂 = 龸 + 口 + 土。","「龸」는 “궁궐”을 뜻하는 글자입니다(링크 참조).","口는 여기서는 “궁궐의 출입구”를 그린 모양자입니다.","「土」는 “흙, 땅”을 뜻합니다.","堂는 “땅(土) 위의 거대한 궁궐(龸)의 출입구(口)” -> “전당, 큰 건물”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/274/"},"暗":{"id":267,"char":"暗","hun":"어두울 암","meaning":"“어두울 암”. 어둡다","on":"アン","kun":"くら(い)","explanation":["暗 = 日 + 音。","「日」는 “해”를 뜻합니다.","「音」는 “소리”를 뜻합니다.","暗는 “햇빛(日)이 없어 소리(音)밖에 들리지 않는 어두운 곳” -> “어둡다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/275/"},"鳥":{"id":268,"char":"鳥","hun":"새 조","meaning":"“새 조”. 새","on":"チョウ","kun":"とり","explanation":["鳥는 “새”의 모습을 본따 그린 상형문자입니다."],"sourceUrl":"https://nihongokanji.com/276/"},"飯":{"id":269,"char":"飯","hun":"밥 반","meaning":"“밥 반”. 식사, 밥","on":"ハン","kun":"めし","explanation":["飯 = 食 + 反。","(의미부) 「食」는 “먹다”라는 뜻입니다.","(소리부) 反(ハン – “돌이킬 반”)은 “반대, 뒤집다”라는 뜻의 상용한자입니다.","다만 여기서는 소리부의 역할만 하고 있습니다.","飯는 “먹다(食)” -> “식사”라는 뜻의 글자입니다(反은 소리부)."],"sourceUrl":"https://nihongokanji.com/277/"},"勉":{"id":270,"char":"勉","hun":"힘쓸 면","meaning":"“힘쓸 면”. 힘쓰다, 노력하다","on":"ベン","kun":"","explanation":["勉 = 免 + 力。","免(“면할 면”)은 “면하다”라는 뜻의 상용한자입니다.","「力」는 “힘”을 뜻합니다.","勉는 “가난을 면하기(免) 위해 열심히 노력하다(力)” -> “힘쓰다, 노력하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/278/"},"冬":{"id":271,"char":"冬","hun":"겨울 동","meaning":"“겨울 동”. 겨울","on":"トウ","kun":"ふゆ","explanation":["冬 = 夂 + 冫。","「夂」는 “발”을 뜻합니다.","「冫」는 “얼음”을 뜻합니다.","冬는 “발(夂) 밑의 얼음(冫)” -> “얼어붙은 길” -> “겨울”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/279/"},"昼":{"id":272,"char":"昼","hun":"낮 주","meaning":"“낮 주”. 낮","on":"チュウ","kun":"ひる","explanation":["昼 = 尺 + 日 + 一。","「日」는 “해”를 뜻합니다.","尺+一는 여기서는 “창문”을 그린 모양자입니다.","昼는 “창밖(尺+一)에 해(日)가 뜨다” -> “낮”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/280/"},"茶":{"id":273,"char":"茶","hun":"차 다","meaning":"“차 다”. 차(tea)","on":"チャ、サ","kun":"","explanation":["茶 = 艹 + 𠆢 + 朩。","「艹」는 “풀”을 뜻합니다.","𠆢 + 朩는 여기서는 “작은 오두막”을 그린 모양자입니다.","茶는 “작은 오두막(𠆢+朩)에서 소박하게 즐기는 차(艹)” -> “차”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/281/"},"弟":{"id":274,"char":"弟","hun":"아우 제","meaning":"“아우 제”. 남동생, 제자","on":"テイ、ダイ、デ","kun":"おとうと","explanation":["弟는 “장작을 밧줄로 칭칭 감아놓은 모습”을 그린 상형문자입니다.","“형이 패놓은 장작을 들어서 옮기는 남동생” -> “남동생”이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/282/"},"洗":{"id":275,"char":"洗","hun":"씻을 세","meaning":"“씻을 세”. 씻다","on":"セン","kun":"あら(う)","explanation":["洗 = 氵 + 先。","(의미부) 「氵」는 “물”을 뜻합니다.","(소리부 겸 의미부) 「先」(セン)은 “먼저, 앞서”라는 뜻입니다.","洗는 “중요한 의식에 앞서(先) 몸을 정갈히 씻다(氵)” -> “씻다”라는 뜻의 글자입니다.","(先은 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/283/"},"牛":{"id":276,"char":"牛","hun":"소 우","meaning":"“소 우”. 소","on":"ギュウ","kun":"うし","explanation":["牛는 “뿔이 달린 소의 머리”를 그린 상형문자입니다."],"sourceUrl":"https://nihongokanji.com/284/"},"兄":{"id":277,"char":"兄","hun":"형 형","meaning":"“형 형”. 형, 오빠","on":"ケイ、キョウ","kun":"あに","explanation":["兄 = 口 + 儿。","「口」는 “입”을 뜻합니다.","儿는 「人」가 살짝 변형된 것으로, “사람”을 뜻합니다.","兄는 “말(口)로 동생들에게 지시를 내리는 맏형(儿)” -> “형”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/285/"},"犬":{"id":278,"char":"犬","hun":"개 견","meaning":"“개 견”. 개","on":"ケン","kun":"いぬ","explanation":["犬는 “꼬리가 강조된 개”를 그린 상형문자입니다."],"sourceUrl":"https://nihongokanji.com/286/"},"菜":{"id":279,"char":"菜","hun":"나물 채","meaning":"“나물 채”. 야채, 채소","on":"サイ","kun":"な","explanation":["菜 = 艹 + 采。","(의미부) 「艹」는 “풀”을 뜻합니다.","(소리부 겸 의미부) 「采」(サイ)는 “뽑다, 따다”라는 뜻의 글자입니다(링크 참조).","菜는 “나물(艹)을 캐다(采)” -> “야채, 채소”라는 뜻의 글자입니다.","(采는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/287/"},"暑":{"id":280,"char":"暑","hun":"더울 서","meaning":"“더울 서”. 덥다","on":"ショ","kun":"あつ(い)","explanation":["暑 = 日 + 者。","「日」는 “해”를 뜻합니다.","「者」는 “사람”을 뜻합니다.","暑는 “뜨거운 햇빛(日)을 받으며 서있는 사람(者)” -> “덥다” 라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/288/"},"妹":{"id":281,"char":"妹","hun":"누이 매","meaning":"“누이 매”. 여동생","on":"マイ","kun":"いもうと","explanation":["妹 = 女 + 未。","「女」는 “여자”를 뜻합니다.","未(“아닐 미”)는 “아직, 미숙한”이란 뜻의 상용한자입니다.","妹는 “미숙한(未) 여자아이(女)” -> “여동생”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/289/"},"寒":{"id":282,"char":"寒","hun":"찰 한","meaning":"“찰 한”. 춥다","on":"カン","kun":"さむ(い)","explanation":["寒 = 宀 + 𠀎 + ハ + ⺀。","「宀」는 “집”을 뜻합니다.","𠀎는 여기서는 “풀을 엮어 만든 담요”를 그린 모양자입니다.","ハ+⺀는 여기서는 「冬」가 축약된 것으로, “겨울”을 뜻합니다.","寒는 “추운 겨울(冬)에 집(宀)에서 담요(𠀎)를 뒤집어쓰다” -> “춥다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/290/"},"姉":{"id":283,"char":"姉","hun":"누이 자","meaning":"“누이 자”. 누나, 언니","on":"シ","kun":"あね","explanation":["姉 = 女 + 市。","(의미부) 「女」는 “여자”를 뜻합니다.","(소리부 겸 의미부) 「市」(シ)는 “시장”을 뜻합니다.","姉는 “시장(市)에 장을 보러 가는 누이(女)” -> “누나, 언니”라는 뜻의 글자입니다.","(市는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/291/"},"漢":{"id":284,"char":"漢","hun":"한나라 한","meaning":"“한나라 한”. 한나라, 중국","on":"カン","kun":"","explanation":["漢 = 氵 + 艹 + 口 + 夫。","「氵」는 “물”을 뜻합니다.","「艹」는 “풀”을 뜻합니다.","口는 여기서는 “건물을 쌓는 데 쓰는 돌”을 표현한 모양자입니다.","夫(“지아비 부”)는 “남편, 성인 남성”을 뜻하는 상용한자입니다.","漢는 “강가(氵)의 풀밭(艹)에 집을 짓는(口) 성인 남성(夫)”이라는 뜻입니다.","여기서 “강가에 집을 짓는다”라는 것은 “양쯔강 문명”을 뜻합니다.","“양쯔강 문명” -> “한나라, 중국”이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/292/"},"議":{"id":285,"char":"議","hun":"의논할 의","meaning":"“의논할 의”. 의논하다, 상의하다","on":"ギ","kun":"","explanation":["議 = 言 + 義。","(의미부) 「言」는 “말하다”라는 뜻입니다.","(소리부 겸 의미부) 義(ギ – “옳을 의”)는 “옳다, 의롭다”라는 뜻의 상용한자입니다.","議는 “의(義)를 논하다(言)” -> “의논하다, 상의하다”라는 뜻의 글자입니다.","(義는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/293/"},"連":{"id":286,"char":"連","hun":"이을 연","meaning":"“이을 연”. 잇다, 연결, 연속되다","on":"レン","kun":"つら(なる)、つら(ねる)、つ(れる)","explanation":["連 = ⻌ + 車。","「⻌」는 “길”을 뜻합니다.","「車」는 “수레, 차”를 뜻합니다.","連는 “길(⻌)에 수레(車)가 줄지어 다니다” -> “잇다, 연속되다, 연결되다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/294/"},"対":{"id":287,"char":"対","hun":"대할 대","meaning":"“대할 대”. 대하다, 마주보다","on":"タイ、ツイ","kun":"","explanation":["対 = 文 + 寸。","「文」는 본래 “가슴팍에 문신이 있는 사람”을 그린 글자입니다(링크 참조).","「寸」는 “손”을 뜻합니다.","対는 “건장한 남성(文)이 주먹(寸)을 치켜들고 상대와 대적하다” -> “대하다, 마주보다, 상대”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/295/"},"部":{"id":288,"char":"部","hun":"떼 부","meaning":"“떼 부”. 부분, 부서","on":"ブ","kun":"","explanation":["部 = 咅 + ⻏。","「咅」는 “화분 위의 화초”를 그린 글자입니다(링크 참조).","「⻏」는 “도시”를 뜻합니다.","部는 “대도시(⻏) 안의 화초(咅)를 매매하는 구역” -> “부분, 부서”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/296/"},"内":{"id":289,"char":"内","hun":"안 내","meaning":"“안 내”. 안, 안쪽, 내부","on":"ナイ、ダイ","kun":"うち","explanation":["内 = 人 + 冂。","「人」는 “사람”을 뜻합니다.","冂는 여기서는 “건물의 내부”를 표현한 모양자입니다.","内는 “건물 안(冂)에 있는 사람(人)” -> “안쪽, 내부”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/297/"},"相":{"id":290,"char":"相","hun":"서로 상","meaning":"“서로 상”. 서로, 모양, 벼슬","on":"ソウ、ショウ","kun":"あい","explanation":["相 = 木 + 目。","「木」는 “나무”를 뜻합니다.","「目」는 “눈”을 뜻합니다.","相는 “나무(木)를 바라보는 눈(目)”이라는 뜻입니다.","“바라보다” -> “서로 바라보다” -> “서로, 모양”이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/298/"},"定":{"id":291,"char":"定","hun":"정할 정","meaning":"“정할 정”. 정하다, 결정하다","on":"テイ、ジョウ","kun":"さだ(める)、さだ(まる)、さだ(か)","explanation":["定 = 宀 + 𤴓。","「宀」는 “집”을 뜻합니다.","𤴓는 「正」가 살짝 변형된 것으로, “바르다”라는 뜻입니다.","定는 “올바른(正) 집(宀)을 고르다” -> “정하다, 결정하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/299/"},"選":{"id":292,"char":"選","hun":"고를 선","meaning":"“고를 선”. 고르다, 선택하다","on":"セン","kun":"えら(ぶ)","explanation":["選 = ⻌ + 己 + 己 + 共。","「⻌」는 “길”을 뜻합니다.","「己」는 “무릎꿇은 사람”을 뜻합니다.","共는 여기서는 “가마”를 그린 모양자입니다.","選는 “앉아있는 사람들(己己) 중에서 가마(共)에 태워 보낼(⻌) 자를 고르다” -> “고르다, 선택하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/300/"},"米":{"id":293,"char":"米","hun":"쌀 미","meaning":"“쌀 미”. 쌀","on":"ベイ、マイ","kun":"こめ","explanation":["米는 “곡식 낟알이 흩어져있는 모습”을 그린 상형문자입니다."],"sourceUrl":"https://nihongokanji.com/301/"},"実":{"id":294,"char":"実","hun":"열매 실","meaning":"“열매 실”. 현실, 진실, 열매, 결실","on":"ジツ","kun":"み、みの(る)","explanation":["実 = 宀 + 大 + 二。","「宀」는 “집”을 뜻합니다.","「大」는 “크다”라는 뜻입니다.","「二」는 “2”를 뜻합니다.","実는 “집(宀) 안의 나무에 열린 커다란(大) 열매 두 개(二)” -> “열매” -> “결실, 진실, 현실”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/302/"},"関":{"id":295,"char":"関","hun":"관계할 관","meaning":"“관계할 관”. 관계되다, 관문","on":"カン","kun":"せき、かか(わる)","explanation":["関 = 門 + 关。","「門」는 “문”을 뜻합니다.","「关」는 “웃음”을 뜻합니다.","関는 “관계가 있는 사람만 웃으며(关) 관문(門) 안으로 들여보내다” -> “관문, 관계되다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/303/"},"決":{"id":296,"char":"決","hun":"결단할 결","meaning":"“결단할 결”. 결정하다, 결단하다","on":"ケツ","kun":"き(める)、き(まる)","explanation":["決 = 氵 + 夬。","「氵」는 “물”을 뜻합니다.","夬는 여기서는 “활(𠃍)을 쏘는 사람(大)”을 그린 모양자입니다.","決는 “강(氵)을 뒤로 한 채 배수진을 치고 싸우다(夬)”라는 뜻입니다.","“결단을 내리고 죽을 각오로 맞서 싸우다” -> “결정하다, 결단하다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/304/"},"全":{"id":297,"char":"全","hun":"온전할 전","meaning":"“온전할 전”. 모두, 전부, 전체","on":"ゼン","kun":"まった(く)、すべ(て)","explanation":["全 = 𠆢 + 王。","𠆢는 여기서는 “궁궐 지붕”을 그린 모양자입니다.","王(“임금 왕”)은 “왕”을 뜻하는 상용한자입니다.","全는 “궁궐(𠆢) 안의 왕(王)”이라는 뜻입니다.","“나라 전체를 지배하는 왕” -> “전체, 모두, 전부”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/305/"},"表":{"id":298,"char":"表","hun":"겉 표","meaning":"“겉 표”. 표면, 드러내다","on":"ヒョウ","kun":"おもて、あらわ(す)、あらわ(れる)","explanation":["表 = 主 + 衣。","「主」는 “주인”을 뜻합니다.","「衣」는 “옷”을 뜻하는 부수입니다(링크 참조).","表는 “주인(主)의 지위를 겉으로 드러내주는 의복(衣)” -> “표면, 드러내다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/306/"},"戦":{"id":299,"char":"戦","hun":"싸울 전","meaning":"“싸울 전”. 전투, 전쟁, 싸움","on":"セン","kun":"いくさ、たたか(う)","explanation":["戦 = 単 + 戈。","単는 “고대에 쓰던 무기”를 그린 상형문자입니다(아래 그림 참조).","「戈」는 “창”을 뜻하는 부수입니다(링크 참조).","戦는 “무기(単) + 창(戈)” -> “전쟁, 전투”라는 뜻의 글자입니다.","참고)","単는 상용한자이기도 합니다(463.「単」참조)."],"sourceUrl":"https://nihongokanji.com/307/"},"最":{"id":300,"char":"最","hun":"가장 최","meaning":"“가장 최”. 최고, 제일","on":"サイ","kun":"もっと(も)","explanation":["最 = 日 + 耳 + 又。","「日」는 “해”를 뜻합니다.","「耳」는 “귀”를 뜻합니다.","「又」는 “손”을 뜻합니다.","먼 옛날 전쟁에서는 죽인 적병의 귀(耳)를 잘라 모아오는(又) 풍습이 있었다고 합니다.","最는 “낮(日)의 전투에서 누가 가장 많은 귀(耳)를 잘라왔나(又) 비교하다” -> “최고, 제일”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/308/"},"調":{"id":301,"char":"調","hun":"조절할 조","meaning":"“조절할 조”. 조화, 조절하다, 조사하다, 운율","on":"チョウ","kun":"しら(べる)、ととの(う)、ととの(える)","explanation":["調 = 言 + 周。","「言」는 “말하다”라는 뜻입니다.","周(“두루 주”)는 “둘레, 돌다”라는 뜻의 상용한자입니다.","調는 “주위를 두루 돌며(周) 의견을 나누다(言)” -> “조사하다, 조절하다, 조화”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/309/"},"化":{"id":302,"char":"化","hun":"될 화","meaning":"“될 화”. 바뀌다, 변하다","on":"カ、ケ","kun":"ば(ける)、ば(かす)","explanation":["化 = 亻 + 匕。","「亻」는 “사람”을 뜻합니다.","「匕」는 “넘어져있는 사람”을 뜻하는 부수입니다.","化는 “서있던 사람(亻)이 넘어지다(匕)” -> “바뀌다, 변하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/310/"},"当":{"id":303,"char":"当","hun":"마땅할 당","meaning":"“마땅할 당”. 맞다, 맞히다, 들어맞다","on":"トウ","kun":"あ(たる)、あ(てる)","explanation":["当 = ⺌ + ⺕。","⺌는 여기서는 “화살촉”을 그린 모양자입니다.","「⺕」는 “손”을 뜻합니다.","当는 “손(⺕)에 화살(⺌)을 맞다” -> “맞다, 맞히다, 들어맞다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/311/"},"約":{"id":304,"char":"約","hun":"맺을 약","meaning":"“맺을 약”. 약속하다","on":"ヤク","kun":"","explanation":["約 = 糸 + 勺。","「糸」는 “실”을 뜻합니다.","勺은 여기서는 “(실의) 매듭”을 그린 모양자입니다.","約는 “실(糸)의 매듭(勺)을 묶다” -> “맺다, 약속하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/312/"},"法":{"id":305,"char":"法","hun":"법 법","meaning":"“법 법”. 법률, 법규, 방법","on":"ホウ、ハッ、ホッ","kun":"","explanation":["法 = 氵 + 去。","「氵」는 “물”을 뜻합니다.","「去」는 “지나가다”라는 뜻입니다.","法는 “물(氵)은 위에서 아래로 흘러가는(去) 법이다” -> “규칙, 법률, 법규”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/313/"},"的":{"id":306,"char":"的","hun":"과녁 적","meaning":"“과녁 적”. 표적, 과녁, ~적(경향/성질/상태를 나타내는 어미)","on":"テキ","kun":"まと","explanation":["的 = 白 + 勺。","「白」는 “흰색”을 뜻합니다.","勺는 여기서는 “과녁(勹) 중간에 적중한 화살(丶)”을 그린 모양자입니다.","的는 “흰색(白)으로 표시된 과녁(勹)에 적중한 화살(丶)” -> “표적, 과녁”이라는 뜻의 글자입니다.","(的가 어쩌다 접미사로 쓰이게 되었는지는 알려진 바가 없습니다.)"],"sourceUrl":"https://nihongokanji.com/314/"},"要":{"id":307,"char":"要","hun":"요긴할 요","meaning":"“요긴할 요”. 중요하다, 요긴하다","on":"ヨウ","kun":"かなめ、い(る)","explanation":["要는 “여자(女)가 허리에 손을 올린 모습”을 그린 상형문자입니다.","“허리는 중요한 부위” -> “중요하다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/315/"},"治":{"id":308,"char":"治","hun":"다스릴 치","meaning":"“다스릴 치”. 다스리다, 치료하다","on":"ジ、チ","kun":"おさ(める)、おさ(まる)、なお(る)、なお(す)","explanation":["治 = 氵 + 台。","「氵」는 “물”을 뜻합니다.","「台」는 “받침대”를 뜻합니다.","治는 “쟁반(台)에 올려둔 탕약(氵)”이라는 뜻입니다.","“탕약으로 병을 다스리다” -> “다스리다, 치료하다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/316/"},"成":{"id":309,"char":"成","hun":"이룰 성","meaning":"“이룰 성”. 이루다, 성취하다","on":"セイ、ジョウ","kun":"な(る)、な(す)","explanation":["成 = 戊 + 𠃌。","「戊」는 “창”을 뜻합니다(링크 참조).","𠃌는 여기서는 「丁」가 변형된 것으로, “못”을 뜻합니다.","成는 “전쟁(戊)의 승리에 못(𠃌)을 박다” -> “이루다, 성취하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/317/"},"期":{"id":310,"char":"期","hun":"기약할 기","meaning":"“기약할 기”. 시기, 때","on":"キ、ゴ","kun":"","explanation":["期 = 其 + 月。","(소리부) 「其」(キ)는 소리부의 역할만 하는 글자입니다(링크 참조).","(의미부) 「月」는 “달”을 뜻합니다.","期는 “달(月)이 뜨고 지는 주기” -> “시기, 때”라는 뜻의 글자입니다(其는 소리부)."],"sourceUrl":"https://nihongokanji.com/318/"},"公":{"id":311,"char":"公","hun":"공평할 공","meaning":"“공평할 공”. 공평한, 공적인","on":"コウ","kun":"おおやけ","explanation":["公 = ハ + 厶。","ハ는 여기서는 “정확히 반으로 나눈 모습”을 그린 모양자입니다.","「厶」는 “사사로운, 개인적인”이라는 뜻입니다.","公는 “사적인(厶) 치우침 없이 공평하게 나누다(ハ)” -> “공적인, 공평한”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/319/"},"協":{"id":312,"char":"協","hun":"화합할 협","meaning":"“화합할 협”. 협력하다","on":"キョウ","kun":"","explanation":["協 = 十 + 力 + 力 + 力。","「十」는 “10”을 뜻합니다.","「力」는 “힘”을 뜻합니다.","協는 “열 명(十)이 힘을 합치다(力力力)” -> “협력하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/320/"},"取":{"id":313,"char":"取","hun":"가질 취","meaning":"“가질 취”. 손에 잡다, 취하다","on":"シュ","kun":"と(る)","explanation":["取 = 耳 + 又。","「耳」는 “귀”를 뜻합니다.","「又」는 “손”을 뜻합니다.","먼 옛날 전쟁에서는 죽인 적병의 귀(耳)를 잘라 모아오는(又) 풍습이 있었다고 합니다.","取는 “귀(耳)를 줍다(又)” -> “집어들다, 취하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/321/"},"和":{"id":314,"char":"和","hun":"화할 화","meaning":"“화할 화”. 온화, 화목, 조화, 일본","on":"ワ、オ","kun":"やわ(らぐ)、やわ(らげる)、なご(む)、なご(やか)","explanation":["和 = 禾 + 口。","「禾」는 “곡식”을 뜻합니다.","「口」는 “입”을 뜻합니다.","和는 “곡식(禾)을 배불리 먹고(口) 마음이 온화해지다” -> “온화, 화목, 조화”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/322/"},"機":{"id":315,"char":"機","hun":"틀 기","meaning":"“틀 기”. 기계, 기회, 베틀","on":"キ","kun":"はた","explanation":["機 = 木 + 幺 + 幺 + 戈 + 人。","「木」는 “나무”를 뜻합니다.","「幺」는 “짧은 실”을 뜻합니다(링크 참조).","「人」는 “사람”을 뜻합니다.","戈는 여기서는 “베틀”을 그린 모양자로 쓰인 것입니다.","機는 “나무(木)로 만든 베틀(戈)에 앉아 실(幺幺)을 짜는 사람(人)”을 그린 글자입니다.","“베를 짜는 기계” -> “기계”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/323/"},"平":{"id":316,"char":"平","hun":"평평할 평","meaning":"“평평할 평”. 평평하다","on":"ヘイ、ビョウ","kun":"たい(ら)、ひら","explanation":["平는 “악기 소리가 고르게 퍼져나가는 모습”을 묘사한 상형문자입니다.","“소리가 고르게 퍼지다” -> “평평하다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/324/"},"加":{"id":317,"char":"加","hun":"더할 가","meaning":"“더할 가”. 더하다","on":"カ","kun":"くわ(える)、くわ(わる)","explanation":["加 = 力 + 口。","「力」는 “힘”을 뜻합니다.","「口」는 “입”을 뜻합니다.","加는 “강한 무력(力)에 말솜씨(口)까지 더해지다” -> “더하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/325/"},"受":{"id":318,"char":"受","hun":"받을 수","meaning":"“받을 수”. 받다, 받아들이다","on":"ジュ","kun":"う(ける)、う(かる)","explanation":["受 = ⺤ + 冖 + 又。","「⺤」는 “손”을 뜻하는 부수입니다(링크 참조).","冖는 여기서는 “책상”을 그린 모양자입니다.","「又」는 “손”을 뜻합니다.","受는 “책상(冖)을 사이에 두고 물건을 주고받다(⺤+又)” -> “받다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/326/"},"続":{"id":319,"char":"続","hun":"계속 속","meaning":"“계속 속”. 계속하다, 이어지다","on":"ゾク","kun":"つづ(く)、つづ(ける)","explanation":["続 = 糸 + 売。","「糸」는 “실”을 뜻합니다.","「売」는 “팔다”라는 뜻입니다.","続는 “장사(売)를 계속 이어가다(糸)” -> “계속하다, 이어지다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/327/"},"改":{"id":320,"char":"改","hun":"고칠 개","meaning":"“고칠 개”. 개선하다, 고치다","on":"カイ","kun":"あらた(める)、あらた(まる)","explanation":["改 = 己 + 攵。","「己」는 “무릎꿇은 사람”을 뜻합니다.","「攵」는 “때리다, 치다”라는 뜻입니다.","改는 “잘못을 저질러 무릎꿇은 아이(己)를 체벌(攵)로 훈육하다” -> “개선하다, 고치다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/328/"},"数":{"id":321,"char":"数","hun":"셀 수","meaning":"“셀 수”. 수, 숫자, 셈하다","on":"スウ、ス","kun":"かず、かぞ(える)","explanation":["数 = 娄 + 攵。","「娄」는 “쌓다, 겹치다”라는 뜻의 글자입니다(링크 참조).","「攵」는 본래 “막대기(丿)를 든 손(又)”을 그린 글자입니다(링크 참조).","먼 옛날에는 “산가지”라는 막대기를 겹쳐서 계산을 했다고 합니다.","数는 “막대기(攵)를 겹쳐서(娄) 셈을 하다” -> “셈, 수”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/329/"},"記":{"id":322,"char":"記","hun":"기록할 기","meaning":"“기록할 기”. 기록, 기억","on":"キ","kun":"しる(す)","explanation":["記 = 言 + 己。","「言」는 “말하다”라는 뜻입니다.","「己」는 “무릎꿇은 사람”을 뜻합니다.","記는 “무릎꿇은 사관(己)이 왕의 말씀(言)을 받아적다” -> “기록하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/330/"},"初":{"id":323,"char":"初","hun":"처음 초","meaning":"“처음 초”. 처음, 시초","on":"ショ","kun":"はじ(め)、はじ(めて)、はつ、うい、そ(める)","explanation":["初 = 衤 + 刀。","「衤」는 “옷, 옷감”을 뜻합니다.","「刀」는 “칼”을 뜻합니다.","옷을 만들 때 가장 먼저 해야 하는 일은 옷감을 재단하는 것입니다.","初는 “옷감(衤)의 재단(刀)” -> “처음, 시초”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/331/"},"指":{"id":324,"char":"指","hun":"가리킬 지","meaning":"“가리킬 지”. 손가락, 가리키다","on":"シ","kun":"ゆび、さ(す)","explanation":["指 = 扌 + 匕 + 日。","「扌」는 “손”을 뜻합니다.","匕는 여기서는 「刀」가 뒤집힌 것으로, “칼”을 뜻합니다.","「日」는 “태양”을 뜻합니다.","指는 “칼(匕)을 들어(扌) 태양(日)을 가리키다” -> “가리키다” -> “손가락”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/332/"},"第":{"id":325,"char":"第","hun":"차례 제","meaning":"“차례 제”. 순서를 나타내는 접두사","on":"ダイ","kun":"","explanation":["第 = 𥫗 + 弟。","(의미부) 「𥫗」는 “대나무”를 뜻합니다.","(소리부 겸 의미부) 「弟」(ダイ)는 본래 “나뭇단을 밧줄로 엮어놓은 모습”을 그린 글자입니다(링크 참조).","第는 “대나무(𥫗)를 차곡차곡 묶어서(弟) 순서대로 쌓아놓다” -> “차례, 순서”라는 뜻의 글자입니다.","(弟는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/333/"},"結":{"id":326,"char":"結","hun":"맺을 결","meaning":"“맺을 결”. 맺다, 묶다, 결실","on":"ケツ","kun":"むす(ぶ)、ゆ(う)、ゆ(わえる)","explanation":["結 = 糸 + 士 + 口。","「糸」는 “실”을 뜻합니다.","士(“선비 사”)는 “선비, 무사”를 뜻하는 상용한자입니다.","「口」는 “입”을 뜻합니다.","結는 “선비(士)는 자신이 말한(口) 일은 반드시 매듭을(糸) 짓는다” -> “맺다, 묶다, 결실”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/334/"},"点":{"id":327,"char":"点","hun":"점 점","meaning":"“점 점”. 점","on":"テン","kun":"","explanation":["点 = 占 + 灬。","(의미부) 灬는 여기서는 단순히 “점 네 개”를 그린 모양자로 쓰인 것입니다.","(소리부) 占는 여기서는 「店」(テン)이 축약된 것으로, 소리부의 역할만 하고 있습니다.","点는 “점 네 개(灬)” -> “점”이라는 뜻의 글자입니다(占 -> 店은 소리부)."],"sourceUrl":"https://nihongokanji.com/335/"},"府":{"id":328,"char":"府","hun":"마을 부","meaning":"“마을 부”. 관청, 일본의 행정 구역 단위","on":"フ","kun":"","explanation":["府 = 广 + 亻 + 寸。","「广」는 “건물”을 뜻합니다.","「亻」는 “사람”을 뜻합니다.","「寸」는 “손”을 뜻합니다.","府는 “관청(广)에서 손(寸)으로 지시를 내리는 관리(亻)” -> “관청”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/336/"},"活":{"id":329,"char":"活","hun":"살 활","meaning":"“살 활”. 활력, 생기, 활동","on":"カツ","kun":"","explanation":["活 = 氵 + 舌。","「氵」는 “물”을 뜻합니다.","「舌」는 “혀”를 뜻합니다.","活는 “혀(舌)에 물(氵)을 대다” -> “물을 마시다” -> “활력, 생기”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/337/"},"原":{"id":330,"char":"原","hun":"근원 원","meaning":"“근원 원”. 근원, 들판","on":"ゲン","kun":"はら","explanation":["原 = 厂 + 白 + 小。","「厂」는 “기슭, 절벽”을 뜻합니다.","「白」는 “흰색”을 뜻합니다.","小는 여기서는 “물이 흘러내리는 모습”을 그린 모양자입니다.","原는 “깨끗한(白) 물(小)이 흘러내리는 절벽(厂)위의 수원지” -> “근원”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/338/"},"共":{"id":331,"char":"共","hun":"한가지 공","meaning":"“한가지 공”. 함께, 같이","on":"キョウ","kun":"とも","explanation":["共 = 龷 + ハ。","龷는 여기서는 “쟁반”을 그린 모양자입니다.","ハ는 여기서는 “(쟁반을 받쳐든) 두 손”을 그린 모양자입니다.","共는 “커다란 쟁반(龷)을 두 손(ハ)으로 함께 들다” -> “함께, 같이”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/339/"},"得":{"id":332,"char":"得","hun":"얻을 득","meaning":"“얻을 득”. 얻다, 획득하다","on":"トク","kun":"え(る)、う(る)","explanation":["得 = 彳 + 旦 + 寸。","「彳」는 “길”을 뜻합니다.","旦는 여기서는 「貝」가 축약된 것으로, “돈”을 뜻합니다.","「寸」는 “손”을 뜻합니다.","得는 “길(彳)에서 돈(貝)을 줍다(寸)” -> “얻다, 획득하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/340/"},"交":{"id":333,"char":"交","hun":"사귈 교","meaning":"“사귈 교”. 교차하다, 교제하다, 바뀌다","on":"コウ","kun":"まじ(わる)、まじ(える)、ま(じる)、ま(ざる)、ま(ぜる)、か(う)、か(わす)","explanation":["交는 “다리를 꼬고 앉은 사람”을 그린 상형문자입니다.","“다리를 교차시키다” -> “교차하다, 교제하다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/341/"},"予":{"id":334,"char":"予","hun":"미리 예","meaning":"“미리 예”. 미리, 사전에","on":"ヨ","kun":"","explanation":["予 = マ + 丁。","マ는 여기서는 “망치”를 그린 모양자입니다.","「丁」는 “못”을 뜻합니다.","予는 “(다른 말이 나오지 않도록) 사전에 미리 못(丁)을 박아놓다(マ)” -> “미리, 사전에”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/342/"},"向":{"id":335,"char":"向","hun":"향할 향","meaning":"“향할 향”. 향하다","on":"コウ","kun":"む(く)、む(ける)、む(かう)、む(こう)","explanation":["向는 “창문이 남쪽에 달린 집”을 그린 상형문자입니다.","“창문이 남쪽에 달린 집” -> “남향” -> “향하다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/343/"},"勝":{"id":336,"char":"勝","hun":"이길 승","meaning":"“이길 승”. 이기다, 우수하다","on":"ショウ","kun":"か(つ)、まさ(る)","explanation":["勝 = 月 + 龹 + 力。","「月」는 “고기”를 뜻합니다.","龹는 여기서는 「关」가 변형된 것으로, “웃음”을 뜻합니다.","「力」는 “힘”을 뜻합니다.","勝는 “전쟁에서 승리하고(力) 모두 함께 웃으며(关) 만찬(月)을 열다” -> “이기다, 우수하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/344/"},"面":{"id":337,"char":"面","hun":"낯 면","meaning":"“낯 면”. 얼굴, 표면","on":"メン","kun":"おも、おもて、つら","explanation":["面 = 丆 + 口 + 目。","丆는 여기서는 “머리카락”을 그린 모양자입니다.","口는 여기서는 “얼굴”을 그린 모양자입니다.","「目」는 “눈”을 뜻합니다.","面는 “머리카락(丆) + 얼굴(口) + 눈(目)” -> “얼굴, 표면”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/345/"},"委":{"id":338,"char":"委","hun":"맡길 위","meaning":"“맡길 위”. 맡기다, 위임하다","on":"イ","kun":"ゆだ(ねる)","explanation":["委 = 禾 + 女。","「禾」는 “곡식”을 뜻합니다.","「女」는 “여자”를 뜻합니다.","委는 “수확한 곡식(禾)을 여자들(女)에게 맡기다” -> “맡기다, 위임하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/346/"},"告":{"id":339,"char":"告","hun":"고할 고","meaning":"“고할 고”. 알리다, 보고하다","on":"コク","kun":"つ(げる)","explanation":["告 = 𠂒 + 口。","「𠂒」는 “소”를 뜻합니다.","「口」는 “입”을 뜻합니다.","告는 “제사에 소(𠂒)를 제물로 바치며 신에게 고하다(口)” -> “알리다, 보고하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/347/"},"軍":{"id":340,"char":"軍","hun":"군사 군","meaning":"“군사 군”. 군대","on":"グン","kun":"","explanation":["軍 = 冖 + 車。","「車」는 “수레, 차”를 뜻합니다.","冖는 여기서는 “수레 위에 실은 짐”을 표현한 모양자입니다.","軍는 “군량미(冖)를 수송하는 수레(車)” -> “군대”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/348/"},"反":{"id":341,"char":"反","hun":"돌이킬 반","meaning":"“돌이킬 반”. 돌이키다, 뒤집다, 반대, 반사","on":"ハン、ホン、タン","kun":"そ(る)、そ(らす)","explanation":["反 = 厂 + 又。","「厂」는 “기슭, 절벽”을 뜻합니다.","「又」는 “손”을 뜻합니다.","反는 “절벽(厂)을 기어오르는 손(又)” -> “거슬러 올라가다” -> “돌이키다, 뒤집다, 반대”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/349/"},"参":{"id":342,"char":"参","hun":"참여할 참","meaning":"“참여할 참”. 참여, 참석, 참관","on":"サン","kun":"まい(る)","explanation":["参 = ム + 大 + 彡。","参는 본래 “하늘의 별자리를 관찰하는 사람”을 그린 상형문자입니다.","ム는 “별자리”, 大는 “사람”, 彡는 “별빛”을 각각 표현한 모양자로 쓰인 것입니다.","“별들이 모여 별자리를 이루다” -> “모임” -> “참여, 참관, 참석”이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/350/"},"利":{"id":343,"char":"利","hun":"이로울 리","meaning":"“이로울 리”. 이득, 이롭다, 쓸모있는","on":"リ","kun":"き(く)","explanation":["利 = 禾 + 刂。","「禾」는 “곡식”을 뜻합니다.","「刂」는 “칼”을 뜻합니다.","利는 “벼(禾)를 베고(刂) 수확하다” -> “이득, 이롭다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/351/"},"組":{"id":344,"char":"組","hun":"짤 조","meaning":"“짤 조”. 조직, 조직하다","on":"ソ","kun":"く(む)、くみ","explanation":["組 = 糸 + 且。","(의미부) 「糸」는 “실”을 뜻합니다.","(소리부 겸 의미부) 「且」(ソ)는 “비석, 조상”을 뜻하는 글자입니다(링크 참조).","組는 “제사(且)를 지내기 위한 상복을 짜다(糸)” -> “짜다, 조직하다”라는 뜻의 글자입니다.","(且는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/352/"},"案":{"id":345,"char":"案","hun":"책상 안","meaning":"“책상 안”. 제안, 계획, 초안, 생각","on":"アン","kun":"","explanation":["案 = 安 + 木。","(소리부 겸 의미부) 「安」(アン)은 본래 “집 안에 앉아있는 여자”를 그린 글자입니다(링크 참조).","(의미부) 「木」는 “나무”를 뜻합니다.","案는 “나무 책상(木) 앞에 앉아서(安) 생각하다” -> “제안, 계획, 생각”이라는 뜻의 글자입니다.","(安는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/353/"},"信":{"id":346,"char":"信","hun":"믿을 신","meaning":"“믿을 신”. 믿다","on":"シン","kun":"","explanation":["信 = 亻 + 言。","「亻」는 “사람”을 뜻합니다.","「言」는 “말하다”라는 뜻입니다.","信는 “타인(亻)의 말(言)을 믿다” -> “믿다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/354/"},"側":{"id":347,"char":"側","hun":"곁 측","meaning":"“곁 측”. 옆, 측면","on":"ソク","kun":"がわ","explanation":["側 = 亻 + 貝 + 刂。","「亻」는 “사람”을 뜻합니다.","「貝」는 “돈, 재물”을 뜻합니다.","「刂」는 “칼”을 뜻합니다.","側는 “돈(貝)과 힘(刂)을 가진 권력자 옆에서 알랑거리는 사람(亻)“ -> “옆, 측면”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/355/"},"求":{"id":348,"char":"求","hun":"구할 구","meaning":"“구할 구”. 바라다, 구하다","on":"キュウ","kun":"もと(める)","explanation":["求는 “귀한 털가죽 옷을 껴입은 사람”을 그린 상형문자입니다.","“추위를 이겨낼 비싸고 귀한 털가죽 옷을 구하다” -> “바라다, 구하다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/356/"},"次":{"id":349,"char":"次","hun":"버금 차","meaning":"“버금 차”. 다음, 두 번째","on":"ジ、シ","kun":"つ(ぐ)、つぎ","explanation":["次 = 冫 + 欠。","冫는 여기서는 「二」가 변형된 것으로, “2”를 뜻합니다.","「欠」는 “입으로 하는 동작”을 뜻합니다. 여기서는 “하품하다”라는 뜻입니다.","次는 “피곤하여 하품(欠)하며 다음(二)으로 미루다” -> “다음, 두 번째”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/357/"},"昨":{"id":350,"char":"昨","hun":"어제 작","meaning":"“어제 작”. 어제","on":"サク","kun":"","explanation":["昨 = 日 + 乍。","(의미부) 「日」는 “날짜”를 뜻합니다.","(소리부) 「乍」(サク)는 여기서는 소리부의 역할만 하고 있습니다.","昨는 “지나간 날짜(日)” -> “어제”라는 뜻의 글자입니다(乍는 소리부)."],"sourceUrl":"https://nihongokanji.com/358/"},"官":{"id":351,"char":"官","hun":"벼슬 관","meaning":"“벼슬 관”. 관청, 관직, 관리","on":"カン","kun":"","explanation":["官 = 宀 + 㠯。","「宀」는 “집”을 뜻합니다.","「㠯」는 “엉덩이”를 뜻합니다.","官는 “관청(宀)에만 앉아있는 엉덩이(㠯)가 무거운 정부 관료” -> “관청, 관직, 관리”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/359/"},"係":{"id":352,"char":"係","hun":"맬 계","meaning":"“맬 계”. 연결되다, 관계, 담당","on":"ケイ","kun":"かか(る)、かかり","explanation":["係 = 亻 + 一 + 糸。","「亻」는 “사람”을 뜻합니다.","「一」는 “하나”를 뜻합니다.","「糸」는 “실”을 뜻합니다.","係는 “하나(一)로 연결된(糸) 사람들(亻)” -> “연결, 관계”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/360/"},"感":{"id":353,"char":"感","hun":"느낄 감","meaning":"“느낄 감”. 느낌, 감각, 감정","on":"カン","kun":"","explanation":["感 = 戌 + 口 + 心。","「戌」는 “창을 든 손”을 뜻하는 글자입니다(링크 참조).","「口」는 “입”을 뜻합니다.","「心」는 “마음”을 뜻합니다.","感는 “창을 들고(戌) 함성을 지르며(口) 고양되는 감정(心)” -> “감정, 감각, 느낌”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/361/"},"投":{"id":354,"char":"投","hun":"던질 투","meaning":"“던질 투”. 던지다","on":"トウ","kun":"な(げる)","explanation":["投 = 扌 + 殳。","「扌」는 “손”을 뜻합니다.","「殳」는 “때리다, 휘두르다”라는 뜻의 부수입니다(링크 참조).","投는 “손(扌)을 휘둘러(殳) 물건을 던지다” -> “던지다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/362/"},"変":{"id":355,"char":"変","hun":"변할 변","meaning":"“변할 변”. 변하다, 변화하다","on":"ヘン","kun":"か(わる)、か(える)","explanation":["変 = 亦 + 夂。","「亦」는 “팔을 벌리고 걷는 사람”을 그린 글자입니다(링크 참조).","「夂」는 “발”을 뜻합니다.","変는 “팔을 벌리고(亦) 걷다(夂)” -> “이동하다” -> “변하다, 변화하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/363/"},"打":{"id":356,"char":"打","hun":"칠 타","meaning":"“칠 타”. 치다, 두드리다, 때리다","on":"ダ","kun":"う(つ)","explanation":["打 = 扌 + 丁。","「扌」는 “손”을 뜻합니다.","「丁」는 “못”을 뜻합니다.","打는 “손(扌)으로 못(丁)을 내리치다” -> “치다, 두드리다, 때리다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/364/"},"各":{"id":357,"char":"各","hun":"각각 각","meaning":"“각각 각”. 각자의, 각각","on":"カク","kun":"おのおの","explanation":["各 = 夂 + 口。","「夂」는 “발”을 뜻합니다.","口는 여기서는 “(집의) 출입문”을 그린 모양자입니다.","各는 “집(口)으로 돌아가는 발걸음(夂)”이라는 뜻입니다.","“각자의 집으로 돌아가다” -> “각각, 각자의”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/365/"},"島":{"id":358,"char":"島","hun":"섬 도","meaning":"“섬 도”. 섬","on":"トウ","kun":"しま","explanation":["島 = 鳥 + 山。","「鳥」는 “새”를 뜻합니다.","「山」는 “산”을 뜻합니다.","島는 “바다 한가운데의 섬(山)으로 날아가는 새(鳥)” -> “섬”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/366/"},"直":{"id":359,"char":"直","hun":"곧을 직","meaning":"“곧을 직”. 곧은, 직선의, 바로잡다","on":"チョク、ジキ","kun":"なお(す)、なお(る)、ただ(ちに)","explanation":["直 = 十 + 目 + 𠃊。","十는 여기서는 “눈썹”을 그린 모양자입니다.","「目」는 “눈”을 뜻합니다.","𠃊는 여기서는 “휘어진 물건”을 그린 모양자입니다.","直는 “눈을 찡그리고(十) 자세히 보며(目) 휘어진 부분(𠃊)을 바로잡다” -> “곧다, 직선, 바로잡다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/367/"},"両":{"id":360,"char":"両","hun":"두 량","meaning":"“두 량”. 양쪽, 한 쌍","on":"リョウ","kun":"","explanation":["両는 “두 필의 말이 끄는 마차”를 그린 상형문자입니다.","“말 한 쌍이 끄는 마차” -> “양쪽, 한 쌍”이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/368/"},"式":{"id":361,"char":"式","hun":"법 식","meaning":"“법 식”. 방식, 형식","on":"シキ","kun":"","explanation":["式 = 弋 + 工。","「弋」는 “공구, 도구”를 뜻합니다.","「工」는 “공작, 공정, 가공”을 뜻합니다.","式는 “목공용(工) 공구(弋)의 사용 방식” -> “방식, 형식”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/369/"},"果":{"id":362,"char":"果","hun":"실과 과","meaning":"“실과 과”. 열매, 결과, 결실","on":"カ","kun":"は(てる)、は(たす)、は(て)","explanation":["果 = 田 + 木。","「木」는 “나무”를 뜻합니다.","田는 여기서는 “나무열매”를 그린 모양자입니다.","果는 “열매(田)를 맺은 나무(木)” -> “열매, 결실, 결과”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/370/"},"必":{"id":363,"char":"必","hun":"반드시 필","meaning":"“반드시 필”. 반드시","on":"ヒツ","kun":"かなら(ず)","explanation":["必 = 心 + ノ。","「心」는 “마음”을 뜻합니다.","ノ는 여기서는 “칼로 새긴 자국”을 표현한 모양자입니다.","必는 “마음속(心) 깊이 새기다(ノ)” -> “반드시”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/371/"},"争":{"id":364,"char":"争","hun":"다툴 쟁","meaning":"“다툴 쟁”. 다투다, 경쟁하다","on":"ソウ","kun":"あらそ(う)","explanation":["争 = ⺈ + ⺕ + 亅。","「⺈」는 “칼”을 뜻합니다.","「⺕」는 “손”을 뜻합니다.","亅는 여기서는 “칼의 손잡이”를 그린 모양자입니다.","争는 “칼(⺈)을 손(⺕)에 들고(亅) 싸우다” -> “다투다, 경쟁하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/372/"},"談":{"id":365,"char":"談","hun":"말씀 담","meaning":"“말씀 담”. 이야기하다, 담화","on":"ダン","kun":"","explanation":["談 = 言 + 火 + 火。","「言」는 “말하다”라는 뜻입니다.","「火」는 “불”을 뜻합니다.","談는 “열정적으로(火火) 말하다(言)” -> “이야기하다, 담화”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/373/"},"無":{"id":366,"char":"無","hun":"없을 무","meaning":"“없을 무”. 없다, 무","on":"ム、ブ","kun":"な(い)","explanation":["無는 “기우제를 지내며 춤을 추는 무희”를 그린 상형문자입니다.","“기우제” -> “비가 오지 않는다” -> “없다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/374/"},"位":{"id":367,"char":"位","hun":"자리 위","meaning":"“자리 위”. 위치, 지위, 등급","on":"イ","kun":"くらい","explanation":["位 = 亻 + 立。","「亻」는 “사람”을 뜻합니다.","「立」는 “서다”라는 뜻입니다.","位는 “사람(亻)이 서 있는(立) 위치” -> “위치, 지위”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/375/"},"置":{"id":368,"char":"置","hun":"둘 치","meaning":"“둘 치”. 두다, 놓다, 배치하다","on":"チ","kun":"お(く)","explanation":["置 = 罒 + 直。","「罒」는 “그물”을 뜻합니다.","「直」는 “직선, 곧다”라는 뜻입니다.","置는 “사냥용 그물(罒)을 직선으로(直) 설치해 두다” -> “놓아두다, 두다, 놓다, 배치하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/376/"},"流":{"id":369,"char":"流","hun":"흐를 류","meaning":"“흐를 류”. 흐르다, 흐름","on":"リュウ、ル","kun":"なが(れる)、なが(す)","explanation":["流 = 氵 + 亠 + ム + 川。","「氵」는 “물”을 뜻합니다.","亠+ム는 「子」를 거꾸로 뒤집은 것으로, “거꾸로 뒤집힌 아이”를 뜻합니다.","「川」는 “강, 하천”을 뜻합니다.","流는 “아기(亠+ム)가 태어나며 양수(氵)가 흘러나오다(川)” -> “흐르다, 흐름”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/377/"},"局":{"id":370,"char":"局","hun":"판 국","meaning":"“판 국”. 국면, 판세, 부분","on":"キョク","kun":"","explanation":["局 = 尸 + 𠃌 + 口。","「尸」는 “앉아있는 사람”을 뜻합니다.","𠃌는 여기서는 “의자”를 그린 모양자입니다.","口는 여기서는 “장기판”을 그린 모양자입니다.","局는 “의자(𠃌)에 앉아(尸) 장기(口)를 두다” -> “장기” -> “판(대국), 국면, 부분, 판세”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/378/"},"放":{"id":371,"char":"放","hun":"놓을 방","meaning":"“놓을 방”. 내쫓다, 놓아주다, 방치하다","on":"ホウ","kun":"はな(す)、はな(つ)、はな(れる)、ほう(る)","explanation":["放 = 方 + 攵。","(소리부 겸 의미부) 「方」(ホウ)는 “방향”을 뜻합니다.","(의미부) 「攵」는 “때리다, 치다”라는 뜻입니다.","放는 “마구 때려서(攵) 반대 방향(方)으로 내쫓다” -> “내쫓다, 놓아주다, 방치하다”라는 뜻의 글자입니다.","(方는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/379/"},"球":{"id":372,"char":"球","hun":"공 구","meaning":"“공 구”. 공, 구체, 구슬","on":"キュウ","kun":"たま","explanation":["球 = 𤣩 + 求。","(의미부) 「𤣩」는 “구슬”을 뜻합니다.","(소리부) 「求」(キュウ)는 여기서는 소리부의 역할만 하고 있습니다.","球는 “구슬(𤣩)” -> “공, 구체”라는 뜻의 글자입니다(求는 소리부)."],"sourceUrl":"https://nihongokanji.com/380/"},"役":{"id":373,"char":"役","hun":"부릴 역","meaning":"“부릴 역”. 역할, 노역","on":"ヤク、エキ","kun":"","explanation":["役 = 彳 + 殳。","「彳」는 “길”을 뜻합니다.","「殳」는 “때리다, 휘두르다“라는 뜻입니다.","役는 “징병된 노예들을 채찍질하며(殳) 길(彳)을 인솔하다” -> “노역, 역할, 임무”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/381/"},"身":{"id":374,"char":"身","hun":"몸 신","meaning":"“몸 신”. 몸, 육체","on":"シン","kun":"み","explanation":["身는 “임신해서 배가 불러온 여자의 옆모습”을 그린 상형문자입니다.","“임신한 여자의 몸” -> “몸”이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/382/"},"費":{"id":375,"char":"費","hun":"쓸 비","meaning":"“쓸 비”. 쓰다, 소모하다","on":"ヒ","kun":"つい(やす)、つい(える)","explanation":["費 = 弗 + 貝。","弗는 여기서는 “장작을 밧줄로 묶어놓은 모습”을 그린 모양자입니다.","「貝」는 “돈, 재물”을 뜻합니다.","費는 “장작(弗)을 사기 위해 돈(貝)을 쓰다” -> “쓰다, 소모하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/383/"},"付":{"id":376,"char":"付","hun":"줄 부","meaning":"“줄 부”. 주다, 부치다, 붙이다, 첨부","on":"フ","kun":"つ(ける)、つ(く)","explanation":["付 = 亻 + 寸。","「亻」는 “사람”을 뜻합니다.","「寸」는 “손”을 뜻합니다.","付는 “사람(亻)에게 물건을 건네주다(寸)” -> “주다, 부치다, 붙이다, 첨부”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/384/"},"由":{"id":377,"char":"由","hun":"말미암을 유","meaning":"“말미암을 유”. 이유, 유래","on":"ユ、ユウ、ユイ","kun":"よし","explanation":["由는 “촛불”을 그린 상형문자입니다.","“이유를 밝히다(由)” -> “원인, 이유, 유래”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/385/"},"夫":{"id":378,"char":"夫","hun":"지아비 부","meaning":"“지아비 부”. 남편, 성인 남성","on":"フ、フウ","kun":"おっと","explanation":["夫 = 大 + 一。","「大」는 본래 “사람”을 그린 글자입니다(링크 참조).","「一」는 “1”을 뜻합니다.","夫는 “가정의 1인자(一)인 사람(大)” -> “남편, 성인 남성”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/386/"},"石":{"id":379,"char":"石","hun":"돌 석","meaning":"“돌 석”. 돌","on":"セキ、シャク、コク","kun":"いし","explanation":["石는 “절벽에서 굴러 떨어지는 돌”을 그린 상형문자입니다."],"sourceUrl":"https://nihongokanji.com/387/"},"消":{"id":380,"char":"消","hun":"사라질 소","meaning":"“사라질 소”. 사라지다","on":"ショウ","kun":"き(える)、け(す)","explanation":["消 = 氵 + ⺌ + 月。","「氵」는 “물”을 뜻합니다.","「月」는 “신체의 일부”를 뜻합니다(링크 참조).","⺌는 여기서는 “땀이 나는 모습”을 그린 모양자입니다.","消는 “몸(月)에서 난(⺌) 땀방울(氵)이 말라서 사라지다” -> “사라지다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/388/"},"神":{"id":381,"char":"神","hun":"귀신 신","meaning":"“귀신 신”. 신, 정신","on":"シン、ジン","kun":"かみ、かん、こう","explanation":["神 = 礻 + 申。","「礻」는 “종교, 신, 고대의 비석”을 뜻합니다.","「申」는 “번개”를 뜻합니다.","神는 “신(礻)이 내리는 번개(申)” -> “신”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/389/"},"番":{"id":382,"char":"番","hun":"차례 번","meaning":"“차례 번”. 차례","on":"バン","kun":"","explanation":["番 = 釆 + 田。","釆는 여기서는 「来」가 변형된 것으로, “동물의 발자국”을 그린 것입니다(링크 참조).","「田」는 “밭”을 뜻합니다.","番는 “밭(田)에 찍혀있는 동물의 발자국(釆)“이라는 뜻입니다.","“밭에 차례대로 찍혀있는 발자국” -> “차례”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/390/"},"害":{"id":383,"char":"害","hun":"해할 해","meaning":"“해할 해”. 해치다, 해로운","on":"ガイ","kun":"","explanation":["害 = 宀 + 龶 + 口。","「宀」는 “집”을 뜻합니다.","龶는 여기서는 “날카로운 흉기”를 그린 모양자입니다.","「口」는 “입”을 뜻합니다.","害는 “집(宀)에서 말다툼(口)으로 흉기(龶)를 휘두르다” -> “해치다, 해로운”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/391/"},"配":{"id":384,"char":"配","hun":"나눌/짝 배","meaning":"“나눌/짝 배”. 부부, 짝짓다, 예속하다, 나누다, 배부하다","on":"ハイ","kun":"くば(る)","explanation":["配 = 酉 + 己。","「酉」는 “술병, 술”을 뜻하는 부수입니다(링크 참조).","「己」는 “무릎꿇은 사람”을 뜻합니다.","配는 “남편의 옆에서 공손히 무릎꿇고(己) 술을(酉) 따르는 아내”라는 뜻입니다.","“공손히 남편의 술시중을 드는 아내” -> “부부, 짝짓다, 예속하다” (배우자, 교배, 지배)","“술을 따르다” -> “나누다” (분배)","라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/392/"},"副":{"id":385,"char":"副","hun":"버금 부","meaning":"“버금 부”. 버금, 둘째","on":"フク","kun":"","explanation":["副 = 畐 + 刂。","(소리부 겸 의미부) 「畐」(フク)는 “가득 찬 항아리”를 그린 글자입니다(링크 참조).","(의미부) 「刂」는 “칼”을 뜻합니다.","副는 “안이 가득 찬 항아리(畐)를 둘로 쪼개다(刂)” -> “둘째, 버금”이라는 뜻의 글자입니다.","(畐는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/393/"},"算":{"id":386,"char":"算","hun":"셈 산","meaning":"“셈 산”. 계산하다","on":"サン","kun":"","explanation":["算 = 𥫗 + 目 + 廾。","「𥫗」는 “대나무”를 뜻합니다.","「目」는 “눈”을 뜻합니다.","廾는 여기서는 “막대기를 늘어놓은 모습”을 그린 모양자입니다.","먼 옛날에는 “산가지”라는 막대기를 써서 계산을 했다고 합니다.","算는 “대나무 막대(𥫗)를 늘어놓고(廾) 그것을 보며(目) 계산하다” -> “계산하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/394/"},"育":{"id":387,"char":"育","hun":"기를 육","meaning":"“기를 육”. 기르다, 양육하다","on":"イク","kun":"そだ(つ)、そだ(てる)、はぐく(む)","explanation":["育 = 亠 + ム + 月。","亠+ム는 「子」를 거꾸로 뒤집은 것으로, “아이”를 뜻합니다.","「月」는 “고기”를 뜻합니다.","育는 “아이(亠+ム)에게 고기(月)를 먹여 키우다” -> “기르다, 양육하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/395/"},"席":{"id":388,"char":"席","hun":"자리 석","meaning":"“자리 석”. 좌석","on":"セキ","kun":"","explanation":["席 = 广 + 廿 + 巾。","「广」는 “건물, 집”을 뜻합니다.","廿는 여기서는 “책상”을 그린 모양자입니다.","「巾」는 “수건, 천”을 뜻합니다.","席는 “집(广) 안의 책상(廿) 앞에 깔아둔 방석(巾)” -> “좌석”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/396/"},"残":{"id":389,"char":"残","hun":"잔인할/남을 잔","meaning":"“잔인할/남을 잔”. 잔혹하다, 남기다","on":"ザン","kun":"のこ(る)、のこ(す)","explanation":["残 = 歹 + 㦮。","「歹」는 “시체”를 뜻합니다.","「㦮」는 “피와 살점이 묻은 창(戈)”을 뜻하는 글자입니다(링크 참조).","残는 “시체(歹)의 피와 살점이 남아있는 창(㦮)” -> “남다, 잔혹하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/397/"},"想":{"id":390,"char":"想","hun":"생각 상","meaning":"“생각 상”. 생각, 상상, 구상","on":"ソウ、ソ","kun":"","explanation":["想 = 相 + 心。","(소리부 겸 의미부) 「相」(ソウ)는 “서로”라는 뜻입니다.","(의미부) 「心」는 “마음”을 뜻합니다.","想는 “연인이 서로(相)를 생각하는 마음(心)” -> “생각하다”라는 뜻의 글자입니다.","(相는 소리부(ソウ -> ソウ・ソ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/398/"},"線":{"id":391,"char":"線","hun":"줄 선","meaning":"“줄 선”. 선","on":"セン","kun":"","explanation":["線 = 糸 + 泉。","(의미부) 「糸」는 “실”을 뜻합니다.","(소리부 겸 의미부) 泉(セン – “샘 천”)은 “샘, 샘물”을 뜻하는 상용한자입니다.","線는 “가느다란 실(糸)처럼 흐르는 물줄기(泉)” -> “선”이라는 뜻의 글자입니다.","(泉는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/399/"},"農":{"id":392,"char":"農","hun":"농사 농","meaning":"“농사 농”. 농사, 농업","on":"ノウ","kun":"","explanation":["農 = 曲 + 辰。","曲는 여기서는 「田」가 잘못 변형된 것으로, “밭”을 뜻합니다.","「辰」는 “쟁기, 농기구”를 뜻하는 부수입니다(링크 참조).","農는 “밭(曲)에서 쟁기(辰)를 휘두르다” -> “농사”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/400/"},"州":{"id":393,"char":"州","hun":"고을 주","meaning":"“고을 주”. 주, 지방, 행정 구획","on":"シュウ","kun":"す","explanation":["州는 “모래톱이 쌓인 강(川)”을 그린 상형문자입니다.","모래톱이나 삼각주는 물살이 완만한 하천에 쌓입니다.","고대의 인류는 그런 장소들을 중심으로 모여 살았습니다.","“물살이 완만한 하천” -> “고을” -> “주, 지방, 행정 구획”이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/401/"},"念":{"id":394,"char":"念","hun":"생각 념","meaning":"“생각 념”. 생각, 사념","on":"ネン","kun":"","explanation":["念 = 今 + 心。","「今」는 “지금”을 뜻합니다.","「心」는 “마음”을 뜻합니다.","念은 “지금(今) 마음속에(心) 있는 생각” -> “생각, 사념”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/402/"},"象":{"id":395,"char":"象","hun":"코끼리 상","meaning":"“코끼리 상”. 코끼리, 형상, 심상","on":"ショウ、ゾウ","kun":"","explanation":["象는 “코끼리”를 그린 상형문자입니다.","“코끼리의 생김새” -> “코끼리, 형상, 심상”이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/403/"},"助":{"id":396,"char":"助","hun":"도울 조","meaning":"“도울 조”. 돕다","on":"ジョ","kun":"たす(ける)、たす(かる)、すけ","explanation":["助 = 且 + 力。","「且」는 “비석, 조상, 장례”를 뜻합니다.","「力」는 “힘”을 뜻합니다.","助는 “장례(且)를 돕다(力)” -> “돕다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/404/"},"労":{"id":397,"char":"労","hun":"일할 로","meaning":"“일할 로”. 노동","on":"ロウ","kun":"","explanation":["労 = ⺍ + 冖 + 力。","「⺍＋冖」는 “불이 환하게 켜진 집”을 뜻합니다.","「力」는 “힘”을 뜻합니다.","労는 “밤늦게까지(⺍+冖) 열심히 일하다(力)” -> “노동”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/405/"},"例":{"id":398,"char":"例","hun":"법식 례","meaning":"“법식 례”. 관례, 예시","on":"レイ","kun":"たと(える)","explanation":["例 = 亻 + 歹 + 刂。","「亻」는 “사람”을 뜻합니다.","「歹」는 “시체”를 뜻합니다.","「刂」는 “칼”을 뜻합니다.","例는 “정육점 주인(亻)이 고기(歹)의 뼈를 분리(刂)해서 부위별로 진열해두다” -> “예시, 관례”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/406/"},"然":{"id":399,"char":"然","hun":"그럴 연","meaning":"“그럴 연”. 그와 같이, 그대로","on":"ゼン、ネン","kun":"","explanation":["然 = 月 + 犬 + 灬。","「月」는 “고기”를 뜻합니다.","「犬」는 “개”를 뜻합니다.","「灬」는 “불”을 뜻합니다.","然는 “개고기(犬+月)를 불(灬)에 구워 먹는 것은 당연하다” -> “그와 같이, 그대로”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/407/"},"追":{"id":400,"char":"追","hun":"쫓을 추","meaning":"“쫓을 추”. 쫓다","on":"ツイ","kun":"お(う)","explanation":["追 = ⻌ + 𠂤。","「⻌」는 “길”을 뜻합니다.","「𠂤」는 “언덕”을 뜻하는 글자입니다(링크 참조).","追는 “산(𠂤)을 넘고 길(⻌)을 달려 상대방을 쫓아가다” -> “쫓다, 추적하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/408/"},"商":{"id":401,"char":"商","hun":"장사 상","meaning":"“장사 상”. 장사하다","on":"ショウ","kun":"あきな(う)","explanation":["商는 “선반 위에 항아리를 올려놓은 모습”을 그린 상형문자입니다.","글자 아래쪽의 「口」는 “장사꾼이 소리치는 입(口)”을 표현하기 위해 추가된 것입니다.","“물건을 올려놓고 소리치며 팔다” -> “팔다, 장사하다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/409/"},"葉":{"id":402,"char":"葉","hun":"잎 엽","meaning":"“잎 엽”. 잎, 나뭇잎","on":"ヨウ","kun":"は","explanation":["葉 = 艹 + 世 + 木。","「艹」는 “풀”을 뜻합니다.","「世」는 본래 “나뭇가지에 돋아난 새싹들”을 그린 글자입니다(링크 참조).","「木」는 “나무”를 뜻합니다.","葉는 “나무(木)의 가지(世)에 돋아난 나뭇잎(艹)” -> “잎”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/410/"},"伝":{"id":403,"char":"伝","hun":"전할 전","meaning":"“전할 전”. 전하다, 알리다, 전설","on":"デン","kun":"つた(わる)、つた(える)、つた(う)","explanation":["伝 = 亻 + 云。","「亻」는 “사람”을 뜻합니다.","「云」는 “구름”을 뜻합니다.","伝는 “사람들(亻) 사이를 건너서(云) 전해지다” -> “전하다, 알리다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/411/"},"形":{"id":404,"char":"形","hun":"모양 형","meaning":"“모양 형”. 모양, 형태","on":"ケイ、ギョウ","kun":"かた、かたち","explanation":["形 = 开 + 彡。","开는 여기서는 “평평한 나무책상”을 그린 모양자입니다.","彡는 여기서는 「三」이 기울어진 것으로, “3”을 뜻합니다.","形는 “똑같은 책상(开) 세 개(彡)” -> “비슷한 모양” -> “모양, 형태”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/412/"},"景":{"id":405,"char":"景","hun":"볕 경","meaning":"“볕 경”. 경치","on":"ケイ","kun":"","explanation":["景 = 日 + 京。","「日」는 “해”를 뜻합니다.","「京」는 “서울, 수도”를 뜻합니다.","景는 “찬란한 햇빛(日) 아래 비치는 수도(京)의 경치” -> “경치”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/413/"},"落":{"id":406,"char":"落","hun":"떨어질 락","meaning":"“떨어질 락”. 떨어지다","on":"ラク","kun":"お(ちる)、お(とす)","explanation":["落 = 艹 + 氵 + 各。","「艹」는 “풀”을 뜻합니다.","「氵」는 “물”을 뜻합니다.","「各」는 “각각, 각자”라는 뜻입니다.","落는 “바람에 흩어져(各) 연못(氵)에 떨어지는 낙엽(艹)” -> “떨어지다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/414/"},"賞":{"id":407,"char":"賞","hun":"상줄 상","meaning":"“상줄 상”. 상","on":"ショウ","kun":"","explanation":["賞 = 龸 + 口 + 貝。","「龸」는 “궁궐”을 뜻합니다.","「口」는 “입”을 뜻합니다.","「貝」는 “돈, 재물”을 뜻합니다.","賞는 “궁궐(龸)에서 공을 치하하며(口) 상(貝)을 내리다” -> “상”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/415/"},"辺":{"id":408,"char":"辺","hun":"가 변","meaning":"“가 변”. 가장자리, 부근, 근처","on":"ヘン","kun":"あた(り)、べ","explanation":["辺 = ⻌ + 刀。","「⻌」는 “길”을 뜻합니다.","「刀」는 “칼”을 뜻합니다. 여기서는 “칼날” -> “가장자리”라는 뜻으로 쓰인 것입니다.","辺는 “길(⻌)의 가장자리(刀)” -> “가장자리, 변두리, 근처”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/416/"},"負":{"id":409,"char":"負","hun":"질 부","meaning":"“질 부”. 패배하다, 부담하다","on":"フ","kun":"ま(ける)、ま(かす)、お(う)","explanation":["負 = ⺈ + 貝。","「⺈」는 “칼”을 뜻합니다.","「貝」는 “돈, 재물”을 뜻합니다.","負는 “전쟁(⺈)에서 지고 재물(貝)을 빼앗기다” -> “지다, 패배하다, 부담하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/417/"},"失":{"id":410,"char":"失","hun":"잃을 실","meaning":"“잃을 실”. 잃다","on":"シツ","kun":"うしな(う)","explanation":["失 = 丶 + 夫。","「夫」는 “남편, 성인 남성”을 뜻합니다.","丶는 여기서는 “화살”을 표현한 모양자입니다.","失는 “전쟁에 나간 남편(夫)이 화살(丶)에 맞아 눈 한쪽을 잃다” -> “잃다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/418/"},"差":{"id":411,"char":"差","hun":"다를 차","meaning":"“다를 차”. 차이","on":"サ","kun":"さ(す)","explanation":["差 = 𦍌 + 左。","(의미부) 「𦍌」는 “양”을 뜻합니다.","(소리부 겸 의미부) 「左」(サ)는 “왼쪽”을 뜻합니다.","差는 “무리에서 떨어져 혼자 왼쪽(左)으로 가는 양(𦍌)” -> “차이, 다르다”라는 뜻의 글자입니다.","(左는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/419/"},"課":{"id":412,"char":"課","hun":"과정/공부할 과","meaning":"“과정/공부할 과”. 과정, 부서, 할당하다","on":"カ","kun":"","explanation":["課 = 言 + 果。","(의미부) 「言」는 “말”을 뜻합니다.","(소리부 겸 의미부) 「果」(カ)는 “결과, 결실, 끝나다”라는 뜻입니다.","課는 “글공부(言)가 끝나기(果)까지의 과정” -> “과정, 할당하다”라는 뜻의 글자입니다.","(果는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/420/"},"末":{"id":413,"char":"末","hun":"끝 말","meaning":"“끝 말”. 끝, 끝부분","on":"マツ、バツ","kun":"すえ","explanation":["末 = 木 + 一。","「木」는 “나무”를 뜻합니다.","一는 여기서는 “나무 꼭대기”를 표시한 모양자입니다.","末는 “나무(木)의 꼭대기(一)” -> “끝, 끝부분”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/421/"},"守":{"id":414,"char":"守","hun":"지킬 수","meaning":"“지킬 수”. 지키다","on":"シュ、ス","kun":"まも(る)、もり","explanation":["守 = 宀 + 寸。","「宀」는 “집”을 뜻합니다.","「寸」는 “손”을 뜻합니다.","守는 “집(宀)을 지키다(寸)” -> “지키다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/422/"},"極":{"id":415,"char":"極","hun":"다할 극","meaning":"“다할 극”. 극한, 극도, 한계","on":"キョク、ゴク","kun":"きわ(める)、きわ(まる)、きわ(み)","explanation":["極 = 木 + 了 + 一 + 口 + 又。","「木」는 “나무”를 뜻합니다.","「口」는 “입”을 뜻합니다.","「又」는 “손”을 뜻합니다.","了+一는 여기서는 “머리가 하늘에까지 닿는 거대한 거인”을 그린 모양자입니다.","極는 “나무기둥(木)으로 하늘을 떠받치며(又) 세상을 호령하는(口) 거인(了+一)” -> “극한, 극도, 한계”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/423/"},"種":{"id":416,"char":"種","hun":"씨 종","meaning":"“씨 종”. 씨, 종자, 종류","on":"シュ","kun":"たね","explanation":["種 = 禾 + 重。","「禾」는 “곡식”을 뜻합니다.","「重」는 “무겁다, 중요하다”라는 뜻입니다.","농사를 짓기 위해서는 곡식의 씨앗이 반드시 필요합니다.","種는 “중요한(重) 곡식(禾)의 씨앗” -> “씨앗” -> “종자, 종류”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/424/"},"美":{"id":417,"char":"美","hun":"아름다울 미","meaning":"“아름다울 미”. 아름답다, 미","on":"ビ","kun":"うつく(しい)","explanation":["美 = 𦍌 + 大。","「𦍌」는 “양”을 뜻합니다.","「大」는 본래 “사람”을 그린 글자입니다(링크 참조).","美는 “양(𦍌) 처럼 곱고 아름다운 사람(大)” -> “아름답다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/425/"},"命":{"id":418,"char":"命","hun":"목숨 명","meaning":"“목숨 명”. 목숨, 명령","on":"メイ、ミョウ","kun":"いのち","explanation":["命 = 亼 + 口 + 卩。","亼는 여기서는 “재판이 열리는 법정”을 그린 모양자입니다.","「口」는 “입”을 뜻합니다.","「卩」는 “무릎꿇은 사람”을 뜻합니다.","命는 “법정(亼)에서 무릎꿇은 죄인(卩)에게 사형 판결(口)을 내리다” -> “목숨, 명령”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/426/"},"福":{"id":419,"char":"福","hun":"복 복","meaning":"“복 복”. 행운, 축복","on":"フク","kun":"","explanation":["福 = 礻 + 畐。","(의미부) 「礻」는 “종교, 신, 고대의 비석”을 뜻합니다.","(소리부 겸 의미부) 「畐」(フク)는 “가득 찬 항아리”를 그린 글자입니다.","福는 “앞날에 행운이 가득하길(畐) 신에게 기원하다(礻)“ -> “행운, 축복”이라는 뜻의 글자입니다.","(畐는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/427/"},"量":{"id":420,"char":"量","hun":"헤아릴 량","meaning":"“헤아릴 량”. 양, 무게를 재다","on":"リョウ","kun":"はか(る)","explanation":["量 = 旦 + 里。","旦는 여기서는 “봇짐”을 그린 모양자입니다.","里는 여기서는 “저울”을 그린 모양자입니다.","量는 “봇짐(旦)의 무게를 재다(里)” -> “분량, 무게를 재다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/428/"},"望":{"id":421,"char":"望","hun":"바랄 망","meaning":"“바랄 망”. 바라다","on":"ボウ、モウ","kun":"のぞ(む)","explanation":["望 = 亡 + 月 + 王。","(소리부 겸 의미부) 亡(ボウ・モウ – “망할 망”)은 “망하다”라는 뜻의 상용한자입니다.","(의미부) 「月」는 “달”을 뜻합니다.","(의미부) 王(“임금 왕”)은 “왕”을 뜻하는 상용한자입니다.","望는 “망국(亡)의 임금(王)이 달(月)을 바라보며 나라의 부흥을 기원하다” -> “바라다”라는 뜻의 글자입니다.","(亡는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/429/"},"観":{"id":422,"char":"観","hun":"볼 관","meaning":"“볼 관”. 관찰하다, 보다","on":"カン","kun":"","explanation":["観 = 𮥶 + 見。","(소리부 겸 의미부) 「𮥶」(カン)은 “새장 안의 새”를 뜻하는 글자입니다(링크 참조).","(의미부) 「見」는 “보다”라는 뜻입니다.","観는 “새장 안의 새(𮥶)를 바라보다(見)” -> “관찰하다, 보다”라는 뜻의 글자입니다.","(𮥶는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/430/"},"察":{"id":423,"char":"察","hun":"살필 찰","meaning":"“살필 찰”. 살피다, 고찰","on":"サツ","kun":"","explanation":["察 = 宀 + 月 + 又 + 示。","「宀」는 “집”을 뜻합니다.","「月」는 “고기”를 뜻합니다.","「又」는 “손”을 뜻합니다.","「示」는 “신, 종교, 고대의 비석”을 뜻합니다.","察는 “집(宀)에서 제사상(示) 위에 고기(月)를 올리고(又) 점을 치다”라는 뜻입니다.","“점을 쳐서 미래를 살피다” -> “살피다, 고찰하다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/431/"},"整":{"id":424,"char":"整","hun":"가지런할 정","meaning":"“가지런할 정”. 정리하다, 정비하다","on":"セイ","kun":"ととの(える)、ととの(う)","explanation":["整 = 束 + 攵 + 正。","(의미부) 束(“묶을 속”)은 “묶다”라는 뜻의 상용한자입니다.","(의미부) 「攵」는 “때리다, 치다”라는 뜻입니다. 여기서는 “(때려서) ~하도록 시키다”라는 뜻으로 쓰인 것입니다.","(소리부 겸 의미부) 「正」(セイ)는 “바르다”라는 뜻입니다.","整는 “바르게(正) 묶도록(束) 시키다(攵)” -> “정리하다”라는 뜻의 글자입니다.","(正는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/432/"},"横":{"id":425,"char":"横","hun":"가로 횡","meaning":"“가로 횡”. 가로, 수평, 방자하다","on":"オウ","kun":"よこ","explanation":["横 = 木 + 黄。","(의미부) 「木」는 “나무”를 뜻합니다.","(소리부 겸 의미부) 黄(オウ – “누를 황”)은 “노란색, 황제”를 뜻하는 상용한자입니다.","横는 “황제(黄)가 궁궐 대문에 나무 빗장(木)을 치다”라는 뜻입니다.","“빗장은 가로로 치는 것” -> “가로, 수평”","“황제가 문을 걸어잠그고 제멋대로 폭정을 행사하다” -> “방자하다”","라는 의미입니다.","(黄는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/433/"},"型":{"id":426,"char":"型","hun":"모형 형","meaning":"“모형 형”. 모형, 본, 모범","on":"ケイ","kun":"かた","explanation":["型 = 开 + 刂 + 土。","开는 여기서는 “목에 칼을 찬 사형수”를 그린 모양자입니다.","「刂」는 “칼”을 뜻합니다.","「土」는 “흙, 땅”을 뜻합니다.","型는 “처형장(土)에서 죄수(开)를 처형하다(刂)”라는 뜻입니다.","“범죄자를 처형해서 본보기를 보이다” -> “모형, 본, 모범”이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/434/"},"深":{"id":427,"char":"深","hun":"깊을 심","meaning":"“깊을 심”. 깊다","on":"シン","kun":"ふか(い)、ふか(まる)、ふか(める)","explanation":["深 = 氵 + 㓁 + 木。","「氵」는 “물”을 뜻합니다.","㓁는 「穴」가 축약된 것으로, “구멍”을 뜻합니다.","「木」는 “나무”를 뜻합니다.","深는 “물(氵)이 솟아나오는 구멍(㓁)에 나무막대(木)를 집어넣어 깊이를 재다” -> “깊다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/435/"},"申":{"id":428,"char":"申","hun":"납 신","meaning":"“납 신”. 진술하다, 말씀드리다","on":"シン","kun":"もう(す)","explanation":["「申」는 “밭(田)에 번개(丨)가 내리치다”라는 뜻의 글자입니다(링크 참조).","“번개가 치다” -> “명령이 내리다” -> “말씀드리다, 진술하다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/436/"},"様":{"id":429,"char":"様","hun":"모양 양","meaning":"“모양 양”. 모양, 모습, 형태, 양식, ~님(존댓말)","on":"ヨウ","kun":"さま","explanation":["様 = 木 + 𦍌 + 氺。","「木」는 “나무”를 뜻합니다.","「𦍌」는 “양”을 뜻합니다.","氺는 「水」가 살짝 변형된 것으로, “물”을 뜻합니다.","様는 “나무(木) 옆에서 물(水)을 마시는 양들(𦍌)의 모습” -> “모양, 모습, 형태”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/437/"},"港":{"id":430,"char":"港","hun":"항구 항","meaning":"“항구 항”. 항구","on":"コウ","kun":"みなと","explanation":["港 = 氵 + 共 + 己。","「氵」는 “물”을 뜻합니다.","「共」는 “함께, 같이”라는 뜻입니다.","「己」는 “몸을 웅크린 사람”을 뜻합니다. 여기서는 그냥 “사람”이라는 뜻으로 쓰인 것입니다.","港는 “바닷가(氵)에서 사람들(己)이 함께(共) 모여사는 곳” -> “항구”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/438/"},"達":{"id":431,"char":"達","hun":"통달할 달","meaning":"“통달할 달”. 통달하다, 달성하다, 도달하다","on":"タツ","kun":"","explanation":["達 = ⻌ + 土 + 羊。","「⻌」는 “길”을 뜻합니다.","「羊」는 “양”을 뜻합니다.","土는 여기서는 「大」가 변형된 것으로, “사람”을 그린 모양자입니다.","達는 “양떼(羊)를 몰고 길(⻌)을 가는 양치기(土)“라는 뜻입니다.","“양떼를 능숙하게 통솔하는 양치기” -> “통달하다, 달성하다, 도달하다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/439/"},"良":{"id":432,"char":"良","hun":"어질 량","meaning":"“어질 량”. 좋다","on":"リョウ","kun":"よ(い)","explanation":["良 = 丶 + 艮。","「艮」는 “천민”을 뜻합니다.","丶는 여기서는 艮와의 구분을 위해 추가된 장식입니다.","良는 “천민(艮)과는 다르다(丶)” -> “좋다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/440/"},"谷":{"id":433,"char":"谷","hun":"골 곡","meaning":"“골 곡”. 계곡, 골짜기","on":"コク","kun":"たに","explanation":["谷는 “물이 흐르는 계곡”을 그린 상형문자입니다."],"sourceUrl":"https://nihongokanji.com/441/"},"候":{"id":434,"char":"候","hun":"기후 후","meaning":"“기후 후”. 기다리다, 기후, 징후","on":"コウ","kun":"そうろう","explanation":["候 = 亻 + 丨 + ユ + 矢。","「亻」는 “사람”을 뜻합니다.","丨+ユ는 여기서는”활시위(丨)와 활(ユ)”을 그린 모양자입니다.","「矢」는 “화살”을 뜻합니다.","候는 “화살(矢)을 당긴 채(丨+ユ) 조준하고 있는 사람(亻)”을 그린 글자입니다.","“화살을 조준한 채 대기하다” -> “기다리다” -> “징후” -> “기후”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/442/"},"史":{"id":435,"char":"史","hun":"역사 사","meaning":"“역사 사”. 역사","on":"シ","kun":"","explanation":["史는 “제사 도구를 든 손”을 그린 상형문자입니다.","“제사장” -> “사관” -> “역사”라는 의미입니다.","참고)","「吏」와 유래는 같으나 다른 글자입니다."],"sourceUrl":"https://nihongokanji.com/443/"},"階":{"id":436,"char":"階","hun":"섬돌 계","meaning":"“섬돌 계”. 계단, 층, 등급","on":"カイ","kun":"","explanation":["階 = ⻖ + 皆。","(의미부) 「⻖」는 “언덕, 산”을 뜻합니다.","(소리부) 皆(カイ – “다 개”)는 “모두, 다”라는 뜻의 상용한자입니다.","다만 여기서는 소리부의 역할만 하고 있습니다.","階는 “계단 지형의 언덕(⻖)” -> “계단, 등급”이라는 뜻의 글자입니다(皆는 소리부)."],"sourceUrl":"https://nihongokanji.com/444/"},"満":{"id":437,"char":"満","hun":"찰 만","meaning":"“찰 만”. 가득하다","on":"マン","kun":"み(ちる)、み(たす)","explanation":["満 = 氵 + 艹 + 両。","「氵」는 “물”을 뜻합니다.","「艹」는 “풀”을 뜻합니다.","「両」는 “양쪽”을 뜻합니다.","満는 “사방팔방(両)에 산천초목(氵+艹 )이 가득하다” -> “가득하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/445/"},"敗":{"id":438,"char":"敗","hun":"패할 패","meaning":"“패할 패”. 패하다","on":"ハイ","kun":"やぶ(れる)","explanation":["敗 = 貝 + 攵。","「貝」는 “재물, 돈”을 뜻합니다.","「攵」는 “때리다, 치다”라는 뜻입니다.","敗는 “침략군이 재물(貝)을 때려부수다(攵)” -> “패배하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/446/"},"管":{"id":439,"char":"管","hun":"대롱 관","meaning":"“대롱 관”. 대롱/관, 관리하다, 관할하다","on":"カン","kun":"くだ","explanation":["管 = 𥫗 + 官。","(의미부) 「𥫗」는 “대나무”를 뜻합니다.","(소리부 겸 의미부) 「官」(カン)은 “관청, 관직”을 뜻합니다.","管는,","“대나무(𥫗) 줄기” -> “관, 대롱”","“관청/관직(官) -> “관할하다, 관리하다”","라는 뜻의 글자입니다.","(官는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/447/"},"兵":{"id":440,"char":"兵","hun":"병사 병","meaning":"“병사 병”. 병사","on":"ヘイ、ヒョウ","kun":"","explanation":["兵 = 斤 + 一 + ハ。","「斤」는 “도끼”를 뜻합니다.","一+ハ는 여기서는 “도끼를 두 손으로 치켜든 모습”을 그린 모양자입니다.","兵는 “도끼(斤)를 하늘 높이 치켜든(一+ハ) 병사” -> “병사”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/448/"},"器":{"id":441,"char":"器","hun":"그릇 기","meaning":"“그릇 기”. 그릇, 도구, 생명체의 기관","on":"キ","kun":"うつわ","explanation":["器 = 口 + 口 + 大 + 口 + 口。","口는 여기서는 “그릇”을 그린 모양자입니다.","大는 여기서는 “(그릇이 놓인) 선반”을 그린 모양자입니다.","器는 “선반(大)에 가지런히 정렬된 그릇들(口)” -> “그릇, 도구”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/449/"},"路":{"id":442,"char":"路","hun":"길 로","meaning":"“길 로”. 길, 경로","on":"ロ","kun":"じ","explanation":["路 = 足 + 各。","「足」는 “발”을 뜻합니다.","「各」는 “각각, 각자”라는 뜻입니다.","路는 “저마다 각자(各)의 길을 걸어가다(足)” -> “길, 경로”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/450/"},"科":{"id":443,"char":"科","hun":"과목 과","meaning":"“과목 과”. 과목, 종류","on":"カ","kun":"","explanation":["科 = 禾 + 斗。","「禾」는 “곡식”을 뜻합니다.","「斗」는 “국자”를 뜻합니다.","科는 “국자(斗)로 곡식(禾)을 퍼담아 종류별로 분류하다” -> “과목, 종류”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/451/"},"細":{"id":444,"char":"細","hun":"가늘 세","meaning":"“가늘 세”. 가늘다, 세밀한, 자세한","on":"サイ","kun":"ほそ(い)、ほそ(る)、こま(か)、こま(かい)","explanation":["細 = 糸 + 田。","「糸」는 “실”을 뜻합니다.","田는 여기서는 “실을 촘촘하게 꿰매놓은 모습”을 그린 모양자입니다.","細는 “실(糸)을 가늘고 촘촘하게 꿰매다(田)” -> “가늘다, 세밀하다, 자세하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/452/"},"積":{"id":445,"char":"積","hun":"쌓일 적","meaning":"“쌓일 적”. 쌓이다","on":"セキ","kun":"つ(む)、つ(もる)","explanation":["積 = 禾 + 龶 + 貝。","「禾」는 “곡식”을 뜻합니다.","「貝」는 “돈, 재물”을 뜻합니다.","龶는 여기서는 “(곡식/돈이) 쌓여있는 모습”을 그린 모양자입니다.","積는 “식량(禾)과 재물(貝)을 쌓아놓다(龶)” -> “쌓다, 쌓이다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/453/"},"丸":{"id":446,"char":"丸","hun":"둥글 환","meaning":"“둥글 환”. 둥글다","on":"ガン","kun":"まる、まる(い)、まる(める)","explanation":["丸는 “몸을 둥글게 말고 엎드린 사람”을 그린 상형문자입니다.","“몸을 둥글게 말다” -> “둥글다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/454/"},"他":{"id":447,"char":"他","hun":"다를 타","meaning":"“다를 타”. 다른, 남","on":"タ","kun":"ほか","explanation":["他 = 亻 + 也。","「亻」는 “사람”을 뜻합니다.","也는 여기서는 「地」가 축약된 것으로, “땅”을 뜻합니다.","他는 “타지(地)에서 온 사람(亻)” -> “다른, 남”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/455/"},"録":{"id":448,"char":"録","hun":"기록할 록","meaning":"“기록할 록”. 기록하다, 기록","on":"ロク","kun":"","explanation":["録 = 金 + 录。","「金」는 “쇠, 금속”을 뜻합니다.","「录」는 “염색하다, 물들이다”라는 뜻의 글자입니다(링크 참조).","録는 “철판(金)에 기록을 새겨넣다(录)” -> “기록하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/456/"},"省":{"id":449,"char":"省","hun":"살필 성/덜 생","meaning":"“살필 성/덜 생”. 살피다, 반성하다, 덜다, 생략하다, 관청","on":"セイ、ショウ","kun":"かえり(みる)、はぶ(く)","explanation":["省 = 少 + 目。","「少」는 “적다”라는 뜻입니다.","「目」는 “눈”을 뜻합니다.","省는,","“세세한 곳까지(少) 자세히 살피다(目)” -> “살피다, 반성하다, 관청”","“사소한(少) 부분은 못 보고(目) 지나치다” -> “생략하다”","라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/457/"},"橋":{"id":450,"char":"橋","hun":"다리 교","meaning":"“다리 교”. 다리","on":"キョウ","kun":"はし","explanation":["橋 = 木 + 喬。","「木」는 “나무”를 뜻합니다.","喬는 「高」가 변형된 글자로, “높다”라는 뜻입니다.","橋는 “높은 곳(喬)에 지어진 나무(木) 다리” -> “다리”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/458/"},"岸":{"id":451,"char":"岸","hun":"언덕 안","meaning":"“언덕 안”. 물가, 벼랑","on":"ガン","kun":"きし","explanation":["岸 = 山 + 厂 + 干。","(의미부) 「山」는 “산”을 뜻합니다.","(의미부) 「厂」는 “기슭, 절벽”을 뜻합니다.","(소리부) 干(カン – “방패 간”)은 “방패”를 뜻하는 상용한자입니다.","다만 여기서는 소리부(カン -> ガン)의 역할만 하고 있습니다.","岸는 “산(山) 기슭의 절벽(厂)” -> “벼랑, 물가”라는 뜻의 글자입니다(干은 소리부)."],"sourceUrl":"https://nihongokanji.com/459/"},"客":{"id":452,"char":"客","hun":"손 객","meaning":"“손 객”. 손님","on":"キャク、カク","kun":"","explanation":["客 = 宀 + 各。","(의미부) 「宀」는 “집”을 뜻합니다.","(소리부 겸 의미부) 「各」(カク)는 본래 “출입구로 들어서는 발걸음”을 그린 글자입니다(링크 참조).","客는 “집(宀)에 들어온(各) 손님” -> “손님”이라는 뜻의 글자입니다.","(各는 소리부(カク -> キャク・カク)도 겸함)"],"sourceUrl":"https://nihongokanji.com/460/"},"周":{"id":453,"char":"周","hun":"두루 주","meaning":"“두루 주”. 둘레, 주기, 돌다","on":"シュウ","kun":"まわ(り)","explanation":["周는 “논밭 주위를 둘러싼 경계선”을 그린 상형문자입니다.","“논밭을 둘러싼 경계선” -> “둘레, 돌다, 주기”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/461/"},"材":{"id":454,"char":"材","hun":"재목 재","meaning":"“재목 재”. 재목, 재료","on":"ザイ","kun":"","explanation":["材 = 木 + 才。","(의미부) 「木」는 “나무”를 뜻합니다.","(소리부 겸 의미부) 才(サイ – “재주 재”)는 “재능, 재질”을 뜻하는 상용한자입니다.","材는 “재질(才)이 뛰어난 나무(木)” -> “재목, 재료”라는 뜻의 글자입니다.","(才는 소리부(サイ -> ザイ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/462/"},"登":{"id":455,"char":"登","hun":"오를 등","meaning":"“오를 등”. 오르다, 올라가다","on":"トウ、ト","kun":"のぼ(る)","explanation":["登 = 癶 + 豆。","(의미부) 癶는 여기서는 “위쪽(↑)”을 가리키는 모양자로 쓰인 것입니다.","(소리부 겸 의미부) 「豆」(トウ)는 “제기그릇”을 뜻합니다.","登는 “제기그릇(豆)을 들고 제단 위로(癶) 올라가다” -> “올라가다”라는 뜻의 글자입니다.","(豆는 소리부(トウ -> トウ・ト)도 겸함)"],"sourceUrl":"https://nihongokanji.com/463/"},"健":{"id":456,"char":"健","hun":"굳셀 건","meaning":"“굳셀 건”. 건강하다","on":"ケン","kun":"すこ(やか)","explanation":["健 = 亻 + 建。","(의미부) 「亻」는 “사람”을 뜻합니다.","(소리부 겸 의미부) 「建」(ケン)은 “세우다, 건립하다”라는 뜻입니다.","健는 “건강한 몸(亻)을 세우다(建)” -> “건강하다”라는 뜻의 글자입니다.","(建은 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/464/"},"戸":{"id":457,"char":"戸","hun":"집 호","meaning":"“집 호”. 집, 문, 출입구","on":"コ","kun":"と","explanation":["戸는 “외닫이 문”을 본따 그린 상형문자입니다.","“외닫이 문” -> “집, 문, 출입구”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/465/"},"速":{"id":458,"char":"速","hun":"빠를 속","meaning":"“빠를 속”. (속도가)빠르다","on":"ソク","kun":"はや(い)、はや(める)、はや(まる)、すみ(やか)","explanation":["速 = ⻌ + 束。","(의미부) 「⻌」는 “길”을 뜻합니다.","(소리부 겸 의미부) 束(ソク – “묶을 속”)은 “묶다”라는 뜻의 상용한자입니다.","速는 “발목의 고름을 단단히 묶고(束) 서둘러 달려가다(⻌)” -> “빠르다”라는 뜻의 글자입니다.","(束는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/466/"},"飛":{"id":459,"char":"飛","hun":"날 비","meaning":"“날 비”. 날다","on":"ヒ","kun":"と(ぶ)、と(ばす)","explanation":["飛는 “새의 날개와 몸통”을 함께 그린 상형문자입니다.","“새” -> “날다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/467/"},"殺":{"id":460,"char":"殺","hun":"죽일 살/덜 쇄","meaning":"“죽일 살/덜 쇄”. 죽이다, 덜다","on":"サツ、サイ、セツ","kun":"ころ(す)","explanation":["殺 = 杀 + 殳。","杀는 “사형대에 묶인 사형수”를 그린 모양자입니다(이런 느낌).","「殳」는 “때리다, 휘두르다”라는 뜻입니다.","殺는 “사형수(杀)의 목에 칼을 내리치다(殳)” -> “죽이다, 덜다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/468/"},"央":{"id":461,"char":"央","hun":"가운데 앙","meaning":"“가운데 앙”. 중앙","on":"オウ","kun":"","explanation":["央는 “목에 칼(冂)을 찬 죄수(大)”를 그린 상형문자입니다.","“칼 중앙에 매여있는 죄수” -> “중앙”이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/469/"},"号":{"id":462,"char":"号","hun":"부르짖을 호","meaning":"“부르짖을 호”. 부르짖다, 호령, 신호","on":"ゴウ","kun":"","explanation":["号 = 口 + 丂。","「口」는 “입”을 뜻합니다.","丂는 여기서는 “입에서 흘러나가는 소리”를 표현한 모양자입니다.","号는 “입(口)에서 흘러나가는 소리(丂)” -> “부르짖다, 호령, 신호”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/470/"},"単":{"id":463,"char":"単","hun":"홑 단","meaning":"“홑 단”. 단독, 홀로, 하나","on":"タン","kun":"","explanation":["単는 “먼 옛날 사냥에 쓰였던 무기의 일종”을 그린 상형문자입니다.","“혼자서 사냥할 수 있는 무기” -> “단독, 홀로”라는 의미입니다.","(“무기 한 개” -> “단독”이라는 설도 있습니다.)"],"sourceUrl":"https://nihongokanji.com/471/"},"竹":{"id":464,"char":"竹","hun":"대나무 죽","meaning":"“대나무 죽”. 대나무","on":"チク","kun":"たけ","explanation":["竹는 “대나무 줄기와 잎사귀”를 그린 상형문자입니다."],"sourceUrl":"https://nihongokanji.com/472/"},"完":{"id":465,"char":"完","hun":"완전할 완","meaning":"“완전할 완”. 완전하다","on":"カン","kun":"","explanation":["完 = 宀 + 元。","「宀」는 “집”을 뜻합니다.","「元」는 “으뜸, 근원, 근본”을 뜻합니다.","完은 “잘 지어진, 으뜸가는(元) 집(宀)” -> “완전하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/473/"},"競":{"id":466,"char":"競","hun":"다툴 경","meaning":"“다툴 경”. 겨루다, 경쟁하다, 다투다","on":"キョウ、ケイ","kun":"きそ(う)、せ(る)","explanation":["競 = 立 + 兄 + 立 + 兄。","「立」는 “서다”라는 뜻입니다.","「兄」는 “형”을 뜻합니다.","競는 “두 사람(兄)이 마주서서(立) 힘을 겨루다” -> “겨루다, 경쟁하다, 다투다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/474/"},"給":{"id":467,"char":"給","hun":"줄 급","meaning":"“줄 급”. 지급하다, 공급하다","on":"キュウ","kun":"","explanation":["給 = 糸 + 合。","「糸」는 “실”을 뜻합니다.","「合」는 “합치다”라는 뜻입니다.","給는 “실(糸)이 끊어지지 않도록 계속 이어주다(合)” -> “지급하다, 공급하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/475/"},"根":{"id":468,"char":"根","hun":"뿌리 근","meaning":"“뿌리 근”. 뿌리, 근본","on":"コン","kun":"ね","explanation":["根 = 木 + 艮。","(의미부) 「木」는 “나무”를 뜻합니다.","(소리부 겸 의미부) 「艮」(コン)은 “고개를 숙인 사람”을 뜻합니다(링크 참조).","根는 “나무(木)의 뿌리를 내려다보다(艮)” -> “뿌리, 근본”이라는 뜻의 글자입니다.","(艮은 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/476/"},"苦":{"id":469,"char":"苦","hun":"쓸 고","meaning":"“쓸 고”. 쓰다, 괴롭다","on":"ク","kun":"くる(しい)、くる(しむ)、くる(しめる)、にが(い)、にが(る)","explanation":["苦 = 艹 + 古。","(의미부) 「艹」는 “풀”을 뜻합니다.","(소리부 겸 의미부) 「古」(コ)는 “오래되다”라는 뜻입니다.","苦는 “오래된(古) 약초(艹)” -> “쓰다” -> “괴롭다”라는 뜻의 글자입니다.","(古는 소리부(コ -> ク)도 겸함)"],"sourceUrl":"https://nihongokanji.com/477/"},"園":{"id":470,"char":"園","hun":"동산 원","meaning":"“동산 원”. 동산, 정원, 공원","on":"エン","kun":"その","explanation":["園 = 囗 + 袁。","(의미부) 囗는 여기서는 “정원의 둘레”를 그린 모양자입니다.","(소리부 겸 의미부) 「袁」(エン)은 “길다, 헐렁하다”라는 뜻입니다.","園는 “정원(囗)에서 느긋하게(袁) 여유를 즐기다” -> “정원, 동산, 공원”이라는 뜻의 글자입니다.","(袁는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/478/"},"具":{"id":471,"char":"具","hun":"갖출 구","meaning":"“갖출 구”. 도구","on":"グ","kun":"","explanation":["具 = 目 + 一 + ハ。","目는 여기서는 “(그릇 위에 올려진) 떡”을 그린 모양자입니다.","一+ハ는 여기서는 “제사용 그릇”을 그린 모양자입니다.","具는 “떡(目)을 담는 제사용 그릇(一+ハ)” -> “도구”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/479/"},"歴":{"id":472,"char":"歴","hun":"지낼 력","meaning":"“지낼 력”. 지나가다, 경과하다","on":"レキ","kun":"","explanation":["歴 = 厂 + 林 + 止。","「厂」는 “기슭, 절벽”을 뜻합니다.","「林」는 “숲”을 뜻합니다.","「止」는 “발”을 뜻합니다.","歴는 “절벽(厂) 아래의 숲(林)으로 걸어 들어간 발자국(止)”이라는 뜻입니다.","“발자국, 기록” -> “지나가다, 경과하다, 이력”이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/480/"},"辞":{"id":473,"char":"辞","hun":"말씀 사","meaning":"“말씀 사”. 말, 단어, 그만두다","on":"ジ","kun":"や(める)","explanation":["辞 = 舌 + 辛。","「舌」는 “혀”를 뜻합니다.","「辛」는 “문신을 새기는 고문 도구”를 뜻하는 부수입니다(링크 참조).","辞는 “혀(舌)를 찔러서(辛) 말을 하지 못하도록 만들다” -> “말, 단어, 그만두다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/481/"},"馬":{"id":474,"char":"馬","hun":"말 마","meaning":"“말 마”. 말","on":"バ","kun":"うま、ま","explanation":["馬는 “말”의 모습을 그린 상형문자입니다."],"sourceUrl":"https://nihongokanji.com/482/"},"愛":{"id":475,"char":"愛","hun":"사랑 애","meaning":"“사랑 애”. 사랑","on":"アイ","kun":"","explanation":["愛 = ⺤ + 冖 + 心 + 夂。","「⺤」는 “손”을 뜻합니다.","冖는 여기서는 “덮다, 품다”라는 뜻을 표현한 모양자입니다.","「心」는 “마음”을 뜻합니다.","「夂」는 “발”을 뜻합니다.","愛는 “사랑하는 마음(心)을 품고(⺤+冖) 다가서다(夂)” -> “사랑”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/483/"},"未":{"id":476,"char":"未","hun":"아닐 미","meaning":"“아닐 미”. 아직, 미숙한, 미-(접두어)","on":"ミ","kun":"","explanation":["未 = 一 + 木。","未는 “가지가 앙상한 나무(木)”를 그린 상형문자입니다.","“아직 잎이 나지 않은 나무” -> “아직, 미숙한”이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/484/"},"航":{"id":477,"char":"航","hun":"배 항","meaning":"“배 항”. 항해","on":"コウ","kun":"","explanation":["航 = 舟 + 亢。","(의미부) 舟(“배 주”)는 “배”를 뜻하는 상용한자입니다.","(소리부 겸 의미부) 「亢」(コウ)는 “오르다”라는 뜻의 글자입니다(링크 참조).","航는 “조각배(舟)를 타고 강을 거슬러 올라가다(亢)” -> “항해”라는 뜻의 글자입니다.","(亢는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/485/"},"冷":{"id":478,"char":"冷","hun":"찰 냉","meaning":"“찰 냉”. 차다, 차갑다","on":"レイ","kun":"つめ(たい)、ひ(える)、ひ(や)、ひ(やす)、ひ(やかす)、さ(める)、さ(ます)","explanation":["冷 = 冫 + 令。","(의미부) 「冫」는 “얼음”을 뜻합니다.","(소리부 겸 의미부) 令(レイ – “하여금 령”)은 “명령”을 뜻하는 상용한자입니다.","冷는 “냉혹한(冫) 명령(令)” -> “차갑다”라는 뜻의 글자입니다.","(令는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/486/"},"鉄":{"id":479,"char":"鉄","hun":"쇠 철","meaning":"“쇠 철”. 철","on":"テツ","kun":"","explanation":["鉄 = 金 + 失。","(의미부) 「金」는 “쇠, 황금”을 뜻합니다.","(소리부 겸 의미부) 「失」(シツ)는 “잃다”라는 뜻입니다.","鉄는 “황금(金)보다 가치가 뒤떨어지는(失) 금속” -> “철”이라는 뜻의 글자입니다.","(失는 소리부(シツ -> テツ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/487/"},"類":{"id":480,"char":"類","hun":"무리 류","meaning":"“무리 류”. 종류, 부류","on":"ルイ","kun":"たぐ(い)","explanation":["類 = 米 + 大 + 頁。","「米」는 “쌀”을 뜻합니다.","「頁」는 “머리”를 뜻합니다.","大는 여기서는 「犬」가 변형된 것으로, “개”를 뜻합니다.","類는 “쌀알(米)처럼 서로 비슷비슷하게 생긴(頁) 개들(犬)”이라는 뜻입니다.","“비슷한 개들끼리 종류별로 나누다” -> “종류, 부류”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/488/"},"児":{"id":481,"char":"児","hun":"아이 아","meaning":"“아이 아”. 아이, 아동","on":"ジ、ニ","kun":"","explanation":["児는 “두 다리(儿)로 아장아장 걷는 아기”를 그린 상형문자입니다."],"sourceUrl":"https://nihongokanji.com/489/"},"印":{"id":482,"char":"印","hun":"도장 인","meaning":"“도장 인”. 도장","on":"イン","kun":"しるし","explanation":["印 = 𠀉 + 卩。","𠀉는 「⺤」를 옆으로 돌린 것으로, “손”을 뜻합니다.","「卩」는 “무릎꿇은 사람”을 뜻합니다.","印는 “무릎꿇은 사람(卩)의 머리를 찍어누르다(𠀉)” -> “누르다” -> “도장”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/490/"},"王":{"id":483,"char":"王","hun":"임금 왕","meaning":"“임금 왕”. 왕","on":"オウ","kun":"","explanation":["王는 “권위를 상징하는 거대한 도끼”를 그린 상형문자입니다.","“권위의 상징” -> “우두머리” -> “왕”이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/491/"},"返":{"id":484,"char":"返","hun":"돌이킬 반","meaning":"“돌이킬 반”. 돌아오다, 반사하다, 갚다","on":"ヘン","kun":"かえ(す)、かえ(る)","explanation":["返 = ⻌ + 反。","「⻌」는 “길”을 뜻합니다.","「反」는 “돌이키다, 뒤집다”라는 뜻입니다.","返는 “가던 길(⻌)을 되돌아오다(反)” -> “돌아오다, 반사하다, 갚다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/492/"},"標":{"id":485,"char":"標","hun":"표할 표","meaning":"“표할 표”. 표시, 표지","on":"ヒョウ","kun":"","explanation":["標 = 木 + 覀 + 示。","「木」는 “나무”를 뜻합니다.","「示」는 “고대의 비석”을 뜻합니다.","覀는 여기서는 “위패”를 그린 모양자입니다.","標는 “신성한 나무(木) 옆에 비석(示)을 세우고 위패(覀)를 올려 표시해두다” -> “표시, 표지”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/493/"},"油":{"id":486,"char":"油","hun":"기름 유","meaning":"“기름 유”. 기름","on":"ユ","kun":"あぶら","explanation":["油 = 氵 + 由。","(의미부) 「氵」는 “물”을 뜻합니다.","(소리부 겸 의미부) 「由」(ユ)는 본래 “촛불”을 그린 상형문자입니다(링크 참조).","油는 “등잔불(由)의 연료가 되는 액체(氵)” -> “기름”이라는 뜻의 글자입니다.","(由는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/494/"},"輪":{"id":487,"char":"輪","hun":"바퀴 륜","meaning":"“바퀴 륜”. 바퀴","on":"リン","kun":"わ","explanation":["輪 = 車 + 侖。","(의미부) 「車」는 “수레, 차”를 뜻합니다.","(소리부 겸 의미부) 「侖」(リン)은 “둥글게 말린 죽간”을 그린 글자입니다(링크 참조).","輪는 “둥근(侖) 수레바퀴(車)” -> “바퀴”라는 뜻의 글자입니다.","(侖는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/495/"},"植":{"id":488,"char":"植","hun":"심을 식","meaning":"“심을 식”. 심다","on":"ショク","kun":"う(える)、う(わる)","explanation":["植 = 木 + 直。","(의미부) 「木」는 “나무”를 뜻합니다.","(소리부 겸 의미부) 「直」(チョク)는 “곧다”라는 뜻입니다.","植는 “나무(木)를 곧게(直) 심다” -> “심다”라는 뜻의 글자입니다.","(直는 소리부(チョク -> ショク)도 겸함)"],"sourceUrl":"https://nihongokanji.com/496/"},"熱":{"id":489,"char":"熱","hun":"더울 열","meaning":"“더울 열”. 열기, 뜨겁다","on":"ネツ","kun":"あつ(い)","explanation":["熱 = 坴 + 丸 + 灬。","「坴」는 “흙더미”를 뜻하는 글자입니다(링크 참조).","丸는 여기서는 “땅(坴)에 나무를 심고 있는 사람”을 그린 모양자입니다(위 그림 참조).","「灬」는 “불”을 뜻합니다.","熱는 “땅(坴)에 심어놓은(丸) 나무를 태우다(灬)“ -> “뜨겁다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/497/"},"宿":{"id":490,"char":"宿","hun":"잘 숙","meaning":"“잘 숙”. 여관, 머무르다","on":"シュク","kun":"やど、やど(る)、やど(す)","explanation":["宿 = 宀 + 亻 + 百。","「宀」는 “집”을 뜻합니다.","「亻」는 “사람”을 뜻합니다.","「百」는 “100”을 뜻합니다.","宿는 “백 명(百)의 사람(亻)이 묵을 수 있는 커다란 집(宀)” -> “여관, 숙소, 머무르다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/498/"},"清":{"id":491,"char":"清","hun":"맑을 청","meaning":"“맑을 청”. 맑다, 깨끗하다","on":"セイ、ショウ","kun":"きよ(い)、きよ(まる)、きよ(める)","explanation":["清 = 氵 + 青。","(의미부) 「氵」는 “물”을 뜻합니다.","(소리부 겸 의미부) 「青」(セイ・ショウ)는 “푸르다”라는 뜻입니다.","清는 “푸르고 깨끗한(青) 물(氵)” -> “맑다, 깨끗하다”라는 뜻의 글자입니다.","(青는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/499/"},"覚":{"id":492,"char":"覚","hun":"깨달을 각","meaning":"“깨달을 각”. 깨닫다, 눈뜨다, 기억하다","on":"カク","kun":"おぼ(える)、さ(ます)、さ(める)","explanation":["覚 = ⺍ + 冖 + 見。","「⺍＋冖」는 “불이 환하게 켜진 집”을 뜻합니다.","「見」는 “보다”라는 뜻입니다.","覚는 “환한 불빛(⺍+冖)으로 어둠을 밝히고 보다(見)” -> “깨달음, 눈뜨다, 기억하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/500/"},"船":{"id":493,"char":"船","hun":"배 선","meaning":"“배 선”. 선박","on":"セン","kun":"ふね、ふな","explanation":["船 = 舟 + 㕣。","舟(“배 주”)는 “배”를 뜻하는 상용한자입니다.","㕣는 여기서는 “작은 배”를 그린 모양자입니다.","船는 “배 두 척(舟+㕣) 만큼 큰 배” -> “선박”이라는 뜻의 글자입니다.","(船는 보통 舟보다 크기가 큰 배를 뜻하는 경우가 많습니다.)"],"sourceUrl":"https://nihongokanji.com/501/"},"倍":{"id":494,"char":"倍","hun":"곱 배","meaning":"“곱 배”. 2배","on":"バイ","kun":"","explanation":["倍 = 亻 + 咅。","(의미부) 「亻」는 “사람”을 뜻합니다.","(소리부 겸 의미부) 「咅」(バイ)는 “화분 위의 화초”를 뜻합니다.","倍는 “사람(亻)이 화초(咅)에 물을 줘서 두 배로 키우다” -> “2배”라는 뜻의 글자입니다.","(咅는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/502/"},"億":{"id":495,"char":"億","hun":"억 억","meaning":"“억 억”. 1억","on":"オク","kun":"","explanation":["億 = 亻 + 意。","「亻」는 “사람”을 뜻합니다.","「意」는 “뜻, 생각, 의미”를 뜻합니다.","億는 “사람(亻)의 머릿속에는 수많은 생각(意)이 있다” -> “많다” -> “1억”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/503/"},"芸":{"id":496,"char":"芸","hun":"재주 예","meaning":"“재주 예”. 재주, 예술","on":"ゲイ","kun":"","explanation":["芸 = 艹 + 云。","「艹」는 “풀”을 뜻합니다.","「云」는 “구름”을 뜻합니다.","芸는 “구름(云)위를 노니는 듯 아름다운 정원(艹)을 가꾸다” -> “예술, 재주”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/504/"},"停":{"id":497,"char":"停","hun":"머무를 정","meaning":"“머무를 정”. 정지, 멈추다","on":"テイ","kun":"","explanation":["停 = 亻 + 亭。","(의미부) 「亻」는 “사람”을 뜻합니다.","(소리부 겸 의미부) 亭(テイ – “정자 정”)은 “정자”를 뜻하는 상용한자입니다.","停는 “나그네(亻)가 정자(亭)에 머물러 쉬다” -> “멈추다, 머무르다”라는 뜻의 글자입니다.","(亭는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/505/"},"陸":{"id":498,"char":"陸","hun":"뭍 육","meaning":"“뭍 육”. 육지","on":"リク","kun":"","explanation":["陸 = ⻖ + 坴。","「⻖」는 “언덕, 산”을 뜻합니다.","「坴」는 “흙더미”를 뜻합니다.","陸는 “흙이 쌓인(坴) 언덕(⻖)” -> “뭍, 육지”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/506/"},"玉":{"id":499,"char":"玉","hun":"구슬 옥","meaning":"“구슬 옥”. 구슬, 보석","on":"ギョク","kun":"たま","explanation":["玉는 “구슬을 실에 꿰어놓은 모습”을 그린 상형문자입니다."],"sourceUrl":"https://nihongokanji.com/507/"},"波":{"id":500,"char":"波","hun":"물결 파","meaning":"“물결 파”. 물결, 파동","on":"ハ","kun":"なみ","explanation":["波 = 氵 + 皮。","(의미부) 「氵」는 “물”을 뜻합니다.","(소리부 겸 의미부) 皮(ヒ – “가죽 피”)는 “표면, 가죽, 껍질”을 뜻하는 상용한자입니다.","波는 “물(氵)의 표면(皮)을 따라 퍼지는 물결” -> “물결, 파동”이라는 뜻의 글자입니다.","(皮는 소리부(ヒ -> ハ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/508/"},"帯":{"id":501,"char":"帯","hun":"띠 대","meaning":"“띠 대”. 허리띠, 휴대하다, 지역","on":"タイ","kun":"お(びる)、おび","explanation":["帯 = 丗 + 冖 + 巾。","丗+冖는 여기서는 “장식(丗)이 달린 허리띠(冖)”를 그린 모양자입니다.","「巾」는 “수건, 천”을 뜻합니다.","帯는 “장식이 달린 허리띠(丗+冖)를 옷(巾) 위에 두르다” -> “허리띠, 두르다, 휴대하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/509/"},"羽":{"id":502,"char":"羽","hun":"깃 우","meaning":"“깃 우”. 깃털, 날개","on":"ウ","kun":"は、はね","explanation":["羽는 “깃털이 달린 새의 날개”를 그린 상형문자입니다."],"sourceUrl":"https://nihongokanji.com/510/"},"努":{"id":503,"char":"努","hun":"힘쓸 노","meaning":"“힘쓸 노”. 힘쓰다, 노력하다","on":"ド","kun":"つと(める)","explanation":["努 = 女 + 又 + 力。","「女」는 “여자”를 뜻합니다.","「又」는 “손”을 뜻합니다.","「力」는 “힘”을 뜻합니다.","努는 “여자(女)를 손(又)에 넣기 위해 열심히 노력하다(力)” -> “힘쓰다, 노력하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/511/"},"固":{"id":504,"char":"固","hun":"굳을 고","meaning":"“굳을 고”. 단단하다, 딱딱하다","on":"コ","kun":"かた(める)、かた(まる)、かた(い)","explanation":["固 = 囗 + 古。","(의미부) 囗는 여기서는 “성벽”을 그린 모양자입니다.","(소리부 겸 의미부) 「古」(コ)는 “오래되다”라는 뜻입니다.","固는 “오래된(古) 성벽(囗)” -> “단단하다, 딱딱하다”라는 뜻의 글자입니다.","(古는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/512/"},"散":{"id":505,"char":"散","hun":"흩을 산","meaning":"“흩을 산”. 흩어지다","on":"サン","kun":"ち(る)、ち(らす)、ち(らかる)、ち(らかす)","explanation":["散 = 龷 + 月 + 攵。","龷는 여기서는 “물건을 널어놓는 장대”를 그린 모양자입니다.","「月」는 “고기”를 뜻합니다.","「攵」는 “때리다, 치다”라는 뜻입니다.","散는 “장대(龷)에 걸어놓은 고기(月)를 마구 두드리다(攵)” -> “흩어지다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/513/"},"司":{"id":506,"char":"司","hun":"맡을 사","meaning":"“맡을 사”. 주관하다, 관리하다, 다스리다","on":"シ","kun":"","explanation":["司 = 𠃌 + 一 + 口。","𠃌+一는 여기서는 “팔로 어딘가를 가리키는 모습”을 그린 모양자입니다.","「口」는 “입”을 뜻합니다.","司는 “팔로 방향을 가리키며(𠃌+一) 지시를 내리다(口)” -> “주관하다, 다스리다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/514/"},"康":{"id":507,"char":"康","hun":"편안할 강","meaning":"“편안할 강”. 무사, 편안, 튼튼","on":"コウ","kun":"","explanation":["康 = 广 + ⺕ + 氺。","「广」는 “집”을 뜻합니다.","「⺕」는 “손”을 뜻합니다.","氺는 여기서는 “동물의 꼬리”를 그린 모양자입니다.","康는 “집(广)에서 애완동물의 꼬리(氺)를 만지며(⺕) 놀다” -> “무사, 편안”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/515/"},"静":{"id":508,"char":"静","hun":"고요할 정","meaning":"“고요할 정”. 고요하다, 조용하다","on":"セイ、ジョウ","kun":"しず、しず(か)、しず(まる)、しず(める)","explanation":["静 = 青 + 争。","(의미부) 「争」는 “다투다, 경쟁하다”라는 뜻입니다.","(소리부 겸 의미부) 「青」(セイ・ショウ)는 “푸르다”라는 뜻입니다.","静는 “싸움(争)이 끝나고 조용해지다(青)” -> “고요하다, 조용하다”라는 뜻의 글자입니다.","(青는 소리부(セイ・ショウ -> セイ・ジョウ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/516/"},"喜":{"id":509,"char":"喜","hun":"기쁠 희","meaning":"“기쁠 희”. 기쁨, 기뻐하다","on":"キ","kun":"よろこ(ぶ)","explanation":["喜 = 壴 + 口。","「壴」는 “북”을 그린 글자입니다(링크 참조).","「口」는 “입”을 뜻합니다.","喜는 “북(壴)을 치고 노래를 부르며(口) 즐거워하다” -> “기뻐하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/517/"},"囲":{"id":510,"char":"囲","hun":"둘레 위","meaning":"“둘레 위”. 두르다, 에워싸다","on":"イ","kun":"かこ(む)、かこ(う)","explanation":["囲 = 囗 + 井。","井(“우물 정”)은 “우물”을 뜻하는 상용한자입니다.","囗는 여기서는 “주위를 둘러싼 벽”을 그린 모양자입니다.","囲는 “우물(井)을 둘러싼 벽(囗)” -> “두르다, 에워싸다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/518/"},"卒":{"id":511,"char":"卒","hun":"마칠 졸","meaning":"“마칠 졸”. 마치다, 졸업, 졸병","on":"ソツ","kun":"","explanation":["卒는 “노비들이 입던 옷”을 그린 상형문자입니다.","전쟁이 나면 가장 먼저 죽어나가는 것은 노예 병사들입니다.","“가장 먼저 죽는 노예들” -> “마치다, 졸업, 졸병”이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/519/"},"順":{"id":512,"char":"順","hun":"순할 순","meaning":"“순할 순”. 온순한, 순종적인, 차례","on":"ジュン","kun":"","explanation":["順 = 川 + 頁。","「川」는 “강, 하천”을 뜻합니다.","「頁」는 “머리”를 뜻합니다.","順는 “물이 아래로 흐르듯(川) 고분고분 머리를 숙이다(頁)” -> “온순한, 순종적인, 차례”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/520/"},"級":{"id":513,"char":"級","hun":"등급 급","meaning":"“등급 급”. 등급, 단계","on":"キュウ","kun":"","explanation":["級 = 糸 + 及。","(의미부) 「糸」는 “실”을 뜻합니다.","(소리부 겸 의미부) 及(キュウ – “미칠 급”)은 “이르다, 미치다”라는 뜻의 상용한자입니다.","級는 “비단(糸)의 등급이 어느 정도에 이르는가(及)” -> “등급, 단계”라는 뜻의 글자입니다.","(及는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/521/"},"幸":{"id":514,"char":"幸","hun":"다행 행","meaning":"“다행 행”. 다행, 행복","on":"コウ","kun":"さいわ(い)、さち、しあわ(せ)","explanation":["幸는 “벽에 고정된 쇠사슬에 묶인 죄인”을 그린 상형문자입니다.","“죄인을 잡아서 다행이다” -> “다행, 행복”이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/522/"},"岩":{"id":515,"char":"岩","hun":"바위 암","meaning":"“바위 암”. 바위, 암석","on":"ガン","kun":"いわ","explanation":["岩 = 山+ 石。","「山」는 “산”을 뜻합니다.","「石」는 “돌”을 뜻합니다.","岩는 “산속(山)의 거대한 돌(石)” -> “암석, 바위”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/523/"},"練":{"id":516,"char":"練","hun":"익힐 련","meaning":"“익힐 련”. 연마하다, 능숙하다","on":"レン","kun":"ね(る)","explanation":["練 = 糸 + 東。","「糸」는 “실”을 뜻합니다.","「東」는 본래 “아침해(日)가 나무(木)에 걸린 모습”을 그린 글자입니다(링크 참조).","練는 “해가 뜰 때까지(東) 밤을 새워 열심히 실(糸)을 짜다” -> “연마하다, 능숙하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/524/"},"等":{"id":517,"char":"等","hun":"무리 등","meaning":"“무리 등”. 같다, 동등하다, 등등","on":"トウ","kun":"ひと(しい)","explanation":["等 = 𥫗 + 寺。","「𥫗」는 “대나무 죽간”을 뜻합니다.","寺(ジ – “절 사”)는 “절, 사찰”을 뜻하는 상용한자입니다.","等는 “절(寺)의 불경(𥫗)을 가지런히 정돈하다” -> “가지런하다” -> “같다, 동등하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/525/"},"救":{"id":518,"char":"救","hun":"구원할 구","meaning":"“구원할 구”. 구해주다","on":"キュウ","kun":"すく(う)","explanation":["救 = 求 + 攵。","(소리부 겸 의미부) 「求」(キュウ)는 “바라다, 구하다”라는 뜻입니다.","(의미부) 「攵」는 “때리다, 치다”라는 뜻입니다.","救는 “도움을 청하는(求) 아군을 구해주다(攵)” -> “구원하다, 구해주다”라는 뜻의 글자입니다.","(求는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/526/"},"老":{"id":519,"char":"老","hun":"늙을 노","meaning":"“늙을 노”. 늙다","on":"ロウ","kun":"お(いる)、ふ(ける)","explanation":["老 = 耂 + 匕。","「耂」는 “노인”을 뜻합니다.","「匕」는 “넘어져있는 사람”을 뜻합니다.","老는 “지쳐서 넘어진(匕) 노인(耂)” -> “노인”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/527/"},"令":{"id":520,"char":"令","hun":"하여금 령","meaning":"“하여금 령”. 명령하다","on":"レイ","kun":"","explanation":["令 = 亼 + 卩。","亼는 여기서는 “왕의 궁궐”을 그린 모양자입니다.","「卩」는 “무릎꿇은 사람”을 뜻합니다.","令는 “왕(亼)이 무릎꿇은 신하(卩)에게 명령을 내리다” -> “명령”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/528/"},"角":{"id":521,"char":"角","hun":"뿔 각","meaning":"“뿔 각”. 뿔, 귀퉁이, 구석","on":"カク","kun":"かど、つの","explanation":["角는 “짐승의 뿔”을 그린 상형문자입니다."],"sourceUrl":"https://nihongokanji.com/529/"},"曲":{"id":522,"char":"曲","hun":"굽을 곡","meaning":"“굽을 곡”. 구부러지다, 곡조","on":"キョク","kun":"ま(がる)、ま(げる)","explanation":["曲는 “구부러진 모양의 자”를 그린 상형문자입니다.","“구부러진 자” -> “구부러지다, 음악, 곡조”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/530/"},"庭":{"id":523,"char":"庭","hun":"뜰 정","meaning":"“뜰 정”. 마당, 뜰, 정원","on":"テイ","kun":"にわ","explanation":["庭 = 广 + 廴 + 壬。","「广」는 “집, 건물”을 뜻합니다.","「廴」는 “길, 걷다”라는 뜻입니다.","壬는 여기서는 “팔을 휘두르며 걷는 사람”을 그린 모양자입니다.","庭는 “저택(广) 안의 뜰을 휘적휘적 걷는(廴) 사람(壬)” -> “정원, 뜰, 마당”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/531/"},"徒":{"id":524,"char":"徒","hun":"무리 도","meaning":"“무리 도”. 길, 무리, 제자","on":"ト","kun":"","explanation":["徒 = 彳 + 走。","「彳」는 “길”을 뜻합니다.","「走」는 “달리다”라는 뜻입니다.","徒는 “같은 길(彳)을 달리는(走) 사람들” -> “길, 무리, 제자”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/532/"},"貨":{"id":525,"char":"貨","hun":"재물 화","meaning":"“재물 화”. 화폐, 재화","on":"カ","kun":"","explanation":["貨 = 化 + 貝。","(소리부) 「化」(カ)는 여기서는 소리부의 역할만 하고 있습니다.","(의미부) 「貝」는 “돈, 재물”을 뜻합니다.","貨는 “돈(貝)” -> “화폐, 재화”라는 뜻의 글자입니다(化는 소리부)."],"sourceUrl":"https://nihongokanji.com/533/"},"血":{"id":526,"char":"血","hun":"피 혈","meaning":"“피 혈”. 피","on":"ケツ","kun":"ち","explanation":["血 = 丶 + 皿。","皿는 “그릇, 접시”를 뜻하는 상용한자입니다.","丶는 여기서는 “핏방울”을 그린 모양자입니다.","血는 “그릇(皿)에 떨어지는 핏방울(丶)” -> “피”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/534/"},"温":{"id":527,"char":"温","hun":"따뜻할 온","meaning":"“따뜻할 온”. 따뜻하다","on":"オン","kun":"あたた(か)、あたた(かい)、あたた(まる)、あたた(める)","explanation":["温 = 氵 + 日 + 皿。","「氵」는 “물”을 뜻합니다.","「日」는 “태양”을 뜻합니다.","皿는 “그릇, 접시”를 뜻하는 상용한자입니다.","温는 “그릇(皿)에 담긴 물(氵)이 햇빛(日)을 받아 따뜻해지다” -> “따뜻하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/535/"},"季":{"id":528,"char":"季","hun":"계절 계","meaning":"“계절 계”. 계절","on":"キ","kun":"","explanation":["季 = 禾 + 子。","「禾」는 “곡식”을 뜻합니다.","「子」는 “어린아이”를 뜻합니다.","季는 “곡식(禾)이 아직 덜 자란(子) 계절” -> “계절”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/536/"},"星":{"id":529,"char":"星","hun":"별 성","meaning":"“별 성”. 별","on":"セイ、ショウ","kun":"ほし","explanation":["星 = 日 + 生。","「日」는 “태양”을 뜻합니다.","「生」는 “생명”을 뜻합니다.","星는 “살아있는(生) 듯이 환하게 빛나는 별(日)” -> “별”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/537/"},"庫":{"id":530,"char":"庫","hun":"곳집 고","meaning":"“곳집 고”. 창고","on":"コ、ク","kun":"","explanation":["庫 = 广 + 車。","「广」는 “집, 건물”을 뜻합니다.","「車」는 “수레, 차”를 뜻합니다.","庫는 “수레(車)를 놓아두는 건물(广)” -> “창고”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/538/"},"欠":{"id":531,"char":"欠","hun":"이지러질 결","meaning":"“이지러질 결”. 부족한, 결함, 이지러진","on":"ケツ","kun":"か(ける)、か(く)","explanation":["欠는 “입을 벌리고 하품하는 사람”을 그린 상형문자입니다.","“하품하다” -> “잠이 부족하다” -> “부족한, 결함의”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/539/"},"坂":{"id":532,"char":"坂","hun":"언덕 판","meaning":"“언덕 판”. 언덕, 비탈","on":"ハン","kun":"さか","explanation":["坂 = 土 + 反。","(의미부) 「土」는 “흙, 땅”을 뜻합니다.","(소리부 겸 의미부) 「反」(ハン)은 여기서는 “비탈길(厂)“을 그린 모양자로 쓰인 것입니다.","坂는 “흙(土)으로 덮인 비탈길(反)” -> “언덕, 비탈”이라는 뜻의 글자입니다.","(反은 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/540/"},"底":{"id":533,"char":"底","hun":"밑 저","meaning":"“밑 저”. 바닥, 밑바닥","on":"テイ","kun":"そこ","explanation":["底 = 广 + 氐。","(의미부) 「广」는 “집, 건물”을 뜻합니다.","(소리부 겸 의미부) 「氐」(テイ)는 “낮다”라는 뜻입니다.","底는 “건물(广)의 밑바닥(氐)” -> “바닥, 밑바닥”이라는 뜻의 글자입니다.","(氐는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/541/"},"寺":{"id":534,"char":"寺","hun":"절 사","meaning":"“절 사”. 절, 사찰","on":"ジ","kun":"てら","explanation":["寺 = 土 + 寸。","「寸」는 “손”을 뜻합니다.","「土」는 “흙”을 뜻합니다.","寺는 “무덤(土)앞에서 합장하는(寸) 스님”이라는 뜻의 글자입니다.","“합장하는 스님” -> “절”이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/542/"},"息":{"id":535,"char":"息","hun":"쉴 식","meaning":"“쉴 식”. 숨쉬다, 휴식","on":"ソク","kun":"いき","explanation":["息 = 自 + 心。","「自」는 본래 “사람의 코”를 그린 글자입니다(링크 참조).","「心」는 본래 “심장”을 그린 글자입니다(링크 참조).","息는 “코(自)와 심장(心)으로 호흡하다” -> “숨쉬다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/543/"},"願":{"id":536,"char":"願","hun":"원할 원","meaning":"“원할 원”. 원하다, 바라다, 소원","on":"ガン","kun":"ねが(う)","explanation":["願 = 原 + 頁。","「原」는 “근원”을 뜻합니다.","「頁」는 “머리”를 뜻합니다.","願는 “머릿속(頁) 깊이(原) 바라는 소원” -> “소원, 원하다, 바라다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/544/"},"絵":{"id":537,"char":"絵","hun":"그림 회","meaning":"“그림 회”. 그림","on":"カイ、エ","kun":"","explanation":["絵 = 糸 + 会。","(의미부) 「糸」는 “실”을 뜻합니다.","(소리부 겸 의미부) 「会」(カイ、エ)는 “만나다”라는 뜻입니다.","絵는 “오색의 실(糸)이 만나(会) 수놓은 문양” -> “그림”이라는 뜻의 글자입니다.","(会는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/545/"},"希":{"id":538,"char":"希","hun":"바랄 희","meaning":"“바랄 희”. 바라다, 드물다","on":"キ","kun":"","explanation":["希 = 爻 + 巾。","「巾」는 “수건, 천”을 뜻합니다.","爻는 여기서는 “천에 새겨넣은 자수”를 그린 모양자입니다.","希는 “많은 사람이 원하는, 자수(爻)가 새겨진 희귀한 천(巾)” -> “바라다, 희귀하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/546/"},"笑":{"id":539,"char":"笑","hun":"웃음 소","meaning":"“웃음 소”. 웃다","on":"ショウ","kun":"わら(う)、え(む)","explanation":["笑 = 𥫗 + 夭。","「𥫗」는 “대나무”를 뜻합니다.","夭는 여기서는 “팔을 휘저으며 뛰어노는 아이”를 그린 모양자입니다.","笑는 “대나무 숲(𥫗)에서 즐겁게 뛰어노는 아이(夭)” -> “웃음, 웃다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/547/"},"束":{"id":540,"char":"束","hun":"묶을 속","meaning":"“묶을 속”. 묶다, 묶음","on":"ソク","kun":"たば","explanation":["束는 “나뭇단을 묶어놓은 모습”을 그린 상형문자입니다."],"sourceUrl":"https://nihongokanji.com/548/"},"仲":{"id":541,"char":"仲","hun":"버금 중","meaning":"“버금 중”. 사람과 사람 사이의 관계","on":"チュウ","kun":"なか","explanation":["仲 = 亻 + 中。","(의미부) 「亻」는 “사람”을 뜻합니다.","(소리부 겸 의미부) 「中」(チュウ)는 “가운데, 중간”을 뜻합니다.","仲는 “사람과 사람(亻) 사이(中)의 관계”라는 뜻의 글자입니다.","(中는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/549/"},"栄":{"id":542,"char":"栄","hun":"영화 영","meaning":"“영화 영”. 번영, 영광","on":"エイ","kun":"さか(える)、は(え)、は(える)","explanation":["栄 = ⺍ + 冖 + 木。","「⺍＋冖」는 “불이 환하게 켜진 집”을 뜻합니다.","「木」는 “나무”를 뜻합니다.","栄는 “밝게 빛나는(⺍+冖) 횃불(木)” -> “영광, 번영”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/550/"},"札":{"id":543,"char":"札","hun":"편지 찰","meaning":"“편지 찰”. 패, 문서, 편지, 명찰 등","on":"サツ","kun":"ふだ","explanation":["札 = 木 + 乚。","「木」는 “나무”를 뜻합니다.","乚는 여기서는 “문패”를 본따 그린 모양자입니다.","札는 “나무(木)로 만든 문패(乚)” -> “문패, 명찰, 문서, 편지”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/551/"},"板":{"id":544,"char":"板","hun":"널빤지 판","meaning":"“널빤지 판”. 판자, 널빤지","on":"ハン、バン","kun":"いた","explanation":["板 = 木 + 反。","(의미부) 「木」는 “나무”를 뜻합니다.","(소리부) 「反」(ハン)은 여기서는 소리부(ハン -> ハン・バン)의 역할만 하고 있습니다.","板는 “나무판자(木)” -> “판자, 널빤지”라는 뜻의 글자입니다(反은 소리부)."],"sourceUrl":"https://nihongokanji.com/552/"},"列":{"id":545,"char":"列","hun":"벌일 열","meaning":"“벌일 열”. 나열하다","on":"レツ","kun":"","explanation":["列 = 歹 + 刂。","「歹」는 “시체”를 뜻합니다.","「刂」는 “칼”을 뜻합니다.","列는 “짐승의 시체(歹)에서 뼈를 분리해(刂) 부위별로 늘어놓다” -> “나열하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/553/"},"節":{"id":546,"char":"節","hun":"마디 절","meaning":"“마디 절”. 마디, 관절","on":"セツ、セチ","kun":"ふし","explanation":["節 = 𥫗 + 即。","「𥫗」는 “대나무”를 뜻합니다.","「卩」는 “무릎꿇은 사람”을 뜻합니다.","即의 왼쪽 부분은 여기서는 글자의 형태를 갖추기 위해 추가된 장식입니다.","節는 “대나무 마디(𥫗) + 무릎 마디(卩)” -> “마디, 관절”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/554/"},"遊":{"id":547,"char":"遊","hun":"놀 유","meaning":"“놀 유”. 놀다","on":"ユウ、ユ","kun":"あそ(ぶ)","explanation":["遊 = ⻌ + 𭤨 + 子。","「⻌」는 “길”을 뜻합니다.","「𭤨」는 “바람에 나부끼는 깃발”을 뜻합니다.","「子」는 “아이”를 뜻합니다.","遊는 “길(⻌)에서 깃발을 흔들며(𭤨) 노는 어린아이(子)” -> “놀다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/555/"},"君":{"id":548,"char":"君","hun":"임금 군","meaning":"“임금 군”. 군주, 임금, 당신","on":"クン","kun":"きみ","explanation":["君 = ⺕ + 丿 + 口。","「⺕」는 “손”을 뜻합니다.","丿는 여기서는 “붓”을 그린 모양자입니다.","「口」는 “입”을 뜻합니다.","君는 “붓(丿)을 들고(⺕) 칙서를 쓰며 명령(口)을 내리는 군주” -> “군주, 임금”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/556/"},"包":{"id":549,"char":"包","hun":"쌀 포","meaning":"“쌀 포”. 감싸다","on":"ホウ","kun":"つつ(む)","explanation":["包 = 勹 + 己。","勹는 여기서는 “자궁”을 그린 모양자입니다.","「己」는 “몸을 웅크린 사람”을 뜻합니다. 여기서는 “태아”를 표현한 것입니다.","包는 “자궁(勹)에 감싸인 태아(己)” -> “감싸다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/557/"},"折":{"id":550,"char":"折","hun":"꺾을 절","meaning":"“꺾을 절”. 꺾다, 꺾이다, 나누다","on":"セツ","kun":"お(る)、お(れる)、おり","explanation":["折 = 扌 + 斤。","「扌」는 “손”을 뜻합니다.","「斤」는 “도끼”를 뜻합니다.","折는 “도끼(斤)를 들고(扌) 나무를 베다” -> “꺾다, 꺾이다, 나누다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/558/"},"草":{"id":551,"char":"草","hun":"풀 초","meaning":"“풀 초”. 풀","on":"ソウ","kun":"くさ","explanation":["草 = 艹 + 早。","(의미부) 「艹」는 “풀”을 뜻합니다.","(소리부) 「早」(ソウ)는 여기서는 소리부의 역할만 하고 있습니다.","草는 “풀(艹)” -> “풀”이라는 뜻의 글자입니다(早는 소리부)."],"sourceUrl":"https://nihongokanji.com/559/"},"焼":{"id":552,"char":"焼","hun":"불사를 소","meaning":"“불사를 소”. 불사르다, 태우다, 굽다","on":"ショウ","kun":"や(く)、や(ける)","explanation":["焼 = 火 + 十 + 艹 + 兀。","「火」는 “불”을 뜻합니다.","兀는 여기서는 “화로”를 그린 모양자입니다.","「艹」는 “풀”을 뜻합니다.","十는 여기서는 “꼬챙이(丨)에 꿴 고기(一)”를 그린 모양자입니다.","焼는 “화로(兀) 위에서 야채(艹)와 고기(十)를 굽다(火)” -> “불사르다, 태우다, 굽다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/560/"},"章":{"id":553,"char":"章","hun":"글 장","meaning":"“글 장”. 글, 문장, 무늬","on":"ショウ","kun":"","explanation":["章 = 辛 + 日。","「辛」는 “문신을 새기는 고문 도구”를 뜻합니다.","日는 여기서는 “(새겨진) 문신, 표식”을 그린 모양자입니다.","章는 “노예의 몸에 새겨진(辛) 표식(日)” -> “글, 문장, 무늬”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/561/"},"照":{"id":554,"char":"照","hun":"비칠 조","meaning":"“비칠 조”. (빛을) 비추다, 쬐다","on":"ショウ","kun":"て(る)、て(らす)、て(れる)","explanation":["照 = 日 + 召 + 灬。","(의미부) 「日」는 “태양”을 뜻합니다.","(의미부) 「灬」는 “불”을 뜻합니다.","(소리부 겸 의미부) 召(ショウ – 부를 소)는 “부르다”라는 뜻의 상용한자입니다.","照는 “불빛(日+灬)을 불러들이다(召)” -> “(빛을) 비추다, 쬐다”라는 뜻의 글자입니다.","(召는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/562/"},"酒":{"id":555,"char":"酒","hun":"술 주","meaning":"“술 주”. 술","on":"シュ","kun":"さけ、さか","explanation":["酒 = 氵 + 酉。","「氵」는 “물”을 뜻합니다.","「酉」는 “술병, 술”을 뜻합니다.","酒는 “술병(酉)에 담긴 액체(氵)” -> “술”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/563/"},"悲":{"id":556,"char":"悲","hun":"슬플 비","meaning":"“슬플 비”. 슬프다","on":"ヒ","kun":"かな(しい)、かな(しむ)","explanation":["悲 = 非 + 心。","(소리부 겸 의미부) 非(ヒ- “아닐 비”)는 “아니다, 잘못되다”라는 뜻의 상용한자입니다.","(의미부) 「心」는 “마음”을 뜻합니다.","悲는 “마음(心)이 영 아니다(非)” -> “슬프다”라는 뜻의 글자입니다.","(非는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/564/"},"秒":{"id":557,"char":"秒","hun":"분초 초","meaning":"“분초 초”. 1초","on":"ビョウ","kun":"","explanation":["秒 = 禾 + 少。","「禾」는 “곡식”을 뜻합니다.","「少」는 “적다”라는 뜻입니다.","秒는 “작디작은(少) 곡식 알갱이(禾)” -> “아주 짧은 시간” -> “1초”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/565/"},"晴":{"id":558,"char":"晴","hun":"갤 청","meaning":"“갤 청”. 날이 개다, 맑은 날씨","on":"セイ","kun":"は(れる)、は(らす)","explanation":["晴 = 日 + 青。","(의미부) 「日」는 “태양”을 뜻합니다.","(소리부 겸 의미부) 「青」(セイ)는 “푸르다”라는 뜻입니다.","晴는 “푸르게(青) 갠 맑은(日) 하늘” -> “맑은 날씨, 날이 개다”라는 뜻의 글자입니다.","(青는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/566/"},"陽":{"id":559,"char":"陽","hun":"볕 양","meaning":"“볕 양”. 볕, 햇빛, 양기","on":"ヨウ","kun":"","explanation":["陽 = ⻖ + 昜。","(의미부) 「⻖」는 “언덕”을 뜻합니다.","(소리부 겸 의미부) 「昜」(ヨウ)는 “햇빛, 뜨거운 햇살”을 뜻합니다.","陽는 “언덕(⻖) 위 높이 내리쬐는 태양(昜)” -> “볕, 햇빛, 양기”라는 뜻의 글자입니다.","(昜는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/567/"},"皮":{"id":560,"char":"皮","hun":"가죽 피","meaning":"“가죽 피”. 가죽, 모피, 표면","on":"ヒ","kun":"かわ","explanation":["皮 = 厂 + 丨 + 又。","厂+丨는 여기서는 “동물의 가죽(厂)과 뿔(丨)”을 그린 모양자입니다.","「又」는 “손”을 뜻합니다.","皮는 “동물의 가죽(厂+丨)을 벗기다(又)” -> “가죽, 껍질, 표면”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/568/"},"漁":{"id":561,"char":"漁","hun":"고기잡을 어","meaning":"“고기잡을 어”. 낚시","on":"ギョ、リョウ","kun":"","explanation":["漁 = 氵 + 魚。","(의미부) 「氵」는 “물”을 뜻합니다.","(소리부 겸 의미부) 「魚」(ギョ)는 “물고기”를 뜻합니다.","漁는 “물(氵) 속의 물고기(魚)를 잡다” -> “낚시”라는 뜻의 글자입니다.","(魚는 소리부(ギョ -> ギョ・リョウ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/569/"},"貯":{"id":562,"char":"貯","hun":"쌓을 저","meaning":"“쌓을 저”. 저축하다, 쌓다","on":"チョ","kun":"","explanation":["貯 = 貝 + 宁。","「貝」는 “돈, 재물”을 뜻합니다.","宁는 여기서는 “금고”를 그린 모양자입니다.","貯는 “금고(宁)에 돈(貝)을 모아놓다” -> “저축하다, 쌓다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/570/"},"歯":{"id":563,"char":"歯","hun":"이 치","meaning":"“이 치”. 이, 치아","on":"シ","kun":"は","explanation":["歯 = 止 + 米 + 凵。","(소리부) 「止」(シ)는 여기서는 소리부의 역할만 하고 있습니다.","(의미부) 米+凵는 여기서는 “치아가 난 모습”을 그린 모양자입니다. 아래 그림을 참조해 주세요.","歯는 “치아(米+凵)” -> “이, 치아”라는 뜻의 글자입니다(止는 소리부)."],"sourceUrl":"https://nihongokanji.com/571/"},"柱":{"id":564,"char":"柱","hun":"기둥 주","meaning":"“기둥 주”. 기둥","on":"チュウ","kun":"はしら","explanation":["柱 = 木 + 主。","(의미부) 「木」는 “나무”를 뜻합니다.","(소리부 겸 의미부) 「主」(シュ)는 “주인, 주축”을 뜻합니다.","柱는 “가옥의 주축(主)이 되는 나무기둥(木)” -> “기둥”이라는 뜻의 글자입니다.","(主는 소리부(シュ -> チュウ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/572/"},"祭":{"id":565,"char":"祭","hun":"제사 제","meaning":"“제사 제”. 제사, 의식, 축제","on":"サイ","kun":"まつ(る)、まつ(り)","explanation":["祭 = 月 + 又 + 示。","「月」는 “고기”를 뜻합니다.","「又」는 “손”을 뜻합니다.","「示」는 “신, 종교, 고대의 비석”을 뜻합니다.","祭는 “제사상(示) 위에 고기(月)를 올리다(又)” -> “제사, 의식, 축제”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/573/"},"雪":{"id":566,"char":"雪","hun":"눈 설","meaning":"“눈 설”. 눈","on":"セツ","kun":"ゆき","explanation":["雪 = 雨 + ヨ。","「雨」는 “비”를 뜻합니다.","ヨ는 여기서는 「帚」가 축약된 것으로, “빗자루”를 뜻합니다.","雪는 “쌓인 눈(雨)을 빗자루(帚)로 쓸어내다” -> “눈”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/574/"},"筆":{"id":567,"char":"筆","hun":"붓 필","meaning":"“붓 필”. 붓, 필기","on":"ヒツ","kun":"ふで","explanation":["筆 = 𥫗 + 聿。","「𥫗」는 “대나무”를 뜻합니다.","「聿」는 “붓을 든 손”을 뜻합니다.","筆는 “대나무(竹)로 만든 붓(聿)” -> “붓, 필기”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/575/"},"訓":{"id":568,"char":"訓","hun":"가르칠 훈","meaning":"“가르칠 훈”. 가르치다, 훈계","on":"クン","kun":"","explanation":["訓 = 言 + 川。","「言」는 “말하다”라는 뜻입니다.","「川」는 “강, 하천”을 뜻합니다.","訓는 “가르침(言)을 내리다(川)” -> “가르치다, 훈계”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/576/"},"浴":{"id":569,"char":"浴","hun":"목욕할 욕","meaning":"“목욕할 욕”. 목욕하다","on":"ヨク","kun":"あ(びる)、あ(びせる)","explanation":["浴 = 氵 + 谷。","「氵」는 “물”을 뜻합니다.","「谷」는 “계곡, 골짜기”를 뜻합니다.","浴는 “계곡(谷)에서 몸을 씻다(氵)” -> “목욕하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/577/"},"童":{"id":570,"char":"童","hun":"아이 동","meaning":"“아이 동”. 아이, 어린이","on":"ドウ","kun":"わらべ","explanation":["童 = 立 + 里。","「立」는 “서다”라는 뜻입니다.","「里」는 “마을”을 뜻합니다.","童는 “마을(里)을 돌아다니며(立) 노는 어린아이” -> “아이, 어린이”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/578/"},"塩":{"id":571,"char":"塩","hun":"소금 염","meaning":"“소금 염”. 소금","on":"エン","kun":"しお","explanation":["塩 = 土 + 𠂉 + 口 + 皿。","「土」는 “흙”을 뜻합니다. 여기서는 “소금 알갱이”를 흙에 비유한 것입니다.","皿는 “그릇, 접시”를 뜻하는 상용한자입니다.","𠂉 + 口는 여기서는 “그릇의 뚜껑”을 그린 모양자입니다.","塩는 “소금(土)이 담긴 그릇(皿)과 뚜껑(𠂉 + 口)” -> “소금”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/579/"},"兆":{"id":572,"char":"兆","hun":"조 조","meaning":"“조 조”. 징조, 전조, 1조(수의 단위)","on":"チョウ","kun":"きざ(す)、きざ(し)","explanation":["兆는 “거북의 등껍질에 나타난 점괘”를 그린 상형문자입니다.","“등껍질에 나타난 점괘” -> “징조, 전조, 징후”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/580/"},"畑":{"id":573,"char":"畑","hun":"화전 전","meaning":"“화전 전”. 밭","on":"","kun":"はた、はたけ","explanation":["畑 = 火 + 田。","「火」는 “불”을 뜻합니다.","「田」는 “밭”을 뜻합니다.","畑는 “산을 태워서(火) 만든 화전(田)” -> “밭”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/581/"},"毛":{"id":574,"char":"毛","hun":"터럭 모","meaning":"“터럭 모”. 털","on":"モウ","kun":"け","explanation":["毛는 “새의 깃털”을 그린 상형문자입니다."],"sourceUrl":"https://nihongokanji.com/582/"},"緑":{"id":575,"char":"緑","hun":"초록빛 록","meaning":"“초록빛 록”. 녹색","on":"リョク、ロク","kun":"みどり","explanation":["緑 = 糸 + 录。","「糸」는 “실”을 뜻합니다.","「录」는 “염색하다”라는 뜻입니다.","緑는 “실(糸)을 초록색으로 염색하다(录)” -> “초록색”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/583/"},"祝":{"id":576,"char":"祝","hun":"빌 축","meaning":"“빌 축”. 기원하다, 축하하다","on":"シュク、シュウ","kun":"いわ(う)","explanation":["祝 = 礻 + 兄。","「礻」는 “종교, 신, 고대의 비석”을 뜻합니다.","「兄」는 “형”을 뜻합니다.","祝는 “장남(兄)의 탄생을 기원하다(礻)” -> “기원하다, 축하하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/584/"},"礼":{"id":577,"char":"礼","hun":"예절 예","meaning":"“예절 예”. 예의, 예절","on":"レイ、ライ","kun":"","explanation":["礼 = 礻 + 乚。","「礻」는 “종교, 신, 고대의 비석”을 뜻합니다.","乚는 여기서는 “엎드려 절하는 모습”을 그린 모양자입니다.","礼는 “신(礻)에게 절(乚)을 올리다” -> “예절, 예의”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/585/"},"昔":{"id":578,"char":"昔","hun":"옛 석","meaning":"“옛 석”. 옛날","on":"セキ、シャク","kun":"むかし","explanation":["昔 = 龷 + 日。","龷는 여기서는 巛가 변형된 것으로, “큰 물살/홍수”를 표현한 모양자입니다.","「日」는 “해”를 뜻합니다.","昔는 “물(巛) 아래 잠긴 태양(日)”이라는 뜻으로, 본래는 약 4300년 전 일어난 중국의 대홍수를 뜻하던 글자입니다.","그러나 시간이 지나며 “대홍수” -> “먼 옛날의 일” -> “옛날”이 되어 지금의 의미를 가지게 되었습니다."],"sourceUrl":"https://nihongokanji.com/586/"},"衣":{"id":579,"char":"衣","hun":"옷 의","meaning":"“옷 의”. 옷","on":"イ","kun":"ころも","explanation":["衣는 “윗옷”을 그린 상형문자입니다."],"sourceUrl":"https://nihongokanji.com/587/"},"泳":{"id":580,"char":"泳","hun":"헤엄칠 영","meaning":"“헤엄칠 영”. 수영하다","on":"エイ","kun":"およ(ぐ)","explanation":["泳 = 氵 + 永。","(의미부) 「氵」는 “물”을 뜻합니다.","(소리부 겸 의미부) 永(エイ – “길 영”)은 “길다, 영원하다”라는 뜻의 상용한자입니다.","泳는 “길게 뻗은(永) 강물(氵)에서 헤엄치다” -> “헤엄치다”라는 뜻의 글자입니다.","(永는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/588/"},"荷":{"id":581,"char":"荷","hun":"멜 하","meaning":"“멜 하”. 짐, 짊어지다","on":"カ","kun":"に","explanation":["荷 = 艹 + 何。","(의미부 겸 소리부) 「何」(カ)는 본래 “짐보따리를 멘 사람”을 그린 글자입니다(링크 참조).","(의미부) 「艹」는 “풀”을 뜻합니다.","荷는 “건초 더미(艹)를 짊어진 사람(何)” -> “짐, 짊어지다”라는 뜻의 글자입니다.","(何는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/589/"},"黄":{"id":582,"char":"黄","hun":"누를 황","meaning":"“누를 황”. 노랑","on":"コウ、オウ","kun":"き、こ","explanation":["黄는 “황금으로 만든 장신구를 허리에 두른 황제”를 그린 상형문자입니다.","“황금을 두른 황제” -> “황금” -> “노란색”이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/590/"},"臣":{"id":583,"char":"臣","hun":"신하 신","meaning":"“신하 신”. 신하","on":"シン、ジン","kun":"","explanation":["臣는 “고개숙인 사람의 눈동자”를 그린 상형문자입니다.","옛날에는 신하는 왕과 눈을 마주칠 수 없었다고 합니다.","臣는 “고개숙인 신하의 눈” -> “신하”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/591/"},"浅":{"id":584,"char":"浅","hun":"얕을 천","meaning":"“얕을 천”. 얕다","on":"セン","kun":"あさ(い)","explanation":["浅 = 氵 + 㦮。","(의미부) 「氵」는 “물”을 뜻합니다.","(소리부 겸 의미부) 「㦮」(セン)은 “피와 살점이 묻은 창”을 뜻합니다.","浅는 “얕은 개울가(氵)에서 피묻은 창(㦮)을 씻어내다” -> “얕다”라는 뜻의 글자입니다.","(㦮은 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/592/"},"雲":{"id":585,"char":"雲","hun":"구름 운","meaning":"“구름 운”. 구름","on":"ウン","kun":"くも","explanation":["雲 = 雨 + 云。","「雨」는 “비”를 뜻합니다.","「云」는 “구름”을 뜻합니다.","雲는 “비(雨) 구름(云)” -> “구름”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/593/"},"鳴":{"id":586,"char":"鳴","hun":"울 명","meaning":"“울 명”. (동물의) 울음소리, 울리다","on":"メイ","kun":"な(く)、な(る)、な(らす)","explanation":["鳴 = 口 + 鳥。","「口」는 “입”을 뜻합니다.","「鳥」는 “새”를 뜻합니다.","鳴는 “새(鳥)가 지저귀다(口)” -> “울음소리, 울리다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/594/"},"炭":{"id":587,"char":"炭","hun":"숯 탄","meaning":"“숯 탄”. 숯, 석탄","on":"タン","kun":"すみ","explanation":["炭 = 山 + 厂 + 火。","「山」는 “산”을 뜻합니다.","「厂」는 “기슭, 절벽”을 뜻합니다.","「火」는 “불”을 뜻합니다.","炭는 “산불(山+火)로 불탄 나무가 지반에 묻혀서(厂) 만들어진 숯” -> “숯, 석탄”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/595/"},"勇":{"id":588,"char":"勇","hun":"날랠 용","meaning":"“날랠 용”. 용기, 용맹","on":"ユウ","kun":"いさ(む)","explanation":["勇 = マ + 男。","マ는 여기서는 “투구”를 그린 모양자입니다.","「男」는 “남성”을 뜻합니다.","勇는 “투구(マ)를 쓴 남성(男)” -> “용기, 용맹”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/596/"},"械":{"id":589,"char":"械","hun":"기계 계","meaning":"“기계 계”. 기계, 도구","on":"カイ","kun":"","explanation":["械 = 木 + 戒。","(의미부) 「木」는 “나무”를 뜻합니다.","(소리부 겸 의미부) 戒(カイ – “경계할 계”)는 “창을 든 병사”를 그린 상용한자입니다.","여기서는 “창을 든 병사” -> “병장기”라는 뜻으로 쓰인 것입니다.","械는 ” 나무(木)로 만든 병장기(戒)” -> “기계”라는 뜻의 글자입니다.","(戒는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/597/"},"湖":{"id":590,"char":"湖","hun":"호수 호","meaning":"“호수 호”. 호수","on":"コ","kun":"みずうみ","explanation":["湖 = 氵 + 古 + 月。","(의미부) 「氵」는 “물”을 뜻합니다.","(소리부 겸 의미부) 「古」(コ)는 “오래되다”라는 뜻입니다.","(의미부) 「月」는 “달”을 뜻합니다.","湖는 “달빛(月)을 받아 빛나는 오래된(古) 호수(氵)” -> “호수”라는 뜻의 글자입니다.","(古는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/598/"},"虫":{"id":591,"char":"虫","hun":"벌레 충","meaning":"“벌레 충”. 벌레","on":"チュウ","kun":"むし","explanation":["虫는 “뿔이 달린 벌레”를 그린 상형문자입니다."],"sourceUrl":"https://nihongokanji.com/599/"},"刷":{"id":592,"char":"刷","hun":"인쇄할 쇄","meaning":"“인쇄할 쇄”. 인쇄하다","on":"サツ","kun":"す(る)","explanation":["刷 = 尸 + 巾 + 刂。","「尸」는 “집, 지붕”을 뜻합니다(링크 참조).","「巾」는 “수건, 천”을 뜻합니다.","「刂」는 “칼”을 뜻합니다.","刷는 “목판에 새긴(刂) 글을 천(巾)에 찍어내는 인쇄소(尸)” -> “인쇄하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/600/"},"湯":{"id":593,"char":"湯","hun":"끓일 탕","meaning":"“끓일 탕”. 뜨거운 물","on":"トウ","kun":"ゆ","explanation":["湯 = 氵 + 昜。","「氵」는 “물”을 뜻합니다.","「昜」는 “햇볕, 뜨거운 햇살”을 뜻합니다.","湯는 “뜨거운 햇볕(昜) 에 달궈진 물(氵)” -> “뜨거운 물”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/601/"},"箱":{"id":594,"char":"箱","hun":"상자 상","meaning":"“상자 상”. 상자","on":"","kun":"はこ","explanation":["箱 = 𥫗 + 木 + 目。","「𥫗」는 “대나무”를 뜻합니다.","「木」는 “나무”를 뜻합니다.","目는 여기서는 “네모난 상자”를 그린 모양자입니다.","箱는 “대나무(竹)로 만든 나무(木) 상자(目)” -> “상자”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/602/"},"泣":{"id":595,"char":"泣","hun":"울 읍","meaning":"“울 읍”. 울다","on":"キュウ","kun":"な(く)","explanation":["泣 = 氵 + 立。","「氵」는 “물”을 뜻합니다.","「立」는 “서다”라는 뜻입니다.","泣는 “혼자 외롭게 서서(立) 구슬프게 울다(氵)” -> “울다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/603/"},"孫":{"id":596,"char":"孫","hun":"손자 손","meaning":"“손자 손”. 손자, 후손","on":"ソン","kun":"まご","explanation":["孫 = 子 + 系。","「子」는 “아이”를 뜻합니다.","系(“이어맬 계”)는 “계통”을 뜻하는 상용한자입니다.","孫는 “혈통(系)을 이어갈 아들(子)” -> “손자”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/604/"},"毒":{"id":597,"char":"毒","hun":"독 독","meaning":"“독 독”. 독","on":"ドク","kun":"","explanation":["毒 = 龶 + 毋。","龶는 여기서는 “(독이 든) 버섯”을 그린 모양자입니다.","「毋」는 “어머니”를 뜻합니다.","아기에게 젖을 물려야 하는 산모는 늘 먹을 것에 주의해야 합니다.","毒는 “어미(毋)가 먹으면 안 되는 독버섯(龶)” -> “독”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/605/"},"氷":{"id":598,"char":"氷","hun":"얼음 빙","meaning":"“얼음 빙”. 얼음","on":"ヒョウ","kun":"こおり、ひ","explanation":["氷 = 水 + 丶。","「水」는 “물”을 뜻합니다.","丶는 여기서는 水와 구분하기 위해 추가된 장식입니다.","氷는 “물(水)이 얼다(丶)” -> “얼음”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/606/"},"拾":{"id":599,"char":"拾","hun":"주울 습","meaning":"“주울 습”. 줍다","on":"シュウ","kun":"ひろ(う)","explanation":["拾 = 扌 + 合。","「扌」는 “손”을 뜻합니다.","「合」는 “합치다”라는 뜻입니다.","拾는 “주워(扌) 모으다(合)” -> “줍다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/607/"},"粉":{"id":600,"char":"粉","hun":"가루 분","meaning":"“가루 분”. 가루","on":"フン","kun":"こ、こな","explanation":["粉 = 米 + 分。","(의미부) 「米」는 “쌀”을 뜻합니다.","(소리부 겸 의미부) 「分」(フン)은 “나누다”라는 뜻입니다.","粉는 “쌀알(米)을 잘게 부수다(分)” -> “가루”라는 뜻의 글자입니다.","(分은 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/608/"},"糸":{"id":601,"char":"糸","hun":"실 사","meaning":"“실 사”. 실","on":"シ","kun":"いと","explanation":["糸는 “실타래”를 그린 상형문자입니다."],"sourceUrl":"https://nihongokanji.com/609/"},"才":{"id":602,"char":"才","hun":"재주 재","meaning":"“재주 재”. 재능","on":"サイ","kun":"","explanation":["才는 “땅 위로 새싹이 올라오는 모습”을 그린 상형문자입니다.","“새로 올라오는 새싹” -> “싹수가 보인다” -> “재능”이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/610/"},"灯":{"id":603,"char":"灯","hun":"등잔 등","meaning":"“등잔 등”. 등, 등잔","on":"トウ","kun":"ひ","explanation":["灯 = 火 + 丁。","「火」는 “불”을 뜻합니다.","丁는 여기서는 “등잔”을 그린 모양자입니다.","灯는 “등잔(丁)의 불빛(火)” -> “등, 등잔”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/611/"},"麦":{"id":604,"char":"麦","hun":"보리 맥","meaning":"“보리 맥”. 보리","on":"バク","kun":"むぎ","explanation":["麦는 “보리 이삭”을 그린 상형문자입니다."],"sourceUrl":"https://nihongokanji.com/612/"},"鼻":{"id":605,"char":"鼻","hun":"코 비","meaning":"“코 비”. 코","on":"ビ","kun":"はな","explanation":["鼻 = 自 + 田 + 廾。","「自」는 본래 “코”를 그린 상형문자입니다(링크 참조).","田는 여기서는 “콧구멍”을 그린 모양자입니다.","廾는 여기서는 “인중”을 그린 모양자입니다.","鼻는 “코(自) + 콧구멍(田) + 인중(廾)” -> “코”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/613/"},"胃":{"id":606,"char":"胃","hun":"밥통 위","meaning":"“밥통 위”. 위(위장)","on":"イ","kun":"","explanation":["胃 = 田 + 月。","田는 여기서는 “사람의 위”를 그린 모양자입니다.","「月」는 “신체의 일부”를 뜻합니다(링크 참조).","胃는 “사람의 위(田) + 신체의 일부(月)” -> “위”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/614/"},"貝":{"id":607,"char":"貝","hun":"조개 패","meaning":"“조개 패”. 조개","on":"","kun":"かい","explanation":["貝는 “조개껍질”을 본따 그린 상형문자입니다."],"sourceUrl":"https://nihongokanji.com/615/"},"皿":{"id":608,"char":"皿","hun":"그릇 명","meaning":"“그릇 명”. 그릇, 접시","on":"","kun":"さら","explanation":["皿는 “음식을 담는 그릇”을 그린 상형문자입니다."],"sourceUrl":"https://nihongokanji.com/616/"},"政":{"id":609,"char":"政","hun":"정사 정","meaning":"“정사 정”. 정치","on":"セイ、ショウ","kun":"まつりごと","explanation":["政 = 正 + 攵。","(의미부 겸 소리부) 「正」(セイ・ショウ)는 “바르다”라는 뜻입니다.","(의미부) 「攵」는 “때리다, 치다”라는 뜻입니다.","政는 “잘못된 일들을 때려서(攵) 바로잡다(正)” -> “다스리다” -> “정치”라는 뜻의 글자입니다.","(正는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/617/"},"党":{"id":610,"char":"党","hun":"무리 당","meaning":"“무리 당”. 무리, 세력, 정당","on":"トウ","kun":"","explanation":["党 = 龸 + 兄。","「龸」는 “궁궐”을 뜻합니다.","「兄」는 “형, 맏이”를 뜻합니다.","党는 “우두머리(兄)를 중심으로 한 궁궐(龸)의 파벌” -> “무리, 세력, 정당”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/618/"},"経":{"id":611,"char":"経","hun":"지날 경","meaning":"“지날 경”. 경로, 경과, 경도(남북 방향), 경전","on":"ケイ、キョウ","kun":"へ(る)","explanation":["経 = 糸 + 圣。","(의미부) 「糸」는 “실”을 뜻합니다.","(소리부 겸 의미부) 「圣」(ケイ・キョウ)는 “지나가다”라는 뜻입니다.","経는 “베틀 사이로 날실(糸)이 지나가다(圣)” -> “지나가다, 경로, 경과”라는 뜻의 글자입니다.","(圣는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/619/"},"現":{"id":612,"char":"現","hun":"나타날 현","meaning":"“나타날 현”. 나타나다, 드러나다","on":"ゲン","kun":"あらわ(れる)、あらわ(す)","explanation":["現 = 𤣩 + 見。","「𤣩」는 “구슬, 보석”을 뜻합니다.","「見」는 “보다”라는 뜻입니다.","現는 “숨겨진 보석(𤣩)이 드러나다(見)” -> “나타나다, 드러나다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/620/"},"性":{"id":613,"char":"性","hun":"성품 성","meaning":"“성품 성”. 성별, 본성, 천성","on":"セイ、ショウ","kun":"","explanation":["性 = 忄 + 生。","(의미부) 「忄」는 “마음”을 뜻하는 부수입니다(링크 참조).","(소리부 겸 의미부) 「生」(セイ・ショウ)는 “태어나다”라는 뜻입니다.","性는 “타고난(生) 마음(忄)” -> “성별, 본성, 천성”이라는 뜻의 글자입니다.","(生는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/621/"},"制":{"id":614,"char":"制","hun":"절제할 제","meaning":"“절제할 제”. 제어, 제도, 절제, 억제, 통제","on":"セイ","kun":"","explanation":["制 = 牛 + 巾 + 刂。","「牛」는 “소”를 뜻합니다.","「巾」는 “수건, 천”을 뜻합니다.","「刂」는 “칼”을 뜻합니다.","制는 “소(牛)에게 농기구를 씌우고(巾) 밭을 갈다(刂)”라는 뜻입니다.","“소를 제어해서 농사를 짓다” -> “제어, 제도, 통제, 억제”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/622/"},"務":{"id":615,"char":"務","hun":"힘쓸 무","meaning":"“힘쓸 무”. 힘쓰다, 종사하다","on":"ム","kun":"つと(める)、つと(まる)","explanation":["務 = 矛 + 攵 + 力。","(소리부 겸 의미부) 矛(ム – “창 모”)는 “창”을 뜻하는 상용한자입니다.","(의미부) 「攵」는 “때리다, 치다”라는 뜻입니다.","(의미부) 「力」는 “힘”을 뜻합니다.","務는 “창(矛)으로 힘껏(力) 찌르다(攵)” -> “힘쓰다, 종사하다”라는 뜻의 글자입니다.","(矛는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/623/"},"総":{"id":616,"char":"総","hun":"거느릴 총","meaning":"“거느릴 총”. 전체, 총합","on":"ソウ","kun":"","explanation":["総 = 糸 + 公 + 心。","「糸」는 “실”을 뜻합니다.","「公」는 “공공의, 공적인”이라는 뜻입니다.","「心」는 “마음”을 뜻합니다.","総는 “국민(公)의 마음(心)을 하나로 묶다(糸)” -> “전체, 총합”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/624/"},"領":{"id":617,"char":"領","hun":"거느릴 령","meaning":"“거느릴 령”. 다스리다, 점유하다, 중요한 부분","on":"リョウ","kun":"","explanation":["領 = 令 + 頁。","「令」는 “명령”을 뜻합니다.","「頁」는 “머리”를 뜻합니다.","領는 “명령(令)을 내리는 우두머리(頁)” -> “다스리다, 점령하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/625/"},"設":{"id":618,"char":"設","hun":"베풀 설","meaning":"“베풀 설”. 설치하다, 마련하다","on":"セツ","kun":"もう(ける)","explanation":["設 = 言 + 殳。","「言」는 “말하다”라는 뜻입니다.","「殳」는 본래 “채찍을 휘두르는 손”을 그린 글자입니다(링크 참조).","設는 “채찍을 휘두르며(殳) 노예들에게 소리치다(言)”라는 뜻입니다.","“노예들을 시켜 건물을 짓다” -> “설치하다, 마련하다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/626/"},"保":{"id":619,"char":"保","hun":"지킬 보","meaning":"“지킬 보”. 지키다, 보살피다","on":"ホ","kun":"たも(つ)","explanation":["保 = 亻 + 呆。","「亻」는 “사람”을 뜻합니다.","呆는 여기서는 “등에 업힌 아기”를 그린 모양자입니다.","保는 “아기를 등에 업은(呆) 사람(亻)” -> “지키다, 보살피다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/627/"},"権":{"id":620,"char":"権","hun":"권세 권","meaning":"“권세 권”. 권력, 권세, 권리","on":"ケン、ゴン","kun":"","explanation":["権 = 𮥶 + 隹。","(의미부 겸 소리부) 「𮥶」(カン)은 “새장 안의 새”를 뜻합니다.","(의미부) 「木」는 “나무”를 뜻합니다.","権는 “나무(木) 위의 새를 잡아 가두다(𮥶)”라는 뜻입니다.","“아무나 마음대로 잡아 가둘 수 있는 무소불위의 권력” -> “권력, 권세, 권리”라는 의미입니다.","(𮥶는 소리부(カン -> ケン)도 겸함)"],"sourceUrl":"https://nihongokanji.com/628/"},"支":{"id":621,"char":"支","hun":"지탱할 지","meaning":"“지탱할 지”. 지탱하다, 지지하다, (갈라져 나온) 지류","on":"シ","kun":"ささ(える)","explanation":["支 = 十 + 又。","十는 여기서는 “나뭇가지”를 그린 모양자입니다.","「又」는 “손”을 뜻합니다.","支는 “나무에서 갈라져 나온 가지(十)를 받쳐든 손(又)” -> “지탱하다, 지지하다, 지류”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/629/"},"報":{"id":622,"char":"報","hun":"갚을/알릴 보","meaning":"“갚을/알릴 보”. 갚다, 알리다","on":"ホウ","kun":"むく(いる)","explanation":["報 = 幸 + 卩 + 又。","「幸」는 본래 “쇠사슬에 묶인 죄인”을 그린 글자입니다(링크 참조).","「卩」는 “무릎꿇은 사람”을 뜻합니다.","「又」는 “손”을 뜻합니다.","報는 “죄인(卩)을 잡아서(又) 쇠사슬에 묶어놓다(幸)”라는 뜻입니다.","“죄수를 붙잡았다는 사실을 알리다” -> “알리다”","“죄수가 죗값을 치르다” -> “갚다”","라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/630/"},"済":{"id":623,"char":"済","hun":"건널 제","meaning":"“건널 제”. 이루다, 끝나다, 마치다, 구하다","on":"サイ","kun":"す(む)、す(ます)","explanation":["済 = 氵 + 斉。","「氵」는 “물”을 뜻합니다.","斉는 여기서는 “다리를 건너는 사람”을 그린 모양자입니다.","(위쪽의 文는 “사람”을 그린 것이고, 아래쪽은 “다리”를 그린 것입니다.)","済는 “강(氵)에 걸린 다리를 끝까지 건너다(斉)” -> “끝나다, 마치다, 이루다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/631/"},"解":{"id":624,"char":"解","hun":"풀 해","meaning":"“풀 해”. 풀다, 분해하다, 풀어내다","on":"カイ、ゲ","kun":"と(く)、と(ける)、と(かす)","explanation":["解 = 角 + 刀 + 牛。","「角」는 “뿔”을 뜻합니다.","「刀」는 “칼”을 뜻합니다.","「牛」는 “소”를 뜻합니다.","解는 “소(牛)의 뿔(角)을 자르다(刀)” -> “분해하다, 풀다, 풀어내다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/632/"},"資":{"id":625,"char":"資","hun":"재물 자","meaning":"“재물 자”. 자본, 자금, 밑천","on":"シ","kun":"","explanation":["資 = 次 + 貝。","(소리부 겸 의미부) 「次」(シ)는 “다음”이라는 뜻입니다.","(의미부) 「貝」는 “돈, 재물”을 뜻합니다.","資는 “다음(次)에 쓸 돈(貝)” -> “자본, 자금, 밑천”이라는 뜻의 글자입니다.","(次는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/633/"},"際":{"id":626,"char":"際","hun":"즈음 제","meaning":"“즈음 제”. 사이, 경계, 만나다, 닿다","on":"サイ","kun":"きわ","explanation":["際 = ⻖ + 祭。","(의미부) 「⻖」는 “언덕”을 뜻합니다.","(소리부) 「祭」(サイ)는 여기서는 소리부의 역할만 하고 있습니다.","際는 “언덕과 언덕(⻖)이 맞닿은 경계선” -> “사이, 경계, 만나다, 닿다”라는 뜻의 글자입니다(祭는 소리부)."],"sourceUrl":"https://nihongokanji.com/634/"},"査":{"id":627,"char":"査","hun":"조사할 사","meaning":"“조사할 사”. 조사하다","on":"サ","kun":"","explanation":["査 = 木 + 且。","「木」는 “나무”를 뜻합니다.","「且」는 “비석, 조상, 장례”를 뜻합니다.","査는 “장례(且)를 지낼 관을 만들 좋은 나무(木)를 조사하다” -> “조사하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/635/"},"判":{"id":628,"char":"判","hun":"판단할 판","meaning":"“판단할 판”. 판단하다, 판정하다","on":"ハン、バン","kun":"","explanation":["判 = 半 + 刂。","(소리부 겸 의미부) 「半」(ハン)은 “절반”을 뜻합니다.","(의미부) 「刂」는 “칼”을 뜻합니다.","判는 “반으로(半) 딱 잘라(刂) 판단하다” -> “판단하다, 판정하다”라는 뜻의 글자입니다.","(半은 소리부(ハン -> ハン・バン)도 겸함)"],"sourceUrl":"https://nihongokanji.com/636/"},"認":{"id":629,"char":"認","hun":"알 인","meaning":"“알 인”. 인정하다, 인식하다","on":"ニン","kun":"みと(める)","explanation":["認 = 言 + 刃 + 心。","「言」는 “말하다”라는 뜻입니다.","刃(“칼날 인”)은 “칼날”을 뜻하는 상용한자입니다.","「心」는 “마음”을 뜻합니다.","認는 “가르침(言)을 마음(心)에 새기다(刃)” -> “인정하다, 인식하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/637/"},"在":{"id":630,"char":"在","hun":"있을 재","meaning":"“있을 재”. 있다, 존재하다","on":"ザイ","kun":"あ(る)","explanation":["在 = 才 + 土。","(소리부 겸 의미부) 「才」(サイ)는 본래 “새싹이 올라오는 모습”을 그린 글자입니다(링크 참조).","(의미부) 「土」는 “흙, 땅”을 뜻합니다.","在는 “땅(土) 위에 새싹(才)이 있다” -> “있다, 존재하다”라는 뜻의 글자입니다.","(才는 소리부(サイ -> ザイ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/638/"},"件":{"id":631,"char":"件","hun":"물건 건","meaning":"“물건 건”. 낱개, 건수, 사건","on":"ケン","kun":"","explanation":["件 = 亻 + 牛。","「亻」는 “사람”을 뜻합니다.","「牛」는 “소”를 뜻합니다.","件은 “사람(亻)이 소고기(牛)를 부위별로 나누다” -> “낱개, 건수, 사건”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/639/"},"団":{"id":632,"char":"団","hun":"둥글 단","meaning":"“둥글 단”. 집단, 뭉치다","on":"ダン、トン","kun":"","explanation":["団 = 囗 + 寸。","囗는 여기서는 “집단, 범위”를 표현한 모양자로 쓰인 것입니다.","「寸」는 “손”을 뜻합니다.","団는 “손잡고(寸) 하나로 뭉친(囗) 사람들” -> “집단”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/640/"},"任":{"id":633,"char":"任","hun":"맡길 임","meaning":"“맡길 임”. 맡기다, 일임하다","on":"ニン","kun":"まか(せる)、まか(す)","explanation":["任 = 亻 + 壬。","「亻」는 “사람”을 뜻합니다.","壬는 여기서는 「王」가 변형된 것으로, “왕”을 뜻합니다.","任는 “왕(壬)이 신하(亻)에게 임무를 맡기다” -> “맡기다, 일임하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/641/"},"論":{"id":634,"char":"論","hun":"논할 논","meaning":"“논할 논”. 논하다, 논의, 이론","on":"ロン","kun":"","explanation":["論 = 言 + 侖。","「言」는 “말하다”라는 뜻입니다.","「侖」는 “둥글게 말린 죽간”을 뜻합니다.","論은 “책(侖)을 읽고 의견을 주고받다(言)” -> “논하다, 논의, 이론”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/642/"},"増":{"id":635,"char":"増","hun":"더할 증","meaning":"“더할 증”. 늘다, 증가하다","on":"ゾウ","kun":"ま(す)、ふ(える)、ふ(やす)","explanation":["増 = 土 + 曽。","(의미부) 「土」는 “흙”을 뜻합니다.","(소리부 겸 의미부) 「曽」(ソウ)는 “쌓이다”라는 뜻의 글자입니다(링크 참조).","増는 “흙더미(土)가 쌓이다(曽)” -> “늘다, 증가하다”라는 뜻의 글자입니다.","(曽는 소리부(ソウ -> ゾウ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/643/"},"情":{"id":636,"char":"情","hun":"뜻 정","meaning":"“뜻 정”. 정, 정서, 마음, 인정","on":"ジョウ、セイ","kun":"なさ(け)","explanation":["情 = 忄 + 青。","(의미부) 「忄」는 “마음”을 뜻합니다.","(소리부 겸 의미부) 「青」(セイ・ショウ)는 “푸르다”라는 뜻입니다.","情는 “푸르고 맑은(青) 마음(忄)” -> “정, 인정, 정서”라는 뜻의 글자입니다.","(青는 소리부(セイ・ショウ -> ジョウ・セイ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/644/"},"示":{"id":637,"char":"示","hun":"보일 시","meaning":"“보일 시”. 보이다, 나타내다","on":"ジ、シ","kun":"しめ(す)","explanation":["示는 “고대의 비석”을 그린 상형문자입니다.","“거대한 비석을 세워놓다” -> “나타내다, 보이다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/645/"},"基":{"id":638,"char":"基","hun":"터 기","meaning":"“터 기”. 토대, 기초, 바탕, 근본","on":"キ","kun":"もと、もとい","explanation":["基 = 其 + 土。","(소리부 겸 의미부) 「其」(キ)는 여기서는 “탑”을 그린 모양자입니다.","(의미부) 「土」는 “흙, 땅”을 뜻합니다.","基는 “토대(土) 위에 쌓은 탑(其)” -> “기초, 토대”라는 뜻의 글자입니다.","(其는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/646/"},"革":{"id":639,"char":"革","hun":"가죽 혁","meaning":"“가죽 혁”. 가죽, 개혁하다","on":"カク","kun":"かわ","explanation":["革는 “손으로 가죽을 펼치는 모습”을 그린 상형문자입니다.","참고) 革와 皮의 차이","革는 “가공 단계의 가죽”을 뜻합니다.","皮는 “재료로서의 가죽”을 뜻합니다."],"sourceUrl":"https://nihongokanji.com/647/"},"価":{"id":640,"char":"価","hun":"값 가","meaning":"“값 가”. 가격, 값어치","on":"カ","kun":"あたい","explanation":["価 = 亻 + 覀。","「亻」는 “사람”을 뜻합니다.","「覀」는 “덮다, 가리다”라는 뜻의 부수입니다(링크 참조).","価는 “상인(亻)이 숨겨둔(覀) 골동품의 값” -> “값, 가격, 값어치”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/648/"},"確":{"id":641,"char":"確","hun":"굳을 확","meaning":"“굳을 확”. 확실, 확인, 단단한","on":"カク","kun":"たし(か)、たし(かめる)","explanation":["確 = 石 + 冖 + 隹。","「石」는 “돌”을 뜻합니다.","冖는 여기서는 “새장”을 그린 모양자입니다.","「隹」는 “새”를 뜻합니다.","確는 “돌(石)로 만든 새장(冖)에 새(隹)를 가둬놓다” -> “단단하다, 확실하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/653/"},"勢":{"id":642,"char":"勢","hun":"형세 세","meaning":"“형세 세”. 기세, 세력, 형세","on":"セイ","kun":"いきお(い)","explanation":["勢 = 坴 + 丸 + 力。","「坴」는 “흙더미”를 뜻하는 글자입니다.","丸는 여기서는 “땅(坴)에 나무를 심고 있는 사람”을 그린 모양자입니다(위 그림 참조).","「力」는 “힘”을 뜻합니다.","勢는 “땅(坴)에 심어놓은(丸) 나무가 힘차게(力) 자라다” -> “기세, 세력, 형세”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/654/"},"減":{"id":643,"char":"減","hun":"덜 감","meaning":"“덜 감”. 줄다, 덜다, 감소하다","on":"ゲン","kun":"へ(る)、へ(らす)","explanation":["減 = 氵 + 咸。","「氵」는 “물”을 뜻합니다.","咸는 “창을 들고(戌) 함성을 지르는(口) 병사”를 뜻합니다(353.「感」 모양 해설 참조).","減는 “병사들(咸)이 피흘리며(氵) 쓰러지다” -> “병사의 수가 줄다” -> “줄다, 감소하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/655/"},"容":{"id":644,"char":"容","hun":"얼굴 용","meaning":"“얼굴 용”. 담다, 수용하다, 얼굴/용모, 용서하다","on":"ヨウ","kun":"","explanation":["容 = 穴 + 㕣。","「穴」는 “구멍”을 뜻합니다.","㕣는 여기서는 “항아리”를 그린 모양자입니다.","容는 “구멍(穴)에 항아리(㕣)를 넣다” -> “담다, 수용하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/656/"},"応":{"id":645,"char":"応","hun":"응할 응","meaning":"“응할 응”. 응하다, 반응하다","on":"オウ","kun":"こた(える)","explanation":["応 = 广 + 心。","「广」는 “건물, 집”을 뜻합니다.","「心」는 “마음”을 뜻합니다.","応는 “집(广)에서 기다리는 가족들의 마음(心)에 답하다” -> “응하다, 반응하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/657/"},"演":{"id":646,"char":"演","hun":"펼 연","meaning":"“펼 연”. 넓게 미치다, 펼치다","on":"エン","kun":"","explanation":["演 = 氵 + 宀 + 一 + 由 + ハ。","「氵」는 “물”을 뜻합니다.","「宀」는 “집”을 뜻합니다.","아래쪽의 一+由+ハ는 “(물을 받기 위한) 항아리”를 그린 모양자입니다.","演는 “지붕(宀)에서 새는 물(氵)을 받는 항아리(一+由+ハ)”라는 뜻입니다.","“빗물이 집 안까지 새어 번지다” -> “넓게 미치다, 펼치다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/658/"},"歳":{"id":647,"char":"歳","hun":"해 세","meaning":"“해 세”. 나이(~세)","on":"サイ、セイ","kun":"","explanation":["歳 = 歩 + 戌。","「歩」는 “걷다”라는 뜻입니다.","「戌」는 “창을 든 손”을 뜻합니다.","歳는 “전쟁터에서 창을 들고(戌) 싸우며 걸어온(歩) 세월들” -> “해, 나이”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/659/"},"能":{"id":648,"char":"能","hun":"능할 능","meaning":"“능할 능”. 능력","on":"ノウ","kun":"","explanation":["能는 “곰”을 그린 상형문자입니다.","“곰” -> “강하다” -> “능력”이라는 의미입니다.","참고)","본래의 “곰”이라는 뜻은 지금은 「熊」가 대신하고 있습니다."],"sourceUrl":"https://nihongokanji.com/660/"},"再":{"id":649,"char":"再","hun":"두 재","meaning":"“두 재”. 다시, 다시 하다","on":"サイ、サ","kun":"ふたた(び)","explanation":["再는 “물고기가 수면 위로 입을 내민 모습”을 그린 상형문자입니다.","“물고기가 수면 위아래를 반복해서 왔다갔다하다” -> “다시, 다시금”이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/661/"},"格":{"id":650,"char":"格","hun":"격식 격","meaning":"“격식 격”. 격, 지위, 신분","on":"カク、コウ","kun":"","explanation":["格 = 木 + 各。","(의미부) 「木」는 “나무”를 뜻합니다.","(소리부 겸 의미부) 「各」(カク)는 “각각, 각자”라는 뜻입니다.","格는 “목재(木) 각각의(各) 질의 차이” -> “격, 지위, 신분”이라는 뜻의 글자입니다.","(各는 소리부(カク -> カク・コウ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/662/"},"疑":{"id":651,"char":"疑","hun":"의심할 의","meaning":"“의심할 의”. 의심하다","on":"ギ","kun":"うたが(う)","explanation":["疑 = 匕 + 矢 + マ + 疋。","匕는 여기서는 「刀」가 뒤집힌 것으로, “칼”을 뜻합니다.","「矢」는 “화살”을 뜻합니다.","오른쪽의 マ+疋는 여기서는 “어린아이”를 그린 모양자입니다(マ는 머리, 乛는 팔, 龰는 몸통+다리를 각각 표현한 것입니다).","疑는 “칼(匕)과 화살(矢)을 든 어린아이(マ+疋)”라는 뜻입니다.","“위험한 무기를 들고 노는 아이를 걱정하다” -> “의심하다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/663/"},"過":{"id":652,"char":"過","hun":"지날 과","meaning":"“지날 과”. 넘치다, 지나치다, 잘못, 죄","on":"カ","kun":"す(ぎる)、す(ごす)、あやま(つ)、あやま(ち)","explanation":["過 = ⻌ + 咼。","(의미부) 「⻌」는 “길”을 뜻합니다.","(소리부 겸 의미부) 「咼」(カ)는 “잘못되다, 어긋나다”라는 뜻의 글자입니다(링크 참조).","過는 “길(⻌)을 착각해서(咼) 지나쳐버리다” -> “지나치다, 잘못, 죄”라는 뜻의 글자입니다.","(咼는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/664/"},"税":{"id":653,"char":"税","hun":"세금 세","meaning":"“세금 세”. 세금","on":"ゼイ","kun":"","explanation":["税 = 禾 + 兑。","「禾」는 “곡식”을 뜻합니다.","「兑」는 “날카로운 눈을 한 사람”을 뜻합니다.","税은 “세금으로 낸 곡식(禾)의 양을 확인하는 세금 징수관(兑)” -> “세금”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/665/"},"検":{"id":654,"char":"検","hun":"검사할 검","meaning":"“검사할 검”. 검사하다","on":"ケン","kun":"","explanation":["検 = 木 + 㑒。","(의미부) 「木」는 “나무”를 뜻합니다.","(소리부 겸 의미부) 「㑒」(ケン)은 “뾰족하다, 날카롭다”라는 뜻입니다.","検는 “목재(木) 가구에 뾰족한(㑒) 부분이 남아있나 마감을 검사하다” -> “검사하다”라는 뜻의 글자입니다.","(㑒은 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/666/"},"常":{"id":655,"char":"常","hun":"항상 상","meaning":"“항상 상”. 보통의, 일반적인, 한결같은","on":"ジョウ","kun":"つね、とこ","explanation":["常 = 龸 + 口 + 巾。","「龸」는 “궁궐”을 뜻합니다.","口는 여기서는 “(궁궐의) 대문”을 그린 모양자입니다.","「巾」는 “수건, 천”을 뜻합니다.","常는 “궁궐(龸)에 출입할(口) 때 항상 입는 관복(巾)” -> “항상, 보통”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/667/"},"状":{"id":656,"char":"状","hun":"형상 상/문서 장","meaning":"“형상 상/문서 장”. 상황, 문서","on":"ジョウ","kun":"","explanation":["状 = 丬 + 犬。","「丬」는 “탁자”를 뜻하는 부수입니다(링크 참조).","「犬」는 “개”를 뜻합니다.","状는 “미친개(犬)를 피해서 탁자(丬) 뒤에 숨다“라는 뜻입니다.","“미친개가 날뛰는 긴박한 상황” -> “상황”","“상황을 정리한 문서를 작성해 올리다” -> “문서”","라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/668/"},"営":{"id":657,"char":"営","hun":"경영할 영","meaning":"“경영할 영”. 경영하다, 사업하다","on":"エイ","kun":"いとな(む)","explanation":["営 = ⺍ + 冖 + 呂。","「⺍+冖」는 “불이 환하게 켜진 집”을 뜻합니다.","「呂」는 “여러 채의 집이 이어져있는 대저택”을 뜻합니다(링크 참조).","営는 “밤에도 환하게 불이 켜진(⺍+冖) 커다란 건물(呂)” -> “경영하다, 사업하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/669/"},"職":{"id":658,"char":"職","hun":"직분 직","meaning":"“직분 직”. 직업, 직무","on":"ショク","kun":"","explanation":["職 = 耳 + 音 + 戈。","「耳」는 “귀”를 뜻합니다.","「音」는 “소리”를 뜻합니다.","「戈」는 “창”을 뜻합니다.","職는 “창(戈)을 들고 귀기울여(耳) 소리(音)를 듣는 경비병 일” -> “직무, 직업”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/670/"},"与":{"id":659,"char":"与","hun":"줄 여","meaning":"“줄 여”. 주다, 관여하다","on":"ヨ","kun":"あた(える)","explanation":["与는 “맞물려있는 치아”를 그린 상형문자입니다.","“맞물리다” -> “주고받다” -> “주다, 관여하다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/671/"},"供":{"id":660,"char":"供","hun":"이바지할 공","meaning":"“이바지할 공”. 바치다, 제공하다, 올리다","on":"キョウ、ク","kun":"そな(える)、とも","explanation":["供 = 亻 + 共。","(의미부) 「亻」는 “사람”을 뜻합니다.","(소리부 겸 의미부) 「共」(キョウ)는 본래 “쟁반을 받쳐든 손”을 그린 글자입니다(링크 참조).","供는 “높은 사람(亻)에게 공물을 올려바치다(共)” -> “바치다, 제공하다, 올리다”라는 뜻의 글자입니다.","(共는 소리부(キョウ -> キョウ・ク)도 겸함)"],"sourceUrl":"https://nihongokanji.com/672/"},"可":{"id":661,"char":"可","hun":"옳을 가","meaning":"“옳을 가”. 가능하다, 허가하다","on":"カ","kun":"","explanation":["可 = 𠃌 + 口。","「口」는 “입”을 뜻합니다.","𠃌는 여기서는 “곡괭이”를 그린 모양자입니다.","可는 본래 “곡괭이질(𠃌)을 하며 흥얼거리다(口)” -> “노래하다”라는 뜻으로 만들어진 글자입니다.","그러나 이후 발음이 같다는 이유로 “옳다”라는 뜻으로 쓰이게 된 것입니다.","즉, 可의 모양과 의미 사이에는 아무런 관계도 없습니다."],"sourceUrl":"https://nihongokanji.com/673/"},"構":{"id":662,"char":"構","hun":"얽을 구","meaning":"“얽을 구”. 만들다, 구축하다","on":"コウ","kun":"かま(える)、かま(う)","explanation":["構 = 木 + 冓。","(의미부) 「木」는 “나무”를 뜻합니다.","(소리부 겸 의미부) 「冓」(コウ)는 “얽다, 짜다”라는 뜻의 글자입니다(링크 참조).","構는 “나무(木)를 얽고 짜다(冓)” -> “만들다, 구축하다”라는 뜻의 글자입니다.","(冓는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/674/"},"割":{"id":663,"char":"割","hun":"벨 할","meaning":"“벨 할”. 베다, 가르다, 나누다","on":"カツ","kun":"わ(る)、わり、わ(れる)、さ(く)","explanation":["割 = 害 + 刂。","「害」는 “해치다”라는 뜻입니다.","「刂」는 “칼”을 뜻합니다.","割는 “칼(刂)로 해치다(害)” -> “베다, 가르다, 나누다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/675/"},"比":{"id":664,"char":"比","hun":"견줄 비","meaning":"“견줄 비”. 비교하다","on":"ヒ","kun":"くら(べる)","explanation":["比는 “나란히 서 있는 사람들”을 그린 상형문자입니다.","“나란히 세워놓고 비교하다” -> “비교하다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/676/"},"難":{"id":665,"char":"難","hun":"어려울 난","meaning":"“어려울 난”. 어렵다","on":"ナン","kun":"むずか(しい)、かた(い)","explanation":["難 = 𦰩 + 隹。","難의 명확한 유래는 알려진 바가 없습니다. 그래서 그냥 제가 만들어 보았습니다.","𦰩는 여기서는 「漢」가 축약된 것으로, “한자”를 뜻합니다.","「隹」는 “새”를 뜻합니다.","難는 “한자(𦰩)는 어려워서 새대가리(隹)들은 배울 수 없다” -> “어렵다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/677/"},"防":{"id":666,"char":"防","hun":"막을 방","meaning":"“막을 방”. 막다, 지키다","on":"ボウ","kun":"ふせ(ぐ)","explanation":["防 = ⻖ + 方。","(의미부) 「⻖」는 “언덕”을 뜻합니다.","(소리부 겸 의미부) 「方」(ホウ)는 “방향”을 뜻합니다.","防는 “적이 오는 방향(方)의 언덕(⻖)에서 적을 막다” -> “막다, 지키다”라는 뜻의 글자입니다.","(方는 소리부(ホウ -> ボウ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/678/"},"補":{"id":667,"char":"補","hun":"기울 보","meaning":"“기울 보”. 보충하다, 보태다","on":"ホ","kun":"おぎな(う)","explanation":["補 = 衤 + 甫。","(의미부) 「衤」는 “옷, 옷감”을 뜻합니다.","(소리부 겸 의미부) 「甫」(ホ)는 “채소밭”을 뜻하는 글자입니다(링크 참조).","補는 “채소밭(甫)에서 일하느라 구멍난 옷(衤)에 천을 기워 덧대다” -> “보충하다, 보태다”라는 뜻의 글자입니다.","(甫는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/679/"},"優":{"id":668,"char":"優","hun":"넉넉할/뛰어날 우","meaning":"“넉넉할/뛰어날 우”. 뛰어난, 우아한, 상냥한","on":"ユウ","kun":"やさ(しい)、すぐ(れる)","explanation":["優 = 亻 + 憂。","(의미부) 「亻」는 “사람”을 뜻합니다.","(소리부 겸 의미부) 憂(ユウ – “근심 우”)는 “걱정, 근심”을 뜻하는 상용한자입니다.","優는,","“뛰어난 사람(亻)은 걱정(憂)이 많다” -> “뛰어나다”","“남을 걱정해주는(憂) 상냥한 사람(亻)” -> “상냥하다”","라는 뜻의 글자입니다.","(憂는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/680/"},"収":{"id":669,"char":"収","hun":"거둘 수","meaning":"“거둘 수”. 거두다, 수습하다","on":"シュウ","kun":"おさ(める)、おさ(まる)","explanation":["収 = 丩 + 又。","「丩」는 “얽히다”라는 뜻의 글자입니다(링크 참조).","「又」는 “손”을 뜻합니다.","収는 “떨어진 물건들을 주워서(又) 묶어놓다(丩)” -> “거두다, 수습하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/681/"},"断":{"id":670,"char":"断","hun":"끊을 단","meaning":"“끊을 단”. 끊다, 결정하다","on":"ダン","kun":"た(つ)、ことわ(る)","explanation":["断 = 𠃊 + 米 + 斤。","𠃊+米는 여기서는 “실뭉치”를 그린 모양자입니다.","「斤」는 “도끼”를 뜻합니다.","断는 “엉켜 있는 실뭉치(𠃊+米)를 도끼(斤)로 끊다” -> “끊다, 결정하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/682/"},"違":{"id":671,"char":"違","hun":"어긋날 위","meaning":"“어긋날 위”. 다르다, 틀리다, 어긋나다","on":"イ","kun":"ちが(う)、ちが(える)","explanation":["違 = ⻌ + 韋。","(의미부) 「⻌」는 “길”을 뜻합니다.","(소리부 겸 의미부) 「韋」(イ)는 “성 주위를 돌며 경계서는 발들”을 그린 글자입니다(링크 참조).","여기서는 “서로 반대 방향을 돌다” -> “엇갈리다”라는 뜻으로 쓰인 것입니다.","違는 “길(⻌)이 엇갈리다(韋)” -> “다르다, 틀리다, 어긋나다”라는 뜻의 글자입니다.","(韋는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/683/"},"境":{"id":672,"char":"境","hun":"지경 경","meaning":"“지경 경”. 경계, 범위, 땅","on":"キョウ、ケイ","kun":"さかい","explanation":["境 = 土 + 音 + 儿。","「土」는 “흙, 땅”을 뜻합니다.","「音」는 “소리”를 뜻합니다.","儿는 「人」가 변형된 것으로, “사람”을 뜻합니다.","境는 “악사(儿)의 악기 소리(音)가 들리는 범위(土)” -> “경계, 범위, 땅”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/684/"},"規":{"id":673,"char":"規","hun":"법 규","meaning":"“법 규”. 규범, 규칙, 규정, 표준","on":"キ","kun":"","explanation":["規 = 夫 + 見。","「夫」는 “남편”을 뜻합니다.","「見」는 “보다”라는 뜻입니다.","規는 “남편(夫)의 안목(見)은 옳다” -> “규범, 규칙, 표준”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/685/"},"術":{"id":674,"char":"術","hun":"재주 술","meaning":"“재주 술”. 기술, 재주, 술수","on":"ジュツ","kun":"","explanation":["術 = 行 + 朮。","(의미부) 「行」는 본래 “사거리”를 그린 글자입니다(링크 참조).","(소리부 겸 의미부) 「朮」(ジュツ)는 “모자를 쓴 재주꾼”을 그린 글자입니다(링크 참조).","術는 “사거리(行) 한가운데서 공연 중인 재주꾼(朮)” -> “재주, 기술, 술수”라는 뜻의 글자입니다.","(朮는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/686/"},"展":{"id":675,"char":"展","hun":"펼 전","meaning":"“펼 전”. 늘어놓다, 펼치다, 퍼지다","on":"テン","kun":"","explanation":["展 = 尸 + 龷 + 衣。","「尸」는 “앉아있는 사람”을 뜻합니다.","글자의 아래쪽은 「衣」가 축약된 것으로, “옷”을 뜻합니다.","龷는 여기서는 “옷(衣)이 좌우로 길게 펼쳐진 모습”을 표현한 모양자입니다.","展는 “자리에 앉았는데(尸) 옷이 너무 길어서 땅바닥까지 길게 늘어지다(龷+衣)”라는 뜻입니다.","“옷이 바닥에 길게 늘어지다” -> “늘어놓다, 펼치다, 퍼지다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/687/"},"導":{"id":676,"char":"導","hun":"인도할 도","meaning":"“인도할 도”. 이끌다","on":"ドウ","kun":"みちび(く)","explanation":["導 = 道 + 寸。","(의미부 겸 소리부) 「道」(ドウ)는 “길”을 뜻합니다.","(의미부) 「寸」는 “손”을 뜻합니다.","導는 “방향을 지시하며(寸) 길(道)을 이끌다” -> “이끌다”라는 뜻의 글자입니다.","(道는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/688/"},"備":{"id":677,"char":"備","hun":"갖출 비","meaning":"“갖출 비”. 준비하다, 갖추다, 구비하다","on":"ビ","kun":"そな(える)、そな(わる)","explanation":["備 = 亻 + 𤰇。","「亻」는 “사람”을 뜻합니다.","𤰇는 여기서는 “화살(𠀗)이 든 화살통(用)”을 그린 모양자입니다. 아래 그림을 참조해 주세요.","備는 “사냥꾼(亻)이 화살통(𤰇)을 매고 사냥 채비를 갖추다” -> “갖추다, 준비하다, 구비하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/689/"},"宅":{"id":678,"char":"宅","hun":"집 택","meaning":"“집 택”. 집, 댁","on":"タク","kun":"","explanation":["宅 = 宀 + 乇。","「宀」는 “집”을 뜻합니다.","乇는 여기서는 “앉아있는 사람”을 그린 모양자입니다.","宅는 “자기 집(宀)에 앉아있는 사람(乇)” -> “집”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/690/"},"条":{"id":679,"char":"条","hun":"조목 조","meaning":"“조목 조”. 조항, 조목","on":"ジョウ","kun":"","explanation":["条 = 夂 + 木。","夂는 여기서는 「攵」가 잘못 변형된 것으로, 본래는 “막대기를 든 손”을 그린 글자입니다(링크 참조).","「木」는 “나무”를 뜻합니다.","条는 “나무(木)에서 뻗어난 가지들 중 하나를 골라 집어든 손(攵)”을 그린 글자입니다.","나무 기둥에서 뻗어난 여러 갈래의 나뭇가지들을 각각의 조목, 조항에 비유한 것입니다.","“나무에서 뻗어난 나뭇가지들” -> “(각각의) 조목, 조항”이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/691/"},"独":{"id":680,"char":"独","hun":"홀로 독","meaning":"“홀로 독”. 혼자, 홀로","on":"ドク","kun":"ひと(り)","explanation":["独 = 犭 + 虫。","「犭」는 “개”를 뜻하는 부수입니다(링크 참조).","「虫」는 “벌레”를 뜻합니다.","独는 “개(犭)가 날파리(虫)를 피해 달아나 혼자 숨다” -> “혼자, 홀로”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/692/"},"警":{"id":681,"char":"警","hun":"경계할 경","meaning":"“경계할 경”. 경계하다, 조심하다","on":"ケイ","kun":"","explanation":["警 = 敬 + 言。","(소리부 겸 의미부) 敬(ケイ – “공경 경”)은 “존경하다”라는 뜻의 상용한자입니다.","(의미부) 「言」는 “말하다”라는 뜻입니다.","警는 “존경(敬)을 담아 조심스럽게 말하다(言)” -> “조심하다, 경계하다”라는 뜻의 글자입니다.","(敬는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/693/"},"輸":{"id":682,"char":"輸","hun":"보낼 수","meaning":"“보낼 수”. 나르다, 운반하다","on":"ユ","kun":"","explanation":["輸 = 車 + 俞。","(의미부) 「車」는 “수레, 차”를 뜻합니다.","(소리부 겸 의미부) 「俞」(ユ)는 “보내다”라는 뜻의 글자입니다(링크 참조).","輸는 “수레(車)에 실어 보내다(俞)” -> “나르다, 운반하다”라는 뜻의 글자입니다.","(俞는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/694/"},"訪":{"id":683,"char":"訪","hun":"찾을 방","meaning":"“찾을 방”. 방문하다","on":"ホウ","kun":"おとず(れる)、たず(ねる)","explanation":["訪 = 言 + 方。","(의미부) 「言」는 “말하다”라는 뜻입니다.","(소리부 겸 의미부) 「方」(ホウ)는 “방향, 방법”을 뜻합니다.","訪는 “방법(方)을 물어보러(言) 찾아가다” -> “방문하다”라는 뜻의 글자입니다.","(方는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/695/"},"述":{"id":684,"char":"述","hun":"펼 술","meaning":"“펼 술”. 말하다, 진술하다","on":"ジュツ","kun":"の(べる)","explanation":["述 = ⻌ + 朮。","(의미부) 「⻌」는 “길”을 뜻합니다.","(소리부 겸 의미부) 「朮」(ジュツ)는 “모자를 쓴 재주꾼”을 그린 글자입니다.","述는 “길가(⻌)에서 자신이 보여준 묘기를 상세히 설명하는 재주꾼(朮)” -> “말하다, 진술하다”라는 뜻의 글자입니다.","(朮는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/696/"},"率":{"id":685,"char":"率","hun":"거느릴 솔/비율 률","meaning":"“거느릴 솔/비율 률”. 이끌다, 비율","on":"ソツ、リツ","kun":"ひき(いる)","explanation":["率는 “밧줄을 잡아당기는 모습”을 그린 상형문자입니다.","“줄을 적절한 힘으로 잡아당기다” -> “이끌다, 비율”이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/697/"},"武":{"id":686,"char":"武","hun":"호반 무","meaning":"“호반 무”. 무력, 무, 강함","on":"ブ、ム","kun":"","explanation":["武 = 止 + 戈。","「止」는 “발”을 뜻합니다.","「戈」는 “창”을 뜻합니다(아래쪽의 ノ가 위쪽의 一로 올라간 형태로 쓰인 것입니다).","武는 “창칼(戈)로 짓밟다(止)” -> “무력, 무”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/698/"},"域":{"id":687,"char":"域","hun":"지경 역","meaning":"“지경 역”. 지역, 영역, 경계","on":"イキ","kun":"","explanation":["域 = 土 + 戈 + 口 + 一。","「土」는 “땅”을 뜻합니다.","「戈」는 “창”을 뜻합니다.","口+一는 여기서는 “성문”을 그린 모양자입니다.","域는 “창(戈)을 들고 영토(土)로 들어가는 성문(口+一)을 지키다” -> “지역, 영역”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/699/"},"張":{"id":688,"char":"張","hun":"베풀 장","meaning":"“베풀 장”. 펴다, 넓히다, 당기다, 뻗치다","on":"チョウ","kun":"は(る)","explanation":["張 = 弓 + 長。","(의미부) 「弓」는 “활”을 뜻합니다.","(소리부 겸 의미부) 「長」(チョウ)는 “길다”라는 뜻입니다.","張는 “활시위(弓)를 길게(長) 잡아당기다” -> 펴다, 넓히다, 당기다, 뻗치다”라는 뜻의 글자입니다.","(長는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/700/"},"限":{"id":689,"char":"限","hun":"한할 한","meaning":"“한할 한”. 제한, 한계, 한도","on":"ゲン","kun":"かぎ(る)","explanation":["限 = ⻖ + 艮。","「⻖」는 “언덕, 산”을 뜻합니다.","「艮」는 “고개를 숙인 사람”을 뜻합니다.","限는 “높은 산(⻖)에 가로막혀 좌절하고 있는 사람(艮)” -> “한계, 한도, 제한”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/701/"},"額":{"id":690,"char":"額","hun":"이마 액","meaning":"“이마 액”. 이마, 금액, 액자","on":"ガク","kun":"ひたい","explanation":["額 = 客 + 頁。","(소리부 겸 의미부) 「客」(カク)는 “손님”을 뜻합니다.","(의미부) 「頁」는 “머리”를 뜻합니다.","額는 “가게에 자주 머리를(頁) 들이미는 단골손님(客)” -> “이마, 금액”이라는 뜻의 글자입니다.","(客는 소리부(カク -> ガク)도 겸함)"],"sourceUrl":"https://nihongokanji.com/702/"},"環":{"id":691,"char":"環","hun":"고리 환","meaning":"“고리 환”. 고리, 두르다","on":"カン","kun":"","explanation":["環 = 𤣩 + 睘。","(의미부) 「𤣩」는 “구슬, 보석”을 뜻합니다.","(소리부 겸 의미부) 「睘」(カン)은 “둥글다”라는 뜻의 글자로, “품 안의 둥근 옥을 바라보는 모습”을 그린 것입니다(링크 참조).","環는 “둥근(睘) 옥가락지(𤣩)” -> “고리, 두르다”라는 뜻의 글자입니다.","(睘은 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/703/"},"欧":{"id":692,"char":"欧","hun":"토할 구","meaning":"“토할 구”. 유럽","on":"オウ","kun":"","explanation":["欧 = 区 + 欠。","「欠」는 “입으로 하는 동작”을 뜻합니다.","区는 여기서는 “땅에 묻은 토사물”을 그린 모양자입니다.","欧는 본래 “입을 벌리고(欠) 토하다(区)” -> “토하다”라는 뜻으로 만들어진 글자입니다.","그러나 이후 발음이 비슷하다는 이유로 “유럽”이라는 뜻으로 쓰이게 된 것입니다.","즉, 欧의 모양과 의미 사이에는 아무런 관계도 없습니다."],"sourceUrl":"https://nihongokanji.com/704/"},"担":{"id":693,"char":"担","hun":"멜 담","meaning":"“멜 담”. 메다, 부담하다","on":"タン","kun":"かつ(ぐ)、にな(う)","explanation":["担 = 扌 + 旦。","「扌」는 “손”을 뜻합니다.","旦는 여기서는 “등에 멘 봇짐”을 그린 모양자입니다.","担는 “봇짐(旦)을 메다(扌)” -> “메다, 부담하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/705/"},"退":{"id":694,"char":"退","hun":"물러날 퇴","meaning":"“물러날 퇴”. 물러나다, 사양하다, 멀리하다","on":"タイ","kun":"しりぞ(く)、しりぞ(ける)","explanation":["退 = ⻌ + 艮。","「⻌」는 “길”을 뜻합니다.","「艮」는 “고개를 숙인 사람”을 뜻합니다.","退는 “상대에게 고개를 숙이고(艮) 길에서(⻌) 물러나다” -> “물러나다, 사양하다, 멀리하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/706/"},"準":{"id":695,"char":"準","hun":"준할 준","meaning":"“준할 준”. 기준, 준하다, 갖추다","on":"ジュン","kun":"","explanation":["準 = 氵 + 隹 + 一 + 丨。","「氵」는 “물”을 뜻합니다.","「隹」는 “새”를 뜻합니다.","一는 여기서는 “평평한 수면”을 그린 모양자입니다.","丨는 여기서는 “직선”을 그린 모양자입니다.","準는 “물(氵)위의 수면(一)을 일직선(丨)으로 곧게 날아가는 새(隹)” -> “정밀하다” -> “기준, 표준”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/707/"},"造":{"id":696,"char":"造","hun":"지을 조","meaning":"“지을 조”. 만들다, 짓다","on":"ゾウ","kun":"つく(る)","explanation":["造 = ⻌ + 𠂒 + 口。","「⻌」는 “길”을 뜻합니다.","「𠂒」는 “소”를 뜻합니다.","口는 여기서는 “외양간”을 그린 모양자입니다.","造는 “길(⻌) 옆에 소(𠂒)를 넣어둘 외양간(口)을 지어놓다” -> “만들다, 짓다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/708/"},"被":{"id":697,"char":"被","hun":"입을 피","meaning":"“입을 피”. 덮다, 덮이다","on":"ヒ","kun":"こうむ(る)","explanation":["被 = 衤 + 皮。","(의미부) 「衤」는 “옷, 옷감”을 뜻합니다.","(소리부 겸 의미부) 「皮」(ヒ)는 “가죽, 피부”를 뜻합니다.","被는 “피부(皮)를 옷(衤)으로 덮다” -> “덮다, 덮이다”라는 뜻의 글자입니다.","(皮는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/709/"},"技":{"id":698,"char":"技","hun":"재주 기","meaning":"“재주 기”. 기술, 재주, 솜씨","on":"ギ","kun":"わざ","explanation":["技 = 扌 + 十 + 又。","「扌」는 “손”을 뜻합니다.","十는 여기서는 “나무막대 두 개”를 그린 모양자입니다.","「又」는 “손”을 뜻합니다.","技는 “양 손(扌+又)에 나무막대(十)를 들고 묘기를 펼치다” -> “재주, 기술, 솜씨”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/710/"},"復":{"id":699,"char":"復","hun":"회복할 복/다시 부","meaning":"“회복할 복/다시 부”. 되돌아가다, 회복하다, 보복하다","on":"フク","kun":"","explanation":["復 = 彳 + 复。","(의미부) 「彳」는 “길”을 뜻합니다.","(소리부 겸 의미부) 「复」(フク)는 “되돌아가다”라는 뜻의 글자입니다(링크 참조).","復는 “길(彳)을 되돌아가다(复)” -> “되돌아가다, 회복하다”라는 뜻의 글자입니다.","(复는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/711/"},"渡":{"id":700,"char":"渡","hun":"건널 도","meaning":"“건널 도”. 건너다, 건네주다","on":"ト","kun":"わた(る)、わた(す)","explanation":["渡 = 氵 + 度。","(의미부) 「氵」는 “물”을 뜻합니다.","(소리부) 「度」(ト)는 여기서는 소리부의 역할만 하고 있습니다.","渡는 “물(氵)을 건너다” -> “건너다, 건네주다”라는 뜻의 글자입니다(度는 소리부)."],"sourceUrl":"https://nihongokanji.com/712/"},"移":{"id":701,"char":"移","hun":"옮길 이","meaning":"“옮길 이”. 옮기다","on":"イ","kun":"うつ(る)、うつ(す)","explanation":["移 = 禾 + 多。","「禾」는 “곡식”을 뜻합니다.","「多」는 “많다”라는 뜻입니다.","移는 “곡식(禾)이 너무 많아서(多) 다른 곳으로 옮기다” -> “옮기다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/713/"},"個":{"id":702,"char":"個","hun":"낱 개","meaning":"“낱 개”. 갯수, 개인, 개별","on":"コ","kun":"","explanation":["個 = 亻 + 固。","(의미부) 「亻」는 “사람”을 뜻합니다.","(소리부 겸 의미부) 「固」(コ)는 “딱딱하다”라는 뜻입니다. 여기서는 “딱딱하다” -> “개체”라는 뜻으로 쓰인 것입니다.","個는 “사람(亻) 한 개체(固)” -> “개인, 개별, 갯수”라는 뜻의 글자입니다.","(固는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/714/"},"評":{"id":703,"char":"評","hun":"평할 평","meaning":"“평할 평”. 비평하다, 품평하다","on":"ヒョウ","kun":"","explanation":["評 = 言 + 平。","(의미부) 「言」는 “말하다”라는 뜻입니다.","(소리부 겸 의미부) 「平」(ヒョウ)는 “평평하다”라는 뜻입니다.","評는 “공평하게(平) 평가하다(言)” -> “비평하다, 평가하다”라는 뜻의 글자입니다.","(平는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/715/"},"若":{"id":704,"char":"若","hun":"같을 약","meaning":"“같을 약”. 젊다, 어리다, 만약, 약간","on":"ジャク、ニャク","kun":"わか(い)、も(しくは)","explanation":["若는 “땅에 머리를 대고 엎드린 사람”을 그린 상형문자입니다.","“노인 앞에 엎드려 예를 취하는 젊은이” -> “젊다, 어리다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/716/"},"脳":{"id":705,"char":"脳","hun":"골 뇌","meaning":"“골 뇌”. 뇌","on":"ノウ","kun":"","explanation":["脳 = 月 + ⺍ + 凶。","「月」는 “신체의 일부”를 뜻합니다.","⺍+凶는 여기서는 “뇌의 주름”을 그린 모양자입니다.","脳는 “신체의 일부(月) + 뇌(⺍+凶)” -> “뇌”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/717/"},"含":{"id":706,"char":"含","hun":"머금을 함","meaning":"“머금을 함”. 머금다, 포함하다","on":"ガン","kun":"ふく(む)、ふく(める)","explanation":["含 = 今 + 口。","「今」는 “지금, 현재”를 뜻합니다.","「口」는 “입”을 뜻합니다.","含는 “지금(今) 입 안에(口) 머금고 있는 것” -> “머금다, 포함하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/718/"},"蔵":{"id":707,"char":"蔵","hun":"감출 장","meaning":"“감출 장”. 창고, 간직하다","on":"ゾウ","kun":"くら","explanation":["蔵 = 艹 + 戊 + 臣。","「艹」는 “풀”을 뜻합니다.","「戊」는 “창”을 뜻합니다.","「臣」는 “신하”를 뜻합니다.","蔵는 “정적의 습격(戊)을 피해 풀숲(艹)에 숨은 신하(臣)” -> “감추다, 간직하다, 창고”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/719/"},"非":{"id":708,"char":"非","hun":"아닐 비","meaning":"“아닐 비”. 아니다, 옳지 않은, 어긋난","on":"ヒ","kun":"","explanation":["非는 “새의 날개”를 그린 상형문자입니다.","“등 위의 날개” -> “등지다” -> “배반” -> “아니다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/720/"},"段":{"id":709,"char":"段","hun":"층계 단","meaning":"“층계 단”. 단계, 등급, 계단","on":"ダン","kun":"","explanation":["段의 왼쪽에 있는 글자는 “돌계단”을 그린 모양자입니다.","「殳」는 “때리다, 휘두르다”라는 뜻입니다.","段는 “망치를 휘둘러(殳) 돌을 깎아내 계단을 만들다” -> “계단, 단계, 등급”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/721/"},"製":{"id":710,"char":"製","hun":"지을 제","meaning":"“지을 제”. 제조하다, 만들다","on":"セイ","kun":"","explanation":["製 = 制 + 衣。","(소리부) 「制」(セイ)는 여기서는 소리부의 역할만 하고 있습니다.","(의미부) 「衣」는 “옷”을 뜻합니다.","製는 “옷(衣)을 만들다” -> “제조하다, 만들다”라는 뜻의 글자입니다(制는 소리부)."],"sourceUrl":"https://nihongokanji.com/722/"},"況":{"id":711,"char":"況","hun":"상황 황","meaning":"“상황 황”. 상황, 실황","on":"キョウ","kun":"","explanation":["況 = 氵 + 兄。","(의미부) 「氵」는 “물”을 뜻합니다.","(소리부 겸 의미부) 「兄」(キョウ)는 “형, 맏이”를 뜻합니다.","況는 “폭우에 불어난 강물(氵)을 걱정스레 지켜보는 맏형(兄)”이라는 뜻입니다.","“폭우에 강의 상황을 지켜보다” -> “상황, 실황”이라는 의미입니다.","(兄는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/723/"},"財":{"id":712,"char":"財","hun":"재물 재","meaning":"“재물 재”. 재물, 재산","on":"ザイ、サイ","kun":"","explanation":["財 = 貝 + 才。","(의미부) 「貝」는 “돈, 재물”을 뜻합니다.","(소리부 겸 의미부) 「才」(サイ)는 “재능, 재주”를 뜻합니다.","財는 “돈(貝) 버는 재주(才)” -> “재물, 재산”이라는 뜻의 글자입니다.","(才는 소리부(サイ -> ザイ・サイ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/724/"},"識":{"id":713,"char":"識","hun":"알 식","meaning":"“알 식”. 지식, 알다","on":"シキ","kun":"","explanation":["識 = 言 + 戠。","「言」는 “말하다”라는 뜻입니다.","戠는 여기서는 「職」이 축약된 것으로, “직무, 직업”을 뜻합니다.","識는 “가르치는(言) 직업(戠)” -> “지식, 알다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/725/"},"呼":{"id":714,"char":"呼","hun":"부를 호","meaning":"“부를 호”. 부르다, (숨을)내쉬다","on":"コ","kun":"よ(ぶ)","explanation":["呼 = 口 + 平。","「口」는 “입”을 뜻합니다.","「平」는 본래 “악기 소리가 퍼져나가는 것”을 표현한 글자입니다(링크 참조).","呼는 “입(口)에서 소리가 퍼져나가다(平)” -> “부르다, (숨을)내쉬다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/726/"},"針":{"id":715,"char":"針","hun":"바늘 침","meaning":"“바늘 침”. 바늘, 침","on":"シン","kun":"はり","explanation":["針 = 金 + 十。","「金」는 “쇠, 금속”을 뜻합니다.","十는 여기서는 “뾰족한 바늘”을 그린 모양자입니다.","針는 “쇠(金)로 된 뾰족한 바늘(十)” -> “바늘, 침”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/727/"},"専":{"id":716,"char":"専","hun":"오로지 전","meaning":"“오로지 전”. 오로지, 전념하다","on":"セン","kun":"もっぱ(ら)","explanation":["専 = 𤰔 + 寸。","「𤰔」는 “방추(실을 감는 도구)”를 그린 글자입니다(링크 참조).","「寸」는 “손”을 뜻합니다.","専는 “방추(𤰔)를 손(寸)으로 계속 돌리다” -> “오로지, 전념하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/728/"},"程":{"id":717,"char":"程","hun":"한도 정","meaning":"“한도 정”. 규정, 정도, 여정","on":"テイ","kun":"ほど","explanation":["程 = 禾 + 口 + 王。","「禾」는 “곡식”을 뜻합니다.","口는 여기서는 “곡식 자루”를 그린 모양자입니다.","王는 여기서는 “무게를 재는 저울”을 그린 모양자입니다.","程는 “세금으로 낼 곡식(禾)의 무게를 저울에 달다(呈)”라는 뜻입니다.","“세금의 규정량” -> “규정, 정도”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/729/"},"値":{"id":718,"char":"値","hun":"값 치","meaning":"“값 치”. 값, 가치","on":"チ","kun":"ね、あたい","explanation":["値 = 亻 + 直。","「亻」는 “사람”을 뜻합니다.","「直」는 “곧다”라는 뜻입니다.","値는 “올곧은(直) 사람(亻)” -> “가치있는 사람” -> “가치, 값”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/730/"},"突":{"id":719,"char":"突","hun":"갑자기 돌","meaning":"“갑자기 돌”. 세차게 부딪치다, 찌르다, 갑작스러운","on":"トツ","kun":"つ(く)","explanation":["突 = 穴 + 大。","「穴」는 “구멍”을 뜻합니다.","「大」는 “크다”라는 뜻입니다.","突는 “구멍(穴)에 커다란 것(大)을 확 찔러넣다” -> “부딪치다, 찌르다, 갑작스러운”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/731/"},"接":{"id":720,"char":"接","hun":"이을 접","meaning":"“이을 접”. 접하다, 접촉하다, 잇다","on":"セツ","kun":"つ(ぐ)","explanation":["接 = 扌 + 妾。","「扌」는 “손”을 뜻합니다.","「女」는 “여자”를 뜻합니다.","立는 여기서는 “땋아올린 여자의 머리”를 그린 모양자입니다.","接는 “여자(女)의 머리(立)를 만지작거리다(扌)” -> “접하다, 접촉하다, 잇다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/732/"},"授":{"id":721,"char":"授","hun":"줄 수","meaning":"“줄 수”. 주다, 전수하다","on":"ジュ","kun":"さず(ける)、さず(かる)","explanation":["授 = 扌 + 受。","(의미부) 「扌」는 “손”을 뜻합니다.","(소리부 겸 의미부) 「受」(ジュ)는 “받다”라는 뜻입니다.","授는 “받는 사람(受)에게 건네주다(扌)” -> “주다, 전수하다”라는 뜻의 글자입니다.","(受는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/733/"},"効":{"id":722,"char":"効","hun":"본받을 효","meaning":"“본받을 효”. 효과, 효능, 효율","on":"コウ","kun":"き(く)","explanation":["効 = 交 + 力。","(소리부 겸 의미부) 「交」(コウ)는 “교차하다, 교제하다”라는 뜻입니다.","(의미부) 「力」는 “힘”을 뜻합니다.","効는 “약효(力)가 몸에 스며들다(交)” -> “효과, 효능, 효율”이라는 뜻의 글자입니다.","(交는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/734/"},"湾":{"id":723,"char":"湾","hun":"물굽이 만","meaning":"“물굽이 만”. (바닷가의) 만, 물굽이","on":"ワン","kun":"","explanation":["湾 = 氵 + 弯。","「氵」는 “물”을 뜻합니다.","弯는 여기서는 “강물(亦)이 굽이쳐 흐르는(弓) 모습”을 그린 모양자입니다.","湾은 “물(氵)이 굽이쳐 흐르는(弯) 곳” -> “만, 물굽이”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/735/"},"処":{"id":724,"char":"処","hun":"곳 처","meaning":"“곳 처”. 머무르다, 처리하다","on":"ショ","kun":"","explanation":["処 = 夂 + 几。","「夂」는 “발”을 뜻합니다.","几는 여기서는 “책상”을 그린 모양자입니다.","処는 “일을 하다가 책상(几)에 기대서서(夂) 쉬다” -> “머무르다, 처리하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/736/"},"旧":{"id":725,"char":"旧","hun":"옛 구","meaning":"“옛 구”. 오랜, 옛날","on":"キュウ","kun":"","explanation":["旧 = 丨 + 日。","「日」는 “날짜”를 뜻합니다.","丨는 여기서는 “(날짜가) 지나가다”라는 뜻을 표현한 모양자입니다.","旧는 “지나간(丨) 나날들(日)” -> “오랜, 옛날”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/737/"},"否":{"id":726,"char":"否","hun":"아닐 부","meaning":"“아닐 부”. 부정, 아니다","on":"ヒ","kun":"いな","explanation":["否 = 不 + 口。","「不」는 “아니다”라는 뜻입니다.","「口」는 “입”을 뜻합니다.","否는 “부정하는(不) 말(口)” -> “아니다, 부정”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/738/"},"師":{"id":727,"char":"師","hun":"스승 사","meaning":"“스승 사”. 전문가, 기술자, 스승, 지도자","on":"シ","kun":"","explanation":["師 = 𠂤 + 帀。","「𠂤」는 “언덕”을 뜻합니다.","帀는 “두르다, 에워싸다”라는 뜻의 글자입니다.","師는 “단상(𠂤) 주위를 에워싸고(帀) 가르침을 받는 제자들” -> “전문가, 스승”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/739/"},"批":{"id":728,"char":"批","hun":"비평할 비","meaning":"“비평할 비”. 비평하다","on":"ヒ","kun":"","explanation":["批 = 扌 + 比。","(의미부) 「扌」는 “손”을 뜻합니다.","(소리부 겸 의미부) 「比」(ヒ)는 “비교하다”라는 뜻입니다.","批는 “손(扌)으로 가리키며 비교하고(比) 평가하다” -> “비평하다”라는 뜻의 글자입니다.","(比는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/740/"},"易":{"id":729,"char":"易","hun":"바꿀 역/쉬울 이","meaning":"“바꿀 역/쉬울 이”. 바꾸다, 쉽다, 운세","on":"エキ、イ","kun":"やさ(しい)","explanation":["易는 “접시(日)에 담긴 물을 쏟아버리는(勿) 모습”을 그린 상형문자입니다.","“물을 쏟아버리고 바꿔 담다” -> “바꾸다”","“바뀌어가는 길흉화복을 점치다” -> “운세”","“물을 쏟아버리는 것은 쉬운 일이다” -> “쉽다”","라는 의미입니다.","주의)","모양이 비슷한 「昜」와 혼동하지 않도록 주의해주세요."],"sourceUrl":"https://nihongokanji.com/741/"},"存":{"id":730,"char":"存","hun":"있을 존","meaning":"“있을 존”. 존재하다, 있다","on":"ソン、ゾン","kun":"","explanation":["存 = 才 + 子。","「才」는 “재능”을 뜻합니다.","「子」는 “아이”를 뜻합니다.","存는 “아이(子)에게는 재능(才)이 있다” -> “있다, 존재하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/742/"},"券":{"id":731,"char":"券","hun":"문서 권","meaning":"“문서 권”. 표, 증서, 권(증권/채권 등)","on":"ケン","kun":"","explanation":["券 = 龹 + 刀。","「刀」는 “칼”을 뜻합니다.","龹는 여기서는 “(칼로 새겨둔) 특별한 표식”을 그린 모양자입니다.","券은 “진짜라는 표식(龹)이 새겨진(刀) 증서” -> “증서, 표”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/743/"},"座":{"id":732,"char":"座","hun":"자리 좌","meaning":"“자리 좌”. 자리, 좌석, 앉다","on":"ザ","kun":"すわ(る)","explanation":["座 = 广 + 土 + 人 + 人。","「广」는 “집, 건물”을 뜻합니다.","「土」는 “땅”을 뜻합니다.","「人」는 “사람”을 뜻합니다.","座는 “집(广)의 바닥(土)에 앉아있는 사람들(人人)” -> “자리, 앉다, 좌석”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/744/"},"破":{"id":733,"char":"破","hun":"깨뜨릴 파","meaning":"“깨뜨릴 파”. 깨뜨리다, 파괴하다","on":"ハ","kun":"やぶ(る)、やぶ(れる)","explanation":["破 = 石 + 皮。","(의미부) 「石」는 “돌”을 뜻합니다.","(소리부 겸 의미부) 「皮」(ヒ)는 “가죽, 표면”을 뜻합니다.","破는 “돌(石)의 표면(皮)을 두드려 깨뜨리다” -> “깨뜨리다, 파괴하다”라는 뜻의 글자입니다.","(皮는 소리부(ヒ -> ハ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/745/"},"編":{"id":734,"char":"編","hun":"엮을 편","meaning":"“엮을 편”. 엮다, 편찬하다, 편집하다","on":"ヘン","kun":"あ(む)","explanation":["編 = 糸 + 扁。","(의미부) 「糸」는 “실”을 뜻합니다.","(소리부 겸 의미부) 「扁」(ヘン)은 “집(戸) 안의 책(冊)”을 뜻하는 글자입니다(링크 참조).","編는 “집 안의 책들(扁)을 하나로 묶다(糸)” -> “엮다, 편찬하다, 편집하다”라는 뜻의 글자입니다.","(扁는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/746/"},"捜":{"id":735,"char":"捜","hun":"찾을 수","meaning":"“찾을 수”. 찾다, 수색하다","on":"ソウ","kun":"さが(す)","explanation":["捜 = 扌 + 申 + 又。","「扌」는 “손”을 뜻합니다.","申는 여기서는 “횃불”을 그린 모양자입니다.","「又」는 “손”을 뜻합니다.","捜는 “양 손(扌+又)에 횃불(申)을 들고 사람을 찾아다니다” -> “찾다, 수색하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/747/"},"除":{"id":736,"char":"除","hun":"덜 제","meaning":"“덜 제”. 제거하다, 없애다","on":"ジョ、ジ","kun":"のぞ(く)","explanation":["除 = ⻖ + 余。","「⻖」는 “언덕”을 뜻합니다.","余는 “잎이 풍성한 나무”를 그린 상형문자입니다.","除는 “언덕(⻖)의 나무(余)를 베다” -> “제거하다, 덜다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/748/"},"降":{"id":737,"char":"降","hun":"내릴 강/항복할 항","meaning":"“내릴 강/항복할 항”. 내리다, 내려오다, 항복하다","on":"コウ","kun":"お(りる)、お(ろす)、ふ(る)","explanation":["降 = ⻖ + 夂 + 㐄。","「⻖」는 “언덕”을 뜻합니다.","「夂」는 “발”을 뜻합니다.","「㐄」는 “발”을 뜻합니다.","降는 “언덕(⻖)을 걸어 내려오다(夂+㐄)” -> “내려가다, 내리다, 항복하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/749/"},"超":{"id":738,"char":"超","hun":"뛰어넘을 초","meaning":"“뛰어넘을 초”. 뛰어넘다, 초월하다","on":"チョウ","kun":"こ(える)、こ(す)","explanation":["超 = 走 + 召。","(의미부) 「走」는 “달리다”라는 뜻입니다.","(소리부 겸 의미부) 召(ショウ – 부를 소)는 “부르다”라는 뜻의 상용한자입니다.","超는 “부름(召)에 응해 달려가다(走)” -> “뛰어넘다”라는 뜻의 글자입니다.","(召는 소리부(ショウ -> チョウ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/750/"},"責":{"id":739,"char":"責","hun":"꾸짖을 책","meaning":"“꾸짖을 책”. 책임, 꾸짖다, 책망하다","on":"セキ","kun":"せ(める)","explanation":["責 = 龶 + 貝。","龶는 여기서는 “무언가가 쌓여있는 모습”을 표현한 모양자입니다.","「貝」는 “돈”을 뜻합니다.","責는 “빚(貝)이 쌓이다(龶)” -> “책임, 책망하다, 꾸짖다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/751/"},"並":{"id":740,"char":"並","hun":"나란히 병","meaning":"“나란히 병”. 나란히","on":"ヘイ","kun":"な(み)、なら(べる)、なら(ぶ)、なら(びに)","explanation":["並는 “나란히 서 있는 두 사람”을 그린 상형문자입니다."],"sourceUrl":"https://nihongokanji.com/752/"},"療":{"id":741,"char":"療","hun":"고칠 료","meaning":"“고칠 료”. 치료하다, 고치다","on":"リョウ","kun":"","explanation":["療 = 疒 + 尞。","(의미부) 「疒」는 “질병, 질환”을 뜻합니다.","(소리부 겸 의미부) 「尞」(リョウ)는 “타오르는 횃불”을 그린 글자입니다(링크 참조).","療는 “병(疒)을 태워버리다(尞)” -> “치료하다, 고치다”라는 뜻의 글자입니다.","(尞는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/753/"},"修":{"id":742,"char":"修","hun":"닦을 수","meaning":"“닦을 수”. 수행하다, 수양하다","on":"シュウ、シュ","kun":"おさ(める)、おさ(まる)","explanation":["修 = 亻 + 丨 + 攵 + 彡。","「亻」는 “사람”을 뜻합니다.","丨는 여기서는 “사람(亻)의 등”을 그린 모양자입니다.","「攵」는 “때리다, 치다”라는 뜻입니다.","彡는 여기서는 “맞아서 난 자국”을 그린 모양자입니다.","修는 “사람(亻)의 등(丨)을 채찍질하며(攵+彡) 단련시키다” -> “수행하다, 수양하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/754/"},"捕":{"id":743,"char":"捕","hun":"잡을 포","meaning":"“잡을 포”. 붙잡다, 잡다","on":"ホ","kun":"と(らえる)、と(らわれる)、と(る)、つか(まえる)、つか(まる)","explanation":["捕 = 扌 + 甫。","(의미부) 「扌」는 “손”을 뜻합니다.","(소리부 겸 의미부) 「甫」(ホ)는 “채소밭”을 뜻합니다.","捕는 “채소밭(甫)에 서리하러 숨어든 도둑을 붙잡다(扌)” -> “붙잡다, 잡다”라는 뜻의 글자입니다.","(甫는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/755/"},"危":{"id":744,"char":"危","hun":"위태할 위","meaning":"“위태할 위”. 위험하다, 위태롭다","on":"キ","kun":"あぶ(ない)、あや(うい)、あや(ぶむ)","explanation":["危 = ⺈ + 厂 + 㔾。","「⺈」는 “칼”을 뜻합니다.","「厂」는 “기슭, 절벽”을 뜻합니다.","「㔾」는 “무릎꿇은 사람”을 뜻하는 글자입니다(링크 참조).","危는 “칼(⺈)에 찔려 절벽(厂) 아래로 굴러 떨어질(㔾) 위기에 처하다” -> “위험하다, 위태롭다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/756/"},"採":{"id":745,"char":"採","hun":"캘 채","meaning":"“캘 채”. 뽑다, 뽑아내다, 취하다","on":"サイ","kun":"と(る)","explanation":["採 = 扌 + 采。","(의미부) 「扌」는 “손”을 뜻합니다.","(소리부 겸 의미부) 「采」(サイ)는 “뽑다, 따다”라는 뜻입니다.","採는 “손(扌)으로 뽑아내다(采)” -> “뽑다, 뽑아내다, 취하다”라는 뜻의 글자입니다.","(采는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/757/"},"拡":{"id":746,"char":"拡","hun":"넓힐 확","meaning":"“넓힐 확”. 확장하다, 넓히다","on":"カク","kun":"","explanation":["拡 = 扌 + 広。","「扌」는 “손”을 뜻합니다.","「広」는 “넓다”라는 뜻입니다.","拡는 “잡아당겨(扌) 넓히다(広)” -> “확장하다, 넓히다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/758/"},"故":{"id":747,"char":"故","hun":"연고 고","meaning":"“연고 고”. 까닭, 이유, 연고","on":"コ","kun":"ゆえ","explanation":["故 = 古 + 攵。","(소리부 겸 의미부) 「古」(コ)는 “옛날, 오래된”이라는 뜻입니다.","(의미부) 「攵」는 “때리다, 치다”라는 뜻입니다.","故는 “과거(古)의 원한을 이유로 때리다(攵)” -> “까닭, 이유, 연고”라는 뜻의 글자입니다.","(古는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/759/"},"介":{"id":748,"char":"介","hun":"끼일 개","meaning":"“끼일 개”. 끼이다, 중개하다","on":"カイ","kun":"","explanation":["介는 “갑옷을 껴입은 모습”을 그린 상형문자입니다.","“갑옷을 껴입다” -> “끼다, 끼이다” -> “중개하다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/760/"},"迎":{"id":749,"char":"迎","hun":"맞을 영","meaning":"“맞을 영”. 맞이하다, 영접하다, 마중하다","on":"ゲイ","kun":"むか(える)","explanation":["迎 = ⻌ + 卬。","「⻌」는 “길”을 뜻합니다.","「卬」는 “우러러보다”라는 뜻의 글자입니다(링크 참조).","迎는 “먼 길(⻌)을 찾아온 손님을 공손히(卬) 맞이하다” -> “맞이하다, 영접하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/761/"},"販":{"id":750,"char":"販","hun":"팔 판","meaning":"“팔 판”. 판매하다","on":"ハン","kun":"","explanation":["販 = 貝 + 反。","(의미부) 「貝」는 “돈, 재물”을 뜻합니다.","(소리부 겸 의미부) 「反」(ハン)은 “돌이키다, 뒤집다, 반대”라는 뜻입니다.","販는 “돈(貝)을 받고 물건을 넘겨주다(反)” -> “판매하다”라는 뜻의 글자입니다.","(反은 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/762/"},"異":{"id":751,"char":"異","hun":"다를 이","meaning":"“다를 이”. 다른, 괴이한","on":"イ","kun":"こと","explanation":["異는 “괴이한 가면(田)을 쓰고 양팔을 벌린 사람”을 그린 상형문자입니다.","“괴상한 사람” -> “괴이하다, 이상하다, 다르다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/763/"},"将":{"id":752,"char":"将","hun":"장차/장수 장","meaning":"“장차/장수 장”. 장래, 앞으로, 장수","on":"ショウ","kun":"","explanation":["将 = 丬 + ⺤ + 寸。","「丬」는 “탁자”를 뜻합니다.","「⺤」는 “손”을 뜻합니다.","「寸」는 “손”을 뜻합니다.","将는 “양 손(⺤+寸)으로 커다란 탁자(丬)를 들어올린 아이”라는 뜻입니다.","“어려서부터 힘이 장사인 아이” -> “장래가 기대되다” -> “장래”","“힘이 강하다” -> “장수, 지휘관”","이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/764/"},"因":{"id":753,"char":"因","hun":"인할 인","meaning":"“인할 인”. 원인, 연유","on":"イン","kun":"よ(る)","explanation":["因 = 囗 + 大。","囗는 여기서는 “침대”를 그린 모양자입니다.","大는 여기서는 “누워있는 사람”을 그린 모양자입니다.","因는 “침대(囗)에 누워있는 사람(大)”이라는 뜻입니다.","“누워서 빈둥거리는 것은 게으름이 원인이다” -> “원인, 연유”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/765/"},"幅":{"id":754,"char":"幅","hun":"폭 폭","meaning":"“폭 폭”. 폭, 너비","on":"フク","kun":"はば","explanation":["幅 = 巾 + 畐。","(의미부) 「巾」는 “수건, 천”을 뜻합니다.","(소리부 겸 의미부) 「畐」(フク)는 “안이 가득 찬 항아리”를 그린 글자입니다.","幅는 “천(巾)으로 항아리(畐)의 둘레를 감싸 폭을 재다” -> “폭, 너비”라는 뜻의 글자입니다.","(畐는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/766/"},"富":{"id":755,"char":"富","hun":"부유할 부","meaning":"“부유할 부”. 부, 부유, 풍족","on":"フ、フウ","kun":"と(む)、とみ","explanation":["富 = 宀 + 畐。","「宀」는 “집”을 뜻합니다.","「畐」는 “가득하다”라는 뜻입니다.","富는 “집(宀)에 재물이 가득하다(畐)” -> “부, 부유, 풍족”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/767/"},"彼":{"id":756,"char":"彼","hun":"저 피","meaning":"“저 피”. 상대방, 저쪽","on":"ヒ","kun":"かれ、かの","explanation":["彼 = 彳 + 皮。","(의미부) 「彳」는 “길”을 뜻합니다.","(소리부 겸 의미부) 「皮」(ヒ)는 “가죽, 표면”을 뜻합니다.","彼는 “길(彳) 바깥쪽(皮)” -> “건너편, 상대방, 저쪽”이라는 뜻의 글자입니다.","(皮는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/768/"},"般":{"id":757,"char":"般","hun":"일반 반","meaning":"“일반 반”. 일반","on":"ハン","kun":"","explanation":["般 = 舟 + 𠘧 + 又。","舟(“배 주”)는 “배”를 뜻하는 상용한자입니다.","𠘧는 여기서는 “고기잡이 그물”을 그린 모양자입니다.","「又」는 “손”을 뜻합니다.","般는 “배(舟)에서 그물(𠘧)을 던져(又) 고기를 잡다”라는 뜻입니다.","“고기를 잡는 것은 일반적인 일이다” -> “일반”이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/769/"},"貿":{"id":758,"char":"貿","hun":"무역할 무","meaning":"“무역할 무”. 무역하다","on":"ボウ","kun":"","explanation":["貿 = 𠂎 + 刀 + 貝。","𠂎+刀는 여기서는 “문을 활짝 열어놓은 모습”을 그린 모양자입니다.","「貝」는 “돈, 재물”을 뜻합니다.","貿는 “활짝 개방된 교역로(𠂎+刀)를 통해 교역을 하다(貝)” -> “무역하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/770/"},"講":{"id":759,"char":"講","hun":"욀 강","meaning":"“욀 강”. 설명하다, 강의하다","on":"コウ","kun":"","explanation":["講 = 言 + 冓。","(의미부) 「言」는 “말하다”라는 뜻입니다.","(소리부 겸 의미부) 「冓」(コウ)는 “얽다, 짜다”라는 뜻입니다.","講는 “짜임새있게(冓) 말하다(言)” -> “설명하다, 강의하다”라는 뜻의 글자입니다.","(冓는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/771/"},"舞":{"id":760,"char":"舞","hun":"춤출 무","meaning":"“춤출 무”. 춤추다","on":"ブ","kun":"ま(う)、まい","explanation":["舞는 “기우제를 지내며 춤을 추는 무희”를 그린 상형문자입니다(「無」와 유래가 같습니다).","“춤추는 무희” -> “춤추다”라는 의미입니다.","참고)","글자 아래쪽의 「舛」는 “두 발, 양발”을 뜻하는 부수입니다(링크 참조).","여기서는 “춤추는 무희의 두 발”을 표현함으로써 無와 의미를 구분한 것입니다."],"sourceUrl":"https://nihongokanji.com/772/"},"装":{"id":761,"char":"装","hun":"꾸밀 장","meaning":"“꾸밀 장”. 꾸미다, 치장하다","on":"ソウ、ショウ","kun":"よそお(う)","explanation":["装 = 丬 + 士 + 衣。","「丬」는 “탁자”를 뜻합니다.","士(“선비 사”)는 “선비, 무사”를 뜻하는 상용한자입니다.","「衣」는 “옷”을 뜻합니다.","装는 “책상(丬) 앞에서 근엄하게 옷(衣)을 차려입고 앉아있는 선비(士)” -> “꾸미다, 치장하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/773/"},"諸":{"id":762,"char":"諸","hun":"모두 제","meaning":"“모두 제”. 모두, 갖가지의","on":"ショ","kun":"","explanation":["諸 = 言 + 者。","(의미부) 「言」는 “말하다”라는 뜻입니다.","(소리부 겸 의미부) 「者」(シャ)는 “사람”을 뜻합니다.","諸는 “모두(者)의 앞에서 연설하다(言)” -> “모두, 갖가지”라는 뜻의 글자입니다.","(者는 소리부(シャ -> ショ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/774/"},"亡":{"id":763,"char":"亡","hun":"망할 망","meaning":"“망할 망”. 망하다, 죽다","on":"ボウ、モウ","kun":"な(い)","explanation":["亡는 “부러진 칼날”을 그린 상형문자입니다.","“부러진 칼날” -> “망하다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/775/"},"劇":{"id":764,"char":"劇","hun":"심할 극","meaning":"“심할 극”. 심하다, 연극","on":"ゲキ","kun":"","explanation":["劇 = 虍 + 豕 + 刂。","「虍」는 “호랑이”를 뜻하는 부수입니다(링크 참조).","「豕」는 “돼지”를 뜻합니다.","「刂」는 “칼”을 뜻합니다.","劇는 “호랑이(虍)와 멧돼지(豕)가 싸우다(刂)”라는 뜻입니다.","“맹수들의 가혹한 싸움” -> “심하다”","“맹수들이 서로 싸우는 모습을 구경하다” -> “공연, 연극”","이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/776/"},"河":{"id":765,"char":"河","hun":"물 하","meaning":"“물 하”. 강","on":"カ","kun":"かわ","explanation":["河 = 氵 + 可。","(의미부) 「氵」는 “물”을 뜻합니다.","(소리부 겸 의미부) 「可」(カ)는 “가능하다”라는 뜻입니다.","河는 “물(氵)을 마실 수 있는(可) 강가” -> “강”이라는 뜻의 글자입니다","(可는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/777/"},"適":{"id":766,"char":"適","hun":"맞을 적","meaning":"“맞을 적”. 알맞다, 적합하다","on":"テキ","kun":"","explanation":["適 = ⻌ + 啇。","(의미부) 「⻌」는 “길”을 뜻합니다.","(소리부 겸 의미부) 「啇」(テキ)는 “화초를 심은 화분”을 뜻하는 글자입니다(링크 참조).","適는 “화초(啇)를 심기 적합하게 가꾸어진 꽃길(⻌)” -> “알맞다, 적합하다”라는 뜻의 글자입니다.","(啇는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/778/"},"婦":{"id":767,"char":"婦","hun":"며느리 부","meaning":"“며느리 부”. 아내","on":"フ","kun":"","explanation":["婦 = 女 + 帚。","「女」는 “여자”를 뜻합니다.","「帚」는 “빗자루”를 뜻합니다.","婦는 “빗자루(帚)를 들고 집을 청소하는 아내(女)” -> “아내”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/779/"},"寄":{"id":768,"char":"寄","hun":"부칠 기","meaning":"“부칠 기”. 맡기다, 부치다, 들르다","on":"キ","kun":"よ(る)、よ(せる)","explanation":["寄 = 宀 + 大 + 可。","「宀」는 “집”을 뜻합니다.","「大」는 본래 “사람”을 그린 글자입니다(링크 참조).","可는 여기서는 “짐보따리”를 그린 모양자입니다(79.「何」모양 해설 참조).","寄는 “남의 집(宀)에 짐(可)을 맡겨놓으러 들른 사람(大)” -> “맡기다, 부치다, 들르다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/780/"},"込":{"id":769,"char":"込","hun":"담을 입","meaning":"“담을 입”. 붐비다, 들어가다, 속에 넣다","on":"","kun":"こ(む)、こ(める)","explanation":["込 = ⻌ + 入。","「⻌」는 “길”을 뜻합니다.","「入」는 “들어가다”라는 뜻입니다.","込는 “길(⻌)에 들어가다(入)” -> “들어가다, 붐비다, 속에 넣다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/781/"},"余":{"id":770,"char":"余","hun":"남을 여","meaning":"“남을 여”. 남다, 여분","on":"ヨ","kun":"あま(る)、あま(す)","explanation":["余는 “잎이 풍성한 나무”를 그린 상형문자입니다.","“잎이 풍성하다” -> “남다, 여분”이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/782/"},"禁":{"id":771,"char":"禁","hun":"금할 금","meaning":"“금할 금”. 금지하다","on":"キン","kun":"","explanation":["禁 = 林 + 示。","「林」는 “숲”을 뜻합니다.","「示」는 “신, 종교, 고대의 비석”을 뜻합니다.","禁는 “신성한 숲(林) 앞에 비석(示)을 세우고 들어가지 못하도록 막다” -> “금지하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/783/"},"逆":{"id":772,"char":"逆","hun":"거스를 역","meaning":"“거스를 역”. 거꾸로, 거스르다, 반항하다","on":"ギャク","kun":"さか、さか(らう)","explanation":["逆 = ⻌ + 屰。","「⻌」는 “길”을 뜻합니다.","「屰」는 “거꾸로”라는 뜻의 글자로, “거꾸로 선 사람”을 그린 글자입니다(링크 참조).","逆는 “길(⻌)을 거꾸로(屰) 가다” -> “거꾸로, 거스르다, 반항하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/784/"},"換":{"id":773,"char":"換","hun":"바꿀 환","meaning":"“바꿀 환”. 바꾸다, 교환하다","on":"カン","kun":"か(える)、か(わる)","explanation":["換 = 扌 + 奐。","(의미부) 「扌」는 “손”을 뜻합니다.","(소리부 겸 의미부) 「奐」(カン)은 “태어나는 아기를 받아내는 모습”을 그린 글자입니다(링크 참조).","換는 “산파가 태어나는 아기(奐)를 받아서 산모에게 넘겨주다(扌)” -> “바꾸다, 교환하다”라는 뜻의 글자입니다.","(奐는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/785/"},"久":{"id":774,"char":"久","hun":"오랠 구","meaning":"“오랠 구”. 오래다, 길다","on":"キュウ、ク","kun":"ひさ(しい)","explanation":["久는 “옆으로 누운 사람”을 그린 상형문자입니다.","“옆으로 누워 오랫동안 잠만 자다” -> “오래다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/786/"},"妻":{"id":775,"char":"妻","hun":"아내 처","meaning":"“아내 처”. 아내, 처","on":"サイ","kun":"つま","explanation":["妻 = 十 + ⺕ + 女。","「⺕」는 “손”을 뜻합니다.","「女」는 “여자”를 뜻합니다.","十는 여기서는 “여자의 머리칼”을 그린 모양자입니다.","妻는 “아내(女)의 머리(十)를 쓰다듬어주다(⺕)” -> “아내”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/787/"},"暴":{"id":776,"char":"暴","hun":"사나울 폭","meaning":"“사나울 폭”. 난폭한, 거친, 드러내다","on":"ボウ、バク","kun":"あば(く)、あば(れる)","explanation":["暴 = 日 + 共 + 氺。","「日」는 “태양”을 뜻합니다.","「共」는 “함께, 같이”라는 뜻입니다.","氺는 여기서는 「水」가 살짝 변형된 것으로, “물”을 뜻합니다.","暴는 “강물(水)이 한꺼번에(共) 말라 버릴 정도로 매서운 햇빛(日)” -> “거친, 난폭한”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/788/"},"占":{"id":777,"char":"占","hun":"점령할/점칠 점","meaning":"“점령할/점칠 점”. 점령하다, 점거하다, 점치다","on":"セン","kun":"し(める)、うらな(う)","explanation":["占 = 卜 + 口。","「卜」는 “점, 점괘”를 뜻합니다.","口는 여기서는 “점술 도구가 보관된 통”을 그린 모양자입니다.","占는 “점술 도구(卜)와 보관함(口)”이라는 뜻입니다.","“점쟁이가 자리를 잡고 점을 치다” -> “점거하다, 점치다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/789/"},"背":{"id":778,"char":"背","hun":"등 배","meaning":"“등 배”. 등, 뒤쪽/배후, 키, 배반하다","on":"ハイ","kun":"せ、せい、そむ(く)、そむ(ける)","explanation":["背 = 北 + 月。","「北」는 본래 “두 사람이 등을 맞대고 있는 모습”을 그린 글자입니다(링크 참조).","「月」는 “신체의 일부”를 뜻합니다.","背는 “등(北) + 신체 부위(月)” -> “등, 뒤쪽, 배후”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/790/"},"険":{"id":779,"char":"険","hun":"험할 험","meaning":"“험할 험”. 험하다, 위험하다","on":"ケン","kun":"けわ(しい)","explanation":["険 = ⻖ + 㑒。","(의미부) 「⻖」는 “언덕, 산”을 뜻합니다.","(소리부 겸 의미부) 「㑒」(ケン)은 “날카롭다, 뾰족하다”라는 뜻입니다.","険는 “날카롭게 깎아지른(㑒) 산맥(⻖)” -> “위험하다”라는 뜻의 글자입니다.","(㑒는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/791/"},"頼":{"id":780,"char":"頼","hun":"의뢰할 뢰","meaning":"“의뢰할 뢰”. 부탁하다, 의지하다, 신뢰하다","on":"ライ","kun":"たの(む)、たの(もしい)、たよ(る)","explanation":["頼 = 束 + 頁。","「束」는 “묶다”라는 뜻입니다.","「頁」는 “머리”를 뜻합니다.","頼는 “머리(頁)를 한데 모아(束) 함께 의논하다” -> “의지하다, 신뢰하다, 부탁하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/792/"},"均":{"id":781,"char":"均","hun":"고를 균","meaning":"“고를 균”. 고르다, 평균","on":"キン","kun":"","explanation":["均 = 土 + 匀。","「土」는 “땅”을 뜻합니다.","匀는 “고르다, 평평하다”라는 뜻의 글자로, “줄이 가지런히 늘어선 현악기”를 그린 상형문자입니다.","均는 “고르고 평평한(匀) 땅(土)” -> “고르다, 평균”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/793/"},"途":{"id":782,"char":"途","hun":"길 도","meaning":"“길 도”. 길","on":"ト","kun":"","explanation":["途 = ⻌ + 余。","「⻌」는 “길”을 뜻합니다.","「余」는 본래 “잎이 풍성한 나무”를 그린 글자입니다(링크 참조).","途는 “가로수(余)가 늘어선 길(⻌)” -> “길”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/794/"},"圧":{"id":783,"char":"圧","hun":"누를 압","meaning":"“누를 압”. 누르다, 압력","on":"アツ","kun":"","explanation":["圧 = 厂 + 土。","厂는 여기서는 “위에서 찍어누르는 손”을 그린 모양자입니다.","「土」는 “흙”을 뜻합니다.","圧는 “흙(土)을 눌러 뭉치다(厂)” -> “압력, 누르다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/795/"},"許":{"id":784,"char":"許","hun":"허락할 허","meaning":"“허락할 허”. 허락하다, 허가하다","on":"キョ","kun":"ゆる(す)","explanation":["許 = 言 + 午。","(의미부) 「言」는 “말하다”라는 뜻입니다.","(소리부) 「午」(ゴ)는 여기서는 소리부(ゴ -> キョ)의 역할만 하고 있습니다.","許는 “허락을 내리다(言)” -> “허락하다”라는 뜻의 글자입니다(午는 소리부)."],"sourceUrl":"https://nihongokanji.com/796/"},"署":{"id":785,"char":"署","hun":"마을 서","meaning":"“마을 서”. 관청, 부서, 서명","on":"ショ","kun":"","explanation":["署 = 罒 + 者。","「罒」는 “그물”을 뜻합니다.","「者」는 “사람”을 뜻합니다.","署는 “그물(罒)처럼 조직적으로 얽힌 사람들(者)” -> “관청, 부서” -> “서명”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/797/"},"抜":{"id":786,"char":"抜","hun":"뽑을 발","meaning":"“뽑을 발”. 뽑다, 가려내다","on":"バツ","kun":"ぬ(く)、ぬ(ける)、ぬ(かす)、ぬ(かる)","explanation":["抜 = 扌 + 𠂇 + 又。","「扌」는 “손”을 뜻합니다.","「又」는 “손”을 뜻합니다.","𠂇는 여기서는 “손에 박힌 가시”를 그린 모양자입니다.","抜는 “손(扌)에 박힌 가시(𠂇)를 뽑아내다(又)” -> “뽑다, 가려내다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/798/"},"伸":{"id":787,"char":"伸","hun":"펼 신","meaning":"“펼 신”. 뻗다, 펴다","on":"シン","kun":"の(びる)、の(ばす)、の(べる)","explanation":["伸 = 亻 + 申。","(의미부) 「亻」는 “사람”을 뜻합니다.","(소리부 겸 의미부) 「申」(シン)은 본래 “번개가 내리치는 모습”을 그린 글자입니다.","여기서는 “번개” -> “길게 뻗다, 뻗치다”라는 뜻으로 쓰인 것입니다.","伸는 “사람(亻)이 몸을 길게 뻗다(申)” -> “뻗다, 펴다”라는 뜻의 글자입니다.","(申는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/799/"},"留":{"id":788,"char":"留","hun":"머무를 류","meaning":"“머무를 류”. 머무르다, 남기다","on":"リュウ、ル","kun":"と(める)、と(まる)","explanation":["留 = 𠂎 + 刀 + 田。","𠂎+刀는 여기서는 “밭을 갈고 있는 사람들”을 그린 모양자입니다.","「田」는 “밭”을 뜻합니다.","留는 “밭(田)을 경작하며(𠂎+刀) 한 곳에 머물러 살다” -> “머무르다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/800/"},"罪":{"id":789,"char":"罪","hun":"허물 죄","meaning":"“허물 죄”. 죄, 허물","on":"ザイ","kun":"つみ","explanation":["罪 = 罒 + 非。","「罒」는 “그물”을 뜻합니다.","「非」는 “아니다, 옳지 않다”라는 뜻입니다.","罪는 “잘못(非)을 저지른 사람이 붙잡히다(罒)” -> “죄”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/801/"},"爆":{"id":790,"char":"爆","hun":"터질 폭","meaning":"“터질 폭”. 터지다, 폭발하다","on":"バク","kun":"","explanation":["爆 = 火 + 暴。","(의미부) 「火」는 “불”을 뜻합니다.","(소리부 겸 의미부) 「暴」(バク)는 “난폭한, 거친”이라는 뜻입니다.","爆는 “불(火)이 격렬하게(暴) 타오르다” -> “폭발하다, 터지다”라는 뜻의 글자입니다.","(暴는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/802/"},"延":{"id":791,"char":"延","hun":"늘일 연","meaning":"“늘일 연”. 늘이다, 늦어지다","on":"エン","kun":"の(びる)、の(ばす)、の(べる)","explanation":["延 = 廴 + 一 + 止。","「廴」는 “길”을 뜻합니다.","「止」는 “발”을 뜻합니다.","위쪽의 一는 여기서는 “발걸음(止)이 늘어지는 모습”을 표현한 모양자입니다.","延는 “길(廴)을 느릿느릿(一) 걷다(止)” -> “늘이다, 늦어지다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/803/"},"精":{"id":792,"char":"精","hun":"정할 정","meaning":"“정할 정”. 정기, 정신, 순수한, 세밀한","on":"セイ、ショウ","kun":"","explanation":["精 = 米 + 青。","(의미부) 「米」는 “쌀”을 뜻합니다.","(소리부 겸 의미부) 「青」(セイ・ショウ)는 “푸르다”라는 뜻입니다.","精는 “깨끗한(青) 쌀(米)” -> “맑다, 깨끗하다” -> “정기, 정신, 순수한, 세밀한”이라는 뜻의 글자입니다.","(青는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/804/"},"則":{"id":793,"char":"則","hun":"법칙 칙","meaning":"“법칙 칙”. 규칙, 법칙","on":"ソク","kun":"","explanation":["則 = 貝 + 刂。","「貝」는 “돈, 재물”을 뜻합니다.","「刂」는 “칼”을 뜻합니다.","則는 “법과 규칙은 돈(貝)과 무력(刂)을 가진 자에 의해 결정된다” -> “법칙, 규정”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/805/"},"乱":{"id":794,"char":"乱","hun":"어지러울 란","meaning":"“어지러울 란”. 혼란한, 어지러운, 음란한","on":"ラン","kun":"みだ(れる)、みだ(す)","explanation":["乱 = 舌 + 乚。","「舌」는 “혀”를 뜻합니다.","乚는 여기서는 “여자의 가슴”을 그린 모양자입니다.","乱는 “입맞춤(舌) + 여자의 가슴(乚)” -> “음란한, 어지러운, 혼란한”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/806/"},"普":{"id":795,"char":"普","hun":"넓을 보","meaning":"“넓을 보”. 넓다, 보편적인","on":"フ","kun":"","explanation":["普 = 並 + 日。","「並」는 “나란히”라는 뜻입니다.","「日」는 “태양”을 뜻합니다.","普는 “하늘의 태양(日)은 모두에게(並) 골고루 내리쬔다” -> “넓다, 보편적인”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/807/"},"測":{"id":796,"char":"測","hun":"헤아릴 측","meaning":"“헤아릴 측”. (길이/넓이/온도 등을)재다, 측정하다","on":"ソク","kun":"はか(る)","explanation":["測 = 氵 + 則。","(의미부) 「氵」는 “물”을 뜻합니다.","(소리부 겸 의미부) 「則」(ソク)는 “법칙, 규칙”을 뜻합니다.","測는 “물(氵)의 양을 기준(則)에 따라 재다” -> “재다, 측정하다”라는 뜻의 글자입니다.","(則는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/808/"},"豊":{"id":797,"char":"豊","hun":"풍년 풍","meaning":"“풍년 풍”. 풍부한, 풍성한","on":"ホウ","kun":"ゆた(か)","explanation":["豊 = 曲 + 豆。","「豆」는 “제기그릇”을 뜻합니다.","曲는 여기서는 “그릇 위에 가득 쌓인 음식”을 그린 모양자입니다.","豊는 “음식이 가득 쌓인(曲) 그릇(豆)” -> “풍부한, 풍성한”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/809/"},"善":{"id":798,"char":"善","hun":"착할 선","meaning":"“착할 선”. 착하다, 바르다","on":"ゼン","kun":"よ(い)","explanation":["善 = 羊 + 䒑 + 口。","「羊」는 “양”을 뜻합니다.","䒑+口는 여기서는 “양의 눈”을 그린 모양자입니다.","善는 “양(羊)의 눈망울(䒑+口)” -> “착하다, 바르다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/810/"},"婚":{"id":799,"char":"婚","hun":"혼인할 혼","meaning":"“혼인할 혼”. 혼인하다","on":"コン","kun":"","explanation":["婚 = 女 + 氏 + 日。","「女」는 “여자”를 뜻합니다.","氏(“성씨 씨”)는 “성씨”를 뜻하는 상용한자입니다.","「日」는 “날”을 뜻합니다.","일본에서는 여자가 결혼하면 남편의 성을 따르게 됩니다.","婚는 “여자(女)가 남편의 성씨(氏)를 따라 이름을 바꾸는 날(日)” -> “혼인하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/811/"},"厚":{"id":800,"char":"厚","hun":"두터울 후","meaning":"“두터울 후”. 두껍다","on":"コウ","kun":"あつ(い)","explanation":["厚 = 厂 + 日 + 子。","「厂」는 “절벽”을 뜻합니다.","「日」는 “태양”을 뜻합니다.","「子」는 “아이”를 뜻합니다.","厚는 “대낮(日)에도 절벽(厂)아래 그늘에서 잠만 자는 게으른 아이(子)” -> “낮짝이 두껍다” -> “두껍다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/812/"},"齢":{"id":801,"char":"齢","hun":"나이 령","meaning":"“나이 령”. 나이","on":"レイ","kun":"","explanation":["齢 = 歯 + 令。","(의미부) 「歯」는 “이, 치아”를 뜻합니다.","(소리부) 「令」(レイ)는 여기서는 소리부의 역할만 하고 있습니다.","齢는 “이(歯)가 나기 시작하는 나이” -> “나이”라는 뜻의 글자입니다(令는 소리부)."],"sourceUrl":"https://nihongokanji.com/813/"},"略":{"id":802,"char":"略","hun":"간략할 략","meaning":"“간략할 략”. 생각, 계책, 간략, 생략","on":"リャク","kun":"","explanation":["略 = 田 + 各。","「田」는 “밭”을 뜻합니다.","「各」는 “각각, 각자”라는 뜻입니다.","略는 “각자(各)에게 논밭(田)을 분배하다”라는 뜻입니다.","“논밭을 계획적으로 분배하다” -> “계획, 계책, 생각”","“논밭을 여러 개로 나눠 각자가 담당할 면적을 줄이다” -> “간략, 생략”","이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/814/"},"承":{"id":803,"char":"承","hun":"이을 승","meaning":"“이을 승”. 계승하다, 승낙하다","on":"ショウ","kun":"うけたまわ(る)","explanation":["承는 “높은 사람을 두 손으로 떠받들고 있는 모습”을 그린 상형문자입니다.","“받들어 모시다” -> “받들다, 계승하다, 승낙하다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/815/"},"浮":{"id":804,"char":"浮","hun":"뜰 부","meaning":"“뜰 부”. 뜨다, 떠오르다","on":"フ","kun":"う(く)、う(かぶ)、う(かべる)、う(かれる)","explanation":["浮 = 氵 + ⺤ + 子。","「氵」는 “물”을 뜻합니다.","「⺤」는 “손”을 뜻합니다.","「子」는 “아이”를 뜻합니다.","浮는 “물(氵)에 빠진 아이(子)를 건져내다(⺤)” -> “뜨다, 떠오르다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/816/"},"絶":{"id":805,"char":"絶","hun":"끊을 절","meaning":"“끊을 절”. 끊다, 끊어지다, 대단히","on":"ゼツ","kun":"た(える)、た(やす)、た(つ)","explanation":["絶 = 糸 + ⺈ + 巴。","「糸」는 “실”을 뜻합니다.","「⺈」는 “칼”을 뜻합니다.","「巴」는 “꼬리”를 뜻하는 글자입니다(링크 참조).","絶는 “실타래(糸)에서 빠져나온 꼬리(巴)를 자르다(⺈)” -> “끊다, 끊어지다” -> “절세의, 대단한”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/817/"},"押":{"id":806,"char":"押","hun":"누를 압","meaning":"“누를 압”. 누르다, 억누르다","on":"オウ","kun":"お(す)、お(さえる)","explanation":["押 = 扌 + 甲。","「扌」는 “손”을 뜻합니다.","甲(“갑옷 갑”)은 “갑옷”을 뜻하는 상용한자입니다.","押는 “갑옷(甲)을 꽉 눌러(扌) 입다” -> “누르다, 억누르다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/818/"},"倒":{"id":807,"char":"倒","hun":"넘어질 도","meaning":"“넘어질 도”. 넘어지다, 쓰러지다","on":"トウ","kun":"たお(れる)、たお(す)","explanation":["倒 = 亻 + 至 + 刂。","「亻」는 “사람”을 뜻합니다.","至(“이를 지”)는 “화살이 과녁에 날아가 박힌 모습”을 그린 상용한자입니다.","「刂」는 “칼”을 뜻합니다.","倒는 “사람(亻)이 화살(至)과 칼(刂)에 맞아 쓰러지다” -> “넘어지다, 쓰러지다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/819/"},"了":{"id":808,"char":"了","hun":"마칠 료","meaning":"“마칠 료”. 마치다, 끝내다","on":"リョウ","kun":"","explanation":["了는 “갓 태어나 몸을 웅크리고 있는 아이”를 그린 상형문자입니다.","(子에서 양 팔을 몸에 붙인 형태로 생각하시면 됩니다.)","“출산을 마치다” -> “마치다, 끝내다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/820/"},"庁":{"id":809,"char":"庁","hun":"관청 청","meaning":"“관청 청”. 관청","on":"チョウ","kun":"","explanation":["庁 = 广 + 丁。","(의미부) 「广」는 “건물, 집”을 뜻합니다.","(소리부) 「丁」(チョウ)는 여기서는 소리부의 역할만 하고 있습니다.","庁는 “큰 건물(广)” -> “관청”이라는 뜻의 글자입니다(丁는 소리부)."],"sourceUrl":"https://nihongokanji.com/821/"},"城":{"id":810,"char":"城","hun":"재 성","meaning":"“재 성”. 성(castle)","on":"ジョウ","kun":"しろ","explanation":["城 = 土 + 成。","(의미부) 「土」는 “흙”을 뜻합니다.","(소리부 겸 의미부) 「成」(ジョウ)는 “이루다, 성취하다”라는 뜻입니다.","城는 “흙(土)을 높이 쌓아 성벽을 완성시키다(成)” -> “성”이라는 뜻의 글자입니다.","(成는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/822/"},"層":{"id":811,"char":"層","hun":"층 층","meaning":"“층 층”. 층, 계급","on":"ソウ","kun":"","explanation":["層 = 尸 + 曽。","(의미부) 「尸」는 “집, 지붕”을 뜻합니다.","(소리부 겸 의미부) 「曽」(ソウ)는 “쌓이다”라는 뜻입니다.","層는 “층층이 쌓인(曽) 건물(尸)” -> “층, 계급”이라는 뜻의 글자입니다.","(曽는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/823/"},"版":{"id":812,"char":"版","hun":"판목 판","meaning":"“판목 판”. 판, 출판, 장부","on":"ハン","kun":"","explanation":["版 = 片 + 反。","(의미부) 片(“조각 편”)은 “나무판자를 이어붙인 모습”을 그린 상용한자입니다.","(소리부) 「反」(ハン)은 여기서는 소리부의 역할만 하고 있습니다.","版는 “글자를 새겨놓은 인쇄용 나무판(片)” -> “판, 출판, 장부”라는 뜻의 글자입니다(反는 소리부)."],"sourceUrl":"https://nihongokanji.com/824/"},"絡":{"id":813,"char":"絡","hun":"이을 락","meaning":"“이을 락”. 잇다, 동여매다, 얽다","on":"ラク","kun":"から(む)、から(まる)、から(める)","explanation":["絡 = 糸 + 各。","「糸」는 “실”을 뜻합니다.","「各」는 “각자, 각각”을 뜻합니다.","絡는 “각자(各) 떨어져있던 것들을 하나로 잇다(糸)” -> “잇다, 동여매다, 얽다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/825/"},"損":{"id":814,"char":"損","hun":"덜 손","meaning":"“덜 손”. 손해보다, 상처내다","on":"ソン","kun":"そこ(なう)、そこ(ねる)","explanation":["損 = 扌 + 員。","「扌」는 “손”을 뜻합니다.","「員」는 “인원, 점원”을 뜻합니다.","損는 “매출 감소로 인원수(員)를 덜어내다(扌)” -> “손해보다, 상처내다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/826/"},"募":{"id":815,"char":"募","hun":"모을 모","meaning":"“모을 모”. 모집하다, 뽑다","on":"ボ","kun":"つの(る)","explanation":["募 = 莫 + 力。","(소리부 겸 의미부) 「莫」(ボ)는 “없다”라는 뜻의 글자입니다(링크 참조).","(의미부) 「力」는 “힘”을 뜻합니다.","募는 “인력(力)이 부족해(莫) 사람을 모집하다” -> “모집하다, 뽑다”라는 뜻의 글자입니다.","(莫는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/827/"},"裏":{"id":816,"char":"裏","hun":"속 리","meaning":"“속 리”. 내부, 뒷면, 이면","on":"リ","kun":"うら","explanation":["裏 = 衣 + 里。","(의미부) 「衣」는 “옷”을 뜻합니다.","(소리부 겸 의미부) 「里」(リ)는 “마을”을 뜻합니다. 여기서는 “마을 안” -> “안쪽, 내부”라는 뜻입니다.","裏는 “옷(衣)의 안쪽(里)” -> “내부” -> “뒷면, 이면”이라는 뜻의 글자입니다.","(里는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/828/"},"払":{"id":817,"char":"払","hun":"떨칠 불","meaning":"“떨칠 불”. 떨쳐내다, 털어버리다","on":"フツ","kun":"はら(う)","explanation":["払 = 扌 + 厶。","「扌」는 “손”을 뜻합니다.","「厶」는 “팔을 안으로 굽힌 모습”을 그린 글자입니다.","払는 “손(扌)으로 닦아내다(厶)” -> “떨쳐내다, 털어버리다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/829/"},"仏":{"id":818,"char":"仏","hun":"부처 불","meaning":"“부처 불”. 부처","on":"ブツ","kun":"ほとけ","explanation":["仏 = 亻 + 厶。","「亻」는 “사람”을 뜻합니다.","「厶」는 “팔을 안으로 굽힌 모습”을 그린 글자입니다.","仏는 “모두를 포용하는(厶) 부처님(亻)의 자비” -> “부처”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/830/"},"績":{"id":819,"char":"績","hun":"길쌈할 적","meaning":"“길쌈할 적”. 성과, 업적, 실을 뽑다","on":"セキ","kun":"","explanation":["績 = 糸 + 龶 + 貝。","「糸」는 “실”을 뜻합니다.","龶는 여기서는 “무언가가 쌓여있는 모습”을 그린 모양자입니다.","「貝」는 “돈, 재물”을 뜻합니다.","績는 “실(糸)을 짜서 많은(龶) 돈을(貝) 벌다” -> “실을 뽑다, 성과, 업적”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/831/"},"築":{"id":820,"char":"築","hun":"쌓을 축","meaning":"“쌓을 축”. 쌓다, 짓다","on":"チク","kun":"きず(く)","explanation":["築 = 𥫗 + 工 + 凡 + 木。","(소리부 겸 의미부) 「𥫗」(チク)는 “대나무”를 뜻합니다.","(의미부) 「工」는 “공작, 가공, 공정”을 뜻합니다.","(의미부) 凡(“무릇 범”)은 “평범하다”라는 뜻의 상용한자입니다.","(의미부) 「木」는 “나무”를 뜻합니다.","筑는 “대나무(𥫗)와 목재(木)로 집을 쌓는(工) 평범한(凡) 공사장 인부들” -> “쌓다, 짓다”라는 뜻의 글자입니다.","(𥫗는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/832/"},"志":{"id":821,"char":"志","hun":"뜻 지","meaning":"“뜻 지”. 목적, 목표","on":"シ","kun":"こころざ(す)、こころざし","explanation":["志 = 士 + 心。","(소리부 겸 의미부) 士(シ – “선비 사”)는 “선비, 무사”를 뜻하는 상용한자입니다.","(의미부) 「心」는 “마음”을 뜻합니다.","志는 “선비(士)가 마음(心)에 품은 높은 뜻” -> “목적, 목표”라는 뜻의 글자입니다.","(士는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/833/"},"混":{"id":822,"char":"混","hun":"섞을 혼","meaning":"“섞을 혼”. 섞다, 섞이다, 혼잡한","on":"コン","kun":"ま(じる)、ま(ざる)、ま(ぜる)、こ(む)","explanation":["混 = 氵 + 日 + 比。","「氵」는 “물”을 뜻합니다.","「日」는 “태양”을 뜻합니다.","「比」는 본래 “나란히 서 있는 사람들”을 그린 글자입니다(링크 참조).","混는 “더위(日)를 피해 다함께 강물(氵)에 뛰어든 사람들(比)”이라는 뜻입니다.","“한데 뒤섞여 물놀이하는 사람들” -> “섞다, 섞이다, 혼잡한”이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/834/"},"昇":{"id":823,"char":"昇","hun":"오를 승","meaning":"“오를 승”. 오르다, 상승하다","on":"ショウ","kun":"のぼ(る)","explanation":["昇 = 日 + 升。","「日」는 “태양”을 뜻합니다.","升는 여기서는 “양손으로 떠받치는 모습”을 그린 모양자입니다.","日는 “태양(日)이 하늘로 떠오르다(升)” -> “오르다, 상승하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/835/"},"勤":{"id":824,"char":"勤","hun":"부지런할 근","meaning":"“부지런할 근”. 근면하다, 근무하다","on":"キン、ゴン","kun":"つと(める)、つと(まる)","explanation":["勤 = 堇 + 力。","(소리부 겸 의미부) 「堇」(キン)은 “처벌, 형벌”을 뜻하는 글자입니다(링크 참조).","(의미부) 「力」는 “힘”을 뜻합니다.","勤는 “처벌(堇)받지 않기 위해 열심히(力) 일하다” -> “근면하다, 근무하다”라는 뜻의 글자입니다.","(堇는 소리부(キン -> キン・ゴン)도 겸함)"],"sourceUrl":"https://nihongokanji.com/836/"},"遅":{"id":825,"char":"遅","hun":"늦을 지","meaning":"“늦을 지”. 늦다, 더디다","on":"チ","kun":"おく(れる)、おく(らす)、おそ(い)","explanation":["遅 = ⻌ + 尸 + 羊。","「⻌」는 “길”을 뜻합니다.","「尸」는 “앉다”라는 뜻입니다.","「羊」는 “양”을 뜻합니다.","遅는 “양(羊)을 타고(尸) 길을 가다(⻌)” -> “늦다, 더디다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/837/"},"居":{"id":826,"char":"居","hun":"살 거","meaning":"“살 거”. 살다, 거주하다","on":"キョ","kun":"い(る)","explanation":["居 = 尸 + 古。","(의미부) 「尸」는 “집, 지붕”을 뜻합니다.","(소리부 겸 의미부) 「古」(コ)는 “오래되다, 낡다”라는 뜻입니다.","居는 “오랫동안(古) 살아온 집(尸)” -> “살다, 거주하다”라는 뜻의 글자입니다.","(古는 소리부(コ -> キョ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/838/"},"雑":{"id":827,"char":"雑","hun":"섞일 잡","meaning":"“섞일 잡”. 잡다한, 뒤섞인, 난잡한, 잡스러운","on":"ザツ、ゾウ","kun":"","explanation":["雑 = 九 + 木 + 隹。","「九」는 “9”를 뜻합니다.","「木」는 “나무”를 뜻합니다.","「隹」는 “새”를 뜻합니다.","雑는 “나무(木) 위에 앉아있는 아홉(九) 종류의 새(隹)”라는 뜻입니다.","“여러 종류의 잡다한 새들” -> “잡다한, 뒤섞인, 잡스러운”이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/839/"},"招":{"id":828,"char":"招","hun":"부를 초","meaning":"“부를 초”. 초대하다, 부르다","on":"ショウ","kun":"まね(く)","explanation":["招 = 扌 + 召。","(의미부) 「扌」는 “손”을 뜻합니다.","(소리부 겸 의미부) 召(ショウ – 부를 소)는 “부르다”라는 뜻의 상용한자입니다.","招는 “손짓해서(扌) 부르다(召)” -> “초대하다, 부르다”라는 뜻의 글자입니다.","(召는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/840/"},"困":{"id":829,"char":"困","hun":"곤할 곤","meaning":"“곤할 곤”. 곤란하다","on":"コン","kun":"こま(る)","explanation":["困 = 囗 + 木。","囗는 여기서는 “출입구”를 그린 모양자입니다.","「木」는 “나무”를 뜻합니다.","困는 “출입구(囗)를 가로막은 나무(木)” -> “장애물” -> “곤란하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/841/"},"永":{"id":830,"char":"永","hun":"길 영","meaning":"“길 영”. 기나긴, 영원의","on":"エイ","kun":"なが(い)","explanation":["永는 “길게 굽이쳐 흐르는 강”을 그린 상형문자입니다.","“길다란 강” -> “길다, 영원하다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/842/"},"著":{"id":831,"char":"著","hun":"나타날 저","meaning":"“나타날 저”. 현저하다, 저명하다, 저술하다","on":"チョ","kun":"あらわ(す)、いちじる(しい)","explanation":["著 = 艹 + 者。","「艹」는 “풀”을 뜻합니다.","「者」는 “사람”을 뜻합니다.","著는 “월계관(艹)을 쓴 사람(者)” -> “현저하다, 저명하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/843/"},"誌":{"id":832,"char":"誌","hun":"기록할 지","meaning":"“기록할 지”. 기록하다, ~지(잡지 등)","on":"シ","kun":"","explanation":["誌 = 言 + 志。","(의미부) 「言」는 “말하다”라는 뜻입니다.","(소리부 겸 의미부) 「志」(シ)는 “목적, 목표”를 뜻합니다.","誌는 “목표(志)를 말(言)로 써서 기록해두다” -> “기록하다”라는 뜻의 글자입니다.","(志는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/844/"},"刊":{"id":833,"char":"刊","hun":"새길 간","meaning":"“새길 간”. 출판하다, 간행하다","on":"カン","kun":"","explanation":["刊 = 干 + 刂。","(소리부 겸 의미부) 干(カン – “방패 간”)은 “방패”를 뜻하는 상용한자입니다.","(의미부) 「刂」는 “칼”을 뜻합니다.","刊는 “방패(干) 모양의 나무판에 글자를 새겨(刂) 인쇄하다” -> “간행하다, 출판하다”라는 뜻의 글자입니다.","(干는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/845/"},"像":{"id":834,"char":"像","hun":"모양 상","meaning":"“모양 상”. 형체, 형상","on":"ゾウ","kun":"","explanation":["像 = 亻 + 象。","(의미부) 「亻」는 “사람”을 뜻합니다.","(소리부 겸 의미부) 「象」(ゾウ)는 “형상”을 뜻합니다.","像는 “사람(亻)을 본뜬 형상(象)” -> “형체, 형상”이라는 뜻의 글자입니다.","(象는 소리부도 겸함)","참고)","象와 像의 차이에 대해서는 아래 설명을 참조해 주세요."],"sourceUrl":"https://nihongokanji.com/846/"},"香":{"id":835,"char":"香","hun":"향기 향","meaning":"“향기 향”. 향기","on":"コウ、キョウ","kun":"か、かお(り)、かお(る)","explanation":["香 = 禾 + 日。","「禾」는 “곡식”을 뜻합니다.","「日」는 “태양”을 뜻합니다.","香는 “가을 햇빛(日) 아래 곡식(禾)이 익어가는 냄새” -> “향기”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/847/"},"更":{"id":836,"char":"更","hun":"고칠 경/다시 갱","meaning":"“고칠 경/다시 갱”. 고치다, 갱신하다","on":"コウ","kun":"さら、ふ(ける)、ふ(かす)","explanation":["更는 “회초리를 든 손 + 두 다리”를 그린 상형문자입니다.","“잘못을 저지른 아이를 회초리로 때리다” -> “바로잡다, 고치다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/848/"},"刻":{"id":837,"char":"刻","hun":"새길 각","meaning":"“새길 각”. 새기다, 썰다, 조각하다","on":"コク","kun":"きざ(む)","explanation":["刻 = 亥 + 刂。","「亥」는 “도축/가공된 돼지”를 뜻하는 글자입니다(링크 참조).","「刂」는 “칼”을 뜻합니다.","刻는 “돼지(亥)를 칼(刂)로 잘라 가공하다” -> “새기다, 썰다, 조각하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/849/"},"賛":{"id":838,"char":"賛","hun":"도울 찬","meaning":"“도울 찬”. 돕다, 칭찬하다","on":"サン","kun":"","explanation":["賛 = 夫 + 夫 + 貝。","「夫」는 “남편, 성인 남성”을 뜻합니다.","「貝」는 “돈, 재물”을 뜻합니다.","賛는 “가장들끼리(夫+夫) 서로 재정적(貝) 도움을 주고받다” -> “돕다, 칭찬하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/850/"},"抱":{"id":839,"char":"抱","hun":"안을 포","meaning":"“안을 포”. 안다, 품다","on":"ホウ","kun":"だ(く)、いだ(く)、かか(える)","explanation":["抱 = 扌 + 包。","(의미부) 「扌」는 “손”을 뜻합니다.","(소리부 겸 의미부) 「包」(ホウ)는 “감싸다”라는 뜻입니다.","抱는 “손(扌)으로 감싸안다(包)” -> “안다, 품다”라는 뜻의 글자입니다.","(包는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/851/"},"犯":{"id":840,"char":"犯","hun":"범할 범","meaning":"“범할 범”. 어기다, 범하다","on":"ハン","kun":"おか(す)","explanation":["犯 = 犭 + 㔾。","「犭」는 “개”를 뜻합니다.","「㔾」는 “무릎꿇은 사람”을 뜻합니다.","犯는 “개(犭)가 사람을 공격해 쓰러뜨리다(㔾)” -> “어기다, 범하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/852/"},"布":{"id":841,"char":"布","hun":"베/펼 포","meaning":"“베/펼 포”. 직물, 천, 베풀다, 퍼지다, 펴다","on":"フ","kun":"ぬの","explanation":["布 = 𠂇 + 巾。","「𠂇」는 “손”을 뜻합니다.","「巾」는 “수건, 천”을 뜻합니다.","布는 “삼베(巾)를 손으로(𠂇) 넓게 펴다” -> “직물, 천, 퍼지다, 펴다, 베풀다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/853/"},"恐":{"id":842,"char":"恐","hun":"두려울 공","meaning":"“두려울 공”. 두려워하다","on":"キョウ","kun":"おそ(れる)、おそ(ろしい)","explanation":["恐 = 工 + 凡 + 心。","「工」는 “공작, 가공, 공정”을 뜻합니다.","凡(“무릇 범”)은 “평범하다”라는 뜻의 상용한자입니다.","「心」는 “마음”을 뜻합니다.","恐는 “위험한 공사(工)에 강제로 동원된 평범한(凡) 인부들이 마음 속으로(心) 느끼는 공포” -> “두려워하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/854/"},"宇":{"id":843,"char":"宇","hun":"집 우","meaning":"“집 우”. 지붕, 집, 우주","on":"ウ","kun":"","explanation":["宇 = 宀 + 于。","「宀」는 “집”을 뜻합니다.","于는 여기서는 “지붕을 떠받치는 기둥”을 그린 모양자입니다.","宇는 “기둥(于) 위에 올려진 지붕(宀)” -> “지붕, 집, 우주”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/855/"},"戻":{"id":844,"char":"戻","hun":"어그러질 려","meaning":"“어그러질 려”. 돌려보내다","on":"レイ","kun":"もど(す)、もど(る)","explanation":["戻 = 戸 + 大。","「戸」는 “집, 출입구”를 뜻합니다.","「大」는 본래 “사람”을 그린 글자입니다.","戻는 “문(戸) 앞에서 거절당하고 돌아가는 사람(大)” -> “돌아가다, 돌려보내다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/856/"},"巨":{"id":845,"char":"巨","hun":"클 거","meaning":"“클 거”. 크다","on":"キョ","kun":"","explanation":["巨는 “거대한 자로 나무의 길이를 재는 사람”을 그린 상형문자입니다.","“나무의 길이를 잴 만큼 거대한 자” -> “크다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/857/"},"震":{"id":846,"char":"震","hun":"우레 진","meaning":"“우레 진”. 흔들리다, 떨리다, 지진","on":"シン","kun":"ふる(う)、ふる(える)","explanation":["震 = 雨 + 辰。","(의미부) 「雨」는 “비”를 뜻합니다.","(소리부 겸 의미부) 「辰」(シン)은 “쟁기, 농기구”를 뜻합니다.","震는 “농기구(辰)를 땅에 강하게 내리쳐 천둥이 치듯(雨) 땅이 울리다” -> “흔들리다, 떨리다, 지진”이라는 뜻의 글자입니다.","(辰는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/858/"},"越":{"id":847,"char":"越","hun":"넘을 월","meaning":"“넘을 월”. 넘다, 능가하다","on":"エツ","kun":"こ(す)、こ(える)","explanation":["越 = 走 + 戉。","「走」는 “달리다”라는 뜻입니다.","戉는 「戊」가 살짝 변형된 것으로, “창”을 뜻합니다.","越는 “창(戉)을 들고 담을 뛰어넘어(走) 돌격하다” -> “넘다, 능가하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/859/"},"欲":{"id":848,"char":"欲","hun":"하고자 할 욕","meaning":"“하고자 할 욕”. 탐내다, 욕심","on":"ヨク","kun":"ほっ(する)、ほ(しい)","explanation":["欲 = 谷 + 欠。","「谷」는 “계곡”을 뜻합니다.","「欠」는 “입을 벌린 사람”을 뜻합니다.","欲는 “계곡물(谷)을 전부 받아마시려는(欠) 사람”이라는 뜻입니다.","“터무니없는 욕심을 부리다” -> “탐내다, 욕심”이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/860/"},"痛":{"id":849,"char":"痛","hun":"아플 통","meaning":"“아플 통”. 아프다, 고통","on":"ツウ","kun":"いた(い)、いた(む)、いた(める)","explanation":["痛 = 疒 + 甬。","「疒」는 “질병, 질환”을 뜻합니다.","「甬」는 “종”을 뜻합니다.","痛는 “종소리(甬)가 울려퍼지듯 온몸에 고통(疒)이 울려퍼지다” -> “아프다, 고통”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/861/"},"触":{"id":850,"char":"触","hun":"닿을 촉","meaning":"“닿을 촉”. 닿다, 접하다","on":"ショク","kun":"ふ(れる)、さわ(る)","explanation":["触 = 角 + 虫。","「角」는 “뿔”을 뜻합니다.","「虫」는 “벌레”를 뜻합니다.","触는 “장수풍뎅이(虫)의 뿔(角)을 만져보다” -> “만지다, 닿다, 접하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/862/"},"依":{"id":851,"char":"依","hun":"의지할 의","meaning":"“의지할 의”. 의지하다, 의존하다","on":"イ、エ","kun":"","explanation":["依 = 亻 + 衣。","(의미부) 「亻」는 “사람”을 뜻합니다.","(소리부 겸 의미부) 「衣」(イ)는 “옷”을 뜻합니다.","依는 “사람(亻)은 옷(衣)에 의존해 추위를 막는다” -> “의지하다, 의존하다”라는 뜻의 글자입니다.","(衣는 소리부(イ -> イ・エ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/863/"},"汚":{"id":852,"char":"汚","hun":"더러울 오","meaning":"“더러울 오”. 더럽다","on":"オ","kun":"けが(す)、けが(れる)、けが(らわしい)、よご(す)、よご(れる)、きたな(い)","explanation":["汚 = 氵 + 亐。","「氵」는 “물”을 뜻합니다.","亐는 여기서는 “구부러진 물길”을 그린 모양자입니다.","汚는 “물길(氵)이 구부러져(亐) 흐름이 막히다” -> “물이 고여서 썩다” -> “더럽다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/864/"},"枚":{"id":853,"char":"枚","hun":"낱 매","meaning":"“낱 매”. 매수, 장수","on":"マイ","kun":"","explanation":["枚 = 木 + 攵。","「木」는 “나무”를 뜻합니다.","「攵」는 본래 “막대기를 든 손”을 그린 글자입니다(링크 참조).","枚는 “나무판자(木)를 한장한장 들어 넘기며(攵) 세다” -> “매수, 장수”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/865/"},"互":{"id":854,"char":"互","hun":"서로 호","meaning":"“서로 호”. 서로, 상호간의","on":"ゴ","kun":"たが(い)","explanation":["互는 “같은 것 두 개가 위아래로 얽힌 모습” -> “서로, 상호간의”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/866/"},"複":{"id":855,"char":"複","hun":"겹칠 복/부","meaning":"“겹칠 복/부”. 겹치다, 중복되다","on":"フク","kun":"","explanation":["複 = 衤 + 复。","(의미부) 「衤」는 “옷, 옷감”을 뜻합니다.","(소리부 겸 의미부) 「复」(フク)는 “되돌아가다”라는 뜻입니다.","複는 “옷감(衤)을 여러 번 다시(复) 겹쳐 덧대다” -> “겹치다, 중복되다”라는 뜻의 글자입니다.","(复는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/867/"},"郵":{"id":856,"char":"郵","hun":"우편 우","meaning":"“우편 우”. 우편","on":"ユウ","kun":"","explanation":["郵 = 垂 + ⻏。","垂(“드리울 수”)는 “드리우다, 매달리다”라는 뜻의 상용한자입니다.","「⻏」는 “도시”를 뜻합니다.","郵는 “편지 가방을 어깨에 늘어뜨리고(垂) 도시(⻏)를 달리는 배달부” -> “우편”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/868/"},"似":{"id":857,"char":"似","hun":"닮을 사","meaning":"“닮을 사”. 비슷하다, 닮다","on":"ジ","kun":"に(る)","explanation":["似 = 亻 + 以。","(의미부) 「亻」는 “사람”을 뜻합니다.","(소리부) 「以」(イ)는 여기서는 소리부(イ -> ジ)의 역할만 하고 있습니다.","似는 “서로 닮은 사람(亻)” -> “비슷하다, 닮다”라는 뜻의 글자입니다(以는 소리부)."],"sourceUrl":"https://nihongokanji.com/869/"},"恵":{"id":858,"char":"恵","hun":"은혜 혜","meaning":"“은혜 혜”. 은혜","on":"ケイ、エ","kun":"めぐ(む)","explanation":["恵 = 𤰔 + 心。","「𤰔」는 “실을 감는 방추”를 그린 글자입니다.","「心」는 “마음”을 뜻합니다.","恵는 “방추에 감긴 실을 풀듯(𤰔) 선한 마음을(心) 베풀다” -> “은혜”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/870/"},"探":{"id":859,"char":"探","hun":"찾을 탐","meaning":"“찾을 탐”. 찾다","on":"タン","kun":"さが(す)、さぐ(る)","explanation":["探 = 扌 + 罙。","「扌」는 “손”을 뜻합니다.","罙는 여기서는 「深」이 축약된 것으로, “깊다”라는 뜻입니다.","探는 “깊은 곳(深)까지 더듬어(扌) 찾아보다” -> “찾다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/871/"},"逃":{"id":860,"char":"逃","hun":"도망할 도","meaning":"“도망할 도”. 달아나다, 도망치다","on":"トウ","kun":"に(げる)、に(がす)、のが(す)、のが(れる)","explanation":["逃 = ⻌ + 兆。","「⻌」는 “길”을 뜻합니다.","「兆」는 “징조, 전조, 징후”를 뜻합니다.","逃는 “재앙의 전조(兆)를 느끼고 달아나다(⻌)” -> “도망치다, 달아나다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/872/"},"骨":{"id":861,"char":"骨","hun":"뼈 골","meaning":"“뼈 골”. 뼈","on":"コツ","kun":"ほね","explanation":["骨 = 冎 + 月。","「冎」는 “뼈”를 뜻합니다.","「月」는 “신체의 일부”를 뜻합니다.","骨는 “몸(月) 안의 뼈(冎)” -> “뼈”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/873/"},"傾":{"id":862,"char":"傾","hun":"기울 경","meaning":"“기울 경”. 기울다, 기울어지다","on":"ケイ","kun":"かたむ(く)、かたむ(ける)","explanation":["傾 = 亻 + 匕 + 頁。","「亻」는 “사람”을 뜻합니다.","「匕」는 “숟가락”을 뜻합니다.","「頁」는 “머리”를 뜻합니다.","음식을 떠먹을 때는 고개를 앞으로 숙이게 됩니다.","傾는 “사람(亻)이 음식을 먹느라(匕) 고개가(頁) 기울어지다” -> “기울다, 기울어지다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/874/"},"届":{"id":863,"char":"届","hun":"닿게 하다, 보내주다","meaning":"닿게 하다, 보내주다","on":"","kun":"とど(ける)、とど(く)","explanation":["届 = 尸 + 由。","「尸」는 “집, 지붕”을 뜻합니다.","「由」는 “유래, 이유”를 뜻합니다. 여기서는 “유래” -> “이르다, 닿다”라는 뜻으로 응용된 것입니다.","届는 “집(尸)에 보낸 편지가 도착하다(由)” -> “닿게 하다, 보내주다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/875/"},"迷":{"id":864,"char":"迷","hun":"미혹할 미","meaning":"“미혹할 미”. 헤메다, 헷갈리다, 미혹되다","on":"メイ","kun":"まよ(う)","explanation":["迷 = ⻌ + 米。","(의미부) 「⻌」는 “길”을 뜻합니다.","(소리부 겸 의미부) 「米」(ベイ・マイ)는 여기서는 “사방으로 뻗은 갈림길”을 그린 모양자로 쓰인 것입니다.","迷는 “여러 방향의(米) 갈림길(⻌) 가운데서 갈피를 잡지 못하고 헤메다” -> “헤메다, 헷갈리다”라는 뜻의 글자입니다.","(米는 소리부(ベイ・マイ -> メイ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/876/"},"夢":{"id":865,"char":"夢","hun":"꿈 몽","meaning":"“꿈 몽”. 꿈","on":"ム","kun":"ゆめ","explanation":["夢 = 艹 + 罒 + 冖 + 夕。","「艹」는 “풀”을 뜻합니다.","「罒」는 “그물”을 뜻합니다.","冖는 여기서는 「宀」가 축약된 것으로, “집”을 뜻합니다.","「夕」는 “저녁”을 뜻합니다.","夢는 “풀(艹)을 엮어(罒) 만든 초가집(冖)에서 밤(夕)에 자면서 꾸는 꿈” -> “꿈”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/877/"},"巻":{"id":866,"char":"巻","hun":"책/말 권","meaning":"“책/말 권”. 돌돌 말다, 감다, 두루마리, 책을 세는 단위(~권)","on":"カン","kun":"ま(く)、まき","explanation":["巻 = 龹 + 己。","(소리부 겸 의미부) 龹는 여기서는 「券」(ケン)이 축약된 것으로, “증서, 표”를 뜻합니다.","(의미부) 「己」는 본래 “구부러진 새끼줄”을 그린 글자입니다(링크 참조).","巻는 “증서(龹)를 새끼줄(己)로 돌돌 감아놓다” -> “감다, 돌돌 말다, 두루마리”라는 뜻의 글자입니다.","(龹->券은 소리부(ケン -> カン)도 겸함)"],"sourceUrl":"https://nihongokanji.com/878/"},"燃":{"id":867,"char":"燃","hun":"탈 연","meaning":"“탈 연”. 불태우다, 불타다","on":"ネン","kun":"も(える)、も(やす)、も(す)","explanation":["燃 = 火 + 然。","(소리부 겸 의미부) 「然」(ネン)은 본래 “개고기를 불에 굽는 모습”을 그린 글자입니다(링크 참조).","(의미부) 「火」는 “불”을 뜻합니다.","燃는 “너무 강한 불(火)로 개고기를 구워(然) 새까맣게 태우다” -> “불타다, 불태우다”라는 뜻의 글자입니다.","(然는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/879/"},"閉":{"id":868,"char":"閉","hun":"닫을 폐","meaning":"“닫을 폐”. 닫다","on":"ヘイ","kun":"と(じる)、と(ざす)、し(める)、し(まる)","explanation":["閉 = 門 + オ。","「門」는 “문”을 뜻합니다.","オ는 여기서는 “문에 걸어놓은 빗장”을 그린 모양자입니다.","閉는 “빗장(オ)이 걸린 문(門)” -> “닫다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/880/"},"緒":{"id":869,"char":"緒","hun":"실마리 서","meaning":"“실마리 서”. 실마리, 시작, 처음","on":"ショ、チョ","kun":"お","explanation":["緒 = 糸 + 者。","(의미부) 「糸」는 “실”을 뜻합니다.","(소리부 겸 의미부) 「者」(シャ)는 “사람”을 뜻합니다.","緒는 “뭉쳐있는 실타래(糸) 속에서 자신이 원하는 실 한 가닥을 찾아낸 사람(者)” -> “실마리, 시작, 처음”이라는 뜻의 글자입니다.","(者는 소리부(シャ -> ショ・チョ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/881/"},"駐":{"id":870,"char":"駐","hun":"머무를 주","meaning":"“머무를 주”. 머무르다","on":"チュウ","kun":"","explanation":["駐 = 馬 + 主。","(의미부) 「馬」는 “말”을 뜻합니다.","(소리부 겸 의미부) 「主」(シュ)는 “주인”을 뜻합니다.","駐는 “주인(主)이 말(馬)을 마굿간에 묶어두고 머무르다” -> “머무르다”라는 뜻의 글자입니다.","(主는 소리부(シュ -> チュウ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/882/"},"賃":{"id":871,"char":"賃","hun":"품삯 임","meaning":"“품삯 임”. 임금, 보수, 요금","on":"チン","kun":"","explanation":["賃 = 任 + 貝。","(소리부 겸 의미부) 「任」(ニン)은 “맡기다”라는 뜻입니다.","(의미부) 「貝」는 “돈, 재물”을 뜻합니다.","賃는 “맡긴(任) 일에 대한 보수(貝)” -> “임금, 보수, 요금”이라는 뜻의 글자입니다.","(任는 소리부(ニン -> チン)도 겸함)"],"sourceUrl":"https://nihongokanji.com/883/"},"紹":{"id":872,"char":"紹","hun":"이을 소","meaning":"“이을 소”. 소개하다","on":"ショウ","kun":"","explanation":["紹 = 糸 + 召。","(의미부) 「糸」는 “실”을 뜻합니다.","(소리부 겸 의미부) 召(ショウ – 부를 소)는 “부르다”라는 뜻의 상용한자입니다.","紹는 “두 사람을 불러서(召) 사이를 이어주다(糸)” -> “소개하다”라는 뜻의 글자입니다.","(召는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/884/"},"雇":{"id":873,"char":"雇","hun":"품 팔 고","meaning":"“품 팔 고”. 고용하다","on":"コ","kun":"やと(う)","explanation":["雇 = 戸 + 隹。","(소리부 겸 의미부) 「戸」(コ)는 “집, 출입구”를 뜻합니다.","(의미부) 「隹」는 “새”를 뜻합니다.","雇는 “문(戸) 안팎으로 들락날락하는 새(隹)”라는 뜻입니다.","직장에 출퇴근하는 직원을 “들락날락하는 새”로 비유한 것입니다.","“매일 출퇴근하는 고용인” -> “고용하다”라는 의미입니다.","(戸는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/885/"},"暮":{"id":874,"char":"暮","hun":"저물 모","meaning":"“저물 모”. 저녁, 황혼, 세월을 보내다","on":"ボ","kun":"く(れる)、く(らす)","explanation":["暮 = 莫 + 日。","(소리부 겸 의미부) 「莫」(ボ)는 “없다”라는 뜻의 글자로, “해가 저무는 모습”을 그린 글자입니다(링크 참조).","(의미부) 「日」는 “해”를 뜻합니다.","暮는 “해(日)가 저물다(莫)” -> “저물다, 황혼”이라는 뜻의 글자입니다.","(莫는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/886/"},"替":{"id":875,"char":"替","hun":"바꿀 체","meaning":"“바꿀 체”. 교체하다, 바꾸다","on":"タイ","kun":"か(える)、か(わる)","explanation":["替 = 夫 + 夫 + 日。","「夫」는 “남편, 성인 남성”을 뜻합니다.","「日」는 “날짜”를 뜻합니다.","替는 “두 사람(夫+夫)이 약속날(日) 만나서 물건을 교환하다” -> “교체하다, 바꾸다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/887/"},"預":{"id":876,"char":"預","hun":"맡길 예","meaning":"“맡길 예”. 맡기다","on":"ヨ","kun":"あず(ける)、あず(かる)","explanation":["預 = 予 + 頁。","(소리부 겸 의미부) 「予」(ヨ)는 “미리, 사전에”라는 뜻입니다.","(의미부) 「頁」는 “머리”를 뜻합니다.","預는 “앞날(予)을 생각해(頁) 돈을 은행에 맡겨두다” -> “맡기다”라는 뜻의 글자입니다.","(予는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/888/"},"簡":{"id":877,"char":"簡","hun":"대쪽 간","meaning":"“대쪽 간”. 간략하다","on":"カン","kun":"","explanation":["簡 = 𥫗 + 間。","(의미부) 「𥫗」는 “대나무 죽간”을 뜻합니다.","(소리부 겸 의미부) 「間」(カン)은 “사이, 틈새”라는 뜻입니다.","簡는 “대나무 죽간(𥫗) 틈새(間)에 간략하게 써놓은 메모” -> “간략하다”라는 뜻의 글자입니다.","(間는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/889/"},"臓":{"id":878,"char":"臓","hun":"오장 장","meaning":"“오장 장”. 내장","on":"ゾウ","kun":"","explanation":["臓 = 月 + 蔵。","(의미부) 「月」는 “신체의 일부”를 뜻합니다.","(소리부 겸 의미부) 「蔵」(ゾウ)는 “창고”를 뜻합니다.","臓는 “여러 가지 기능이 저장된(蔵) 신체 기관(月)” -> “내장, 오장”이라는 뜻의 글자입니다.","(蔵는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/890/"},"律":{"id":879,"char":"律","hun":"법칙 률","meaning":"“법칙 률”. 음률, 법률, 계율, 주기율 등","on":"リツ、リチ","kun":"","explanation":["律 = 彳 + 聿。","「彳」는 “길”을 뜻합니다.","「聿」는 “붓을 든 손”을 뜻합니다.","律는 “법령을 만들어(聿) 널리(彳) 반포하다” -> “법률, 음률, 계율, 법칙”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/891/"},"贈":{"id":880,"char":"贈","hun":"줄 증","meaning":"“줄 증”. 증여하다","on":"ゾウ、ソウ","kun":"おく(る)","explanation":["贈 = 貝 + 曽。","(의미부) 「貝」는 “돈, 재물”을 뜻합니다.","(소리부 겸 의미부) 「曽」(ソウ)는 “쌓이다”라는 뜻입니다.","贈는 “재물(貝)을 더해주다(曽)” -> “증여하다”라는 뜻의 글자입니다.","(曽는 소리부(ソウ -> ゾウ・ソウ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/892/"},"宙":{"id":881,"char":"宙","hun":"집 주","meaning":"“집 주”. 허공, 하늘, 우주","on":"チュウ","kun":"","explanation":["宙 = 宀 + 由。","(의미부) 「宀」는 본래 “집의 지붕”을 그린 글자입니다.","(소리부) 「由」(ユウ)는 여기서는 소리부(ユウ -> チュウ)의 역할만 하고 있습니다.","宙는 “하늘 위의 지붕(宀)” -> “허공, 하늘, 우주”라는 뜻의 글자입니다(由는 소리부)."],"sourceUrl":"https://nihongokanji.com/893/"},"薄":{"id":882,"char":"薄","hun":"엷을 박","meaning":"“엷을 박”. 엷다, 얇다","on":"ハク","kun":"うす(い)、うす(める)、うす(まる)、うす(らぐ)、うす(れる)","explanation":["薄 = 艹 + 氵 + 尃。","(의미부) 「艹」는 “풀”을 뜻합니다.","(의미부) 「氵」는 “물”을 뜻합니다.","(소리부 겸 의미부) 「尃」(ハク)는 “넓게 퍼지다”라는 뜻의 글자입니다(링크 참조).","薄는 “물가(氵)에 넓고 얇게 퍼져(尃) 자라난 이끼(艹)” -> “엷다, 얇다”라는 뜻의 글자입니다.","(尃는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/894/"},"群":{"id":883,"char":"群","hun":"무리 군","meaning":"“무리 군”. 무리, 떼","on":"グン","kun":"む(れる)、む(れ)、むら","explanation":["群 = 君 + 羊。","(의미부) 「羊」는 “양”을 뜻합니다.","(소리부 겸 의미부) 「君」(クン)은 “군주”를 뜻합니다.","群는 “주인(君) 옆으로 모여든 양떼(羊)” -> “무리, 떼”라는 뜻의 글자입니다.","(君는 소리부(クン -> グン)도 겸함)"],"sourceUrl":"https://nihongokanji.com/895/"},"操":{"id":884,"char":"操","hun":"잡을 조","meaning":"“잡을 조”. 잡다, 조종하다, 지조, 절개","on":"ソウ","kun":"みさお、あやつ(る)","explanation":["操 = 扌 + 品 + 木。","「扌」는 “손”을 뜻합니다.","「木」는 “나무”를 뜻합니다.","品는 여기서는 「口」세 개가 합쳐진 것으로, “지저귀는(口) 새들”을 표현한 것입니다.","操는 “나무(木) 위의 새(品)를 손(扌)으로 잡다”라는 뜻입니다.","“새를 잡다” -> “잡다” -> “조종하다”","“새가 날아가지 않도록 조심조심 접근하다” -> “조심하다” -> “지조, 절개”","라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/896/"},"奥":{"id":885,"char":"奥","hun":"깊을 오","meaning":"“깊을 오”. 깊은, 심오한, 안쪽","on":"オウ","kun":"おく","explanation":["奥 = 宀 + 米 + 大。","「宀」는 “집”을 뜻합니다.","「米」는 “쌀”을 뜻합니다.","「大」는 “사람”을 그린 글자입니다.","奥는 “집(宀) 안쪽 깊숙이 쌀(米)을 숨겨두고 지키는 사람(大)” -> “깊은, 안쪽”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/897/"},"詰":{"id":886,"char":"詰","hun":"물을/꾸짖을 힐","meaning":"“물을/꾸짖을 힐”. 문책하다, 힐난하다","on":"キツ","kun":"つ(める)、つ(まる)、つ(む)","explanation":["詰 = 言 + 士 + 口。","「言」는 “말하다”라는 뜻입니다.","士(“선비 사”)는 “선비, 무사”를 뜻하는 상용한자입니다.","「口」는 “입”을 뜻합니다.","詰는 “선비(士)가 아랫사람을 큰 소리로(口) 꾸짖다(言)” -> “문책하다, 힐난하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/898/"},"双":{"id":887,"char":"双","hun":"두 쌍","meaning":"“두 쌍”. 쌍, 짝","on":"ソウ","kun":"ふた","explanation":["双 = 又 + 又。","「又」는 “손”을 뜻합니다.","双는 “손 한 쌍(又+又)” -> “쌍, 짝”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/899/"},"刺":{"id":888,"char":"刺","hun":"찌를 자","meaning":"“찌를 자”. 찌르다","on":"シ","kun":"さ(す)、さ(さる)","explanation":["刺 = 朿 + 刂。","「朿」는 “삼지창”을 그린 글자입니다(링크 참조).","「刂」는 “칼”을 뜻합니다.","刺는 “삼지창(朿)과 칼(刂)로 찌르다” -> “찌르다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/900/"},"到":{"id":889,"char":"到","hun":"이를 도","meaning":"“이를 도”. 도착하다, 도달하다","on":"トウ","kun":"","explanation":["到 = 至 + 刂。","至(“이를 지”)는 “화살이 과녁에 날아가 박힌 모습”을 그린 상용한자입니다.","刂는 여기서는 “길”을 그린 모양자로 쓰인 것입니다.","到는 “길(刂)을 달려 목적지에 도달하다(至)” -> “도착하다, 도달하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/901/"},"寝":{"id":890,"char":"寝","hun":"잠잘 침","meaning":"“잠잘 침”. 잠자리에 들다, 눕다","on":"シン","kun":"ね(る)、ね(かす)","explanation":["寝 = 宀 + 丬 + 𠬶。","「宀」는 “집”을 뜻합니다.","「丬」는 “탁자”를 뜻합니다. 여기서는 “침상”이라는 뜻으로 쓰인 것입니다.","𠬶는 “빗자루(「帚」)를 든 손(「又」)“을 뜻합니다.","寝는 “집(宀)에서 잠들기 전에 침상(丬)을 정돈하다(𠬶)” -> “잠자리에 들다, 눕다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/902/"},"壁":{"id":891,"char":"壁","hun":"벽 벽","meaning":"“벽 벽”. 벽","on":"ヘキ","kun":"かべ","explanation":["壁 = 辟 + 土。","(소리부 겸 의미부) 「辟」(ヘキ)는 “피하다, 숨다”라는 뜻의 글자입니다(링크 참조).","(의미부) 「土」는 “흙”을 뜻합니다","壁는 “흙벽(土) 뒤로 도망쳐 숨다(辟)” -> “벽”이라는 뜻의 글자입니다.","(辟는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/903/"},"仮":{"id":892,"char":"仮","hun":"거짓 가","meaning":"“거짓 가”. 가짜, 거짓","on":"カ、ケ","kun":"かり","explanation":["仮 = 亻 + 反。","「亻」는 “사람”을 뜻합니다.","「反」는 “뒤집다, 반대”라는 뜻입니다.","仮는 “사실과 반대의(反) 말만 하는 사람(亻)” -> “거짓말쟁이” -> “거짓, 가짜”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/904/"},"純":{"id":893,"char":"純","hun":"순수할 순","meaning":"“순수할 순”. 순수한, 진실한, 있는 그대로의","on":"ジュン","kun":"","explanation":["純 = 糸 + 屯。","「糸」는 “실”을 뜻합니다.","「屯」는 “뿌리깊은 나무”를 그린 글자입니다(링크 참조).","純는,","“누에고치에서 방금 뽑아낸 순수한 명주실(糸)” -> “순수한, 있는 그대로의”","“뿌리깊은 나무(屯)” -> “진실된”","이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/905/"},"盗":{"id":894,"char":"盗","hun":"훔칠 도","meaning":"“훔칠 도”. 훔치다, 도둑","on":"トウ","kun":"ぬす(む)","explanation":["盗 = 冫 + 欠 + 皿。","「欠」는 “입을 벌린 사람”을 뜻합니다.","冫는 여기서는 “침방울”을 그린 모양자입니다.","「皿」는 “접시”를 뜻합니다.","盗는 “남의 접시(皿) 위의 음식을 보며 군침(冫)을 흘리는(欠) 사람”이라는 뜻입니다.","“남의 음식을 탐내서 훔쳐먹다” -> “훔치다, 도둑”이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/906/"},"吸":{"id":895,"char":"吸","hun":"마실 흡","meaning":"“마실 흡”. (숨을) 들이쉬다","on":"キュウ","kun":"す(う)","explanation":["吸 = 口 + 及。","(의미부) 「口」는 “입”을 뜻합니다.","(소리부 겸 의미부) 及(キュウ – “미칠 급”)은 “이르다, 미치다”라는 뜻의 상용한자입니다.","吸는 “공기가 폐에 닿도록(及) 숨을 들이마시다(口)” -> “숨을 들이쉬다”라는 뜻의 글자입니다.","(及는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/907/"},"看":{"id":896,"char":"看","hun":"볼 간","meaning":"“볼 간”. 살펴보다, 보살피다","on":"カン","kun":"","explanation":["看 = 手 + 目。","「手」는 “손”을 뜻합니다.","「目」는 “눈”을 뜻합니다.","看는 “자세히 살펴보며(目) 돌보다(手)” -> “살펴보다, 보살피다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/908/"},"翌":{"id":897,"char":"翌","hun":"다음날 익","meaning":"“다음날 익”. 이튿날, 다음","on":"ヨク","kun":"","explanation":["翌 = 羽 + 立。","「羽」는 “날개”를 뜻합니다.","「立」는 “서다”라는 뜻입니다.","翌는 “새가 자리에서 일어선(立) 다음에 날아가다(羽)” -> “이튿날, 다음”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/909/"},"快":{"id":898,"char":"快","hun":"쾌할 쾌","meaning":"“쾌할 쾌”. 상쾌한, 재미있는, 빠른","on":"カイ","kun":"こころよ(い)","explanation":["快 = 忄 + 夬。","「忄」는 “마음”을 뜻합니다.","夬는 여기서는 “활(𠃍)을 쏘는 사람(大)”을 그린 모양자입니다(296.「決」 참조).","快는 “활을 쏘며(夬) 사냥을 즐기는 상쾌한 마음(忄)” -> “상쾌하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/910/"},"片":{"id":899,"char":"片","hun":"조각 편","meaning":"“조각 편”. 조각, 파편","on":"ヘン","kun":"かた","explanation":["片는 “나무판자를 이어붙인 모습”을 그린 상형문자입니다.","“판자 조각” -> “조각, 파편”이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/911/"},"敬":{"id":900,"char":"敬","hun":"공경 경","meaning":"“공경 경”. 공경하다, 존중하다","on":"ケイ","kun":"うやま(う)","explanation":["敬 = 苟 + 攵。","苟는 여기서는 “귀(艹)를 쫑긋 세운 개(句)”의 모습을 그린 모양자입니다.","「攵」는 “때리다, 치다”라는 뜻입니다.","敬는 “개(苟)를 때려서(攵) 예절을 갖추도록 훈육하다” -> “공경하다, 존경하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/912/"},"悩":{"id":901,"char":"悩","hun":"번뇌할 뇌","meaning":"“번뇌할 뇌”. 고민하다","on":"ノウ","kun":"なや(む)、なや(ます)","explanation":["悩 = 忄 + ⺍ + 凶。","(의미부) 「忄」는 “마음”을 뜻합니다.","(소리부 겸 의미부) ⺍+凶는 여기서는 「脳」(ノウ)가 축약된 것으로, “뇌”를 뜻합니다.","悩는 “머릿속(脳)의 고민으로 마음(忄)이 괴롭다” -> “고민하다, 괴로워하다”라는 뜻의 글자입니다.","(脳는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/913/"},"泉":{"id":902,"char":"泉","hun":"샘 천","meaning":"“샘 천”. 샘, 샘물","on":"セン","kun":"いずみ","explanation":["泉 = 白 + 水。","「白」는 “흰색”을 뜻합니다.","「水」는 “물”을 뜻합니다.","泉는 “맑은(白) 물(水)” -> “샘, 샘물”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/914/"},"御":{"id":903,"char":"御","hun":"거느릴 어","meaning":"“거느릴 어”. 통치하다, 거느리다, 막다","on":"ギョ、ゴ","kun":"おん","explanation":["御 = 彳 + 午 + 止 + 卩。","(의미부) 「彳」는 “길”을 뜻합니다.","(소리부) 「午」(ゴ)는 여기서는 소리부(ゴ -> ギョ・ゴ)의 역할만 하고 있습니다.","(의미부) 「止」는 “발”을 뜻합니다.","(의미부) 「卩」는 “무릎꿇은 사람”을 뜻합니다.","御는 “길(彳)에서 왕의 발밑(止)에 꿇어 엎드린(卩) 백성들” -> “거느리다, 통치하다”라는 뜻의 글자입니다(午는 소리부)."],"sourceUrl":"https://nihongokanji.com/915/"},"荒":{"id":904,"char":"荒","hun":"거칠 황","meaning":"“거칠 황”. 거친, 황폐한","on":"コウ","kun":"あら(い)、あ(れる)、あ(らす)","explanation":["荒 = 艹 + 亡 + 川。","「艹」는 “풀”을 뜻합니다.","「川」는 “강, 하천”을 뜻합니다.","「亡」는 “망하다”라는 뜻입니다.","荒는 “풀(艹) 한 포기도 물(川) 한 모금도 없는 버려진(亡) 땅” -> “거친, 황폐한”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/916/"},"硬":{"id":905,"char":"硬","hun":"굳을 경","meaning":"“굳을 경”. 딱딱한, 단단한","on":"コウ","kun":"かた(い)","explanation":["硬 = 石 + 更。","(의미부) 「石」는 “돌”을 뜻합니다.","(소리부 겸 의미부) 「更」(コウ)는 본래 “회초리로 때리는 모습”을 그린 글자입니다(링크 참조).","硬는 “돌(石)을 두드리다(更)” -> “딱딱한, 단단한”이라는 뜻의 글자입니다.","(更는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/917/"},"埋":{"id":906,"char":"埋","hun":"묻을 매","meaning":"“묻을 매”. 묻다, 묻히다","on":"マイ","kun":"う(める)、う(まる)、う(もれる)","explanation":["埋 = 土 + 里。","「土」는 “흙”을 뜻합니다.","「里」는 “마을”을 뜻합니다.","埋는 “마을(里) 앞의 공동묘지(土)” -> “묻다, 묻히다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/918/"},"袋":{"id":907,"char":"袋","hun":"자루 대","meaning":"“자루 대”. 자루, 주머니","on":"タイ","kun":"ふくろ","explanation":["袋 = 代 + 衣。","(소리부) 「代」(タイ)는 여기서는 소리부의 역할만 하고 있습니다.","(의미부) 「衣」는 “옷”을 뜻합니다.","袋는 “옷(衣) 안의 주머니” -> “주머니, 자루”라는 뜻의 글자입니다(代는 소리부)."],"sourceUrl":"https://nihongokanji.com/919/"},"忘":{"id":908,"char":"忘","hun":"잊을 망","meaning":"“잊을 망”. 잊다","on":"ボウ","kun":"わす(れる)","explanation":["忘 = 亡 + 心。","(소리부 겸 의미부) 「亡」(ボウ)는 “망하다, 죽다”라는 뜻입니다.","(의미부) 「心」는 “마음”을 뜻합니다.","忘는 “마음(心)에서 사라지다(亡)” -> “잊다”라는 뜻의 글자입니다.","(亡는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/920/"},"吹":{"id":909,"char":"吹","hun":"불 취","meaning":"“불 취”. 불다","on":"スイ","kun":"ふ(く)","explanation":["吹 = 口 + 欠。","「口」는 “입”을 뜻합니다.","「欠」는 “입을 벌린 사람, 입으로 하는 동작”을 뜻합니다.","吹는 “입(口)을 벌리고(欠) 입김을 불다” -> “불다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/921/"},"宝":{"id":910,"char":"宝","hun":"보배 보","meaning":"“보배 보”. 보물","on":"ホウ","kun":"たから","explanation":["宝 = 宀 + 玉。","「宀」는 “집”을 뜻합니다.","「玉」는 “구슬, 보석”을 뜻합니다.","宝는 “집(宀)에 있는 값비싼 보석(玉)” -> “보물”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/922/"},"封":{"id":911,"char":"封","hun":"봉할 봉","meaning":"“봉할 봉”. 봉하다, 닫다","on":"フウ、ホウ","kun":"","explanation":["封 = 圭 + 寸。","圭는 “흙더미(土+土)”라는 뜻입니다.","「寸」는 “손”을 뜻합니다.","封는 “흙더미(圭) 속에 묻어두다(寸)” -> “봉하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/923/"},"胸":{"id":912,"char":"胸","hun":"가슴 흉","meaning":"“가슴 흉”. 가슴","on":"キョウ","kun":"むね、むな","explanation":["胸 = 月 + 匈。","(의미부) 「月」는 “신체의 일부”를 뜻합니다.","(의미부) 勹는 여기서는 “(안쪽을) 품은 모습”을 그린 모양자입니다.","(소리부 겸 의미부) 凶(キョウ – “흉할 흉”)은 “흉하다, 간악하다”라는 뜻의 상용한자입니다.","胸는 “신체의 일부(月) + 흉한 생각(凶)을 품은(勹) 곳” -> “가슴”이라는 뜻의 글자입니다.","(凶는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/924/"},"娘":{"id":913,"char":"娘","hun":"계집 낭","meaning":"“계집 낭”. 처녀, 소녀, 딸","on":"","kun":"むすめ","explanation":["娘 = 女 + 良。","「女」는 “여자”를 뜻합니다.","「良」는 “좋다”라는 뜻입니다.","娘는 “착한(良) 딸아이(女)” -> “처녀, 소녀, 딸”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/925/"},"砂":{"id":914,"char":"砂","hun":"모래 사","meaning":"“모래 사”. 모래","on":"サ、シャ","kun":"すな","explanation":["砂 = 石 + 少。","「石」는 “돌”을 뜻합니다.","「少」는 “적다”라는 뜻입니다.","砂는 “돌(石)이 잘게(少) 갈린 것” -> “모래”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/926/"},"誤":{"id":915,"char":"誤","hun":"그르칠 오","meaning":"“그르칠 오”. 틀리다, 실수하다","on":"ゴ","kun":"あやま(る)","explanation":["誤 = 言 + 呉。","(소리부 겸 의미부) 「呉」(ゴ)는 “머리가 옆으로 기울어진 사람”을 그린 글자입니다(링크 참조).","(의미부) 「言」는 “말”을 뜻합니다.","誤는 “틀린 말(言)에 고개를 갸우뚱하다(呉)” -> “틀리다, 실수하다”라는 뜻의 글자입니다.","(呉는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/927/"},"賢":{"id":916,"char":"賢","hun":"어질 현","meaning":"“어질 현”. 현명하다","on":"ケン","kun":"かしこ(い)","explanation":["賢 = 臣 + 又 + 貝。","「臣」는 “신하”를 뜻합니다.","「又」는 “손”을 뜻합니다.","「貝」는 “돈, 재물”을 뜻합니다.","賢는 “빈민들에게 재물(貝)을 나누어주는(又) 신하(臣)” -> “어질다, 현명하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/928/"},"腕":{"id":917,"char":"腕","hun":"팔뚝 완","meaning":"“팔뚝 완”. 팔, 능력, 실력","on":"ワン","kun":"うで","explanation":["腕 = 月 + 宛。","「月」는 “신체의 일부”를 뜻합니다.","宛는 여기서는 “사람의 목~어깨(宀)와 양팔(夕+㔾)”을 그린 모양자입니다.","腕는 “신체의 일부(月) + 양팔(宛)” -> “팔뚝, 팔, 실력”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/929/"},"較":{"id":918,"char":"較","hun":"견줄 교","meaning":"“견줄 교”. 비교하다","on":"カク","kun":"","explanation":["較 = 車 + 交。","「車」는 “수레, 차”를 뜻합니다.","「交」는 “엇갈리다, 교차하다”라는 뜻입니다.","較는 “엇갈려 지나가는(交) 두 수레(車)의 속도를 비교하다” -> “비교하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/930/"},"床":{"id":919,"char":"床","hun":"평상 상","meaning":"“평상 상”. 평상(침상, 걸상, 병상 등)","on":"ショウ","kun":"とこ、ゆか","explanation":["床 = 广 + 木。","「广」는 “집, 건물”을 뜻합니다.","「木」는 “나무”를 뜻합니다.","床는 “집(广)의 나무바닥(木)” -> “평상, 상”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/931/"},"慣":{"id":920,"char":"慣","hun":"익숙할 관","meaning":"“익숙할 관”. 익숙해지다, 습관","on":"カン","kun":"な(れる)、な(らす)","explanation":["慣 = 忄 + 貫。","(의미부) 「忄」는 “마음”을 뜻합니다.","(소리부 겸 의미부) 貫(カン – “꿸 관”)은 “꿰다, 관통하다”라는 뜻의 상용한자입니다.","慣는 “마음(忄)에 깊이 박힌(貫) 습관” -> “습관, 익숙해지다”라는 뜻의 글자입니다.","(貫는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/932/"},"尊":{"id":921,"char":"尊","hun":"높을 존","meaning":"“높을 존”. 존경하다, 소중하다","on":"ソン","kun":"たっと(い)、とうと(い)、たっと(ぶ)、とうと(ぶ)","explanation":["尊 = 丷 + 酉 + 寸。","「酉」는 “술병, 술”을 뜻합니다.","丷는 여기서는 “따뜻한 술에서 올라오는 김”을 그린 모양자입니다.","「寸」는 “손”을 뜻합니다.","尊는 “윗사람에게 따뜻한 술(丷+酉)을 따라 올리다(寸)” -> “존경하다, 소중하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/933/"},"窓":{"id":922,"char":"窓","hun":"창 창","meaning":"“창 창”. 창문","on":"ソウ","kun":"まど","explanation":["窓 = 穴 + 厶 + 心。","「穴」는 “구멍”을 뜻합니다.","「厶」는 “사사로운, 개인적인”이라는 뜻입니다.","「心」는 “마음”을 뜻합니다.","窓는 “사적인(厶) 마음(心)이 엿보이는 구멍(穴)” -> “마음의 창” -> “창문”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/934/"},"柔":{"id":923,"char":"柔","hun":"부드러울 유","meaning":"“부드러울 유”. 부드러운, 유순한","on":"ジュウ、ニュウ","kun":"やわ(らか)、やわ(らかい)","explanation":["柔 = 矛 + 木。","矛는 여기서는 “(나무에 돋아난) 새순”을 그린 모양자입니다.","「木」는 “나무”를 뜻합니다.","柔는 “나무(木)에 돋아난 새순(矛)” -> “부드러운, 유순한”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/935/"},"殿":{"id":924,"char":"殿","hun":"전각 전","meaning":"“전각 전”. 전각, 궁전","on":"デン、テン","kun":"との、どの","explanation":["殿 = 尸 + 共 + 殳。","「尸」는 “앉아있는 사람”을 뜻합니다.","「共」는 본래 “쟁반을 두 손으로 받쳐든 모습”을 그린 글자입니다(링크 참조).","「殳」는 “때리다, 휘두르다”라는 뜻입니다.","殿는 “자리에 앉아(尸) 시중을 받으며(共) 채찍을 휘두르는(殳) 귀족” -> “전각, 궁전”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/936/"},"濃":{"id":925,"char":"濃","hun":"짙을 농","meaning":"“짙을 농”. 짙다, 진하다","on":"ノウ","kun":"こ(い)","explanation":["濃 = 氵 + 農。","(의미부) 「氵」는 “물”을 뜻합니다.","(소리부 겸 의미부) 「農」(ノウ)는 “농사”를 뜻합니다.","濃는 “논(農)의 흙탕물(氵)” -> “진하다, 짙다”라는 뜻의 글자입니다.","(農는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/937/"},"液":{"id":926,"char":"液","hun":"진 액","meaning":"“진 액”. 액체","on":"エキ","kun":"","explanation":["液 = 氵 + 夜。","「氵」는 “물”을 뜻합니다.","「夜」는 “밤”을 뜻합니다.","液는 “밤늦게까지(夜) 일하며 흘리는 땀(氵)” -> “액체”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/938/"},"貧":{"id":927,"char":"貧","hun":"가난할 빈","meaning":"“가난할 빈”. 가난하다, 부족하다","on":"ヒン、ビン","kun":"まず(しい)","explanation":["貧 = 分 + 貝。","「分」는 “나누다”라는 뜻입니다.","「貝」는 “돈, 재물”을 뜻합니다.","貧는 “재물(貝)이 쪼개지다(分)” -> “돈이 없다” -> “가난하다, 부족하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/939/"},"肩":{"id":928,"char":"肩","hun":"어깨 견","meaning":"“어깨 견”. 어깨","on":"ケン","kun":"かた","explanation":["肩 = 戸 + 月。","戸는 여기서는 “사람의 어깨”를 그린 모양자입니다.","「月」는 “신체의 일부”를 뜻합니다.","肩는 “신체의 일부(月) + 어깨(戸)” -> “어깨”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/940/"},"零":{"id":929,"char":"零","hun":"떨어질/영 영","meaning":"“떨어질/영 영”. 극히 작다, 0","on":"レイ","kun":"","explanation":["零 = 雨 + 令。","(의미부) 「雨」는 “비”를 뜻합니다.","(소리부) 「令」(レイ)는 여기서는 소리부의 역할만 하고 있습니다.","零는 “작은 빗방울(雨)” -> “아주 작다, 0″이라는 뜻의 글자입니다(令는 소리부)."],"sourceUrl":"https://nihongokanji.com/941/"},"怒":{"id":930,"char":"怒","hun":"성낼 노","meaning":"“성낼 노”. 화내다, 분노하다","on":"ド","kun":"いか(る)、おこ(る)","explanation":["怒 = 奴 + 心。","(소리부 겸 의미부) 奴(ド – “종 노”)는 “노예, 종”을 뜻하는 상용한자입니다.","(의미부) 「心」는 “마음”을 뜻합니다.","怒는 “노예(奴)의 억울한 마음(心)” -> “화내다, 분노하다”라는 뜻의 글자입니다.","(奴는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/942/"},"祖":{"id":931,"char":"祖","hun":"할아버지 조","meaning":"“할아버지 조”. 조상, 시조","on":"ソ","kun":"","explanation":["祖 = 礻 + 且。","(의미부) 「礻」는 “종교, 신”을 뜻합니다.","(소리부 겸 의미부) 「且」(ソ)는 “비석, 조상, 장례”를 뜻합니다.","祖는 “조상님(且)의 신령(礻)” -> “조상, 시조, 선조”라는 뜻의 글자입니다.","(且는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/943/"},"幼":{"id":932,"char":"幼","hun":"어릴 유","meaning":"“어릴 유”. 어리다, 미숙하다","on":"ヨウ","kun":"おさな(い)","explanation":["幼 = 幺 + 力。","「幺」는 “짧은 실, 작다, 어리다”라는 뜻입니다.","「力」는 “힘”을 뜻합니다.","幼는 “힘(力)이 약한 어린아이(幺)” -> “어린, 미숙한”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/944/"},"泊":{"id":933,"char":"泊","hun":"머무를 박","meaning":"“머무를 박”. 머무르다, 숙박하다","on":"ハク","kun":"と(まる)、と(める)","explanation":["泊 = 氵 + 白。","(의미부) 「氵」는 “물”을 뜻합니다.","(소리부 겸 의미부) 「白」(ハク)는 여기서는 “조각배”를 그린 모양자로 쓰인 것입니다.","泊는 “물가(氵)에 정박한 배(白)” -> “머무르다, 숙박하다”라는 뜻의 글자입니다.","(白는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/945/"},"杯":{"id":934,"char":"杯","hun":"잔 배","meaning":"“잔 배”. 술잔, 세는 단위(수저/잔 등)","on":"ハイ","kun":"さかずき","explanation":["杯 = 木 + 不。","「木」는 “나무”를 뜻합니다.","不는 여기서는 “술잔”을 그린 모양자입니다.","杯는 “나무(木)로 만든 술잔(不)” -> “술잔, 잔”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/946/"},"甘":{"id":935,"char":"甘","hun":"달 감","meaning":"“달 감”. 달콤하다, 만족하다","on":"カン","kun":"あま(い)、あま(える)、あま(やかす)","explanation":["甘는 “입에 음식을 넣은 모습”을 그린 상형문자입니다.","“달콤한 음식” -> “달다, 만족하다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/947/"},"掃":{"id":936,"char":"掃","hun":"쓸 소","meaning":"“쓸 소”. 쓸다, 제거하다","on":"ソウ","kun":"は(く)","explanation":["掃 = 扌 + 帚。","「扌」는 “손”을 뜻합니다.","「帚」는 “빗자루”를 뜻합니다.","掃는 “빗자루(帚)를 들고(扌) 청소하다” -> “쓸다, 제거하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/948/"},"掘":{"id":937,"char":"掘","hun":"팔 굴","meaning":"“팔 굴”. 파다, 파내다","on":"クツ","kun":"ほ(る)","explanation":["掘 = 扌 + 屈。","(의미부) 「扌」는 “손”을 뜻합니다.","(소리부 겸 의미부) 屈(クツ – “굽힐 굴”)은 “굽히다, 움츠리다”라는 뜻의 상용한자입니다.","掘는 “허리를 굽히고(屈) 땅을 파다(扌)” -> “파다, 파내다”라는 뜻의 글자입니다.","(屈는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/949/"},"疲":{"id":938,"char":"疲","hun":"피곤할 피","meaning":"“피곤할 피”. 피로하다, 피곤하다","on":"ヒ","kun":"つか(れる)","explanation":["疲 = 疒 + 皮。","(의미부) 「疒」는 “질병, 질환”을 뜻합니다.","(소리부 겸 의미부) 「皮」(ヒ)는 “가죽, 표면”을 뜻합니다.","疲는 “피부(皮)가 일어날 정도로 피로하다(疒)” -> “피곤하다, 피로하다”라는 뜻의 글자입니다.","(皮는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/950/"},"捨":{"id":939,"char":"捨","hun":"버릴 사","meaning":"“버릴 사”. 버리다","on":"シャ","kun":"す(てる)","explanation":["捨 = 扌 + 舎。","(의미부) 「扌」는 “손”을 뜻합니다.","(소리부 겸 의미부) 舎(シャ – “집 사”)는 “숙소, 집, 저택”을 뜻하는 상용한자입니다.","捨는 “집(舎)을 버리고(扌) 뛰쳐나오다” -> “버리다”라는 뜻의 글자입니다.","(舎는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/951/"},"皆":{"id":940,"char":"皆","hun":"다 개","meaning":"“다 개”. 모두, 전부","on":"カイ","kun":"みな","explanation":["皆 = 比 + 白。","「比」는 본래 “나란히 서 있는 사람들”을 그린 글자입니다(링크 참조).","白는 여기서는 「曰」이 잘못 변형되어 굳어진 것으로, “말하다”라는 뜻입니다.","皆는 “여러 사람(比)이 함께 말하다(曰)” -> “모두, 다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/952/"},"軟":{"id":941,"char":"軟","hun":"연할 연","meaning":"“연할 연”. 부드러운, 연한","on":"ナン","kun":"やわ(らか)、やわ(らかい)","explanation":["軟 = 車 + 欠。","「車」는 “수레, 차”를 뜻합니다.","「欠」는 “부족한, 결함의”라는 뜻입니다.","軟는 “낡아서 여기저기 망가진(欠) 수레(車)” -> “연약한, 부드러운”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/953/"},"沈":{"id":942,"char":"沈","hun":"잠길 침","meaning":"“잠길 침”. 잠기다, 가라앉다","on":"チン","kun":"しず(む)、しず(める)","explanation":["沈 = 氵 + 冘。","「氵」는 “물”을 뜻합니다.","冘는 “목에 칼(冖)을 찬 죄수(人)”를 그린 모양자입니다.","沈는 “물(氵) 속에 죄수(冘)를 수장시키다” -> “잠기다, 가라앉다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/954/"},"凍":{"id":943,"char":"凍","hun":"얼 동","meaning":"“얼 동”. 얼다","on":"トウ","kun":"こお(る)、こご(える)","explanation":["凍 = 冫 + 東。","(의미부) 「冫」는 “얼음”을 뜻합니다.","(소리부 겸 의미부) 「東」(トウ)는 “동쪽”을 뜻합니다.","凍는 “모든 게 얼어붙는(冫) 추운 극동(東)” -> “얼다”라는 뜻의 글자입니다.","(東는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/955/"},"腹":{"id":944,"char":"腹","hun":"배 복","meaning":"“배 복”. 배","on":"フク","kun":"はら","explanation":["腹 = 月 + 复。","(의미부) 「月」는 “신체의 일부”를 뜻합니다.","(소리부) 「复」(フク)는 여기서는 소리부의 역할만 하고 있습니다.","腹는 “신체의 일부(月)” -> “배”라는 뜻의 글자입니다(复는 소리부)."],"sourceUrl":"https://nihongokanji.com/956/"},"乳":{"id":945,"char":"乳","hun":"젖 유","meaning":"“젖 유”. 젖, 유방","on":"ニュウ","kun":"ちち、ち","explanation":["乳 = ⺤ + 子 + 乚。","「⺤」는 “손”을 뜻합니다.","「子」는 “아이”를 뜻합니다.","乚는 여기서는 “여자의 유방”을 그린 모양자입니다.","乳는 “아이(子)를 손(⺤)에 안고 젖(乚)을 먹이다” -> “젖, 유방”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/957/"},"煙":{"id":946,"char":"煙","hun":"연기 연","meaning":"“연기 연”. 연기, 그을음","on":"エン","kun":"けむ(る)、けむり、けむ(い)","explanation":["煙 = 火 + 覀 + 土。","「火」는 “불”을 뜻합니다.","「覀」는 “덮다”라는 뜻입니다.","「土」는 “땅”을 뜻합니다.","煙는 “연기(火)가 땅(土)을 뒤덮다(覀)” -> “연기, 그을음”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/958/"},"恋":{"id":947,"char":"恋","hun":"사모할 연","meaning":"“사모할 연”. 그리워하다, 사모하다","on":"レン","kun":"こ(う)、こい、こい(しい)","explanation":["恋 = 亦 + 心。","「亦」는 “팔을 벌리고 걷는 사람”을 그린 글자입니다.","「心」는 “마음”을 뜻합니다.","恋는 “떠나간 사람(亦)을 그리워하는 마음(心)” -> “그리워하다, 사모하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/959/"},"紅":{"id":948,"char":"紅","hun":"붉을 홍","meaning":"“붉을 홍”. 붉다, 홍색","on":"コウ、ク","kun":"べに、くれない","explanation":["紅 = 糸 + 工。","(의미부) 「糸」는 “실”을 뜻합니다.","(소리부) 「工」(コウ・ク)는 여기서는 소리부의 역할만 하고 있습니다.","紅는 “붉게 염색한 실(糸)” -> “붉다”라는 뜻의 글자입니다(工는 소리부)."],"sourceUrl":"https://nihongokanji.com/960/"},"郊":{"id":949,"char":"郊","hun":"들 교","meaning":"“들 교”. 변두리, 교외","on":"コウ","kun":"","explanation":["郊 = 交 + ⻏。","(소리부 겸 의미부) 「交」(コウ)는 “교차하다”라는 뜻입니다.","(의미부) 「⻏」는 “도시”를 뜻합니다.","郊는 “도시(⻏) 밖으로 나가는 교차로(交)” -> “변두리, 교외”라는 뜻의 글자입니다.","(交는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/961/"},"腰":{"id":950,"char":"腰","hun":"허리 요","meaning":"“허리 요”. 허리","on":"ヨウ","kun":"こし","explanation":["腰 = 月 + 要。","(의미부) 「月」는 “신체의 일부”를 뜻합니다.","(소리부 겸 의미부) 「要」(ヨウ)는 본래 “허리에 손을 올린 여자”를 그린 글자입니다(링크 참조).","腰는 “신체의 일부(月) + 여자의 허리(要)” -> “허리”라는 뜻의 글자입니다.","(要는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/962/"},"踊":{"id":951,"char":"踊","hun":"뛸 용","meaning":"“뛸 용”. 춤추다","on":"ヨウ","kun":"おど(る)","explanation":["踊 = 足 + 甬。","「足」는 “발”을 뜻합니다.","「甬」는 “종”을 뜻합니다.","踊는 “종소리(甬)에 맞춰 춤추다(足)” -> “춤추다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/963/"},"冊":{"id":952,"char":"冊","hun":"책 책","meaning":"“책 책”. 책","on":"サツ、サク","kun":"","explanation":["冊는 “죽간을 둥글게 말아놓은 모습”을 그린 상형문자입니다.","“죽간을 말아놓은 것” -> “책”이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/964/"},"眠":{"id":953,"char":"眠","hun":"잘 면","meaning":"“잘 면”. 잠자다, 졸리다","on":"ミン","kun":"ねむ(る)、ねむ(い)","explanation":["眠 = 目 + 民。","(의미부) 「目」는 “눈”을 뜻합니다.","(소리부 겸 의미부) 「民」(ミン)은 “백성, 국민”을 뜻합니다.","眠는 “서민(民)의 졸리고 피곤한 눈(目)” -> “잠자다, 졸다”라는 뜻의 글자입니다.","(民는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/965/"},"怖":{"id":954,"char":"怖","hun":"두려워할 포","meaning":"“두려워할 포”. 두려워하다, 무서워하다","on":"フ","kun":"こわ(い)","explanation":["怖 = 忄 + 布。","(의미부) 「忄」는 “마음”을 뜻합니다.","(소리부 겸 의미부) 「布」(フ)는 “퍼지다, 베풀다”라는 뜻입니다.","怖는 “두려운 마음(忄)이 퍼져나가다(布)” -> “두려워하다”라는 뜻의 글자입니다.","(布는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/966/"},"珍":{"id":955,"char":"珍","hun":"보배 진","meaning":"“보배 진”. 진귀한, 흔치 않은","on":"チン","kun":"めずら(しい)","explanation":["珍 = 𤣩 + 㐱。","「𤣩」는 “구슬”을 뜻합니다.","㐱는 여기서는 “반짝반짝 윤기가 흐르는 모습”을 표현한 모양자입니다.","珍는 “반짝반짝 윤기가 흐르는(㐱) 옥구슬(𤣩)” -> “진귀한, 흔치 않은”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/967/"},"卵":{"id":956,"char":"卵","hun":"알 란","meaning":"“알 란”. 알","on":"ラン","kun":"たまご","explanation":["卵는 “곤충이 식물의 줄기에 알을 낳아놓은 모습”을 그린 상형문자입니다.","“곤충의 알” -> “알”이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/968/"},"狭":{"id":957,"char":"狭","hun":"좁을 협","meaning":"“좁을 협”. 좁다, 좁히다","on":"キョウ","kun":"せま(い)、せば(める)、せば(まる)","explanation":["狭 = 犭 + 夹。","(의미부) 「犭」는 “개”를 뜻합니다.","(소리부 겸 의미부) 「夹」(キョウ)는 “끼다, 끼이다”라는 뜻의 글자입니다(링크 참조).","狭는 “좁은 틈에 끼어서(夹) 나오지 못하고 있는 개(犭)” -> “좁다, 좁히다”라는 뜻의 글자입니다.","(夹는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/969/"},"喫":{"id":958,"char":"喫","hun":"먹을 끽","meaning":"“먹을 끽”. 씹다, 먹다, 만끽하다","on":"キツ","kun":"","explanation":["喫 = 口 + 龶 + 刀 + 大。","「口」는 “입”을 뜻합니다.","龶는 여기서는 “담뱃잎”을 그린 모양자입니다.","「刀」는 “칼”을 뜻합니다.","「大」는 “사람”을 그린 글자입니다.","喫는 “담뱃잎(龶)을 잘라(刀) 입(口) 안에 넣고 씹는 사람(大)” -> “씹다, 먹다, 만끽하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/970/"},"干":{"id":959,"char":"干","hun":"방패/줄기 간, 마를 건","meaning":"“방패/줄기 간, 마를 건”. 방패, 줄기, 상관하다, 마르다","on":"カン","kun":"ほ(す)、ひ(る)","explanation":["干는 “고대에 쓰이던 방패”를 본따 그린 상형문자입니다.","(干에 포함된 여러 가지 다른 의미들(줄기, 상관하다, 마르다 등)은 전부 음독이 비슷하다는 이유로 나중에 추가된 것입니다.)"],"sourceUrl":"https://nihongokanji.com/971/"},"頂":{"id":960,"char":"頂","hun":"정수리 정","meaning":"“정수리 정”. 정상, 꼭대기","on":"チョウ","kun":"いただ(く)、いただき","explanation":["頂 = 丁 + 頁。","(소리부 겸 의미부) 「丁」(チョウ)는 “못”을 뜻합니다. 여기서는 “뾰족한 못” -> “꼭대기”라는 뜻으로 쓰인 것입니다.","(의미부) 「頁」는 “머리”를 뜻합니다.","頂는 “머리(頁) 꼭대기(丁)” -> “정상, 꼭대기”라는 뜻의 글자입니다.","(丁는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/972/"},"溶":{"id":961,"char":"溶","hun":"녹을 용","meaning":"“녹을 용”. 녹다, 녹이다","on":"ヨウ","kun":"と(ける)、と(かす)、と(く)","explanation":["溶 = 氵 + 容。","(의미부) 「氵」는 “물”을 뜻합니다.","(소리부 겸 의미부) 「容」(ヨウ)는 “담다, 수용하다”라는 뜻입니다.","溶는 “물(氵)에 녹아 스며들다(容)” -> “녹다, 녹이다”라는 뜻의 글자입니다.","(容는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/973/"},"暖":{"id":962,"char":"暖","hun":"따뜻할 난","meaning":"“따뜻할 난”. 따뜻하다","on":"ダン","kun":"あたた(か)、あたた(かい)、あたた(まる)、あたた(める)","explanation":["暖 = 日 + 爰。","「日」는 “태양”을 뜻합니다.","「爰」는 “한가롭다, 여유롭다, 느긋하다”라는 뜻의 글자입니다(링크 참조).","暖는 “따뜻한 햇살(日) 아래서 여유를(爰) 즐기다” -> “따뜻하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/974/"},"鉱":{"id":963,"char":"鉱","hun":"광물 광","meaning":"“광물 광”. 광석, 광물","on":"コウ","kun":"","explanation":["鉱 = 金 + 広。","(의미부) 「金」는 “쇠, 금속”을 뜻합니다.","(소리부 겸 의미부) 「広」(コウ)는 “넓다”라는 뜻입니다.","鉱는 “넓은 광산(広)에서 나는 금속들(金)” -> “광석, 광물”이라는 뜻의 글자입니다.","(広는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/975/"},"涙":{"id":964,"char":"涙","hun":"눈물 루","meaning":"“눈물 루”. 눈물","on":"ルイ","kun":"なみだ","explanation":["涙 = 氵 + 戻。","「氵」는 “물”을 뜻합니다.","「戻」는 본래 “문(戸) 앞에서 거절당하고 돌아가는 사람(大)”을 그린 글자입니다(링크 참조).","涙는 “거절당하고 돌아가며(戻) 눈물을 흘리다(氵)” -> “눈물”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/976/"},"匹":{"id":965,"char":"匹","hun":"짝 필","meaning":"“짝 필”. 짝, 상대, ~필(동물을 세는 단위)","on":"ヒツ","kun":"ひき","explanation":["匹는 “사람의 콧구멍”을 그린 상형문자입니다.","“콧구멍 두 개” -> “짝, 상대”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/977/"},"鋭":{"id":966,"char":"鋭","hun":"날카로울 예","meaning":"“날카로울 예”. 날카로운, 예리한","on":"エイ","kun":"するど(い)","explanation":["鋭 = 金 + 兑。","「金」는 “쇠, 금속”을 뜻합니다.","「兑」는 “날카로운 눈을 한 사람”을 그린 글자입니다.","鋭는 “날카로운(兑) 금속(金)” -> “날카로운, 예리한”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/978/"},"枝":{"id":967,"char":"枝","hun":"가지 지","meaning":"“가지 지”. 가지, 나뭇가지","on":"シ","kun":"えだ","explanation":["枝 = 木 + 支。","(의미부) 「木」는 “나무”를 뜻합니다.","(소리부 겸 의미부) 「支」(シ)는 “(갈라져 나온) 지류/지부”를 뜻합니다.","枝는 “나무(木)에서 갈라져 나온(支) 가지” -> “나뭇가지”라는 뜻의 글자입니다.","(支는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/979/"},"塗":{"id":968,"char":"塗","hun":"칠할 도","meaning":"“칠할 도”. 칠하다, 바르다","on":"ト","kun":"ぬ(る)","explanation":["塗 = 氵 + 余 + 土。","「氵」는 “물”을 뜻합니다.","「土」는 “흙”을 뜻합니다.","「余」는 “잎이 풍성한 나무”를 그린 글자입니다.","塗는 “나무(余)에 진흙(氵+土)을 바르다” -> “칠하다, 바르다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/980/"},"軒":{"id":969,"char":"軒","hun":"집 헌","meaning":"“집 헌”. 처마, 가옥","on":"ケン","kun":"のき","explanation":["軒 = 車 + 干。","「車」는 “수레, 차”를 뜻합니다.","「干」는 “방패”를 뜻합니다. 여기서는 “방패” -> “차양막”이라는 뜻으로 쓰인 것입니다.","軒는 “수레(車)에 달린 차양막(干)” -> “처마”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/981/"},"晩":{"id":970,"char":"晩","hun":"늦을 만","meaning":"“늦을 만”. 저녁, 밤, 늦다","on":"バン","kun":"","explanation":["晩 = 日 + 免。","「日」는 “해”를 뜻합니다.","免(“면할 면”)은 “면하다”라는 뜻의 상용한자입니다.","晩는 “해가 져서 햇빛(日)을 면하다(免)” -> “저녁, 밤, 늦다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/982/"},"叫":{"id":971,"char":"叫","hun":"부르짖을 규","meaning":"“부르짖을 규”. 울부짖다, 부르짖다","on":"キョウ","kun":"さけ(ぶ)","explanation":["叫 = 口 + 丩。","「口」는 “입”을 뜻합니다.","「丩」는 “얽히다”라는 뜻입니다.","叫는 “한데 얽혀(丩) 울부짖다(口)” -> “부르짖다, 울부짖다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/983/"},"拝":{"id":972,"char":"拝","hun":"절 배","meaning":"“절 배”. 절하다, 경의를 표하다","on":"ハイ","kun":"おが(む)","explanation":["拝 = 扌 + 一 + 丰。","「扌」는 “손”을 뜻합니다.","「一」는 “1”을 뜻합니다.","丰는 여기서는 「手」가 변형된 것으로, “손”을 뜻합니다.","拝는 “두 손(扌+丰)을 하나로 모아(一) 합장하다” -> “절하다, 경의를 표하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/984/"},"乾":{"id":973,"char":"乾","hun":"마를 건","meaning":"“마를 건”. 마르다, 말리다","on":"カン","kun":"かわ(く)、かわ(かす)","explanation":["乾 = 𠦝 + 乞。","「𠦝」는 “떠오르는 아침해”를 그린 글자입니다.","乞는 여기서는 “아지랑이(乙)가 피어오르는(𠂉) 모습”을 표현한 모양자입니다.","乾는 “햇볕(𠦝)을 받아 아지랑이가(乞) 피어오르다” -> “마르다, 말리다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/985/"},"棒":{"id":974,"char":"棒","hun":"막대 봉","meaning":"“막대 봉”. 막대, 봉","on":"ボウ","kun":"","explanation":["棒 = 木 + 奉。","(의미부) 「木」는 “나무”를 뜻합니다.","(소리부) 奉(ホウ – “받들 봉”)은 “받들다, 섬기다”라는 뜻의 상용한자입니다.","다만 여기서는 소리부(ホウ -> ボウ)의 역할만 하고 있습니다.","棒는 “나무(木) 막대기” -> “막대, 봉”이라는 뜻의 글자입니다(奉는 소리부)."],"sourceUrl":"https://nihongokanji.com/986/"},"祈":{"id":975,"char":"祈","hun":"빌 기","meaning":"“빌 기”. 빌다, 기원하다","on":"キ","kun":"いの(る)","explanation":["祈 = 礻 + 斤。","「礻」는 “종교, 신, 고대의 비석”을 뜻합니다.","「斤」는 “도끼”를 뜻합니다.","祈는 “전쟁(斤)의 승리를 신에게 빌다(礻)” -> “기원하다, 빌다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/987/"},"髪":{"id":976,"char":"髪","hun":"터럭 발","meaning":"“터럭 발”. 머리카락","on":"ハツ","kun":"かみ","explanation":["髪 = 镸 + 彡 + 友。","镸는 「長」가 축약된 것으로, “길다”라는 뜻입니다.","彡는 여기서는 “머리카락”을 그린 모양자입니다.","「友」는 “친구”를 뜻합니다.","髪는 “머리(彡)를 길게(镸) 기른 친구(友)” -> “머리카락”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/988/"},"忙":{"id":977,"char":"忙","hun":"바쁠 망","meaning":"“바쁠 망”. 바쁘다","on":"ボウ","kun":"いそが(しい)","explanation":["忙 = 忄 + 亡。","(의미부) 「忄」는 “마음”을 뜻합니다.","(소리부 겸 의미부) 「亡」(ボウ)는 “망하다, 죽다”라는 뜻입니다.","忙는 “마음을(忄) 잊을(亡) 정도로 바쁘다” -> “바쁘다”라는 뜻의 글자입니다.","(亡는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/989/"},"綿":{"id":978,"char":"綿","hun":"솜 면","meaning":"“솜 면”. 솜, 무명","on":"メン","kun":"わた","explanation":["綿 = 糸 + 白 + 巾。","「糸」는 “실”을 뜻합니다.","「白」는 “흰색”을 뜻합니다.","「巾」는 “수건, 천”을 뜻합니다.","綿는 “실(糸)로 된 흰색(白) 천(巾)” -> “솜, 무명”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/990/"},"汗":{"id":979,"char":"汗","hun":"땀 한","meaning":"“땀 한”. 땀","on":"カン","kun":"あせ","explanation":["汗 = 氵 + 干。","(의미부) 「氵」는 “물”을 뜻합니다.","(소리부 겸 의미부) 「干」(カン)은 “마르다”라는 뜻입니다.","汗는 “땀(氵)이 마르다(干)” -> “땀”이라는 뜻의 글자입니다.","(干은 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/991/"},"銅":{"id":980,"char":"銅","hun":"구리 동","meaning":"“구리 동”. 구리","on":"ドウ","kun":"","explanation":["銅 = 金 + 同。","(의미부) 「金」는 “쇠, 금속”을 뜻합니다.","(소리부) 「同」(ドウ)는 여기서는 소리부의 역할만 하고 있습니다.","銅는 “금속(金)” -> “구리”라는 뜻의 글자입니다(同는 소리부)."],"sourceUrl":"https://nihongokanji.com/992/"},"湿":{"id":981,"char":"湿","hun":"젖을 습","meaning":"“젖을 습”. 습기차다, 젖다","on":"シツ","kun":"しめ(る)、しめ(す)","explanation":["湿 = 氵 + 日 + 业。","「氵」는 “물”을 뜻합니다.","「日」는 “태양”을 뜻합니다.","业는 여기서는 “젖은 윗옷”을 그린 모양자입니다.","湿는 “물(氵)에 젖은 윗옷(业)을 햇볕(日)에 말리다” -> “습기차다, 젖다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/993/"},"咲":{"id":982,"char":"咲","hun":"필 소","meaning":"“필 소”. (꽃이)피다","on":"","kun":"さ(く)","explanation":["咲 = 口 + 关。","「口」는 “입”을 뜻합니다.","「关」는 “웃음”을 뜻합니다.","咲는 “꽃봉오리가 입(口)을 벌리고 활짝 웃다(关)” -> “꽃이 피다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/994/"},"召":{"id":983,"char":"召","hun":"부를 소","meaning":"“부를 소”. 부르다, 소환","on":"ショウ","kun":"め(す)","explanation":["召 = 刀 + 口。","「刀」는 “칼”을 뜻합니다.","「口」는 “입”을 뜻합니다.","옛사람들은 “입은 화를 부르는 문이며, 혀는 몸을 베는 칼이다”라고 경계했다고 합니다.","召는 “말실수(口)가 화(刀)를 부르다” -> “부르다”라는 뜻의 글자입니다.","참고) 招、召의 차이점","召는 “법적인 소환, 혹은 지위가 높은 사람이 부르는 소환/소집”을 뜻합니다.","招는 별다른 상하관계가 없는 단순한 “초대”, “초청”을 뜻합니다."],"sourceUrl":"https://nihongokanji.com/995/"},"脂":{"id":984,"char":"脂","hun":"기름 지","meaning":"“기름 지”. 기름, 지방","on":"シ","kun":"あぶら","explanation":["脂 = 月 + 旨。","(의미부) 「月」는 “고기”를 뜻합니다.","(소리부 겸 의미부) 旨는 여기서는 「指」(シ)가 축약된 것으로, “손가락”을 뜻합니다.","脂는 “개기름(月)이 줄줄 흐르는 손가락(指)” -> “기름, 지방”이라는 뜻의 글자입니다.","(旨->指는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/996/"},"蒸":{"id":985,"char":"蒸","hun":"찔 증","meaning":"“찔 증”. 찌다, 증기","on":"ジョウ","kun":"む(れる)、む(らす)、む(す)","explanation":["蒸 = 艹 + 氶 + 一 + 灬。","「艹」는 “풀”을 뜻합니다.","氶는 「水」가 살짝 변형된 것으로, “물”을 뜻합니다.","一는 여기서는 “불판”을 그린 모양자입니다.","「灬」는 “불”을 뜻합니다.","蒸는 “불판(一+灬)위에 야채(艹)를 올리고 수증기(氶)를 내서 찌다” -> “찌다, 증기”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/997/"},"肌":{"id":986,"char":"肌","hun":"살 기","meaning":"“살 기”. 살갗, 피부","on":"","kun":"はだ","explanation":["肌 = 月 + 几。","「月」는 “신체의 일부”를 뜻합니다.","几는 여기서는 “살가죽”을 그린 모양자입니다.","肌는 “신체의 일부(月) + 살가죽(几)” -> “살갗, 피부”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/998/"},"靴":{"id":987,"char":"靴","hun":"신 화","meaning":"“신 화”. 구두","on":"カ","kun":"くつ","explanation":["靴 = 革 + 化。","(의미부) 「革」는 “가죽”을 뜻합니다.","(소리부 겸 의미부) 「化」(カ)는 “바뀌다, 변하다”라는 뜻입니다.","靴는 “가죽(革)을 가공해서(化) 만든 구두” -> “구두”라는 뜻의 글자입니다.","(化는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/999/"},"耕":{"id":988,"char":"耕","hun":"밭 갈 경","meaning":"“밭 갈 경”. 밭을 갈다, 경작하다","on":"コウ","kun":"たがや(す)","explanation":["耕 = 耒 + 井。","「耒」는 “쟁기”를 그린 글자입니다(링크 참조).","井(“우물 정”)은 “우물”을 뜻하는 상용한자입니다.","耕는 “쟁기(耒)와 농사에 쓸 물(井)” -> “경작하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1000/"},"鈍":{"id":989,"char":"鈍","hun":"둔할 둔","meaning":"“둔할 둔”. 둔하다, 무디다","on":"ドン","kun":"にぶ(い)、にぶ(る)","explanation":["鈍 = 金 + 屯。","(의미부) 「金」는 “쇠, 금속”을 뜻합니다.","(소리부 겸 의미부) 「屯」(トン)은 “뿌리깊은 나무”를 뜻합니다.","鈍는 “무쇠(金)처럼 굳건히 뿌리박고(屯) 서 있는 거대한 나무” -> “둔하다, 무디다”라는 뜻의 글자입니다.","(屯는 소리부(トン -> ドン)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1001/"},"恥":{"id":990,"char":"恥","hun":"부끄러울 치","meaning":"“부끄러울 치”. 부끄러워하다, 부끄러움","on":"チ","kun":"は(じる)、はじ、は(じらう)、は(ずかしい)","explanation":["恥 = 耳 + 心。","「耳」는 “귀”를 뜻합니다.","「心」는 “마음”을 뜻합니다.","恥는 “부끄러운 마음(心)에 귀(耳)가 빨개지다” -> “부끄러움”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1002/"},"泥":{"id":991,"char":"泥","hun":"진흙 니","meaning":"“진흙 니”. 진흙","on":"デイ","kun":"どろ","explanation":["泥 = 氵 + 尸 + 匕。","「氵」는 “물”을 뜻합니다.","「尸」는 “앉아있는 사람”을 뜻합니다.","「匕」는 “넘어져있는 사람”을 뜻합니다.","泥는 “진흙탕(氵)에 넘어져(匕) 주저앉은(尸) 사람” -> “진흙”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1003/"},"隅":{"id":992,"char":"隅","hun":"모퉁이 우","meaning":"“모퉁이 우”. 구석, 모퉁이","on":"グウ","kun":"すみ","explanation":["隅 = ⻖ + 禺。","(의미부) 「⻖」는 “언덕, 산”을 뜻합니다.","(소리부 겸 의미부) 「禺」(グウ)는 “원숭이”를 뜻하는 글자입니다(링크 참조).","隅는 “깊은 산속(⻖) 구석에만 숨어사는 원숭이(禺)” -> “구석, 모퉁이”라는 뜻의 글자입니다.","(禺는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1004/"},"偶":{"id":993,"char":"偶","hun":"짝 우","meaning":"“짝 우”. 우연, 짝, 배필, 우상","on":"グウ","kun":"","explanation":["偶 = 亻 + 禺。","(의미부) 「亻」는 “사람”을 뜻합니다.","(소리부 겸 의미부) 「禺」(グウ)는 “원숭이”를 뜻합니다.","偶는 “사람(亻)이 원숭이(禺)를 마주치다”라는 뜻입니다.","“원숭이를 마주치는 것은 희귀한 일” -> “우연”","“마주치다” -> “만나다” -> “짝, 배필”","“사람과 닮은 동물” -> “닮다” -> “우상”","이라는 의미입니다.","(禺는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1005/"},"辛":{"id":994,"char":"辛","hun":"매울 신","meaning":"“매울 신”. 맵다, 가혹하다, 괴롭다","on":"シン","kun":"から(い)","explanation":["辛는 “노예의 몸에 문신을 새기던 도구”를 그린 상형문자입니다.","“노예 신세” -> “가혹하다, 괴롭다, 맵다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/1006/"},"磨":{"id":995,"char":"磨","hun":"갈 마","meaning":"“갈 마”. 갈다, 윤기나게 닦다, 연마하다","on":"マ","kun":"みが(く)","explanation":["磨 = 广 + 林 + 石。","「广」는 “건물, 집”을 뜻합니다.","「石」는 “돌”을 뜻합니다.","林는 여기서는 “대마(삼베의 원료)”를 그린 모양자입니다. 아래 그림을 참조해 주세요.","삼베를 만들기 위해서는, 먼저 대마를 말린 다음 돌로 문질러야 한다고 합니다.","磨는 “집(广)에서 말린 대마(林)를 돌(石)로 문지르다” -> “갈다, 닦다, 연마하다”라는 뜻의 글자입니다.","참고)","磨에서 石를 뺀 麻는 “삼베”를 뜻하는 상용한자입니다(1296.「麻」참조)."],"sourceUrl":"https://nihongokanji.com/1007/"},"姓":{"id":996,"char":"姓","hun":"성 성","meaning":"“성 성”. 성씨","on":"セイ、ショウ","kun":"","explanation":["姓 = 女 + 生。","(의미부) 「女」는 “여자”를 뜻합니다.","(소리부 겸 의미부) 「生」(セイ・ショウ)는 “생명, 태어나다”라는 뜻입니다.","일본에서는 여자가 결혼하면 남편의 성을 따르게 됩니다.","姓는 “여자(女)가 자라서(生) 결혼하면 받게 되는 것” -> “성씨”라는 뜻의 글자입니다.","(生는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1008/"},"筒":{"id":997,"char":"筒","hun":"통 통","meaning":"“통 통”. 통, 원통","on":"トウ","kun":"つつ","explanation":["筒 = 𥫗 + 同。","(의미부) 「𥫗」는 “대나무”를 뜻합니다.","(소리부 겸 의미부) 「同」(ドウ)는 본래 “둥글게 둘러앉은 모습”을 그린 글자입니다(링크 참조).","筒는 “둥근(同) 통 모양의 대나무 줄기(𥫗)” -> “원통”이라는 뜻의 글자입니다.","(同는 소리부(ドウ -> トウ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1009/"},"粒":{"id":998,"char":"粒","hun":"낟알 립","meaning":"“낟알 립”. 낟알, 입자","on":"リュウ","kun":"つぶ","explanation":["粒 = 米 + 立。","(의미부) 「米」는 “쌀”을 뜻합니다.","(소리부) 「立」(リュウ)는 여기서는 소리부의 역할만 하고 있습니다.","粒는 “쌀알(米)” -> “낟알, 입자”라는 뜻의 글자입니다(立는 소리부)."],"sourceUrl":"https://nihongokanji.com/1010/"},"詞":{"id":999,"char":"詞","hun":"말/글 사","meaning":"“말/글 사”. 말, 언어, 시","on":"シ","kun":"","explanation":["詞 = 言 + 司。","(의미부) 「言」는 “말하다”라는 뜻입니다.","(소리부 겸 의미부) 「司」(シ)는 “주관하다, 다스리다”라는 뜻입니다.","詞는 “높은 사람(司)이 쓰는 말(言)” -> “말, 언어, 시”라는 뜻의 글자입니다.","(司는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1011/"},"偉":{"id":1000,"char":"偉","hun":"클 위","meaning":"“클 위”. 위대하다, 뛰어나다","on":"イ","kun":"えら(い)","explanation":["偉 = 亻 + 韋。","(의미부) 「亻」는 “사람”을 뜻합니다.","(소리부 겸 의미부) 「韋」(イ)는 “성 주위를 돌며 경계서는 발들”을 그린 글자입니다.","偉는 “호위병들(韋)에게 호위받는 높은 사람(亻)” -> “위대하다, 훌륭하다”라는 뜻의 글자입니다.","(韋는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1012/"},"畳":{"id":1001,"char":"畳","hun":"겹쳐질 첩","meaning":"“겹쳐질 첩”. (이불 등을) 접다, 개다, 다다미","on":"ジョウ","kun":"たた(む)、たたみ","explanation":["畳는 “이불을 반듯이 개서 쌓아놓은 모습”을 그린 상형문자입니다.","(田、冖、且는 여기서는 전부 단순한 모양자로 쓰인 것입니다.)"],"sourceUrl":"https://nihongokanji.com/1013/"},"机":{"id":1002,"char":"机","hun":"책상 궤","meaning":"“책상 궤”. 책상, 탁자","on":"キ","kun":"つくえ","explanation":["机 = 木 + 几。","「木」는 “나무”를 뜻합니다.","几는 여기서는 “책상”을 그린 모양자입니다.","机는 “나무(木)로 만든 책상(几)” -> “책상, 탁자”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1014/"},"膚":{"id":1003,"char":"膚","hun":"살갗 부","meaning":"“살갗 부”. 피부","on":"フ","kun":"","explanation":["膚 = 虍 + 胃。","「虍」는 “호랑이”를 뜻합니다.","「胃」는 “위”를 뜻합니다.","膚는 “호랑이(虍)의 내장(胃)을 덮고 있는 가죽” -> “피부, 살갗”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1015/"},"濯":{"id":1004,"char":"濯","hun":"씻을 탁","meaning":"“씻을 탁”. 씻다, 세탁","on":"タク","kun":"","explanation":["濯 = 氵 + 羽 + 隹。","「氵」는 “물”을 뜻합니다.","「羽」는 “날개”를 뜻합니다.","「隹」는 “새”를 뜻합니다.","濯는 “새(隹)가 날개(羽)를 퍼덕이며 물기(氵)를 털어내다” -> “씻다, 세탁”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1016/"},"猫":{"id":1005,"char":"猫","hun":"고양이 묘","meaning":"“고양이 묘”. 고양이","on":"ビョウ","kun":"ねこ","explanation":["猫 = ⺨ + 艹 + 田。","「⺨」는 “개, 동물”을 뜻합니다.","「艹」는 “풀”을 뜻합니다.","「田」는 “밭”을 뜻합니다.","猫는 “밭(田)의 곡식(艹)을 갉아먹는 쥐를 잡아먹는 애완동물(⺨)” -> “고양이”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1017/"},"塔":{"id":1006,"char":"塔","hun":"탑 탑","meaning":"“탑 탑”. 탑","on":"トウ","kun":"","explanation":["塔 = 土 + 荅。","(의미부) 「土」는 “흙”을 뜻합니다.","(소리부 겸 의미부) 荅는 여기서는 「答」(トウ)가 살짝 변형된 것으로, “탑”의 모습을 그린 모양자로 쓰인 것입니다.","塔는 “흙(土)으로 쌓아올린 탑(荅)” -> “탑”이라는 뜻의 글자입니다.","(荅->答는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1018/"},"沸":{"id":1007,"char":"沸","hun":"끓을 비","meaning":"“끓을 비”. 끓다, 용솟음치다","on":"フツ","kun":"わ(く)、わ(かす)","explanation":["沸 = 氵 + 弗。","「氵」는 “물”을 뜻합니다.","弗는 여기서는 “땅에서 온천수가 솟아나는 모습”을 그린 모양자입니다.","沸는 “온천수(氵)가 땅에서 솟아나다(弗)” -> “끓다, 용솟음치다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1019/"},"灰":{"id":1008,"char":"灰","hun":"재 회","meaning":"“재 회”. 재","on":"カイ","kun":"はい","explanation":["灰 = 厂 + 火。","厂는 여기서는 “아궁이”를 그린 모양자입니다.","「火」는 “불”을 뜻합니다.","灰는 “아궁이(厂)의 불(火)이 타고 남은 재” -> “재, 잿더미”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1020/"},"菓":{"id":1009,"char":"菓","hun":"과자 과","meaning":"“과자 과”. 과자","on":"カ","kun":"","explanation":["菓 = 艹 + 果。","(의미부) 「艹」는 “풀”을 뜻합니다.","(소리부 겸 의미부) 「果」(カ)는 본래 “나무 위의 열매”를 그린 글자입니다(링크 참조).","菓는 “나무열매(果)와 야채(艹)로 만든 과자” -> “과자”라는 뜻의 글자입니다.","(果는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1021/"},"帽":{"id":1010,"char":"帽","hun":"모자 모","meaning":"“모자 모”. 모자","on":"ボウ","kun":"","explanation":["帽 = 巾 + 日 + 目。","「巾」는 “수건, 천”을 뜻합니다.","「日」는 “태양”을 뜻합니다.","「目」는 “눈”을 뜻합니다.","帽는 “태양빛(日)을 막기 위해 눈(目) 위에 두른 천(巾)” -> “모자”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1022/"},"枯":{"id":1011,"char":"枯","hun":"마를 고","meaning":"“마를 고”. 마르다, 시들다, 고갈되다","on":"コ","kun":"か(れる)、か(らす)","explanation":["枯 = 木 + 古。","(의미부) 「木」는 “나무”를 뜻합니다.","(소리부 겸 의미부) 「古」(コ)는 “오래되다”라는 뜻입니다.","枯는 “너무 오래돼서(古) 말라죽은 나무(木)” -> “마르다, 시들다, 고갈되다”라는 뜻의 글자입니다.","(古는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1023/"},"涼":{"id":1012,"char":"涼","hun":"서늘할 량","meaning":"“서늘할 량”. 서늘하다, 시원하다","on":"リョウ","kun":"すず(しい)、すず(む)","explanation":["涼 = 氵 + 京。","(의미부) 「氵」는 “물”을 뜻합니다.","(소리부 겸 의미부) 「京」(キョウ)는 본래 “기둥 위에 세워진 건물”을 그린 글자입니다(링크 참조).","涼는 “강가(氵)에 세워놓은 정자(京)” -> “시원하다, 서늘하다”라는 뜻의 글자입니다.","(京는 소리부(キョウ -> リョウ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1024/"},"舟":{"id":1013,"char":"舟","hun":"배 주","meaning":"“배 주”. 배","on":"シュウ","kun":"ふね、ふな","explanation":["舟는 “노를 저어 움직이는 작은 조각배”를 그린 상형문자입니다."],"sourceUrl":"https://nihongokanji.com/1025/"},"符":{"id":1014,"char":"符","hun":"부호 부","meaning":"“부호 부”. 부호, 기호","on":"フ","kun":"","explanation":["符 = 𥫗 + 付。","(의미부) 「𥫗」는 “대나무”를 뜻합니다.","(소리부 겸 의미부) 「付」(フ)는 “부치다, 붙이다”라는 뜻입니다.","먼 옛날에는 편지의 진위 여부를 확인하기 위해 반으로 쪼개 나눈 대나무 조각을 맞춰 보았다고 합니다.","즉, “대나무 조각(𥫗)을 붙여(付) 보는 것”이 신원을 확인하는 표식의 역할을 한 것입니다.","符는 “대나무 조각(𥫗)을 붙여서(付) 진위를 확인하는 증표” -> “부호, 기호”라는 뜻의 글자입니다.","(付는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1026/"},"憎":{"id":1015,"char":"憎","hun":"미울 증","meaning":"“미울 증”. 미워하다, 증오하다","on":"ゾウ","kun":"にく(む)、にく(い)、にく(らしい)、にく(しみ)","explanation":["憎 = 忄 + 曽。","(의미부) 「忄」는 “마음”을 뜻합니다.","(소리부 겸 의미부) 「曽」(ソウ)는 “쌓이다”라는 뜻입니다.","憎는 “증오하는 마음(忄)이 쌓이다(曽)” -> “미워하다, 증오하다”라는 뜻의 글자입니다.","(曽는 소리부(ソウ -> ゾウ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1027/"},"肯":{"id":1016,"char":"肯","hun":"즐길 긍","meaning":"“즐길 긍”. 긍정하다, 수긍하다","on":"コウ","kun":"","explanation":["肯 = 止 + 月。","「止」는 “발”을 뜻합니다.","「月」는 “고기”를 뜻합니다.","肯는 “돼지족발(止)로 만든 고기(月)는 맛있다” -> “긍정하다, 수긍하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1028/"},"燥":{"id":1017,"char":"燥","hun":"마를 조","meaning":"“마를 조”. 마르다, 말리다","on":"ソウ","kun":"","explanation":["燥 = 火 + 品 + 木。","「火」는 “불”을 뜻합니다.","「品」는 “물건, 물품”을 뜻합니다.","「木」는 “나무”를 뜻합니다.","燥는 “나무(木)를 말려서(火) 팔 수 있는 장작(品)으로 만들다” -> “마르다, 말리다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1029/"},"畜":{"id":1018,"char":"畜","hun":"짐승 축","meaning":"“짐승 축”. 가축","on":"チク","kun":"","explanation":["畜 = 亠 + 幺 + 田。","亠는 여기서는 「宀」이 축약된 것으로, “집”을 뜻합니다.","「幺」는 “작다, 어리다”라는 뜻입니다.","「田」는 “밭”을 뜻합니다.","畜는 “어릴(幺) 때부터 집(亠)에서 키워서 밭(田)을 갈 때 쓰는 가축” -> “가축”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1030/"},"坊":{"id":1019,"char":"坊","hun":"동네 방","meaning":"“동네 방”. 어린이, 승려, 동네","on":"ボウ、ボッ","kun":"","explanation":["坊 = 土 + 方。","(의미부) 「土」는 “흙”을 뜻합니다.","(소리부 겸 의미부) 「方」(ホウ)는 “방향”을 뜻합니다.","坊는 “사방(方)이 흙(土)으로 둘러싸인 산골짜기” -> “승려, 동자승, 어린아이”라는 뜻의 글자입니다.","(方는 소리부(ホウ -> ボウ・ボッ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1031/"},"挟":{"id":1020,"char":"挟","hun":"낄 협","meaning":"“낄 협”. (사이에)끼다, 끼이다","on":"キョウ","kun":"はさ(む)、はさ(まる)","explanation":["挟 = 扌 + 夹。","(의미부) 「扌」는 “손”을 뜻합니다.","(소리부 겸 의미부) 「夹」(キョウ)는 “옆구리에 무언가를 끼고 있는 사람”을 그린 글자입니다(링크 참조).","挟는 “옆구리에 무언가를 꽉 끼고(夹) 손으로 잡고있는(扌) 사람” -> “끼다, 끼이다”라는 뜻의 글자입니다.","(夹는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1032/"},"曇":{"id":1021,"char":"曇","hun":"흐릴 담","meaning":"“흐릴 담”. 구름이 끼다, 흐리다","on":"ドン","kun":"くも(る)","explanation":["曇 = 日 + 雲。","「日」는 “해”를 뜻합니다.","「雲」는 “구름”을 뜻합니다.","曇는 “해(日)가 구름(雲)에 가리다” -> “구름이 끼다, 흐리다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1033/"},"滴":{"id":1022,"char":"滴","hun":"물방울 적","meaning":"“물방울 적”. 물방울, 방울져 떨어지다","on":"テキ","kun":"しずく、したた(る)","explanation":["滴 = 氵 + 啇。","(의미부) 「氵」는 “물”을 뜻합니다.","(소리부 겸 의미부) 「啇」(テキ)는 “화초를 심은 화분”을 그린 글자입니다.","滴는 “화초(啇)에 맺힌 이슬(氵)“ -> “물방울, 방울져 떨어지다”라는 뜻의 글자입니다.","(啇는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1034/"},"伺":{"id":1023,"char":"伺","hun":"엿볼 사","meaning":"“엿볼 사”. 찾아뵙다","on":"シ","kun":"うかが(う)","explanation":["伺 = 亻 + 司。","(의미부) 「亻」는 “사람”을 뜻합니다.","(소리부 겸 의미부) 「司」(シ)는 “주관하다, 다스리다”라는 뜻입니다.","伺는 “윗사람(司)을 찾아뵙다(亻)” -> “찾아뵙다”라는 뜻의 글자입니다.","(司는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1035/"},"氏":{"id":1024,"char":"氏","hun":"성씨 씨","meaning":"“성씨 씨”. 성씨, 집안, ~씨","on":"シ","kun":"うじ","explanation":["氏는 “나무뿌리가 땅 속으로 뻗은 모습”을 그린 상형문자입니다.","“뿌리” -> “혈통” -> “성씨”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/1036/"},"統":{"id":1025,"char":"統","hun":"거느릴 통","meaning":"“거느릴 통”. 거느리다, 통괄하다, 계통","on":"トウ","kun":"す(べる)","explanation":["統 = 糸 + 亠 + ム + 儿。","「糸」는 “실”을 뜻합니다.","亠+ム는 「子」를 거꾸로 뒤집은 것으로, “아이”를 뜻합니다.","儿는 「人」가 살짝 변형된 것으로, “사람”을 뜻합니다.","統는 “아이들(子)을 한데 모아(糸) 데리고 가는 어른(儿)” -> “거느리다, 통괄하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1037/"},"派":{"id":1026,"char":"派","hun":"갈래 파","meaning":"“갈래 파”. 갈래, 파벌, 갈라지다","on":"ハ","kun":"","explanation":["派 = 氵 + 𠂢。","「氵」는 “물”을 뜻합니다.","𠂢는 “물줄기가 여러 갈래로 갈라져 흘러가는 모습”을 그린 모양자입니다.","派는 “여러 갈래로 갈라져(𠂢) 흘러가는 물(氵)” -> “갈래, 파벌, 갈라지다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1038/"},"策":{"id":1027,"char":"策","hun":"꾀 책","meaning":"“꾀 책”. 계책, 책략","on":"サク","kun":"","explanation":["策 = 𥫗 + 朿。","「𥫗」는 “대나무”를 뜻합니다.","「朿」는 “삼지창”을 그린 글자입니다.","策는 “대나무(𥫗) 죽창(朿)으로 상대의 허를 찌르는 전략” -> “계책, 책략”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1039/"},"提":{"id":1028,"char":"提","hun":"끌 제","meaning":"“끌 제”. 제시하다, 들다","on":"テイ","kun":"さ(げる)","explanation":["提 = 扌 + 是。","「扌」는 “손”을 뜻합니다.","是(“옳을 시”)는 “옳다, 바르다”라는 뜻의 상용한자입니다.","提는 “올바른 제안(是)을 내밀다(扌)” -> “제시하다, 들다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1040/"},"挙":{"id":1029,"char":"挙","hun":"들 거","meaning":"“들 거”. 들어올리다, 행동하다","on":"キョ","kun":"あ(げる)、あ(がる)","explanation":["挙 = 兴 + 手。","「手」는 “손”을 뜻합니다.","兴는 여기서는 “왕관”을 그린 모양자입니다.","挙는 “왕관(兴)을 높이 들어올리다(手)” -> “들어올리다, 행동하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1041/"},"企":{"id":1030,"char":"企","hun":"꾀할 기","meaning":"“꾀할 기”. 도모하다, 계획하다","on":"キ","kun":"くわだ(てる)","explanation":["企 = 𠆢 + 止。","「止」는 “발”을 뜻합니다.","𠆢는 여기서는 “위쪽”을 표현한 모양자입니다.","企는 “위쪽(𠆢)으로 올라가려(止) 하다” -> “신분 상승을 도모하다” -> “도모하다, 계획하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1042/"},"藤":{"id":1031,"char":"藤","hun":"등나무 등","meaning":"“등나무 등”. 등나무","on":"トウ","kun":"ふじ","explanation":["藤 = 艹 + 月 + 龹 + 氺。","「艹」는 “풀”을 뜻합니다.","「月」는 “고기”를 뜻합니다.","龹는 여기서는 「关」가 변형된 것으로, “웃음”을 뜻합니다.","氺는 「水」가 변형된 것으로, “물”을 뜻합니다.","藤는 “등나무 덩굴(艹) 아래서 고기(月)와 술(氺)을 먹으며 웃고 떠들다(龹)” -> “등나무”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1043/"},"沢":{"id":1032,"char":"沢","hun":"못 택","meaning":"“못 택”. 못, 윤기, 윤택하다","on":"タク","kun":"さわ","explanation":["沢 = 氵 + 尺。","「氵」는 “물”을 뜻합니다.","尺는 여기서는 “얕은 못”을 그린 모양자입니다.","沢는 “물(氵)이 고여있는 얕은 못(尺)” -> “못” -> “윤기, 윤택하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1044/"},"裁":{"id":1033,"char":"裁","hun":"옷 마를 재","meaning":"“옷 마를 재”. 재단하다, 판가름하다","on":"サイ","kun":"た(つ)、さば(く)","explanation":["裁 = 𢦏 + 衣。","(소리부 겸 의미부) 「𢦏」(サイ)는 “화려한 의장용 창”을 뜻하는 글자입니다(링크 참조).","(의미부) 「衣」는 “옷”을 뜻합니다.","裁는 “의장용 창(𢦏)과 함께 입을 제복(衣)을 재단하다” -> “재단하다”라는 뜻의 글자입니다.","(𢦏는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1045/"},"証":{"id":1034,"char":"証","hun":"증거 증","meaning":"“증거 증”. 증명, 증거","on":"ショウ","kun":"","explanation":["証 = 言 + 正。","(의미부) 「言」는 “말하다”라는 뜻입니다.","(소리부 겸 의미부) 「正」(ショウ)는 “바르다”라는 뜻입니다.","証는 “바른대로(正) 말하다(言)” -> “증명, 증거”라는 뜻의 글자입니다.","(正는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1046/"},"援":{"id":1035,"char":"援","hun":"도울 원","meaning":"“도울 원”. 돕다","on":"エン","kun":"","explanation":["援 = 扌 + 爰。","「扌」는 “손”을 뜻합니다.","「爰」는 “여유롭다, 한가롭다”라는 뜻입니다.","援는 “스스로가 여유로워(爰) 남에게 도움의 손길(扌)을 내밀다” -> “돕다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1047/"},"施":{"id":1036,"char":"施","hun":"베풀 시","meaning":"“베풀 시”. 베풀다, 행하다","on":"シ、セ","kun":"ほどこ(す)","explanation":["施 = 𭤨 + 也。","「𭤨」는 “바람에 나부끼는 깃발”을 그린 것입니다.","也는 여기서는 「地」가 축약된 것으로, “땅”을 뜻합니다.","施는 “깃발을 들고(𭤨) 각지(地)를 돌아다니며 자선을 베푸는 승려들” -> “베풀다, 행하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1048/"},"井":{"id":1037,"char":"井","hun":"우물 정","meaning":"“우물 정”. 우물","on":"セイ、ショウ","kun":"い","explanation":["井는 “우물”을 본따 그린 상형문자입니다."],"sourceUrl":"https://nihongokanji.com/1049/"},"護":{"id":1038,"char":"護","hun":"도울 호","meaning":"“도울 호”. 보호하다","on":"ゴ","kun":"","explanation":["護 = 言 + 艹 + 隹 + 又。","「言」는 “말하다”라는 뜻입니다.","「艹」는 “풀”을 뜻합니다.","「隹」는 “새”를 뜻합니다.","「又」는 “손”을 뜻합니다.","護는 “풀숲(艹)에 쓰러져있는 다친 새(隹)를 구해서(又) 다시 지저귈(言)수 있도록 보살펴주다” -> “보호하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1050/"},"態":{"id":1039,"char":"態","hun":"모습 태","meaning":"“모습 태”. 모습, 형태, 상태","on":"タイ","kun":"","explanation":["態 = 能 + 心。","「能」는 본래 “곰”을 그린 글자입니다(링크 참조).","「心」는 “마음”을 뜻합니다.","態는 “마음(心)속에 떠올린 곰(能)의 모습” -> “모습, 형태, 상태”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1051/"},"鮮":{"id":1040,"char":"鮮","hun":"고울 선","meaning":"“고울 선”. 신선한, 선명한","on":"セン","kun":"あざ(やか)","explanation":["鮮 = 魚 + 羊。","「魚」는 “물고기”를 뜻합니다.","「羊」는 “양”을 뜻합니다.","鮮는 “신선한 생선(魚)과 양고기(羊)” -> “신선하다, 선명하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1052/"},"視":{"id":1041,"char":"視","hun":"볼 시","meaning":"“볼 시”. 보다, 살펴보다","on":"シ","kun":"","explanation":["視 = 礻 + 見。","「礻」는 “신, 종교, 고대의 비석”을 뜻합니다.","「見」는 “보다”라는 뜻입니다.","視는 “신들(礻)께서 내려다보시다(見)” -> “보다, 살펴보다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1053/"},"幹":{"id":1042,"char":"幹","hun":"줄기 간","meaning":"“줄기 간”. 줄기, 주요 부분","on":"カン","kun":"みき","explanation":["幹 = 𠦝 + 𠆢 + 干。","(의미부) 「𠦝」는 “떠오르는 아침해”를 그린 글자입니다.","(소리부 겸 의미부) 「干」(カン)은 여기서는 “(줄기식물의) 지지대”를 그린 모양자로 쓰인 것입니다.","(의미부) 𠆢는 여기서는 “(지지대 위에 자라난) 줄기식물”을 그린 모양자입니다.","幹는 “햇빛(𠦝)을 받으며 지지대(干)를 타고 자라나는 줄기식물(𠆢)“을 그린 글자입니다.","토마토 등의 줄기식물은 지지대 없이는 줄기를 지탱할 수 없는 식물입니다.","“줄기식물을 지탱해주는 중요한 지지대” -> “줄기, 주요 부분”이라는 의미입니다.","(干는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1054/"},"宮":{"id":1043,"char":"宮","hun":"집 궁","meaning":"“집 궁”. 궁전, 궁궐","on":"キュウ、グウ、ク","kun":"みや","explanation":["宮 = 宀 + 呂。","「宀」는 “집”을 뜻합니다.","「呂」는 “여러 채의 집이 이어진 대저택”을 뜻합니다.","宮는 “여러 채의 건물(呂)로 된 거대한 집(宀)” -> “궁궐”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1055/"},"衛":{"id":1044,"char":"衛","hun":"지킬 위","meaning":"“지킬 위”. 지키다, 방비하다","on":"エイ","kun":"","explanation":["衛 = 行 + 韋。","「行」는 본래 “사거리”를 그린 글자입니다(링크 참조).","「韋」는 “성 주위를 돌며 경계서는 발들”을 그린 글자입니다.","衛는 “거리(行)를 돌며 보초를 서다(韋)” -> “지키다, 방비하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1056/"},"監":{"id":1045,"char":"監","hun":"볼 감","meaning":"“볼 감”. 감독하다, 감시하다","on":"カン","kun":"","explanation":["監 = 臣 + 𠂉 + 一 + 皿。","「臣」는 본래 “눈동자”를 그린 글자입니다(링크 참조).","𠂉+一는 여기서는 “눈썹(𠂉)과 눈(一)“을 그린 모양자입니다.","「皿」는 “그릇”을 뜻합니다.","監는 “그릇(皿)을 내려다보는 눈(𠂉+一+臣)” -> “내려다보다” -> “감독하다, 감시하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1057/"},"審":{"id":1046,"char":"審","hun":"살필 심","meaning":"“살필 심”. 심사하다, 자세히 조사하다","on":"シン","kun":"","explanation":["審 = 宀 + 番。","「宀」는 “집”을 뜻합니다.","「番」는 “차례”를 뜻합니다.","審는 “관청(宀)에서 허가 심사 차례(番)를 기다리다” -> “심사하다, 자세히 조사하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1058/"},"義":{"id":1047,"char":"義","hun":"옳을 의","meaning":"“옳을 의”. 의, 도리","on":"ギ","kun":"","explanation":["義 = 𦍌 + 扌 + 戈。","「𦍌」는 “양”을 뜻합니다.","「扌」는 “손”을 뜻합니다.","「戈」는 “창”을 뜻합니다.","義는 “손(扌)에 창(戈)을 들고 양(𦍌)을 지키다” -> “옳다, 의롭다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1059/"},"訴":{"id":1048,"char":"訴","hun":"호소할 소","meaning":"“호소할 소”. 호소하다, 하소연하다","on":"ソ","kun":"うった(える)","explanation":["訴 = 言 + 斤 + 丶。","「言」는 “말하다”라는 뜻입니다.","「斤」는 “도끼”를 뜻합니다.","丶는 여기서는 “(도끼에) 베인 자국”을 그린 모양자입니다.","訴는 “이유없이 도끼(斤)로 공격당하고(丶) 억울함을 호소하다(言)” -> “호소하다, 하소연하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1060/"},"株":{"id":1049,"char":"株","hun":"그루 주","meaning":"“그루 주”. 그루, 그루터기, 주식","on":"","kun":"かぶ","explanation":["株 = 木 + 朱。","(의미부) 「木」는 “나무”를 뜻합니다.","(소리부) 朱(シュ – “붉을 주”)는 “주홍색”을 뜻하는 상용한자입니다.","다만 여기서는 소리부의 역할만 하고 있습니다.","(株의 정식 음독은 없으나, 본래의 음독은 シュ입니다.)","株는 “잘려나간 나무(木)의 밑동” -> “그루, 그루터기”라는 뜻의 글자입니다(朱는 소리부)."],"sourceUrl":"https://nihongokanji.com/1061/"},"姿":{"id":1050,"char":"姿","hun":"모양 자","meaning":"“모양 자”. 모양, 자세, 자태, 맵시","on":"シ","kun":"すがた","explanation":["姿 = 次 + 女。","「次」는 “다음, 두 번째”를 뜻합니다.","「女」는 “여자”를 뜻합니다.","姿는 “교양이 부족한 둘째(次) 딸(女)에게 여자다운 자세를 가르치다” -> “자세, 자태, 모양, 맵시”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1062/"},"閣":{"id":1051,"char":"閣","hun":"집 각","meaning":"“집 각”. 전각, 누각, 복층 건물","on":"カク","kun":"","explanation":["閣 = 門 + 各。","(의미부) 「門」는 “문”을 뜻합니다.","(소리부 겸 의미부) 「各」(カク)는 “각자, 각각”을 뜻합니다.","閣는 “층층마다 각각(各) 문(門)이 따로 있는 건물” -> “전각, 누각, 복층 건물”이라는 뜻의 글자입니다.","(各는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1063/"},"衆":{"id":1052,"char":"衆","hun":"무리 중","meaning":"“무리 중”. 무리, 군중, 대중","on":"シュウ、シュ","kun":"","explanation":["衆 = 血 + 乑。","「血」는 “피”를 뜻합니다.","乑는 여기서는 「人」 세 개를 합쳐 놓은 글자로, “여러 명의 사람(人)”이라는 뜻입니다.","衆는 “피를 흘리며(血) 열심히 일하는 노비들(乑)” -> “군중, 무리, 대중”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1064/"},"影":{"id":1053,"char":"影","hun":"그림자 영","meaning":"“그림자 영”. 그림자","on":"エイ","kun":"かげ","explanation":["影 = 景 + 彡。","「景」는 “경치, 풍경”을 뜻합니다.","彡는 여기서는 “햇빛”을 그린 모양자입니다.","햇빛이 비치면 반드시 그림자가 생기게 됩니다.","影는 “풍경(景)에 햇빛(彡)이 비쳐 생긴 그림자” -> “그림자”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1065/"},"松":{"id":1054,"char":"松","hun":"소나무 송","meaning":"“소나무 송”. 소나무","on":"ショウ","kun":"まつ","explanation":["松 = 木 + 公。","「木」는 “나무”를 뜻합니다.","「公」는 “공정하다”라는 뜻입니다.","소나무의 곧게 뻗은 잎은 “공정함”을 연상시키곤 합니다.","松는 “공정한(公) 나무(木)” -> “소나무”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1066/"},"撃":{"id":1055,"char":"撃","hun":"칠 격","meaning":"“칠 격”. 때리다, 공격하다, 무력을 가하다","on":"ゲキ","kun":"う(つ)","explanation":["撃 = 車 + 殳 + 手。","「車」는 “수레, 차”를 뜻합니다.","「殳」는 “때리다, 휘두르다”라는 뜻입니다.","「手」는 “손”을 뜻합니다.","撃는 “손(手)을 마구 휘둘러(殳) 수레(車)를 때려부수다” -> “때리다, 공격하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1067/"},"佐":{"id":1056,"char":"佐","hun":"도울 좌","meaning":"“도울 좌”. 돕다, 보좌하다","on":"サ","kun":"","explanation":["佐 = 亻 + 左。","(의미부) 「亻」는 “사람”을 뜻합니다.","(소리부 겸 의미부) 「左」(サ)는 “왼쪽”을 뜻합니다.","佐는 “높은 사람의 왼쪽(左)에 서서 그를 보좌하는 보좌관(亻)” -> “돕다, 보좌하다”라는 뜻의 글자입니다.","(左는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1068/"},"核":{"id":1057,"char":"核","hun":"씨 핵","meaning":"“씨 핵”. 핵심, 핵, 중심","on":"カク","kun":"","explanation":["核 = 木 + 亥。","「木」는 “나무”를 뜻합니다.","「亥」는 “뼈만 남은 돼지”를 그린 글자입니다.","核는 “알맹이(亥)만 남은 나무열매(木)” -> “알맹이” -> “핵심, 핵, 중심”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1069/"},"融":{"id":1058,"char":"融","hun":"녹을 융","meaning":"“녹을 융”. 녹다, 녹이다, 화합하다","on":"ユウ","kun":"","explanation":["融 = 鬲 + 虫。","鬲는 “화로 위의 냄비(𠮛)”를 그린 모양자입니다.","「虫」는 “벌레”를 뜻합니다.","融는 “펄펄 끓는 냄비(鬲)에 멋모르고 들어가 녹아버린 벌레(虫)” -> “녹다, 녹이다, 화합하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1070/"},"票":{"id":1059,"char":"票","hun":"표 표","meaning":"“표 표”. 표, 쪽지, 증표, 투표","on":"ヒョウ","kun":"","explanation":["票 = 覀 + 示。","「示」는 “고대의 비석”을 뜻합니다.","覀는 여기서는 “(이름을 적어둔) 위패”를 그린 모양자입니다.","票는 “비석(示) 위에 놓아둔 작은 위패(覀)” -> “표, 쪽지”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1071/"},"渉":{"id":1060,"char":"渉","hun":"건널 섭","meaning":"“건널 섭”. 건너다, 관계하다, 상관하다","on":"ショウ","kun":"","explanation":["渉 = 氵 + 歩。","「氵」는 “물”을 뜻합니다.","「歩」는 “걷다”라는 뜻입니다.","渉는 “강(氵) 반대편까지 건너와서(歩) 끼어들다” -> “건너다, 관계하다, 상관하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1072/"},"響":{"id":1061,"char":"響","hun":"울릴 향","meaning":"“울릴 향”. 울리다, 공명하다, 메아리치다","on":"キョウ","kun":"ひび(く)","explanation":["響 = 郷 + 音。","(소리부 겸 의미부) 郷(キョウ – “시골 향”)은 “정답게 이야기를 나누는 사람들”을 그린 상용한자입니다.","(의미부) 「音」는 “소리”를 뜻합니다.","響는 “정겹게 대화를 나누는(郷) 소리(音)가 울려퍼지다” -> “울리다, 메아리치다”라는 뜻의 글자입니다.","(郷는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1073/"},"推":{"id":1062,"char":"推","hun":"밀 추","meaning":"“밀 추”. 밀다, 추측하다, 추천하다","on":"スイ","kun":"お(す)","explanation":["推 = 扌 + 隹。","「扌」는 “손”을 뜻합니다.","「隹」는 “새”를 뜻합니다.","새는 앞으로밖에 걸어갈 수 없다는 특징이 있습니다.","推는 “새(隹)를 앞으로 밀다(扌)”라는 뜻입니다.","“밀다” -> “(미루어) 추측하다”","“밀다” -> “추천하다”","라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/1074/"},"請":{"id":1063,"char":"請","hun":"청할 청","meaning":"“청할 청”. 청원하다, 부탁하다","on":"セイ、シン","kun":"こ(う)、う(ける)","explanation":["請 = 言 + 青。","(의미부) 「言」는 “말하다”라는 뜻입니다.","(소리부 겸 의미부) 「青」(セイ)는 “푸르다”라는 뜻입니다.","請는 “정중하게(青) 말하다(言)” -> “청원하다, 부탁하다”라는 뜻의 글자입니다.","(青는 소리부(セイ -> セイ・シン)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1075/"},"士":{"id":1064,"char":"士","hun":"선비 사","meaning":"“선비 사”. 선비, 무사","on":"シ","kun":"","explanation":["士는 “고대의 무사들이 허리에 차고 다니던 무기”를 그린 상형문자입니다.","“무사를 상징하는 무기” -> “무사, 선비”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/1076/"},"討":{"id":1065,"char":"討","hun":"칠 토","meaning":"“칠 토”. 따져 묻다, 공격하다","on":"トウ","kun":"う(つ)","explanation":["討 = 言 + 寸。","「言」는 “말하다”라는 뜻입니다.","「寸」는 “손”을 뜻합니다.","討는 “말(言)로 때리다(寸)” -> “따져 묻다, 공격하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1077/"},"攻":{"id":1066,"char":"攻","hun":"칠 공","meaning":"“칠 공”. 공격하다","on":"コウ","kun":"せ(める)","explanation":["攻 = 工 + 攵。","(소리부 겸 의미부) 「工」(コウ)는 “공작, 가공, 공정”을 뜻합니다.","(의미부) 「攵」는 “때리다, 치다”라는 뜻입니다.","攻는 “공구(工)로 때리다(攵)” -> “공격하다”라는 뜻의 글자입니다.","(工는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1078/"},"崎":{"id":1067,"char":"崎","hun":"험할 기","meaning":"“험할 기”. (지명에 쓰이는 한자)","on":"","kun":"さき","explanation":["崎는 본래는 “곶”을 뜻하는 한자로, “산(山)”과 소리부(奇 – キ)가 합쳐져서 만들어진 글자입니다.","“산” -> “험한 지형” -> “곶”이라는 의미입니다.","그러나 이 한자는 실생활에서는 거의 지명의 일부로만 쓰이는 글자입니다.","(이 한자가 상용한자에 포함된 이유는, 일본 초등교육과정의 목표 중 하나가 “47도도부현의 지명을 전부 읽을 수 있게 되는 것”이기 때문입니다.)"],"sourceUrl":"https://nihongokanji.com/1079/"},"督":{"id":1068,"char":"督","hun":"감독할 독","meaning":"“감독할 독”. 감독하다, 지켜보다","on":"トク","kun":"","explanation":["督 = 尗 + 又 + 目。","「尗」는 “식물의 줄기와 뿌리”를 그린 글자입니다(링크 참조).","「又」는 “손”을 뜻합니다.","「目」는 “눈”을 뜻합니다.","督는 “땅에 심어놓은 식물(尗)이 잘 자라도록 관리해주며(又) 지켜보다(目)” -> “감독하다, 지켜보다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1080/"},"催":{"id":1069,"char":"催","hun":"재촉할 최","meaning":"“재촉할 최”. 재촉하다, 개최하다","on":"サイ","kun":"もよお(す)","explanation":["催 = 亻 + 山 + 隹。","「亻」는 “사람”을 뜻합니다.","「山」는 “산”을 뜻합니다.","「隹」는 “새”를 뜻합니다.","催는,","“사냥꾼(亻)이 산(山)에서 새(隹)를 잡아 회식을 열다” -> “개최하다”","“새고기가 식욕을 불러일으키다” -> “재촉하다”","라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1081/"},"及":{"id":1070,"char":"及","hun":"미칠 급","meaning":"“미칠 급”. 미치다, 이르다","on":"キュウ","kun":"およ(ぶ)、およ(ぼす)、およ(び)","explanation":["及 = 人 + 又。","「人」는 “사람”을 뜻합니다.","「又」는 “손”을 뜻합니다.","及는 “사람(人)을 붙잡다(又)” -> “손이 닿다” -> “이르다, 미치다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1082/"},"憲":{"id":1071,"char":"憲","hun":"법 헌","meaning":"“법 헌”. 헌법","on":"ケン","kun":"","explanation":["憲 = 宀 + 龶 + 罒 + 心。","「宀」는 “집”을 뜻합니다.","龶는 여기서는 “날카로운 흉기”를 그린 모양자입니다.","「罒」는 “그물”을 뜻합니다.","「心」는 “마음”을 뜻합니다.","憲는 “사람들의 마음(心)을 옭아매고(罒) 폭력으로 협박해(龶) 굴복시키는 국가의(宀) 법규” -> “헌법”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1083/"},"離":{"id":1072,"char":"離","hun":"떠날 리","meaning":"“떠날 리”. 떨어지다, 분리되다","on":"リ","kun":"はな(れる)、はな(す)","explanation":["離 = 离 + 隹。","离는 “덫에 걸린 동물”을 그린 모양자입니다.","(윗부분의 㐫는 “짐승의 머리”를 그린 것이고, 아래쪽의 禸는 “덫(冂)에 걸린 다리(厶)”를 그린 것입니다.)","「隹」는 “새”를 뜻합니다.","離는 “덫(离)에서 빠져나와 달아나는 새(隹)” -> “떨어지다, 분리되다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1084/"},"激":{"id":1073,"char":"激","hun":"격할 격","meaning":"“격할 격”. 격렬하다, 거세다","on":"ゲキ","kun":"はげ(しい)","explanation":["激 = 氵 + 白 + 方 + 攵。","「氵」는 “물”을 뜻합니다.","「白」는 “흰색”을 뜻합니다.","「方」는 “방향”을 뜻합니다.","「攵」는 “때리다, 치다”라는 뜻입니다.","激는 “거센 급류(氵)가 휘몰아쳐(攵) 사방에(方) 하얀 거품(白)이 일다” -> “격렬한, 거센”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1085/"},"摘":{"id":1074,"char":"摘","hun":"딸 적","meaning":"“딸 적”. 집어내다, 따다, 들추어내다, 폭로하다","on":"テキ","kun":"つ(む)","explanation":["摘 = 扌 + 啇。","(의미부) 「扌」는 “손”을 뜻합니다.","(소리부 겸 의미부) 「啇」(テキ)는 “화초를 심은 화분”을 그린 글자입니다.","摘는 “화초(啇)에 붙은 벌레를 집어내다(扌)” -> “집어내다, 따다, 들추다, 폭로하다”라는 뜻의 글자입니다.","(啇는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1086/"},"系":{"id":1075,"char":"系","hun":"이어맬 계","meaning":"“이어맬 계”. 계통, 분류","on":"ケイ","kun":"","explanation":["系 = 一 + 糸。","「一」는 “1”을 뜻합니다.","「糸」는 “실”을 뜻합니다.","系는 “하나로(一) 이어지는(糸) 계통” -> “계통, 분류”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1087/"},"郎":{"id":1076,"char":"郎","hun":"사내 랑","meaning":"“사내 랑”. 젊은 남성","on":"ロウ","kun":"","explanation":["郎 = 良 + ⻏。","「良」는 “좋다”라는 뜻입니다.","「⻏」는 “도시”를 뜻합니다.","郎는 “도시(⻏)의 좋은(良) 신랑감” -> “젊은 남성”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1088/"},"盟":{"id":1077,"char":"盟","hun":"맹세 맹","meaning":"“맹세 맹”. 맹세하다","on":"メイ","kun":"","explanation":["盟 = 明 + 皿。","(소리부 겸 의미부) 「明」(メイ)는 “밝다”라는 뜻입니다.","(의미부) 「皿」는 “그릇”을 뜻합니다.","옛날 중국에서는 동맹을 맺을 때 술잔을 나누며 의식을 치렀다고 합니다.","盟는 “밝은 달(明) 아래에서 술잔을(皿) 나누며 맹세하다” -> “맹세하다”라는 뜻의 글자입니다.","(明는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1089/"},"従":{"id":1078,"char":"従","hun":"좇을 종","meaning":"“좇을 종”. 따르다, 복종하다","on":"ジュウ、ショウ、ジュ","kun":"したが(う)、したが(える)","explanation":["従 = 彳 + 䒑 + 止。","「彳」는 “길”을 뜻합니다.","䒑는 여기서는 “발자국”을 그린 모양자입니다.","「止」는 “발”을 뜻합니다.","従는 “길(彳)에 남아있는 앞사람의 발자국(䒑)을 따라가다(止)” -> “따르다, 복종하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1090/"},"隊":{"id":1079,"char":"隊","hun":"무리 대","meaning":"“무리 대”. 조직, 무리","on":"タイ","kun":"","explanation":["隊 = ⻖ + 丷 + 豕。","「⻖」는 “언덕, 산”을 뜻합니다.","丷는 여기서는 “수풀”을 그린 모양자입니다.","「豕」는 “돼지”를 뜻합니다.","隊는 “산속(⻖)의 수풀(丷) 사이로 몰려다니는 멧돼지(豕) 무리” -> “무리, 조직, 떼”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1091/"},"織":{"id":1080,"char":"織","hun":"짤 직","meaning":"“짤 직”. 짜다, 조직하다","on":"ショク、シキ","kun":"お(る)","explanation":["織 = 糸 + 戠。","(의미부) 「糸」는 “실”을 뜻합니다.","(소리부 겸 의미부) 戠는 여기서는 「職」(ショク)가 축약된 것으로, “일, 직업”을 뜻합니다.","織는 “실(糸)을 짜는 일(職)” -> “(직물을) 짜다, 조직하다”라는 뜻의 글자입니다.","(戠->職는 소리부(ショク -> ショク・シキ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1092/"},"振":{"id":1081,"char":"振","hun":"떨칠 진","meaning":"“떨칠 진”. 흔들다","on":"シン","kun":"ふ(る)、ふ(るう)、ふ(れる)","explanation":["振 = 扌 + 辰。","(의미부) 「扌」는 “손”을 뜻합니다.","(소리부 겸 의미부) 「辰」(シン)은 “쟁기, 농기구”를 뜻합니다.","振는 “쟁기(辰)를 손에 들고(扌) 휘두르다” -> “흔들다”라는 뜻의 글자입니다.","(辰는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1093/"},"弁":{"id":1082,"char":"弁","hun":"말씀 변","meaning":"“말씀 변”. 변론하다, 말하다","on":"ベン","kun":"","explanation":["弁 = 厶 + 廾。","「厶」는 “팔을 안으로 굽힌 모습”을 그린 글자입니다.","廾는 여기서는 “두 손을 들어올린 모습”을 그린 모양자입니다.","弁는 “팔을 들었다(廾) 굽혔다(厶) 하며 열변을 토하다” -> “변론하다, 말하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1094/"},"就":{"id":1083,"char":"就","hun":"나아갈 취","meaning":"“나아갈 취”. 따라가다, 취임하다, 이루다","on":"シュウ、ジュ","kun":"つ(く)、つ(ける)","explanation":["就 = 京 + 尤。","「京」는 “수도”를 뜻합니다.","尤는 여기서는 “짐을 메고 걷는 사람”을 그린 모양자입니다.","就는 “짐을 싸들고(尤) 수도로(京) 상경해 일을 시작하다” -> “따라가다, 취임하다, 이루다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1095/"},"献":{"id":1084,"char":"献","hun":"바칠 헌","meaning":"“바칠 헌”. 바치다, 드리다","on":"ケン、コン","kun":"","explanation":["献 = 南 + 犬。","「南」는 “남쪽”을 뜻합니다.","「犬」는 “개”를 뜻합니다.","献는 “남쪽(南)을 향해 제사를 지내며 동물(犬)을 공양하다” -> “바치다, 드리다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1096/"},"厳":{"id":1085,"char":"厳","hun":"엄할 엄","meaning":"“엄할 엄”. 엄한, 엄숙한","on":"ゲン、ゴン","kun":"おごそ(か)、きび(しい)","explanation":["厳 = ⺍ + 厂 + 丅 + 耳 + 攵。","⺍+厂는 여기서는 「⺍＋冖」가 변형된 것으로, “불이 환하게 켜진 집”을 뜻합니다.","「耳」는 “귀”를 뜻합니다.","丅는 여기서는 “(귀로 들어오는) 잔소리”를 표현한 모양자입니다.","「攵」는 “때리다, 치다”라는 뜻입니다.","厳는 “늦은 밤에(⺍+厂) 아이를 훈계하며(丅+耳) 회초리로 때리다(攵)” -> “엄한, 엄숙한”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1097/"},"維":{"id":1086,"char":"維","hun":"벼리 유","meaning":"“벼리 유”. 잇다, 유지하다","on":"イ","kun":"","explanation":["維 = 糸 + 隹。","「糸」는 “실”을 뜻합니다.","「隹」는 “새”를 뜻합니다.","維는 “새(隹)가 날아가지 못하도록 실(糸)로 묶어두다” -> “잇다, 유지하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1098/"},"浜":{"id":1087,"char":"浜","hun":"물가 빈","meaning":"“물가 빈”. 물가, 해변","on":"ヒン","kun":"はま","explanation":["浜 = 氵 + 兵。","「氵」는 “물”을 뜻합니다.","「兵」는 “병사”를 뜻합니다.","浜는 “바닷가(氵)에 늘어서있는 수군(兵)들” -> “물가, 해변”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1099/"},"遺":{"id":1088,"char":"遺","hun":"남길 유","meaning":"“남길 유”. (사후에) 남기다, 잃어버리다","on":"イ、ユイ","kun":"","explanation":["遺 = ⻌ + 𠀐 + 貝。","「⻌」는 “길”을 뜻합니다.","𠀐는 여기서는 「上」가 변형된 것으로, “높다”라는 뜻입니다.","「貝」는 “돈, 재물”을 뜻합니다.","遺는 “길(⻌)에 상등품(𠀐)의 재보(貝)를 떨어뜨리다” -> “남기다, 잃어버리다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1100/"},"塁":{"id":1089,"char":"塁","hun":"보루 루","meaning":"“보루 루”. 성채, 베이스(야구)","on":"ルイ","kun":"","explanation":["塁 = 田 + 冫 + 冫 + 土。","塁는 본래 “흙(土)으로 쌓아올린 작은 성”을 그린 상형문자입니다.","그러나 현재는 본래의 의미로는 거의 쓰이지 않고, “야구의 베이스(1루, 2루, 3루)”를 뜻하는 글자로서만 쓰이고 있습니다.","(田는 투수, 중간의 冫+冫는 1루/2루/3루/홈, 土는 타자를 각각 그린 것으로 기억하시면 됩니다.)"],"sourceUrl":"https://nihongokanji.com/1101/"},"邦":{"id":1090,"char":"邦","hun":"나라 방","meaning":"“나라 방”. 국가, 나라","on":"ホウ","kun":"","explanation":["邦 = 丰 + ⻏。","丰는 여기서는 「手」가 변형된 것으로, “손”을 뜻합니다.","「⻏」는 “도시”를 뜻합니다.","邦는 “모두의 손(手)으로 쌓아올린 대도시(⻏)” -> “나라, 국가”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1102/"},"素":{"id":1091,"char":"素","hun":"본디 소","meaning":"“본디 소”. 꾸밈없는, 그대로의, 본래의, 원초적인","on":"ソ、ス","kun":"","explanation":["素 = 龶 + 糸。","龶는 여기서는 “돌돌 말린 누에고치”를 그린 모양자입니다.","「糸」는 “실”을 뜻합니다.","素는 “누에고치(龶)에서 갓 뽑은 실(糸)” -> “본래의, 원초적인, 그대로의”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1103/"},"遣":{"id":1092,"char":"遣","hun":"보낼 견","meaning":"“보낼 견”. 보내다, 파견하다","on":"ケン","kun":"つか(う)、つか(わす)","explanation":["遣 = ⻌ + 𠀐 + 㠯。","⻌+𠀐는 여기서는 「遺」가 축약된 것으로, “잃어버리다”라는 뜻입니다.","㠯는 여기서는 「官」가 축약된 것으로, “관리, 벼슬아치”를 뜻합니다.","遣는 “왕이 잃어버린(遺) 물건을 되찾기 위해 관리(官)를 파견하다” -> “보내다, 파견하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1104/"},"抗":{"id":1093,"char":"抗","hun":"겨룰 항","meaning":"“겨룰 항”. 항거하다, 대항하다","on":"コウ","kun":"","explanation":["抗 = 扌 + 亢。","(의미부) 「扌」는 “손”을 뜻합니다.","(소리부 겸 의미부) 「亢」(コウ)는 “오르다”라는 뜻입니다.","抗는 “높은 곳으로 올라가(亢) 적군을 막아내다(扌)” -> “항거하다, 대항하다”라는 뜻의 글자입니다.","(亢는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1105/"},"模":{"id":1094,"char":"模","hun":"본뜰 모","meaning":"“본뜰 모”. 모형, 본, 무늬","on":"モ、ボ","kun":"","explanation":["模 = 木 + 莫。","(의미부) 「木」는 “나무”를 뜻합니다.","(소리부 겸 의미부) 「莫」(ボ)는 “없다”라는 뜻입니다.","模는 “원본이 없을(莫) 때 쓰는, 나무(木)로 만든 모형” -> “모형, 본”이라는 뜻의 글자입니다.","(莫는 소리부(ボ -> モ・ボ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1106/"},"雄":{"id":1095,"char":"雄","hun":"수컷 웅","meaning":"“수컷 웅”. 수컷, 남자다운, 굳센, 힘찬","on":"ユウ","kun":"お、おす","explanation":["雄 = 厷 + 隹。","厷는 「広」가 살짝 변형된 것으로, “넓다”라는 뜻입니다.","「隹」는 “새”를 뜻합니다.","雄는 본래 “수컷 새(隹)”를 뜻하던 글자입니다.","“몸통이 넓은(広) 새(隹)” -> “수컷 새” -> “수컷, 남자다운, 굳센, 힘찬”이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/1107/"},"益":{"id":1096,"char":"益","hun":"더할 익","meaning":"“더할 익”. 이익, 유익하다","on":"エキ、ヤク","kun":"","explanation":["益 = 丷 + 一 + ハ + 皿。","「皿」는 “그릇, 접시”를 뜻합니다.","丷+一+ハ는 여기서는 “그릇(皿)에서 넘쳐흐르는 물”을 그린 모양자입니다.","益는 “그릇(皿)에서 물이 넘쳐흐르다(丷+一+ハ)” -> “넘치다” -> “이익, 유익”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1108/"},"緊":{"id":1097,"char":"緊","hun":"긴할 긴","meaning":"“긴할 긴”. 긴박하다, 시급하다, 세게 조르다","on":"キン","kun":"","explanation":["緊 = 臣 + 又 + 糸。","「臣」는 “신하”를 뜻합니다.","「又」는 “손”을 뜻합니다.","「糸」는 “줄”을 뜻합니다.","緊는 “신하(臣)가 왕을 뵙기 전 갓끈(糸)을 단단히 동여매다(又)” -> “긴박하다, 시급하다, 세게 조르다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1109/"},"宣":{"id":1098,"char":"宣","hun":"베풀 선","meaning":"“베풀 선”. 널리 퍼지다, 선언하다, 퍼뜨리다","on":"セン","kun":"","explanation":["宣 = 宀 + 亘。","「宀」는 “집”을 뜻합니다.","亘는 “하늘(一)과 땅(一) 사이의 태양(日)” -> “천지”라는 뜻의 글자입니다.","宣는 “황궁(宀)에서 반포한 칙명이 천지(亘)로 퍼져나가다” -> “널리 퍼지다, 선언하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1110/"},"昭":{"id":1099,"char":"昭","hun":"밝을 소","meaning":"“밝을 소”. 밝다 (일본 연호에 쓰이는 글자)","on":"ショウ","kun":"","explanation":["昭 = 日 + 召。","(의미부) 「日」는 “태양”을 뜻합니다.","(소리부 겸 의미부) 「召」(ショウ)는 “부르다”라는 뜻입니다.","昭는 “햇빛(日)을 불러들이다(召)” -> “밝다”라는 뜻의 글자입니다.","다만, 이 한자는 실제로는 일본의 연호(쇼와)를 지칭할 때에만 쓰이는 글자로, 그 외에는 거의 쓰이지 않습니다."],"sourceUrl":"https://nihongokanji.com/1111/"},"廃":{"id":1100,"char":"廃","hun":"폐할/버릴 폐","meaning":"“폐할/버릴 폐”. 버리다, 폐기하다, 쇠퇴하다","on":"ハイ","kun":"すた(れる)、すた(る)","explanation":["廃 = 广 + 発。","「广」는 “건물, 집”을 뜻합니다.","「発」는 “쏘다, 발사하다”라는 뜻입니다.","廃는 “집(广)을 버리고 뛰쳐나오다(発)” -> “버리다, 폐기하다, 쇠퇴하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1112/"},"江":{"id":1101,"char":"江","hun":"강 강","meaning":"“강 강”. 강","on":"コウ","kun":"え","explanation":["江 = 氵 + 工。","(의미부) 「氵」는 “물”을 뜻합니다.","(소리부) 「工」(コウ)는 여기서는 소리부의 역할만 하고 있습니다.","江는 “물길(氵)” -> “강”이라는 뜻의 글자입니다(工는 소리부)."],"sourceUrl":"https://nihongokanji.com/1113/"},"僚":{"id":1102,"char":"僚","hun":"동료 료","meaning":"“동료 료”. 친구, 동료, 관료","on":"リョウ","kun":"","explanation":["僚 = 亻 + 尞。","(의미부) 「亻」는 “사람”을 뜻합니다.","(소리부 겸 의미부) 「尞」(リョウ)는 “횃불”을 그린 글자입니다.","僚는 “내가 어려울 때 옆에서 빛을 밝혀주며(尞) 도와주는 사람(亻)” -> “친구, 동료”라는 뜻의 글자입니다.","(尞는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1114/"},"吉":{"id":1103,"char":"吉","hun":"길할 길","meaning":"“길할 길”. 길하다, 상서롭다, 운이 좋다","on":"キチ、キツ","kun":"","explanation":["吉 = 士 + 口。","「士」는 “선비”를 뜻합니다.","「口」는 “입”을 뜻합니다.","吉는 “선비(士)의 덕담(口)” -> “길하다, 상서롭다, 운이 좋다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1115/"},"盛":{"id":1104,"char":"盛","hun":"성할 성","meaning":"“성할 성”. 번성하다, 가득 쌓다","on":"セイ、ジョウ","kun":"も(る)、さか(る)、さか(ん)","explanation":["盛 = 成 + 皿。","(소리부 겸 의미부) 「成」(セイ・ジョウ)는 “이루다, 성취하다”라는 뜻입니다.","(의미부) 「皿」는 “그릇, 접시”를 뜻합니다.","盛는 “그릇(皿)에 음식을 가득 만들어(成) 쌓아놓다” -> “번성하다, 가득 쌓다”라는 뜻의 글자입니다.","(成는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1116/"},"皇":{"id":1105,"char":"皇","hun":"임금 황","meaning":"“임금 황”. 황제","on":"コウ、オウ","kun":"","explanation":["皇 = 丶 + 日 + 王。","丶는 여기서는 「一」가 축약된 것으로, “1”을 뜻합니다.","「日」는 “태양”을 뜻합니다.","「王」는 “임금, 왕”을 뜻합니다.","皇는 “왕(王)들의 위에서 태양(日)처럼 군림하는 1인자(一)” -> “황제”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1117/"},"臨":{"id":1106,"char":"臨","hun":"임할 임","meaning":"“임할 임”. 내려다보다, 임하다, 임시","on":"リン","kun":"のぞ(む)","explanation":["臨 = 臣 + 𠂉 + 品。","「臣」는 “신하”를 뜻합니다.","𠂉는 여기서는 “내려다보는 눈”을 표현한 모양자입니다.","品는 여기서는 “민가가 모여있는 마을”을 그린 모양자입니다.","臨는 “자신이 다스릴 영지(品)를 내려다보는(𠂉) 신하(臣)” -> “내려다보다, 임하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1118/"},"踏":{"id":1107,"char":"踏","hun":"밟을 답","meaning":"“밟을 답”. 밟다, 짓밟다","on":"トウ","kun":"ふ(む)、ふ(まえる)","explanation":["踏 = 足 + 水 + 日。","「足」는 “발”을 뜻합니다.","「水」는 “물”을 뜻합니다.","日는 여기서는 “(물 속의) 징검다리”를 그린 모양자입니다.","踏는 “물(水) 속의 징검다리(日)를 밟고(足) 건너가다” -> “밟다, 짓밟다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1119/"},"壊":{"id":1108,"char":"壊","hun":"무너질 괴","meaning":"“무너질 괴”. 부서지다, 파괴되다, 무너지다","on":"カイ","kun":"こわ(す)、こわ(れる)","explanation":["壊 = 土 + 十 + 罒 + 衣。","「土」는 “흙”을 뜻합니다.","十+罒는 여기서는 “눈썹(十)과 눈(罒)“을 그린 모양자입니다.","「衣」는 “옷”을 뜻합니다.","壊는 “힘들게 쌓은 흙벽(土)이 무너지는 것을 보며 옷(衣)에 눈을 파묻고(十+罒) 울다” -> “무너지다, 부서지다, 파괴되다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1120/"},"債":{"id":1109,"char":"債","hun":"빚 채","meaning":"“빚 채”. 빚, 채무","on":"サイ","kun":"","explanation":["債 = 亻 + 責。","「亻」는 “사람”을 뜻합니다.","「責」는 “책임, 꾸짖다, 책망하다”라는 뜻입니다.","債는 “빚을 독촉하는(責) 빚쟁이(亻)” -> “빚, 채무”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1121/"},"興":{"id":1110,"char":"興","hun":"일 흥","meaning":"“일 흥”. 흥하다, 부흥하다, 흥미, 흥겨움","on":"コウ、キョウ","kun":"おこ(る)、おこ(す)","explanation":["興 = 𦥑 + 一 + ハ + 同。","「同」는 “같다”라는 뜻입니다.","𦥑는 여기서는 「⺤」 두 개가 합쳐진 것으로, “손(⺤) 두 개”를 뜻합니다.","一+ハ는 여기서는 “서로 붙잡은(一) 손(ハ)”을 그린 모양자입니다.","興는 “모두 함께(同) 손(𦥑+ハ)을 잡고(一) 춤추다” -> “흥하다, 흥겨움, 흥미”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1122/"},"源":{"id":1111,"char":"源","hun":"근원 원","meaning":"“근원 원”. 원천, 원류","on":"ゲン","kun":"みなもと","explanation":["源 = 氵 + 原。","(의미부) 「氵」는 “물”을 뜻합니다.","(소리부 겸 의미부) 「原」(ゲン)는 “근원”을 뜻합니다.","源는 “물(氵)이 흘러나오는 수원지(原)” -> “원천, 원류”라는 뜻의 글자입니다.","(原는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1123/"},"儀":{"id":1112,"char":"儀","hun":"거동 의","meaning":"“거동 의”. 법도, 예법, 예식, 모형","on":"ギ","kun":"","explanation":["儀 = 亻 + 義。","(의미부) 「亻」는 “사람”을 뜻합니다.","(소리부 겸 의미부) 「義」(ギ)는 “옳다”라는 뜻입니다.","儀는 “사람(亻)이 지켜야 할 올바른(義) 예법” -> “법도, 예법, 예식, 모형”이라는 뜻의 글자입니다.","(義는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1124/"},"創":{"id":1113,"char":"創","hun":"비롯할 창","meaning":"“비롯할 창”. 창조하다, 만들다","on":"ソウ","kun":"つく(る)","explanation":["創 = 合 + 戸 + 刂。","「合」는 “합치다”라는 뜻입니다.","「戸」는 “집, 문”을 뜻합니다.","「刂」는 “칼”을 뜻합니다.","創는 “망가진 문(戸)을 떼어내 자르고(刂) 합쳐서(合) 새로운 물건을 만들다” -> “창조하다, 만들다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1125/"},"障":{"id":1114,"char":"障","hun":"막을 장","meaning":"“막을 장”. 막다, 방해하다, 거치적거리다","on":"ショウ","kun":"さわ(る)","explanation":["障 = ⻖ + 章。","(의미부) 「⻖」는 “언덕, 산”을 뜻합니다.","(소리부) 「章」(ショウ)는 여기서는 소리부(ショウ)의 역할만 하고 있습니다.","障는 “높은 산(⻖)이 앞을 가로막다” -> “막다, 방해하다, 거치적거리다”라는 뜻의 글자입니다(章는 소리부)."],"sourceUrl":"https://nihongokanji.com/1126/"},"継":{"id":1115,"char":"継","hun":"이을 계","meaning":"“이을 계”. 이어가다, 계속하다","on":"ケイ","kun":"つ(ぐ)","explanation":["継 = 糸 + 𠃊 + 米。","「糸」는 “실”을 뜻합니다.","𠃊+米는 여기서는 “실뭉치”를 그린 모양자입니다(670.「断」 모양 해설 참조).","継는 “실뭉치(𠃊+米)에서 빠져나온 실(糸)이 계속 이어지다” -> “이어가다, 계속하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1127/"},"筋":{"id":1116,"char":"筋","hun":"힘줄 근","meaning":"“힘줄 근”. 근육, 힘줄","on":"キン","kun":"すじ","explanation":["筋 = 𥫗 + 月 + 力。","「𥫗」는 “대나무”를 뜻합니다.","「月」는 “신체의 일부”를 뜻합니다.","「力」는 “힘”을 뜻합니다.","筋는 “대나무 마디(竹)처럼 잘 갈라진 신체(月)의 근육(力)” -> “근육, 힘줄”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1128/"},"闘":{"id":1117,"char":"闘","hun":"싸울 투","meaning":"“싸울 투”. 싸우다, 겨루다","on":"トウ","kun":"たたか(う)","explanation":["闘 = 門 + 豆 + 寸。","「門」는 “문”을 뜻합니다.","「豆」는 “제기그릇”을 뜻합니다.","「寸」는 “손”을 뜻합니다.","闘는 “도장(門)에서 기왓장(豆)을 격파(寸)하다” -> “싸우다, 겨루다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1129/"},"葬":{"id":1118,"char":"葬","hun":"장사지낼 장","meaning":"“장사지낼 장”. 장례치르다","on":"ソウ","kun":"ほうむ(る)","explanation":["葬 = 艹 + 死 + 廾。","「艹」는 “풀”을 뜻합니다.","「死」는 “죽다”라는 뜻입니다.","廾는 여기서는 「艹」가 변형된 것으로, “풀”을 뜻합니다.","葬는 “풀숲(艹+廾)에 죽은 사람(死)을 묻다” -> “장사지내다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1130/"},"避":{"id":1119,"char":"避","hun":"피할 피","meaning":"“피할 피”. 피하다","on":"ヒ","kun":"さ(ける)","explanation":["避 = ⻌ + 辟。","「⻌」는 “길”을 뜻합니다.","「辟」는 “피하다, 숨다”라는 뜻입니다.","避는 “길(⻌)에서 도망쳐 몸을 숨기다(辟)” -> “피하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1131/"},"逮":{"id":1120,"char":"逮","hun":"잡을 체","meaning":"“잡을 체”. 붙잡다, 체포하다","on":"タイ","kun":"","explanation":["逮 = ⻌ + 隶。","「⻌」는 “길”을 뜻합니다.","隶는 “짐승의 꼬리(氺)를 붙잡다(⺕)”라는 뜻의 글자입니다(507.「康」 모양 해설 참조).","逮는 “길(⻌)을 달려 달아나는 상대를 붙잡다(隶)” -> “붙잡다, 체포하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1132/"},"迫":{"id":1121,"char":"迫","hun":"핍박할 박","meaning":"“핍박할 박”. 다가오다, 핍박하다","on":"ハク","kun":"せま(る)","explanation":["迫 = ⻌ + 白。","(의미부) 「⻌」는 “길”을 뜻합니다.","(소리부) 「白」(ハク)는 여기서는 소리부의 역할만 하고 있습니다.","迫는 “길(⻌)에서 가까이 다가오다” -> “다가오다, 핍박하다”라는 뜻의 글자입니다(白는 소리부)."],"sourceUrl":"https://nihongokanji.com/1133/"},"惑":{"id":1122,"char":"惑","hun":"미혹할 혹","meaning":"“미혹할 혹”. 갈팡질팡하다, 미혹되다, 현혹되다","on":"ワク","kun":"まど(う)","explanation":["惑 = 戈 + 口 + 一 + 心。","「戈」는 “창”을 뜻합니다.","口+一는 여기서는 “성문”을 그린 모양자입니다.","「心」는 “마음”을 뜻합니다.","惑는 “창(戈)을 들고 성문(口+一)을 지키는 병사의 불안한 마음(心)” -> “갈팡질팡하다, 미혹되다, 현혹되다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1134/"},"崩":{"id":1123,"char":"崩","hun":"무너질 붕","meaning":"“무너질 붕”. 무너지다, 붕괴","on":"ホウ","kun":"くず(れる)、くず(す)","explanation":["崩 = 山 + 朋。","「山」는 “산”을 뜻합니다.","朋는 여기서는 “산사태로 흙이 쏟아져 내리는 모습”을 그린 모양자입니다.","崩는 “산(山)이 산사태(朋)로 무너져내리다” -> “무너지다, 붕괴하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1135/"},"紀":{"id":1124,"char":"紀","hun":"벼리 기","meaning":"“벼리 기”. 연대, 기록","on":"キ","kun":"","explanation":["紀 = 糸 + 己。","「糸」는 “실”을 뜻합니다.","「己」는 “구부러진 새끼줄”을 뜻합니다.","紀는 “실(糸)처럼 계속 이어지는(己) 연대기” -> “연대, 기록”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1136/"},"聴":{"id":1125,"char":"聴","hun":"들을 청","meaning":"“들을 청”. (귀담아)듣다","on":"チョウ","kun":"き(く)","explanation":["聴 = 耳 + 十 + 罒 + 心。","「耳」는 “귀”를 뜻합니다.","十+罒는 여기서는 「直」가 변형된 것으로, “곧다”라는 뜻입니다.","「心」는 “마음”을 뜻합니다.","聴는 “마음(心)을 바르게(直) 하고 귀담아(耳) 듣다” -> “(귀담아)듣다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1137/"},"脱":{"id":1126,"char":"脱","hun":"벗을 탈","meaning":"“벗을 탈”. 벗다, 벗어나다","on":"ダツ","kun":"ぬ(ぐ)、ぬ(げる)","explanation":["脱 = 月 + 兑。","「月」는 “신체의 일부”를 뜻합니다.","「兑」는 “진지한 표정을 한 사람”을 뜻합니다.","脱는 “구도자(兑)가 육신(月)의 굴레를 벗어나 해탈에 이르다” -> “벗다, 벗어나다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1138/"},"博":{"id":1127,"char":"博","hun":"넓을 박","meaning":"“넓을 박”. 넓다, 박식하다","on":"ハク、バク","kun":"","explanation":["博 = 十 + 尃。","(의미부) 「十」는 “10”을 뜻합니다.","(소리부 겸 의미부) 「尃」(ハク・バク)는 “넓다”라는 뜻입니다.","博는 “열 가지 분야(十)에 걸친 넓은(尃) 지식을 가지다” -> “넓다, 박식하다”라는 뜻의 글자입니다.","(尃는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1139/"},"患":{"id":1128,"char":"患","hun":"근심 환","meaning":"“근심 환”. 근심, 괴로움","on":"カン","kun":"わずら(う)","explanation":["患 = 串 + 心。","串는 “꼬챙이에 꿰인 떡”을 그린 글자입니다.","「心」는 “마음”을 뜻합니다.","患는 “마음(心)이 꼬챙이에 꿰인(串) 듯 아프다” -> “근심, 괴로움”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1140/"},"締":{"id":1129,"char":"締","hun":"맺을 체","meaning":"“맺을 체”. 약속을 맺다, 단단히 묶다","on":"テイ","kun":"し(まる)、し(める)","explanation":["締 = 糸 + 帝。","(의미부) 「糸」는 “실”을 뜻합니다.","(소리부 겸 의미부) 帝(テイ- “임금 제”)는 “황제”를 뜻하는 상용한자입니다.","締는 “황제(帝)의 명령이 가지는 절대적인 구속력(糸)” -> “맺다, 단단히 묶다”라는 뜻의 글자입니다.","(帝는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1141/"},"執":{"id":1130,"char":"執","hun":"잡을 집","meaning":"“잡을 집”. 꼭 붙잡다, 집행하다","on":"シツ、シュウ","kun":"と(る)","explanation":["執 = 幸 + 丸。","「幸」는 “쇠사슬에 묶인 죄인”을 그린 글자입니다(링크 참조).","「丸」는 “몸을 둥글게 말고 엎드린 사람”을 그린 글자입니다(링크 참조).","執는 “죄인을 쇠사슬로 묶어(幸) 무릎꿇리고(丸) 형을 집행하다” -> “꼭 붙잡다, 집행하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1142/"},"房":{"id":1131,"char":"房","hun":"방 방","meaning":"“방 방”. 방, 침실","on":"ボウ","kun":"ふさ","explanation":["房 = 戸 + 方。","(의미부) 「戸」는 “집, 출입구, 문”을 뜻합니다.","(소리부 겸 의미부) 「方」(ホウ)는 “방향”을 뜻합니다.","房는 “문(戸) 안쪽(方)의 방” -> “방, 침실”이라는 뜻의 글자입니다.","(方는 소리부(ホウ -> ボウ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1143/"},"撤":{"id":1132,"char":"撤","hun":"거둘 철","meaning":"“거둘 철”. 제거하다, 거두어들이다","on":"テツ","kun":"","explanation":["撤 = 扌 + 育 + 攵。","「扌」는 “손”을 뜻합니다.","「育」는 “키우다, 기르다, 양육하다”라는 뜻입니다.","「攵」는 “때리다, 치다”라는 뜻입니다.","撤는 “때리는(攵) 계모에게서 아이를 데려와(扌) 대신 키우다(育)” -> “거두어들이다, 제거하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1144/"},"削":{"id":1133,"char":"削","hun":"깎을 삭","meaning":"“깎을 삭”. 잘라내다, 삭제하다","on":"サク","kun":"けず(る)","explanation":["削 = ⺌ + 月 + 刂。","⺌는 여기서는 「小」가 뒤집힌 것으로, “작다”라는 뜻입니다.","「月」는 “고기”를 뜻합니다.","「刂」는 “칼”을 뜻합니다.","削는 “고기(月)를 작게(小) 자르다(刂)” -> “잘라내다, 삭제하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1145/"},"密":{"id":1134,"char":"密","hun":"빽빽할 밀","meaning":"“빽빽할 밀”. 비밀의, 빈틈없는, 빽빽한","on":"ミツ","kun":"","explanation":["密 = 宀 + 必 + 山。","「宀」는 “집”을 뜻합니다.","「必」는 “반드시, 필수적인”이라는 뜻입니다.","「山」는 “산”을 뜻합니다.","密는 “산(山)속의 오두막(宀)에 꼭꼭 숨겨놓은 중요한(必) 물건” -> “비밀의, 빈틈없는”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1146/"},"措":{"id":1135,"char":"措","hun":"둘 조","meaning":"“둘 조”. 두다, 그대로 두다","on":"ソ","kun":"","explanation":["措 = 扌 + 昔。","「扌」는 “손”을 뜻합니다.","「昔」는 “옛날”을 뜻합니다.","措는 “오래 전에(昔) 놓아둔(扌) 상태 그대로 두다” -> “두다, 그대로 두다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1147/"},"載":{"id":1136,"char":"載","hun":"실을 재","meaning":"“실을 재”. 싣다, 얹다","on":"サイ","kun":"の(せる)、の(る)","explanation":["載 = 𢦏 + 車。","(소리부 겸 의미부) 「𢦏」(サイ)는 “화려한 의장용 창”을 뜻합니다.","(의미부) 「車」는 “수레, 차”를 뜻합니다.","載는 “의장용 창(𢦏)을 수레(車)에 실어 운반하다” -> “싣다, 얹다”라는 뜻의 글자입니다.","(𢦏는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1148/"},"陣":{"id":1137,"char":"陣","hun":"진칠 진","meaning":"“진칠 진”. 진, 진치다","on":"ジン","kun":"","explanation":["陣 = ⻖ + 車。","「⻖」는 “언덕”을 뜻합니다.","「車」는 “수레, 차”를 뜻합니다.","陣는 “언덕(⻖) 아래 늘어선 전차들(車)” -> “진, 진치다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1149/"},"我":{"id":1138,"char":"我","hun":"나 아","meaning":"“나 아”. 나, 자신","on":"ガ","kun":"われ、わ","explanation":["我 = 扌 + 戈。","「扌」는 “손”을 뜻합니다.","「戈」는 “창”을 뜻합니다.","我는 “창(戈)을 들어(扌) 자신의 몸을 지키다” -> “나, 자신”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1150/"},"為":{"id":1139,"char":"為","hun":"할 위","meaning":"“할 위”. 하다, 행하다","on":"イ","kun":"","explanation":["為는 본래 “코끼리에게 지시를 내리는 손”을 그린 상형문자입니다.","“코끼리를 이용해 노동을 하다” -> “하다, 행하다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/1151/"},"抑":{"id":1140,"char":"抑","hun":"누를 억","meaning":"“누를 억”. 누르다, 억누르다","on":"ヨク","kun":"おさ(える)","explanation":["抑 = 扌 + 卬。","「扌」는 “손”을 뜻합니다.","「卬」는 “서 있는 사람(𠂎)과 무릎꿇은 사람(卩)”을 그린 글자입니다(링크 참조).","抑는 “서 있는 사람(𠂎)이 무릎꿇은 사람(卩)의 머리를 찍어누르다(扌)” -> “누르다, 억누르다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1152/"},"幕":{"id":1141,"char":"幕","hun":"장막 막","meaning":"“장막 막”. 장막","on":"マク、バク","kun":"","explanation":["幕 = 莫 + 巾。","(소리부 겸 의미부) 「莫」(バク)는 “해가 수풀 사이로 저무는 모습”을 그린 글자입니다(링크 참조).","(의미부) 「巾」는 “수건, 천”을 뜻합니다.","幕는 “천(巾)으로 햇빛을 가려 없애다(莫)” -> “장막”이라는 뜻의 글자입니다.","(莫는 소리부(バク -> マク・バク)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1153/"},"染":{"id":1142,"char":"染","hun":"물들 염","meaning":"“물들 염”. 염색하다, 물들다","on":"セン","kun":"そ(める)、そ(まる)、し(みる)、し(み)","explanation":["染 = 氵 + 九 + 木。","「氵」는 “물”을 뜻합니다.","「九」는 “9”를 뜻합니다.","「木」는 “나무”를 뜻합니다.","染는 “나무열매(木)에서 추출한 9가지(九) 색의 천연 염료(氵)” -> “염색하다, 물들다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1154/"},"奈":{"id":1143,"char":"奈","hun":"어찌 나","meaning":"“어찌 나”. (지명에 쓰이는 한자)","on":"ナ","kun":"","explanation":["奈 = 大 + 示。","「大」는 “크다”라는 뜻입니다.","「示」는 “고대의 비석”을 뜻합니다.","奈는 “이렇게 커다란(大) 비석(示)을 어찌 만들었나” -> “어찌하여, 어찌”라는 뜻의 글자입니다.","(다만, 이 한자는 실제로는 거의 지명의 일부로만 쓰이는 지명한자입니다.)"],"sourceUrl":"https://nihongokanji.com/1155/"},"傷":{"id":1144,"char":"傷","hun":"다칠 상","meaning":"“다칠 상”. 상처, 상처내다, 다치다","on":"ショウ","kun":"きず、いた(む)、いた(める)","explanation":["傷 = 亻 + 𠂉 + 昜。","「昜」는 “햇볕, 뜨거운 햇살”을 뜻합니다.","「亻」는 “사람”을 뜻합니다.","𠂉는 여기서는 “눈이 부셔서 햇볕을 가린 손”을 그린 모양자입니다.","傷는 “너무 강한 햇빛(昜)에 눈이 아파 손으로 가린(𠂉) 사람(亻)” -> “상처, 다치다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1156/"},"択":{"id":1145,"char":"択","hun":"가릴 택","meaning":"“가릴 택”. 선택하다, 고르다","on":"タク","kun":"","explanation":["択 = 扌 + 尺。","「扌」는 “손”을 뜻합니다.","尺는 여기서는 “말고삐”를 그린 모양자입니다.","択는 “타고 갈 말(尺)을 고르다(扌)” -> “선택하다, 고르다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1157/"},"秀":{"id":1146,"char":"秀","hun":"빼어날 수","meaning":"“빼어날 수”. 뛰어나다","on":"シュウ","kun":"ひい(でる)","explanation":["秀 = 禾 + 乃。","「禾」는 “곡식”을 뜻합니다.","乃는 여기서는 “엄지를 치켜든 모습”을 그린 모양자입니다.","秀는 “최상급 품질(乃)의 곡식(禾)” -> “빼어나다, 뛰어나다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1158/"},"徴":{"id":1147,"char":"徴","hun":"부를 징","meaning":"“부를 징”. 징집하다, 특징, 징표, 상징","on":"チョウ","kun":"","explanation":["徴 = 彳 + 山 + 王 + 攵。","「彳」는 “길”을 뜻합니다.","「山」는 “산”을 뜻합니다.","「王」는 “왕”을 뜻합니다.","「攵」는 “때리다, 치다”라는 뜻입니다.","徴는 “왕(王)에게 징병된 노예들이 두들겨맞고(攵) 산속의(山) 군부대로 끌려가다(彳)”라는 뜻입니다.","“노예들이 군대로 끌려가다” -> “징집하다”","“징병된 노예들의 신분증을 확인하다” -> “특징, 징표, 상징”","이라는 의미입니다.","(“왕”을 “정부권력”으로 바꿔서 생각하면 조금 더 쉽게 기억할 수 있습니다.)"],"sourceUrl":"https://nihongokanji.com/1159/"},"弾":{"id":1148,"char":"弾","hun":"탄알 탄","meaning":"“탄알 탄”. 탄알, 튕기다","on":"ダン","kun":"ひ(く)、はず(む)、たま","explanation":["弾 = 弓 + 単。","(의미부) 「弓」는 “활”을 뜻합니다.","(소리부 겸 의미부) 「単」(タン)은 “단독, 홀로”라는 뜻입니다.","弾는 “활시위(弓)를 튕겨 화살 한 개(単)를 쏘아 날리다” -> “탄알, 튕기다”라는 뜻의 글자입니다.","(単는 소리부(タン -> ダン)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1160/"},"償":{"id":1149,"char":"償","hun":"갚을 상","meaning":"“갚을 상”. 변상하다, 보상하다","on":"ショウ","kun":"つぐな(う)","explanation":["償 = 亻 + 賞。","(의미부) 「亻」는 “사람”을 뜻합니다.","(소리부 겸 의미부) 「賞」(ショウ)는 “상”을 뜻합니다.","償는 “공을 세우고 죽은 사람(亻)에게 상(賞)을 내리다” -> “보상하다, 변상하다”라는 뜻의 글자입니다.","(賞는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1161/"},"功":{"id":1150,"char":"功","hun":"공 공","meaning":"“공 공”. 공적, 공로","on":"コウ、ク","kun":"","explanation":["功 = 工 + 力。","(소리부 겸 의미부) 「工」(コウ・ク)는 “공작, 가공, 공정”을 뜻합니다.","(의미부) 「力」는 “힘”을 뜻합니다.","功는 “공사(工)에 큰 힘을(力) 보태다” -> “공적, 공로”라는 뜻의 글자입니다.","(工는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1162/"},"拠":{"id":1151,"char":"拠","hun":"의거할 거","meaning":"“의거할 거”. 의지하다","on":"キョ、コ","kun":"","explanation":["拠 = 扌 + 処。","「扌」는 “손”을 뜻합니다.","「処」는 “처리하다”라는 뜻입니다.","拠는 “일처리(処)를 믿고 맡길 수 있는 일손(扌)” -> “의지하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1163/"},"秘":{"id":1152,"char":"秘","hun":"숨길 비","meaning":"“숨길 비”. 숨기다, 비밀","on":"ヒ","kun":"ひ(める)","explanation":["秘 = 禾 + 必。","「禾」는 “곡식”을 뜻합니다.","「必」는 “반드시, 필수적인”이라는 뜻입니다.","秘는 “생존을 위해 반드시 필요한(必) 양의 곡식(禾)을 몰래 숨겨두다” -> “숨기다, 비밀”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1164/"},"拒":{"id":1153,"char":"拒","hun":"막을 거","meaning":"“막을 거”. 거절하다, 거부하다","on":"キョ","kun":"こば(む)","explanation":["拒 = 扌 + 巨。","(의미부) 「扌」는 “손”을 뜻합니다.","(소리부 겸 의미부) 「巨」(キョ)는 “크다”라는 뜻입니다.","拒는 “커다란(巨) 유혹을 밀어내다(扌)” -> “거절하다, 거부하다”라는 뜻의 글자입니다.","(巨는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1165/"},"刑":{"id":1154,"char":"刑","hun":"형벌 형","meaning":"“형벌 형”. 형벌, 벌하다","on":"ケイ","kun":"","explanation":["刑 = 开 + 刂。","开는 여기서는 “목에 칼을 찬 사형수”를 그린 모양자입니다.","「刂」는 “칼”을 뜻합니다.","刑는 “사형수(开)의 목을 베다(刂)” -> “형벌”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1166/"},"塚":{"id":1155,"char":"塚","hun":"무덤 총","meaning":"“무덤 총”. 무덤, 흙무더기","on":"","kun":"つか","explanation":["塚 = 土 + 冢。","「土」는 “흙”을 뜻합니다.","冢는 여기서는 「家」가 축약된 것으로, “집”을 뜻합니다.","塚는 “흙(土) 속에 묻힌 죽은 자의 집(冢)” -> “무덤, 흙무더기”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1167/"},"致":{"id":1156,"char":"致","hun":"이를 치","meaning":"“이를 치”. 초래하다, 이르다, 보내다","on":"チ","kun":"いた(す)","explanation":["致 = 至 + 攵。","至(“이를 지”)는 “화살이 과녁에 날아가 박힌 모습”을 그린 상용한자입니다.","「攵」는 “때리다, 치다”라는 뜻입니다.","致는 “남에게 가한 폭력(攵)이 보복(至)을 초래하다” -> “초래하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1168/"},"繰":{"id":1157,"char":"繰","hun":"고치 켤 조","meaning":"“고치 켤 조”. (실/밧줄 등을) 감다, (하나씩) 헤아리다/세다","on":"","kun":"く(る)","explanation":["繰 = 糸 + 品 + 木。","「糸」는 “실”을 뜻합니다.","「木」는 “나무”를 뜻합니다.","品는 여기서는 “(나무 위의) 누에고치들”을 그린 모양자입니다.","繰는 “나무(木) 위의 누에고치들(品)에서 실(糸)을 한 가닥씩 뽑아내다” -> “(실을) 감다, (하나씩) 헤아리다/세다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1169/"},"尾":{"id":1158,"char":"尾","hun":"꼬리 미","meaning":"“꼬리 미”. 꼬리","on":"ビ","kun":"お","explanation":["尾 = 尸 + 毛。","「尸」는 “앉아있는 사람”을 뜻합니다. 여기서는 “앉다” -> “엉덩이”라는 뜻입니다.","「毛」는 “털”을 뜻합니다.","尾는 “엉덩이(尸)에 난 털(毛)” -> “꼬리”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1170/"},"描":{"id":1159,"char":"描","hun":"그릴 묘","meaning":"“그릴 묘”. 그리다","on":"ビョウ","kun":"えが(く)、か(く)","explanation":["描 = 扌 + 苗。","(의미부) 「扌」는 “손”을 뜻합니다.","(소리부 겸 의미부) 苗는 여기서는 「猫」(ビョウ)가 축약된 것으로, “고양이”를 뜻합니다.","描는 “고양이(苗->猫)를 그리다(扌)” -> “그리다”라는 뜻의 글자입니다.","(苗는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1171/"},"鈴":{"id":1160,"char":"鈴","hun":"방울 령","meaning":"“방울 령”. 방울","on":"レイ、リン","kun":"すず","explanation":["鈴 = 金 + 令。","(의미부) 「金」는 “쇠, 금속”을 뜻합니다.","(소리부) 「令」(レイ)는 여기서는 소리부(レイ -> レイ・リン)의 역할만 하고 있습니다.","鈴는 “금속(金) 방울” -> “방울”이라는 뜻의 글자입니다(令는 소리부)."],"sourceUrl":"https://nihongokanji.com/1172/"},"盤":{"id":1161,"char":"盤","hun":"소반 반","meaning":"“소반 반”. 쟁반, 평평한 판","on":"バン","kun":"","explanation":["盤 = 般 + 皿。","(소리부 겸 의미부) 「般」(ハン)은 “일반”이라는 뜻입니다.","(의미부) 「皿」는 “그릇, 접시”를 뜻합니다.","盤는 “평범한(般) 접시(皿)” -> “쟁반, 평평한 판”이라는 뜻의 글자입니다.","(般은 소리부(ハン -> バン)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1173/"},"項":{"id":1162,"char":"項","hun":"항목 항","meaning":"“항목 항”. 항목, 조항","on":"コウ","kun":"","explanation":["項 = 工 + 頁。","(소리부) 「工」(コウ)는 여기서는 소리부의 역할만 하고 있습니다.","(의미부) 「頁」는 “머리”를 뜻합니다.","項는 “머리(頁)” -> “문서의 윗부분, 목차” -> “항목, 조항”이라는 뜻의 글자입니다(工는 소리부)."],"sourceUrl":"https://nihongokanji.com/1174/"},"喪":{"id":1163,"char":"喪","hun":"잃을 상","meaning":"“잃을 상”. 잃다","on":"ソウ","kun":"も","explanation":["喪 = 衣 + 口 + 口。","「衣」는 “옷”을 뜻합니다.","「口」는 “입”을 뜻합니다.","喪는 “상복(衣)을 입고 곡소리를(口) 내다” -> “장례식” -> “잃다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1175/"},"伴":{"id":1164,"char":"伴","hun":"짝 반","meaning":"“짝 반”. 짝, 동반자, 반려","on":"ハン、バン","kun":"ともな(う)","explanation":["伴 = 亻 + 半。","(의미부) 「亻」는 “사람”을 뜻합니다.","(소리부 겸 의미부) 「半」(ハン)은 “절반”을 뜻합니다.","伴는 “나(亻)의 절반(半)” -> “짝, 반려” -> “동반자, 동반하다”라는 뜻의 글자입니다.","(半는 소리부(ハン -> ハン・バン)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1176/"},"養":{"id":1165,"char":"養","hun":"기를 양","meaning":"“기를 양”. 사육하다, 기르다","on":"ヨウ","kun":"やしな(う)","explanation":["養 = 羊 + 食。","(소리부 겸 의미부) 「羊」(ヨウ)는 “양”을 뜻합니다.","(의미부) 「食」는 “먹다”라는 뜻입니다.","養는 “양(羊)에게 먹이(食)를 줘서 기르다” -> “사육하다, 기르다”라는 뜻의 글자입니다.","(羊는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1177/"},"懸":{"id":1166,"char":"懸","hun":"달 현","meaning":"“달 현”. 매달다","on":"ケン、ケ","kun":"か(ける)、か(かる)","explanation":["懸 = 県 + 一 + 糸 + 心。","(소리부 겸 의미부) 「県」(ケン)은 본래 “목매달린 사람”을 그린 글자입니다(링크 참조).","(의미부) 「糸」는 “실”을 뜻합니다.","(의미부) 一는 여기서는 “잇다, 연결하다”라는 뜻을 표현한 모양자입니다.","(의미부) 「心」는 “마음”을 뜻합니다.","懸는 “밧줄(糸)에 연결되어(一) 목이 매달린(県) 사람을 보고 두려운 마음(心)을 느끼다” -> “매달다”라는 뜻의 글자입니다.","(県은 소리부(ケン -> ケン・ケ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1178/"},"街":{"id":1167,"char":"街","hun":"거리 가","meaning":"“거리 가”. 시가, 거리","on":"ガイ、カイ","kun":"まち","explanation":["街 = 行 + 圭。","「行」는 본래 “사거리”를 그린 글자입니다.","圭는 “흙더미(土+土)”라는 뜻입니다.","街는 “흙언덕(圭)을 사이에 두고 양 옆에 늘어선 거리(行)” -> “시가, 거리”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1179/"},"契":{"id":1168,"char":"契","hun":"맺을 계","meaning":"“맺을 계”. (약속/계약 등을) 맺다, 새기다","on":"ケイ","kun":"ちぎ(る)","explanation":["契 = 龶 + 刀 + 大。","「刀」는 “칼”을 뜻합니다.","「大」는 본래 “사람”을 그린 글자입니다.","龶는 여기서는 “(칼로 새긴) 표식”을 그린 모양자입니다.","契는 “칼(刀)로 자신의 몸(大)에 표식(龶)을 새겨 맹세하다” -> “(약속/계약을) 맺다, 새기다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1180/"},"掲":{"id":1169,"char":"掲","hun":"높이 들 게","meaning":"“높이 들 게”. 높이 들다, 걸다","on":"ケイ","kun":"かか(げる)","explanation":["掲 = 扌 + 曷。","「曷」는 “허리를 굽혀 구걸하는 사람”을 그린 글자입니다(링크 참조).","「扌」는 “손”을 뜻합니다.","掲는 “허리를 굽신거리며(曷) 손을 위로 들어(扌) 돈을 구걸하다” -> “높이 들다, 걸다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1181/"},"躍":{"id":1170,"char":"躍","hun":"뛸 약","meaning":"“뛸 약”. 뛰어오르다","on":"ヤク","kun":"おど(る)","explanation":["躍 = 足 + 羽 + 隹。","「足」는 “발”을 뜻합니다.","「羽」는 “날개”를 뜻합니다.","「隹」는 “새”를 뜻합니다.","躍는 “새(隹)가 놀라서 펄쩍 뛰어(足) 날아가버리다(羽)” -> “뛰어오르다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1182/"},"棄":{"id":1171,"char":"棄","hun":"버릴 기","meaning":"“버릴 기”. 버리다","on":"キ","kun":"","explanation":["棄 = 亠 + ム + 丗 + 木。","亠+ム는 「子」가 위아래로 뒤집힌 것으로, “아이”를 뜻합니다.","丗는 여기서는 “바구니”를 그린 모양자입니다.","「木」는 “나무”를 뜻합니다.","棄는 “죽은 아이(亠+ム)를 바구니(丗)에 담아 나무(木) 위에 버리다” -> “버리다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1183/"},"邸":{"id":1172,"char":"邸","hun":"집 저","meaning":"“집 저”. 집, 저택","on":"テイ","kun":"","explanation":["邸 = 氐 + ⻏。","(소리부 겸 의미부) 「氐」(テイ)는 “낮다”라는 뜻입니다.","(의미부) 「⻏」는 “도시”를 뜻합니다.","邸는 “도시(⻏) 아래쪽(氐)에 지어진 대저택” -> ” 집, 저택”이라는 뜻의 글자입니다.","(氐는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1184/"},"籍":{"id":1173,"char":"籍","hun":"문서 적","meaning":"“문서 적”. 문서, 호적","on":"セキ","kun":"","explanation":["籍 = 𥫗 + 耒 + 昔。","(의미부) 「𥫗」는 “대나무 죽간”을 뜻합니다.","(의미부) 「耒」는 “쟁기”를 뜻합니다.","(소리부 겸 의미부) 「昔」(セキ)는 “옛날, 오래된”이라는 뜻입니다.","籍는 “오랫동안(昔) 전해져 내려온, 농민들(耒)의 명부가 대대로 적힌 문서(𥫗)” -> “문서, 호적”이라는 뜻의 글자입니다.","(昔는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1185/"},"縮":{"id":1174,"char":"縮","hun":"줄일 축","meaning":"“줄일 축”. 줄어들다, 축소되다","on":"シュク","kun":"ちぢ(む)、ちぢ(まる)、ちぢ(める)、ちぢ(れる)、ちぢ(らす)","explanation":["縮 = 糸 + 宿。","(의미부) 「糸」는 “실”을 뜻합니다.","(소리부) 「宿」(シュク)는 여기서는 소리부의 역할만 하고 있습니다.","縮는 “실(糸)이 물에 젖어 오그라들다” -> “줄어들다, 축소되다”라는 뜻의 글자입니다(宿는 소리부)."],"sourceUrl":"https://nihongokanji.com/1186/"},"還":{"id":1175,"char":"還","hun":"돌아올 환","meaning":"“돌아올 환”. 돌아오다","on":"カン","kun":"","explanation":["還 = ⻌ + 睘。","(의미부) 「⻌」는 “길”을 뜻합니다.","(소리부 겸 의미부) 「睘」(カン)은 “둥글다”라는 뜻의 글자입니다.","還는 “길(⻌)을 둥글게 돌아(睘) 원래 자리로 돌아오다” -> “돌아오다”라는 뜻의 글자입니다.","(睘는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1187/"},"属":{"id":1176,"char":"属","hun":"무리 속","meaning":"“무리 속”. 속하다","on":"ゾク","kun":"","explanation":["属 = 尾 + 虫。","「尾」는 “꼬리”를 뜻합니다.","「虫」는 “벌레”를 뜻합니다.","属는 “꼬리(尾)로 쫓아도 귀찮게 따라붙는 날벌레들(虫)” -> “따르다” -> “무리, 속하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1188/"},"慮":{"id":1177,"char":"慮","hun":"생각할 려","meaning":"“생각할 려”. 고려하다, 깊이 생각하다","on":"リョ","kun":"","explanation":["慮 = 虍 + 思。","「虍」는 “호랑이”를 뜻합니다.","「思」는 “생각하다”라는 뜻입니다.","慮는 “산에서 호랑이(虍)를 만날까봐 걱정하다(思)” -> “고려하다, 깊이 생각하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1189/"},"枠":{"id":1178,"char":"枠","hun":"테두리, 틀 (일본에서 만들어진 한자)","meaning":"테두리, 틀 (일본에서 만들어진 한자)","on":"","kun":"わく","explanation":["枠 = 木 + 卆。","「木」는 “나무”를 뜻합니다.","卆는 단순히 「九」와 「十」을 합쳐놓은 글자로, “9(九) + 10(十)” -> “여러 개, 많다”라는 뜻입니다.","枠는 “나무(木) 여러 개(卆)를 이어붙여 만든 뼈대” -> “테두리, 틀”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1190/"},"露":{"id":1179,"char":"露","hun":"이슬 로","meaning":"“이슬 로”. 이슬, 드러내다","on":"ロ、ロウ","kun":"つゆ","explanation":["露 = 雨 + 路。","(의미부) 「雨」는 “비”를 뜻합니다.","(소리부 겸 의미부) 「路」(ロ)는 “길”을 뜻합니다.","露는,","“비온 뒤(雨) 길가(路)의 풀잎에 맺힌 이슬” -> “이슬”","“비(雨)로 쓸려나간 길(路)의 표면이 드러나다” -> “드러나다”","라는 뜻의 글자입니다.","(路는 소리부(ロ -> ロ・ロウ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1191/"},"沖":{"id":1180,"char":"沖","hun":"화할 충","meaning":"“화할 충”. 높이 오르다, 먼 바다","on":"チュウ","kun":"おき","explanation":["沖 = 氵 + 中。","(의미부) 「氵」는 “물”을 뜻합니다.","(소리부 겸 의미부) 「中」(チュウ)는 “가운데”라는 뜻입니다.","沖는 “바다(氵) 한가운데(中)에서 일어나는 용오름” -> “높이 오르다, 먼 바다”라는 뜻의 글자입니다.","(中는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1192/"},"緩":{"id":1181,"char":"緩","hun":"느릴 완","meaning":"“느릴 완”. 느린, 느슨한, 완만한","on":"カン","kun":"ゆる(い)、ゆる(やか)、ゆる(む)、ゆる(める)","explanation":["緩 = 糸 + 爰。","「糸」는 “실”을 뜻합니다.","「爰」는 “한가하다, 여유롭다, 느긋하다”라는 뜻입니다.","緩는 “느슨하게(爰) 늘어진 실(糸)” -> “느슨한, 느린, 완만한”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1193/"},"需":{"id":1182,"char":"需","hun":"쓰일/쓸 수","meaning":"“쓰일/쓸 수”. 필요한, 필수적인","on":"ジュ","kun":"","explanation":["需 = 雨 + 而。","「雨」는 “비”를 뜻합니다.","而는 여기서는 “비를 막기 위해 쓰던 비옷(도롱이)”를 그린 모양자입니다. 아래 그림을 참조해 주세요.","需는 “비(雨)를 막기 위해 꼭 필요한 비옷(而)” -> “필요한, 필수적인”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1194/"},"射":{"id":1183,"char":"射","hun":"쏠 사","meaning":"“쏠 사”. 쏘다","on":"シャ","kun":"い(る)","explanation":["射 = 身 + 寸。","「身」는 “신체, 몸”을 뜻합니다.","寸는 여기서는 “활”을 그린 모양자입니다.","射는 “몸(身)에 든 활(寸)을 쏘다” -> “쏘다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1195/"},"購":{"id":1184,"char":"購","hun":"살 구","meaning":"“살 구”. 사들이다","on":"コウ","kun":"","explanation":["購 = 貝 + 冓。","(의미부) 「貝」는 “돈, 재물”을 뜻합니다.","(소리부 겸 의미부) 「冓」(コウ)는 본래 “물고기 두 마리가 얽힌 모습”을 그린 글자입니다(링크 참조).","購는 “생선 묶음(冓)을 구입하다(貝)” -> “사들이다”라는 뜻의 글자입니다.","(冓는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1196/"},"揮":{"id":1185,"char":"揮","hun":"휘두를 휘","meaning":"“휘두를 휘”. 휘두르다, 지휘하다","on":"キ","kun":"","explanation":["揮 = 扌 + 軍。","「扌」는 “손”을 뜻합니다.","「軍」는 “군대”를 뜻합니다.","揮는 “손(扌)을 흔들어 군대(軍)를 지휘하다” -> “휘두르다, 지휘하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1197/"},"充":{"id":1186,"char":"充","hun":"채울 충","meaning":"“채울 충”. 가득한, 채우다","on":"ジュウ","kun":"あ(てる)","explanation":["充는 “배가 나온 사람”을 그린 상형문자입니다.","“배가 나오다” -> “가득하다, 채우다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/1198/"},"跡":{"id":1187,"char":"跡","hun":"발자취 적","meaning":"“발자취 적”. 발자취, 흔적","on":"セキ","kun":"あと","explanation":["跡 = 足 + 亦。","「足」는 “발”을 뜻합니다.","「亦」는 “팔을 벌리고 걷는 사람”을 그린 글자입니다.","跡는 “걸어가는 사람(亦)의 발자국(足)” -> “발자취, 흔적”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1199/"},"貢":{"id":1188,"char":"貢","hun":"바칠 공","meaning":"“바칠 공”. 바치다, 공물","on":"コウ、ク","kun":"みつ(ぐ)","explanation":["貢 = 工 + 貝。","(소리부 겸 의미부) 「工」(コウ・ク)는 “공작, 가공, 공정”을 뜻합니다.","(의미부) 「貝」는 “돈, 재물”을 뜻합니다.","貢는 “공사(工)에 들어갈 비용(貝)을 상납하다” -> “바치다, 공물”이라는 뜻의 글자입니다.","(工는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1200/"},"鹿":{"id":1189,"char":"鹿","hun":"사슴 록","meaning":"“사슴 록”. 사슴","on":"","kun":"しか、か","explanation":["鹿는 “뿔이 긴 수사슴”을 그린 상형문자입니다."],"sourceUrl":"https://nihongokanji.com/1201/"},"却":{"id":1190,"char":"却","hun":"물리칠 각","meaning":"“물리칠 각”. 물리치다, 물러나다, 없애버리다","on":"キャク","kun":"","explanation":["却 = 去 + 卩。","「去」는 “떠나가다, 지나가다”라는 뜻입니다.","「卩」는 “무릎꿇은 사람”을 뜻합니다.","却는 “무릎꿇고 애원하는 사람(卩)을 매정하게 내치고 떠나다(去)” -> “물리치다, 물러나다, 없애버리다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1202/"},"端":{"id":1191,"char":"端","hun":"끝 단","meaning":"“끝 단”. 단정하다, 끝, 끄트머리","on":"タン","kun":"はし、は、はた","explanation":["端 = 立 + 耑。","「立」는 “서다”라는 뜻입니다.","耑는 여기서는 “나무의 뿌리(而)와 뻗어나간 가지(山)”를 그린 모양자입니다.","端는,","“단단히 뿌리박고(而) 곧게 선(立) 나무(山)” -> “단정하다, 바르다”","“뻗어나간 가지(山)의 끄트머리” -> “끝, 끄트머리”","라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1203/"},"獲":{"id":1192,"char":"獲","hun":"얻을 획","meaning":"“얻을 획”. 얻다, 획득하다","on":"カク","kun":"え(る)","explanation":["獲 = 犭 + 艹 + 隹 + 又。","「犭」는 “개, 동물”을 뜻합니다.","「艹」는 “풀”을 뜻합니다.","「隹」는 “새”를 뜻합니다.","「又」는 “손”을 뜻합니다.","獲는 “사냥개(犭)가 풀숲(艹)에 숨은 새(隹)를 붙잡다(又)” -> “얻다, 획득하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1204/"},"郡":{"id":1193,"char":"郡","hun":"고을 군","meaning":"“고을 군”. 군, 고을, 행정 구획(도도부현의 아래)","on":"グン","kun":"","explanation":["郡 = 君 + ⻏。","(소리부 겸 의미부) 「君」(クン)은 “군주, 임금”을 뜻합니다.","(의미부) 「⻏」는 “도시”를 뜻합니다.","郡는 “군주(郡)가 다스리는 도시(⻏)” -> “군, 고을”이라는 뜻의 글자입니다.","(君는 소리부(クン -> グン)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1205/"},"併":{"id":1194,"char":"併","hun":"아우를 병","meaning":"“아우를 병”. 나란히 하다, 겸하다, 아우르다","on":"ヘイ","kun":"あわ(せる)","explanation":["併 = 亻 + 并。","「亻」는 “사람”을 뜻합니다.","并는 여기서는 “두 사람이 나란히 서 있는 모습”을 그린 모양자입니다.","併는 “두 사람(亻)이 나란히 늘어서다(并)” -> “나란히 하다, 겸하다, 아우르다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1206/"},"徹":{"id":1195,"char":"徹","hun":"통할 철","meaning":"“통할 철”. 꿰뚫다, 끝까지 하다","on":"テツ","kun":"","explanation":["徹 = 彳 + 育 + 攵。","「彳」는 “길”을 뜻합니다.","「育」는 “기르다, 양육하다”라는 뜻입니다.","「攵」는 “때리다, 치다”라는 뜻입니다.","徹는 “길(彳)에서 아이를 회초리로 때리며(攵) 훈육하다(育)”라는 뜻입니다.","“아이를 철저히 훈육하다” -> “끝까지 하다, 꿰뚫다, 철저히”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/1207/"},"貴":{"id":1196,"char":"貴","hun":"귀할 귀","meaning":"“귀할 귀”. 귀중한, 고귀한","on":"キ","kun":"たっと(い)、とうと(い)、たっと(ぶ)、とうと(ぶ)","explanation":["貴 = 𠀐 + 貝。","𠀐는 여기서는 「上」가 변형된 것으로, “높다”라는 뜻입니다.","「貝」는 “돈, 재물”을 뜻합니다.","貴는 “상등품(𠀐)의 재보(貝)” -> “귀하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1208/"},"衝":{"id":1197,"char":"衝","hun":"찌를 충","meaning":"“찌를 충”. 부딪다, 찌르다","on":"ショウ","kun":"","explanation":["衝 = 行 + 重。","「行」는 본래 “사거리”를 그린 글자입니다.","「重」는 “무겁다”라는 뜻입니다.","衝는 “사거리 한가운데(行)에서 무거운(重) 수레에 치이다” -> “부딪다, 찌르다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1209/"},"焦":{"id":1198,"char":"焦","hun":"탈 초","meaning":"“탈 초”. 그슬리다, 태우다, 안달하다","on":"ショウ","kun":"こ(げる)、こ(がす)、こ(がれる)、あせ(る)","explanation":["焦 = 隹 + 灬。","「隹」는 “새”를 뜻합니다.","「灬」는 “불”을 뜻합니다.","焦는 “새고기(隹)를 불(灬)에 굽다”라는 뜻입니다.","“새고기를 불에 굽다” -> “그슬리다, 태우다”","“새고기를 빨리 먹고 싶어 안달이 나다” -> “애가 타다, 안달하다”","라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/1210/"},"奪":{"id":1199,"char":"奪","hun":"빼앗을 탈","meaning":"“빼앗을 탈”. 빼앗다","on":"ダツ","kun":"うば(う)","explanation":["奪 = 大 + 隹 + 寸。","「大」는 “사람”을 그린 글자입니다.","「隹」는 “새”를 뜻합니다.","「寸」는 “손”을 뜻합니다.","奪는 “다른 사람(大)의 품 안에 있는 새(隹)를 빼앗다(寸)” -> “빼앗다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1211/"},"災":{"id":1200,"char":"災","hun":"재앙 재","meaning":"“재앙 재”. 재앙","on":"サイ","kun":"わざわ(い)","explanation":["災 = 巛 + 火。","巛는 여기서는 “흐르는 물살”을 그린 모양자입니다.","「火」는 “불”을 뜻합니다.","災는 “홍수(巛)와 화재(火)” -> “재앙”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1212/"},"浦":{"id":1201,"char":"浦","hun":"개 포","meaning":"“개 포”. 물가","on":"","kun":"うら","explanation":["浦 = 氵 + 甫。","「氵」는 “물”을 뜻합니다.","「甫」는 “채소밭”을 뜻합니다.","浦는 “바닷가(氵)에 자라난 물풀(甫)” -> “물가”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1213/"},"析":{"id":1202,"char":"析","hun":"쪼갤 석","meaning":"“쪼갤 석”. 산산이 분해하다, 나누다","on":"セキ","kun":"","explanation":["析 = 木 + 斤。","「木」는 “나무”를 뜻합니다.","「斤」는 “도끼”를 뜻합니다.","析는 “도끼(斤)로 나무(木)를 쪼개다” -> “산산이 분해하다, 나누다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1214/"},"譲":{"id":1203,"char":"譲","hun":"사양할 양","meaning":"“사양할 양”. 양보하다, 양도하다, 사양하다, 겸손한","on":"ジョウ","kun":"ゆず(る)","explanation":["譲 = 言 + 㐮。","(의미부) 「言」는 “말하다”라는 뜻입니다.","(소리부 겸 의미부) 「㐮」(ジョウ)는 “상복, 예복”을 뜻하는 글자입니다(링크 참조).","譲는 “상복(㐮)을 입은 사람에게 위로의 말(言)을 건네다” -> “양도하다, 양보하다, 사양하다”라는 뜻의 글자입니다.","(㐮는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1215/"},"称":{"id":1204,"char":"称","hun":"일컬을 칭","meaning":"“일컬을 칭”. 칭찬하다, 칭하다, 칭호","on":"ショウ","kun":"","explanation":["称 = 禾 + 尔。","「禾」는 “곡식”을 뜻합니다.","尔는 여기서는 “천칭”을 그린 모양자입니다.","称는 “곡식(禾)의 무게를 천칭(尔)에 달아 가격을 부르다” -> “칭하다, 칭호”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1216/"},"納":{"id":1205,"char":"納","hun":"들일 납","meaning":"“들일 납”. 수납하다, 넣어 두다","on":"ノウ、ナッ、ナ、ナン、トウ","kun":"おさ(める)、おさ(まる)","explanation":["納 = 糸 + 内。","「糸」는 “실”을 뜻합니다.","「内」는 “안쪽”을 뜻합니다.","納는 “실(糸)을 감아서 서랍 안쪽(内)에 넣어두다” -> “수납하다, 넣어 두다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1217/"},"樹":{"id":1206,"char":"樹","hun":"나무 수","meaning":"“나무 수”. 나무, 세우다","on":"ジュ","kun":"","explanation":["樹 = 木 + 壴 + 寸。","「木」는 “나무”를 뜻합니다.","「壴」는 “북”을 뜻합니다.","「寸」는 “손”을 뜻합니다.","樹는 “나무(木)를 심어(寸) 과수원을 세우고 북(壴)을 치며 축하하다” -> “나무, 세우다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1218/"},"挑":{"id":1207,"char":"挑","hun":"돋울 도","meaning":"“돋울 도”. 도전하다","on":"チョウ","kun":"いど(む)","explanation":["挑 = 扌 + 兆。","(의미부) 「扌」는 “손”을 뜻합니다.","(소리부 겸 의미부) 「兆」(チョウ)는 “징조, 전조, 징후”를 뜻합니다.","挑는 “승리의 전조(兆)를 느끼고 싸움을 걸다(扌)” -> “도전하다”라는 뜻의 글자입니다.","(兆는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1219/"},"誘":{"id":1208,"char":"誘","hun":"꾈 유","meaning":"“꾈 유”. 꾀어내다, 유인하다","on":"ユウ","kun":"さそ(う)","explanation":["誘 = 言 + 秀。","「言」는 “말하다”라는 뜻입니다.","「秀」는 “뛰어나다”라는 뜻의 상용한자입니다.","誘는 “뛰어난(秀) 언변(言)으로 유혹하다” -> “꾀어내다, 유인하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1220/"},"紛":{"id":1209,"char":"紛","hun":"어지러울 분","meaning":"“어지러울 분”. 어지러운, 혼란스러운, 번잡한","on":"フン","kun":"まぎ(れる)、まぎ(らす)、まぎ(らわす)、まぎ(らわしい)","explanation":["紛 = 糸 + 分。","(의미부) 「糸」는 “실”을 뜻합니다.","(소리부 겸 의미부) 「分」(フン)은 “나누다, 가르다”라는 뜻입니다.","紛는 “실타래(糸)를 잘못 잘라(分) 전부 뒤엉켜버리다” -> “어지러운, 혼란스러운, 번잡한”이라는 뜻의 글자입니다.","(分는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1221/"},"至":{"id":1210,"char":"至","hun":"이를 지","meaning":"“이를 지”. 이르다, 극에 달하다","on":"シ","kun":"いた(る)","explanation":["至 = 𠫔 + 土。","𠫔는 여기서는 “과녁”을 그린 모양자입니다.","土는 여기서는 “(과녁에 날아가 박힌) 화살”을 그린 모양자입니다.","至는 “화살(土)이 과녁(𠫔)에 날아가 박히다” -> “이르다, 극에 달하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1222/"},"宗":{"id":1211,"char":"宗","hun":"마루 종","meaning":"“마루 종”. 근원, 으뜸, 종주, 종교","on":"シュウ、ソウ","kun":"","explanation":["宗 = 宀 + 示。","「宀」는 “집”을 뜻합니다.","「示」는 “신, 종교, 고대의 비석”을 뜻합니다.","宗는 “집(宀)에서 받들어 모시는 신(示)” -> “으뜸, 근원, 종주, 종교”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1223/"},"促":{"id":1212,"char":"促","hun":"재촉할 촉","meaning":"“재촉할 촉”. 재촉하다","on":"ソク","kun":"うなが(す)","explanation":["促 = 亻 + 足。","「亻」는 “사람”을 뜻합니다.","「足」는 “발”을 뜻합니다.","促는 “서둘러 발걸음(足)을 재촉하는 사람(亻)” -> “재촉하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1224/"},"慎":{"id":1213,"char":"慎","hun":"삼갈 신","meaning":"“삼갈 신”. 조심하다, 삼가다","on":"シン","kun":"つつし(む)","explanation":["慎 = 忄 + 真。","(의미부) 「忄」는 “마음”을 뜻합니다.","(소리부 겸 의미부) 「真」(シン)은 “참되다, 진실되다”라는 뜻입니다.","慎는 “마음(忄)을 진지하게(真) 다잡다” -> “조심하다, 삼가다”라는 뜻의 글자입니다.","(真는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1225/"},"控":{"id":1214,"char":"控","hun":"당길 공","meaning":"“당길 공”. 빼다, 당기다, 기다리다","on":"コウ","kun":"ひか(える)","explanation":["控 = 扌 + 空。","(의미부) 「扌」는 “손”을 뜻합니다.","(소리부 겸 의미부) 「空」(クウ)는 “비어있다”라는 뜻입니다.","控는 “뭉친 것을 잡아당겨(扌) 빈 공간(空)을 만들다” -> “빼다, 당기다, 기다리다”라는 뜻의 글자입니다.","(空는 소리부(クウ -> コウ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1226/"},"握":{"id":1215,"char":"握","hun":"쥘 악","meaning":"“쥘 악”. 쥐다","on":"アク","kun":"にぎ(る)","explanation":["握 = 扌 + 握。","(의미부) 「扌」는 “손”을 뜻합니다.","(소리부 겸 의미부) 「屋」(オク)는 “집, 지붕”을 뜻합니다.","握는 “지붕(屋) 끝을 꽉 잡고(扌) 매달리다” -> “쥐다, 움켜쥐다”라는 뜻의 글자입니다.","(屋는 소리부(オク -> アク)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1227/"},"俊":{"id":1216,"char":"俊","hun":"준걸 준","meaning":"“준걸 준”. 뛰어난, 걸출한","on":"シュン","kun":"","explanation":["俊 = 亻 + 夋。","「亻」는 “사람”을 뜻합니다.","「夋」는 “천천히 걷는 사람”을 그린 글자입니다(링크 참조).","俊는 “기품있게 천천히 걷는(夋) 사람(亻)” -> “뛰어나다, 걸출하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1228/"},"銭":{"id":1217,"char":"銭","hun":"돈 전","meaning":"“돈 전”. 동전","on":"セン","kun":"ぜに","explanation":["銭 = 金 + 㦮。","(의미부) 「金」는 “쇠, 황금, 돈”을 뜻합니다.","(소리부 겸 의미부) 㦮는 여기서는 「浅」(セン)이 축약된 것으로, “얕다”라는 뜻입니다.","銭는 “적은(浅) 돈(金)” -> “동전”이라는 뜻의 글자입니다.","(㦮->浅는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1229/"},"渋":{"id":1218,"char":"渋","hun":"떫을 삽","meaning":"“떫을 삽”. 떫다, 일이 정체되다","on":"ジュウ","kun":"しぶ、しぶ(い)、しぶ(る)","explanation":["渋 = 氵 + 止 + 冫 + 冫。","「氵」는 “물”을 뜻합니다.","「止」는 “멈추다”라는 뜻입니다(여기서는 “발”이 아닌 한자 자체의 뜻으로 사용된 것입니다).","아래쪽의 冫+冫는 여기서는 “물이 고여있는 모습”을 그린 모양자입니다.","渋는 “물(氵)이 고인 채(冫+冫) 흐르지 않고 멈추다(止)” -> “정체되다, 떫다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1230/"},"銃":{"id":1219,"char":"銃","hun":"총 총","meaning":"“총 총”. 총","on":"ジュウ","kun":"","explanation":["銃 = 金 + 充。","(의미부) 「金」는 “쇠, 금속”을 뜻합니다.","(소리부 겸 의미부) 「充」(ジュウ)는 “채우다”라는 뜻입니다.","銃는 “금속(金)에 화약을 채워서(充) 쓰는 무기” -> “총”이라는 뜻의 글자입니다.","(充는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1231/"},"携":{"id":1220,"char":"携","hun":"이끌 휴","meaning":"“이끌 휴”. 휴대하다, 잡다, 끌다","on":"ケイ","kun":"たずさ(える)、たずさ(わる)","explanation":["携 = 扌 + 隹 + 乃。","「扌」는 “손”을 뜻합니다.","「隹」는 “새”를 뜻합니다.","乃는 여기서는 “엄지를 치켜든 모습”을 그린 모양자입니다.","携는 “최고급(乃) 새고기(隹)를 잡아서 허리춤에 들고 다니다(扌)” -> “휴대하다, 잡다, 끌다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1232/"},"診":{"id":1221,"char":"診","hun":"진찰할 진","meaning":"“진찰할 진”. 진찰하다","on":"シン","kun":"み(る)","explanation":["診 = 言 + 㐱。","(의미부) 「言」는 “말하다”라는 뜻입니다.","(소리부 겸 의미부) 㐱는 여기서는 「珍」(チン)이 축약된 것으로, “진귀한, 흔치 않은”이라는 뜻입니다.","診는 “의사가 해주는 진귀한(珍) 조언(言)” -> “진찰하다, 진단하다”라는 뜻의 글자입니다.","(㐱->珍는 소리부(チン -> シン)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1233/"},"託":{"id":1222,"char":"託","hun":"부탁할 탁","meaning":"“부탁할 탁”. 부탁하다","on":"タク","kun":"","explanation":["託 = 言 + 乇。","「言」는 “말하다”라는 뜻입니다.","乇는 여기서는 “등을 돌리고 앉아있는 사람”을 그린 모양자입니다.","託는 “등을 돌리고 앉아있는 사람(乇)에게 애원하다(言)” -> “부탁하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1234/"},"撮":{"id":1223,"char":"撮","hun":"모을 촬","meaning":"“모을 촬”. 사진 찍다(촬영하다)","on":"サツ","kun":"と(る)","explanation":["撮 = 扌 + 最。","「扌」는 “손”을 뜻합니다.","「最」는 “최고”라는 뜻입니다.","撮는 “최고의 순간(最)을 사진으로 찍어서(扌) 남기다” -> “촬영하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1235/"},"誕":{"id":1224,"char":"誕","hun":"낳을 탄","meaning":"“낳을 탄”. 태어나다","on":"タン","kun":"","explanation":["誕 = 言 + 延。","「言」는 “말하다”라는 뜻입니다.","「延」는 “늘이다”라는 뜻입니다.","誕는 “갓 태어난 아기의 울음소리(言)가 길게 이어지다(延)” -> “태어나다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1236/"},"侵":{"id":1225,"char":"侵","hun":"침노할 침","meaning":"“침노할 침”. 침범하다, 침해하다","on":"シン","kun":"おか(す)","explanation":["侵 = 亻 + 𠬶。","「亻」는 “사람”을 뜻합니다.","𠬶는 “빗자루(「帚」)를 든 손(「又」)“을 뜻합니다.","侵는 “빗자루를 휘둘러(𠬶) 침입자(亻)를 쫓아내다” -> “침범하다, 침해하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1237/"},"括":{"id":1226,"char":"括","hun":"묶을 괄","meaning":"“묶을 괄”. 묶다, 일괄의","on":"カツ","kun":"","explanation":["括 = 扌 + 舌。","「扌」는 “손”을 뜻합니다.","「舌」는 “혓바닥”을 뜻합니다.","括는 “시끄러운 혓바닥(舌)을 묶어버리다(扌)” -> “묶다, 일괄의”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1238/"},"掛":{"id":1227,"char":"掛","hun":"걸 괘","meaning":"“걸 괘”. 걸다, 걸리다","on":"","kun":"か(ける)、か(かる)、かか(り)","explanation":["掛 = 扌 + 圭 + 卜。","「扌」는 “손”을 뜻합니다.","圭는 “흙더미(土+土)”라는 뜻입니다.","「卜」는 “점괘”를 뜻합니다.","掛는 “흙으로 쌓은 제단(圭)에 점괘(卜)를 걸어두다(扌)” -> “걸다, 걸리다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1239/"},"謝":{"id":1228,"char":"謝","hun":"사례할 사","meaning":"“사례할 사”. 사례하다, 사과하다","on":"シャ","kun":"あやま(る)","explanation":["謝 = 言 + 射。","(의미부) 「言」는 “말하다”라는 뜻입니다.","(소리부 겸 의미부) 「射」(シャ)는 “쏘다”라는 뜻입니다.","謝는,","“축하의 말(言)을 보내다(射)” -> “사례하다”","“사죄의 말(言)을 보내다(射)” -> “사과하다”","라는 뜻의 글자입니다.","(射는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1240/"},"孝":{"id":1229,"char":"孝","hun":"효도 효","meaning":"“효도 효”. 효도하다","on":"コウ","kun":"","explanation":["孝 = 耂 + 子。","「耂」는 “노인”을 뜻합니다.","「子」는 “아이”를 뜻합니다.","孝는 “늙은 부모(耂)를 모시는 아이(子)” -> “효도하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1241/"},"駆":{"id":1230,"char":"駆","hun":"몰 구","meaning":"“몰 구”. 몰다, 몰아내다","on":"ク","kun":"か(ける)、か(る)","explanation":["駆 = 馬 + 区。","(의미부) 「馬」는 “말”을 뜻합니다.","(소리부 겸 의미부) 「区」(ク)는 “구역, 구획”을 뜻합니다.","駆는 “말(馬)을 몰아 들짐승을 구역(区)에서 몰아내다” -> “몰다, 몰아대다, 몰아내다”라는 뜻의 글자입니다.","(区는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1242/"},"透":{"id":1231,"char":"透","hun":"사무칠 투","meaning":"“사무칠 투”. 투명하다, 꿰뚫다, 투과하다","on":"トウ","kun":"す(く)、す(ける)、す(かす)","explanation":["透 = ⻌ + 秀。","「⻌」는 “길”을 뜻합니다.","「秀」는 “뛰어나다, 빼어나다”라는 뜻입니다.","透는 “뛰어난(秀) 통찰력으로 올바른 길(⻌)을 꿰뚫어보다” -> “꿰뚫다, 투과하다, 투명하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1243/"},"津":{"id":1232,"char":"津","hun":"나루 진","meaning":"“나루 진”. 넘치다, 진액","on":"シン","kun":"つ","explanation":["津 = 氵 + 聿。","「氵」는 “물”을 뜻합니다.","「聿」는 “붓을 든 손”을 뜻합니다.","津는 “붓(聿)에서 먹물(氵)이 넘치다” -> “넘치다, 진액”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1244/"},"稲":{"id":1233,"char":"稲","hun":"벼 도","meaning":"“벼 도”. 벼","on":"トウ","kun":"いね、いな","explanation":["稲 = 禾 + ⺤ + 旧。","「禾」는 “곡식”을 뜻합니다.","「⺤」는 “손”을 뜻합니다.","旧는 여기서는 “항아리”를 그린 모양자입니다.","稲는 “항아리(旧)에 담아놓은(⺤) 탈곡한 벼(禾)” -> “벼”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1245/"},"裂":{"id":1234,"char":"裂","hun":"찢어질 렬","meaning":"“찢어질 렬”. 찢다, 터지다, 균열","on":"レツ","kun":"さ(く)、さ(ける)","explanation":["裂 = 列 + 衣。","(소리부 겸 의미부) 「列」(レツ)는 본래 “짐승의 시체(歹)를 잘라(刂) 나열하다“라는 뜻으로 만들어진 글자입니다(링크 참조).","(의미부) 「衣」는 “옷”을 뜻합니다.","裂는 “옷(衣)을 조각조각 찢다(列)” -> “찢다, 터지다, 균열”이라는 뜻의 글자입니다.","(列는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1246/"},"敏":{"id":1235,"char":"敏","hun":"민첩할 민","meaning":"“민첩할 민”. 민첩하다, 재빠르다","on":"ビン","kun":"","explanation":["敏 = 毎 + 攵。","「毎」는 본래 “머리에 비녀를 꽃은 어머니”를 그린 글자입니다(링크 참조).","「攵」는 “때리다, 치다”라는 뜻입니다.","敏는 “손을 바삐 움직이며(攵) 머리를 손질하는 여자(毎)” -> “민첩하다, 재빠르다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1247/"},"是":{"id":1236,"char":"是","hun":"옳을 시","meaning":"“옳을 시”. 옳다","on":"ゼ","kun":"","explanation":["是 = 日 + 𤴓。","「日」는 “태양”을 뜻합니다.","𤴓는 「正」가 살짝 변형된 것으로, “바르다”라는 뜻입니다.","是는 “하늘의 태양(日)처럼 바르고 올곧다(𤴓)” -> “옳다“라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1248/"},"排":{"id":1237,"char":"排","hun":"밀칠 배","meaning":"“밀칠 배”. 밀어내다, 배척하다","on":"ハイ","kun":"","explanation":["排 = 扌 + 非。","(의미부) 「扌」는 “손”을 뜻합니다.","(소리부 겸 의미부) 「非」(ヒ)는 “아니다, 옳지 않다”라는 뜻입니다.","排는 “옳지 못한(非) 것을 밀어내다(扌)” -> “밀어내다, 배척하다”라는 뜻의 글자입니다.","(非는 소리부(ヒ -> ハイ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1249/"},"裕":{"id":1238,"char":"裕","hun":"넉넉할 유","meaning":"“넉넉할 유”. 넉넉한, 너그러운","on":"ユウ","kun":"","explanation":["裕 = 衤 + 谷。","「衤」는 “옷, 옷감”을 뜻합니다.","「谷」는 “계곡, 골짜기”라는 뜻입니다.","裕는 “드넓은 계곡처럼(谷) 크고 넉넉한 옷(衤)” -> “넉넉하다, 너그럽다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1250/"},"堅":{"id":1239,"char":"堅","hun":"굳을 견","meaning":"“굳을 견”. 단단하다, 굳다","on":"ケン","kun":"かた(い)","explanation":["堅 = 臣 + 又 + 土。","「臣」는 본래 “눈동자”를 그린 글자입니다(링크 참조).","「又」는 “손”을 뜻합니다.","「土」는 “흙, 땅”을 뜻합니다.","堅는 “땅(土)을 바라보며(臣) 단단히 다지다(又)” -> “단단하다, 굳다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1251/"},"訳":{"id":1240,"char":"訳","hun":"번역할 역","meaning":"“번역할 역”. 번역, 이유","on":"ヤク","kun":"わけ","explanation":["訳 = 言 + 尺。","「言」는 “말하다”라는 뜻입니다.","尺는 여기서는 “말고삐”를 그린 모양자입니다.","訳는,","“말을 타고(尺) 온 외국 사신의 말(言)을 통역하다” -> “번역하다, 내용”","“사신이 온 이유” -> “이유”","라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1252/"},"芝":{"id":1241,"char":"芝","hun":"지초 지","meaning":"“지초 지”. 잔디","on":"","kun":"しば","explanation":["芝 = 艹 + 之。","「艹」는 “풀”을 뜻합니다.","之는 여기서는 “오솔길”을 그린 모양자입니다.","芝는 “잔디(艹)가 자라난 오솔길(之)” -> “잔디”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1253/"},"綱":{"id":1242,"char":"綱","hun":"벼리 강","meaning":"“벼리 강”. 밧줄, 일의 뼈대","on":"コウ","kun":"つな","explanation":["綱 = 糸 + 岡。","(의미부) 「糸」는 “실”을 뜻합니다.","(소리부 겸 의미부) 「岡」(コウ)는 “강하다”라는 뜻의 글자로, “산(山) 위에 쳐놓은 쇠그물”을 그린 것입니다(링크 참조).","綱는 “튼튼한(岡) 밧줄(糸)” -> “밧줄, (중심이 되는) 뼈대”라는 뜻의 글자입니다.","(岡는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1254/"},"典":{"id":1243,"char":"典","hun":"법 전","meaning":"“법 전”. 경전, 중요한 책, 기준, 규칙","on":"テン","kun":"","explanation":["典는 “대나무 죽간을 두 손으로 받든 모습”을 그린 상형문자입니다.","“경전을 두 손으로 받들다” -> “경전, 중요한 책, 기준, 규칙”이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/1255/"},"賀":{"id":1244,"char":"賀","hun":"하례할 하","meaning":"“하례할 하”. 축하하다","on":"ガ","kun":"","explanation":["賀 = 加 + 貝。","(소리부 겸 의미부) 「加」(カ)는 “더하다, 보태다”라는 뜻입니다.","(의미부) 「貝」는 “돈, 재물”을 뜻합니다.","賀는 “축의금(貝)을 보태다(加)” -> “축하하다”라는 뜻의 글자입니다.","(加는 소리부(カ -> ガ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1256/"},"扱":{"id":1245,"char":"扱","hun":"거둘 급","meaning":"“거둘 급”. 다루다, 취급하다","on":"","kun":"あつか(う)","explanation":["扱 = 扌 + 及。","「扌」는 “손”을 뜻합니다.","「及」는 “미치다, 이르다”라는 뜻입니다.","扱는 “손(扌)이 미치다(及)” -> “다루다, 취급하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1257/"},"顧":{"id":1246,"char":"顧","hun":"돌아볼 고","meaning":"“돌아볼 고”. 돌아보다, 돌이켜보다","on":"コ","kun":"かえり(みる)","explanation":["顧 = 雇 + 頁。","(소리부 겸 의미부) 「雇」(コ)는 “고용하다”라는 뜻입니다.","(의미부) 「頁」는 “머리”를 뜻합니다.","顧는 “직장을 은퇴하는 고용인(雇)이 그간의 추억을 돌이켜보다(頁)” -> “돌아보다, 돌이켜보다”라는 뜻의 글자입니다.","(雇는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1258/"},"訟":{"id":1247,"char":"訟","hun":"송사할 송","meaning":"“송사할 송”. 소송하다","on":"ショウ","kun":"","explanation":["訟 = 言 + 公。","「言」는 “말하다”라는 뜻입니다.","「公」는 “공적인, 공공의”라는 뜻입니다.","訟는 “억울함을 공공기관(公)에 호소하다(言)” -> “소송하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1259/"},"戒":{"id":1248,"char":"戒","hun":"경계할 계","meaning":"“경계할 계”. 경계하다, 금지하다, 계율","on":"カイ","kun":"いまし(める)","explanation":["戒 = 戈 + 廾。","「戈」는 “창”을 뜻합니다.","廾는 여기서는 “두 손을 치켜든 모습”을 그린 모양자입니다.","戒는 “창(戈)을 들고(廾) 보초를 서는 병사” -> “경계하다, 금지하다, 계율”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1260/"},"祉":{"id":1249,"char":"祉","hun":"복 지","meaning":"“복 지”. 행복, 복지","on":"シ","kun":"","explanation":["祉 = 礻 + 止。","(의미부) 「礻」는 “신, 종교, 고대의 비석”을 뜻합니다.","(소리부 겸 의미부) 「止」(シ)는 “멈추다”라는 뜻입니다.","祉는 “신을 모시는 비석(礻) 앞에 멈춰서서(止) 행복을 기원하다” -> “행복, 복지”라는 뜻의 글자입니다.","(止는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1261/"},"誉":{"id":1250,"char":"誉","hun":"명예 예","meaning":"“명예 예”. 칭찬하다, 명예","on":"ヨ","kun":"ほま(れ)","explanation":["誉 = 兴 + 言。","兴는 여기서는 「挙」가 축약된 것으로, “들어올리다”라는 뜻입니다.","「言」는 “말하다”라는 뜻입니다.","誉는 “말(言)로 띄워주다(兴)” -> “칭찬하다, 명예”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1262/"},"歓":{"id":1251,"char":"歓","hun":"기뻐할 환","meaning":"“기뻐할 환”. 기쁨, 즐거움","on":"カン","kun":"","explanation":["歓 = 𮥶 + 欠。","(소리부 겸 의미부) 「𮥶」(カン)은 “새장 안에 잡힌 새”를 뜻합니다.","(의미부) 「欠」는 “입을 벌린 사람”을 뜻합니다.","歓는 “희귀한 새를 잡아(𮥶) 환성을 지르다(欠)” -> “기쁨, 즐거움”이라는 뜻의 글자입니다.","(𮥶는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1263/"},"奏":{"id":1252,"char":"奏","hun":"아뢸 주","meaning":"“아뢸 주”. 연주하다","on":"ソウ","kun":"かな(でる)","explanation":["奏 = 𡗗 + 天。","𡗗는 여기서는 「春」가 축약된 것으로, “봄”을 뜻합니다.","「天」는 “하늘”을 뜻합니다.","奏는 “봄(春)의 하늘(天)에서 들려오는 아름다운 새소리” -> “연주하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1264/"},"勧":{"id":1253,"char":"勧","hun":"권할 권","meaning":"“권할 권”. 권고하다, 장려하다","on":"カン","kun":"すす(める)","explanation":["勧 = 𮥶 + 力。","(소리부 겸 의미부) 「𮥶」(カン)은 “새장 안에 갇힌 새”를 뜻합니다.","(의미부) 「力」는 “힘”을 뜻합니다.","勧는 “무력(力)으로 적을 가둬두고(𮥶) 항복을 권하다” -> “권고하다, 장려하다”라는 뜻의 글자입니다.","(𮥶는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1265/"},"騒":{"id":1254,"char":"騒","hun":"떠들 소","meaning":"“떠들 소”. 시끄럽다, 소란하다","on":"ソウ","kun":"さわ(ぐ)","explanation":["騒 = 馬 + 又 + 虫。","「馬」는 “말”을 뜻합니다.","「又」는 “손”을 뜻합니다.","「虫」는 “벌레”를 뜻합니다.","騒는 “말(馬)의 등 위에 벌레(虫)를 얹어놓다(又)”라는 뜻입니다.","벌레가 갑자기 등을 깨물면 말이 놀라서 날뛸 것입니다.","“놀라서 날뛰는 말” -> “시끄럽다, 소란하다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/1266/"},"閥":{"id":1255,"char":"閥","hun":"문벌 벌","meaning":"“문벌 벌”. 문벌, 파벌","on":"バツ","kun":"","explanation":["閥 = 門 + 亻 + 戈。","「門」는 “문”을 뜻합니다.","「亻」는 “사람”을 뜻합니다.","「戈」는 “창”을 뜻합니다.","閥는 “창(戈)을 들고 문(門)을 지키며(亻) 자기 파벌만 들여보내다” -> “파벌, 문벌”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1267/"},"甲":{"id":1256,"char":"甲","hun":"갑옷 갑","meaning":"“갑옷 갑”. 등딱지, 갑옷","on":"コウ、カン","kun":"","explanation":["甲는 “거북의 등딱지와 꼬리”를 그린 상형문자입니다.","“단단한 거북의 등딱지” -> “갑옷”이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/1268/"},"縄":{"id":1257,"char":"縄","hun":"줄 승","meaning":"“줄 승”. 줄, 노끈","on":"ジョウ","kun":"なわ","explanation":["縄 = 糸 + 亀。","「糸」는 “실”을 뜻합니다.","亀(“거북 균”)은 “거북”을 뜻하는 상용한자입니다(여기서는 위쪽의 ⺈가 생략되어 있습니다).","縄는 “거대한 바다거북(亀)을 운반하기 위한 굵은 밧줄(糸)” -> “줄, 노끈”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1269/"},"郷":{"id":1258,"char":"郷","hun":"시골 향","meaning":"“시골 향”. 시골, 고향","on":"キョウ、ゴウ","kun":"","explanation":["郷 = 乡 + 皀 + ⻏。","중간의 「皀」는 “음식이 담긴 식기”를 그린 글자입니다.","양 옆의 乡+⻏는 여기서는 “(음식을 가운데 두고 앉은) 사람들”을 그린 모양자입니다.","(위 그림을 참조해 주세요.)","郷는 “음식(皀)을 먹으며 정답게 이야기를 나누는 사람들(乡+⻏)” -> “시골, 고향”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1270/"},"揺":{"id":1259,"char":"揺","hun":"흔들릴 요","meaning":"“흔들릴 요”. 흔들다, 움직이다, 흔들리다","on":"ヨウ","kun":"ゆ(る)、ゆ(する)、ゆ(れる)、ゆ(らぐ)、ゆ(るぐ)、ゆ(さぶる)、ゆ(すぶる)","explanation":["揺 = 扌 + ⺤ + 𠙻。","「扌」는 “손”을 뜻합니다.","「⺤」는 “손”을 뜻합니다.","𠙻는 여기서는 “뚜껑이 꽉 낀 항아리”를 그린 모양자입니다.","揺는 “뚜껑이 꽉 낀 항아리(𠙻)를 두 손으로 잡고(扌+⺤) 억지로 열다” -> “흔들리다, 움직이다, 흔들다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1271/"},"免":{"id":1260,"char":"免","hun":"면할 면","meaning":"“면할 면”. 면하다, 허가하다","on":"メン","kun":"まぬか(れる)","explanation":["免는 “투구를 쓴 사람”을 그린 상형문자입니다.","“전장에서 투구 덕분에 죽음을 면하다” -> “면하다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/1272/"},"既":{"id":1261,"char":"既","hun":"이미 기","meaning":"“이미 기”. 이미, 벌써, 이전에","on":"キ","kun":"すで(に)","explanation":["既 = 皀 + 旡。","「皀」는 “음식이 담긴 식기”를 뜻합니다.","旡는 여기서는 “앉은 채 고개를 뒤로 돌린 사람”을 그린 모양자입니다.","既는 “식사(皀)를 마치고 고개를 뒤로 돌려(旡) 트림하고 있는 사람“을 그린 글자입니다.","“식사가 이미 끝나다” -> “이미, 벌써, 이전에”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/1273/"},"薦":{"id":1262,"char":"薦","hun":"천거할 천","meaning":"“천거할 천”. 천거하다, 추천하다","on":"セン","kun":"すす(める)","explanation":["薦 = 艹 + 廌。","「艹」는 “풀”을 뜻합니다.","廌는 “뿔이 달린 해태”를 그린 상형문자로, 「鹿」(사슴)에서 아래쪽의 比만 바꾼 것입니다.","(해태는 선악을 판별한다고 알려진 상상의 동물입니다.)","薦는 “수풀(艹)안에 숨어있는 해태(廌)”라는 뜻입니다.","여기서 “해태”란 “뛰어난 인물”을 의미합니다.","“세상에 알려지지 않고 초야에 묻혀있는 뛰어난 인물을 천거하다” -> “천거하다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/1274/"},"隣":{"id":1263,"char":"隣","hun":"이웃 린","meaning":"“이웃 린”. 이웃하다","on":"リン","kun":"とな(る)、となり","explanation":["隣 = ⻖ + 米 + 舛。","「⻖」는 “언덕”을 뜻합니다.","「米」는 “쌀”을 뜻합니다.","「舛」는 “두 발”을 뜻합니다.","隣는 “쌀(米)을 짊어지고 언덕(⻖) 너머 이웃마을에 가다(舛)” -> “이웃, 이웃하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1275/"},"華":{"id":1264,"char":"華","hun":"빛날 화","meaning":"“빛날 화”. 화려하다, 빛나다, 꽃","on":"カ、ケ","kun":"はな","explanation":["華는 “활짝 핀 화려한 꽃(艹)”을 그린 상형문자입니다."],"sourceUrl":"https://nihongokanji.com/1276/"},"範":{"id":1265,"char":"範","hun":"법 범","meaning":"“법 범”. 모범, 규범, 틀, 범위","on":"ハン","kun":"","explanation":["範 = 𥫗 + 車 + 㔾。","「𥫗」는 “대나무 죽간”을 뜻합니다.","「車」는 “수레”를 뜻합니다.","「㔾」는 “무릎꿇은 사람”을 뜻합니다.","範는 “먼 길을 떠나기 전에(車) 죽간에 적힌 절차대로(𥫗) 안전을 기원하는 제사를 지내다(㔾)”라는 뜻입니다.","“제사 형식과 절차” -> 모범, 규범, 틀, 범위”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/1277/"},"隠":{"id":1266,"char":"隠","hun":"숨을 은","meaning":"“숨을 은”. 숨다, 숨기다","on":"イン","kun":"かく(す)、かく(れる)","explanation":["隠 = ⻖ + ⺤ + 急。","「⻖」는 “언덕, 산”을 뜻합니다.","「⺤」는 “손”을 뜻합니다.","「急」는 “급하다”라는 뜻입니다.","隠는 “전쟁통에 아이의 손(⺤)을 잡고 황급히(急) 산속(⻖)으로 숨다” -> “숨다, 숨기다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1278/"},"徳":{"id":1267,"char":"徳","hun":"덕 덕","meaning":"“덕 덕”. 덕, 도덕","on":"トク","kun":"","explanation":["徳 = 彳 + 十 + 罒 + 心。","「彳」는 “길”을 뜻합니다.","十+罒는 여기서는 「直」가 변형된 것으로, “곧다”라는 뜻입니다(1125.「聴」 모양 해설 참조).","「心」는 “마음”을 뜻합니다.","徳는 “곧은(直) 마음(心)으로 바른 길(彳)을 나아가다” -> “덕, 도덕”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1279/"},"哲":{"id":1268,"char":"哲","hun":"밝을 철","meaning":"“밝을 철”. 철학, 총명함, 사리에 밝음","on":"テツ","kun":"","explanation":["哲 = 折 + 口。","「折」는 “꺾다”라는 뜻입니다.","「口」는 “입”을 뜻합니다.","哲는 “조리있는 언변(口)으로 상대방을 꺾다(折)” -> “총명한, 사리에 밝은, 철학”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1280/"},"杉":{"id":1269,"char":"杉","hun":"삼나무 삼","meaning":"“삼나무 삼”. 삼나무","on":"","kun":"すぎ","explanation":["杉 = 木 + 彡。","「木」는 “나무”를 뜻합니다.","彡는 여기서는 「三」가 변형된 것으로, “3”을 뜻합니다.","杉는 “삼(彡) 나무(木)” -> “삼나무”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1281/"},"里":{"id":1270,"char":"里","hun":"마을 리","meaning":"“마을 리”. 마을","on":"リ","kun":"さと","explanation":["里 = 田 + 土。","「土」는 “흙, 땅”을 뜻합니다.","「田」는 “밭”을 뜻합니다.","里는 “논밭(田)이 늘어선 땅(土)” -> “마을”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1282/"},"釈":{"id":1271,"char":"釈","hun":"풀 석","meaning":"“풀 석”. 해석하다, 설명하다","on":"シャク","kun":"","explanation":["釈 = 釆 + 尺。","釆는 여기서는 「来」가 변형된 것으로, “동물의 발자국”을 뜻합니다(링크 참조).","尺는 여기서는 “말발굽”을 그린 모양자입니다.","釈는 “말발굽(尺) 모양의 발자국(釆)으로 적이 향한 방향을 식별해내다” -> “해석하다, 설명하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1283/"},"己":{"id":1272,"char":"己","hun":"몸 기","meaning":"“몸 기”. 나, 자신","on":"コ、キ","kun":"おのれ","explanation":["「己」는 “무릎꿇은 사람”을 뜻합니다.","“무릎꿇은 사람” -> “사람” -> “나, 자신”이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/1284/"},"妥":{"id":1273,"char":"妥","hun":"온당할 타","meaning":"“온당할 타”. 타당하다, 온당하다","on":"ダ","kun":"","explanation":["妥 = ⺤ + 女。","「⺤」는 “손”을 뜻합니다.","「女」는 “여자”를 뜻합니다.","妥는 “순종적인 여자(女)는 머리를 쓰다듬어(⺤) 칭찬해주는 것이 타당하다” -> “온당하다, 타당하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1285/"},"威":{"id":1274,"char":"威","hun":"위엄 위","meaning":"“위엄 위”. 두려움, 위엄, 권위","on":"イ","kun":"","explanation":["威 = 戌 + 女。","「戌」는 “창을 든 손”을 뜻합니다.","「女」는 “여자”를 뜻합니다.","威는 “창을 들고(戌) 여자(女)를 위협하다” -> “두려움, 위엄, 권위”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1286/"},"豪":{"id":1275,"char":"豪","hun":"호걸 호","meaning":"“호걸 호”. 호걸, 뛰어남","on":"ゴウ","kun":"","explanation":["豪 = 高 + 豕。","(소리부 겸 의미부) 「高」(コウ)는 “높다”라는 뜻입니다.","(의미부) 「豕」는 “돼지”를 뜻합니다.","豪는 “멧돼지(豕) 무리의 우두머리(高) ” -> “호걸, 뛰어남”이라는 뜻의 글자입니다.","(高는 소리부(コウ -> ゴウ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1287/"},"熊":{"id":1276,"char":"熊","hun":"곰 웅","meaning":"“곰 웅”. 곰","on":"","kun":"くま","explanation":["熊 = 能 + 灬。","「能」는 본래 “곰”을 그린 상형문자입니다(링크 참조).","灬는 여기서는 “(곰의) 네 발”을 그린 모양자입니다.","熊는 “곰(能)의 네 발(灬)” -> “곰”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1288/"},"滞":{"id":1277,"char":"滞","hun":"막힐 체","meaning":"“막힐 체”. 머무르다, 막히다","on":"タイ","kun":"とどこお(る)","explanation":["滞 = 氵 + 帯。","(의미부) 「氵」는 “물”을 뜻합니다.","(소리부 겸 의미부) 「帯」(タイ)는 “허리띠, 두르다”라는 뜻입니다.","滞는 “물(氵)이 흐르지 못하고 둥글게(帯) 고이다” -> “머무르다, 막히다”라는 뜻의 글자입니다.","(帯는 소리부도 겸함)."],"sourceUrl":"https://nihongokanji.com/1289/"},"微":{"id":1278,"char":"微","hun":"작을 미","meaning":"“작을 미”. 미세한, 작은","on":"ビ","kun":"","explanation":["微 = 徴 + ⺎。","「徴」는 “특징, 징표”를 뜻합니다.","⺎는 여기서는 “달팽이”를 그린 모양자입니다.","微는 “달팽이(⺎)의 특징(徴)은 작다는 것이다” -> “미세한, 작은”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1290/"},"隆":{"id":1279,"char":"隆","hun":"높을 륭","meaning":"“높을 륭”. 높이 오르다, 번성하다","on":"リュウ","kun":"","explanation":["隆 = ⻖ + 夂 + 生。","「⻖」는 “언덕”을 뜻합니다.","「夂」는 “발”을 뜻합니다.","「生」는 “생명”을 뜻합니다.","隆는 “활기찬(生) 발걸음(夂)으로 언덕(⻖)을 오르다” -> “높이 오르다, 번성하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1291/"},"症":{"id":1280,"char":"症","hun":"증세 증","meaning":"“증세 증”. 증상, 증세","on":"ショウ","kun":"","explanation":["症 = 疒 + 正。","(의미부) 「疒」는 “질병, 질환”을 뜻합니다.","(소리부 겸 의미부) 「正」(ショウ)는 “바르다”라는 뜻입니다.","症는 “병(疒)의 증상을 바르게(正) 파악하다” -> “증세, 증상”이라는 뜻의 글자입니다.","(正는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1292/"},"暫":{"id":1281,"char":"暫","hun":"잠깐 잠","meaning":"“잠깐 잠”. 잠깐","on":"ザン","kun":"","explanation":["暫 = 車 + 斤 + 日。","「車」는 “수레, 차”를 뜻합니다.","「斤」는 “도끼”를 뜻합니다.","「日」는 “날짜”를 뜻합니다. 여기서는 “날짜” -> “시간”이라는 뜻입니다.","暫는 “수레(車)를 도끼(斤)로 부수는 데는 잠깐이면(日) 충분하다” -> “잠깐”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1293/"},"忠":{"id":1282,"char":"忠","hun":"충성 충","meaning":"“충성 충”. 충성스러운","on":"チュウ","kun":"","explanation":["忠 = 中 + 心。","(소리부 겸 의미부) 「中」(チュウ)는 “중심, 중앙”을 뜻합니다.","(의미부) 「心」는 “마음”을 뜻합니다.","忠는 “언제나 중심(中)을 잃지 않는 충실한 마음(心)” -> “충성스럽다”라는 뜻의 글자입니다.","(中는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1294/"},"倉":{"id":1283,"char":"倉","hun":"곳집 창","meaning":"“곳집 창”. 창고, 곳간","on":"ソウ","kun":"くら","explanation":["倉 = 合 + 戸。","合는 여기서는 “지붕이 달린 커다란 창고”를 그린 모양자입니다.","「戸」는 “문”을 뜻합니다.","倉는 “커다란 문(戸)이 달린 창고(合)” -> “창고”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1295/"},"肝":{"id":1284,"char":"肝","hun":"간 간","meaning":"“간 간”. 간, 중요한","on":"カン","kun":"きも","explanation":["肝 = 月 + 干。","(의미부) 「月」는 “신체의 일부”를 뜻합니다.","(소리부 겸 의미부) 「干」(カン)은 “방패”를 뜻합니다.","肝는 “외부의 독소를 막는(干) 신체기관(月)” -> “간, 중요한”이라는 뜻의 글자입니다.","(干는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1296/"},"喚":{"id":1285,"char":"喚","hun":"부를 환","meaning":"“부를 환”. 부르다, 외치다","on":"カン","kun":"","explanation":["喚 = 口 + 奐。","(의미부) 「口」는 “입”을 뜻합니다.","(소리부 겸 의미부) 「奐」(カン)은 “태어나는 아기를 받아내는 모습”을 그린 글자입니다.","喚는 “아기가 태어나며(奐) 첫 울음을 외치다(口)” -> “부르다, 외치다”라는 뜻의 글자입니다.","(奐는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1297/"},"沿":{"id":1286,"char":"沿","hun":"물 따라갈 연","meaning":"“물 따라갈 연”. (물/흐름 등을) 따라가다","on":"エン","kun":"そ(う)","explanation":["沿 = 氵 + 㕣。","「氵」는 “물”을 뜻합니다.","㕣는 여기서는 “작은 조각배”를 그린 모양자입니다.","沿는 “강가(氵)를 따라 흘러가는 조각배(㕣)” -> “(물/흐름을) 따라가다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1298/"},"妙":{"id":1287,"char":"妙","hun":"묘할 묘","meaning":"“묘할 묘”. 묘하다, 신묘하다, 아름답다","on":"ミョウ","kun":"","explanation":["妙 = 女 + 少。","「女」는 “여자”를 뜻합니다.","「少」는 “적다”라는 뜻입니다.","妙는 “어리고 귀여운(少) 여자(女)” -> “아름답다” -> “묘하다, 신묘하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1299/"},"唱":{"id":1288,"char":"唱","hun":"부를 창","meaning":"“부를 창”. 소리내 읽다, 노래를 부르다","on":"ショウ","kun":"とな(える)","explanation":["唱 = 口 + 昌。","「口」는 “입”을 뜻합니다.","昌는 「曰」두 개가 합쳐진 것으로, “말하다“라는 뜻입니다.","唱는 “입(口)을 열어 말하다(昌)” -> “소리내 읽다, 노래를 부르다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1300/"},"索":{"id":1289,"char":"索","hun":"찾을 색","meaning":"“찾을 색”. 찾다","on":"サク","kun":"","explanation":["索 = 十 + 冖 + 糸。","「糸」는 “실”을 뜻합니다.","冖는 여기서는 “천장”을 그린 모양자입니다.","十는 여기서는 “(천장에 매달린) 새끼줄의 매듭”을 그린 모양자입니다.","索는 “어두운 밤에 허공을 더듬어 천장(冖)에 매달아놓은(十) 새끼줄(糸)을 찾다” -> “찾다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1301/"},"誠":{"id":1290,"char":"誠","hun":"정성 성","meaning":"“정성 성”. 진심의, 성실한","on":"セイ","kun":"まこと","explanation":["誠 = 言 + 成。","(의미부) 「言」는 “말하다”라는 뜻입니다.","(소리부 겸 의미부) 「成」(セイ)는 “이루다, 성취하다”라는 뜻입니다.","誠는 “진심을 갖춘(成) 말(言)” -> “진심의, 성실한”이라는 뜻의 글자입니다.","(成는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1302/"},"襲":{"id":1291,"char":"襲","hun":"엄습할 습","meaning":"“엄습할 습”. 습격하다, 세습하다","on":"シュウ","kun":"おそ(う)","explanation":["襲 = 龍 + 衣。","「衣」는 “옷”을 뜻합니다.","龍는 “하늘로 승천하는 용”을 그린 상형문자입니다. 아래 그림을 참조해 주세요.","襲는 “용(龍)의 무늬가 수놓인 임금의 옷(衣)” = “곤룡포”라는 뜻입니다.","“임금이 죽다” -> “죽음이 엄습하다” -> “습격하다”","“임금이 죽고 아들이 왕위를 계승하다” -> “세습하다”","라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/1303/"},"懇":{"id":1292,"char":"懇","hun":"간절할 간","meaning":"“간절할 간”. 간절하다","on":"コン","kun":"ねんご(ろ)","explanation":["懇 = 豸 + 艮 + 心。","(소리부 겸 의미부) 「艮」(コン)은 “천민”을 뜻합니다.","(의미부) 豸는 여기서는 “(천민이 등에 진) 등짐”을 그린 모양자입니다.","(의미부) 「心」는 “마음”을 뜻합니다.","懇는 “힘든 노역(豸) 중인 천민(艮)의 해방되고 싶다는 간절한 마음(心)” -> “간절하다”라는 뜻의 글자입니다.","(艮는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1304/"},"俳":{"id":1293,"char":"俳","hun":"배우 배","meaning":"“배우 배”. 배우, 광대","on":"ハイ","kun":"","explanation":["俳 = 亻 + 非。","(의미부) 「亻」는 “사람”을 뜻합니다.","(소리부 겸 의미부) 「非」(ヒ)는 “아니다”라는 뜻입니다.","俳는 “자신이 아닌(非) 사람(亻)을 연기하다” -> “배우”라는 뜻의 글자입니다.","(非는 소리부(ヒ -> ハイ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1305/"},"柄":{"id":1294,"char":"柄","hun":"자루 병","meaning":"“자루 병”. 자루, 손잡이, 성질/상태","on":"ヘイ","kun":"がら、え","explanation":["柄 = 木 + 丙。","(의미부) 「木」는 “나무”를 뜻합니다.","(소리부) 丙(ヘイ)는 “갑을병”의 “병”을 뜻하는 상용한자입니다.","다만 여기서는 소리부의 역할만 하고 있습니다.","柄는 “나무(木)로 만든 손잡이” -> “자루, 손잡이”라는 뜻의 글자입니다(丙는 소리부)."],"sourceUrl":"https://nihongokanji.com/1306/"},"驚":{"id":1295,"char":"驚","hun":"놀랄 경","meaning":"“놀랄 경”. 놀라다","on":"キョウ","kun":"おどろ(く)、おどろ(かす)","explanation":["驚 = 敬 + 馬。","(소리부 겸 의미부) 「敬」(ケイ)는 본래 “개를 때리는 모습”을 그린 글자입니다(링크 참조).","(의미부) 「馬」는 “말”을 뜻합니다.","驚는 “말(馬)을 때렸더니(敬) 말이 놀라 날뛰다” -> “놀라다”라는 뜻의 글자입니다.","(敬는 소리부(ケイ -> キョウ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1307/"},"麻":{"id":1296,"char":"麻","hun":"삼 마","meaning":"“삼 마”. 삼베, 마비","on":"マ","kun":"あさ","explanation":["麻 = 广 + 林。","「广」는 “건물, 집”을 뜻합니다.","林는 여기서는 “대마(삼베의 원료)”를 그린 모양자입니다. 아래 그림을 참조해 주세요.","麻는 “수확한 대마(林)를 집(广)에서 말리는 모습“을 그린 글자입니다.","“대마를 말려서 삼베를 만들다” -> “삼베”","“대마의 잎과 꽃에 있는 마비 성분” -> “마비”","라는 의미입니다.","(대마의 잎과 꽃에는 생물을 일시적으로 마비시키는 성분이 있다고 합니다.)"],"sourceUrl":"https://nihongokanji.com/1308/"},"剤":{"id":1297,"char":"剤","hun":"약제 제","meaning":"“약제 제”. 약, 약을 조제하다","on":"ザイ","kun":"","explanation":["剤 = 斉 + 刂。","(소리부 겸 의미부) 斉는 여기서는 「済」(サイ)가 축약된 것으로, “끝나다, 마치다”라는 뜻입니다.","(의미부) 「刂」는 “칼”을 뜻합니다.","剤는 “약재를 자르는(刂) 작업을 마치다(済)” -> “약을 조제하다, 약”이라는 뜻의 글자입니다.","(斉->済는 소리부(サイ -> ザイ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1309/"},"瀬":{"id":1298,"char":"瀬","hun":"여울 뢰","meaning":"“여울 뢰”. 여울","on":"","kun":"せ","explanation":["瀬 = 氵 + 頼。","「氵」는 “물”을 뜻합니다.","「頼」는 “의뢰하다, 의지하다”라는 뜻입니다.","瀬는 “수심(氵)이 얕아 빠질 염려 없이 안심되는(頼) 개울가” -> “여울”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1310/"},"趣":{"id":1299,"char":"趣","hun":"뜻 취","meaning":"“뜻 취”. 취지, 취향, 취미","on":"シュ","kun":"おもむき","explanation":["趣 = 走 + 取。","(의미부) 「走」는 “달리다”라는 뜻입니다.","(소리부 겸 의미부) 「取」(シュ)는 “집다, 쥐다”라는 뜻입니다.","趣는 “자신이 좋아하는 것을 달려가서(走) 잡다(取)” -> “취향, 취미, 취지”라는 뜻의 글자입니다.","(取는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1311/"},"陥":{"id":1300,"char":"陥","hun":"빠질 함","meaning":"“빠질 함”. 함정, 빠지다, 함락하다","on":"カン","kun":"おちい(る)、おとしい(れる)","explanation":["陥 = ⻖ + ⺈ + 旧。","「⻖」는 “언덕, 산”을 뜻합니다.","「⺈」는 “칼”을 뜻합니다.","旧는 여기서는 “구덩이, 함정”을 그린 모양자입니다.","陥는 “언덕(⻖) 위에 있던 사람을 칼(⺈)로 찔러 구덩이(旧) 안에 빠뜨리다” -> “함정, 빠지다, 함락하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1312/"},"斎":{"id":1301,"char":"斎","hun":"재계할/집 재, 상복 자","meaning":"“재계할/집 재, 상복 자”. 심신을 깨끗이 하다, 장례식","on":"サイ","kun":"","explanation":["斎 = 文 + 丿丨 + 示。","「文」는 본래 “사람”을 그린 글자입니다(링크 참조).","丿丨는 여기서는 “흐르는 물”을 그린 모양자입니다.","「示」는 “신, 종교, 고대의 비석”을 뜻합니다.","斎는 “종교 의식(示)에 앞서 몸(文)을 깨끗이 씻다(丿丨) -> “심신을 깨끗이 하다, 장례식”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1313/"},"貫":{"id":1302,"char":"貫","hun":"꿸 관","meaning":"“꿸 관”. 꿰뚫다","on":"カン","kun":"つらぬ(く)","explanation":["貫 = 毌 + 貝。","毌는 “판자에 쇠막대를 꿰어놓은 모습”을 그린 모양자입니다.","「貝」는 “돈, 재물”을 뜻합니다.","貫는 “동전(貝)을 한 줄로 꿰어놓다(毌)” -> “꿰다, 관통하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1314/"},"仙":{"id":1303,"char":"仙","hun":"신선 선","meaning":"“신선 선”. 신선","on":"セン","kun":"","explanation":["仙 = 亻 + 山。","「亻」는 “사람”을 뜻합니다.","「山」는 “산”을 뜻합니다.","仙는 “산속(山)의 신선(亻)” -> “신선, 수행자”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1315/"},"慰":{"id":1304,"char":"慰","hun":"위로할 위","meaning":"“위로할 위”. 위로하다","on":"イ","kun":"なぐさ(む)、なぐさ(める)","explanation":["慰 = 尸 + 示 + 寸 + 心。","「尸」는 “앉아있는 사람”을 뜻합니다.","「示」는 “신, 종교, 고대의 비석”을 뜻합니다.","「寸」는 “손”을 뜻합니다.","「心」는 “마음”을 뜻합니다.","慰는 “자리에 앉아(尸) 신(示)에게 기도(寸)를 올리고 마음(心)을 위로받다” -> “위로하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1316/"},"序":{"id":1305,"char":"序","hun":"차례 서","meaning":"“차례 서”. 처음, 순서","on":"ジョ","kun":"","explanation":["序 = 广 + 予。","「广」는 “집, 건물”을 뜻합니다.","「予」는 “미리”라는 뜻입니다.","序는 “집(广)을 짓기 전에 먼저(予) 해둬야 할 일들” -> “처음, 차례”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1317/"},"旬":{"id":1306,"char":"旬","hun":"열흘 순","meaning":"“열흘 순”. 열흘, 10, 가득 차다, 제철","on":"ジュン、シュン","kun":"","explanation":["旬 = 勹 + 日。","勹는 여기서는 “한 바퀴 돌다”라는 추상적인 의미를 표현한 모양자입니다.","「日」는 “날짜”를 뜻합니다.","旬는 “날짜(日)가 한 바퀴 돌다(勹)” -> “열흘, 10, 가득 차다, 제철”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1318/"},"兼":{"id":1307,"char":"兼","hun":"겸할 겸","meaning":"“겸할 겸”. 겸하다","on":"ケン","kun":"か(ねる)","explanation":["兼는 “손(⺕)에 볏단 두 개를 동시에 쥔 모습”을 그린 상형문자입니다.","“볏단 두 개를 한꺼번에 쥐다” -> “겸하다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/1319/"},"聖":{"id":1308,"char":"聖","hun":"성인 성","meaning":"“성인 성”. 신성한, 성스러운","on":"セイ","kun":"","explanation":["聖 = 耳 + 口 + 王。","「耳」는 “귀”를 뜻합니다.","「口」는 “입”을 뜻합니다.","「王」는 “왕”을 뜻합니다.","聖는 “신하의 말(口)에 귀기울일(耳) 줄 아는 성군(王)” -> “신성한, 성스러운”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1320/"},"旨":{"id":1309,"char":"旨","hun":"뜻 지","meaning":"“뜻 지”. 뜻, 취지","on":"シ","kun":"むね","explanation":["旨 = 匕 + 日。","匕는 여기서는 「刀」가 뒤집힌 것으로, “칼”을 뜻합니다.","「日」는 “태양”을 뜻합니다.","旨는 “하늘(日)의 뜻에 따라 적에 맞서 싸우다(匕)” -> “뜻, 취지”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1321/"},"即":{"id":1310,"char":"即","hun":"곧 즉","meaning":"“곧 즉”. 즉시, 곧바로","on":"ソク","kun":"","explanation":["即 = 皀 + 卩。","「皀」는 “음식이 담긴 식기”를 뜻합니다.","「卩」는 “무릎꿇은 사람”을 뜻합니다.","即는 “식기(皀) 앞에 앉자마자(卩) 밥을 먹기 시작하다” -> “즉시, 곧바로”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1322/"},"柳":{"id":1311,"char":"柳","hun":"버들 류","meaning":"“버들 류”. 버드나무","on":"リュウ","kun":"やなぎ","explanation":["柳 = 木 + 卯。","「木」는 “나무”를 뜻합니다.","卯는 여기서는 “축 늘어진 버드나무 가지”를 그린 모양자입니다.","柳는 “버드나무(木)의 늘어진 가지(卯)” -> “버드나무”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1323/"},"舎":{"id":1312,"char":"舎","hun":"집 사","meaning":"“집 사”. 숙소, 집, 저택","on":"シャ","kun":"","explanation":["舎는 “잠시 쉬어갈 수 있는 쉼터”를 그린 상형문자입니다.","“쉴 수 있는 곳” -> “숙소, 집, 저택”이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/1324/"},"偽":{"id":1313,"char":"偽","hun":"거짓 위","meaning":"“거짓 위”. 거짓, 가짜","on":"ギ","kun":"にせ、いつわ(る)","explanation":["偽 = 亻 + 為。","(의미부) 「亻」는 “사람”을 뜻합니다.","(소리부 겸 의미부) 「為」(イ)는 “하다, 행하다”라는 뜻입니다.","偽는 “다른 사람(亻)을 사칭하여 행동하다(為)” -> “거짓, 가짜”라는 뜻의 글자입니다.","(為는 소리부(イ -> ギ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1325/"},"覇":{"id":1314,"char":"覇","hun":"으뜸 패","meaning":"“으뜸 패”. 제패하다, 으뜸","on":"ハ","kun":"","explanation":["覇 = 覀 + 革 + 月。","「覀」는 “덮다”라는 뜻입니다.","「革」는 “가죽”을 뜻합니다.","「月」는 “고기”를 뜻합니다.","覇는 “곰을 맨손으로 때려잡아 가죽(革)을 덮고(覀) 고기(月)를 먹다” -> “으뜸, 제패하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1326/"},"詳":{"id":1315,"char":"詳","hun":"자세할 상","meaning":"“자세할 상”. 자세한, 상세한","on":"ショウ","kun":"くわ(しい)","explanation":["詳 = 言 + 羊。","(의미부) 「言」는 “말하다”라는 뜻입니다.","(소리부 겸 의미부) 「羊」(ヨウ)는 “양”을 뜻합니다.","詳는 “양(羊)의 생김새를 자세히 묘사하다(言)” -> “자세하다, 상세하다”라는 뜻의 글자입니다.","(羊는 소리부(ヨウ -> ショウ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1327/"},"抵":{"id":1316,"char":"抵","hun":"막을 저","meaning":"“막을 저”. 막다, 저항하다","on":"テイ","kun":"","explanation":["抵 = 扌 + 氐。","(의미부) 「扌」는 “손”을 뜻합니다.","(소리부 겸 의미부) 「氐」(テイ)는 “낮다”라는 뜻입니다.","抵는 “신분이 낮은(氐) 사람들이 힘을 모아 저항하다(扌)” -> “막다, 저항하다”라는 뜻의 글자입니다.","(氐는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1328/"},"脅":{"id":1317,"char":"脅","hun":"위협할 협","meaning":"“위협할 협”. 위협하다","on":"キョウ","kun":"おど(す)、おど(かす)、おびや(かす)","explanation":["脅 = 劦 + 月。","劦는 “힘(「力」)” 세 개를 합쳐놓은 것입니다.","「月」는 “신체의 일부”를 뜻합니다.","脅는 “여러 명의 폭력(劦)으로 신체에(月) 위협을 가하다” -> “위협하다, 협박하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1329/"},"茂":{"id":1318,"char":"茂","hun":"무성할 무","meaning":"“무성할 무”. 무성하다, 풍성하다","on":"モ","kun":"しげ(る)","explanation":["茂 = 艹 + 戊。","「艹」는 “풀”을 뜻합니다.","「戊」는 “반달 모양의 낫이 달린 창”을 그린 글자입니다.","茂는 “무성하게 자란 잡초(艹)를 낫(戊)으로 베다” -> “무성하다, 풍성하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1330/"},"犠":{"id":1319,"char":"犠","hun":"희생 희","meaning":"“희생 희”. 희생","on":"ギ","kun":"","explanation":["犠 = 牜 + 義。","(의미부) 「牜」는 “소”를 뜻합니다.","(소리부 겸 의미부) 「義」(ギ)는 “의, 도리”를 뜻합니다.","고대에는 소가 신성한 동물로 여겨져 제사의 제물로 쓰이는 경우가 많았다고 합니다.","犠는 “소(牜)를 신에게 제물로 바쳐 도리(義)를 다하다” -> “희생”이라는 뜻의 글자입니다.","(義는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1331/"},"旗":{"id":1320,"char":"旗","hun":"기 기","meaning":"“기 기”. 깃발","on":"キ","kun":"はた","explanation":["旗 = 𭤨 + 其。","(의미부) 「𭤨」는 “바람에 나부끼는 깃발”을 그린 글자입니다.","(소리부) 「其」(キ)는 여기서는 소리부의 역할만 하고 있습니다.","旗는 “바람에 나부끼는 깃발(𭤨)” -> “깃발”이라는 뜻의 글자입니다(其는 소리부)."],"sourceUrl":"https://nihongokanji.com/1332/"},"距":{"id":1321,"char":"距","hun":"상거할 거","meaning":"“상거할 거”. 멀리 떨어지다, 거리","on":"キョ","kun":"","explanation":["距 = 足 + 巨。","(의미부) 「足」는 “발”을 뜻합니다.","(소리부 겸 의미부) 「巨」(キョ)는 “크다, 거대하다”라는 뜻입니다.","距는 “거대한(巨) 발(足)” -> “보폭이 크다” -> “멀리 떨어지다, 거리”라는 뜻의 글자입니다.","(巨는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1333/"},"雅":{"id":1322,"char":"雅","hun":"맑을 아","meaning":"“맑을 아”. 맑은, 우아한","on":"ガ","kun":"","explanation":["雅 = 牙 + 隹。","(소리부) 牙(ガ – “어금니 아”)는 “이, 어금니”를 뜻하는 상용한자입니다.","다만 여기서는 소리부의 역할만 하고 있습니다.","(의미부) 「隹」는 “새”를 뜻합니다.","雅는 “새(隹)가 지저귀는 맑은 소리” -> “우아하다, 맑다”라는 뜻의 글자입니다(牙는 소리부)."],"sourceUrl":"https://nihongokanji.com/1334/"},"飾":{"id":1323,"char":"飾","hun":"꾸밀 식","meaning":"“꾸밀 식”. 꾸미다, 장식","on":"ショク","kun":"かざ(る)","explanation":["飾 = 食 + 𠂉 + 巾。","「食」는 “먹다”라는 뜻입니다.","𠂉는 여기서는 “천장”을 그린 모양자입니다.","「巾」는 “수건, 천”을 뜻합니다.","飾는 “연회(食)를 위해 천장(𠂉)에 휘장(巾)을 달다” -> “꾸미다, 장식”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1335/"},"網":{"id":1324,"char":"網","hun":"그물 망","meaning":"“그물 망”. 그물, 망","on":"モウ","kun":"あみ","explanation":["網 = 糸 + 𦉰 + 亡。","(의미부) 「糸」는 “실”을 뜻합니다.","(의미부) 𦉰는 「罒」가 변형된 것으로, “쇠그물”을 뜻합니다.","(소리부) 「亡」(モウ)는 여기서는 소리부의 역할만 하고 있습니다.","網는 “밧줄(糸)을 엮어서 만든 쇠그물(𦉰)” -> “그물, 망”이라는 뜻의 글자입니다(亡는 소리부)."],"sourceUrl":"https://nihongokanji.com/1336/"},"竜":{"id":1325,"char":"竜","hun":"용 룡","meaning":"“용 룡”. 용","on":"リュウ","kun":"たつ","explanation":["竜 = 立 + 电。","(소리부 겸 의미부) 「立」(リュウ)는 “서다”라는 뜻입니다.","(의미부) 电는 「申」가 변형된 것으로, “번개”를 뜻합니다.","竜는 “번개(电)가 치는 하늘 위에 우뚝 선(立) 용” -> “용”이라는 뜻의 글자입니다.","(立는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1337/"},"詩":{"id":1326,"char":"詩","hun":"시 시","meaning":"“시 시”. 시, 운문, 시가","on":"シ","kun":"","explanation":["詩 = 言 + 寺。","(의미부) 「言」는 “말하다”라는 뜻입니다.","(소리부 겸 의미부) 「寺」(ジ)는 “절, 사찰”을 뜻합니다.","詩는 “한적한 절(寺)의 풍경을 바라보며 시를 읊다(言)” -> “시, 운문, 시가”라는 뜻의 글자입니다.","(寺는 소리부(ジ -> シ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1338/"},"繁":{"id":1327,"char":"繁","hun":"번성할 번","meaning":"“번성할 번”. 번창하다, 번성하다, 번거롭다","on":"ハン","kun":"","explanation":["繁 = 敏 + 糸。","「敏」는 본래 “손을 바삐 움직이는(攵) 여자(毎)”를 그린 글자입니다(링크 참조).","「糸」는 “실”을 뜻합니다.","繁는 “실타래(糸)를 안고 바삐 손을 움직이며(攵) 뜨개질을 하는 여자(毎)”라는 뜻입니다.","“뜨개질을 해서 풍성한 옷을 만들다” -> “번창하다, 번성하다”","“하나하나 손으로 뜨개질하다” -> “번거롭다”","라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/1339/"},"翼":{"id":1328,"char":"翼","hun":"날개 익","meaning":"“날개 익”. 날개","on":"ヨク","kun":"つばさ","explanation":["翼 = 羽 + 異。","「羽」는 “깃, 날개”를 뜻합니다.","「異」는 “기이하다, 이상하다, 다르다”라는 뜻입니다.","翼는 “희귀한(異) 새의 독특한 날개(羽)” -> “날개”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1340/"},"潟":{"id":1329,"char":"潟","hun":"개펄 석","meaning":"“개펄 석”. 개펄, 간석지","on":"","kun":"かた","explanation":["潟 = 氵 + 舄。","「氵」는 “물”을 뜻합니다.","舄는 여기서는 “게의 집게발(臼)과 몸통(勹), 다리(灬)”를 그린 모양자입니다.","潟는 “게(舄)가 사는 바닷가(氵)의 개펄” -> “개펄, 간석지”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1341/"},"敵":{"id":1330,"char":"敵","hun":"대적할 적","meaning":"“대적할 적”. 적, 원수","on":"テキ","kun":"かたき","explanation":["敵 = 啇 + 攵。","(소리부 겸 의미부) 「啇」(テキ)는 “화초를 심은 화분”을 뜻합니다.","(의미부) 「攵」는 “때리다, 치다”라는 뜻입니다.","敵는 “뿌리깊은(啇) 원한을 갚다(攵)” -> “적, 원수”라는 뜻의 글자입니다.","(啇는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1342/"},"魅":{"id":1331,"char":"魅","hun":"매혹할 매","meaning":"“매혹할 매”. 매혹, 매력","on":"ミ","kun":"","explanation":["魅 = 鬼 + 未。","(의미부) 鬼(“귀신 귀”)는 “귀신”을 뜻하는 상용한자입니다.","(소리부) 「未」(ミ)는 여기서는 소리부의 역할만 하고 있습니다.","魅는 “귀신(鬼)에게 홀리다” -> “홀리다, 매혹, 매력”이라는 뜻의 글자입니다(未는 소리부)."],"sourceUrl":"https://nihongokanji.com/1343/"},"嫌":{"id":1332,"char":"嫌","hun":"싫어할 혐","meaning":"“싫어할 혐”. 싫어하다, 혐오하다","on":"ケン、ゲン","kun":"きら(う)、いや","explanation":["嫌 = 女 + 兼。","(의미부) 「女」는 “여자”를 뜻합니다.","(소리부 겸 의미부) 「兼」(ケン)은 “겸하다”라는 뜻입니다.","嫌는 “여자(女)가 마음속에 가진(兼) 시기와 질투” -> “싫어하다, 혐오하다”라는 뜻의 글자입니다.","(兼는 소리부(ケン -> ケン・ゲン)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1344/"},"斉":{"id":1333,"char":"斉","hun":"가지런할 제","meaning":"“가지런할 제”. 가지런한, 균일한","on":"セイ","kun":"","explanation":["斉는 본래 “다리를 건너는 사람(文)”을 그린 상형문자입니다(623.「済」 모양 해설 참조).","“한 줄로 가지런히 서서 다리를 건너다” -> “가지런한, 균일한”이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/1345/"},"敷":{"id":1334,"char":"敷","hun":"펼 부","meaning":"“펼 부”. 펴다, 깔다","on":"フ","kun":"し(く)","explanation":["敷 = 甫 + 方 + 攵。","(소리부 겸 의미부) 「甫」(ホ)는 “채소밭”을 뜻합니다.","(의미부) 「方」는 “방향”을 뜻합니다.","(의미부) 「攵」는 “때리다, 치다”라는 뜻입니다.","敷는 “사방팔방(方)에 채소밭(甫)을 일궈놓다(攵)” -> “펴다, 깔다”라는 뜻의 글자입니다.","(甫는 소리부(ホ -> フ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1346/"},"擁":{"id":1335,"char":"擁","hun":"낄 옹","meaning":"“낄 옹”. 껴안다, 감싸주다","on":"ヨウ","kun":"","explanation":["擁 = 扌 + 亠 + 乡 + 隹。","「扌」는 “손”을 뜻합니다.","亠는 여기서는 “지붕”을 그린 모양자입니다.","乡는 여기서는 “붕대”를 그린 모양자입니다.","「隹」는 “새”를 뜻합니다.","擁는 “지붕(亠)에서 떨어진 다친 새(隹)에게 붕대(乡)를 감아주고 꼭 껴안아주다(扌)” -> “껴안다, 감싸주다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1347/"},"圏":{"id":1336,"char":"圏","hun":"우리 권","meaning":"“우리 권”. 범위, 구역","on":"ケン","kun":"","explanation":["圏 = 囗 + 巻。","(의미부) 囗는 여기서는 “경계선, 범위”를 표현한 모양자입니다.","(소리부 겸 의미부) 「巻」(カン)은 “돌돌 말다, 감다”라는 뜻입니다.","圏는 “경계(囗)로 둘러싸인(巻) 구역” -> “범위, 구역”이라는 뜻의 글자입니다.","(巻는 소리부(カン -> ケン)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1348/"},"酸":{"id":1337,"char":"酸","hun":"실 산","meaning":"“실 산”. 산성, 시큼한","on":"サン","kun":"す(い)","explanation":["酸 = 酉 + 夋。","「酉」는 “술”을 뜻합니다.","「夋」는 “천천히 걷는 사람”을 뜻합니다.","酸는 “술(酉)에 취해 느릿느릿 걷는(夋) 사람” -> “술” -> “산성의, 시큼한”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1349/"},"罰":{"id":1338,"char":"罰","hun":"벌할 벌","meaning":"“벌할 벌”. 벌하다","on":"バツ、バチ","kun":"","explanation":["罰 = 罒 + 言 + 刂。","「罒」는 “그물”을 뜻합니다.","「言」는 “말하다”라는 뜻입니다.","「刂」는 “칼”을 뜻합니다.","罰는 “죄인을 잡아서(罒) 훈계하고(言) 벌을 내리다(刂)” -> “벌하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1350/"},"滅":{"id":1339,"char":"滅","hun":"멸할 멸","meaning":"“멸할 멸”. 사라지다, 없어지다, 멸망하다","on":"メツ","kun":"ほろ(びる)、ほろ(ぼす)","explanation":["滅 = 氵 + 戌 + 火。","「氵」는 “물”을 뜻합니다.","「戌」는 “창을 든 손”을 뜻합니다.","「火」는 “불”을 뜻합니다.","滅는 “홍수(氵)와 화재(火)와 전쟁(戌)” -> “멸망하다, 없어지다, 사라지다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1351/"},"礎":{"id":1340,"char":"礎","hun":"주춧돌 초","meaning":"“주춧돌 초”. 주춧돌, 초석","on":"ソ","kun":"いしずえ","explanation":["礎 = 石 + 木 + 木 + 疋。","「石」는 “돌”을 뜻합니다.","「木」는 “나무”를 뜻합니다.","疋는 「正」가 변형된 것으로, “바르다”라는 뜻입니다.","礎는 “집의 나무기둥(木木)을 바르게(疋) 세우기 위한 주춧돌(石)” -> “주춧돌, 초석”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1352/"},"腐":{"id":1341,"char":"腐","hun":"썩을 부","meaning":"“썩을 부”. 썩다","on":"フ","kun":"くさ(る)、くさ(れる)、くさ(らす)","explanation":["腐 = 府 + 肉。","(소리부 겸 의미부) 「府」(フ)는 “관청, 정부”를 뜻합니다.","(의미부) 「肉」는 “고기”를 뜻합니다.","腐는 “썩은 고기(肉)처럼 부패한 정부(府)” -> “썩다”라는 뜻의 글자입니다.","(府는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1353/"},"脚":{"id":1342,"char":"脚","hun":"다리 각","meaning":"“다리 각”. 다리","on":"キャク、キャ","kun":"あし","explanation":["脚 = 月 + 却。","(의미부) 「月」는 “신체의 일부”를 뜻합니다.","(소리부 겸 의미부) 「却」(キャク)는 “물러나다”라는 뜻입니다.","脚는 “다리로(月) 걸어서 물러나다(却)” -> “다리”라는 뜻의 글자입니다.","(却는 소리부(キャク -> キャク・キャ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1354/"},"潮":{"id":1343,"char":"潮","hun":"밀물/조수 조","meaning":"“밀물/조수 조”. 조수","on":"チョウ","kun":"しお","explanation":["潮 = 氵 + 朝。","(의미부) 「氵」는 “물”을 뜻합니다.","(소리부 겸 의미부) 「朝」(チョウ)는 “아침”을 뜻합니다.","潮는 “아침(朝)에 밀려오는 바닷물(氵)” -> “조수”라는 뜻의 글자입니다.","(朝는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1355/"},"梅":{"id":1344,"char":"梅","hun":"매화 매","meaning":"“매화 매”. 매화","on":"バイ","kun":"うめ","explanation":["梅 = 木 + 毎。","(의미부) 「木」는 “나무”를 뜻합니다.","(소리부) 「毎」(マイ)는 여기서는 소리부(マイ->バイ)의 역할만 하고 있습니다.","梅는 “나무(木)” -> “매화나무”라는 뜻의 글자입니다(毎는 소리부)."],"sourceUrl":"https://nihongokanji.com/1356/"},"尽":{"id":1345,"char":"尽","hun":"다할 진","meaning":"“다할 진”. 다하다, 전부, 죄다","on":"ジン","kun":"つ(くす)、つ(きる)、つ(かす)","explanation":["尽 = 尺 + ⺀。","尺는 여기서는 “그릇을 거꾸로 뒤집은 모습”을 그린 모양자입니다.","⺀는 여기서는 “그릇에서 떨어져나오는 찌꺼기”를 그린 모양자입니다.","尽는 “그릇을 거꾸로 뒤집어(尺) 안에 든 것을 전부 털어내다(⺀)” -> “다하다, 전부, 죄다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1357/"},"僕":{"id":1346,"char":"僕","hun":"종 복","meaning":"“종 복”. 하인, 남자의 자칭(겸손한 말투)","on":"ボク","kun":"","explanation":["僕 = 亻 + 菐。","「亻」는 “사람”을 뜻합니다.","菐는 「業」에서 선 하나가 빠진 것으로, “업무”를 뜻합니다.","僕는 “잡무(菐)를 수행하는 사람(亻)” -> “하인”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1358/"},"桜":{"id":1347,"char":"桜","hun":"앵두 앵","meaning":"“앵두 앵”. 벚나무, 벚꽃","on":"オウ","kun":"さくら","explanation":["桜 = 木 + ⺍ + 女。","「木」는 “나무”를 뜻합니다.","⺍는 여기서는 “벚꽃잎”을 그린 모양자입니다.","「女」는 “여자”를 뜻합니다.","桜는 “벚꽃잎(⺍) 흩날리는 벚나무(木) 아래에서 꽃놀이하는 여자(女)” -> “벚나무, 벚꽃”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1359/"},"滑":{"id":1348,"char":"滑","hun":"미끄러울 활","meaning":"“미끄러울 활”. 미끄러운, 유창한","on":"カツ、コツ","kun":"すべ(る)、なめ(らか)","explanation":["滑 = 氵 + 骨。","(의미부) 「氵」는 “물”을 뜻합니다.","(소리부 겸 의미부) 「骨」(コツ)는 “뼈”를 뜻합니다.","滑는 “물(氵)에 젖은 뼈다귀(骨)” -> “미끄럽다, 유창하다”라는 뜻의 글자입니다.","(骨는 소리부(コツ -> カツ・コツ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1360/"},"孤":{"id":1349,"char":"孤","hun":"고아/외로울 고","meaning":"“고아/외로울 고”. 외롭다, 고아","on":"コ","kun":"","explanation":["孤 = 子 + 瓜。","「子」는 “아이”를 뜻합니다.","瓜는 “덩굴에 매달려 흔들리는 열매”를 그린 글자입니다. 아래 그림을 참조해 주세요","孤는 “홀로 매달린 열매(瓜)처럼 쓸쓸히 남겨진 고아(子)” -> “고아, 외롭다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1361/"},"炎":{"id":1350,"char":"炎","hun":"불꽃 염","meaning":"“불꽃 염”. 타오르다, 화염, 불꽃","on":"エン","kun":"ほのお","explanation":["炎 = 火 + 火。","「火」는 “불”을 뜻합니다.","炎는 “불꽃(火)이 타오르다(火)” -> “화염, 불꽃”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1362/"},"賠":{"id":1351,"char":"賠","hun":"물어줄 배","meaning":"“물어줄 배”. 배상, 보상","on":"バイ","kun":"","explanation":["賠 = 貝 + 咅。","(의미부) 「貝」는 “돈, 재물”을 뜻합니다.","(소리부 겸 의미부) 咅는 여기서는 「倍」(バイ)가 축약된 것으로, “두 배”라는 뜻입니다.","賠는 “돈(貝)을 두 배로(倍) 물어주다” -> “배상하다, 보상하다”라는 뜻의 글자입니다.","(咅는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1363/"},"句":{"id":1352,"char":"句","hun":"글귀 구","meaning":"“글귀 구”. 구절, 글귀","on":"ク","kun":"","explanation":["句 = 勹 + 口。","(의미부) 勹는 여기서는 “감싸다”라는 뜻을 표현한 모양자입니다.","(소리부 겸 의미부) 「口」(ク)는 “입”을 뜻합니다.","句는 “말(口)을 묶은(勹) 단위” -> “구절, 글귀”라는 뜻의 글자입니다.","(口는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1364/"},"寿":{"id":1353,"char":"寿","hun":"목숨 수","meaning":"“목숨 수”. 장수하다, 나이, 생명","on":"ジュ","kun":"ことぶき","explanation":["寿 = 丰 + 寸。","丰는 여기서는 “주름살”을 그린 모양자입니다.","「寸」는 “손”을 뜻합니다.","寿는 “주름살(丰)이 많은 손(寸)” -> “노인” -> “장수하다, 나이, 생명”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1365/"},"鋼":{"id":1354,"char":"鋼","hun":"강철 강","meaning":"“강철 강”. 강철","on":"コウ","kun":"はがね","explanation":["鋼 = 金 + 岡。","(의미부) 「金」는 “쇠”를 뜻합니다.","(소리부 겸 의미부) 「岡」(コウ)는 “강하다”라는 뜻입니다.","鋼는 “강한(岡) 쇠(金)” -> “강철”이라는 뜻의 글자입니다.","(岡는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1366/"},"頑":{"id":1355,"char":"頑","hun":"완고할 완","meaning":"“완고할 완”. 완고한, 강경한","on":"ガン","kun":"","explanation":["頑 = 元 + 頁。","(소리부 겸 의미부) 「元」(ガン)은 “근본, 근원, 으뜸”이라는 뜻입니다.","(의미부) 「頁」는 “머리”를 뜻합니다.","頑는 “가장 단단한(元) 머리(頁)” -> “완고하다, 강경하다”라는 뜻의 글자입니다.","(元는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1367/"},"鎖":{"id":1356,"char":"鎖","hun":"쇠사슬 쇄","meaning":"“쇠사슬 쇄”. 쇠사슬, 잠그다","on":"サ","kun":"くさり","explanation":["鎖 = 金 + ⺌ + 貝。","「金」는 “쇠, 황금”을 뜻합니다.","⺌는 여기서는 「小」가 뒤집힌 것으로, “작다”라는 뜻입니다.","「貝」는 “돈, 재물”을 뜻합니다.","鎖는 “전재산(貝)이 들어있는 작은(小) 금고를 쇠사슬(金)로 꼭꼭 잠가두다” -> “쇠사슬, 잠그다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1368/"},"彩":{"id":1357,"char":"彩","hun":"채색 채","meaning":"“채색 채”. 채색하다","on":"サイ","kun":"いろど(る)","explanation":["彩 = 采 + 彡。","(소리부 겸 의미부) 「采」(サイ)는 본래 “나무열매를 따는 모습”을 그린 글자입니다(링크 참조).","(의미부) 彡는 여기서는 “화사한 햇살”을 표현한 모양자입니다.","彩는 “햇살(彡)이 나무(采)를 밝게 물들이다” -> “채색하다”라는 뜻의 글자입니다.","(采는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1369/"},"摩":{"id":1358,"char":"摩","hun":"문지를 마","meaning":"“문지를 마”. 문지르다, 비비다, 마찰, 갈다","on":"マ","kun":"","explanation":["摩 = 麻 + 手。","(소리부 겸 의미부) 「麻」(マ)는 “삼베, 마”를 뜻합니다.","(의미부) 「手」는 “손”을 뜻합니다.","삼베를 만들기 위해서는, 먼저 대마를 말린 다음 돌로 문질러야 한다고 합니다.","摩는 “마(麻)를 가공하기 위해 돌에 문지르다(手)” -> “문지르다, 비비다”라는 뜻의 글자입니다.","(麻는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1370/"},"励":{"id":1359,"char":"励","hun":"힘쓸 려","meaning":"“힘쓸 려”. 힘쓰다, 격려하다","on":"レイ","kun":"はげ(む)、はげ(ます)","explanation":["励 = 厂 + 万 + 力。","「厂」는 “절벽”을 뜻합니다.","「万」는 본래 “날카로운 칼날”을 그린 글자입니다(링크 참조).","「力」는 “힘”을 뜻합니다.","励는 “절벽(厂)을 깎아내기(万) 위해 힘쓰다(力)” -> “힘쓰다, 노력하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1371/"},"縦":{"id":1360,"char":"縦","hun":"세로 종","meaning":"“세로 종”. 세로","on":"ジュウ","kun":"たて","explanation":["縦 = 糸 + 従。","(의미부) 「糸」는 “실”을 뜻합니다.","(소리부 겸 의미부) 「従」(ジュウ)는 “따르다, 복종하다”라는 뜻입니다.","縦는 “천장에 매달린 실(糸)이 상하로(従) 길게 늘어지다” -> “세로”라는 뜻의 글자입니다.","(従는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1372/"},"輝":{"id":1361,"char":"輝","hun":"빛날 휘","meaning":"“빛날 휘”. 빛나다","on":"キ","kun":"かがや(く)","explanation":["輝 = 光 + 軍。","「光」는 “빛”을 뜻합니다.","「軍」는 “군대”를 뜻합니다.","輝는 “야영 중인 군대(軍)의 막사에서 새어나오는 불빛(光)” -> “빛나다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1373/"},"蓄":{"id":1362,"char":"蓄","hun":"모을 축","meaning":"“모을 축”. 모으다, 쌓다","on":"チク","kun":"たくわ(える)","explanation":["蓄 = 艹 + 畜。","(의미부) 「艹」는 “풀”을 뜻합니다.","(소리부 겸 의미부) 「畜」(チク)는 “가축”을 뜻합니다.","蓄는 “가축(畜)들에게 먹이로 줄 건초(艹)를 모으다” -> “모으다, 쌓다”라는 뜻의 글자입니다.","(畜는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1374/"},"軸":{"id":1363,"char":"軸","hun":"굴대 축","meaning":"“굴대 축”. 축, 주축","on":"ジク","kun":"","explanation":["軸 = 車 + 由。","「車」는 “수레, 차”를 뜻합니다.","由는 여기서는 “(수레)바퀴의 축”을 그린 모양자입니다.","軸는 “수레바퀴(車)의 축(由)” -> “축, 주축”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1375/"},"巡":{"id":1364,"char":"巡","hun":"돌 순","meaning":"“돌 순”. 순회하다, 한바퀴 돌다","on":"ジュン","kun":"めぐ(る)","explanation":["巡 = ⻌ + 巛。","「⻌」는 “길”을 뜻합니다.","巛는 “흐르는 물살”을 그린 모양자입니다.","巡는 “물살(巛)이 물길(⻌)을 한바퀴 돌다” -> “순회하다, 한바퀴 돌다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1376/"},"稼":{"id":1365,"char":"稼","hun":"심을 가","meaning":"“심을 가”. (돈을) 벌다, 열심히 일하다","on":"カ","kun":"かせ(ぐ)","explanation":["稼 = 禾 + 家。","(의미부) 「禾」는 “곡식”을 뜻합니다.","(소리부 겸 의미부) 「家」(カ)는 “집”을 뜻합니다.","稼는 “가족(家)을 먹여살리기(禾) 위해 열심히 일하다” -> “돈을 벌다, 열심히 일하다”라는 뜻의 글자입니다.","(家는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1377/"},"瞬":{"id":1366,"char":"瞬","hun":"깜짝일 순","meaning":"“깜짝일 순”. 깜빡이다, 찰나의","on":"シュン","kun":"またた(く)","explanation":["瞬 = 目 + ⺤ + 冖 + 舛。","「目」는 “눈”을 뜻합니다.","「⺤」는 “손”을 뜻합니다.","冖는 여기서는 “덮다”라는 뜻을 표현한 모양자입니다.","「舛」는 “두 발”을 뜻합니다.","瞬는 “손(⺤)으로 잠깐 눈(目)을 덮었다(冖) 뗀 사이에 도망쳐버리다(舛)” -> “깜빡이다, 찰나의”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1378/"},"砲":{"id":1367,"char":"砲","hun":"대포 포","meaning":"“대포 포”. 대포","on":"ホウ","kun":"","explanation":["砲 = 石 + 包。","(의미부) 「石」는 “돌”을 뜻합니다.","(소리부 겸 의미부) 「包」(ホウ)는 “감싸다”라는 뜻입니다.","砲는 “돌무더기(石)를 그물로 감싸(包) 던지는 투석기” -> “대포”라는 뜻의 글자입니다.","(包는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1379/"},"噴":{"id":1368,"char":"噴","hun":"뿜을 분","meaning":"“뿜을 분”. 내뿜다","on":"フン","kun":"ふ(く)","explanation":["噴 = 口 + 十 + 艹 + 貝。","「口」는 “입”을 뜻합니다.","「十」는 “10”을 뜻합니다.","艹는 여기서는 「十」 두 개가 합쳐진 것으로, “20”을 뜻합니다.","「貝」는 “돈, 재물”을 뜻합니다.","噴는 “삼십 년(十+艹) 동안 모은 재산(貝)을 전부 토해내다(口)” -> “내뿜다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1380/"},"誇":{"id":1369,"char":"誇","hun":"자랑할 과","meaning":"“자랑할 과”. 자랑하다, 과시하다","on":"コ","kun":"ほこ(る)","explanation":["誇 = 言 + 夸。","「言」는 “말하다”라는 뜻입니다.","夸는 “양 팔을 크게 벌리고 뽐내는 사람(大)”을 그린 모양자입니다.","誇는 “양 팔을 벌리고 뽐내며(夸) 자기 자랑을 떠벌리다(言)” -> “자랑하다, 과시하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1381/"},"祥":{"id":1370,"char":"祥","hun":"상서 상","meaning":"“상서 상”. 경사, 행복","on":"ショウ","kun":"","explanation":["祥 = 礻 + 羊。","(의미부) 「礻」는 “신, 종교, 고대의 비석”을 뜻합니다.","(소리부 겸 의미부) 「羊」(ヨウ)는 “양”을 뜻합니다.","祥는 “좋은 일을 바라며 신(礻)에게 양(羊)을 제물로 바치다” -> “경사, 행복”이라는 뜻의 글자입니다.","(羊는 소리부(ヨウ -> ショウ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1382/"},"牲":{"id":1371,"char":"牲","hun":"희생 생","meaning":"“희생 생”. 희생","on":"セイ","kun":"","explanation":["牲 = 牜 + 生。","(의미부) 「牜」는 “소”를 뜻합니다.","(소리부 겸 의미부) 「生」(セイ)는 “생명”을 뜻합니다.","牲는 “소(牜)의 생명(生)을 제물로 바치다” -> “희생”이라는 뜻의 글자입니다.","(生는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1383/"},"秩":{"id":1372,"char":"秩","hun":"차례 질","meaning":"“차례 질”. 질서, 순서","on":"チツ","kun":"","explanation":["秩 = 禾 + 失。","(의미부) 「禾」는 “곡식”을 뜻합니다.","(소리부) 「失」(シツ)는 여기서는 소리부(シツ -> チツ)의 역할만 하고 있습니다.","秩는 “수확한 볏단(禾)을 가지런히 쌓아놓다” -> “질서, 순서”라는 뜻의 글자입니다(失는 소리부)."],"sourceUrl":"https://nihongokanji.com/1384/"},"帝":{"id":1373,"char":"帝","hun":"임금 제","meaning":"“임금 제”. 황제","on":"テイ","kun":"","explanation":["帝 = 立 + 冖 + 巾。","「立」는 “서다”라는 뜻입니다.","冖는 여기서는 “허리띠”를 그린 모양자입니다.","「巾」는 “수건, 천”을 뜻합니다.","帝는 “황금 허리띠(冖)와 곤룡포(巾)를 입고 위풍당당히 선(立) 황제” -> “황제”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1385/"},"唆":{"id":1374,"char":"唆","hun":"부추길 사","meaning":"“부추길 사”. 꾀다, 부추기다","on":"サ","kun":"そそのか(す)","explanation":["唆 = 口 + 夋。","「口」는 “입”을 뜻합니다.","「夋」는 “천천히 걷는 사람”을 뜻합니다.","唆는 “옆에서 천천히 따라 걸으며(夋) 속삭이다(口)” -> “부추기다, 꾀다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1386/"},"阻":{"id":1375,"char":"阻","hun":"막힐 조","meaning":"“막힐 조”. 막다, 방해하다","on":"ソ","kun":"はば(む)","explanation":["阻 = ⻖ + 且。","(의미부) 「⻖」는 “언덕, 산”을 뜻합니다.","(소리부 겸 의미부) 「且」(ソ)는 “비석”을 뜻합니다.","阻는 “언덕(⻖)의 오솔길을 가로막은 비석(且)” -> “막다, 방해하다”라는 뜻의 글자입니다.","(且는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1387/"},"泰":{"id":1376,"char":"泰","hun":"클 태","meaning":"“클 태”. 편안하다, 침착하다","on":"タイ","kun":"","explanation":["泰 = 𡗗 + 氺。","𡗗는 여기서는 「春」가 축약된 것으로, “봄”을 뜻합니다.","氺는 여기서는 「水」가 변형된 것으로, “물”을 뜻합니다.","泰는 “따뜻한 봄(春)에 개울가(氺)에서 소풍을 즐기다” -> “편안하다, 침착하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1388/"},"賄":{"id":1377,"char":"賄","hun":"재물/뇌물 회","meaning":"“재물/뇌물 회”. 뇌물, 재물","on":"ワイ","kun":"まかな(う)","explanation":["賄 = 貝 + 有。","「貝」는 “재물, 돈”을 뜻합니다.","「有」는 “있다”라는 뜻입니다.","賄는 “받아먹은 돈(貝)이 있다(有)” -> “재물, 뇌물”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1389/"},"撲":{"id":1378,"char":"撲","hun":"칠 박","meaning":"“칠 박”. 때리다, 두드리다","on":"ボク","kun":"","explanation":["撲 = 扌 + 菐。","(의미부) 「扌」는 “손”을 뜻합니다.","(소리부 겸 의미부) 菐는 여기서는 「僕」(ボク)가 축약된 것으로, “하인”을 뜻합니다.","撲는 “하인(僕)을 손으로 때리다(扌)” -> “때리다, 두드리다”라는 뜻의 글자입니다.","(菐->僕는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1390/"},"堀":{"id":1379,"char":"堀","hun":"굴 굴","meaning":"“굴 굴”. 수로, 굴","on":"","kun":"ほり","explanation":["堀 = 土 + 屈。","「土」는 “흙, 땅”을 뜻합니다.","屈는 여기서는 「掘」가 축약된 것으로, “파다”라는 뜻입니다.","堀는 “땅(土)을 파서(掘) 만든 땅굴” -> “수로, 굴”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1391/"},"菊":{"id":1380,"char":"菊","hun":"국화 국","meaning":"“국화 국”. 국화","on":"キク","kun":"","explanation":["菊 = 艹 + 匊。","「艹」는 “풀”을 뜻합니다.","匊는 여기서는 “국화꽃”을 본따 그린 모양자입니다.","菊는 “국화꽃(匊)과 잎(艹)” -> “국화”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1392/"},"絞":{"id":1381,"char":"絞","hun":"목맬 교","meaning":"“목맬 교”. 죄다, 조르다","on":"コウ","kun":"しぼ(る)、し(める)、し(まる)","explanation":["絞 = 糸 + 交。","(의미부) 「糸」는 “실”을 뜻합니다.","(소리부 겸 의미부) 「交」(コウ)는 “교차하다, 엇갈리다”라는 뜻입니다.","絞는 “줄(糸)을 교차시켜(交) 목을 조르다” -> “죄다, 조르다”라는 뜻의 글자입니다.","(交는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1393/"},"縁":{"id":1382,"char":"縁","hun":"인연 연","meaning":"“인연 연”. 인연, 가장자리","on":"エン","kun":"ふち","explanation":["縁 = 糸 + 彐 + 豕。","「糸」는 “실”을 뜻합니다.","彐+豕는 여기서는 「家」가 변형된 것으로, “집”을 뜻합니다.","縁은 “굳게 이어진(糸) 가족(家)의 인연” -> “인연”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1394/"},"唯":{"id":1383,"char":"唯","hun":"오직 유","meaning":"“오직 유”. 오직, 그것 뿐, 다만","on":"ユイ、イ","kun":"","explanation":["唯 = 口 + 隹。","「口」는 “입”을 뜻합니다.","「隹」는 “새”를 뜻합니다.","唯는 “새(隹)는 항상 같은 울음소리(口)로 지저귄다” -> “오직, 다만, 그것 뿐”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1395/"},"膨":{"id":1384,"char":"膨","hun":"불을 팽","meaning":"“불을 팽”. 팽창하다, 부풀어오르다","on":"ボウ","kun":"ふく(らむ)、ふく(れる)","explanation":["膨 = 月 + 壴 + 彡。","「月」는 “고기”를 뜻합니다.","「壴」는 “북”을 뜻합니다.","彡는 여기서는 “햇살”을 그린 모양자입니다.","膨는 “화창한 날(彡)에 연회(月)를 열고 북(壴)을 치며 분위기를 띄우다” -> “팽창하다, 부풀어오르다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1396/"},"矢":{"id":1385,"char":"矢","hun":"화살 시","meaning":"“화살 시”. 화살","on":"シ","kun":"や","explanation":["矢는 “화살”을 본따 그린 상형문자입니다."],"sourceUrl":"https://nihongokanji.com/1397/"},"耐":{"id":1386,"char":"耐","hun":"견딜 내","meaning":"“견딜 내”. 견디다, 참다","on":"タイ","kun":"た(える)","explanation":["耐 = 而 + 寸。","而는 여기서는 “깊게 뿌리내린 뿌리”를 그린 모양자입니다.","「寸」는 “손”을 뜻합니다.","耐는 “뿌리(而)가 깊어 뽑아내려(寸) 해도 뽑히지 않고 버티다” -> “견디다, 참다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1398/"},"塾":{"id":1387,"char":"塾","hun":"글방 숙","meaning":"“글방 숙”. 학원","on":"ジュク","kun":"","explanation":["塾 = 享 + 丸 + 土。","「享」는 “모자를 쓴 아이”를 그린 글자입니다(링크 참조).","「丸」는 본래 “엎드린 사람”을 그린 글자입니다(링크 참조).","「土」는 “흙, 땅”을 뜻합니다.","塾는 “아이(享)가 땅바닥(土)에 엎드려(丸) 흙 위에 글자 쓰는 연습을 하다” -> “학원”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1399/"},"漏":{"id":1388,"char":"漏","hun":"샐 루","meaning":"“샐 루”. 새다, 누출되다","on":"ロウ","kun":"も(る)、も(れる)、も(らす)","explanation":["漏 = 氵 + 尸 + 雨。","「氵」는 “물”을 뜻합니다.","「尸」는 “지붕”을 뜻합니다.","「雨」는 “비”를 뜻합니다.","漏는 “비(雨)가 와 지붕(尸)에서 물(氵)이 새다” -> “새다, 누출되다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1400/"},"慶":{"id":1389,"char":"慶","hun":"경사 경","meaning":"“경사 경”. 경사, 축하하다","on":"ケイ","kun":"","explanation":["慶 = 鹿 + 乛 + 心 + 夂。","윗부분은 「鹿」가 축약된 것으로, “사슴”을 뜻합니다.","「心」는 “마음”을 뜻합니다.","「夂」는 “발”을 뜻합니다.","고대에는 사슴 가죽이 귀한 선물로서 쓰였다고 합니다.","慶는 “사슴 가죽(鹿)을 들쳐메고(乛) 기쁜 마음으로(心) 축하하러 가다(夂)” -> “경사, 축하하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1401/"},"猛":{"id":1390,"char":"猛","hun":"사나울 맹","meaning":"“사나울 맹”. 거친, 사나운","on":"モウ","kun":"","explanation":["猛 = 犭 + 子 + 皿。","「犭」는 “개”를 뜻합니다.","「子」는 “아이”를 뜻합니다.","皿는 여기서는 「血」가 잘못 변형된 것으로, “피”를 뜻합니다.","猛는 “아이(子)가 사나운 개(犭)에게 물려 피(血)를 흘리다” -> “거칠다, 사납다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1402/"},"芳":{"id":1391,"char":"芳","hun":"꽃다울 방","meaning":"“꽃다울 방”. 향기롭다","on":"ホウ","kun":"かんば(しい)","explanation":["芳 = 艹 + 方。","(의미부) 「艹」는 “풀”을 뜻합니다.","(소리부 겸 의미부) 「方」(ホウ)는 “방향”을 뜻합니다.","芳는 “꽃향기(艹)가 사방(方)으로 퍼져나가다” -> “향기롭다”라는 뜻의 글자입니다.","(方는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1403/"},"懲":{"id":1392,"char":"懲","hun":"징계할 징","meaning":"“징계할 징”. 징계하다","on":"チョウ","kun":"こ(りる)、こ(らす)、こ(らしめる)","explanation":["懲 = 徴 + 心。","(소리부 겸 의미부) 「徴」(チョウ)는 “징집하다”라는 뜻입니다.","(의미부) 「心」는 “마음”을 뜻합니다.","예나 지금이나, 노예들이 정부권력의 강제 징병을 거부하면 강력한 처벌을 받게 됩니다.","懲는 “강제 징병(徴)에 거역한(心) 자를 강력히 처벌하다” -> “징계하다”라는 뜻의 글자입니다.","(徴는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1404/"},"剣":{"id":1393,"char":"剣","hun":"칼 검","meaning":"“칼 검”. 검","on":"ケン","kun":"つるぎ","explanation":["剣 = 㑒 + 刂。","(소리부 겸 의미부) 「㑒」(ケン)은 “뾰족하다, 날카롭다”라는 뜻입니다.","(의미부) 「刂」는 “칼”을 뜻합니다.","剣는 “날카로운(㑒) 칼(刂)” -> “칼, 검”이라는 뜻의 글자입니다.","(㑒는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1405/"},"彰":{"id":1394,"char":"彰","hun":"드러날 창","meaning":"“드러날 창”. 뚜렷이 드러나다","on":"ショウ","kun":"","explanation":["彰 = 章 + 彡。","(소리부 겸 의미부) 「章」(ショウ)는 “글, 무늬”를 뜻합니다.","(의미부) 彡는 여기서는 “햇살”을 그린 모양자입니다.","彰는 “햇살(彡)을 받아 무늬(章)가 뚜렷이 드러나다” -> “뚜렷이 드러나다”라는 뜻의 글자입니다.","(章는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1406/"},"棋":{"id":1395,"char":"棋","hun":"바둑 기","meaning":"“바둑 기”. 장기","on":"キ","kun":"","explanation":["棋 = 木 + 其。","(의미부) 「木」는 “나무”를 뜻합니다.","(소리부 겸 의미부) 「其」(キ)는 여기서는 “장기말”을 그린 모양자입니다.","棋는 “나무(木)로 만든 장기말(其)” -> “장기”라는 뜻의 글자입니다.","(其는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1407/"},"丁":{"id":1396,"char":"丁","hun":"고무래/장정 정","meaning":"“고무래/장정 정”. 거리의 구분, 장정, 못 등","on":"チョウ、テイ","kun":"","explanation":["丁는 “못”을 그린 상형문자입니다.","“못질하다” -> “노동하다” -> “장정”이라는 의미입니다.","(다만, 이 한자는 실제로는 본래의 유래와는 별 관계 없이 매우 다양한 의미로 쓰이는 글자입니다.)"],"sourceUrl":"https://nihongokanji.com/1408/"},"恒":{"id":1397,"char":"恒","hun":"항상 항","meaning":"“항상 항”. 항상, 변치 않는","on":"コウ","kun":"","explanation":["恒 = 忄 + 亘。","「忄」는 “마음”을 뜻합니다.","亘는 “하늘(一)과 땅(一) 사이에 떠있는 태양(日)”이라는 뜻입니다.","恒는 “하늘의 태양(亘)처럼 변치않는 마음(忄)” -> “항상, 변치 않는”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1409/"},"揚":{"id":1398,"char":"揚","hun":"날릴 양","meaning":"“날릴 양”. 떠오르다, 올리다","on":"ヨウ","kun":"あ(げる)、あ(がる)","explanation":["揚 = 扌 + 昜。","(의미부) 「扌」는 “손”을 뜻합니다.","(소리부 겸 의미부) 「昜」(ヨウ)는 “햇빛이 내리쬐는 모습”을 그린 글자입니다.","揚는 “태양이 내리쬐는(昜) 하늘 높이 들어올리다(扌)” -> “떠오르다, 올리다”라는 뜻의 글자입니다.","(昜는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1410/"},"冒":{"id":1399,"char":"冒","hun":"무릅쓸 모","meaning":"“무릅쓸 모”. 무릅쓰다","on":"ボウ","kun":"おか(す)","explanation":["冒 = 日 + 目。","「目」는 “눈”을 뜻합니다.","日는 여기서는 冃가 변형된 것으로, 본래는 “(얼굴을 가리는) 복면”을 그린 모양자입니다.","冒는 “눈(目) 만 드러낸 복면(日->冃)을 쓰고 잠입하다” -> “(위험을) 무릅쓰다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1411/"},"倫":{"id":1400,"char":"倫","hun":"인륜 륜","meaning":"“인륜 륜”. 윤리","on":"リン","kun":"","explanation":["倫 = 亻 + 侖。","(의미부) 「亻」는 “사람”을 뜻합니다.","(소리부 겸 의미부) 「侖」(リン)은 “둥글게 말린 죽간”을 뜻합니다.","倫는 “사람(亻)이 마땅히 지켜야 할 도리를 적은 책(侖)” -> “윤리”라는 뜻의 글자입니다.","(侖는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1412/"},"陳":{"id":1401,"char":"陳","hun":"베풀 진","meaning":"“베풀 진”. 진열하다, 진술하다","on":"チン","kun":"","explanation":["陳 = ⻖ + 東。","「⻖」는 “언덕”을 뜻합니다.","「東」는 “동쪽”을 뜻합니다.","陳는 “동쪽(東)에 늘어선 산맥(⻖)” -> “늘어서다, 진열하다” -> “진술하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1413/"},"憶":{"id":1402,"char":"憶","hun":"생각할 억","meaning":"“생각할 억”. 기억하다, 추억하다","on":"オク","kun":"","explanation":["憶 = 忄 + 意。","「忄」는 “마음”을 뜻합니다.","「意」는 “뜻, 생각”을 뜻합니다.","憶는 “마음(忄)속의 생각(意)” -> “기억하다, 추억하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1414/"},"潜":{"id":1403,"char":"潜","hun":"잠길 잠","meaning":"“잠길 잠”. 잠수하다, 숨다","on":"セン","kun":"ひそ(む)、もぐ(る)","explanation":["潜 = 氵 + 替。","「氵」는 “물”을 뜻합니다.","「替」는 “교체하다, 바꾸다”라는 뜻입니다.","潜는 “수면(氵) 위아래로 들락날락(替) 하며 잠수하다” -> “잠수하다, 숨다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1415/"},"梨":{"id":1404,"char":"梨","hun":"배나무 리","meaning":"“배나무 리”. 배(과일)","on":"","kun":"なし","explanation":["梨 = 利 + 木。","「利」는 “이득, 이롭다”라는 뜻입니다.","「木」는 “나무”를 뜻합니다.","梨는 “맛있는 배가 열리는 이로운(利) 나무(木)” -> “배나무, 배”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1416/"},"仁":{"id":1405,"char":"仁","hun":"어질 인","meaning":"“어질 인”. 인자함","on":"ジン、ニ","kun":"","explanation":["仁 = 亻 + 二。","「亻」는 “사람”을 뜻합니다.","「二」는 “2”를 뜻합니다.","仁는 “두(二) 사람(亻)이 싸우지 않고 친하게 지내다” -> “인자하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1417/"},"克":{"id":1406,"char":"克","hun":"이길 극","meaning":"“이길 극”. 극복하다, 이겨내다","on":"コク","kun":"","explanation":["克 = 古 + 儿。","「古」는 “오래다”라는 뜻입니다.","儿는 「人」가 변형된 것으로, “사람”을 뜻합니다.","克는 “오랜(古) 고난을 견뎌온 사람(儿)” -> “극복하다, 이겨내다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1418/"},"岳":{"id":1407,"char":"岳","hun":"큰 산 악","meaning":"“큰 산 악”. 산악, 거대한 산","on":"ガク","kun":"たけ","explanation":["岳 = 丘 + 山。","丘는 “작은 산”의 모습을 그린 글자입니다. 아래 그림을 참조해 주세요.","「山」는 “산”을 뜻합니다.","岳는 “산(山) 위의 산(丘)” -> “거대한 산, 산악”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1419/"},"概":{"id":1408,"char":"概","hun":"대개 개","meaning":"“대개 개”. 개요, 대체로","on":"ガイ","kun":"","explanation":["概 = 木 + 既。","「木」는 “나무”를 뜻합니다.","「既」는 “벌써, 이전에”라는 뜻입니다.","概는 “필요한 나무(木)의 양을 사전에(既) 대략적으로 어림잡다” -> “대체로, 개요”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1420/"},"拘":{"id":1409,"char":"拘","hun":"잡을 구","meaning":"“잡을 구”. 붙잡다","on":"コウ","kun":"","explanation":["拘 = 扌 + 句。","(의미부) 「扌」는 “손”을 뜻합니다.","(소리부) 「句」(ク)는 여기서는 소리부(ク -> コウ)의 역할만 하고 있습니다.","拘는 “손(扌)으로 붙잡다” -> “붙잡다”라는 뜻의 글자입니다(句는 소리부)."],"sourceUrl":"https://nihongokanji.com/1421/"},"墓":{"id":1410,"char":"墓","hun":"무덤 묘","meaning":"“무덤 묘”. 무덤","on":"ボ","kun":"はか","explanation":["墓 = 莫 + 土。","(소리부 겸 의미부) 「莫」(ボ)는 “없다”라는 뜻입니다.","(의미부) 「土」는 “흙, 땅”을 뜻합니다.","墓는 “죽고 없는(莫) 사람이 묻힌 땅(土)” -> “무덤, 묘지”라는 뜻의 글자입니다.","(莫는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1422/"},"黙":{"id":1411,"char":"黙","hun":"묵묵할 묵","meaning":"“묵묵할 묵”. 침묵, 소리없는","on":"モク","kun":"だま(る)","explanation":["黙 = 黒 + 犬。","「黒」는 “검정”을 뜻합니다.","「犬」는 “개”를 뜻합니다.","黙는 “개들(犬)도 조용히 침묵하는 칠흑(黒)같이 어두운 밤” -> “침묵, 소리없는”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1423/"},"須":{"id":1412,"char":"須","hun":"모름지기 수","meaning":"“모름지기 수”. 모름지기, 반드시","on":"ス","kun":"","explanation":["須 = 彡 + 頁。","「頁」는 “얼굴”을 뜻합니다.","彡는 여기서는 “수염”을 그린 모양자입니다.","옛날에는 수염이 성인의 증표로서 여겨지곤 했습니다.","그러므로 성인 남성이 수염을 기르는 것은 당연한 일이었습니다.","須는 “어른이라면 모름지기 얼굴(頁)에 수염(彡)이 있어야 한다” -> “모름지기, 반드시”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1424/"},"偏":{"id":1413,"char":"偏","hun":"치우칠 편","meaning":"“치우칠 편”. 치우치다, 쏠리다, 기울다","on":"ヘン","kun":"かたよ(る)","explanation":["偏 = 亻 + 扁。","(의미부) 「亻」는 “사람”을 뜻합니다.","(소리부 겸 의미부) 「扁」(ヘン)은 “집 안의 책”을 뜻합니다.","偏는 “자기(亻) 집 안에 있는 책(扁)만 읽는 사람” -> “지식이 치우치다” -> “치우치다, 쏠리다, 기울다”라는 뜻의 글자입니다.","(扁는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1425/"},"雰":{"id":1414,"char":"雰","hun":"눈 날릴 분","meaning":"“눈 날릴 분”. 에워싸다, 분위기","on":"フン","kun":"","explanation":["雰 = 雨 + 分。","(의미부) 「雨」는 “비”를 뜻합니다.","(소리부 겸 의미부) 「分」(フン)은 “나뉘다”라는 뜻입니다.","雰는 “물안개(雨)가 퍼지다(分)” -> “에워싸다, 분위기”라는 뜻의 글자입니다.","(分는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1426/"},"遇":{"id":1415,"char":"遇","hun":"만날 우","meaning":"“만날 우”. 마주치다, 만나다, 접대하다","on":"グウ","kun":"","explanation":["遇 = ⻌ + 禺。","(의미부) 「⻌」는 “길”을 뜻합니다.","(소리부 겸 의미부) 「禺」(グウ)는 “원숭이”를 뜻합니다.","遇는 “길(⻌)에서 원숭이(禺)를 마주치다” -> “마주치다, 만나다” -> “대우하다”라는 뜻의 글자입니다.","(禺는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1427/"},"諮":{"id":1416,"char":"諮","hun":"물을 자","meaning":"“물을 자”. 자문하다","on":"シ","kun":"はか(る)","explanation":["諮 = 言 + 次 + 口。","(의미부) 「言」는 “말하다”라는 뜻입니다.","(소리부 겸 의미부) 「次」(シ)는 “다음”을 뜻합니다.","(의미부) 「口」는 “입”을 뜻합니다.","諮는 “이 다음(次)은 어떻게 해야 할지 입(口)을 열어 물어보다(言)” -> “자문하다”라는 뜻의 글자입니다.","(次는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1428/"},"卓":{"id":1417,"char":"卓","hun":"높을 탁","meaning":"“높을 탁”. 높다, 뛰어나다, 탁자","on":"タク","kun":"","explanation":["卓 = ⺊ + 早。","⺊는 여기서는 “하늘을 나는 새”를 그린 모양자입니다.","「早」는 “이르다, (시간적으로) 빠르다”라는 뜻입니다.","卓는 “아침 일찍 일어나(早) 하늘 높이 날아가는 새(⺊)” -> “높다, 뛰어나다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1429/"},"亀":{"id":1418,"char":"亀","hun":"거북 귀/터질 균","meaning":"“거북 귀/터질 균”. 거북, 균열","on":"キ","kun":"かめ","explanation":["亀는 “거대한 바다거북의 머리와 등딱지, 꼬리”를 그린 상형문자입니다.","“바다거북의 갈라진 등딱지” -> “거북, 균열”이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/1430/"},"糧":{"id":1419,"char":"糧","hun":"양식 량","meaning":"“양식 량”. 식량","on":"リョウ、ロウ","kun":"かて","explanation":["糧 = 米 + 量。","(의미부) 「米」는 “쌀”을 뜻합니다.","(소리부 겸 의미부) 「量」(リョウ)는 “양, 무게를 재다”라는 뜻입니다.","糧는 “식량으로 쓸 쌀(米)의 양(量)” -> “식량”이라는 뜻의 글자입니다.","(量는 소리부(リョウ -> リョウ・ロウ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1431/"},"簿":{"id":1420,"char":"簿","hun":"문서 부","meaning":"“문서 부”. 문서, 장부","on":"ボ","kun":"","explanation":["簿 = 𥫗 + 溥。","「𥫗」는 “대나무 죽간”을 뜻합니다.","溥는 여기서는 「薄」가 축약된 것으로, “얇다”라는 뜻입니다.","簿는 “대나무 죽간(𥫗)을 얇게(薄) 펴서 기록한 장부” -> “문서, 장부”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1432/"},"炉":{"id":1421,"char":"炉","hun":"화로 로","meaning":"“화로 로”. 화로","on":"ロ","kun":"","explanation":["炉 = 火 + 戸。","「火」는 “불”을 뜻합니다.","「戸」는 “집, 문”을 뜻합니다.","炉는 “불(火)을 뿜는 문(戸)” -> “화로”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1433/"},"牧":{"id":1422,"char":"牧","hun":"칠 목","meaning":"“칠 목”. 목축, 목동, 목장","on":"ボク","kun":"まき","explanation":["牧 = 牜 + 攵。","「牜」는 “소”를 뜻합니다.","「攵」는 “때리다, 치다”라는 뜻입니다.","牧는 “소(牜)를 치다(攵)” -> “목축하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1434/"},"殊":{"id":1423,"char":"殊","hun":"다를 수","meaning":"“다를 수”. 다르다, 특수하다","on":"シュ","kun":"こと","explanation":["殊 = 歹 + 朱。","(의미부) 「歹」는 “시체”를 뜻합니다.","(소리부 겸 의미부) 朱(シュ – “붉을 주”)는 “주홍색”을 뜻하는 상용한자입니다.","殊는 “시체(歹)에서 흘러나오는 붉은 피(朱)”라는 뜻입니다.","“피가 유달리 진하고 붉다” -> “다르다, 특수하다”라는 의미입니다.","(朱는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1435/"},"殖":{"id":1424,"char":"殖","hun":"불릴 식","meaning":"“불릴 식”. 번식하다, 불리다","on":"ショク","kun":"ふ(える)、ふ(やす)","explanation":["殖 = 歹 + 直。","(의미부) 「歹」는 “시체”를 뜻합니다.","(소리부) 「直」(チョク)는 여기서는 소리부(チョク -> ショク)의 역할만 하고 있습니다.","殖는 “시체(歹)에 구더기가 들끓다” -> “번식하다, 불리다”라는 뜻의 글자입니다(直는 소리부)."],"sourceUrl":"https://nihongokanji.com/1436/"},"艦":{"id":1425,"char":"艦","hun":"큰 배 함","meaning":"“큰 배 함”. 군함, 큰 배","on":"カン","kun":"","explanation":["艦 = 舟 + 監。","(의미부) 「舟」는 “배”를 뜻합니다.","(소리부 겸 의미부) 「監」(カン)은 “감시하다, 감독하다”라는 뜻입니다.","艦는 “바다 위에서 적선을 감시하는(監) 커다란 배(舟)” -> “군함, 큰 배”라는 뜻의 글자입니다.","(監는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1437/"},"輩":{"id":1426,"char":"輩","hun":"무리 배","meaning":"“무리 배”. 무리, 패거리","on":"ハイ","kun":"","explanation":["輩 = 非 + 車。","(의미부) 「車」는 “수레”를 뜻합니다.","(소리부 겸 의미부) 「非」(ヒ)는 여기서는 “(수레 뒤를 일렬로 따르는) 사람들”을 그린 모양자로 쓰인 것입니다.","輩는 “수레(車) 뒤를 줄지어 따라가는 사람들(非)” -> “무리, 패거리”라는 뜻의 글자입니다.","(非는 소리부(ヒ -> ハイ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1438/"},"穴":{"id":1427,"char":"穴","hun":"구멍 혈","meaning":"“구멍 혈”. 구멍","on":"ケツ","kun":"あな","explanation":["穴는 “동굴의 입구”를 그린 상형문자입니다.","“동굴 입구” -> “구멍”이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/1439/"},"奇":{"id":1428,"char":"奇","hun":"기이할 기","meaning":"“기이할 기”. 진기한, 기묘한","on":"キ","kun":"","explanation":["奇 = 大 + 可。","「大」는 본래 “사람”을 그린 글자입니다.","可는 여기서는 “짐보따리”를 그린 모양자입니다.","奇는 “짐보따리(可) 안에 신기한 물건을 가득 들고있는 사람(大)” -> “기이하다, 신기하다”라는 뜻의 글자입니다.","(768.「寄」 모양 해설과 함께 연관지어 기억하시면 더 쉽게 기억할 수 있습니다.)"],"sourceUrl":"https://nihongokanji.com/1440/"},"慢":{"id":1429,"char":"慢","hun":"거만할 만","meaning":"“거만할 만”. 거만하다, 게으르다","on":"マン","kun":"","explanation":["慢 = 忄 + 日 + 罒 + 又。","「忄」는 “마음”을 뜻합니다.","「日」는 “태양”을 뜻합니다.","罒는 여기서는 「目」를 옆으로 기울인 것으로, “눈”을 뜻합니다.","「又」는 “손”을 뜻합니다.","慢는 “오만한 눈(罒)으로 위에서(日) 내려다보며 지시를 내리는(又) 거만함(忄)” -> “거만하다, 게으르다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1441/"},"鶴":{"id":1430,"char":"鶴","hun":"학 학","meaning":"“학 학”. 두루미, 학","on":"","kun":"つる","explanation":["鶴 = 隺 + 鳥。","(소리부 겸 의미부) 隺는 여기서는 「確」(カク)가 축약된 것으로, “확실하다, 단단하다”라는 뜻입니다.","(鶴에는 정식 음독이 없으나, 본래의 음독은 カク입니다.)","(의미부) 「鳥」는 “새”를 뜻합니다.","鶴는 “굳은 지조(確)를 상징하는 새(鳥)” -> “두루미, 학”이라는 뜻의 글자입니다.","(隺->確는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1442/"},"謀":{"id":1431,"char":"謀","hun":"꾀 모","meaning":"“꾀 모”. 모의하다, 계획하다","on":"ボウ、ム","kun":"はか(る)","explanation":["謀 = 言 + 甘 + 木。","「言」는 “말하다”라는 뜻입니다.","「甘」는 “달다, 달콤하다”라는 뜻입니다.","「木」는 “나무”를 뜻합니다.","謀는 “과수원 나무(木) 위의 달콤한(甘) 열매를 몰래 훔쳐먹기 위해 모의하다(言)” -> “모의하다, 계획하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1443/"},"拍":{"id":1432,"char":"拍","hun":"칠 박","meaning":"“칠 박”. 박수, 박자","on":"ハク、ヒョウ","kun":"","explanation":["拍 = 扌 + 白。","(의미부) 「扌」는 “손”을 뜻합니다.","(소리부) 「白」(ハク)는 여기서는 소리부(ハク -> ハク・ヒョウ)의 역할만 하고 있습니다.","拍는 “손뼉(扌)을 치다” -> “박수, 박자”라는 뜻의 글자입니다(白는 소리부)."],"sourceUrl":"https://nihongokanji.com/1444/"},"朗":{"id":1433,"char":"朗","hun":"밝을 랑","meaning":"“밝을 랑”. 밝은, 명랑한, 낭랑한","on":"ロウ","kun":"ほが(らか)","explanation":["朗 = 良 + 月。","「良」는 “좋다”라는 뜻입니다.","「月」는 “달”을 뜻합니다.","朗는 “달밤(月)의 즐거운(良) 분위기” -> “밝은, 명랑한, 낭랑한”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1445/"},"丈":{"id":1434,"char":"丈","hun":"어른 장","meaning":"“어른 장”. 어른, 남성, 튼튼함, 길이","on":"ジョウ","kun":"たけ","explanation":["丈는 “지팡이를 손(又)에 든 모습”을 그린 상형문자입니다.","“지팡이는 어른이 쓰는 것” -> “어른, 남성”","“튼튼한 지팡이” -> “튼튼함”","“길다란 지팡이” -> “길이의 단위”","라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/1446/"},"寛":{"id":1435,"char":"寛","hun":"너그러울 관","meaning":"“너그러울 관”. 너그럽다","on":"カン","kun":"","explanation":["寛 = 宀 + 艹 + 見。","「宀」는 “집”을 뜻합니다.","「艹」는 “풀”을 뜻합니다.","「見」는 “보다”라는 뜻입니다.","寛는 “집(宀)에서 화초(艹)를 감상하다(見)”라는 뜻의 글자입니다.","“여유로운 마음으로 화초를 감상하다” -> “여유롭다, 너그럽다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/1447/"},"覆":{"id":1436,"char":"覆","hun":"다시 복/덮을 부","meaning":"“다시 복/덮을 부”. 덮다, 뒤집어엎다","on":"フク","kun":"おお(う)、くつがえ(す)、くつがえ(る)","explanation":["覆 = 覀 + 復。","(의미부) 「覀」는 “덮다”라는 뜻입니다.","(소리부 겸 의미부) 「復」(フク)는 “되돌아가다”라는 뜻입니다.","覆는 “벗겨진 뚜껑을 다시(復) 덮어놓다(覀)” -> “덮다, 뒤집어엎다”라는 뜻의 글자입니다.","(復는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1448/"},"胞":{"id":1437,"char":"胞","hun":"세포 포","meaning":"“세포 포”. 세포","on":"ホウ","kun":"","explanation":["胞 = 月 + 包。","(의미부) 「月」는 “신체의 일부”를 뜻합니다.","(소리부 겸 의미부) 「包」(ホウ)는 “감싸다”라는 뜻입니다.","胞는 “신체 내부(月)를 감싸고 있는(包) 세포” -> “세포”라는 뜻의 글자입니다.","(包는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1449/"},"隔":{"id":1438,"char":"隔","hun":"사이 뜰 격","meaning":"“사이 뜰 격”. 사이를 띄우다, 간격","on":"カク","kun":"へだ(てる)、へだ(たる)","explanation":["隔 = ⻖ + 鬲。","「⻖」는 “언덕, 산”을 뜻합니다.","鬲는 “화로 위의 냄비(𠮛)”를 그린 모양자입니다(1058.「融」 모양 해설 참조).","隔는 “산(⻖)에 불이 나지 않도록 떨어진 곳에서 요리를 하다(鬲)” -> “간격, 사이를 띄우다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1450/"},"浄":{"id":1439,"char":"浄","hun":"깨끗할 정","meaning":"“깨끗할 정”. 깨끗한, 청명한","on":"ジョウ","kun":"","explanation":["浄 = 氵 + 争。","(의미부) 「氵」는 “물”을 뜻합니다.","(소리부 겸 의미부) 「争」(ソウ)는 “다투다, 경쟁하다”라는 뜻입니다.","浄는 “필사적으로(争) 우물을 파서 얻어낸 깨끗한 물(氵)” -> “깨끗한, 청명한”이라는 뜻의 글자입니다.","(争는 소리부(ソウ -> ジョウ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1451/"},"没":{"id":1440,"char":"没","hun":"빠질 몰","meaning":"“빠질 몰”. 가라앉다, 침몰하다","on":"ボツ","kun":"","explanation":["没 = 氵 + 殳。","「氵」는 “물”을 뜻합니다.","「殳」는 “때리다, 휘두르다”라는 뜻입니다.","没는 “물(氵)에 빠진 사람에게 채찍을 휘둘러(殳) 수장시키다” -> “침몰하다, 가라앉다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1452/"},"暇":{"id":1441,"char":"暇","hun":"틈 가","meaning":"“틈 가”. 여가","on":"カ","kun":"ひま","explanation":["暇 = 日 + 𡰥 + コ + 又。","「日」는 “태양”을 뜻합니다.","중간의 𡰥는 여기서는 “책장”을 그린 모양자입니다.","コ는 여기서는 “책”을 그린 모양자입니다.","「又」는 “손”을 뜻합니다.","暇는 “한가로운 낮(日)에 책장(𡰥)에서 책(コ)을 꺼내(又) 읽으며 여유를 즐기다” -> “여가”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1453/"},"肺":{"id":1442,"char":"肺","hun":"허파 폐","meaning":"“허파 폐”. 폐","on":"ハイ","kun":"","explanation":["肺 = 月 + 市。","「月」는 “신체의 일부”를 뜻합니다.","「市」는 “시장”을 뜻합니다.","肺는 “몸에 활기(市)를 불어넣는 신체기관(月)” -> “폐”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1454/"},"貞":{"id":1443,"char":"貞","hun":"곧을 정","meaning":"“곧을 정”. 곧다, 지조가 굳다","on":"テイ","kun":"","explanation":["貞 = ⺊ + 貝。","「貝」는 “재물, 돈”을 뜻합니다.","⺊는 여기서는 “망치”를 그린 모양자입니다.","貞는 “뇌물(貝)을 망치(⺊)로 내리쳐 부수다” -> “곧다, 지조가 굳다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1455/"},"鑑":{"id":1444,"char":"鑑","hun":"거울 감","meaning":"“거울 감”. 살펴보다, 식별하다, 본보기","on":"カン","kun":"かんが(みる)","explanation":["鑑 = 金 + 監。","(의미부) 「金」는 “황금”을 뜻합니다.","(소리부 겸 의미부) 「監」(カン)은 “감독하다, 감시하다”라는 뜻입니다.","鑑는 “순금(金)에 불순물이 섞이지 않았나 감시하다(監)” -> “식별하다, 살펴보다, 본보기”라는 뜻의 글자입니다.","(監는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1456/"},"飼":{"id":1445,"char":"飼","hun":"기를 사","meaning":"“기를 사”. 기르다, 사육하다","on":"シ","kun":"か(う)","explanation":["飼 = 食 + 司。","(의미부) 「食」는 “먹다”라는 뜻입니다.","(소리부 겸 의미부) 「司」(シ)는 “주관하다, 다스리다”라는 뜻입니다.","飼는 “직접 관리하며(司) 밥을 먹이다(食)” -> “기르다, 사육하다”라는 뜻의 글자입니다.","(司는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1457/"},"陰":{"id":1446,"char":"陰","hun":"그늘 음","meaning":"“그늘 음”. 그늘","on":"イン","kun":"かげ、かげ(る)","explanation":["陰 = ⻖ + 今 + 云。","「⻖」는 “언덕”을 뜻합니다.","「云」는 “구름”을 뜻합니다.","今는 여기서는 「云」가 변형된 것으로, “구름”을 뜻합니다.","陰는 “겹겹이 쌓인 구름(今+云)에 가려진 언덕(⻖)” -> “그늘”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1458/"},"銘":{"id":1447,"char":"銘","hun":"새길 명","meaning":"“새길 명”. 이름을 새기다, 기록해 남기다","on":"メイ","kun":"","explanation":["銘 = 金 + 名。","(의미부) 「金」는 “쇠, 금속”을 뜻합니다.","(소리부 겸 의미부) 「名」(メイ)는 “이름”을 뜻합니다.","銘는 “금속판(金)에 이름(名)을 새겨 오래도록 보존하다” -> “이름을 새기다, 기록에 남기다”라는 뜻의 글자입니다.","(名는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1459/"},"随":{"id":1448,"char":"随","hun":"따를 수","meaning":"“따를 수”. 따르다, 순응하다","on":"ズイ","kun":"","explanation":["随 = ⻖ + ⻌ + 有。","「⻖」는 “언덕, 산”을 뜻합니다.","「⻌」는 “길”을 뜻합니다.","「有」는 “있다”라는 뜻입니다.","随는 “험준한 산(⻖)까지 따라 올라오는(⻌) 충실한 수행원이 있다(有)” -> “따르다, 순응하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1460/"},"烈":{"id":1449,"char":"烈","hun":"매울 렬","meaning":"“매울 렬”. 맹렬한, 거센","on":"レツ","kun":"","explanation":["烈 = 列 + 灬。","(소리부 겸 의미부) 「列」(レツ)는 여기서는 “시체(「歹」)를 자르다(「刂」)“라는 뜻으로 쓰인 것입니다.","(의미부) 「灬」는 “불”을 뜻합니다.","烈는 “적의 시체(歹)를 난도질하고(刂) 불태우다(灬)” -> “맹렬한, 거센”이라는 뜻의 글자입니다.","(列는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1461/"},"尋":{"id":1450,"char":"尋","hun":"찾을 심","meaning":"“찾을 심”. 찾다, 캐묻다","on":"ジン","kun":"たず(ねる)","explanation":["尋 = ⺕ + 工 + 口 + 寸。","「⺕」는 “손”을 뜻합니다.","「工」는 “공작, 공정, 가공”을 뜻합니다.","「口」는 “입”을 뜻합니다.","「寸」는 “손”을 뜻합니다.","尋는 “양 손(⺕+寸)으로 작업(工)을 수행하며 방법을 묻다(口)” -> “찾다, 캐묻다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1462/"},"稿":{"id":1451,"char":"稿","hun":"볏짚/원고 고","meaning":"“볏짚/원고 고”. 원고","on":"コウ","kun":"","explanation":["稿 = 禾 + 高。","(의미부) 「禾」는 “곡식”을 뜻합니다.","(소리부 겸 의미부) 「高」(コウ)는 “높다”라는 뜻입니다.","稿는 “원고 뭉치가 쌓인 모습이 마치 볏짚(禾)이 높이 쌓인(高) 모습과 같다” -> “원고”라는 뜻의 글자입니다.","(高는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1463/"},"丹":{"id":1452,"char":"丹","hun":"붉을 단","meaning":"“붉을 단”. 붉은 빛, 꾸밈없음, 정성","on":"タン","kun":"","explanation":["丹는 “광산 입구에서 흘러나오는 붉은 빛(丶)”을 그린 상형문자입니다.","고대 중국에서는 발작을 진정시키는 약재로 “황화수은”이라는 붉은 빛의 광물을 사용했다고 합니다.","丹는 바로 이 황화수은이 채굴되는 광산을 그린 글자입니다.","“황화수은 광산에서 흘러나오는 황화수은의 붉은 빛” -> “붉은 빛”","“발작을 진정시키는 약재” -> “꾸밈없음, 정성”","이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/1464/"},"啓":{"id":1453,"char":"啓","hun":"열 계","meaning":"“열 계”. 깨우치다, 열다","on":"ケイ","kun":"","explanation":["啓 = 戸 + 攵 + 口。","「戸」는 “문”을 그린 것입니다.","「攵」는 “때리다, 치다”라는 뜻입니다.","「口」는 “입”을 뜻합니다.","啓는 “문(戸)을 두드리며(攵) 큰 소리로(口) 깨우다” -> “깨우치다, 열다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1465/"},"丘":{"id":1454,"char":"丘","hun":"언덕 구","meaning":"“언덕 구”. 언덕","on":"キュウ","kun":"おか","explanation":["丘는 “작은 산”의 모습을 본따 그린 상형문자입니다."],"sourceUrl":"https://nihongokanji.com/1466/"},"棟":{"id":1455,"char":"棟","hun":"마룻대 동","meaning":"“마룻대 동”. 용마루, 동(건물을 세는 말)","on":"トウ","kun":"むね、むな","explanation":["棟 = 木 + 東。","(의미부) 「木」는 여기서는 “나무기둥”을 뜻합니다.","(소리부 겸 의미부) 「東」(トウ)는 “동쪽”을 뜻합니다.","棟는 “건물 동쪽(東)의 거대한 나무기둥(木)” -> “용마루, 동”이라는 뜻의 글자입니다.","(東는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1467/"},"壌":{"id":1456,"char":"壌","hun":"흙덩이 양","meaning":"“흙덩이 양”. 토양, 대지","on":"ジョウ","kun":"","explanation":["壌 = 土 + 㐮。","(의미부) 「土」는 “흙”을 뜻합니다.","(소리부 겸 의미부) 「㐮」(ジョウ)는 “상복, 예복”을 뜻합니다.","壌는 “상복(㐮)을 입고 죽은 사람을 땅(土)에 묻다” -> “토양, 대지”라는 뜻의 글자입니다.","(㐮는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1468/"},"漫":{"id":1457,"char":"漫","hun":"흩어질 만","meaning":"“흩어질 만”. 느슨하다, 넓다","on":"マン","kun":"","explanation":["漫 = 氵 + 曼。","(의미부) 「氵」는 “물”을 뜻합니다.","(소리부 겸 의미부) 曼는 여기서는 「慢」(マン)이 축약된 것으로, “게으르다”라는 뜻입니다.","漫는 “드넓은 바다(氵) 위에서 한가롭게 늘어져(慢) 유람하다” -> “느슨하다, 넓다”라는 뜻의 글자입니다.","(曼->慢는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1469/"},"玄":{"id":1458,"char":"玄","hun":"검을 현","meaning":"“검을 현”. 검정, 심오한","on":"ゲン","kun":"","explanation":["玄 = 亠 + 幺。","亠는 여기서는 “천장”을 그린 모양자입니다.","「幺」는 “짧은 실”을 뜻합니다.","玄는 “송진을 발라 천장(亠)에 매달아놓은 새끼줄(幺)”이라는 뜻입니다.","옛날에는 줄에 송진을 발라 강도를 높였다고 합니다.","이때 송진을 바른 줄은 검붉은 빛을 띠게 됩니다.","“송진을 발라 가공한 검붉은 줄” -> “검정” -> “심오한”이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/1470/"},"粘":{"id":1459,"char":"粘","hun":"붙을 점","meaning":"“붙을 점”. 끈적한, 달라붙다","on":"ネン","kun":"ねば(る)","explanation":["粘 = 米 + 占。","「米」는 “쌀”을 뜻합니다.","占는 여기서는 “절구(口)와 절굿공이(⺊)”를 그린 모양자입니다.","粘는 “쌀(米)을 절구에 빻아(占) 만든 끈적한 떡” -> “끈적한, 달라붙다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1471/"},"悟":{"id":1460,"char":"悟","hun":"깨달을 오","meaning":"“깨달을 오”. 깨닫다","on":"ゴ","kun":"さと(る)","explanation":["悟 = 忄 + 五 + 口。","(의미부) 「忄」는 “마음”을 뜻합니다.","(소리부) 「五」(ゴ)는 여기서는 소리부의 역할만 하고 있습니다.","(의미부) 「口」는 “입”을 뜻합니다.","悟는 “가르침(口)을 마음(忄)으로 깨닫다” -> “깨닫다”라는 뜻의 글자입니다(五는 소리부)."],"sourceUrl":"https://nihongokanji.com/1472/"},"舗":{"id":1461,"char":"舗","hun":"펼 포","meaning":"“펼 포”. 점포, 펴다","on":"ホ","kun":"","explanation":["舗 = 舎 + 甫。","(의미부) 「舎」는 “숙소, 집, 저택”을 뜻합니다.","(소리부 겸 의미부) 「甫」(ホ)는 “채소밭”을 뜻합니다.","舗는 “집(舎) 앞에 채소(甫)를 늘어놓고 팔다” -> “점포, 펴다”라는 뜻의 글자입니다.","(甫는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1473/"},"妊":{"id":1462,"char":"妊","hun":"아이 밸 임","meaning":"“아이 밸 임”. 임신하다","on":"ニン","kun":"","explanation":["妊 = 女 + 壬。","(의미부) 「女」는 “여자”를 뜻합니다.","(소리부 겸 의미부) 壬는 여기서는 「任」(ニン)이 축약된 것으로, “임무, 의무”를 뜻합니다.","妊은 “여자(女)의 일(任)은 아이를 낳는 것” -> “임신”이라는 뜻의 글자입니다.","(壬->任는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1474/"},"熟":{"id":1463,"char":"熟","hun":"익을 숙","meaning":"“익을 숙”. 익다, 성숙하다, 여물다","on":"ジュク","kun":"う(れる)","explanation":["熟 = 孰 + 灬。","(소리부) 孰는 여기서는 「塾」(ジュク)가 축약된 것으로, 소리부의 역할만 하고 있습니다.","(의미부) 「灬」는 “불”을 뜻합니다.","熟는 “음식을 익히다(灬)” -> “익다, 성숙하다, 여물다”라는 뜻의 글자입니다(孰->塾는 소리부)."],"sourceUrl":"https://nihongokanji.com/1475/"},"恩":{"id":1464,"char":"恩","hun":"은혜 은","meaning":"“은혜 은”. 은혜","on":"オン","kun":"","explanation":["恩 = 因 + 心。","(소리부 겸 의미부) 「因」(イン)은 “원인, 연유”를 뜻합니다.","(의미부) 「心」는 “마음”을 뜻합니다.","恩는 “감사한 마음(心)을 갖게 된 연유(因)” -> “은혜”라는 뜻의 글자입니다.","(因는 소리부(イン -> オン)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1476/"},"騰":{"id":1465,"char":"騰","hun":"오를 등","meaning":"“오를 등”. 뛰어오르다, 높아지다","on":"トウ","kun":"","explanation":["騰 = 月 + 龹 + 馬。","月+龹는 여기서는 「勝」가 축약된 것으로, “이기다”라는 뜻입니다.","「馬」는 “말”을 뜻합니다.","騰는 “경주에서 승리(勝)하고 하늘 높이 뛰어오르는 말(馬)” -> “뛰어오르다, 높아지다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1477/"},"往":{"id":1466,"char":"往","hun":"갈 왕","meaning":"“갈 왕”. 가다, 향하다","on":"オウ","kun":"","explanation":["往 = 彳 + 主。","(의미부) 「彳」는 “길”을 뜻합니다.","(소리부 겸 의미부) 主는 여기서는 「王」(オウ)가 잘못 변형된 것으로, “왕”을 뜻합니다.","往는 “왕(王)이 행차하다(彳)” -> “가다, 향하다”라는 뜻의 글자입니다.","(主->王는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1478/"},"豆":{"id":1467,"char":"豆","hun":"콩 두","meaning":"“콩 두”. 콩","on":"トウ、ズ","kun":"まめ","explanation":["豆는 “콩을 담을 때 쓰던 제기그릇”을 그린 상형문자입니다."],"sourceUrl":"https://nihongokanji.com/1479/"},"遂":{"id":1468,"char":"遂","hun":"드디어 수","meaning":"“드디어 수”. 이루다, 성취하다","on":"スイ","kun":"と(げる)","explanation":["遂 = ⻌ + 豕 + 丷。","「⻌」는 “길”을 뜻합니다.","「豕」는 “돼지”를 뜻합니다.","丷는 여기서는 “풀숲”을 그린 모양자입니다.","遂는 “멧돼지(豕)가 풀숲(丷)을 헤치고 달아나(⻌) 사냥꾼에게서 도망치는 데 성공하다” -> “이루다, 성취하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1480/"},"狂":{"id":1469,"char":"狂","hun":"미칠 광","meaning":"“미칠 광”. 미친, 미치광이","on":"キョウ","kun":"くる(う)、くる(おしい)","explanation":["狂 = 犭 + 王。","「犭」는 “개”를 뜻합니다.","「王」는 “왕”을 뜻합니다.","狂는 “미친개(犭)처럼 날뛰는 폭군(王)” -> “미친, 미치광이”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1481/"},"岐":{"id":1470,"char":"岐","hun":"갈림길 기","meaning":"“갈림길 기”. 갈림길","on":"キ","kun":"","explanation":["岐 = 山 + 支。","「山」는 “산”을 뜻합니다.","「支」는 “지부, 지류”라는 뜻입니다.","岐는 “여러 갈래(支)로 뻗은 산맥(山)” -> “갈림길”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1482/"},"陛":{"id":1471,"char":"陛","hun":"대궐 섬돌 폐","meaning":"“대궐 섬돌 폐”. 폐하, 왕","on":"ヘイ","kun":"","explanation":["陛 = ⻖ + 比 + 土。","「⻖」는 “언덕”을 뜻합니다.","「比」는 본래 “나란히 늘어선 사람들”을 그린 글자입니다(링크 참조).","「土」는 “땅”을 뜻합니다.","陛는 “땅(土)에 늘어선 사람들(比)이 언덕(⻖) 위의 왕을 향해 경배하다” -> “왕, 폐하”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1483/"},"緯":{"id":1472,"char":"緯","hun":"씨 위","meaning":"“씨 위”. 가로, 횡","on":"イ","kun":"","explanation":["緯 = 糸 + 韋。","(의미부) 「糸」는 “실”을 뜻합니다.","(소리부 겸 의미부) 「韋」(イ)는 “성 주위를 돌며 경계서는 발들”을 뜻합니다.","緯는 “성의 둘레(韋)에 가로로 밧줄(糸)을 치고 출입을 막다” -> “가로, 횡”이라는 뜻의 글자입니다.","(韋는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1484/"},"培":{"id":1473,"char":"培","hun":"북돋을 배","meaning":"“북돋을 배”. 배양하다","on":"バイ","kun":"つちか(う)","explanation":["培 = 土 + 咅。","(의미부) 「土」는 “흙, 땅”을 뜻합니다.","(소리부 겸 의미부) 「咅」(バイ)는 “화분 위의 화초”를 뜻합니다.","培는 “화분(咅)에 흙(土)을 넣고 화초를 키우다” -> “배양하다”라는 뜻의 글자입니다.","(咅는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1485/"},"衰":{"id":1474,"char":"衰","hun":"쇠할 쇠","meaning":"“쇠할 쇠”. 약해지다, 쇠하다","on":"スイ","kun":"おとろ(える)","explanation":["衰 = 衣 + 口 + 一。","「衣」는 “옷”을 뜻합니다.","口+一는 여기서는 “(옷이) 여기저기 찢기고(一) 구멍이 뚫린(口) 모습”을 그린 모양자입니다.","衰는 “여기저기 찢기고(一) 구멍뚫린(口) 낡은 옷(衣)” -> “약해지다, 쇠하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1486/"},"艇":{"id":1475,"char":"艇","hun":"배 정","meaning":"“배 정”. 작은 배","on":"テイ","kun":"","explanation":["艇 = 舟 + 廷。","(의미부) 「舟」는 “배”를 뜻합니다.","(소리부 겸 의미부) 廷는 여기서는 「庭」(テイ)가 축약된 것으로, “마당, 뜰”을 뜻합니다.","艇는 “집 앞의 뜰(庭)처럼 작은 배(舟)” -> “작은 배, 나룻배”라는 뜻의 글자입니다.","(廷->庭는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1487/"},"屈":{"id":1476,"char":"屈","hun":"굽힐 굴","meaning":"“굽힐 굴”. 굽히다","on":"クツ","kun":"","explanation":["屈 = 尸 + 出。","「尸」는 “앉아있는 사람”을 뜻합니다.","「出」는 “나오다”라는 뜻입니다.","屈는 “앉아있던 사람(尸)이 자리에서 일어나(出) 허리를 굽혀 인사하다” -> “굽히다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1488/"},"径":{"id":1477,"char":"径","hun":"지름길 경","meaning":"“지름길 경”. 지름길, 지름, 직경","on":"ケイ","kun":"","explanation":["径 = 彳 + 圣。","(의미부) 「彳」는 “길”을 뜻합니다.","(소리부 겸 의미부) 「圣」(ケイ)는 “지나가다”라는 뜻입니다.","径는 “길(彳)을 가로질러 지나가다(圣)” -> “지름길, 직경, 지름”이라는 뜻의 글자입니다.","(圣는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1489/"},"淡":{"id":1478,"char":"淡","hun":"“맑을 담’","meaning":"“맑을 담’. 엷다, 꾸밈없는, 담백한","on":"タン","kun":"あわ(い)","explanation":["淡 = 氵 + 炎。","「氵」는 “물”을 뜻합니다.","「炎」는 “화염”을 뜻합니다.","淡는 “불길(炎)에 물(氵)을 끼얹어 약하게 하다” -> “엷다, 꾸밈없는, 담백한”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1490/"},"抽":{"id":1479,"char":"抽","hun":"뽑을 추","meaning":"“뽑을 추”. 빼내다, 뽑아내다","on":"チュウ","kun":"","explanation":["抽 = 扌 + 由。","(의미부) 「扌」는 “손”을 뜻합니다.","(소리부 겸 의미부) 「由」(ユウ)는 “유래, 연원”을 뜻합니다.","抽는 “출처(由)로부터 뽑아내다(扌)” -> “빼내다, 뽑아내다”라는 뜻의 글자입니다.","(由는 소리부(ユウ -> チュウ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1491/"},"披":{"id":1480,"char":"披","hun":"헤칠 피","meaning":"“헤칠 피”. 펼치다, 풀어헤치다","on":"ヒ","kun":"","explanation":["披 = 扌 + 皮。","(의미부) 「扌」는 “손”을 뜻합니다.","(소리부 겸 의미부) 「皮」(ヒ)는 “가죽, 껍질”을 뜻합니다.","披는 “겉껍질(皮)을 뜯어내고(扌) 안을 펼치다” -> “펼치다, 풀어헤치다”라는 뜻의 글자입니다.","(皮는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1492/"},"廷":{"id":1481,"char":"廷","hun":"조정 정","meaning":"“조정 정”. 법정, 조정, 관아","on":"テイ","kun":"","explanation":["廷 = 廴 + 壬。","「廴」는 “길, 걷다”라는 뜻입니다.","壬는 여기서는 “팔을 휘두르며 걷는 사람”을 그린 모양자입니다.","廷는 “관청의 복도(廴)를 휘적휘적 걷는 사람(壬)” -> “법정, 조정, 관아”라는 뜻의 글자입니다.","참고)","廷는 523. 「庭」의 소리부이기도 합니다."],"sourceUrl":"https://nihongokanji.com/1493/"},"錦":{"id":1482,"char":"錦","hun":"비단 금","meaning":"“비단 금”. 비단","on":"キン","kun":"にしき","explanation":["錦 = 金 + 白 + 巾。","(소리부 겸 의미부) 「金」(キン)은 “쇠, 황금”을 뜻합니다.","(의미부) 「白」는 “흰색”을 뜻합니다.","(의미부) 「巾」는 “수건, 천”을 뜻합니다.","錦는 “반짝반짝(金) 윤기가 나는 하얀(白) 천(巾)” -> “비단”이라는 뜻의 글자입니다.","(金는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1494/"},"准":{"id":1483,"char":"准","hun":"준할 준","meaning":"“준할 준”. 준하다","on":"ジュン","kun":"","explanation":["准는 「準」(ジュン)을 축약한 간체자입니다. 음독도 같습니다.","“기준(準)” -> “준하다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/1495/"},"奨":{"id":1484,"char":"奨","hun":"장려할 장","meaning":"“장려할 장”. 권장하다, 장려하다","on":"ショウ","kun":"","explanation":["奨 = 将 + 大。","(소리부 겸 의미부) 「将」(ショウ)는 “장래, 장차”라는 뜻입니다.","(의미부) 「大」는 “크다”라는 뜻입니다.","奨는 “장래(将)에 위대한(大) 사람이 되도록 장려하다” -> “권장하다, 장려하다”라는 뜻의 글자입니다.","(将는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1496/"},"浸":{"id":1485,"char":"浸","hun":"잠길 침","meaning":"“잠길 침”. 잠기다, 스며들다","on":"シン","kun":"ひた(す)、ひた(る)","explanation":["浸 = 氵 + 𠬶。","「氵」는 “물”을 뜻합니다.","𠬶는 “빗자루(「帚」)를 든 손(「又」)“을 뜻합니다.","浸는 “홍수로 집 안까지 들어온 물(氵)을 빗자루로 쓸어내다(𠬶)” -> “잠기다, 스며들다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1497/"},"剰":{"id":1486,"char":"剰","hun":"남을 잉","meaning":"“남을 잉”. 남다, 여분, 잉여","on":"ジョウ","kun":"","explanation":["剰 = 乗 + 刂。","(소리부 겸 의미부) 「乗」(ジョウ)는 본래 “나무 위에 올라탄 사람”을 그린 글자입니다(링크 참조).","(의미부) 「刂」는 “칼”을 뜻합니다.","剰는 “나무 위에 올라가(乗) 필요 없는 가지를 쳐내다(刂)” -> “남다, 여분, 잉여”라는 뜻의 글자입니다.","(乗는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1498/"},"胆":{"id":1487,"char":"胆","hun":"쓸개 담","meaning":"“쓸개 담”. 담력, 쓸개","on":"タン","kun":"","explanation":["胆 = 月 + 旦。","(의미부) 「月」는 “신체의 일부”를 뜻합니다.","(소리부) 旦(タン – “아침 단”)은 “아침”을 뜻하는 상용한자입니다.","다만 여기서는 소리부의 역할만 하고 있습니다.","胆는 “신체의 일부(月)” -> “쓸개, 담력”이라는 뜻의 글자입니다(旦는 소리부)."],"sourceUrl":"https://nihongokanji.com/1499/"},"繊":{"id":1488,"char":"繊","hun":"가늘 섬","meaning":"“가늘 섬”. 가늘다, 섬세하다, 곱다","on":"セン","kun":"","explanation":["繊 = 糸 + 𢦏 + 业。","「糸」는 “실”을 뜻합니다.","𢦏는 여기서는 「裁」가 축약된 것으로, “재단하다”라는 뜻입니다.","业는 여기서는 「並」가 축약된 것으로, “나란히”라는 뜻입니다.","繊는 “실(糸)을 가느다란 선에 맞추어(並) 꿰매다(裁)” -> “섬세한, 가늘다, 곱다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1500/"},"駒":{"id":1489,"char":"駒","hun":"망아지 구","meaning":"“망아지 구”. 망아지","on":"","kun":"こま","explanation":["駒 = 馬 + 句。","(의미부) 「馬」는 “말”을 뜻합니다.","(소리부) 「句」(ク)는 여기서는 소리부의 역할만 하고 있습니다.","(駒에는 정식 음독이 없으나, 본래의 음독은 ク입니다.)","駒는 “말(馬)의 새끼” -> “망아지”라는 뜻의 글자입니다(句는 소리부)."],"sourceUrl":"https://nihongokanji.com/1501/"},"虚":{"id":1490,"char":"虚","hun":"빌 허","meaning":"“빌 허”. 텅 비다, 없다, 공허","on":"キョ、コ","kun":"","explanation":["虚 = 虍 + 业。","「虍」는 “호랑이”를 뜻합니다.","业는 여기서는 “(호랑이의) 이빨”을 그린 모양자입니다.","虚는 “이빨(业) 빠진 호랑이(虍)” -> “없다, 공허, 텅 비다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1502/"},"霊":{"id":1491,"char":"霊","hun":"신령 령","meaning":"“신령 령”. 영혼, 영","on":"レイ、リョウ","kun":"たま","explanation":["霊 = 雨 + 一 + 亚。","「雨」는 “비”를 뜻합니다.","아래쪽의 一+亚는 여기서는 「並」가 변형된 것으로, “나란히”라는 뜻입니다.","霊는 “짙은 안개(雨)가 나란히 퍼져(並) 주위를 뒤덮다”라는 뜻입니다.","“유령이 나올 것 같은 으스스한 분위기” -> “영혼, 영”이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/1503/"},"帳":{"id":1492,"char":"帳","hun":"장막 장","meaning":"“장막 장”. 장막, 커튼, 장부","on":"チョウ","kun":"","explanation":["帳 = 巾 + 長。","(의미부) 「巾」는 “수건, 천”을 뜻합니다.","(소리부 겸 의미부) 「長」(チョウ)는 “길다”라는 뜻입니다.","帳는 “길다란(長) 천(巾)” -> “장막, 장부”라는 뜻의 글자입니다.","(長는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1504/"},"悔":{"id":1493,"char":"悔","hun":"뉘우칠 회","meaning":"“뉘우칠 회”. 후회, 분함","on":"カイ","kun":"く(いる)、く(やむ)、くや(しい)","explanation":["悔 = 忄 + 毎。","(의미부) 「忄」는 “마음”을 뜻합니다.","(소리부 겸 의미부) 「毎」(マイ)는 “매번”이라는 뜻입니다.","悔는 “매일(毎) 마음속(忄)에 떠오를 정도로 후회되는 일” -> “후회, 분함”이라는 뜻의 글자입니다.","(毎는 소리부(マイ -> カイ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1505/"},"諭":{"id":1494,"char":"諭","hun":"타이를 유","meaning":"“타이를 유”. 타이르다","on":"ユ","kun":"さと(す)","explanation":["諭 = 言 + 俞。","(의미부) 「言」는 “말하다”라는 뜻입니다.","(소리부 겸 의미부) 「俞」(ユ)는 “보내다”라는 뜻입니다.","諭는 “충고의 말(言)을 보내다(俞)” -> “타이르다”라는 뜻의 글자입니다.","(俞는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1506/"},"惨":{"id":1495,"char":"惨","hun":"참혹할 참","meaning":"“참혹할 참”. 참혹한, 비참한","on":"サン、ザン","kun":"みじ(め)","explanation":["惨 = 忄 + 参。","(의미부) 「忄」는 “마음”을 뜻합니다.","(소리부 겸 의미부) 「参」(サン)은 “참여하다, 참배하다”라는 뜻입니다.","惨는 “죽은 자식의 묘에 참배(参)하는 슬픈 마음(忄)” -> “참혹한, 비참한”이라는 뜻의 글자입니다.","(参는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1507/"},"虐":{"id":1496,"char":"虐","hun":"모질 학","meaning":"“모질 학”. 모진, 가혹한","on":"ギャク","kun":"しいた(げる)","explanation":["虐 = 虍 + ㅌ。","「虍」는 “호랑이”를 뜻합니다.","ㅌ는 여기서는 “호랑이의 발톱”을 그린 모양자입니다.","虐는 “호랑이(虍)가 발톱(ㅌ)으로 할퀴다” -> “모진, 가혹한”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1508/"},"翻":{"id":1497,"char":"翻","hun":"날 번","meaning":"“날 번”. 뒤집히다, 번역하다, 나부끼다","on":"ホン","kun":"ひるがえ(る)、ひるがえ(す)","explanation":["翻 = 番 + 羽。","(소리부) 「番」(バン)은 여기서는 소리부(バン -> ホン)의 역할만 하고 있습니다.","(의미부) 「羽」는 “날개”를 뜻합니다.","翻는 “날개(羽)를 퍼덕이다” -> “나부끼다, 뒤집다” -> “번역하다”라는 뜻의 글자입니다(番는 소리부)."],"sourceUrl":"https://nihongokanji.com/1509/"},"墜":{"id":1498,"char":"墜","hun":"떨어질 추","meaning":"“떨어질 추”. 추락하다, 떨어지다","on":"ツイ","kun":"","explanation":["墜 = 隊 + 土。","(소리부 겸 의미부) 「隊」(タイ)는 “조직, 무리, 부대”를 뜻합니다.","(의미부) 「土」는 “흙, 땅”을 뜻합니다.","墜는 “전투기 부대(隊)가 지상(土)으로 추락하다” -> “추락하다, 떨어지다”라는 뜻의 글자입니다.","(部는 소리부(タイ -> ツイ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1510/"},"沼":{"id":1499,"char":"沼","hun":"못 소","meaning":"“못 소”. 늪, 못","on":"ショウ","kun":"ぬま","explanation":["沼 = 氵 + 召。","(의미부) 「氵」는 “물”을 뜻합니다.","(소리부 겸 의미부) 「召」(ショウ)는 “부르다”라는 뜻입니다.","沼는 “죽음을 부르는(召) 늪지대(氵)” -> “늪, 못”이라는 뜻의 글자입니다.","(召는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1511/"},"据":{"id":1500,"char":"据","hun":"의거할 거","meaning":"“의거할 거”. 자리잡다, 차려놓다","on":"","kun":"す(える)、す(わる)","explanation":["据 = 扌 + 居。","「扌」는 “손”을 뜻합니다.","「居」는 “살다, 거주하다”라는 뜻입니다.","据는 “사는 집(居)에 기물을 설치하다(扌)” -> “자리잡다, 차려놓다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1512/"},"肥":{"id":1501,"char":"肥","hun":"살찔 비","meaning":"“살찔 비”. 비옥하다, 살찌다, 비료","on":"ヒ","kun":"こ(える)、こえ、こ(やす)、こ(やし)","explanation":["肥 = 月 + 巴。","「月」는 “고기”를 뜻합니다.","「巴」는 “꼬리”를 뜻합니다.","肥는 “꼬리(巴)까지 통통하게 살찐 고기(月)” -> “비옥하다, 살찌다, 비료”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1513/"},"徐":{"id":1502,"char":"徐","hun":"천천히 할 서","meaning":"“천천히 할 서”. 천천히, 여유로운","on":"ジョ","kun":"","explanation":["徐 = 彳 + 余。","「彳」는 “길”을 뜻합니다.","「余」는 본래 “잎이 풍성한 나무”를 그린 글자입니다.","徐는 “가로수(余) 길(彳)을 천천히 걷다” -> “천천히, 여유로운”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1514/"},"糖":{"id":1503,"char":"糖","hun":"엿 당","meaning":"“엿 당”. 당, 설탕","on":"トウ","kun":"","explanation":["糖 = 米 + 广 + ⺕ + 丨 + 口。","「米」는 “쌀”을 뜻합니다.","「广」는 “건물, 집”을 뜻합니다.","「⺕」는 “손”을 뜻합니다.","丨+口는 여기서는 “절굿공이(丨)와 절구(口)”를 그린 모양자입니다.","糖는 “방앗간(广)에서 쌀(米)을 절구(丨+口)에 빻아(⺕) 만든 설탕” -> “당, 설탕”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1515/"},"搭":{"id":1504,"char":"搭","hun":"탈 탑","meaning":"“탈 탑”. 타다, 싣다","on":"トウ","kun":"","explanation":["搭 = 扌 + 荅。","(의미부) 「扌」는 “손”을 뜻합니다.","(소리부 겸 의미부) 荅는 여기서는 「塔」(トウ)가 축약된 것으로, “탑”을 뜻합니다.","搭는 “탑(塔) 꼭대기로 기어 올라가(扌) 앉다” -> “타다, 싣다”라는 뜻의 글자입니다.","(荅->塔는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1516/"},"盾":{"id":1505,"char":"盾","hun":"방패 순","meaning":"“방패 순”. 방패","on":"ジュン","kun":"たて","explanation":["盾 = 𠂆 + 十 + 目。","𠂆+十는 여기서는 “투구(𠂆)의 차양(十)”을 그린 모양자입니다.","「目」는 “눈”을 뜻합니다.","盾는 “눈(目)을 보호하는 투구(𠂆)의 차양(十)” -> “막다” -> “방패”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1517/"},"脈":{"id":1506,"char":"脈","hun":"줄기 맥","meaning":"“줄기 맥”. 줄기, 맥, 혈관","on":"ミャク","kun":"","explanation":["脈 = 月 + 𠂢。","「月」는 “신체의 일부”를 뜻합니다.","𠂢는 “물줄기가 여러 갈래로 갈라져 흘러가는 모습”을 그린 모양자입니다(1026.「派」 모양 해설 참조).","脈는 “몸(月) 구석구석 퍼져있는 혈관(𠂢)” -> “줄기, 맥, 혈관”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1518/"},"滝":{"id":1507,"char":"滝","hun":"폭포","meaning":"폭포","on":"","kun":"たき","explanation":["滝 = 氵 + 竜。","「氵」는 “물”을 뜻합니다.","「竜」는 “용”을 뜻합니다.","滝는 “폭포수(氵)를 거슬러 올라가는 용(竜)” -> “폭포”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1519/"},"軌":{"id":1508,"char":"軌","hun":"바퀴 자국 궤","meaning":"“바퀴 자국 궤”. 궤도, 정해진 길","on":"キ","kun":"","explanation":["軌 = 車 + 九。","(의미부) 「車」는 “수레, 차”를 뜻합니다.","(소리부 겸 의미부) 「九」(キュウ)는 “아홉”을 뜻합니다.","軌는 “아홉 대(九)의 수레(車)가 지나간 바퀴 자국” -> “궤도, 정해진 길”이라는 뜻의 글자입니다.","(九는 소리부(キュウ -> キ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1520/"},"俵":{"id":1509,"char":"俵","hun":"나누어줄 표","meaning":"“나누어줄 표”. 부대, 섬(‘쌀 한 섬’ 등)","on":"ヒョウ","kun":"たわら","explanation":["俵 = 亻 + 表。","(의미부) 「亻」는 “사람”을 뜻합니다.","(소리부) 「表」(ヒョウ)는 여기서는 소리부의 역할만 하고 있습니다.","俵는 “쌀 한 섬을 등에 진 사람(亻)” -> “부대, 섬”이라는 뜻의 글자입니다(表는 소리부)."],"sourceUrl":"https://nihongokanji.com/1521/"},"妨":{"id":1510,"char":"妨","hun":"방해할 방","meaning":"“방해할 방”. 방해하다","on":"ボウ","kun":"さまた(げる)","explanation":["妨 = 女 + 方。","(의미부) 「女」는 “여자”를 뜻합니다.","(소리부 겸 의미부) 「方」(ホウ)는 “방향”을 뜻합니다.","妨는 “여색(女)에 지나치게 빠지는 것은 목표를 향해 나아가는(方) 데에 방해된다” -> “방해하다”라는 뜻의 글자입니다.","(方는 소리부(ホウ -> ボウ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1522/"},"擦":{"id":1511,"char":"擦","hun":"문지를 찰","meaning":"“문지를 찰”. 문지르다","on":"サツ","kun":"す(る)、す(れる)","explanation":["擦 = 扌 + 察。","(의미부) 「扌」는 “손”을 뜻합니다.","(소리부) 「察」(サツ)는 여기서는 소리부의 역할만 하고 있습니다.","察는 “손(扌)으로 문지르다” -> “문지르다”라는 뜻의 글자입니다(察는 소리부)."],"sourceUrl":"https://nihongokanji.com/1523/"},"鯨":{"id":1512,"char":"鯨","hun":"고래 경","meaning":"“고래 경”. 고래","on":"ゲイ","kun":"くじら","explanation":["鯨 = 魚 + 京。","(의미부) 「魚」는 “물고기”를 뜻합니다.","(소리부 겸 의미부) 「京」(ケイ)는 “수도, 대도시”를 뜻합니다.","鯨는 “커다란(京) 물고기(魚)” -> “고래”라는 뜻의 글자입니다.","(京는 소리부(ケイ -> ゲイ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1524/"},"荘":{"id":1513,"char":"荘","hun":"장엄할/별장 장","meaning":"“장엄할/별장 장”. 장엄하다, 별장","on":"ソウ","kun":"","explanation":["荘 = 艹 + 壮。","(의미부) 「艹」는 “풀”을 뜻합니다.","(소리부 겸 의미부) 壮(ソウ – “씩씩할 장”)은 “장하다, 씩씩하다”라는 뜻의 상용한자입니다.","荘는 “장엄하게(壮) 펼쳐진 초원(艹) 위의 별장“ -> “장엄하다, 별장”이라는 뜻의 글자입니다.","(壮는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1525/"},"諾":{"id":1514,"char":"諾","hun":"허락할 낙","meaning":"“허락할 낙”. 승낙하다","on":"ダク","kun":"","explanation":["諾 = 言 + 若。","(의미부) 「言」는 “말하다”라는 뜻입니다.","(소리부 겸 의미부) 「若」(ジャク)는 본래 “땅에 엎드린 젊은이”를 그린 글자입니다(링크 참조).","諾는 “엎드린 젊은이(若)에게 허락을 내리다(言)” -> “승낙하다”라는 뜻의 글자입니다.","(若는 소리부(ジャク -> ダク)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1526/"},"雷":{"id":1515,"char":"雷","hun":"우레 뢰","meaning":"“우레 뢰”. 천둥","on":"ライ","kun":"かみなり","explanation":["雷 = 雨 + 田。","「雨」는 “비”를 뜻합니다.","「田」는 “밭”을 뜻합니다.","雷는 “폭풍우(雨)가 휘몰아치는 밭(田)” -> “천둥”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1527/"},"漂":{"id":1516,"char":"漂","hun":"떠다닐 표","meaning":"“떠다닐 표”. 표류하다, 떠돌다","on":"ヒョウ","kun":"ただよ(う)","explanation":["漂 = 氵 + 票。","(의미부) 「氵」는 “물”을 뜻합니다.","(소리부 겸 의미부) 「票」(ヒョウ)는 “쪽지, 표”라는 뜻입니다.","漂는 “물(氵) 위를 떠다니는 종이쪽지(票)” -> “표류하다, 떠돌다”라는 뜻의 글자입니다.","(票는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1528/"},"懐":{"id":1517,"char":"懐","hun":"품을 회","meaning":"“품을 회”. 품다, 안에 가지다, 그리워하다","on":"カイ","kun":"なつ(かしい)、なつ(かしむ)、なつ(く)、なつ(ける)、ふところ","explanation":["懐 = 忄 + 十 + 𭾱。","(의미부) 「忄」는 “마음”을 뜻합니다.","(소리부 겸 의미부) 十+𭾱는 여기서는 「壊」(カイ)가 축약된 것으로, “부서지다, 파괴되다”라는 뜻입니다.","懐는 “전쟁으로 파괴된(壊) 고향을 마음(忄) 속으로 그리워하다” -> “품다, 그리워하다”라는 뜻의 글자입니다.","(壊는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1529/"},"勘":{"id":1518,"char":"勘","hun":"헤아릴 감","meaning":"“헤아릴 감”. 헤아리다, 직감","on":"カン","kun":"","explanation":["勘 = 甘 + 匹 + 力。","(소리부) 「甘」(カン)은 여기서는 소리부의 역할만 하고 있습니다.","(의미부) 「匹」는 “짝, 상대”를 뜻합니다.","(의미부) 「力」는 “힘”을 뜻합니다.","勘는 “상대(匹)의 전력(力)을 가늠하다” -> “헤아리다, 가늠하다, 직감”이라는 뜻의 글자입니다(甘는 소리부)."],"sourceUrl":"https://nihongokanji.com/1530/"},"栽":{"id":1519,"char":"栽","hun":"심을 재","meaning":"“심을 재”. 재배하다, 심다","on":"サイ","kun":"","explanation":["栽 = 𢦏 + 木。","(소리부) 「𢦏」(サイ)는 여기서는 소리부의 역할만 하고 있습니다.","(의미부) 「木」는 “나무”를 뜻합니다.","栽는 “나무(木)를 심다” -> “재배하다, 심다”라는 뜻의 글자입니다(𢦏는 소리부)."],"sourceUrl":"https://nihongokanji.com/1531/"},"拐":{"id":1520,"char":"拐","hun":"후릴 괴","meaning":"“후릴 괴”. 유괴하다, 꾀어내다, 유인하다","on":"カイ","kun":"","explanation":["拐 = 扌 + 口 + 刀。","「扌」는 “손”을 뜻합니다.","「口」는 “입”을 뜻합니다.","「刀」는 “칼”을 뜻합니다.","拐는 “말(口)로 유혹하고 칼(刀)로 위협해서 데려가다(扌)” -> “유괴하다, 꾀어내다, 유인하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1532/"},"駄":{"id":1521,"char":"駄","hun":"실을 타","meaning":"“실을 타”. 무가치한, 짐을 싣다","on":"ダ","kun":"","explanation":["駄 = 馬 + 太。","(의미부) 「馬」는 “말”을 뜻합니다.","(소리부 겸 의미부) 「太」(タ)는 “크다, 거대하다”라는 뜻입니다.","駄는 “말(馬)이 감당 못할 정도로 큰(太) 짐을 억지로 실으려고 하다” -> “쓸모없는, 무가치한, 짐을 싣다”라는 뜻의 글자입니다.","(太는 소리부(タ -> ダ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1533/"},"添":{"id":1522,"char":"添","hun":"더할 첨","meaning":"“더할 첨”. 더하다, 보태다","on":"テン","kun":"そ(える)、そ(う)","explanation":["添 = 氵 + 夭 + ⺗。","(의미부) 「氵」는 “물”을 뜻합니다.","(소리부 겸 의미부) 夭는 「天」(テン)이 살짝 변형된 것으로, “하늘”을 뜻합니다.","(의미부) ⺗는 여기서는 “빗방울”을 그린 모양자입니다.","添는 “하늘(夭)에서 떨어지는 빗방울(⺗)이 강물(氵)에 더해지다” -> “더하다, 보태다”라는 뜻의 글자입니다.","(天는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1534/"},"冠":{"id":1523,"char":"冠","hun":"갓 관","meaning":"“갓 관”. 왕관, 관","on":"カン","kun":"かんむり","explanation":["冠 = 冖 + 元 + 寸。","(의미부) 冖는 여기서는 “왕관”을 그린 모양자입니다.","(소리부 겸 의미부) 「元」(ガン)은 본래 “사람의 머리”를 그린 글자입니다(링크 참조).","(의미부) 「寸」는 “손”을 뜻합니다.","冠는 “머리(元)에 왕관(冖)을 씌우는 손(寸)” -> “왕관, 관”이라는 뜻의 글자입니다.","(元는 소리부(ガン -> カン)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1535/"},"斜":{"id":1524,"char":"斜","hun":"비낄 사","meaning":"“비낄 사”. 비스듬한, 경사","on":"シャ","kun":"なな(め)","explanation":["斜 = 余 + 斗。","「余」는 “남다, 여분의”라는 뜻입니다.","「斗」는 “국자”를 뜻합니다.","斜는 “여분(余)의 음식을 자신에게 퍼오다(斗)”라는 뜻입니다.","“사사로운 이득은 자신에게 기울어진다” -> “비스듬한, 경사”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/1536/"},"鏡":{"id":1525,"char":"鏡","hun":"거울 경","meaning":"“거울 경”. 거울","on":"キョウ","kun":"かがみ","explanation":["鏡 = 金 + 音 + 儿。","(의미부) 「金」는 “쇠, 금속”을 뜻합니다.","(소리부) 音+儿는 여기서는 「境」(キョウ)가 축약된 것으로, 소리부의 역할만 하고 있습니다.","鏡는 “청동(金)으로 만든 거울” -> “거울”이라는 뜻의 글자입니다(境는 소리부)."],"sourceUrl":"https://nihongokanji.com/1537/"},"浪":{"id":1526,"char":"浪","hun":"물결 랑","meaning":"“물결 랑”. 유랑, 방랑, 낭비","on":"ロウ","kun":"","explanation":["浪 = 氵 + 良。","(의미부) 「氵」는 “물”을 뜻합니다.","(소리부 겸 의미부) 「良」(リョウ)는 “좋다”라는 뜻입니다.","浪는 “물결(氵)따라 흐르듯 떠도는 즐거운(良) 유랑 생활” -> “유랑, 방랑, 낭비”라는 뜻의 글자입니다.","(良는 소리부(リョウ -> ロウ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1538/"},"亜":{"id":1527,"char":"亜","hun":"버금 아","meaning":"“버금 아”. 버금, 아~(외국어의 음역에 쓰임; “아시아” 등)","on":"ア","kun":"","explanation":["亜는 본래 “고대의 중형 저택의 구조”를 본따 그린 글자입니다.","“(대형 저택보다는 작은) 중형 저택의 구조” -> “버금, 두 번째”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/1539/"},"覧":{"id":1528,"char":"覧","hun":"볼 람","meaning":"“볼 람”. 두루 보다, 둘러보다","on":"ラン","kun":"","explanation":["覧 = 臣 + 𠂉 + 一 + 見。","(소리부 겸 의미부) 위쪽의 臣+𠂉+一는 여기서는 「監」(カン)이 축약된 것으로, “감독하다”라는 뜻입니다.","(의미부) 「見」는 “보다”라는 뜻입니다.","覧는 “공사를 감독하며(監) 두루 둘러보다(見)” -> “두루 보다, 둘러보다”라는 뜻의 글자입니다.","(監는 소리부(カン -> ラン)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1540/"},"詐":{"id":1529,"char":"詐","hun":"속일 사","meaning":"“속일 사”. 사기, 거짓말, 속이다","on":"サ","kun":"","explanation":["詐 = 言 + 乍。","(의미부) 「言」는 “말하다”라는 뜻입니다.","(소리부 겸 의미부) 「乍」(サ)는 “바느질하다”라는 뜻입니다.","詐는 “거짓말(言)을 짜맞추다(乍)” -> “사기, 거짓말, 속이다”라는 뜻의 글자입니다.","(乍는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1541/"},"壇":{"id":1530,"char":"壇","hun":"단 단","meaning":"“단 단”. ~단(“화단”, “제단”, “단상” 등)","on":"ダン、タン","kun":"","explanation":["壇 = 土 + 亶。","「土」는 “흙, 땅”을 뜻합니다.","亶는 “고대에 제사를 지내던 제단의 모습”을 그린 모양자입니다.","(㐭는 제단 위의 위패, 旦는 그 아래의 제사상을 각각 표현한 것입니다.)","壇는 “흙(土)을 쌓아 만든 제단(亶)” -> “~단(화단, 제단, 단상 등)”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1542/"},"勲":{"id":1531,"char":"勲","hun":"공 훈","meaning":"“공 훈”. 공로, 공훈","on":"クン","kun":"","explanation":["勲 = 動 + 灬。","「動」는 “움직이다”라는 뜻입니다.","「灬」는 “불”을 뜻합니다.","勲는 “온 몸을 불사를 각오로(灬) 열심히 움직여(動) 일하다” -> “공훈, 공로”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1543/"},"魔":{"id":1532,"char":"魔","hun":"마귀 마","meaning":"“마귀 마”. 마술, 마귀, 마법 등","on":"マ","kun":"","explanation":["魔 = 麻 + 鬼。","(소리부 겸 의미부) 「麻」(マ)는 “삼베, 마, 마비”를 뜻합니다.","(의미부) 鬼(“귀신 귀”)는 “귀신”을 뜻하는 상용한자입니다.","魔는 “사람을 마비시키는(麻) 귀신(鬼)의 신비한 힘” -> “마술, 마법, 마귀”라는 뜻의 글자입니다.","(麻는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1544/"},"酬":{"id":1533,"char":"酬","hun":"갚을 수","meaning":"“갚을 수”. 갚다, 보답하다","on":"シュウ","kun":"","explanation":["酬 = 酉 + 州。","(의미부) 「酉」는 “술, 술병”을 뜻합니다.","(소리부) 「州」(シュウ)는 여기서는 소리부의 역할만 하고 있습니다.","酬는 “감사의 뜻으로 술(酉)을 대접하다” -> “갚다, 보답하다”라는 뜻의 글자입니다(州는 소리부)."],"sourceUrl":"https://nihongokanji.com/1545/"},"紫":{"id":1534,"char":"紫","hun":"자줏빛 자","meaning":"“자줏빛 자”. 보라색, 자주색","on":"シ","kun":"むらさき","explanation":["紫 = 止 + 匕 + 糸。","(소리부) 「止」(シ)는 여기서는 소리부의 역할만 하고 있습니다.","(의미부) 匕는 여기서는 단순한 장식으로 추가된 것입니다.","(의미부) 「糸」는 “실”을 뜻합니다.","紫는 “보라색으로 염색한 실(糸)” -> “보라색, 자주색”이라는 뜻의 글자입니다(止는 소리부)."],"sourceUrl":"https://nihongokanji.com/1546/"},"紋":{"id":1535,"char":"紋","hun":"무늬 문","meaning":"“무늬 문”. 무늬, 문장(집단을 상징하는 문양)","on":"モン","kun":"","explanation":["紋 = 糸 + 文。","(의미부) 「糸」는 “실”을 뜻합니다.","(소리부 겸 의미부) 「文」(モン)은 “글자, 문예”를 뜻합니다.","紋는 “실(糸)로 수놓은 자수 무늬(文)” -> “무늬, 문장(집단을 상징하는 문양)”이라는 뜻의 글자입니다.","(文는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1547/"},"卸":{"id":1536,"char":"卸","hun":"풀 사","meaning":"“풀 사”. 도매, 도매하다","on":"","kun":"おろ(す)、おろし","explanation":["卸 = 𦈢 + 卩。","卸는 본래 “왕의 발밑에 꿇어 엎드린 백성들”을 그린 글자입니다(903.「御」 모양 해설 참조).","“왕 앞에 무릎꿇고 진상품을 늘어놓다” -> “도매, 도매하다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/1548/"},"奮":{"id":1537,"char":"奮","hun":"떨칠 분","meaning":"“떨칠 분”. 분발하다, 기운내다","on":"フン","kun":"ふる(う)","explanation":["奮 = 大 + 隹 + 田。","「大」는 “크다”라는 뜻입니다.","「隹」는 “새”를 뜻합니다.","「田」는 “밭”을 뜻합니다.","奮는 “커다란(大) 새(隹)가 밭(田)에서 힘차게 날아오르다” -> “분발하다, 기운내다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1549/"},"欄":{"id":1538,"char":"欄","hun":"난간 난","meaning":"“난간 난”. 난간, ~란(글을 싣는 칸)","on":"ラン","kun":"","explanation":["欄 = 木 + 門 + 東。","「木」는 “나무”를 뜻합니다.","「門」는 “문”을 뜻합니다.","「東」는 “동쪽”을 뜻합니다.","欄는 “문(門) 동쪽(東)으로 나가지 못하도록 가로막은 나무(木)”라는 뜻입니다.","“따로 막아놓은 구역” -> “~란(글을 싣는 칸)”","“계단 옆으로 떨어지지 않도록 막아놓은 울타리” -> “난간”","이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/1550/"},"逸":{"id":1539,"char":"逸","hun":"달아날 일","meaning":"“달아날 일”. 벗어나다, 일탈, 뛰어나다","on":"イツ","kun":"","explanation":["逸 = ⻌ + 免。","「⻌」는 “길”을 뜻합니다.","「免」는 “면하다, 벗어나다”라는 뜻입니다.","逸는 “평범한 길(⻌)에서 벗어나다(免)” -> “벗어나다, 일탈, 뛰어나다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1551/"},"涯":{"id":1540,"char":"涯","hun":"물가 애","meaning":"“물가 애”. 물가, 가장자리, 끝, 한계","on":"ガイ","kun":"","explanation":["涯 = 氵 + 厂 + 圭。","「氵」는 “물”을 뜻합니다.","「厂」는 “절벽, 기슭”을 뜻합니다.","圭는 “흙더미(土+土)”라는 뜻입니다.","涯는 “흙(圭)으로 덮인 절벽(厂) 아래의 망망대해(氵)” -> “물가, 가장자리, 끝, 한계”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1552/"},"拓":{"id":1541,"char":"拓","hun":"넓힐 척/박을 탁","meaning":"“넓힐 척/박을 탁”. 넓히다, 본을 뜨다","on":"タク","kun":"","explanation":["拓 = 扌 + 石。","「扌」는 “손”을 뜻합니다.","「石」는 “돌”을 뜻합니다.","拓는,","“바위(石)를 뽑아내고(扌) 땅을 개간하다” -> “넓히다, 개척하다, 확장하다”","“돌(石)에 새겨진 글자를 종이에 떠내다(扌)” -> “본을 뜨다, 탁본”","이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1553/"},"眼":{"id":1542,"char":"眼","hun":"눈 안","meaning":"“눈 안”. 눈, 안구","on":"ガン、ゲン","kun":"まなこ","explanation":["眼 = 目 + 艮。","「目」는 “눈”을 뜻합니다.","「艮」는 “고개를 숙인 사람”을 뜻합니다.","眼는 “웅크린 사람(艮)의 뒷모습을 바라보는 눈(目)” -> “눈, 안구”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1554/"},"瓶":{"id":1543,"char":"瓶","hun":"병 병","meaning":"“병 병”. 병, 단지","on":"ビン","kun":"","explanation":["瓶 = 并 + 瓦。","并는 여기서는 “꽃이 든 꽃병”을 그린 모양자입니다.","瓦(“기와 와”)는 “기와, 기왓장”을 뜻하는 상용한자입니다.","瓶는 “기와(瓦)로 만든 꽃병(并)” -> “병, 단지”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1555/"},"獄":{"id":1544,"char":"獄","hun":"옥 옥","meaning":"“옥 옥”. 감옥","on":"ゴク","kun":"","explanation":["獄 = 犭 + 言 + 犬。","「犭」는 “개”를 뜻합니다.","「言」는 “말하다”라는 뜻입니다.","「犬」는 “개”를 뜻합니다.","獄는 “감옥을 지키는 파수견들(犭+犬) 사이에서 울부짖는(言) 죄수” -> “감옥”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1556/"},"尚":{"id":1545,"char":"尚","hun":"오히려 상","meaning":"“오히려 상”. 높다, 한층 더","on":"ショウ","kun":"","explanation":["尚 = 龸 + 口。","「龸」는 “궁궐”을 뜻합니다.","口는 여기서는 “출입구”를 그린 모양자입니다.","尚는 “궁궐(龸)의 출입구(口)” -> “높다, 한층 더”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1557/"},"彫":{"id":1546,"char":"彫","hun":"새길 조","meaning":"“새길 조”. 새기다","on":"チョウ","kun":"ほ(る)","explanation":["彫 = 周 + 彡。","「周」는 “주위, 주변”을 뜻합니다.","彡는 여기서는 “칼로 새겨놓은 빗금”을 그린 모양자입니다.","彫는 “갈림길 주변(周)에 빗금(彡)을 새겨 위치를 표시해두다” -> “새기다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1558/"},"穏":{"id":1547,"char":"穏","hun":"편안할 온","meaning":"“편안할 온”. 평온한, 온화한","on":"オン","kun":"おだ(やか)","explanation":["穏 = 禾 + ⺤ + ⺕ + 心。","「禾」는 “곡식”을 뜻합니다.","「⺤」는 “손”을 뜻합니다.","「⺕」는 “손”을 뜻합니다.","「心」는 “마음”을 뜻합니다.","穏는 “배고픈 사람의 손(⺤)에 곡식(禾)을 건네주는(⺕) 따뜻한 마음(心)” -> “평온한, 온화한”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1559/"},"顕":{"id":1548,"char":"顕","hun":"나타날 현","meaning":"“나타날 현”. 눈에 띄는, 분명한","on":"ケン","kun":"","explanation":["顕 = 日 + 业 + 頁。","「日」는 “태양”을 뜻합니다.","业는 여기서는 “들판에 자라난 초목”을 그린 모양자입니다.","「頁」는 “머리”를 뜻합니다.","顕는 “햇빛(日)을 받아 밝게 빛나는 초목(业)을 바라보다(頁)”라는 뜻입니다.","“햇빛이 밝아 풍경이 잘 보이다” -> “눈에 띄는, 분명한”이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/1560/"},"巧":{"id":1549,"char":"巧","hun":"공교할 교","meaning":"“공교할 교”. 교묘한, 솜씨 좋은","on":"コウ","kun":"たく(み)","explanation":["巧 = 工 + 丂。","(소리부 겸 의미부) 「工」(コウ)는 “공작, 가공, 공정”을 뜻합니다.","(의미부) 丂는 여기서는 “구부러진 물건”을 그린 모양자로, “정밀하게 가공된 물품”이라는 뜻입니다.","巧는 “정밀한(丂) 가공(工)” -> “교묘한, 솜씨 좋은”이라는 뜻의 글자입니다.","(工는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1561/"},"矛":{"id":1550,"char":"矛","hun":"창 모","meaning":"“창 모”. 창","on":"ム","kun":"ほこ","explanation":["矛는 “날이 세 개인 창”을 그린 상형문자입니다."],"sourceUrl":"https://nihongokanji.com/1562/"},"垣":{"id":1551,"char":"垣","hun":"담 원","meaning":"“담 원”. 울타리, 담","on":"","kun":"かき","explanation":["垣 = 土 + 亘。","「土」는 “흙”을 뜻합니다.","亘는 여기서는 “담벼락”을 그린 모양자입니다.","垣는 “흙(土)으로 쌓은 담벼락(亘)” -> “울타리, 담”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1563/"},"欺":{"id":1552,"char":"欺","hun":"속일 기","meaning":"“속일 기”. 속이다, 기만하다","on":"ギ","kun":"あざむ(く)","explanation":["欺 = 其 + 欠。","(소리부) 「其」(キ)는 여기서는 소리부(キ -> ギ)의 역할만 하고 있습니다.","(의미부) 「欠」는 “입을 벌린 사람, 입으로 하는 동작”을 뜻합니다.","欺는 “그럴듯한 말을 떠벌리며(欠) 상대방을 속여넘기다” -> “속이다, 기만하다”라는 뜻의 글자입니다(其는 소리부)."],"sourceUrl":"https://nihongokanji.com/1564/"},"釣":{"id":1553,"char":"釣","hun":"낚을 조","meaning":"“낚을 조”. 낚시하다","on":"チョウ","kun":"つ(る)","explanation":["釣 = 金 + 勺。","「金」는 “쇠, 금속”을 뜻합니다.","勺는 여기서는 “낚싯대와 낚싯줄, 미끼”를 그린 모양자입니다.","釣는 “쇠(金)로 만든 낚싯대(勺)” -> “낚시하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1565/"},"缶":{"id":1554,"char":"缶","hun":"깡통, 캔, 양철통","meaning":"깡통, 캔, 양철통","on":"カン","kun":"","explanation":["缶는 “술을 담아놓은 술통”을 그린 상형문자입니다.","“술통” -> “깡통, 캔, 양철통”이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/1566/"},"粧":{"id":1555,"char":"粧","hun":"단장할 장","meaning":"“단장할 장”. 화장하다, 꾸미다, 단장하다","on":"ショウ","kun":"","explanation":["粧 = 米 + 广 + 土。","「米」는 “쌀”을 뜻합니다. 여기서는 “분가루”를 쌀에 비유한 것입니다.","「广」는 “집, 건물”을 뜻합니다.","「土」는 “흙”을 뜻합니다. 여기서는 “연지”를 흙에 비유한 것입니다.","粧는 “집(广)에서 연지(土)와 분(米)을 바르다” -> “화장하다, 꾸미다, 단장하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1567/"},"隻":{"id":1556,"char":"隻","hun":"외짝 척","meaning":"“외짝 척”. 외짝의, 하나의, ~척(배를 세는 단위)","on":"セキ","kun":"","explanation":["隻 = 隹 + 又。","「隹」는 “새”를 뜻합니다.","「又」는 “손”을 뜻합니다.","隻는 “새(隹) 한 마리를 잡다(又)” -> “외짝의, 하나의”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1568/"},"粛":{"id":1557,"char":"粛","hun":"엄숙할 숙","meaning":"“엄숙할 숙”. 엄숙한, 조용한, 정중한","on":"シュク","kun":"","explanation":["粛 = ⺕ + 丨 + 米 + 丿丨。","「⺕」는 “손”을 뜻합니다.","丨+米는 여기서는 “낚싯대(丨)와 낚싯바늘(米)”을 그린 모양자입니다.","丿丨는 여기서는 “호수”를 그린 모양자입니다.","粛는 “호수(丿丨)에 낚싯대(丨+米)를 드리우고(⺕) 조용히 낚시하다” -> “엄숙한, 조용한, 정중한”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1569/"},"愚":{"id":1558,"char":"愚","hun":"어리석을 우","meaning":"“어리석을 우”. 어리석은, 미련한","on":"グ","kun":"おろ(か)","explanation":["愚 = 禺 + 心。","(소리부 겸 의미부) 「禺」(グウ)는 “원숭이”를 뜻합니다.","(의미부) 「心」는 “마음”을 뜻합니다.","愚는 “원숭이(禺)처럼 멍청하다(心)” -> “어리석다, 미련하다”라는 뜻의 글자입니다.","(禺는 소리부(グウ -> グ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1570/"},"遭":{"id":1559,"char":"遭","hun":"만날 조","meaning":"“만날 조”. 만나다, 조우하다","on":"ソウ","kun":"あ(う)","explanation":["遭 = ⻌ + 曹。","(의미부) 「⻌」는 “길”을 뜻합니다.","(소리부 겸 의미부) 曹(ソウ – “무리 조”)는 “무리”를 뜻하는 상용한자입니다.","遭는 “길(⻌)에서 한 무리(曹)의 사람들과 마주치다” -> “만나다, 조우하다”라는 뜻의 글자입니다.","(曹는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1571/"},"架":{"id":1560,"char":"架","hun":"시렁 가","meaning":"“시렁 가”. 가설하다, 걸쳐 놓다","on":"カ","kun":"か(ける)、か(かる)","explanation":["架 = 加 + 木。","(소리부 겸 의미부) 「加」(カ)는 “더하다”라는 뜻입니다.","(의미부) 「木」는 “나무”를 뜻합니다.","架는 “강에 나무 다리(木)를 걸어놓다(加)” -> “가설하다, 걸쳐 놓다”라는 뜻의 글자입니다.","(加는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1572/"},"鬼":{"id":1561,"char":"鬼","hun":"귀신 귀","meaning":"“귀신 귀”. 귀신","on":"キ","kun":"おに","explanation":["鬼는 “가면(田)을 쓴 채 무릎꿇고(厶) 제사를 지내는 사람”을 그린 상형문자입니다.","“제사” -> “귀신”이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/1573/"},"庶":{"id":1562,"char":"庶","hun":"여러 서","meaning":"“여러 서”. 서민, 대중, 여럿/전부","on":"ショ","kun":"","explanation":["庶 = 广 + 廿 + 灬。","「广」는 “집, 건물”을 뜻합니다.","廿는 여기서는 “냄비”를 그린 모양자입니다.","「灬」는 “불”을 뜻합니다.","庶는 “집(广) 에서 냄비(廿)를 끓여(灬) 요리를 하는 서민” -> “서민, 대중” -> “여럿, 전부”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1574/"},"稚":{"id":1563,"char":"稚","hun":"어릴 치","meaning":"“어릴 치”. 어리다","on":"チ","kun":"","explanation":["稚 = 禾 + 隹。","「禾」는 “곡식”을 뜻합니다.","「隹」는 “새”를 뜻합니다.","稚는 “곡식(禾)을 쪼아먹는 참새(隹)” -> “작다, 어리다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1575/"},"滋":{"id":1564,"char":"滋","hun":"불을 자","meaning":"“불을 자”. 영양, 자라다, 늘다","on":"ジ","kun":"","explanation":["滋 = 氵 + 兹。","(의미부) 「氵」는 “물”을 뜻합니다.","(소리부 겸 의미부) 「兹」(ジ)는 “무성한 덩굴”을 그린 글자입니다(링크 참조).","滋는 “덩굴(兹)에 물(氵)을 주다” -> “영양, 자라다, 늘다”라는 뜻의 글자입니다.","(兹는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1576/"},"幻":{"id":1565,"char":"幻","hun":"헛보일 환","meaning":"“헛보일 환”. 환영, 환상, 허깨비","on":"ゲン","kun":"まぼろし","explanation":["幻 = 幺 + 𠃌。","「幺」는 “짧은 실”을 뜻합니다.","𠃌는 여기서는 “(실이) 나풀거리는 모습”을 그린 모양자입니다.","幻는 “허공에서 나풀거리는(𠃌) 짧은 실(幺)” -> “아지랑이, 신기루” -> “환영, 환상, 허깨비”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1577/"},"煮":{"id":1566,"char":"煮","hun":"삶을 자","meaning":"“삶을 자”. 끓이다, 삶다","on":"シャ","kun":"に(る)、に(える)、に(やす)","explanation":["煮 = 者 + 灬。","(소리부 겸 의미부) 「者」(シャ)는 “사람”을 뜻합니다.","(의미부) 「灬」는 “불”을 뜻합니다.","煮는 “죄인(者)을 솥에 넣고 삶아(灬) 죽이다” -> “끓이다, 삶다”라는 뜻의 글자입니다.","(者는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1578/"},"姫":{"id":1567,"char":"姫","hun":"아가씨 희","meaning":"“아가씨 희”. 후궁, 아가씨, 공주","on":"","kun":"ひめ","explanation":["姫 = 女 + 臣。","「女」는 “여자”를 뜻합니다.","「臣」는 “신하”를 뜻합니다.","姫는 “시중드는 사람(臣)이 있는 여자(女)” -> “후궁, 아가씨, 공주”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1579/"},"誓":{"id":1568,"char":"誓","hun":"맹세할 서","meaning":"“맹세할 서”. 맹세하다, 서약하다","on":"セイ","kun":"ちか(う)","explanation":["誓 = 扌 + 斤 + 言。","「扌」는 “손”을 뜻합니다.","「斤」는 “도끼”를 뜻합니다.","「言」는 “말하다”라는 뜻입니다.","誓는 “도끼(斤)를 손(扌)에 들고 충성을 맹세하다(言)” -> “맹세하다, 서약하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1580/"},"把":{"id":1569,"char":"把","hun":"잡을 파","meaning":"“잡을 파”. 쥐다, 잡다","on":"ハ","kun":"","explanation":["把 = 扌 + 巴。","「扌」는 “손”을 뜻합니다.","「巴」는 “꼬리”를 뜻합니다.","把는 “동물의 꼬리(巴)를 잡다(扌)” -> “쥐다, 잡다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1581/"},"践":{"id":1570,"char":"践","hun":"밟을 천","meaning":"“밟을 천”. 짓밟다, 실천하다","on":"セン","kun":"","explanation":["践 = 足 + 㦮。","(의미부) 「足」는 “발”을 뜻합니다.","(소리부 겸 의미부) 「㦮」(セン)은 “피와 살점이 묻은 창”을 뜻합니다.","践는 “적을 정벌하고(㦮) 짓밟다(足)” -> “짓밟다” -> “실천하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1582/"},"呈":{"id":1571,"char":"呈","hun":"드릴 정","meaning":"“드릴 정”. 바치다, 드러내다","on":"テイ","kun":"","explanation":["呈 = 口 + 王。","「王」는 “왕”을 뜻합니다.","口는 여기서는 “왕에게 바칠 진상품”을 그린 모양자입니다.","呈는 “왕(王)에게 바칠 진상품(口)을 왕 앞에 드러내다” -> “바치다, 드러내다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1583/"},"疎":{"id":1572,"char":"疎","hun":"성길 소","meaning":"“성길 소”. 소원하다, 멀리하다","on":"ソ","kun":"うと(い)、うと(む)","explanation":["疎 = 𤴔 + 束。","𤴔는 여기서는 「止」가 변형된 것으로, “발”을 뜻합니다.","「束」는 “묶다”라는 뜻입니다.","疎는 “발(𤴔)이 묶여(束) 사람들을 만나러 다닐 수 없다” -> “소원하다, 멀리하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1584/"},"仰":{"id":1573,"char":"仰","hun":"우러를 앙","meaning":"“우러를 앙”. 우러러보다","on":"ギョウ、コウ","kun":"あお(ぐ)、おお(せ)","explanation":["仰 = 亻 + 卬。","「亻」는 “사람”을 뜻합니다.","「卬」는 “우러러보다”라는 뜻입니다.","仰는 “위대한 사람(亻)을 우러러보다(卬)” -> “우러러보다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1585/"},"剛":{"id":1574,"char":"剛","hun":"굳셀 강","meaning":"“굳셀 강”. 굳센","on":"ゴウ","kun":"","explanation":["剛 = 岡 + 刂。","(소리부 겸 의미부) 「岡」(コウ)는 “강하다”라는 뜻입니다.","(의미부) 「刂」는 “칼”을 뜻합니다.","剛는 “강한(岡) 재질로 만들어진 칼(刂)” -> “굳세다”라는 뜻의 글자입니다.","(岡는 소리부(コウ -> ゴウ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1586/"},"疾":{"id":1575,"char":"疾","hun":"병 질","meaning":"“병 질”. 질병, 빠르다","on":"シツ","kun":"","explanation":["疾 = 疒 + 矢。","「疒」는 “질병, 질환”을 뜻합니다.","「矢」는 “화살”을 뜻합니다.","疾는 “쏜살같이 날아온 화살(矢)에 맞아 다치다(疒)” -> “질병, 빠르다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1587/"},"征":{"id":1576,"char":"征","hun":"칠 정","meaning":"“칠 정”. 정벌하다, 토벌하다","on":"セイ","kun":"","explanation":["征 = 彳 + 正。","(의미부) 「彳」는 “길”을 뜻합니다.","(소리부 겸 의미부) 「正」(セイ)는 본래 “적의 성문을 향해 진격하는 발”을 그린 글자입니다(링크 참조).","征는 “적을 토벌하러(正) 길을 떠나다(彳)” -> “정벌하다, 토벌하다”라는 뜻의 글자입니다.","(正는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1588/"},"砕":{"id":1577,"char":"砕","hun":"부술 쇄","meaning":"“부술 쇄”. 부서지다, 부수다","on":"サイ","kun":"くだ(く)、くだ(ける)","explanation":["砕 = 石 + 卆。","「石」는 “돌”을 뜻합니다.","卆는 단순히 「九」와 「十」을 합쳐놓은 글자로, “9(九) + 10(十)” -> “여러 개, 많다”라는 뜻입니다.","砕는 “돌(石)을 수십 조각(卆)으로 분쇄하다” -> “부수다, 부서지다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1589/"},"謡":{"id":1578,"char":"謡","hun":"노래 요","meaning":"“노래 요”. 노래","on":"ヨウ","kun":"うた(い)、うた(う)","explanation":["謡 = 言 + ⺤ + 𠙻。","(의미부) 「言」는 “말하다”라는 뜻입니다.","(소리부 겸 의미부) 오른쪽의 ⺤+𠙻는 여기서는 「揺」(ヨウ)가 축약된 것으로, “흔들리다, 떨리다”라는 뜻입니다.","謡는 “떨리는(揺) 목소리로 노래하다(言)” -> “노래하다”라는 뜻의 글자입니다.","(揺는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1590/"},"嫁":{"id":1579,"char":"嫁","hun":"시집갈 가","meaning":"“시집갈 가”. 시집가다","on":"カ","kun":"よめ、とつ(ぐ)","explanation":["嫁 = 女 + 家。","(의미부) 「女」는 “여자”를 뜻합니다.","(소리부 겸 의미부) 「家」(カ)는 “집”을 뜻합니다.","嫁는 “여자(女)가 남편의 집안(家)으로 시집가다” -> “시집가다”라는 뜻의 글자입니다.","(家는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1591/"},"謙":{"id":1580,"char":"謙","hun":"겸손할 겸","meaning":"“겸손할 겸”. 겸손하다","on":"ケン","kun":"","explanation":["謙 = 言 + 兼。","(의미부) 「言」는 “말하다”라는 뜻입니다.","(소리부 겸 의미부) 「兼」(ケン)은 “겸하다”라는 뜻의 상용한자입니다.","謙는 “공손함과 예의를 함께(兼) 갖추어 말하다(言)” -> “겸손하다”라는 뜻의 글자입니다.","(兼는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1592/"},"后":{"id":1581,"char":"后","hun":"뒤 후","meaning":"“뒤 후”. 왕비, 황후, 뒤","on":"コウ","kun":"","explanation":["后는 “땅바닥에 끌리는 긴 옷(𠂆)을 입고 걷는 황후”를 그린 상형문자입니다."],"sourceUrl":"https://nihongokanji.com/1593/"},"嘆":{"id":1582,"char":"嘆","hun":"탄식할 탄","meaning":"“탄식할 탄”. 한탄하다, 탄식하다","on":"タン","kun":"なげ(く)、なげ(かわしい)","explanation":["嘆 = 口 + 𦰩。","「口」는 “입”을 뜻합니다.","𦰩는 여기서는 「漢」가 생략된 것으로, “한나라”를 뜻합니다.","嘆는 “한나라(漢)의 패망을 한탄하다(口)” -> “한탄하다, 탄식하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1594/"},"菌":{"id":1583,"char":"菌","hun":"버섯 균","meaning":"“버섯 균”. 균, 세균, 곰팡이 등","on":"キン","kun":"","explanation":["菌 = 艹 + 囗 + 禾。","「艹」는 “풀”을 뜻합니다.","囗는 여기서는 “창고”를 그린 모양자입니다.","「禾」는 “곡식”을 뜻합니다.","菌는 “창고(囗) 안의 곡식(禾)에 핀 곰팡이(艹)” -> “세균, 균”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1595/"},"鎌":{"id":1584,"char":"鎌","hun":"낫 겸","meaning":"“낫 겸”. 낫","on":"","kun":"かま","explanation":["鎌 = 金 + 兼。","「金」는 “쇠, 금속”을 뜻합니다.","「兼」는 본래 “손에 볏단을 쥔 모습”을 그린 글자입니다(링크 참조).","鎌는 “금속 낫(金)으로 짚단(兼)을 베다” -> “낫”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1596/"},"巣":{"id":1585,"char":"巣","hun":"새집 소","meaning":"“새집 소”. 둥지, 보금자리, 소굴","on":"ソウ","kun":"す","explanation":["巣 = ⺍ + 田 + 木。","「木」는 “나무”를 뜻합니다.","⺍+田는 여기서는 “(나무 위의) 새 둥지”를 그린 모양자입니다.","巣는 “나무(木) 위의 새 둥지(⺍+田)” -> “둥지, 보금자리, 소굴”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1597/"},"頻":{"id":1586,"char":"頻","hun":"자주 빈","meaning":"“자주 빈”. 자주, 빈번한","on":"ヒン","kun":"","explanation":["頻 = 歩 + 頁。","「歩」는 “걷다”라는 뜻입니다.","「頁」는 “얼굴”을 뜻합니다.","頻는 “자주 찾아와(歩) 얼굴(頁)을 비추다” -> “자주, 빈번한”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1598/"},"琴":{"id":1587,"char":"琴","hun":"거문고 금","meaning":"“거문고 금”. 거문고, 현악기","on":"キン","kun":"こと","explanation":["琴 = 玨 + 今。","(의미부) 玨는 여기서는 “거문고의 줄”을 그린 모양자입니다.","(소리부) 「今」(キン)은 여기서는 소리부의 역할만 하고 있습니다.","琴는 “거문고 줄(玨)” -> “거문고”라는 뜻의 글자입니다(今는 소리부)."],"sourceUrl":"https://nihongokanji.com/1599/"},"班":{"id":1588,"char":"班","hun":"나눌 반","meaning":"“나눌 반”. 반, 조, 그룹, 나누다","on":"ハン","kun":"","explanation":["班 = 𤣩 + 刂 + 𤣩。","「𤣩」는 “옥, 구슬”을 뜻합니다.","「刂」는 “칼”을 뜻합니다.","班는 “칼(刂)로 옥(𤣩𤣩)을 반으로 가르다” -> “나누다” -> “반, 조, 그룹”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1600/"},"棚":{"id":1589,"char":"棚","hun":"사다리 붕","meaning":"“사다리 붕”. 선반","on":"","kun":"たな","explanation":["棚 = 木 + 朋。","「木」는 “나무”를 뜻합니다.","朋는 여기서는 “선반”의 모습을 그린 모양자입니다.","棚는 “나무(木)로 만든 선반(朋)” -> “선반”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1601/"},"潔":{"id":1590,"char":"潔","hun":"깨끗할 결","meaning":"“깨끗할 결”. 깨끗한, 순결한","on":"ケツ","kun":"いさぎよ(い)","explanation":["潔 = 氵 + 絜。","「氵」는 “물”을 뜻합니다.","龶는 여기서는 “꿰맨 자국”을 그린 모양자입니다.","「刀」는 “칼”을 뜻합니다.","「糸」는 “실”을 뜻합니다.","潔는 “베여서(刀)난 상처를 실(糸)로 꿰매고(龶) 깨끗이 소독하다(氵)” -> “깨끗한, 순결한”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1602/"},"酷":{"id":1591,"char":"酷","hun":"심할 혹","meaning":"“심할 혹”. 가혹한, 심한","on":"コク","kun":"","explanation":["酷 = 酉 + 告。","(의미부) 「酉」는 “술”을 뜻합니다.","(소리부 겸 의미부) 「告」(コク)는 “고하다, 알리다”라는 뜻입니다.","酷는 “술김에(酉) 내뱉은(告) 잔혹한 말” -> “가혹한, 심한”이라는 뜻의 글자입니다.","(告는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1603/"},"宰":{"id":1592,"char":"宰","hun":"재상 재","meaning":"“재상 재”. 주관하다, 재상","on":"サイ","kun":"","explanation":["宰 = 宀 + 辛。","「宀」는 “집”을 뜻합니다.","「辛」는 “문신을 새기는 고문 도구”를 뜻합니다.","宰는 “관청(宀)에서 형벌(辛)을 내리는 고급 관료” -> “주관하다, 재상”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1604/"},"廊":{"id":1593,"char":"廊","hun":"사랑채/행랑 랑","meaning":"“사랑채/행랑 랑”. 회랑, 복도","on":"ロウ","kun":"","explanation":["廊 = 广 + 郎。","(의미부) 「广」는 “집, 건물”을 뜻합니다.","(소리부 겸 의미부) 「郎」(ロウ)는 “신랑, 젊은 남성”을 뜻합니다.","廊는 “집(广)에서 집주인(郎)만 지나다닐 수 있는 전용 회랑” -> “회랑, 복도”라는 뜻의 글자입니다.","(郎는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1605/"},"寂":{"id":1594,"char":"寂","hun":"고요할 적","meaning":"“고요할 적”. 적막한, 쓸쓸한, 고요한","on":"ジャク、セキ","kun":"さび、さび(しい)、さび(れる)","explanation":["寂 = 宀 + 叔。","「宀」는 “집”을 뜻합니다.","「尗」는 “식물의 줄기와 뿌리”를 그린 글자입니다.","「又」는 “손”을 뜻합니다.","寂는 “집(宀)에 홀로 남아 쓸쓸히 화초(尗)만 어루만지다(又)“ -> “적막한, 쓸쓸한, 고요한”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1606/"},"伏":{"id":1595,"char":"伏","hun":"엎드릴 복/안을 부","meaning":"“엎드릴 복/안을 부”. 엎드리다, 복종하다","on":"フク","kun":"ふ(せる)、ふ(す)","explanation":["伏 = 亻 + 犬。","「亻」는 “사람”을 뜻합니다.","「犬」는 “개”를 뜻합니다.","伏는 “사람(亻)앞에 엎드린 개(犬)” -> “엎드리다, 복종하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1607/"},"碁":{"id":1596,"char":"碁","hun":"바둑 기","meaning":"“바둑 기”. 바둑","on":"ゴ","kun":"","explanation":["碁 = 其 + 石。","(소리부) 「其」(キ)는 여기서는 소리부(キ -> ゴ)의 역할만 하고 있습니다.","(의미부) 「石」는 “돌”을 뜻합니다.","碁는 “바둑돌(石)” -> “바둑”이라는 뜻의 글자입니다(其는 소리부).","참고)","“장기”를 뜻하는 1395.「棋」와 함께 공부하시면 더 쉽게 기억하실 수 있습니다."],"sourceUrl":"https://nihongokanji.com/1608/"},"俗":{"id":1597,"char":"俗","hun":"풍속 속","meaning":"“풍속 속”. 풍속, 세속, 평범한","on":"ゾク","kun":"","explanation":["俗 = 亻 + 谷。","(의미부) 「亻」는 “사람”을 뜻합니다.","(소리부 겸 의미부) 「谷」(コク)는 “계곡”을 뜻합니다.","俗는 “계곡(谷)에서 몸을 씻는 서민(亻)” -> “평범한, 세속적인, 풍속”이라는 뜻의 글자입니다.","(谷는 소리부(コク -> ゾク)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1609/"},"漠":{"id":1598,"char":"漠","hun":"넓을 막","meaning":"“넓을 막”. 사막, 끝이 없는, 막연한","on":"バク","kun":"","explanation":["漠 = 氵 + 莫。","(의미부) 「氵」는 “물”을 뜻합니다.","(소리부 겸 의미부) 「莫」(バク)는 “없다”라는 뜻입니다.","漠는 “물(氵)이 없는(莫) 곳” -> “사막” -> “끝이 없는, 막연한”이라는 뜻의 글자입니다.","(莫는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1610/"},"邪":{"id":1599,"char":"邪","hun":"간사할 사","meaning":"“간사할 사”. 간사한, 사악한","on":"ジャ","kun":"","explanation":["邪 = 牙 + ⻏。","牙(“어금니 아”)는 “이, 어금니”를 뜻하는 상용한자입니다.","「⻏」는 “도시”를 뜻합니다.","邪는 “도시(⻏)에 침입해 사람을 물어죽이는(牙) 맹수” -> “사악한, 간사한”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1611/"},"晶":{"id":1600,"char":"晶","hun":"맑을 정","meaning":"“맑을 정”. 수정","on":"ショウ","kun":"","explanation":["晶 = 日 + 日 + 日。","「日」는 “태양”을 뜻합니다.","晶는 “반짝반짝 빛나는(日日日) 보석” -> “수정”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1612/"},"墨":{"id":1601,"char":"墨","hun":"먹 묵","meaning":"“먹 묵”. 먹","on":"ボク","kun":"すみ","explanation":["墨 = 黒 + 土。","「黒」는 “검정”을 뜻합니다.","「土」는 “흙”을 뜻합니다.","墨는 “검정색(黒) 진흙(土)” -> “먹”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1613/"},"鎮":{"id":1602,"char":"鎮","hun":"진압할 진","meaning":"“진압할 진”. 진압하다, 진정시키다","on":"チン","kun":"しず(める)、しず(まる)","explanation":["鎮 = 金 + 真。","(의미부) 「金」는 “쇠, 금속”을 뜻합니다.","(소리부 겸 의미부) 「真」(シン)은 “진실, 진심”을 뜻합니다.","鎮는 “무거운 쇳덩이(金)로 진심(真)을 담아 내리치다” -> “진압하다, 진정시키다”라는 뜻의 글자입니다.","(真는 소리부(シン -> チン)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1614/"},"洞":{"id":1603,"char":"洞","hun":"골 동/밝을 통","meaning":"“골 동/밝을 통”. 동굴, 구멍, 꿰뚫어 보다","on":"ドウ","kun":"ほら","explanation":["洞 = 氵 + 同。","(의미부) 「氵」는 “물”을 뜻합니다.","(소리부 겸 의미부) 「同」(ドウ)는 여기서는 “동굴의 입구”를 그린 모양자입니다.","洞는 “지하수(氵)가 흐르는 동굴(同)” -> “동굴, 구멍, 꿰뚫어 보다”라는 뜻의 글자입니다.","(同는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1615/"},"履":{"id":1604,"char":"履","hun":"밟을 리","meaning":"“밟을 리”. 발로 밟다, 행하다","on":"リ","kun":"は(く)","explanation":["履 = 尸 + 復。","「尸」는 “앉다”라는 뜻입니다.","「復」는 “되돌아가다, 회복하다”라는 뜻입니다.","履는 “앉았던 자리(尸)로 되돌아가다(復)”라는 뜻입니다.","“지나온 길을 되밟아가다” -> “발로 밟다, 행하다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/1616/"},"劣":{"id":1605,"char":"劣","hun":"못할 렬","meaning":"“못할 렬”. 못하다, 열등하다","on":"レツ","kun":"おと(る)","explanation":["劣 = 少 + 力。","「少」는 “적다”라는 뜻입니다.","「力」는 “힘”을 뜻합니다.","劣는 “힘(力)이 적다(少)” -> “못하다, 열등하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1617/"},"那":{"id":1606,"char":"那","hun":"어찌 나","meaning":"“어찌 나”. 어째서, 찰나의","on":"ナ","kun":"","explanation":["那는 본래 “서역인”을 뜻하던 글자로, 서양인들의 수염과 머리칼을 그린 상형문자입니다.","그러나 지금은 본래의 뜻과는 아무 상관 없이 잡다한 의미로 사용되는 글자입니다.","즉, 那의 모양과 의미 사이에는 아무런 관계도 없습니다."],"sourceUrl":"https://nihongokanji.com/1618/"},"殴":{"id":1607,"char":"殴","hun":"때릴 구","meaning":"“때릴 구”. 때리다, 두드리다","on":"オウ","kun":"なぐ(る)","explanation":["殴 = 区 + 殳。","区는 여기서는 “맞아서 생긴 흉터”를 그린 모양자입니다.","「殳」는 “때리다, 치다”라는 뜻입니다.","殴는 “흉터(区)가 남도록 때리다(殳)” -> “때리다, 두드리다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1619/"},"娠":{"id":1608,"char":"娠","hun":"아이 밸 신","meaning":"“아이 밸 신”. 잉태하다, 임신하다","on":"シン","kun":"","explanation":["娠 = 女 + 辰。","(의미부) 「女」는 “여자”를 뜻합니다.","(소리부 겸 의미부) 「辰」(シン)은 “쟁기, 농기구”를 뜻합니다.","娠는 “여자(女)의 자궁에 아기씨를 심어(辰) 임신시키다” -> “잉태하다, 임신하다”라는 뜻의 글자입니다.","(辰는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1620/"},"奉":{"id":1609,"char":"奉","hun":"받들 봉","meaning":"“받들 봉”. 받들다, 섬기다","on":"ホウ、ブ","kun":"たてまつ(る)","explanation":["奉는 “약초를 두 손으로 받들고 있는 모습”을 그린 상형문자입니다.","“약초를 두 손으로 받들어 바치다” -> “받들다, 섬기다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/1621/"},"憂":{"id":1610,"char":"憂","hun":"근심 우","meaning":"“근심 우”. 걱정, 근심","on":"ユウ","kun":"うれ(える)、うれ(い)、う(い)","explanation":["憂 = 頁 + 冖 + 心 + 夂。","「頁」는 “머리”를 뜻합니다.","「心」는 “마음”을 뜻합니다.","冖는 여기서는 “마음(心)을 짓누르는 모습”을 표현한 모양자입니다.","「夂」는 “발”을 뜻합니다.","憂는 “머릿속(頁)의 걱정이 마음(心)을 짓눌러(冖) 발걸음(夂)이 무거운 사람” -> “걱정, 근심”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1622/"},"朴":{"id":1611,"char":"朴","hun":"순박할 박","meaning":"“순박할 박”. 꾸밈없는, 순박한","on":"ボク","kun":"","explanation":["朴 = 木 + 卜。","「木」는 “나무”를 뜻합니다.","「卜」는 “점괘”를 뜻합니다.","朴는 “나뭇가지(木)로 만든 싸구려 점술 도구(卜)” -> “소박하다, 순박하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1623/"},"亭":{"id":1612,"char":"亭","hun":"정자 정","meaning":"“정자 정”. 정자, 건물","on":"テイ","kun":"","explanation":["亭는 “작은 정자”를 그린 상형문자입니다."],"sourceUrl":"https://nihongokanji.com/1624/"},"怪":{"id":1613,"char":"怪","hun":"괴이할 괴","meaning":"“괴이할 괴”. 괴상한, 이상한, 진기한","on":"カイ","kun":"あや(しい)、あや(しむ)","explanation":["怪 = 忄 + 圣。","(의미부) 「忄」는 “마음”을 뜻합니다.","(소리부 겸 의미부) 「圣」(ケイ)는 “지나가다”라는 뜻입니다.","怪는 “섬뜩한 느낌이 마음속(忄)을 스쳐 지나가다(圣)” -> “괴이하다, 괴상하다”라는 뜻의 글자입니다.","(圣는 소리부(ケイ -> カイ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1625/"},"酔":{"id":1614,"char":"酔","hun":"취할 취","meaning":"“취할 취”. (술에) 취하다, 심취하다","on":"スイ","kun":"よ(う)","explanation":["酔 = 酉 + 卆。","「酉」는 “술”을 뜻합니다.","卆는 단순히 「九」와 「十」을 합쳐놓은 글자로, “9(九) + 10(十)” -> “여러 개, 많다”라는 뜻입니다.","酔는 “술(酉)을 너무 많이(卆) 마셔 취하다” -> “취하다, 심취하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1626/"},"惜":{"id":1615,"char":"惜","hun":"아낄 석","meaning":"“아낄 석”. 아쉬워하다, 아깝다","on":"セキ","kun":"お(しい)、お(しむ)","explanation":["惜 = 忄 + 昔。","(의미부) 「忄」는 “마음”을 뜻합니다.","(소리부 겸 의미부) 「昔」(セキ)는 “옛날”을 뜻합니다.","惜는 “지나간 일(昔)을 아쉬워하다(忄)” -> “아쉬워하다, 아깝다”라는 뜻의 글자입니다.","(昔는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1627/"},"穫":{"id":1616,"char":"穫","hun":"거둘 확","meaning":"“거둘 확”. 수확하다","on":"カク","kun":"","explanation":["穫 = 禾 + 蒦。","(의미부) 「禾」는 “곡식”을 뜻합니다.","(소리부 겸 의미부) 蒦는 여기서는 「獲」(カク)가 축약된 것으로, “얻다, 획득하다”라는 뜻입니다.","穫는 “곡식(禾)을 획득하다(獲)” -> “수확하다”라는 뜻의 글자입니다.","(蒦->獲는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1628/"},"佳":{"id":1617,"char":"佳","hun":"아름다울 가","meaning":"“아름다울 가”. 아름답다","on":"カ","kun":"","explanation":["佳 = 亻 + 圭。","「亻」는 “사람”을 뜻합니다.","圭는 “흙더미(土+土)”라는 뜻입니다.","佳는 “흙으로 빚은(圭) 예쁜 인형(亻)” -> “아름답다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1629/"},"潤":{"id":1618,"char":"潤","hun":"불을 윤","meaning":"“불을 윤”. 물기가 있는, 윤기있는","on":"ジュン","kun":"うるお(う)、うるお(す)、うる(む)","explanation":["潤 = 氵 + 門 + 王。","「氵」는 “물”을 뜻합니다.","「門」는 “문”을 뜻합니다.","「王」는 “왕”을 뜻합니다.","潤는 “가뭄이 들어 사당(門)에서 비(氵)를 기원하는 기우제를 지내는 왕(王)”이라는 뜻입니다.","“기우제” -> “비가 내리다” -> “물기가 있는, 윤기있는”이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/1630/"},"悼":{"id":1619,"char":"悼","hun":"슬퍼할 도","meaning":"“슬퍼할 도”. 애도하다","on":"トウ","kun":"いた(む)","explanation":["悼 = 忄 + 卓。","「忄」는 “마음”을 뜻합니다.","「卓」는 “높다, 뛰어나다”라는 뜻입니다.","悼는 “뛰어난(卓) 사람의 죽음을 애도하다(忄)” -> “애도하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1631/"},"乏":{"id":1620,"char":"乏","hun":"모자랄 핍","meaning":"“모자랄 핍”. 부족하다, 가난하다","on":"ボウ","kun":"とぼ(しい)","explanation":["乏는 𣥄가 변형된 것으로, 본래는 「正」를 거꾸로 뒤집어 만든 글자입니다.","“바르다(正)의 반대(𣥄)” -> “잘못되다” -> “부족하다”라는 의미입니다.","그러나 지금은 글자의 형태가 많이 바뀌어, 본래의 의미를 유추하기 어렵게 되었습니다."],"sourceUrl":"https://nihongokanji.com/1632/"},"該":{"id":1621,"char":"該","hun":"갖출/마땅 해","meaning":"“갖출/마땅 해”. 해박하다, 일치하다","on":"ガイ","kun":"","explanation":["該 = 言 + 亥。","「言」는 “말하다”라는 뜻입니다.","「亥」는 “도축, 가공된 돼지”를 뜻합니다.","該는 “세세한 부분까지 낱낱이 분해해(亥) 전부 설명하다(言)” -> “해박하다, 일치하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1633/"},"赴":{"id":1622,"char":"赴","hun":"다다를/갈 부","meaning":"“다다를/갈 부”. 향해 가다, 달려가다","on":"フ","kun":"おもむ(く)","explanation":["赴 = 走 + 卜。","「走」는 “달리다”라는 뜻입니다.","「卜」는 “점, 점괘”를 뜻합니다.","赴는 “점(卜)을 쳐서 나온 방향대로 달려가다(走)” -> “향해 가다, 달려가다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1634/"},"桑":{"id":1623,"char":"桑","hun":"뽕나무 상","meaning":"“뽕나무 상”. 뽕나무","on":"ソウ","kun":"くわ","explanation":["桑 = 叒 + 木。","「木」는 “나무”를 뜻합니다.","叒는 여기서는 “뽕잎”을 그린 모양자입니다.","桑는 “뽕잎(叒)이 있는 나무(木)” -> “뽕나무”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1635/"},"髄":{"id":1624,"char":"髄","hun":"골수 수","meaning":"“골수 수”. 골수","on":"ズイ","kun":"","explanation":["髄 = 骨 + 迶。","(의미부) 「骨」는 “뼈”를 뜻합니다.","(소리부 겸 의미부) 迶는 여기서는 「随」(ズイ)가 축약된 것으로, “따르다”라는 뜻입니다.","髄는 “뼈(骨)를 따라(随) 흐르는 액체” -> “골수”라는 뜻의 글자입니다.","(迶->随는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1636/"},"虎":{"id":1625,"char":"虎","hun":"범 호","meaning":"“범 호”. 호랑이","on":"コ","kun":"とら","explanation":["虎 = 虍 + 儿。","「虍」는 “호랑이”를 뜻합니다.","儿는 여기서는 “호랑이의 앞발”을 그린 모양자입니다.","虎는 “호랑이(虍)의 앞발(儿)” -> “호랑이”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1637/"},"盆":{"id":1626,"char":"盆","hun":"동이 분","meaning":"“동이 분”. 동이, 쟁반","on":"ボン","kun":"","explanation":["盆 = 分 + 皿。","(소리부) 「分」(ブン)은 여기서는 소리부(ブン -> ボン)의 역할만 하고 있습니다.","(의미부) 「皿」는 “그릇, 접시”를 뜻합니다.","盆는 “커다란 그릇(皿)” -> “동이, 쟁반”이라는 뜻의 글자입니다(分는 소리부)."],"sourceUrl":"https://nihongokanji.com/1638/"},"穂":{"id":1627,"char":"穂","hun":"이삭 수","meaning":"“이삭 수”. 이삭","on":"スイ","kun":"ほ","explanation":["穂 = 禾 + 恵。","「禾」는 “곡식”을 뜻합니다.","「恵」는 “은혜”를 뜻합니다.","穂는 “곡식(禾)이 주는 은혜(恵)” -> “이삭”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1639/"},"壮":{"id":1628,"char":"壮","hun":"씩씩할 장","meaning":"“씩씩할 장”. 장하다, 사내답다, 굳세다","on":"ソウ","kun":"","explanation":["壮 = 丬 + 士。","「丬」는 “탁자”를 뜻합니다.","「士」는 “선비, 무사”를 뜻합니다.","壮는 “거대한 탁자(丬)를 한 손으로 든 무사(士)” -> “장하다, 씩씩하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1640/"},"堤":{"id":1629,"char":"堤","hun":"둑 제","meaning":"“둑 제”. 제방, 둑","on":"テイ","kun":"つつみ","explanation":["堤 = 土 + 是。","(의미부) 「土」는 “흙”을 뜻합니다.","(소리부 겸 의미부) 「是」(ゼ)는 “옳다, 바르다”라는 뜻입니다.","堤는 “흙(土)을 바르게(是) 쌓아 둑을 만들다” -> “둑, 제방”이라는 뜻의 글자입니다.","(是는 소리부(ゼ -> テイ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1641/"},"飢":{"id":1630,"char":"飢","hun":"주릴 기","meaning":"“주릴 기”. 굶주리다","on":"キ","kun":"う(える)","explanation":["飢 = 食 + 几。","「食」는 “먹다”라는 뜻입니다.","几는 여기서는 “살가죽”을 그린 모양자입니다(986.「肌」 모양 해설 참조).","飢는 “밥(食)을 먹지 못해 살가죽(几)이 등에 붙다” -> “굶주리다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1642/"},"傍":{"id":1631,"char":"傍","hun":"곁 방","meaning":"“곁 방”. 곁, 옆","on":"ボウ","kun":"かたわ(ら)","explanation":["傍 = 亻 + 立 + 方。","(의미부) 「亻」는 “사람”을 뜻합니다.","(의미부) 「立」는 “서다”라는 뜻입니다.","(소리부 겸 의미부) 「方」(ホウ)는 “방향”을 뜻합니다.","傍는 “옆쪽(方)에 서있는(立) 사람(亻)” -> “곁, 옆”이라는 뜻의 글자입니다.","(方는 소리부(ホウ -> ボウ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1643/"},"疫":{"id":1632,"char":"疫","hun":"전염병 역","meaning":"“전염병 역”. 역병, 전염병","on":"エキ、ヤク","kun":"","explanation":["疫 = 疒 + 殳。","(의미부) 「疒」는 “병, 질병”을 뜻합니다.","(소리부) 殳는 여기서는 「役」(エキ・ヤク)가 축약된 것으로, 소리부의 역할만 하고 있습니다.","疫는 “전염되는 질병(疒)” -> “전염병, 역병”이라는 뜻의 글자입니다(殳->役는 소리부)."],"sourceUrl":"https://nihongokanji.com/1644/"},"累":{"id":1633,"char":"累","hun":"묶을/여러 루","meaning":"“묶을/여러 루”. 쌓이다, 겹치다, 묶이다","on":"ルイ","kun":"","explanation":["累 = 田 + 糸。","「糸」는 “실”을 뜻합니다.","田는 여기서는 “털실이 차곡차곡 쌓여 포개진 모습”을 그린 모양자입니다.","累는 “겹겹이 쌓여 포개진(田) 털실(糸)” -> “쌓이다, 겹치다, 묶이다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1645/"},"痴":{"id":1634,"char":"痴","hun":"어리석을 치","meaning":"“어리석을 치”. 어리석다","on":"チ","kun":"","explanation":["痴 = 疒 + 知。","(의미부) 「疒」는 “병, 질병”을 뜻합니다.","(소리부 겸 의미부) 「知」(チ)는 “알다, 지식”을 뜻합니다.","痴는 “지적(知)인 측면의 질병(疒)” -> “멍청하다, 어리석다”라는 뜻의 글자입니다.","(知는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1646/"},"搬":{"id":1635,"char":"搬","hun":"옮길 반","meaning":"“옮길 반”. 옮기다, 나르다","on":"ハン","kun":"","explanation":["搬 = 扌 + 般。","(의미부) 「扌」는 “손”을 뜻합니다.","(소리부 겸 의미부) 「般」(ハン)은 본래 “고기잡이 배”를 그린 글자입니다(링크 참조).","搬은 “배에서 잡은 고기(般)를 육지로 운반하다(扌)” -> “옮기다, 나르다”라는 뜻의 글자입니다.","(般는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1647/"},"癒":{"id":1636,"char":"癒","hun":"병 나을 유","meaning":"“병 나을 유”. 치유하다","on":"ユ","kun":"い(える)、い(やす)","explanation":["癒 = 疒 + 俞 + 心。","(의미부) 「疒」는 “병, 질병”을 뜻합니다.","(소리부 겸 의미부) 「俞」(ユ)는 “보내다”라는 뜻입니다.","(의미부) 「心」는 “마음”을 뜻합니다.","癒는 “마음(心)의 병(疒)을 훨훨 날려보내다(俞)” -> “치유하다”라는 뜻의 글자입니다.","(俞는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1648/"},"寸":{"id":1637,"char":"寸","hun":"마디 촌","meaning":"“마디 촌”. 촌(길이의 단위), 극히 조금","on":"スン","kun":"","explanation":["寸는 “손과 손목”을 본따 그린 상형문자입니다.","“손끝에서 손목까지의 길이” -> “촌, 조금”이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/1649/"},"郭":{"id":1638,"char":"郭","hun":"둘레/외성 곽","meaning":"“둘레/외성 곽”. 외곽, 둘레, 성곽","on":"カク","kun":"","explanation":["郭 = 享 + ⻏。","「享」는 “모자를 쓴 아이”를 뜻합니다.","「⻏」는 “도시”를 뜻합니다.","郭는 “도시(⻏) 바깥의 성곽에서 놀고있는 아이(享)” -> “외곽, 둘레, 성곽”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1650/"},"尿":{"id":1639,"char":"尿","hun":"오줌 뇨","meaning":"“오줌 뇨”. 소변, 오줌","on":"ニョウ","kun":"","explanation":["尿 = 尸 + 水。","「尸」는 “앉아있는 사람”을 뜻합니다.","「水」는 “물”을 뜻합니다.","尿는 “여자가 앉아서(尸) 소변을(水) 보다” -> “소변”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1651/"},"凶":{"id":1640,"char":"凶","hun":"흉할 흉","meaning":"“흉할 흉”. 간악한, 흉한, 불길한","on":"キョウ","kun":"","explanation":["凶는 “함정(凵)에 빠진 사람(メ)”을 그린 상형문자입니다.","“함정에 빠지다” -> “불길하다, 흉하다, 간악하다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/1652/"},"吐":{"id":1641,"char":"吐","hun":"토할 토","meaning":"“토할 토”. 토하다","on":"ト","kun":"は(く)","explanation":["吐 = 口 + 土。","(의미부) 「口」는 “입”을 뜻합니다.","(소리부 겸 의미부) 「土」(ト)는 “흙, 땅”을 뜻합니다.","吐는 “땅바닥(土)에 토하다(口)” -> “토하다”라는 뜻의 글자입니다.","(土는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1653/"},"宴":{"id":1642,"char":"宴","hun":"잔치 연","meaning":"“잔치 연”. 잔치, 연회","on":"エン","kun":"","explanation":["宴 = 宀 + 曰 + 女。","「宀」는 “집”을 뜻합니다.","「曰」는 “말하다”라는 뜻입니다.","「女」는 “여자”를 뜻합니다.","宴는 “집(宀)에서 여자(女)를 끼고 왁자지껄 떠들며(曰) 연회를 벌이다” -> “연회, 잔치”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1654/"},"賓":{"id":1643,"char":"賓","hun":"손 빈","meaning":"“손 빈”. 귀한 손님","on":"ヒン","kun":"","explanation":["賓 = 宀 + 一 + 少 + 貝。","「宀」는 “집”을 뜻합니다.","「一」는 “하나”를 뜻합니다.","「少」는 “적다”라는 뜻입니다.","「貝」는 “돈, 재물”을 뜻합니다.","賓는 “가끔(少) 한 번씩(一) 집에(宀) 찾아오는 돈 많은(貝) 손님” -> “귀한 손님”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1655/"},"虜":{"id":1644,"char":"虜","hun":"사로잡을 로","meaning":"“사로잡을 로”. 포로","on":"リョ","kun":"","explanation":["虜 = 虍 + 男。","「虍」는 “호랑이”를 뜻합니다.","「男」는 “사내, 남성”을 뜻합니다.","虜는 “호랑이(虍)에게 잡힌 사내(男)” -> “포로, 사로잡다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1656/"},"陶":{"id":1645,"char":"陶","hun":"질그릇 도","meaning":"“질그릇 도”. 질그릇, 빚어 만들다, 황홀함","on":"トウ","kun":"","explanation":["陶 = ⻖ + 匋。","⻖는 여기서는 “(질그릇을 굽는) 가마”를 그린 모양자입니다.","匋는 “허리를 숙인 채(勹) 절굿공이(午)를 들고 절구(凵)에 빻는 사람”을 그린 상형문자입니다. 아래 그림을 참조해 주세요.","여기서는 “절구를 빻다” -> “진흙을 빚다”라는 뜻으로 응용된 것입니다.","陶는 “진흙을 빚어서(匋) 가마(⻖)에 넣고 구워 질그릇을 만들다” -> “질그릇, 빚어 만들다, 황홀함”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1657/"},"鐘":{"id":1646,"char":"鐘","hun":"쇠북 종","meaning":"“쇠북 종”. 종","on":"ショウ","kun":"かね","explanation":["鐘 = 金 + 童。","「金」는 “쇠, 금속”을 뜻합니다.","「童」는 “아이”를 뜻합니다.","鐘는 “쇠종(金)을 치는 동자승(童)” -> “종”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1658/"},"憾":{"id":1647,"char":"憾","hun":"섭섭할 감","meaning":"“섭섭할 감”. 섭섭하다, 유감","on":"カン","kun":"","explanation":["憾 = 忄 + 感。","(의미부) 「忄」는 “마음”을 뜻합니다.","(소리부 겸 의미부) 「感」(カン)은 “감정”을 뜻합니다.","憾는 “섭섭한 마음(忄)의 감정(感)” -> “섭섭함, 유감”이라는 뜻의 글자입니다.","(感는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1659/"},"磁":{"id":1648,"char":"磁","hun":"자석 자","meaning":"“자석 자”. 자석","on":"ジ","kun":"","explanation":["磁 = 石 + 兹。","(의미부) 「石」는 “돌”을 뜻합니다.","(소리부 겸 의미부) 「兹」(ジ)는 “담장에 붙어 자라난 덩굴”을 그린 글자입니다.","磁는 “금속이 달라붙는(兹) 돌(石)” -> “자석”이라는 뜻의 글자입니다.","(兹는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1660/"},"弥":{"id":1649,"char":"弥","hun":"두루 미","meaning":"“두루 미”. 퍼지다, 두루 미치다, 깁다","on":"ビ、ミ","kun":"や","explanation":["弥 = 弓 + 尔。","「弓」는 “활”을 뜻합니다.","尔는 여기서는 “화살(小)이 날아가 꽂히는 모습”을 그린 모양자입니다.","弥는 “활(弓)을 쏘아 화살을 멀리 날리다(尔)” -> “퍼지다, 두루 미치다, 깁다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1661/"},"昆":{"id":1650,"char":"昆","hun":"맏/벌레 곤","meaning":"“맏/벌레 곤”. 후손, 곤충","on":"コン","kun":"","explanation":["昆 = 日 + 比。","「日」는 “태양”을 뜻합니다.","「比」는 본래 “나란히 서 있는 사람들”을 그린 글자입니다(링크 참조).","昆는 “태양(日) 아래 늘어선 사람들(比)”이라는 뜻입니다.","“줄지어 늘어선 사람들” -> “대가 이어지다” -> “후손”","“후손” -> “곤충은 새끼를 많이 낳는다” -> “곤충”","이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/1662/"},"粗":{"id":1651,"char":"粗","hun":"거칠 조","meaning":"“거칠 조”. 거친, 조잡한","on":"ソ","kun":"あら(い)","explanation":["粗 = 米 + 且。","(의미부) 「米」는 “쌀”을 뜻합니다.","(소리부 겸 의미부) 「且」(ソ)는 “비석, 조상, 장례”를 뜻합니다.","粗는 “제사(且)에 쓰는 생쌀(米)” -> “거친, 조잡한”이라는 뜻의 글자입니다.","(且는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1663/"},"訂":{"id":1652,"char":"訂","hun":"바로잡을 정","meaning":"“바로잡을 정”. 수정하다, 고치다, 바로잡다","on":"テイ","kun":"","explanation":["訂 = 言 + 丁。","(의미부) 「言」는 “말하다”라는 뜻입니다.","(소리부 겸 의미부) 「丁」(テイ)는 “못”을 뜻합니다. 여기서는 “못질하다” -> “수리하다, 고치다”라는 뜻으로 쓰인 것입니다.","訂는 “말(言)을 고치다(丁)” -> “수정하다, 바로잡다”라는 뜻의 글자입니다.","(丁는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1664/"},"芽":{"id":1653,"char":"芽","hun":"싹 아","meaning":"“싹 아”. 싹, 새싹","on":"ガ","kun":"め","explanation":["芽 = 艹 + 牙。","(의미부) 「艹」는 “풀”을 뜻합니다.","(소리부 겸 의미부) 牙(ガ – “어금니 아”)는 “이, 어금니”를 뜻하는 상용한자입니다.","芽는 “아기의 이(牙)가 나듯 새싹(艹)이 돋아나다” -> “새싹”이라는 뜻의 글자입니다.","(牙는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1665/"},"傘":{"id":1654,"char":"傘","hun":"우산 산","meaning":"“우산 산”. 우산","on":"サン","kun":"かさ","explanation":["傘는 “우산을 펼친 모습”을 본따 그린 상형문자입니다."],"sourceUrl":"https://nihongokanji.com/1666/"},"騎":{"id":1655,"char":"騎","hun":"말 탈 기","meaning":"“말 탈 기”. 말을 타다","on":"キ","kun":"","explanation":["騎 = 馬 + 奇。","(의미부) 「馬」는 “말”을 뜻합니다.","(소리부 겸 의미부) 「奇」(キ)는 본래 “짐보따리를 든 사람”을 그린 글자입니다(링크 참조).","騎는 “짐을 들고(奇) 말(馬) 위에 올라타다” -> “말을 타다”라는 뜻의 글자입니다.","(奇는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1667/"},"寧":{"id":1656,"char":"寧","hun":"편안할 녕","meaning":"“편안할 녕”. 편안한, 안정된, 정중한","on":"ネイ","kun":"","explanation":["寧 = 宀 + 心 + 罒 + 丁。","「宀」는 “집”을 뜻합니다.","「心」는 “마음”을 뜻합니다.","丁는 여기서는 “탁자”를 그린 모양자입니다.","罒는 여기서는 “(탁자 위의) 음식”을 그린 모양자입니다.","寧는 “살 집(宀)과 먹을 음식(罒+丁)이 있으니 마음(心)이 편안하다” -> “편안한, 안정된, 정중한”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1668/"},"循":{"id":1657,"char":"循","hun":"돌 순","meaning":"“돌 순”. 순환하다, 따라서 돌다","on":"ジュン","kun":"","explanation":["循 = 彳 + 盾。","(의미부) 「彳」는 “길”을 뜻합니다.","(소리부 겸 의미부) 「盾」(ジュン)은 “방패”를 뜻합니다.","循은 “방패(盾)를 들고 길(彳)을 돌며 순찰하다” -> “순환하다, 따라서 돌다”라는 뜻의 글자입니다.","(盾는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1669/"},"忍":{"id":1658,"char":"忍","hun":"참을 인","meaning":"“참을 인”. 참다, 견디다","on":"ニン","kun":"しの(ぶ)、しの(ばせる)","explanation":["忍 = 刃 + 心。","刃(“칼날 인”)은 “칼날”을 뜻하는 상용한자입니다.","「心」는 “마음”을 뜻합니다.","忍는 “마음(心)을 찌르는(刃) 고통을 견디다” -> “참다, 견디다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1670/"},"怠":{"id":1659,"char":"怠","hun":"게으를 태","meaning":"“게으를 태”. 게으르다","on":"タイ","kun":"おこた(る)、なま(ける)","explanation":["怠 = 台 + 心。","(소리부) 「台」(タイ)는 여기서는 소리부의 역할만 하고 있습니다.","(의미부) 「心」는 “마음”을 뜻합니다.","怠는 “게으른 심성(心)” -> “게으르다”라는 뜻의 글자입니다(台는 소리부)."],"sourceUrl":"https://nihongokanji.com/1671/"},"如":{"id":1660,"char":"如","hun":"같을 여","meaning":"“같을 여”. 그대로, 같은","on":"ジョ、ニョ","kun":"","explanation":["如 = 女 + 口。","(소리부 겸 의미부) 「女」(ジョ・ニョ)는 “여자”를 뜻합니다.","(의미부) 「口」는 “입”을 뜻합니다.","如는 “여자(女)가 남성의 지시(口)대로 순종하다” -> “그대로 따르다” -> “그대로, 같은”이라는 뜻의 글자입니다.","(女는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1672/"},"寮":{"id":1661,"char":"寮","hun":"동관 료","meaning":"“동관 료”. 기숙사","on":"リョウ","kun":"","explanation":["寮 = 宀 + 尞。","(의미부) 「宀」는 “집”을 뜻합니다.","(소리부 겸 의미부) 「尞」(リョウ)는 “횃불”을 뜻합니다.","寮는 “불이 환하게 켜진(尞) 집(宀)” -> “기숙사”라는 뜻의 글자입니다.","(尞는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1673/"},"鉛":{"id":1662,"char":"鉛","hun":"납 연","meaning":"“납 연”. 납","on":"エン","kun":"なまり","explanation":["鉛 = 金 + 㕣。","(의미부) 「金」는 “쇠, 금속”을 뜻합니다.","(소리부) 㕣는 여기서는 「沿」(エン)이 축약된 것으로, 소리부의 역할만 하고 있습니다.","鉛는 “무거운 금속(金)” -> “납”이라는 뜻의 글자입니다(㕣->沿는 소리부)."],"sourceUrl":"https://nihongokanji.com/1674/"},"珠":{"id":1663,"char":"珠","hun":"구슬 주","meaning":"“구슬 주”. 구슬, 진주","on":"シュ","kun":"","explanation":["珠 = 𤣩 + 朱。","(의미부) 「𤣩」는 “구슬, 보석”을 뜻합니다.","(소리부 겸 의미부) 朱(シュ – “붉을 주”)는 “주홍색”을 뜻하는 상용한자입니다.","珠는 “주홍색(朱) 구슬(𤣩)” -> “구슬, 진주”라는 뜻의 글자입니다(朱는 소리부도 겸함)."],"sourceUrl":"https://nihongokanji.com/1675/"},"凝":{"id":1664,"char":"凝","hun":"엉길 응","meaning":"“엉길 응”. 엉기다","on":"ギョウ","kun":"こ(る)、こ(らす)","explanation":["凝 = 冫 + 疑。","(의미부) 「冫」는 “얼음”을 뜻합니다.","(소리부) 「疑」(ギ)는 여기서는 소리부(ギ -> ギョウ)의 역할만 하고 있습니다.","凝는 “얼음(冫)이 얼어붙어 뭉치다” -> “엉기다”라는 뜻의 글자입니다(疑는 소리부)."],"sourceUrl":"https://nihongokanji.com/1676/"},"苗":{"id":1665,"char":"苗","hun":"모 묘","meaning":"“모 묘”. 모종, 곡식","on":"ビョウ","kun":"なえ、なわ","explanation":["苗 = 艹 + 田。","「艹」는 “풀”을 뜻합니다.","「田」는 “밭”을 뜻합니다.","苗는 “밭(田)에 심어놓은 어린 싹(艹)” -> “모종, 곡식”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1677/"},"獣":{"id":1666,"char":"獣","hun":"짐승 수","meaning":"“짐승 수”. 짐승","on":"ジュウ","kun":"けもの","explanation":["獣 = 兽 + 犬。","兽는 「単」가 변형된 것으로, 본래 “사냥에 쓰이던 무기”를 그린 글자입니다(링크 참조).","「犬」는 “개”를 뜻합니다.","獣는 “사냥용 무기(兽)와 사냥개(犬)로 짐승을 사냥하다” -> “짐승”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1678/"},"哀":{"id":1667,"char":"哀","hun":"슬플 애","meaning":"“슬플 애”. 슬프다, 가엾다","on":"アイ","kun":"あわ(れ)、あわ(れむ)","explanation":["哀 = 衣 + 口。","「衣」는 “옷”을 뜻합니다.","「口」는 “입”을 뜻합니다.","哀는 “상복(衣)을 입고 슬피 울다(口)” -> “슬프다, 가엾다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1679/"},"跳":{"id":1668,"char":"跳","hun":"뛸 도","meaning":"“뛸 도”. 뛰어오르다, 도약하다","on":"チョウ","kun":"は(ねる)、と(ぶ)","explanation":["跳 = 足 + 兆。","(의미부) 「足」는 “발”을 뜻합니다.","(소리부 겸 의미부) 「兆」(チョウ)는 여기서는 “두 팔을 휘두르며 방방 뛰는 모습”을 그린 모양자입니다.","跳는 “발(足)을 구르며 방방 뛰다(兆)” -> “뛰어오르다, 도약하다”라는 뜻의 글자입니다.","(兆는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1680/"},"匠":{"id":1669,"char":"匠","hun":"장인 장","meaning":"“장인 장”. 장인, 기술자, 목공","on":"ショウ","kun":"","explanation":["匠 = 匚 + 斤。","「斤」는 “도끼”를 뜻합니다.","匚는 여기서는 “도끼를 넣어두는 목공 도구 상자”를 그린 모양자입니다.","匠는 “도끼(斤)가 든 목공 도구 상자(匚)” -> “목공, 기술자, 장인”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1681/"},"垂":{"id":1670,"char":"垂","hun":"드리울 수","meaning":"“드리울 수”. 드리우다, 매달리다","on":"スイ","kun":"た(れる)、た(らす)","explanation":["垂는 “풀잎이 드리워져 있는 모습”을 그린 상형문자입니다."],"sourceUrl":"https://nihongokanji.com/1682/"},"蛇":{"id":1671,"char":"蛇","hun":"긴 뱀 사","meaning":"“긴 뱀 사”. 뱀","on":"ジャ、ダ","kun":"へび","explanation":["蛇 = 虫 + 宀 + 匕。","虫는 여기서는 “또아리를 튼 뱀”을 그린 모양자입니다.","「宀」는 “집”을 뜻합니다.","「匕」는 “넘어져있는 사람”을 뜻합니다.","蛇는 “집(宀)에 들어온 뱀(虫)에게 물려 쓰러진 사람(匕)” -> “뱀”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1683/"},"澄":{"id":1672,"char":"澄","hun":"맑을 징","meaning":"“맑을 징”. 맑다","on":"チョウ","kun":"す(む)、す(ます)","explanation":["澄 = 氵 + 登。","(의미부) 「氵」는 “물”을 뜻합니다.","(소리부 겸 의미부) 「登」(トウ)는 “오르다, 올라가다”라는 뜻입니다.","澄는 “산 정상에 올라(登) 마시는 맑은 샘물(氵)” -> “맑다”라는 뜻의 글자입니다.","(登는 소리부(トウ -> チョウ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1684/"},"縫":{"id":1673,"char":"縫","hun":"꿰맬 봉","meaning":"“꿰맬 봉”. 꿰매다","on":"ホウ","kun":"ぬ(う)","explanation":["縫 = 糸 + ⻌ + 夆。","「糸」는 “실”을 뜻합니다.","「⻌」는 “길”을 뜻합니다.","夆는 여기서는 “실을 꿰매고(丰) 매듭을 지은(夂) 모습”을 그린 모양자입니다.","縫는 “표시된 길(⻌)을 따라 실(糸)을 꿰매다(夆)” -> “꿰매다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1685/"},"僧":{"id":1674,"char":"僧","hun":"중 승","meaning":"“중 승”. 승려","on":"ソウ","kun":"","explanation":["僧 = 亻 + 曽。","(의미부) 「亻」는 “사람”을 뜻합니다.","(소리부 겸 의미부) 「曽」(ソウ)는 “쌓이다”라는 뜻입니다.","僧는 “절에서 수행을 쌓는(曽) 사람(亻)” -> “승려”라는 뜻의 글자입니다.","(曽는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1686/"},"幾":{"id":1675,"char":"幾","hun":"몇 기","meaning":"“몇 기”. 몇, 얼마","on":"キ","kun":"いく","explanation":["幾는 본래 “베틀(戈)에 앉아 실(幺幺)을 짜는 사람(人)“을 그린 글자입니다(315.「機」 모양 해설 참조).","“베를 몇 필이나 짜냈는가” -> “몇, 얼마”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/1687/"},"眺":{"id":1676,"char":"眺","hun":"바라볼 조","meaning":"“바라볼 조”. 바라보다, 조망하다","on":"チョウ","kun":"なが(める)","explanation":["眺 = 目 + 兆。","(의미부) 「目」는 “눈”을 뜻합니다.","(소리부 겸 의미부) 「兆」(チョウ)는 “징조, 징후”를 뜻합니다.","眺는 “날씨가 나빠질 징조(兆)를 내다보다(目)” -> “바라보다, 조망하다”라는 뜻의 글자입니다.","(兆는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1688/"},"唐":{"id":1677,"char":"唐","hun":"당나라/당황할 당","meaning":"“당나라/당황할 당”. 당나라, 당황하다","on":"トウ","kun":"から","explanation":["唐 = 广 + ⺕ + 丨 + 口。","「广」는 “건물, 집”을 뜻합니다.","「⺕」는 “손”을 뜻합니다.","丨+口는 여기서는 “절굿공이(丨)와 절구(口)”를 그린 모양자입니다.","唐는 “집(广) 안까지 절구(丨+口)를 가지고 들어와 빻다(⺕)” -> “당황하다”라는 뜻의 글자입니다.","(“당나라”라는 의미는 단순히 중국의 당나라가 唐라는 글자를 나라 이름으로 썼기에 붙게 된 것입니다.)"],"sourceUrl":"https://nihongokanji.com/1689/"},"呉":{"id":1678,"char":"呉","hun":"성씨 오","meaning":"“성씨 오”. 오나라","on":"ゴ","kun":"","explanation":["呉는 본래 “머리를 옆으로 기우뚱하고 있는 사람”을 그린 상형문자입니다.","“오나라”라는 의미는 단순히 오나라가 呉를 나라 이름으로 썼기에 붙게 된 것입니다."],"sourceUrl":"https://nihongokanji.com/1690/"},"凡":{"id":1679,"char":"凡","hun":"무릇 범","meaning":"“무릇 범”. 평범한","on":"ボン、ハン","kun":"","explanation":["凡는 “나무판자”를 그린 상형문자입니다.","“아무데나 있는 나무판자” -> “평범하다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/1691/"},"憩":{"id":1680,"char":"憩","hun":"쉴 게","meaning":"“쉴 게”. 쉬다","on":"ケイ","kun":"いこ(い)、いこ(う)","explanation":["憩 = 舌 + 息。","「舌」는 “혀”를 뜻합니다.","「息」는 “숨쉬다, 휴식”이라는 뜻입니다.","憩는 “혀(舌)를 내밀고 헉헉거리며 휴식하다(息)” -> “쉬다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1692/"},"媛":{"id":1681,"char":"媛","hun":"여자 원","meaning":"“여자 원”. 우아한 여자, 미녀","on":"エン","kun":"","explanation":["媛 = 女 + 爰。","「女」는 “여자”를 뜻합니다.","「爰」는 “한가롭다, 여유롭다, 느긋하다”라는 뜻입니다.","媛는 “한가롭게(爰) 정원을 거닐고 있는 여자(女)” -> “우아한 여자, 미녀”라는 뜻의 글자입니다.","(다만, 이 한자는 실제로는 거의 지명한자로만 쓰입니다.)"],"sourceUrl":"https://nihongokanji.com/1693/"},"溝":{"id":1682,"char":"溝","hun":"도랑 구","meaning":"“도랑 구”. 도랑, 해자","on":"コウ","kun":"みぞ","explanation":["溝 = 氵 + 冓。","(의미부) 「氵」는 “물”을 뜻합니다.","(소리부 겸 의미부) 冓는 여기서는 「構」(コウ)가 축약된 것으로, “만들다, 구축하다”라는 뜻입니다.","溝는 “물(氵)이 흘러갈 도랑을 만들다(構)” -> “도랑, 해자”라는 뜻의 글자입니다.","(冓->構는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1694/"},"恭":{"id":1683,"char":"恭","hun":"공손할 공","meaning":"“공손할 공”. 공경하다, 공손하다","on":"キョウ","kun":"うやうや(しい)","explanation":["恭 = 共 + ⺗。","(소리부 겸 의미부) 「共」(キョウ)는 본래 “쟁반을 두 손으로 받든 모습”을 그린 글자입니다(링크 참조).","(의미부) ⺗는 여기서는 「心」가 변형된 것으로, “마음”을 뜻합니다.","恭는 “공경하는 마음(⺗)으로 공손히 받들다(共)” -> “공경하다, 공손하다”라는 뜻의 글자입니다.","(共는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1695/"},"刈":{"id":1684,"char":"刈","hun":"벨 예","meaning":"“벨 예”. 베다","on":"","kun":"か(る)","explanation":["刈 = メ + 刂。","メ는 여기서는 “칼자국”을 그린 모양자입니다.","「刂」는 “칼”을 뜻합니다.","刈는 “칼(刂)로 베다(メ)” -> “베다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1696/"},"睡":{"id":1685,"char":"睡","hun":"졸음 수","meaning":"“졸음 수”. 졸다, 자다","on":"スイ","kun":"","explanation":["睡 = 目 + 垂。","(의미부) 「目」는 “눈”을 뜻합니다.","(소리부 겸 의미부) 「垂」(スイ)는 “늘어지다, 드리우다”라는 뜻입니다.","睡는 “졸려서 눈(目)이 아래로 늘어지다(垂)” -> “졸다, 자다”라는 뜻의 글자입니다.","(垂는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1697/"},"錯":{"id":1686,"char":"錯","hun":"어긋날 착","meaning":"“어긋날 착”. 착각하다, 뒤섞이다","on":"サク","kun":"","explanation":["錯 = 金 + 昔。","(의미부) 「金」는 “쇠, 금속”을 뜻합니다.","(소리부 겸 의미부) 「昔」(シャク)는 “옛날”을 뜻합니다.","錯는 “옛날(昔) 방식의 금속(金) 제련은 어렵고 헷갈린다” -> “착각하다, 뒤섞이다”라는 뜻의 글자입니다.","(昔는 소리부(シャク -> サク)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1698/"},"伯":{"id":1687,"char":"伯","hun":"맏 백","meaning":"“맏 백”. 맏, 큰형","on":"ハク","kun":"","explanation":["伯 = 亻 + 白。","(의미부) 「亻」는 “사람”을 뜻합니다.","(소리부 겸 의미부) 「白」(ハク)는 “희다”라는 뜻입니다.","伯는 “머리가 하얗게(白) 센 맏형(亻)” -> “맏, 큰형”이라는 뜻의 글자입니다.","(白는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1699/"},"穀":{"id":1688,"char":"穀","hun":"곡식 곡","meaning":"“곡식 곡”. 곡물, 곡식","on":"コク","kun":"","explanation":["穀 = 士 + 冖 + 禾 + 殳。","「禾」는 “곡식”을 뜻합니다.","「殳」는 “때리다, 휘두르다”라는 뜻입니다.","士+冖는 여기서는 “도리깨”를 그린 모양자입니다.","穀는 “도리깨(士+冖)를 휘둘러(殳) 곡식의(禾) 낟알을 벗기다” -> “곡물, 곡식”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1700/"},"陵":{"id":1689,"char":"陵","hun":"언덕 릉","meaning":"“언덕 릉”. 구릉, 능(임금의 무덤)","on":"リョウ","kun":"みささぎ","explanation":["陵 = ⻖ + 土 + ハ + 夂。","「⻖」는 “언덕”을 뜻합니다.","「土」는 “흙”을 뜻합니다.","「夂」는 “발”을 뜻합니다.","ハ는 여기서는 “오르막길”을 그린 모양자입니다.","陵는 “흙(土)으로 뒤덮인 언덕(⻖) 위로 올라가는(ハ) 발(夂)” -> “구릉, 큰 언덕” -> “능묘”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1701/"},"霧":{"id":1690,"char":"霧","hun":"안개 무","meaning":"“안개 무”. 안개","on":"ム","kun":"きり","explanation":["霧 = 雨 + 務。","(의미부) 「雨」는 “비”를 뜻합니다.","(소리부) 「務」(ム)는 여기서는 소리부의 역할만 하고 있습니다.","霧는 “비(雨)가 와서 안개가 끼다” -> “안개”라는 뜻의 글자입니다(務는 소리부)."],"sourceUrl":"https://nihongokanji.com/1702/"},"魂":{"id":1691,"char":"魂","hun":"넋 혼","meaning":"“넋 혼”. 혼백, 영혼, 정신","on":"コン","kun":"たましい","explanation":["魂 = 云 + 鬼。","「云」는 “구름”을 뜻합니다.","「鬼」는 “귀신”을 뜻합니다.","魂는 “구름(云)처럼 떠도는 귀신(鬼)의 혼백” -> “혼백, 영혼, 정신”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1703/"},"弊":{"id":1692,"char":"弊","hun":"폐단/해질 폐","meaning":"“폐단/해질 폐”. 폐해, 폐단, 피로, 피폐","on":"ヘイ","kun":"","explanation":["弊 = 敝 + 廾。","(소리부 겸 의미부) 「敝」(ヘイ)는 “두들겨 맞아서 찢어진 옷”을 뜻하는 글자입니다(링크 참조).","(의미부) 廾는 여기서는 “두 손을 들어올린 사람”을 그린 모양자입니다.","弊는 “벌을 받는 사람(廾)의 옷이 찢어질 정도로 두들겨패다(敝)” -> “폐해, 폐단, 피로, 피폐”라는 뜻의 글자입니다.","(敝는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1704/"},"妃":{"id":1693,"char":"妃","hun":"왕비 비","meaning":"“왕비 비”. 왕비","on":"ヒ","kun":"","explanation":["妃 = 女 + 己。","「女」는 “여자”를 뜻합니다.","「己」는 “무릎꿇은 사람”을 뜻합니다.","妃는 “왕에게 간택받아 무릎꿇고(己) 감사를 표하는 여자(女)” -> “왕비”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1705/"},"舶":{"id":1694,"char":"舶","hun":"배 박","meaning":"“배 박”. 선박, 배","on":"ハク","kun":"","explanation":["舶 = 舟 + 白。","(의미부) 「舟」는 “배”를 뜻합니다.","(소리부) 「白」(ハク)는 여기서는 소리부의 역할만 하고 있습니다.","舶는 “큰 배(舟)” -> “선박”이라는 뜻의 글자입니다(白는 소리부)."],"sourceUrl":"https://nihongokanji.com/1706/"},"餓":{"id":1695,"char":"餓","hun":"주릴 아","meaning":"“주릴 아”. 굶주리다","on":"ガ","kun":"","explanation":["餓 = 食 + 我。","(의미부) 「食」는 “먹다”라는 뜻입니다.","(소리부 겸 의미부) 「我」(ガ)는 본래 “창을 든 손”을 그린 글자입니다(링크 참조).","餓는 “먹을(食) 것이 없어 창을 들고(我) 사냥에 나서다” -> “굶주리다”라는 뜻의 글자입니다.","(我는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1707/"},"窮":{"id":1696,"char":"窮","hun":"다할/궁할 궁","meaning":"“다할/궁할 궁”. 한계에 이르다, 궁핍하다","on":"キュウ","kun":"きわ(める)、きわ(まる)","explanation":["窮 = 穴 + 身 + 弓。","「穴」는 본래 “동굴의 입구”를 그린 글자입니다(링크 참조).","「身」는 “몸”을 뜻합니다.","弓는 여기서는 “뼈가 앙상한 몸”을 그린 모양자입니다.","窮는 “동굴(穴)에 사는 빈민의 뼈가 앙상한(弓) 몸(身)” -> “궁핍하다, 한계에 이르다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1708/"},"掌":{"id":1697,"char":"掌","hun":"손바닥 장","meaning":"“손바닥 장”. 손바닥","on":"ショウ","kun":"","explanation":["掌 = 尚 + 手。","(소리부 겸 의미부) 「尚」(ショウ)는 “높다”라는 뜻입니다.","(의미부) 「手」는 “손”을 뜻합니다.","掌는 “손바닥(手) 위(尚)” -> “손바닥”이라는 뜻의 글자입니다.","(尚는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1709/"},"麗":{"id":1698,"char":"麗","hun":"고울 려","meaning":"“고울 려”. 곱다, 아름답다","on":"レイ","kun":"うるわ(しい)","explanation":["麗 = 丽 + 鹿。","「鹿」는 “사슴”을 뜻합니다.","丽는 여기서는 “사슴의 두 눈”을 그린 모양자입니다.","麗는 “사슴(鹿)의 눈망울(丽)” -> “곱다, 아름답다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1710/"},"臭":{"id":1699,"char":"臭","hun":"냄새 취","meaning":"“냄새 취”. 악취, (나쁜) 냄새","on":"シュウ","kun":"くさ(い)、にお(う)","explanation":["臭 = 自 + 大。","「自」는 본래 “사람의 코”를 그린 글자입니다(링크 참조).","「大」는 “크다”라는 뜻입니다.","臭는 “코(自)로 커다란(大) 악취가 풍겨오다” -> “악취, 냄새”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1711/"},"悦":{"id":1700,"char":"悦","hun":"기쁠 열","meaning":"“기쁠 열”. 기쁘다","on":"エツ","kun":"","explanation":["悦 = 忄 + 兑。","「忄」는 “마음”을 뜻합니다.","「兑」는 “진지한 표정을 한 사람”을 뜻합니다.","悦는 “마음(忄)의 깨달음을 얻은 구도자(兑)” -> “기쁘다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1712/"},"刃":{"id":1701,"char":"刃","hun":"칼날 인","meaning":"“칼날 인”. 칼날","on":"ジン","kun":"は","explanation":["刃 = 刀 + 丶。","「刀」는 “칼”을 뜻합니다.","丶는 여기서는 “칼날” 부분을 강조한 모양자입니다.","刃는 “칼(刀)의 칼날(丶)” -> “칼날”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1713/"},"縛":{"id":1702,"char":"縛","hun":"얽을 박","meaning":"“얽을 박”. 묶다, 포박하다","on":"バク","kun":"しば(る)","explanation":["縛 = 糸 + 尃。","(의미부) 「糸」는 “실”을 뜻합니다.","(소리부 겸 의미부) 「尃」(バク)는 “넓게 퍼지다, 넓다”라는 뜻입니다.","縛는 “밧줄(糸)을 넓게(尃) 둘러 감아두다” -> “묶다, 포박하다”라는 뜻의 글자입니다.","(尃는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1714/"},"暦":{"id":1703,"char":"暦","hun":"책력 력","meaning":"“책력 력”. 달력","on":"レキ","kun":"こよみ","explanation":["暦 = 歴 + 日。","(소리부 겸 의미부) 「歴」(レキ)는 “지나가다, 경과하다”라는 뜻입니다.","(의미부) 「日」는 “날짜”를 뜻합니다.","暦는 歴에서 止 대신 日를 넣어 “날짜, 달력”이라는 의미를 강조한 글자입니다.","“날짜(日)의 경과(歴)를 세다” -> “달력”이라는 의미입니다.","(歴는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1715/"},"宜":{"id":1704,"char":"宜","hun":"마땅 의","meaning":"“마땅 의”. 마땅하다, 적절하다","on":"ギ","kun":"","explanation":["宜 = 宀 + 且。","「宀」는 “집”을 뜻합니다.","「且」는 “비석, 조상, 장례”를 뜻합니다.","宜는 “집(宀)에서는 매년 제사를(且) 지내야 마땅하다” -> “마땅하다, 적절하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1716/"},"盲":{"id":1705,"char":"盲","hun":"맹인 맹","meaning":"“맹인 맹”. 눈이 멀다, 맹인","on":"モウ","kun":"","explanation":["盲 = 亡 + 目。","(소리부 겸 의미부) 「亡」(モウ)는 “망하다, 죽다, 없다”라는 뜻입니다.","(의미부) 「目」는 “눈”을 뜻합니다.","盲는 “눈(目)을 잃다(亡)” -> “눈이 멀다, 맹인”이라는 뜻의 글자입니다.","(亡는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1717/"},"粋":{"id":1706,"char":"粋","hun":"순수할 수","meaning":"“순수할 수”. 순수한, 세련된","on":"スイ","kun":"いき","explanation":["粋 = 米 + 卆。","「米」는 “쌀”을 뜻합니다.","卆는 단순히 「九」와 「十」을 합쳐놓은 글자로, “9(九) + 10(十)” -> “여러 개, 많다”라는 뜻입니다.","粋는 “밥에 백미(米)의 비율이 높다(卆)”라는 뜻입니다.","“잡곡이 섞이지 않은 순수한 백미” -> “순수한, 세련된”이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/1718/"},"辱":{"id":1707,"char":"辱","hun":"욕될 욕","meaning":"“욕될 욕”. 욕보이다, 더럽히다","on":"ジョク","kun":"はずかし(める)","explanation":["辱 = 辰 + 寸。","「辰」는 “쟁기, 농기구”를 뜻합니다.","「寸」는 “손”을 뜻합니다.","辱는 “쟁기(辰)를 손(寸)에 들고 밭일을 하다”라는 뜻입니다.","“고되고 힘든 밭일” -> “욕보이다, 더럽히다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/1719/"},"轄":{"id":1708,"char":"轄","hun":"다스릴 할","meaning":"“다스릴 할”. 관할하다, 관리하다","on":"カツ","kun":"","explanation":["轄 = 車 + 害。","(의미부) 「車」는 “수레, 차”를 뜻합니다.","(소리부 겸 의미부) 害는 여기서는 「割」(カツ)가 축약된 것으로, “가르다, 나누다”라는 뜻입니다.","轄는 “담당 구역을 나누어(割) 각자 차에 타고(車) 돌아보며 관리하다” -> “관할하다, 관리하다”라는 뜻의 글자입니다.","(害->割는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1720/"},"猿":{"id":1709,"char":"猿","hun":"원숭이 원","meaning":"“원숭이 원”. 원숭이","on":"エン","kun":"さる","explanation":["猿 = 犭 + 袁。","(의미부) 「犭」는 “개, 짐승”을 뜻합니다.","(소리부 겸 의미부) 「袁」(エン)은 “길다, 헐렁하다”라는 뜻입니다.","猿는 “팔다리가 길쭉한(袁) 짐승(犭)” -> “원숭이”라는 뜻의 글자입니다.","(袁는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1721/"},"弦":{"id":1710,"char":"弦","hun":"활시위 현","meaning":"“활시위 현”. 활시위","on":"ゲン","kun":"つる","explanation":["弦 = 弓 + 玄。","(의미부) 「弓」는 “활”을 뜻합니다.","(소리부 겸 의미부) 「玄」(ゲン)은 본래 “송진을 발라 가공한 줄”을 그린 글자입니다(링크 참조).","弦는 “활(弓)에 쓰는 튼튼한 활줄(玄)” -> “활시위”라는 뜻의 글자입니다.","(玄은 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1722/"},"窒":{"id":1711,"char":"窒","hun":"막힐 질","meaning":"“막힐 질”. 막히다, 막다","on":"チツ","kun":"","explanation":["窒 = 穴 + 至。","「穴」는 “구멍”을 뜻합니다.","「至」는 본래 “화살이 과녁에 박힌 모습”을 그린 글자입니다(링크 참조).","窒는 “구멍(穴)에 화살을 박아넣어(至) 막다” -> “막다, 막히다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1723/"},"炊":{"id":1712,"char":"炊","hun":"불 땔 취","meaning":"“불 땔 취”. 밥을 짓다","on":"スイ","kun":"た(く)","explanation":["炊 = 火 + 欠。","「火」는 “불”을 뜻합니다.","「欠」는 “입을 벌리고 있는 사람”을 뜻합니다.","炊는 “입김을 불며(欠) 불을 피워(火) 밥을 짓다” -> “밥을 짓다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1724/"},"洪":{"id":1713,"char":"洪","hun":"넓을 홍","meaning":"“넓을 홍”. 홍수","on":"コウ","kun":"","explanation":["洪 = 氵 + 共。","(의미부) 「氵」는 “물”을 뜻합니다.","(소리부 겸 의미부) 「共」(キョウ)는 “함께, 같이”라는 뜻입니다.","洪는 “홍수(氵)에 다 함께(共) 대비하다” -> “홍수”라는 뜻의 글자입니다.","(共는 소리부(キョウ -> コウ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1725/"},"摂":{"id":1714,"char":"摂","hun":"다스릴 섭","meaning":"“다스릴 섭”. 다스리다, 집행하다","on":"セツ","kun":"","explanation":["摂 = 扌 + 耳 + 丷 + ハ。","「扌」는 “손”을 뜻합니다.","「耳」는 “귀”를 뜻합니다.","丷+ハ는 여기서는 “소근거리는 귓속말 소리”를 표현한 모양자입니다.","摂는 “귀(耳)에 손(扌)을 대고 귓속말(丷+ハ)로 지시를 내리다” -> “다스리다, 집행하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1726/"},"飽":{"id":1715,"char":"飽","hun":"배부를 포","meaning":"“배부를 포”. 배부르다, 질리다","on":"ホウ","kun":"あ(きる)、あ(かす)","explanation":["飽 = 食 + 包。","(의미부) 「食」는 “먹다”라는 뜻입니다.","(소리부 겸 의미부) 「包」(ホウ)는 “감싸다”라는 뜻입니다.","飽는 “배가 가득 차도록(包) 실컷 먹다(食)” -> “배부르다, 질리다”라는 뜻의 글자입니다.","(包는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1727/"},"冗":{"id":1716,"char":"冗","hun":"쓸데없을 용","meaning":"“쓸데없을 용”. 쓸데없는, 번거로운","on":"ジョウ","kun":"","explanation":["冗 = 冖 + 几。","冖는 여기서는 「宀」가 축약된 것으로, “집”을 뜻합니다.","几는 여기서는 “집에서 뒹굴거리는 백수”를 그린 모양자입니다.","冗는 “집(冖)에서 할일없이 뒹굴거리는 백수(几)” -> “쓸데없다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1728/"},"桃":{"id":1717,"char":"桃","hun":"복숭아 도","meaning":"“복숭아 도”. 복숭아","on":"トウ","kun":"もも","explanation":["桃 = 木 + 兆。","(의미부) 「木」는 “나무”를 뜻합니다.","(소리부) 「兆」(チョウ)는 여기서는 소리부(チョウ -> トウ)의 역할만 하고 있습니다.","桃는 “복숭아 나무(木)” -> “복숭아”라는 뜻의 글자입니다(兆는 소리부)."],"sourceUrl":"https://nihongokanji.com/1729/"},"狩":{"id":1718,"char":"狩","hun":"사냥할 수","meaning":"“사냥할 수”. 사냥","on":"シュ","kun":"か(る)、か(り)","explanation":["狩 = 犭 + 守。","(의미부) 「犭」는 “개”를 뜻합니다.","(소리부 겸 의미부) 「守」(シュ)는 “지키다”라는 뜻입니다.","狩는 “집을 지키는(守) 파수견(犭)을 데리고 사냥에 나서다” -> “사냥하다”라는 뜻의 글자입니다.","(守는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1730/"},"朱":{"id":1719,"char":"朱","hun":"붉을 주","meaning":"“붉을 주”. 주홍색","on":"シュ","kun":"","explanation":["朱 = 𠂉 + 木。","「木」는 “나무”를 뜻합니다.","𠂉는 여기서는 단순히 구분을 위한 장식으로 추가된 것입니다.","朱는 본래 “적심목”이라는 붉은 빛을 띤 나무를 뜻하기 위해 만들어진 글자입니다.","“붉은색 나무(木)” -> “주홍색”이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/1731/"},"渦":{"id":1720,"char":"渦","hun":"소용돌이 와","meaning":"“소용돌이 와”. 소용돌이","on":"カ","kun":"うず","explanation":["渦 = 氵 + 咼。","(의미부) 「氵」는 “물”을 뜻합니다.","(소리부 겸 의미부) 「咼」(カ)는 “잘못되다, 어긋나다”라는 뜻입니다.","渦는 “물(氵)의 흐름이 어긋나고 난폭해지다(咼)” -> “소용돌이”라는 뜻의 글자입니다.","(咼는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1732/"},"紳":{"id":1721,"char":"紳","hun":"띠 신","meaning":"“띠 신”. 띠, 신사","on":"シン","kun":"","explanation":["紳 = 糸 + 申。","(의미부) 「糸」는 “실”을 뜻합니다.","(소리부 겸 의미부) 「申」(シン)은 여기서는 “허리띠”를 그린 모양자입니다.","紳는 “허리에 매는(申) 끈(糸)” -> “허리띠, 예복” -> “띠, 신사”라는 뜻의 글자입니다.","(申는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1733/"},"枢":{"id":1722,"char":"枢","hun":"지도리 추","meaning":"“지도리 추”. 중추, 가장 중요한 부분","on":"スウ","kun":"","explanation":["枢 = 木 + 区。","「木」는 “나무”를 뜻합니다.","「区」는 “구역, 구획”을 뜻합니다.","枢는 “핵심 구역(区)을 지탱하는 나무기둥(木)” -> “중추, 가장 중요한 부분”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1734/"},"碑":{"id":1723,"char":"碑","hun":"비석 비","meaning":"“비석 비”. 비석","on":"ヒ","kun":"","explanation":["碑 = 石 + 卑。","(의미부) 「石」는 “돌”을 뜻합니다.","(소리부 겸 의미부) 卑(ヒ – “낮을 비”)는 “비천하다”라는 뜻의 상용한자입니다.","碑는 “이름없는 천민(卑)의 무덤에 세워준 비석(石)” -> “비석”이라는 뜻의 글자입니다.","(卑는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1735/"},"鍛":{"id":1724,"char":"鍛","hun":"쇠 불릴 단","meaning":"“쇠 불릴 단”. 단련하다, (쇠를)불리다","on":"タン","kun":"きた(える)","explanation":["鍛 = 金 + 段。","(의미부) 「金」는 “쇠, 금속”을 뜻합니다.","(소리부 겸 의미부) 「段」(ダン)은 “계단, 단계”를 뜻합니다.","鍛는 “쇠(金)를 단계별로(段) 제련하다” -> “단련하다, 쇠를 불리다”라는 뜻의 글자입니다.","(段는 소리부(ダン -> タン)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1736/"},"刀":{"id":1725,"char":"刀","hun":"칼 도","meaning":"“칼 도”. 칼","on":"トウ","kun":"かたな","explanation":["刀는 “반달 모양의 날이 달린 칼”을 본따 그린 상형문자입니다."],"sourceUrl":"https://nihongokanji.com/1737/"},"鼓":{"id":1726,"char":"鼓","hun":"북 고","meaning":"“북 고”. 북","on":"コ","kun":"つづみ","explanation":["鼓 = 壴 + 十 + 又。","「壴」는 “북”을 뜻합니다.","十는 여기서는 “두 개의 북채”를 그린 모양자입니다.","「又」는 “손”을 뜻합니다.","鼓는 “북채(十)를 들고(又) 북(壴)을 치다” -> “북”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1738/"},"裸":{"id":1727,"char":"裸","hun":"벗을 라","meaning":"“벗을 라”. 알몸, 벌거벗다","on":"ラ","kun":"はだか","explanation":["裸 = 衤 + 果。","「衤」는 “옷”을 뜻합니다.","「果」는 본래 “나무에 열린 나무열매”를 그린 글자입니다(링크 참조).","裸는 “옷(衤)을 벗고 알맹이(果)를 드러내다” -> “알몸, 벌거벗다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1739/"},"猶":{"id":1728,"char":"猶","hun":"오히려 유","meaning":"“오히려 유”. 망설이다, 주저하다","on":"ユウ","kun":"","explanation":["猶 = 犭 + 丷 + 酉。","「犭」는 “개, 짐승”을 뜻합니다.","「酉」는 “술, 술병”을 뜻합니다.","丷는 여기서는 “(술통에서 올라오는) 김”을 그린 모양자입니다.","猶는 “김(丷)이 모락모락 올라오는 술통(酉) 앞에서 맛볼지 말지 주저하는 개(犭)” -> “망설이다, 주저하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1740/"},"塊":{"id":1729,"char":"塊","hun":"덩어리 괴","meaning":"“덩어리 괴”. 덩어리","on":"カイ","kun":"かたまり","explanation":["塊 = 土 + 鬼。","(의미부) 「土」는 “흙”을 뜻합니다.","(소리부) 「鬼」(キ)는 여기서는 소리부(キ -> カイ)의 역할만 하고 있습니다.","塊는 “흙(土) 덩어리” -> “덩어리”라는 뜻의 글자입니다(鬼는 소리부)."],"sourceUrl":"https://nihongokanji.com/1741/"},"旋":{"id":1730,"char":"旋","hun":"돌 선","meaning":"“돌 선”. 빙빙 돌다, 회전하다","on":"セン","kun":"","explanation":["旋 = 𭤨 + 疋。","「𭤨」는 “바람에 나부끼는 깃발”을 뜻합니다.","疋는 「正」가 변형된 것으로, 본래 “성문을 향해 걸어가는 발”을 그린 글자입니다(링크 참조).","旋는 “전쟁에서 승리하고 깃발을 휘날리며(𭤨) 성으로 되돌아오다(疋)” -> “돌다, 회전하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1742/"},"弓":{"id":1731,"char":"弓","hun":"활 궁","meaning":"“활 궁”. 활","on":"キュウ","kun":"ゆみ","explanation":["弓는 “활”의 모습을 본따 그린 상형문자입니다."],"sourceUrl":"https://nihongokanji.com/1743/"},"幣":{"id":1732,"char":"幣","hun":"화폐 폐","meaning":"“화폐 폐”. 화폐","on":"ヘイ","kun":"","explanation":["幣 = 敝 + 巾。","(소리부 겸 의미부) 「敝」(ヘイ)는 “두들겨 맞아서 찢어진 옷”을 뜻합니다.","(의미부) 「巾」는 “천”을 뜻합니다.","幣는 “찢어진 옷(敝)을 버리고 새로 산 비단(巾)”이라는 뜻입니다.","고대에는 비단이 비싸고 귀한 물건이었기에 화폐의 단위로 쓰이는 경우가 많았다고 합니다.","“새로 장만한 값비싼 비단” -> “화폐”라는 의미입니다.","(敝는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1744/"},"膜":{"id":1733,"char":"膜","hun":"막 막","meaning":"“막 막”. 얇은 막, 점막","on":"マク","kun":"","explanation":["膜 = 月 + 莫。","(의미부) 「月」는 “신체의 일부”를 뜻합니다.","(소리부 겸 의미부) 莫는 여기서는 「幕」(マク)가 축약된 것으로, “장막”을 뜻합니다.","膜는 “신체(月)를 구성하는 얇은 막(幕)” -> “막, 점막”이라는 뜻의 글자입니다.","(莫->幕는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1745/"},"扇":{"id":1734,"char":"扇","hun":"부채 선","meaning":"“부채 선”. 부채","on":"セン","kun":"おうぎ","explanation":["扇 = 戸 + 羽。","「戸」는 “집, 문, 출입구”를 뜻합니다.","「羽」는 “날개”를 뜻합니다.","문을 열고 닫거나 날개를 펄럭이면 바람이 일어나게 됩니다.","扇는 “문을 여닫고(戸) 날개를 펄럭이듯(羽) 바람을 일으키는 부채” -> “부채”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1746/"},"腸":{"id":1735,"char":"腸","hun":"창자 장","meaning":"“창자 장”. 창자","on":"チョウ","kun":"","explanation":["腸 = 月 + 昜。","「月」는 “신체의 일부”를 뜻합니다.","「昜」는 “햇살이 내리쬐는 모습”을 그린 글자입니다.","腸는 “영양분을 온 몸에 퍼뜨리는(昜) 신체기관(月)” -> “창자”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1747/"},"槽":{"id":1736,"char":"槽","hun":"구유 조","meaning":"“구유 조”. 통, 구유","on":"ソウ","kun":"","explanation":["槽 = 木 + 曹。","(의미부) 「木」는 “나무”를 뜻합니다.","(소리부) 曹(ソウ)는 여기서는 소리부의 역할만 하고 있습니다(1559.「遭」 모양 해설 참조).","槽는 “나무(木)로 만든 통” -> “통, 구유”라는 뜻의 글자입니다(曹는 소리부)."],"sourceUrl":"https://nihongokanji.com/1748/"},"慈":{"id":1737,"char":"慈","hun":"사랑 자","meaning":"“사랑 자”. 자애, 자비","on":"ジ","kun":"いつく(しむ)","explanation":["慈 = 兹 + 心。","(소리부 겸 의미부) 「兹」(ジ)는 “무성하다”라는 뜻입니다.","(의미부) 「心」는 “마음”을 뜻합니다.","慈는 “만인에게 베푸는(兹) 자비로운 마음(心)” -> “자애, 자비”라는 뜻의 글자입니다.","(兹는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1749/"},"伐":{"id":1738,"char":"伐","hun":"칠 벌","meaning":"“칠 벌”. 치다, 정벌하다, 토벌하다","on":"バツ","kun":"","explanation":["伐 = 亻 + 戈。","「亻」는 “사람”을 뜻합니다.","「戈」는 “창”을 뜻합니다.","伐는 “창(戈)을 들고 적을 정벌하러 나서다(亻)” -> “치다, 정벌하다, 토벌하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1750/"},"漬":{"id":1739,"char":"漬","hun":"담글 지","meaning":"“담글 지”. 담그다, 담궈지다","on":"","kun":"つ(ける)、つ(かる)","explanation":["漬 = 氵 + 責。","「氵」는 “물”을 뜻합니다.","「貝」는 “조개”를 뜻합니다.","龶는 여기서는 “(조개와 함께 무친) 양념”을 그린 모양자입니다.","漬는 “소금물(氵)에 조개(貝)와 양념(龶)을 담가 젓갈을 만들다” -> “담그다, 담궈지다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1751/"},"糾":{"id":1740,"char":"糾","hun":"얽힐 규","meaning":"“얽힐 규”. 얽히다, 꼬이다","on":"キュウ","kun":"","explanation":["糾 = 糸 + 丩。","「糸」는 “실”을 뜻합니다.","「丩」는 “얽히다”라는 뜻입니다.","糾는 “실(糸)이 얽히다(丩)” -> “얽히다, 꼬이다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1752/"},"墳":{"id":1741,"char":"墳","hun":"무덤 분","meaning":"“무덤 분”. 무덤","on":"フン","kun":"","explanation":["墳 = 土 + 賁。","(의미부) 「土」는 “흙”을 뜻합니다.","(소리부) 賁는 여기서는 「噴」(フン)이 축약된 것으로, 소리부의 역할만 하고 있습니다.","墳는 “흙(土)으로 덮인 무덤” -> “무덤”이라는 뜻의 글자입니다(賁->噴는 소리부)."],"sourceUrl":"https://nihongokanji.com/1753/"},"坪":{"id":1742,"char":"坪","hun":"들 평","meaning":"“들 평”. 평(토지, 면적의 단위)","on":"","kun":"つぼ","explanation":["坪 = 土 + 平。","「土」는 “땅”을 뜻합니다.","「平」는 “평평하다”라는 뜻입니다.","坪는 “평평한(平) 땅(土)” -> “평(토지, 면적의 단위)”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1754/"},"紺":{"id":1743,"char":"紺","hun":"감색 감","meaning":"“감색 감”. 감색/암청색","on":"コン","kun":"","explanation":["紺 = 糸 + 甘。","(의미부) 「糸」는 “실”을 뜻합니다.","(소리부) 「甘」(カン)은 여기서는 소리부(カン -> コン)의 역할만 하고 있습니다.","紺는 “암청색으로 염색한 실(糸)” -> “감색, 암청색”이라는 뜻의 글자입니다(甘는 소리부)."],"sourceUrl":"https://nihongokanji.com/1755/"},"慌":{"id":1744,"char":"慌","hun":"어리둥절 황","meaning":"“어리둥절 황”. 당황하다, 허둥대다","on":"コウ","kun":"あわ(てる)、あわ(ただしい)","explanation":["慌 = 忄 + 荒。","(의미부) 「忄」는 “마음”을 뜻합니다.","(소리부 겸 의미부) 「荒」(コウ)는 “거칠다, 황폐하다”라는 뜻입니다.","慌는 “마음(忄)이 어수선하다(荒)” -> “당황하다, 허둥대다”라는 뜻의 글자입니다.","(荒는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1756/"},"娯":{"id":1745,"char":"娯","hun":"즐거워할 오","meaning":"“즐거워할 오”. 즐기다, 오락","on":"ゴ","kun":"","explanation":["娯 = 女 + 呉。","(의미부) 「女」는 “여자”를 뜻합니다.","(소리부 겸 의미부) 「呉」(ゴ)는 “머리가 기울어진 사람”을 그린 글자입니다.","娯는 “여자(女)를 옆에 끼고(呉) 유흥을 즐기다” -> “즐기다, 오락”이라는 뜻의 글자입니다.","(呉는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1757/"},"舌":{"id":1746,"char":"舌","hun":"혀 설","meaning":"“혀 설”. 혀","on":"ゼツ","kun":"した","explanation":["舌 = 千 + 口。","千는 여기서는 “뱀의 혓바닥”를 그린 모양자입니다.","口는 여기서는 “뱀의 머리”를 그린 모양자입니다.","舌는 “뱀이 혓바닥(千)을 내밀고 있는 모습”을 본따 그린 상형문자입니다.","“뱀의 혀” -> “혀”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/1758/"},"羅":{"id":1747,"char":"羅","hun":"벌일 라","meaning":"“벌일 라”. 그물, 나열하다","on":"ラ","kun":"","explanation":["羅 = 罒 + 糸 + 隹。","「罒」는 “그물”을 뜻합니다.","「糸」는 “실”을 뜻합니다.","「隹」는 “새”를 뜻합니다.","羅는 “새(隹)를 잡기 위해 그물(罒)을 펼치고 밧줄(糸)을 걸다” -> “그물, 늘어놓다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1759/"},"峡":{"id":1748,"char":"峡","hun":"골짜기 협","meaning":"“골짜기 협”. 골짜기, 협곡","on":"キョウ","kun":"","explanation":["峡 = 山 + 夹。","(의미부) 「山」는 “산”을 뜻합니다.","(소리부 겸 의미부) 「夹」(キョウ)는 “끼다, 끼이다”라는 뜻입니다.","峡는 “산맥(山) 사이에 낀(夹) 골짜기” -> “골짜기, 협곡”이라는 뜻의 글자입니다.","(夹는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1760/"},"俸":{"id":1749,"char":"俸","hun":"녹 봉","meaning":"“녹 봉”. 봉급, 급료","on":"ホウ","kun":"","explanation":["俸 = 亻 + 奉。","(의미부) 「亻」는 “사람”을 뜻합니다.","(소리부 겸 의미부) 「奉」(ホウ)는 “받들다, 섬기다”라는 뜻입니다.","俸는 “시중드는(奉) 시종(亻)에게 주는 급료” -> “봉급, 급료”라는 뜻의 글자입니다.","(奉는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1761/"},"厘":{"id":1750,"char":"厘","hun":"다스릴 리","meaning":"“다스릴 리”. 매우 작은 수","on":"リン","kun":"","explanation":["厘 = 厂 + 里。","(의미부) 「厂」는 “기슭, 절벽”을 뜻합니다.","(소리부 겸 의미부) 「里」(リ)는 “마을”을 뜻합니다.","厘는 “기슭(厂) 아래의 작은 마을(里)” -> “작다, 매우 작은 수”라는 뜻의 글자입니다.","(里는 소리부(リ -> リン)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1762/"},"峰":{"id":1751,"char":"峰","hun":"봉우리 봉","meaning":"“봉우리 봉”. 산봉우리","on":"ホウ","kun":"みね","explanation":["峰 = 山 + 丰 + 夂。","「山」는 “산”을 뜻합니다.","丰는 여기서는 “산길”을 그린 모양자입니다.","「夂」는 “발”을 뜻합니다.","峰는 “산(山)에 난 길(丰)을 따라 정상에 오르다(夂)” -> “산봉우리”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1763/"},"醸":{"id":1752,"char":"醸","hun":"술 빚을 양","meaning":"“술 빚을 양”. 양조하다, 빚다","on":"ジョウ","kun":"かも(す)","explanation":["醸 = 酉 + 㐮。","(의미부) 「酉」는 “술”을 뜻합니다.","(소리부 겸 의미부) 「㐮」(ジョウ)는 “예복, 상복”을 뜻합니다.","醸는 “작업복(㐮)을 입고 술(酉)을 빚다” -> “양조하다, 빚다”라는 뜻의 글자입니다.","(㐮는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1764/"},"弔":{"id":1753,"char":"弔","hun":"조상할 조","meaning":"“조상할 조”. 조문하다, 위로하다","on":"チョウ","kun":"とむら(う)","explanation":["弔는 “활(「弓」)을 등에 멘(丨) 사람”을 그린 글자입니다.","옛날에는 조문을 갈 때, 산짐승의 습격을 막기 위해 활을 들고 갔다고 합니다.","“활을 들고 산을 넘어 조문을 가다” -> “조문하다, 위로하다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/1765/"},"乙":{"id":1754,"char":"乙","hun":"새 을","meaning":"“새 을”. 을(‘갑을병’의 ‘을’)","on":"オツ","kun":"","explanation":["乙는 본래 “굽이쳐 흐르는 시냇물”을 그린 글자입니다.","그러나 지금은 단순히 “갑을병”의 “을”을 뜻하는 글자로 쓰이고 있습니다.","즉, 乙의 모양과 의미 사이에는 아무런 관계도 없습니다."],"sourceUrl":"https://nihongokanji.com/1766/"},"汁":{"id":1755,"char":"汁","hun":"즙 즙","meaning":"“즙 즙”. 즙, 액체","on":"ジュウ","kun":"しる","explanation":["汁 = 氵 + 十。","(의미부) 「氵」는 “물”을 뜻합니다.","(소리부 겸 의미부) 「十」(ジュウ)는 여기서는 “10” -> “많다”라는 뜻으로 쓰인 것입니다.","汁는 “즙(氵)이 많이(十) 나오다” -> “즙, 액체”라는 뜻의 글자입니다.","(十는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1767/"},"尼":{"id":1756,"char":"尼","hun":"여승 니","meaning":"“여승 니”. 비구니","on":"ニ","kun":"あま","explanation":["尼 = 尸 + 匕。","「尸」는 “집, 지붕”을 뜻합니다.","匕는 여기서는 “앉아있는 사람”을 그린 모양자입니다.","尼는 “절(尸)에 앉아서(匕) 불공을 드리는 비구니” -> “비구니”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1768/"},"遍":{"id":1757,"char":"遍","hun":"두루 편","meaning":"“두루 편”. 두루, 모든, 보편","on":"ヘン","kun":"","explanation":["遍 = ⻌ + 扁。","(의미부) 「⻌」는 “길”을 뜻합니다.","(소리부 겸 의미부) 「扁」(ヘン)은 “집 안의 책”을 뜻합니다.","遍는 “여러 곳을 두루(⻌) 찾아다니며 다양한 책(扁)을 읽다” -> “두루, 모든, 보편”이라는 뜻의 글자입니다.","(扁는 소리부도 겸함)","참고)","1413.「偏」 모양 설명과 함께 공부하시면 더 쉽게 구분·기억하실 수 있습니다."],"sourceUrl":"https://nihongokanji.com/1769/"},"衡":{"id":1758,"char":"衡","hun":"저울대 형","meaning":"“저울대 형”. 저울, 균형","on":"コウ","kun":"","explanation":["衡 = 行 + 角 + 大。","(소리부 겸 의미부) 「行」(コウ)는 본래 “사거리”를 그린 글자입니다(링크 참조).","(의미부) 「角」는 “뿔”을 뜻합니다.","(의미부) 「大」는 본래 “사람”을 그린 글자입니다.","衡는 “길(行) 한가운데서 날뛰는 소의 뿔(角)을 잡고 버티는 사람(大)”이라는 뜻입니다.","“소와 사람이 팽팽하게 맞서다” -> “균형, 저울”이라는 의미입니다.","(行는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1770/"},"薫":{"id":1759,"char":"薫","hun":"향초 훈","meaning":"“향초 훈”. 향기, 향을 내다","on":"クン","kun":"かお(る)","explanation":["薫 = 艹 + 重 + 灬。","「艹」는 “풀”을 뜻합니다.","「重」는 “무겁다, 겹치다”라는 뜻입니다.","「灬」는 “불”을 뜻합니다.","薫는 “약초(艹)를 겹쳐 쌓아놓고(重) 태워서(灬) 향을 내다” -> “향기, 향을 내다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1771/"},"猟":{"id":1760,"char":"猟","hun":"사냥 렵","meaning":"“사냥 렵”. 사냥하다","on":"リョウ","kun":"","explanation":["猟 = 犭 + 鼡。","「犭」는 “개”를 뜻합니다.","鼡는 “말갈기와 말안장”을 그린 모양자입니다.","猟는 “말을 타고(鼡) 사냥개(犭)를 몰며 사냥을 하다” -> “사냥하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1772/"},"羊":{"id":1761,"char":"羊","hun":"양 양","meaning":"“양 양”. 양","on":"ヨウ","kun":"ひつじ","explanation":["羊는 “양의 머리”를 그린 상형문자입니다."],"sourceUrl":"https://nihongokanji.com/1773/"},"款":{"id":1762,"char":"款","hun":"항목 관","meaning":"“항목 관”. 약관, 조항, 항목","on":"カン","kun":"","explanation":["款 = 士 + 示 + 欠。","「士」는 “선비”를 뜻합니다.","「示」는 “보이다, 나타내다”라는 뜻입니다.","「欠」는 “입을 벌린 모습, 입으로 하는 동작”을 뜻합니다.","款는 “선비(士)가 계약서를 보여주며(示) 조항을 읽어내리다(欠)” -> “약관, 조항, 항목”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1774/"},"閲":{"id":1763,"char":"閲","hun":"볼 열","meaning":"“볼 열”. 열람하다, 검열하다","on":"エツ","kun":"","explanation":["閲 = 門 + 兑。","「門」는 “문”을 뜻합니다.","「兑」는 “날카로운 눈을 한 사람”을 뜻합니다.","閲는 “문(門) 앞에서 날카로운 눈으로(兑) 소지품을 검열하다” -> “열람하다, 검열하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1775/"},"偵":{"id":1764,"char":"偵","hun":"염탐할 정","meaning":"“염탐할 정”. 염탐하다, 정찰하다","on":"テイ","kun":"","explanation":["偵 = 亻 + 貞。","(의미부) 「亻」는 “사람”을 뜻합니다.","(소리부 겸 의미부) 「貞」(テイ)는 본래 “뇌물을 거부하는 모습”을 그린 글자입니다(링크 참조).","偵는 “관리가 뇌물을 받지 않는지(貞) 감시하는 사람(亻)” -> “염탐하다, 정찰하다”라는 뜻의 글자입니다.","(貞는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1776/"},"喝":{"id":1765,"char":"喝","hun":"꾸짖을 갈","meaning":"“꾸짖을 갈”. 꾸짖다, 으르다","on":"カツ","kun":"","explanation":["喝 = 口 + 曷。","(의미부) 「口」는 “입”을 뜻합니다.","(소리부) 「曷」(カツ)는 “허리를 굽혀 구걸하는 모습”을 그린 글자입니다.","喝는 “굽신거리며 용서를 비는 사람(曷)에게 소리를 지르다(口)” -> “꾸짖다, 으르다”라는 뜻의 글자입니다.","(曷는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1777/"},"敢":{"id":1766,"char":"敢","hun":"감히 감","meaning":"“감히 감”. 감히, 구태여, 과감한","on":"カン","kun":"","explanation":["敢 = 丅 + 耳 + 攵。","「攵」는 “때리다, 치다”라는 뜻입니다.","「耳」는 “귀”를 뜻합니다.","丅는 여기서는 “귀에 박아넣은 칼”을 그린 모양자입니다.","敢는 “맹수의 귀(耳)에 칼을 박아넣고(丅) 때려잡다(攵)” -> “용감하다, 과감하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1778/"},"胎":{"id":1767,"char":"胎","hun":"아이 밸 태","meaning":"“아이 밸 태”. 아이를 배다, 자궁","on":"タイ","kun":"","explanation":["胎 = 月 + 台。","(의미부) 「月」는 “신체의 일부”를 뜻합니다.","(소리부 겸 의미부) 「台」(タイ)는 “받침대, 토대”를 뜻합니다.","胎는 “아기가 자라나는 토대(台)가 되는 신체 기관(月)” -> “자궁, 아이를 배다”라는 뜻의 글자입니다.","(台는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1779/"},"酵":{"id":1768,"char":"酵","hun":"삭힐 효","meaning":"“삭힐 효”. 발효","on":"コウ","kun":"","explanation":["酵 = 酉 + 孝。","(의미부) 「酉」는 “술”을 뜻합니다.","(소리부) 「孝」(コウ)는 여기서는 소리부의 역할만 하고 있습니다.","酵는 “술(酉)을 발효시키다” -> “발효”라는 뜻의 글자입니다(孝는 소리부)."],"sourceUrl":"https://nihongokanji.com/1780/"},"憤":{"id":1769,"char":"憤","hun":"분할 분","meaning":"“분할 분”. 분개하다, 분노","on":"フン","kun":"いきどお(る)","explanation":["憤 = 忄 + 賁。","(의미부) 「忄」는 “마음”을 뜻합니다.","(소리부 겸 의미부) 賁는 여기서는 「噴」(フン)이 축약된 것으로, “내뿜다”라는 뜻입니다.","憤는 “마음속(忄)의 분노를 발산하다(噴)” -> “분개하다, 분노”라는 뜻의 글자입니다.","(賁->噴는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1781/"},"豚":{"id":1770,"char":"豚","hun":"돼지 돈","meaning":"“돼지 돈”. 돼지","on":"トン","kun":"ぶた","explanation":["豚 = 月 + 豕。","「月」는 “고기”를 뜻합니다.","「豕」는 “돼지”를 뜻합니다.","豚는 “돼지(豕) 고기(月)” -> “돼지”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1782/"},"遮":{"id":1771,"char":"遮","hun":"가릴 차","meaning":"“가릴 차”. 가로막다, 차단하다","on":"シャ","kun":"さえぎ(る)","explanation":["遮 = ⻌ + 庶。","(의미부) 「⻌」는 “길”을 뜻합니다.","(소리부 겸 의미부) 「庶」(ショ)는 “서민, 대중”을 뜻합니다.","遮는 “서민(庶)이 귀족의 길(⻌)을 가로막다” -> “가로막다, 차단하다”라는 뜻의 글자입니다.","(庶는 소리부(ショ -> シャ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1783/"},"扉":{"id":1772,"char":"扉","hun":"사립문 비","meaning":"“사립문 비”. 문짝, 문","on":"ヒ","kun":"とびら","explanation":["扉 = 戸 + 非。","(의미부) 「戸」는 “문”을 뜻합니다.","(소리부 겸 의미부) 「非」(ヒ)는 여기서는 “사립문”을 본따 그린 모양자입니다. 아래 그림을 참조해 주세요.","扉는 “사립문(非) 형태의 문(戸)” -> “문, 문짝”이라는 뜻의 글자입니다.","(非는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1784/"},"硫":{"id":1773,"char":"硫","hun":"유황 류","meaning":"“유황 류”. 황(sulphur)","on":"リュウ","kun":"","explanation":["硫 = 石 + 㐬。","(의미부) 「石」는 “돌”을 뜻합니다.","(소리부 겸 의미부) 㐬는 여기서는 「流」(リュウ)가 축약된 것으로, “흐르다”라는 뜻입니다.","硫는 “돌(石)이 황산에 녹아 흘러내리다(流)” -> “황”이라는 뜻의 글자입니다.","(㐬->流는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1785/"},"赦":{"id":1774,"char":"赦","hun":"용서할 사","meaning":"“용서할 사”. 용서하다","on":"シャ","kun":"","explanation":["赦 = 赤 + 攵。","「赤」는 “빨강”을 뜻합니다.","「攵」는 “때리다, 치다”라는 뜻입니다.","赦는 “아이의 엉덩이가 빨개지도록(赤) 때리고(攵) 용서해주다” -> “용서하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1786/"},"窃":{"id":1775,"char":"窃","hun":"훔칠 절","meaning":"“훔칠 절”. 훔치다, 절도","on":"セツ","kun":"","explanation":["窃 = 穴 + 切。","(의미부) 「穴」는 “구멍”을 뜻합니다.","(소리부 겸 의미부) 「切」(セツ)는 “자르다”라는 뜻입니다.","窃는 “담벼락에 구멍(穴)을 뚫고(切) 들어가 도둑질하다” -> “훔치다”라는 뜻의 글자입니다.","(切는 소리부도 겸함)."],"sourceUrl":"https://nihongokanji.com/1787/"},"泡":{"id":1776,"char":"泡","hun":"거품 포","meaning":"“거품 포”. 거품","on":"ホウ","kun":"あわ","explanation":["泡 = 氵 + 包。","(의미부) 「氵」는 “물”을 뜻합니다.","(소리부 겸 의미부) 「包」(ホウ)는 “감싸다”라는 뜻입니다.","泡는 “안쪽을 둥글게 감싼(包) 물거품(氵)” -> “거품”이라는 뜻의 글자입니다.","(包는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1788/"},"又":{"id":1777,"char":"又","hun":"또 우","meaning":"“또 우”. 또, 다시, 재차","on":"","kun":"また","explanation":["又는 “엄지와 검지로 무언가를 집어드는 손”의 모습을 그린 상형문자입니다.","“손으로 계속해서 음식을 집어먹다” -> “또, 다시, 재차”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/1789/"},"慨":{"id":1778,"char":"慨","hun":"슬퍼할 개","meaning":"“슬퍼할 개”. 개탄하다, 슬퍼하다","on":"ガイ","kun":"","explanation":["慨 = 忄 + 既。","「忄」는 “마음”을 뜻합니다.","「既」는 본래 “식사를 이미 다 끝마친 사람”을 그린 글자입니다(링크 참조).","慨는 “자신이 오기도 전에 먼저 밥을 다 먹어버린 모습(既)에 분개하다(忄)” -> “개탄하다, 슬퍼하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1790/"},"紡":{"id":1779,"char":"紡","hun":"길쌈 방","meaning":"“길쌈 방”. 실을 잣다","on":"ボウ","kun":"つむ(ぐ)","explanation":["紡 = 糸 + 方。","(의미부) 「糸」는 “실”을 뜻합니다.","(소리부) 「方」(ホウ)는 여기서는 소리부(ホウ -> ボウ)의 역할만 하고 있습니다.","紡는 “실(糸)” -> “실을 잣다”라는 뜻의 글자입니다(方는 소리부)."],"sourceUrl":"https://nihongokanji.com/1791/"},"恨":{"id":1780,"char":"恨","hun":"한 한","meaning":"“한 한”. 원망하다, 한","on":"コン","kun":"うら(む)、うら(めしい)","explanation":["恨 = 忄 + 艮。","(의미부) 「忄」는 “마음”을 뜻합니다.","(소리부 겸 의미부) 「艮」(コン)은 “고개를 떨군 천민”을 뜻합니다.","恨는 “노예로 태어난 천민(艮)의 한이 서린 마음(忄)” -> “원망하다, 한”이라는 뜻의 글자입니다.","(艮는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1792/"},"肪":{"id":1781,"char":"肪","hun":"살찔 방","meaning":"“살찔 방”. 기름, 지방","on":"ボウ","kun":"","explanation":["肪 = 月 + 方。","(의미부) 「月」는 “고기”를 뜻합니다.","(소리부) 「方」(ホウ)는 여기서는 소리부(ホウ -> ボウ)의 역할만 하고 있습니다.","肪는 “돼지고기(月)의 비계” -> “기름, 지방”이라는 뜻의 글자입니다(方는 소리부)."],"sourceUrl":"https://nihongokanji.com/1793/"},"扶":{"id":1782,"char":"扶","hun":"도울 부","meaning":"“도울 부”. 돕다, 조력하다","on":"フ","kun":"","explanation":["扶 = 扌 + 夫。","(의미부) 「扌」는 “손”을 뜻합니다.","(소리부 겸 의미부) 「夫」(フ)는 “남편, 성인 남성”을 뜻합니다.","扶는 “도움의 손길(扌)을 내미는 사내(夫)” -> “돕다, 조력하다”라는 뜻의 글자입니다.","(夫는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1794/"},"戯":{"id":1783,"char":"戯","hun":"놀 희","meaning":"“놀 희”. 놀다, 장난치다, 희롱하다","on":"ギ","kun":"たわむ(れる)","explanation":["戯 = 虚 + 戈。","「虚」는 “텅 비다, 없다”라는 뜻입니다.","「戈」는 “창”을 뜻합니다.","戯는 “장난감(虚) 창(戈)을 가지고 놀다” -> “놀다, 장난치다, 희롱하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1795/"},"忌":{"id":1784,"char":"忌","hun":"꺼릴 기","meaning":"“꺼릴 기”. 꺼리다, 싫어하다","on":"キ","kun":"い(む)、い(まわしい)","explanation":["忌 = 己 + 心。","(소리부 겸 의미부) 「己」(キ)는 “자신”을 뜻합니다.","(의미부) 「心」는 “마음”을 뜻합니다.","忌는 “남을 싫어하는 마음(心)은 모두 자신(己)에게서 비롯되는 것이다” -> “꺼리다, 싫어하다”라는 뜻의 글자입니다.","(己는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1796/"},"濁":{"id":1785,"char":"濁","hun":"흐릴 탁","meaning":"“흐릴 탁”. 탁하다, 흐리다","on":"ダク","kun":"にご(る)、にご(す)","explanation":["濁 = 氵 + 罒 + 勹 + 虫。","「氵」는 “물”을 뜻합니다.","「虫」는 “벌레”를 뜻합니다.","罒는 여기서는 “(벌레의) 눈”을 그린 모양자입니다.","勹는 여기서는 “(벌레의) 긴 몸통”을 그린 모양자입니다.","濁는 “눈이 커다랗고(罒) 몸이 긴(勹) 벌레(虫)가 득시글거리는 더러운 물(氵)” -> “탁하다, 흐리다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1797/"},"奔":{"id":1786,"char":"奔","hun":"달릴 분","meaning":"“달릴 분”. 빠르게 달리다","on":"ホン","kun":"","explanation":["奔는 “양 팔을 좌우로 휘두르며(大) 달리는(廾) 모습”을 그린 상형문자입니다."],"sourceUrl":"https://nihongokanji.com/1798/"},"斗":{"id":1787,"char":"斗","hun":"말 두","meaning":"“말 두”. ~말(술/곡물을 세는 단위)","on":"ト","kun":"","explanation":["斗는 “(곡식/술 등을 퍼담는) 국자”를 본따 그린 상형문자입니다.","“곡식/술을 퍼담는 국자” -> “~말(술/곡물을 세는 단위)”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/1799/"},"迅":{"id":1788,"char":"迅","hun":"빠를 신","meaning":"“빠를 신”. 빠르다","on":"ジン","kun":"","explanation":["迅 = ⻌ + 卂。","「⻌」는 “길”을 뜻합니다.","卂는 「飛」가 축약된 것으로, “빠르게 날다(飛)”라는 뜻입니다.","迅는 “빠른 속도로(卂) 길을 질주하다(⻌)” -> “빠르다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1800/"},"肖":{"id":1789,"char":"肖","hun":"닮을/같을 초","meaning":"“닮을/같을 초”. 닮다, 본뜨다","on":"ショウ","kun":"","explanation":["肖 = ⺌ + 月。","⺌는 「小」가 뒤집어진 것으로, “작다”라는 뜻입니다.","「月」는 “신체의 일부”를 뜻합니다.","肖는 “작은(小) 나 자신(月) = 나의 후손” -> “닮다, 같다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1801/"},"鉢":{"id":1790,"char":"鉢","hun":"바리때 발","meaning":"“바리때 발”. 바리때, 사발","on":"ハチ、ハツ","kun":"","explanation":["鉢 = 金 + 本。","「金」는 “쇠, 금속”을 뜻합니다.","「本」은 “근본”을 뜻합니다.","鉢는 “승려의 본분(本)을 지키는, 놋쇠(金)로 만든 바리때” -> “바리때, 사발”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1802/"},"朽":{"id":1791,"char":"朽","hun":"썩을 후","meaning":"“썩을 후”. 썩다","on":"キュウ","kun":"く(ちる)","explanation":["朽 = 木 + 丂。","「木」는 “나무”를 뜻합니다.","丂는 여기서는 “썩어 문드러진 나무토막”을 그린 모양자입니다.","朽는 “썩어 문드러진(丂) 나무토막(木)” -> “썩다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1803/"},"殻":{"id":1792,"char":"殻","hun":"껍질 각","meaning":"“껍질 각”. 껍질","on":"カク","kun":"から","explanation":["殻 = 穀 + 几。","(소리부 겸 의미부) 「穀」(コク)는 본래 “도리깨를 내리치는 모습”을 그린 글자입니다(링크 참조).","(의미부) 几는 여기서는 “등껍질”을 그린 모양자입니다.","殻는 穀에서 아래쪽의 禾만 几로 바꾼 글자입니다.","“세게 내리쳐도(穀) 깨지지 않는 단단한 등껍질(几)” -> “껍질”이라는 의미입니다.","(穀는 소리부(コク -> カク)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1804/"},"享":{"id":1793,"char":"享","hun":"누릴 향","meaning":"“누릴 향”. 누리다, 향유하다","on":"キョウ","kun":"","explanation":["「享」는 “모자(亠+口)를 쓴 아이(子)”를 그린 상형문자입니다.","“아이의 재롱을 즐기다” -> “누리다, 향유하다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/1805/"},"藩":{"id":1794,"char":"藩","hun":"울타리 번","meaning":"“울타리 번”. 울타리, 영지","on":"ハン","kun":"","explanation":["藩 = 艹 + 氵 + 番。","(의미부) 「艹」는 “풀”을 뜻합니다.","(의미부) 「氵」는 “물”을 뜻합니다.","(소리부 겸 의미부) 「番」(バン)은 본래 “밭에 찍힌 동물의 발자국”을 그린 글자입니다(링크 참조).","藩는 “산천초목(艹+氵)과 농사지을 밭(番)이 있는 영지” -> “영지, 울타리”라는 뜻의 글자입니다.","(番는 소리부(バン -> ハン)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1806/"},"沙":{"id":1795,"char":"沙","hun":"모래 사","meaning":"“모래 사”. 모래","on":"サ","kun":"","explanation":["沙는 「砂」에서 石만 氵로 바뀐 글자로, 본래 의미도 같습니다.","“바닷가(氵)의 모래(少->砂)” -> “모래”라는 의미입니다.","다만, 실제로 “모래”라는 뜻을 표현할 때는 「砂」가 쓰이고, 沙는 주로 본래 의미와는 별 관계 없는 관용어구나 범어의 음역 등에 쓰이는 글자입니다."],"sourceUrl":"https://nihongokanji.com/1807/"},"媒":{"id":1796,"char":"媒","hun":"중매 매","meaning":"“중매 매”. 중매하다","on":"バイ","kun":"","explanation":["媒 = 女 + 某。","「女」는 “여자”를 뜻합니다.","某는 여기서는 「謀」가 축약된 것으로, “모의하다, 계획하다”라는 뜻입니다.","媒는 “서로 모르는 남녀 사이의 결혼을 계획하고(謀) 이어주는 중매쟁이(女)” -> “중매하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1808/"},"鶏":{"id":1797,"char":"鶏","hun":"닭 계","meaning":"“닭 계”. 닭","on":"ケイ","kun":"にわとり","explanation":["鶏 = ⺤ + 夫 + 鳥。","「⺤」는 “손”을 뜻합니다.","「夫」는 “남편”을 뜻합니다.","「鳥」는 “새”를 뜻합니다.","鶏는 “손(⺤)으로 닭(鳥)의 모가지를 비틀어 잡는 남편(夫)” -> “닭”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1809/"},"禅":{"id":1798,"char":"禅","hun":"선 선","meaning":"“선 선”. 선종(불교의 종파)","on":"ゼン","kun":"","explanation":["禅 = 礻 + 単。","「礻」는 “신, 종교, 고대의 비석”을 뜻합니다.","「単」는 “단독, 홀로”라는 뜻입니다.","禅는 “홀로(単) 조용히 명상하며 진리를 구하는 종교(礻)” -> “선종”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1810/"},"嘱":{"id":1799,"char":"嘱","hun":"부탁할 촉","meaning":"“부탁할 촉”. 부탁하다","on":"ショク","kun":"","explanation":["嘱 = 口 + 属。","(의미부) 「口」는 “입”을 뜻합니다.","(소리부 겸 의미부) 「属」(ゾク)는 “속하다”라는 뜻입니다.","嘱는 “집단에 소속된(属) 내부자에게 청탁하다(口)” -> “부탁하다”라는 뜻의 글자입니다.","(属는 소리부(ゾク -> ショク)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1811/"},"胴":{"id":1800,"char":"胴","hun":"몸통 동","meaning":"“몸통 동”. 몸통","on":"ドウ","kun":"","explanation":["胴 = 月 + 同。","(의미부) 「月」는 “신체의 일부”를 뜻합니다.","(소리부) 「同」(ドウ)는 여기서는 소리부의 역할만 하고 있습니다.","胴는 “신체의 일부(月)” -> “몸통”이라는 뜻의 글자입니다(同는 소리부)."],"sourceUrl":"https://nihongokanji.com/1812/"},"迭":{"id":1801,"char":"迭","hun":"번갈아들 질","meaning":"“번갈아들 질”. 번갈아서","on":"テツ","kun":"","explanation":["迭 = ⻌ + 失。","(의미부) 「⻌」는 “길”을 뜻합니다.","(소리부 겸 의미부) 「失」(シツ)는 “잃다”라는 뜻입니다.","迭는 “길(⻌)을 잃고(失) 오락가락 헤메다” -> “왔다갔다” -> “번갈아서”라는 뜻의 글자입니다.","(失는 소리부(シツ -> テツ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1813/"},"挿":{"id":1802,"char":"挿","hun":"꽂을 삽","meaning":"“꽂을 삽”. 꽂다, 끼우다","on":"ソウ","kun":"さ(す)","explanation":["挿 = 扌 + 千 + 日。","「扌」는 “손”을 뜻합니다.","千는 여기서는 “열쇠”를 그린 모양자입니다.","日는 여기서는 臼가 변형된 것으로, “열쇠구멍”을 그린 모양자입니다.","挿는 “열쇠(千)를 열쇠구멍(日)에 꽂아넣다(扌)” -> “꽂다, 끼우다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1814/"},"嵐":{"id":1803,"char":"嵐","hun":"남기 람","meaning":"“남기 람”. 폭풍우","on":"","kun":"あらし","explanation":["嵐 = 山 + 風。","「山」는 “산”을 뜻합니다.","「風」는 “바람”을 뜻합니다.","嵐는 “산(山)에서 불어오는 강한 바람(風)” -> “폭풍우”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1815/"},"椎":{"id":1804,"char":"椎","hun":"등골 추","meaning":"“등골 추”. 척추","on":"ツイ","kun":"","explanation":["椎 = 木 + 隹。","「木」는 “나무”를 뜻합니다.","隹는 여기서는 “사람(亻)의 척추뼈(丰)”라는 뜻으로 쓰인 모양자입니다.","椎는 “나무기둥(木)처럼 사람의 몸을 지탱하는 척추뼈(隹)” -> “척추”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1816/"},"絹":{"id":1805,"char":"絹","hun":"비단 견","meaning":"“비단 견”. 비단","on":"ケン","kun":"きぬ","explanation":["絹 = 糸 + 肙。","「糸」는 “실”을 뜻합니다.","肙는 여기서는 “누에”를 그린 모양자입니다.","絹는 “누에(肙)가 자아낸 실(糸)” -> “비단”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1817/"},"陪":{"id":1806,"char":"陪","hun":"모실 배","meaning":"“모실 배”. 따르다, 모시다","on":"バイ","kun":"","explanation":["陪 = ⻖ + 咅。","(의미부) 「⻖」는 “언덕”을 뜻합니다.","(소리부) 「咅」(バイ)는 여기서는 소리부의 역할만 하고 있습니다.","陪는 “주인을 따라 언덕(⻖)을 오르다” -> “따르다, 모시다”라는 뜻의 글자입니다(咅는 소리부)."],"sourceUrl":"https://nihongokanji.com/1818/"},"剖":{"id":1807,"char":"剖","hun":"쪼갤 부","meaning":"“쪼갤 부”. 쪼개다","on":"ボウ","kun":"","explanation":["剖 = 咅 + 刂。","(소리부 겸 의미부) 咅는 여기서는 「部」(ブ)가 축약된 것으로, “부분, 부서”라는 뜻입니다.","(의미부) 「刂」는 “칼”을 뜻합니다.","剖는 “칼로 쪼개서(刂) 여러 부분(部)으로 나누다” -> “쪼개다”라는 뜻의 글자입니다.","(咅->部는 소리부(ブ -> ボウ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1819/"},"譜":{"id":1808,"char":"譜","hun":"족보 보","meaning":"“족보 보”. 족보, 악보, 기보 등","on":"フ","kun":"","explanation":["譜 = 言 + 普。","(의미부) 「言」는 “말하다”라는 뜻입니다.","(소리부 겸 의미부) 「普」(フ)는 “넓다, 보편적인”이라는 뜻입니다.","譜는 “넓고 광대한(普) 혈통 관계를 설명하는(言) 책” -> “족보” -> “악보, 기보”라는 뜻의 글자입니다.","(普는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1820/"},"悠":{"id":1809,"char":"悠","hun":"멀 유","meaning":"“멀 유”. 멀다, 아득하다, 끝이 없다","on":"ユウ","kun":"","explanation":["悠 = 攸 + 心。","攸는 여기서는 「修」가 축약된 것으로, “수행하다, 수양하다”라는 뜻입니다.","「心」는 “마음”을 뜻합니다.","悠는 “마음(心)의 수행(攸)에는 끝이 없다“ -> “멀다, 아득하다, 끝이 없다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1821/"},"淑":{"id":1810,"char":"淑","hun":"맑을 숙","meaning":"“맑을 숙”. 얌전하다, 착하다","on":"シュク","kun":"","explanation":["淑 = 氵 + 尗 + 又。","「氵」는 “물”을 뜻합니다.","「尗」는 “식물의 줄기와 뿌리”를 그린 글자입니다.","「又」는 “손”을 뜻합니다.","淑는 “화초(尗)를 정성스레 가꾸는(又) 여자의 맑은(氵) 심성” -> “얌전하다, 착하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1822/"},"帆":{"id":1811,"char":"帆","hun":"돛 범","meaning":"“돛 범”. 돛","on":"ハン","kun":"ほ","explanation":["帆 = 巾 + 凡。","(의미부) 「巾」는 “수건, 천”을 뜻합니다.","(소리부) 「凡」(ハン)은 여기서는 소리부의 역할만 하고 있습니다.","帆는 “바람을 받아 배를 가게 하는 천(巾)” -> “돛”이라는 뜻의 글자입니다(凡은 소리부)."],"sourceUrl":"https://nihongokanji.com/1823/"},"暁":{"id":1812,"char":"暁","hun":"새벽 효","meaning":"“새벽 효”. 새벽녘","on":"ギョウ","kun":"あかつき","explanation":["暁 = 日 + 尭。","(의미부) 「日」는 “태양”을 뜻합니다.","(소리부 겸 의미부) 尭는 여기서는 「焼」(ショウ)가 축약된 것으로, “불사르다, 태우다”라는 뜻입니다.","暁는 “하늘을 서서히 밝혀오는(焼) 새벽녘의 태양(日)” -> “새벽녘”이라는 뜻의 글자입니다.","(尭->焼는 소리부(ショウ -> ギョウ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1824/"},"傑":{"id":1813,"char":"傑","hun":"뛰어날 걸","meaning":"“뛰어날 걸”. 뛰어난, 걸출한","on":"ケツ","kun":"","explanation":["傑 = 亻 + 舛 + 木。","「亻」는 “사람”을 뜻합니다.","「舛」는 “두 발, 양발”을 뜻합니다.","「木」는 “나무”를 뜻합니다.","傑는 “나무(木) 위에 올라선(舛) 사람(亻)” -> “높이 올라서다” -> “뛰어난, 걸출한”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1825/"},"笛":{"id":1814,"char":"笛","hun":"피리 적","meaning":"“피리 적”. 피리","on":"テキ","kun":"ふえ","explanation":["笛 = 𥫗 + 由。","「𥫗」는 “대나무”를 뜻합니다.","「由」는 “유래, 연유”를 뜻합니다.","笛는 “대나무 피리(𥫗)에서 흘러나오는(由) 소리” -> “피리”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1826/"},"奴":{"id":1815,"char":"奴","hun":"종 노","meaning":"“종 노”. 종, 노예","on":"ド","kun":"","explanation":["奴 = 女 + 又。","「女」는 “여자”를 뜻합니다.","「又」는 “손”을 뜻합니다.","奴는 “여자(女) 노예를 손에(又) 넣다” -> “종, 노예”라는 뜻의 글자입니다.","참고) 奴는 503.「努」의 소리부이기도 합니다."],"sourceUrl":"https://nihongokanji.com/1827/"},"錠":{"id":1816,"char":"錠","hun":"덩이 정","meaning":"“덩이 정”. 자물쇠, ~정(약 등을 세는 단위)","on":"ジョウ","kun":"","explanation":["錠 = 金 + 定。","(의미부) 「金」는 “쇠, 금속”을 뜻합니다.","(소리부 겸 의미부) 「定」(ジョウ)는 “정하다”라는 뜻입니다.","錠는 “정해진(定) 열쇠로만 풀 수 있는 금속 자물쇠(金)” -> “자물쇠”라는 뜻의 글자입니다.","(定는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1828/"},"拳":{"id":1817,"char":"拳","hun":"주먹 권","meaning":"“주먹 권”. 주먹","on":"ケン","kun":"こぶし","explanation":["拳 = 龹 + 手。","(소리부 겸 의미부) 龹는 여기서는 「巻」(カン)이 축약된 것으로, “돌돌 말다”라는 뜻입니다.","(의미부) 「手」는 “손”을 뜻합니다.","拳는 “손(手)을 말아쥐다(巻)” -> “주먹”이라는 뜻의 글자입니다.","(龹->巻는 소리부(カン -> ケン)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1829/"},"遷":{"id":1818,"char":"遷","hun":"옮길 천","meaning":"“옮길 천”. 옮기다, 옮겨 가다","on":"セン","kun":"","explanation":["遷 = ⻌ + 覀 + 大 + 己。","「⻌」는 “길”을 뜻합니다.","「覀」는 “덮다”라는 뜻입니다.","「大」는 “크다”라는 뜻입니다.","「己」는 “나, 자신”을 뜻합니다.","遷는 “커다란 이삿짐(大)을 머리에 짊어지고(覀) 길을 걷는(⻌) 사람(己)” -> “옮기다, 옮겨 가다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1830/"},"拙":{"id":1819,"char":"拙","hun":"옹졸할 졸","meaning":"“옹졸할 졸”. 서투른, 졸렬한","on":"セツ","kun":"つたな(い)","explanation":["拙 = 扌 + 出。","(의미부) 「扌」는 “손”을 뜻합니다.","(소리부 겸 의미부) 「出」(シュツ)는 “나가다, 내보내다”라는 뜻입니다.","拙는 “작업이 서툴러 손(扌)이 자꾸 엇나가다(出)” -> “서툴다, 졸렬하다”라는 뜻의 글자입니다.","(出는 소리부(シュツ -> セツ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1831/"},"侍":{"id":1820,"char":"侍","hun":"모실 시","meaning":"“모실 시”. 모시다, 시중들다","on":"ジ","kun":"さむらい","explanation":["侍 = 亻 + 寺。","(의미부) 「亻」는 “사람”을 뜻합니다.","(소리부 겸 의미부) 「寺」(ジ)는 “절, 사찰”을 뜻합니다.","侍는 “절(寺)에서 잡일을 하는 시동(亻)” -> “모시다, 시중들다”라는 뜻의 글자입니다.","(寺는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1832/"},"尺":{"id":1821,"char":"尺","hun":"자 척","meaning":"“자 척”. 척(길이의 단위), 길이, 척도","on":"シャク","kun":"","explanation":["尺는 본래 “사람이 걷는 모습”을 두 다리를 강조하여 그린 글자입니다.","“보폭만큼의 길이(약 23~30cm)” -> “척(약 30cm), 길이, 척도”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/1833/"},"峠":{"id":1822,"char":"峠","hun":"고개 상","meaning":"“고개 상”. 고개(일본에서 만들어진 한자)","on":"","kun":"とうげ","explanation":["峠 = 山 + 上 + 下。","「山」는 “산”을 뜻합니다.","「上」는 “위”를 뜻합니다.","「下」는 “아래”를 뜻합니다.","峠는 “고개(山)를 오르고(上) 내려가다(下)” -> “고개”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1834/"},"篤":{"id":1823,"char":"篤","hun":"도타울 독","meaning":"“도타울 독”. 진지한, 독실한, 착실한","on":"トク","kun":"","explanation":["篤 = 𥫗 + 馬。","「𥫗」는 “대나무”를 뜻합니다.","「馬」는 “말”을 뜻합니다.","篤는 “대나무(𥫗) 말(馬)” -> “죽마”라는 뜻입니다.","“죽마를 타고 조심조심 걷다” -> “진지한, 독실한, 착실한”이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/1835/"},"渇":{"id":1824,"char":"渇","hun":"목마를 갈","meaning":"“목마를 갈”. 목마른, 간절한","on":"カツ","kun":"かわ(く)","explanation":["渇 = 氵 + 曷。","(의미부) 「氵」는 “물”을 뜻합니다.","(소리부 겸 의미부) 「曷」(カツ)는 “허리를 굽혀 구걸하는 모습”을 그린 글자입니다.","渇는 “물(氵)이 마시고 싶어 굽신거리며 구걸하다(曷)” -> “목마른, 간절한”이라는 뜻의 글자입니다.","(曷는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1836/"},"叔":{"id":1825,"char":"叔","hun":"아저씨 숙","meaning":"“아저씨 숙”. 아저씨, 숙부","on":"シュク","kun":"","explanation":["叔 = 尗 + 又。","「尗」는 “식물의 줄기와 뿌리”를 그린 글자입니다.","「又」는 “손”을 뜻합니다.","叔는 본래 “줄줄이 뽑혀 나오는(又) 땅속의 감자(尗)”를 표현한 글자입니다.","“줄줄이 이어져 나오는 감자”를 “여러 명의 형제”로 비유한 것입니다.","“여러 명의 형제들” -> “숙부, 아저씨”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/1837/"},"雌":{"id":1826,"char":"雌","hun":"암컷 자","meaning":"“암컷 자”. 암컷, 약하다","on":"シ","kun":"め、めす","explanation":["雌 = 止 + 匕 + 隹。","(소리부) 「止」(シ)는 여기서는 소리부의 역할만 하고 있습니다.","(의미부) 匕는 여기서는 단순히 장식으로 추가된 것입니다.","(의미부) 「隹」는 “새”를 뜻합니다.","雌는 본래 “암컷 새(隹)”라는 뜻으로 만들어진 글자입니다.","“암컷 새” -> “암컷” -> “약하다”라는 의미입니다(止는 소리부)."],"sourceUrl":"https://nihongokanji.com/1838/"},"堪":{"id":1827,"char":"堪","hun":"견딜 감","meaning":"“견딜 감”. 견디다, 참다","on":"カン","kun":"た(える)","explanation":["堪 = 土 + 甚。","(의미부) 「土」는 “흙”을 뜻합니다.","(소리부 겸 의미부) 甚는 여기서는 「勘」(カン)이 축약된 것으로, “헤아리다, 가늠하다”라는 뜻입니다.","堪는 “산속에 유배되어 흙(土)을 씹고 버티며 석방될 날을 헤아리다(勘)” -> “참다, 견디다”라는 뜻의 글자입니다.","(甚->勘는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1839/"},"叙":{"id":1828,"char":"叙","hun":"펼/차례 서","meaning":"“펼/차례 서”. 서술하다, 차례","on":"ジョ","kun":"","explanation":["叙 = 余 + 又。","(소리부 겸 의미부) 「余」(ヨ)는 본래 “잎이 풍성한 나무”를 그린 글자입니다.","(의미부) 「又」는 “손”을 뜻합니다.","叙는 “손(又)으로 나뭇잎(余)을 하나하나 떼다” -> “차례대로” -> “서술하다”라는 뜻의 글자입니다.","(余는 소리부(ヨ -> ジョ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1840/"},"酢":{"id":1829,"char":"酢","hun":"신맛 초","meaning":"“신맛 초”. 식초, 초산","on":"サク","kun":"す","explanation":["酢 = 酉 + 乍。","(의미부) 「酉」는 “술”을 뜻합니다.","(소리부) 「乍」(サク)는 여기서는 소리부의 역할만 하고 있습니다.","酢는 “술(酉)에 넣는 식초” -> “식초, 초산”이라는 뜻의 글자입니다(乍는 소리부)."],"sourceUrl":"https://nihongokanji.com/1841/"},"吟":{"id":1830,"char":"吟","hun":"읊을 음","meaning":"“읊을 음”. 읊다, 음미하다","on":"ギン","kun":"","explanation":["吟 = 口 + 今。","(의미부) 「口」는 “입”을 뜻합니다.","(소리부 겸 의미부) 「今」(キン)은 본래 “말하고 있는 입”을 그린 글자입니다(링크 참조).","吟는 “입(口)으로 읊조리다(今)” -> “읊다, 음미하다”라는 뜻의 글자입니다.","(今는 소리부(キン -> ギン)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1842/"},"逓":{"id":1831,"char":"逓","hun":"갈마들 체","meaning":"“갈마들 체”. 차례로, 번갈아서, 보내다","on":"テイ","kun":"","explanation":["逓 = ⻌ + 乕。","「⻌」는 “길”을 뜻합니다.","乕는 “말(二+巾)에 올라타는(厂) 사람”을 그린 모양자입니다.","逓는 “역참에서 말을 갈아타며(乕) 먼 길을 달려(⻌) 소식을 전하다” -> “차례로, 번갈아서, 보내다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1843/"},"甚":{"id":1832,"char":"甚","hun":"심할 심","meaning":"“심할 심”. 심하다","on":"ジン","kun":"はなは(だ)、はなは(だしい)","explanation":["甚 = 甘 + 匹。","「甘」는 “달다”라는 뜻입니다.","匹는 여기서는 “혀를 내두르며 음식을 뱉어내는 모습”을 그린 모양자입니다.","甚는 “음식이 너무 달아서(甘) 뱉어버리다(匹)” -> “심하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1844/"},"崇":{"id":1833,"char":"崇","hun":"높을 숭","meaning":"“높을 숭”. 숭고한, 숭배하다","on":"スウ","kun":"","explanation":["崇 = 山 + 宗。","(의미부) 「山」는 “산”을 뜻합니다.","(소리부 겸 의미부) 「宗」(ソウ)는 “종교”를 뜻합니다.","崇는 “산신령(山)을 숭배하다(宗)” -> “숭고한, 숭배하다”라는 뜻의 글자입니다.","(宗는 소리부(ソウ -> スウ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1845/"},"漆":{"id":1834,"char":"漆","hun":"옻 칠","meaning":"“옻 칠”. 옻, 칠","on":"シツ","kun":"うるし","explanation":["漆 = 氵 + 木 + 𠆢 + 氺。","「氵」는 “물”을 뜻합니다.","「木」는 “나무”를 뜻합니다.","氺는 「水」가 살짝 변형된 것으로, “물”을 뜻합니다.","𠆢는 여기서는 “(옻나무에서) 흘러나오는 진액”을 그린 모양자입니다.","漆는 “옻나무(木)에서 흘러나오는(𠆢+氺) 진액(氵)” -> “옻, 칠”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1846/"},"岬":{"id":1835,"char":"岬","hun":"곶 갑","meaning":"“곶 갑”. 곶, 갑(지명한자)","on":"","kun":"みさき","explanation":["岬 = 山 + 甲。","(의미부) 「山」는 “산”을 뜻합니다.","(소리부) 「甲」(コウ)는 여기서는 소리부의 역할만 하고 있습니다.","(岬에는 정식 음독이 없으나, 본래의 음독은 コウ입니다.)","山는 “해안 쪽으로 뾰족하게 뻗은 돌산(山)” -> “곶, 갑”이라는 뜻의 글자입니다(甲는 소리부).","(다만, 이 한자는 실제로는 거의 지명한자로만 쓰입니다.)"],"sourceUrl":"https://nihongokanji.com/1847/"},"癖":{"id":1836,"char":"癖","hun":"버릇 벽","meaning":"“버릇 벽”. 버릇, 병","on":"ヘキ","kun":"くせ","explanation":["癖 = 疒 + 辟。","(의미부) 「疒」는 “병, 질병”을 뜻합니다.","(소리부 겸 의미부) 「辟」(ヘキ)는 “피하다, 숨다”라는 뜻입니다.","癖는 “힘든 일을 피하려고만(辟) 하는 버릇(疒)” -> “버릇, 병”이라는 뜻의 글자입니다.","(辟는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1848/"},"愉":{"id":1837,"char":"愉","hun":"즐거울 유","meaning":"“즐거울 유”. 즐겁다, 기쁘다","on":"ユ","kun":"","explanation":["愉 = 忄 + 俞。","(의미부) 「忄」는 “마음”을 뜻합니다.","(소리부 겸 의미부) 「俞」(ユ)는 “보내다”라는 뜻입니다.","愉는 “마음(忄)속의 슬픔을 훨훨 날려보내고(俞) 즐거워지다” -> “즐겁다, 기쁘다”라는 뜻의 글자입니다.","(俞는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1849/"},"礁":{"id":1838,"char":"礁","hun":"암초 초","meaning":"“암초 초”. 암초","on":"ショウ","kun":"","explanation":["礁 = 石 + 焦。","(의미부) 「石」는 “돌”을 뜻합니다.","(소리부 겸 의미부) 「焦」(ショウ)는 “초조하다”라는 뜻입니다.","礁는 “항해 중 암초(石)를 만나 초조해하다(焦)” -> “암초”라는 뜻의 글자입니다.","(焦는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1850/"},"屯":{"id":1839,"char":"屯","hun":"진칠 둔","meaning":"“진칠 둔”. 진치다","on":"トン","kun":"","explanation":["屯는 “땅에 깊게 뿌리내린 나무”를 그린 상형문자입니다.","“뿌리를 박다” -> “진치다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/1851/"},"姻":{"id":1840,"char":"姻","hun":"혼인 인","meaning":"“혼인 인”. 혼인","on":"イン","kun":"","explanation":["姻 = 女 + 因。","(의미부) 「女」는 “여자”를 뜻합니다.","(소리부 겸 의미부) 「因」(イン)은 본래 “침대에 누워있는 사람”을 그린 글자입니다(링크 참조).","姻은 “결혼한 여자(女)가 신랑과 한 침대에서 동침하다(因)” -> “혼인”이라는 뜻의 글자입니다.","(因는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1852/"},"擬":{"id":1841,"char":"擬","hun":"비길 의","meaning":"“비길 의”. 흉내내다, 본뜨다","on":"ギ","kun":"","explanation":["擬 = 扌 + 疑。","(의미부) 「扌」는 “손”을 뜻합니다.","(소리부 겸 의미부) 「疑」(ギ)는 “의심하다”라는 뜻입니다.","擬는 “의심(疑)하지 못할 정도로 똑같이 만들다(扌)” -> “흉내내다, 본뜨다”라는 뜻의 글자입니다.","(疑는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1853/"},"塀":{"id":1842,"char":"塀","hun":"담 병","meaning":"“담 병”. 담, 담장","on":"ヘイ","kun":"","explanation":["塀 = 土 + 尸 + 并。","(의미부) 「土」는 “흙”을 뜻합니다.","(의미부) 「尸」는 “집, 지붕”을 뜻합니다.","(소리부 겸 의미부) 并는 여기서는 「併」(ヘイ)가 축약된 것으로, “나란히”라는 뜻입니다.","塀는 “나란히(併) 늘어선 집들(尸) 사이의 흙담장(土)” -> “담, 담장”이라는 뜻의 글자입니다.","(并->併는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1854/"},"唇":{"id":1843,"char":"唇","hun":"입술 순","meaning":"“입술 순”. 입술","on":"シン","kun":"くちびる","explanation":["唇 = 辰 + 口。","(소리부) 「辰」(シン)은 여기서는 소리부의 역할만 하고 있습니다.","(의미부) 「口」는 “입”을 뜻합니다.","唇는 “입(口)” -> “입술”이라는 뜻의 글자입니다(辰는 소리부)."],"sourceUrl":"https://nihongokanji.com/1855/"},"睦":{"id":1844,"char":"睦","hun":"화목할 목","meaning":"“화목할 목”. 화목하다","on":"ボク","kun":"","explanation":["睦 = 目 + 坴。","「目」는 “눈”을 뜻합니다.","「坴」는 “흙더미”를 뜻합니다.","睦는 “흙장난(坴)하는 아이들을 따뜻하게 바라보는(目) 부모” -> “화목한 가족” -> “화목하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1856/"},"閑":{"id":1845,"char":"閑","hun":"한가할 한","meaning":"“한가할 한”. 한가로운, 조용한","on":"カン","kun":"","explanation":["閑 = 門 + 木。","「木」는 “나무”를 뜻합니다.","「門」는 “문”을 뜻합니다.","閑는 “아무도 못 들어오도록 문(門)을 나무(木)로 막아놓고 한가롭게 쉬다” -> “한가로운, 조용한”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1857/"},"幽":{"id":1846,"char":"幽","hun":"그윽할 유","meaning":"“그윽할 유”. 그윽한, 은은한, 아득한, 저승","on":"ユウ","kun":"","explanation":["幽 = 幺 + 幺 + 山。","幺는 여기서는 “안개”를 그린 모양자입니다.","「山」는 “산”을 뜻합니다.","幽는 “깊은 산(山) 속에 자욱하게 낀 안개(幺幺)” -> “그윽한, 은은한, 아득한, 저승”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1858/"},"曹":{"id":1847,"char":"曹","hun":"무리 조","meaning":"“무리 조”. 무리, 관청","on":"ソウ","kun":"","explanation":["曹 = 一 + 曲 + 曰。","「一」는 “하나”를 뜻합니다.","「曲」는 “곡, 음악’을 뜻합니다.","「曰」는 “말하다”라는 뜻입니다.","曹는 “모두 함께(一) 노래(曲)를 합창하다(曰)” -> “무리”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1859/"},"詠":{"id":1848,"char":"詠","hun":"읊을 영","meaning":"“읊을 영”. 노래하다, 읊조리다","on":"エイ","kun":"よ(む)","explanation":["詠 = 言 + 永。","(의미부) 「言」는 “말하다”라는 뜻입니다.","(소리부 겸 의미부) 「永」(エイ)는 “기나긴, 영원의”라는 뜻입니다.","詠는 “시가를 길게(永) 읊조리다(言)” -> “노래하다, 읊조리다”라는 뜻의 글자입니다.","(永는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1860/"},"卑":{"id":1849,"char":"卑","hun":"낮을 비","meaning":"“낮을 비”. 낮은, 비천한, 저열한","on":"ヒ","kun":"いや(しい)、いや(しむ)、いや(しめる)","explanation":["卑는 “부채를 든 손”을 그린 상형문자입니다.","“주인의 옆에서 부채를 부치는 시종” -> “비천하다, 낮다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/1861/"},"侮":{"id":1850,"char":"侮","hun":"업신여길 모","meaning":"“업신여길 모”. 업신여기다, 멸시하다","on":"ブ","kun":"あなど(る)","explanation":["侮 = 亻 + 毎。","「亻」는 “사람”을 뜻합니다.","「毎」는 본래 “머리에 비녀를 꽂은 어머니”를 그린 글자입니다(링크 참조).","侮는 “자기 어미(毎)를 업신여기는 사람(亻)” -> “업신여기다, 멸시하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1862/"},"鋳":{"id":1851,"char":"鋳","hun":"불릴 주","meaning":"“불릴 주”. 주물하다, 주조하다","on":"チュウ","kun":"い(る)","explanation":["鋳 = 金 + 寿。","(의미부) 「金」는 “쇠, 금속”을 뜻합니다.","(소리부 겸 의미부) 「寿」(ジュ)는 “장수하다”라는 뜻입니다.","鋳는 “쇠(金)를 오랫동안(寿) 달궈서 녹이다” -> “주물하다, 주조하다”라는 뜻의 글자입니다.","(寿는 소리부(ジュ -> チュウ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1863/"},"抹":{"id":1852,"char":"抹","hun":"지울 말","meaning":"“지울 말”. 지우다, 가루","on":"マツ","kun":"","explanation":["抹 = 扌 + 末。","(의미부) 「扌」는 “손”을 뜻합니다.","(소리부 겸 의미부) 「末」(マツ)는 “끝, 끝부분”을 뜻합니다.","抹는,","“손(扌) 끝으로(末) 문질러 지우다” -> “지우다”","“문질러서 가루가 나오다” -> “가루”","라는 뜻의 글자입니다.","(末는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1864/"},"尉":{"id":1853,"char":"尉","hun":"벼슬 위","meaning":"“벼슬 위”. 벼슬, 계급(군대의 ‘위관’을 지칭)","on":"イ","kun":"","explanation":["尉 = 尸 + 示 + 寸。","「尸」는 “앉아있는 사람”을 뜻합니다.","「示」는 “신, 종교, 고대의 비석”을 뜻합니다.","「寸」는 “손”을 뜻합니다.","尉는 “자리에 앉아(尸) 신(示)에게 기도(寸)를 올리다”라는 뜻입니다.","“전쟁의 승리를 기원하는 기도를 올리다” -> “벼슬, 계급(군대의 장교)”라는 의미입니다.","참고)","尉는 1304.「慰」의 소리부(イ)이기도 합니다."],"sourceUrl":"https://nihongokanji.com/1865/"},"隷":{"id":1854,"char":"隷","hun":"종 예","meaning":"“종 예”. 노예, 종, 예속","on":"レイ","kun":"","explanation":["隷 = 士 + 示 + 隶。","「士」는 “선비, 무사”를 뜻합니다.","「示」는 “보여주다”라는 뜻입니다.","隶는 여기서는 「逮」가 축약된 것으로, “붙잡다”라는 뜻입니다.","隷는 “무사(士)가 전쟁에서 붙잡은(隶) 노예를 보여주며(示) 자랑하다” -> “노예, 종, 예속”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1866/"},"禍":{"id":1855,"char":"禍","hun":"재앙 화","meaning":"“재앙 화”. 재앙, 화","on":"カ","kun":"","explanation":["禍 = 礻 + 咼。","(의미부) 「礻」는 “신, 종교, 고대의 비석”을 뜻합니다.","(소리부 겸 의미부) 「咼」(カ)는 “잘못되다, 어긋나다”라는 뜻입니다.","禍는 “신(礻)이 죄지은 자(咼)에게 내리는 천벌” -> “재앙, 화”라는 뜻의 글자입니다.","(咼는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1867/"},"酪":{"id":1856,"char":"酪","hun":"소젖 락","meaning":"“소젖 락”. 유제품","on":"ラク","kun":"","explanation":["酪 = 酉 + 各。","(의미부) 「酉」는 “술”을 뜻합니다. 여기서는 “술” -> “발효되다”라는 뜻으로 쓰인 것입니다.","(소리부) 「各」(カク)는 여기서는 소리부(カク -> ラク)의 역할만 하고 있습니다.","酪는 “발효된(酉) 유제품” -> “유제품”이라는 뜻의 글자입니다(各는 소리부)."],"sourceUrl":"https://nihongokanji.com/1868/"},"茎":{"id":1857,"char":"茎","hun":"줄기 경","meaning":"“줄기 경”. 줄기","on":"ケイ","kun":"くき","explanation":["茎 = 艹 + 圣。","(의미부) 「艹」는 “풀”을 뜻합니다.","(소리부 겸 의미부) 「圣」(ケイ)는 “지나가다”라는 뜻입니다.","茎는 “식물(艹)의 영양분이 지나가는(圣) 줄기” -> “줄기”라는 뜻의 글자입니다.","(圣는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1869/"},"帥":{"id":1858,"char":"帥","hun":"장수 수","meaning":"“장수 수”. 장수, 우두머리","on":"スイ","kun":"","explanation":["帥 = 𠂤 + 巾。","「𠂤」는 “언덕”을 뜻합니다.","「巾」는 “수건, 천”을 뜻합니다.","帥는 “장수가 언덕(𠂤)에 진을 치고 깃발(巾)을 꽂아두다” -> “장수, 우두머리”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1870/"},"逝":{"id":1859,"char":"逝","hun":"갈 서","meaning":"“갈 서”. 멀리 떠나다 ,죽다","on":"セイ","kun":"ゆ(く)、い(く)","explanation":["逝 = ⻌ + 折。","「⻌」는 “길”을 뜻합니다.","「折」는 “꺾다, 꺾이다”라는 뜻입니다.","逝는 “삶의 기나긴 여정(⻌)이 꺾이다(折)” -> “죽다, 멀리 떠나다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1871/"},"汽":{"id":1860,"char":"汽","hun":"물 끓는 김 기","meaning":"“물 끓는 김 기”. 증기, 김","on":"キ","kun":"","explanation":["汽 = 氵 + 气。","(의미부) 「氵」는 “물”을 뜻합니다.","(소리부 겸 의미부) 气는 여기서는 「気」(キ)가 축약된 것으로, “기체”를 뜻합니다.","汽는 “물(氵)이 증발한 기체(気)” -> “수증기”라는 뜻의 글자입니다.","(气->気는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1872/"},"匿":{"id":1861,"char":"匿","hun":"숨길 닉","meaning":"“숨길 닉”. 숨기다, 감추다","on":"トク","kun":"","explanation":["匿 = 匚 + 若。","匚는 여기서는 “동굴”을 그린 모양자입니다.","「若」는 “젊다, 어리다”라는 뜻입니다.","匿는 “젊은이(若)가 징집을 피해 동굴(匚)에 몸을 숨기다” -> “숨기다, 감추다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1873/"},"襟":{"id":1862,"char":"襟","hun":"옷깃 금","meaning":"“옷깃 금”. 옷깃, 목덜미, 마음속","on":"キン","kun":"えり","explanation":["襟 = 衤 + 禁。","(의미부) 「衤」는 “옷, 옷감”을 뜻합니다.","(소리부 겸 의미부) 「禁」(キン)은 “금하다”라는 뜻입니다.","襟는 “옷깃(衤)을 잠그다(禁)” -> “옷깃, 목덜미” -> “가슴, 마음속”이라는 뜻의 글자입니다.","(禁는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1874/"},"蛍":{"id":1863,"char":"蛍","hun":"반딧불 형","meaning":"“반딧불 형”. 반딧불","on":"ケイ","kun":"ほたる","explanation":["蛍 = ⺍ + 冖 + 虫。","「⺍＋冖」는 “불이 환하게 켜진 집”을 뜻합니다.","「虫」는 “벌레”를 뜻합니다.","蛍는 “불빛(⺍＋冖)을 내는 벌레(虫)” -> “반딧불”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1875/"},"寡":{"id":1864,"char":"寡","hun":"적을 과","meaning":"“적을 과”. 적다, 과부","on":"カ","kun":"","explanation":["寡 = 宀 + 夏。","(의미부) 「宀」는 “집”을 뜻합니다.","(소리부 겸 의미부) 아래쪽 글자는 「夏」(カ)가 변형된 것으로, “여름”을 뜻합니다.","寡는,","“여름(夏)에 모두 밭일을 하러 나가 집(宀)에 아무도 없다” -> “적다”","“사람이 적다” -> “남편이 없다” -> “과부”","라는 뜻의 글자입니다.","(夏는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1876/"},"痢":{"id":1865,"char":"痢","hun":"설사 리","meaning":"“설사 리”. 설사","on":"リ","kun":"","explanation":["痢 = 疒 + 利。","(의미부) 「疒」는 “병, 질병”을 뜻합니다.","(소리부) 「利」(リ)는 여기서는 소리부의 역할만 하고 있습니다.","痢는 “병(疒)” -> “설사”라는 뜻의 글자입니다(利는 소리부)."],"sourceUrl":"https://nihongokanji.com/1877/"},"庸":{"id":1866,"char":"庸","hun":"쓸 용","meaning":"“쓸 용”. 평범하다, 고용하다","on":"ヨウ","kun":"","explanation":["庸 = 广 + 肀 + 用。","(의미부) 「广」는 “건물, 집”을 뜻합니다.","(의미부) 「肀」는 “붓을 든 손”을 뜻합니다.","(소리부 겸 의미부) 「用」(ヨウ)는 “쓰다, 사용하다”라는 뜻입니다.","庸는 “집(广)에서 아이에게 글을 가르칠(肀) 가정교사를 고용하다(用)”라는 뜻입니다.","“가정교사를 고용하다” -> “고용하다”","“평범한 가정교사” -> “평범하다”","라는 의미입니다.","(用는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1878/"},"坑":{"id":1867,"char":"坑","hun":"구덩이 갱","meaning":"“구덩이 갱”. 구덩이","on":"コウ","kun":"","explanation":["坑 = 土 + 亢。","(의미부) 「土」는 “흙”을 뜻합니다.","(소리부 겸 의미부) 「亢」(コウ)는 “오르다”라는 뜻입니다.","坑는 “흙(土) 구덩이를 기어오르다(亢)” -> “구덩이”라는 뜻의 글자입니다.","(亢는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1879/"},"藍":{"id":1868,"char":"藍","hun":"쪽 람","meaning":"“쪽 람”. 쪽빛, 남빛","on":"ラン","kun":"あい","explanation":["藍 = 艹 + 監。","(의미부) 「艹」는 “풀”을 뜻합니다.","(소리부 겸 의미부) 「監」(カン)은 본래 “그릇을 내려다보는 눈”을 그린 글자입니다(링크 참조).","藍는 “쪽풀(艹)에서 짜낸 염료가 그릇에 담기는 것을 바라보다(監)” -> “쪽빛, 남빛”이라는 뜻의 글자입니다.","(監는 소리부(カン -> ラン)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1880/"},"賊":{"id":1869,"char":"賊","hun":"도둑 적","meaning":"“도둑 적”. 도적, 산적","on":"ゾク","kun":"","explanation":["賊 = 貝 + 十 + 戈。","「貝」는 “돈, 재물”을 뜻합니다.","「戈」는 “창”을 뜻합니다.","十는 여기서는 “사람”을 그린 모양자입니다.","賊는 “창칼(戈)로 사람(十)을 위협해서 돈(貝)을 빼앗다” -> “도적, 산적”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1881/"},"搾":{"id":1870,"char":"搾","hun":"짤 착","meaning":"“짤 착”. 짜다","on":"サク","kun":"しぼ(る)","explanation":["搾 = 扌 + 穴 + 乍。","(의미부) 「扌」는 “손”을 뜻합니다.","(의미부) 「穴」는 “구멍”을 뜻합니다.","(소리부 겸 의미부) 「乍」(サク)는 여기서는 “흘러나오는 젖”을 그린 모양자로 쓰인 것입니다.","搾는 “젖꼭지(穴)에서 모유(乍)를 짜내다(扌)” -> “짜다”라는 뜻의 글자입니다.","(乍는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1882/"},"畔":{"id":1871,"char":"畔","hun":"밭두둑 반","meaning":"“밭두둑 반”. 논둑, 물가","on":"ハン","kun":"","explanation":["畔 = 田 + 半。","(의미부) 「田」는 “밭”을 뜻합니다.","(소리부 겸 의미부) 「半」(ハン)은 “절반”이라는 뜻입니다.","畔은 “밭과 밭(田) 사이를 반으로 나누는(半) 경계” -> “논둑, 물가”라는 뜻의 글자입니다.","(半는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1883/"},"唄":{"id":1872,"char":"唄","hun":"염불소리 패","meaning":"“염불소리 패”. 노래","on":"","kun":"うた","explanation":["唄 = 口 + 貝。","「口」는 “입”을 뜻합니다.","「貝」는 “돈, 재물”을 뜻합니다.","唄는 “돈(貝)을 받고 노래를 불러주는(口) 소리꾼” -> “노래”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1884/"},"孔":{"id":1873,"char":"孔","hun":"구멍 공","meaning":"“구멍 공”. 구멍","on":"コウ","kun":"","explanation":["孔 = 子 + 乚。","「子」는 “아이”를 뜻합니다.","乚는 여기서는 “여자의 가슴”을 그린 모양자입니다.","孔는 “어미의 젖(乚)을 빠는 아기(子)” -> “젖이 나오는 구멍” -> “구멍”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1885/"},"呂":{"id":1874,"char":"呂","hun":"법칙 려","meaning":"“법칙 려”. 음률","on":"ロ","kun":"","explanation":["「呂」는 “여러 채의 집이 이어져있는 대저택”을 그린 글자입니다.","“커다란 저택(呂)에서 흘러나오는 음악” -> “음률”이라는 의미입니다.","(다만, 이 한자는 실제로는 단순히 「ろ」음의 취음자 역할로 쓰이는 경우가 대부분입니다.)"],"sourceUrl":"https://nihongokanji.com/1886/"},"拷":{"id":1875,"char":"拷","hun":"칠 고","meaning":"“칠 고”. 고문하다","on":"ゴウ","kun":"","explanation":["拷 = 扌 + 考。","(의미부) 「扌」는 “손”을 뜻합니다.","(소리부 겸 의미부) 「考」(コウ)는 본래 “지팡이를 짚은 노인”을 그린 글자입니다(링크 참조).","拷는 “힘없는 노인(考)을 괴롭히고 고문하다(扌)” -> “고문하다”라는 뜻의 글자입니다.","(考는 소리부(コウ -> ゴウ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1887/"},"嬢":{"id":1876,"char":"嬢","hun":"아가씨 양","meaning":"“아가씨 양”. 처녀, 색시, 아가씨","on":"ジョウ","kun":"","explanation":["嬢 = 女 + 㐮。","(의미부) 「女」는 “여자”를 뜻합니다.","(소리부 겸 의미부) 「㐮」(ジョウ)는 “예복, 상복”을 뜻합니다.","嬢는 “귀여운 예복(㐮)을 입은 아가씨(女)” -> “처녀, 색시, 아가씨”라는 뜻의 글자입니다.","(㐮는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1888/"},"渓":{"id":1877,"char":"渓","hun":"시내 계","meaning":"“시내 계”. 계곡, 골짜기","on":"ケイ","kun":"","explanation":["渓 = 氵 + ⺤ + 夫。","「氵」는 “물”을 뜻합니다.","「⺤」는 “손”을 뜻합니다.","「夫」는 “남편, 성인 남성”을 뜻합니다.","渓는 “계곡(氵)에서 물고기를 잡는(⺤) 성인 남성(夫)” -> “계곡, 골짜기”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1889/"},"翁":{"id":1878,"char":"翁","hun":"늙은이 옹","meaning":"“늙은이 옹”. 노인 남성","on":"オウ","kun":"","explanation":["翁 = 公 + 羽。","(소리부 겸 의미부) 「公」(コウ)는 “공평하다”라는 뜻입니다.","(의미부) 「羽」는 “깃털”을 뜻합니다. 여기서는 “깃털” -> “수염”이라는 뜻으로 응용된 것입니다.","翁는 “일을 공정하게(公) 판단해주는 수염이 긴(羽) 어르신” -> “노인 남성, 어르신”이라는 뜻의 글자입니다.","(公는 소리부(コウ -> オウ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1890/"},"廉":{"id":1879,"char":"廉","hun":"청렴할 렴","meaning":"“청렴할 렴”. 청렴하다, 저렴하다","on":"レン","kun":"","explanation":["廉 = 广 + 兼。","(의미부) 「广」는 “집, 건물”을 뜻합니다.","(소리부 겸 의미부) 「兼」(ケン)은 본래 “손에 볏단을 쥔 모습”을 그린 글자입니다(링크 참조).","廉는 “볏짚(兼)을 엮어 만든 작은 초가집(广)에서 사는 선비” -> “청렴하다, 저렴하다”라는 뜻의 글자입니다.","(兼는 소리부(ケン -> レン)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1891/"},"謹":{"id":1880,"char":"謹","hun":"삼갈 근","meaning":"“삼갈 근”. 삼가다, 주의하다","on":"キン","kun":"つつし(む)","explanation":["謹 = 言 + 堇。","(의미부) 「言」는 “말하다”라는 뜻입니다.","(소리부 겸 의미부) 「堇」(キン)은 “처벌, 형벌”을 뜻합니다.","謹는 “말실수(言)로 인해 처벌(堇)받지 않도록 조심하다” -> “삼가다, 조심하다”라는 뜻의 글자입니다.","(堇는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1892/"},"瞳":{"id":1881,"char":"瞳","hun":"눈동자 동","meaning":"“눈동자 동”. 눈동자","on":"ドウ","kun":"ひとみ","explanation":["瞳 = 目 + 童。","(의미부) 「目」는 “눈”을 뜻합니다.","(소리부 겸 의미부) 「童」(ドウ)는 “어린이, 아이”를 뜻합니다.","瞳는 “아이(童)의 맑은 눈(目)” -> “눈동자”라는 뜻의 글자입니다.","(童는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1893/"},"湧":{"id":1882,"char":"湧","hun":"물 솟을 용","meaning":"“물 솟을 용”. 지하에서 물이 솟아나오다","on":"ユウ","kun":"わ(く)","explanation":["湧 = 氵 + 勇。","(의미부) 「氵」는 “물”을 뜻합니다.","(소리부 겸 의미부) 「勇」(ユウ)는 “용기”를 뜻합니다.","湧는 “마음속의 용기(勇)가 끓어오르듯 물(氵)이 땅에서 솟아나다” -> “물이 솟아오르다”라는 뜻의 글자입니다.","(勇는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1894/"},"窯":{"id":1883,"char":"窯","hun":"기와 가마 요","meaning":"“기와 가마 요”. 가마, 도기","on":"ヨウ","kun":"かま","explanation":["窯 = 穴 + 𦍌 + 灬。","(의미부) 「穴」는 “구멍”을 뜻합니다.","(소리부 겸 의미부) 「𦍌」(ヨウ)는 여기서는 “도자기”의 모습을 그린 모양자로 쓰인 것입니다.","(의미부) 「灬」는 “불”을 뜻합니다.","窯는 “도자기(𦍌)를 구워내는(灬) 가마(穴)” -> “가마, 도기”라는 뜻의 글자입니다.","(𦍌는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1895/"},"褒":{"id":1884,"char":"褒","hun":"기릴 포","meaning":"“기릴 포”. 칭찬하다","on":"ホウ","kun":"ほ(める)","explanation":["褒 = 衣 + 保。","(의미부) 「衣」는 “옷”을 뜻합니다.","(소리부 겸 의미부) 「保」(ホ)는 “지키다, 보호하다”라는 뜻입니다.","褒는 “체온을 지켜주는(保) 두껍고 따뜻한 옷(衣)” -> “좋다, 칭찬하다”라는 뜻의 글자입니다.","(保는 소리부(ホ -> ホウ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1896/"},"醜":{"id":1885,"char":"醜","hun":"추할 추","meaning":"“추할 추”. 못생긴, 추한, 흉한","on":"シュウ","kun":"みにく(い)","explanation":["醜 = 酉 + 鬼。","「酉」는 “술”을 뜻합니다.","「鬼」는 “귀신, 도깨비”를 뜻합니다.","醜는 “술(酉)에 취하지 않고는 도저히 눈뜨고 볼 수 없는, 도깨비(鬼)처럼 추한 모습” -> “못생긴, 추한, 흉한”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1897/"},"升":{"id":1886,"char":"升","hun":"되 승","meaning":"“되 승”. 되/승(용량의 단위)","on":"ショウ","kun":"ます","explanation":["升는 본래 “국자로 술을 퍼올리는 모습”을 그린 상형문자입니다.","“한 국자만큼의 술” -> “되, 승(용량의 단위)”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/1898/"},"殉":{"id":1887,"char":"殉","hun":"따라죽을 순","meaning":"“따라죽을 순”. 순교하다, 따라 죽다","on":"ジュン","kun":"","explanation":["殉 = 歹 + 旬。","(의미부) 「歹」는 “시체”를 뜻합니다.","(소리부) 「旬」(ジュン)은 여기서는 소리부의 역할만 하고 있습니다.","殉은 “주군을 따라서 죽다(歹)” -> “순교하다, 따라 죽다”라는 뜻의 글자입니다(旬는 소리부)."],"sourceUrl":"https://nihongokanji.com/1899/"},"煩":{"id":1888,"char":"煩","hun":"번거로울 번","meaning":"“번거로울 번”. 번거롭다, 귀찮다, 번민하다","on":"ハン、ボン","kun":"わずら(う)、わずら(わす)","explanation":["煩 = 火 + 頁。","「火」는 “불”을 뜻합니다.","「頁」는 “머리”를 뜻합니다.","煩는 “머리(頁)에 불이 날(火) 정도로 번거롭고 귀찮다” -> “번거롭다, 귀찮다, 번민하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1900/"},"劾":{"id":1889,"char":"劾","hun":"꾸짖을 핵","meaning":"“꾸짖을 핵”. 추궁하다, 탄핵하다","on":"ガイ","kun":"","explanation":["劾 = 亥 + 力。","「亥」는 “도축, 가공된 돼지”를 뜻합니다.","「力」는 “힘”을 뜻합니다.","劾는 “강한 힘으로(力) 뼈도 못 추리게(亥) 몰아붙이다” -> “추궁하다, 탄핵하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1901/"},"堕":{"id":1890,"char":"堕","hun":"떨어질 타","meaning":"“떨어질 타”. 무너지다, 떨어지다","on":"ダ","kun":"","explanation":["堕 = ⻖ + 有 + 土。","「⻖」는 “언덕”을 뜻합니다.","「有」는 “있다”라는 뜻입니다.","「土」는 “흙, 땅”을 뜻합니다.","堕는 “언덕(⻖) 위에 있던(有) 것이 땅(土)으로 떨어지다” -> “무너지다, 떨어지다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1902/"},"租":{"id":1891,"char":"租","hun":"조세 조","meaning":"“조세 조”. 조세, 세금","on":"ソ","kun":"","explanation":["租 = 禾 + 且。","(의미부) 「禾」는 “곡식”을 뜻합니다.","(소리부 겸 의미부) 「且」(ソ)는 “비석, 조상, 장례”를 뜻합니다.","租는 “세금으로 곡식(禾)을 전부 뜯기고 굶어죽다(且)” -> “세금, 조세”라는 뜻의 글자입니다.","(且는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1903/"},"桟":{"id":1892,"char":"桟","hun":"사다리 잔","meaning":"“사다리 잔”. 잔교, 가교","on":"サン","kun":"","explanation":["桟 = 木 + 㦮。","(의미부) 「木」는 “나무”를 뜻합니다.","(소리부 겸 의미부) 「㦮」(セン)은 여기서는 “부두에 놓인 잔교”를 그린 모양자로 쓰인 것입니다.","아래 그림을 참조해 주세요.","桟는 “나무(木)로 만든 잔교(㦮)” -> “잔교, 가교”라는 뜻의 글자입니다.","(㦮는 소리부(セン -> サン)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1904/"},"婿":{"id":1893,"char":"婿","hun":"사위 서","meaning":"“사위 서”. 사위","on":"セイ","kun":"むこ","explanation":["婿 = 女 + 疋 + 月。","(의미부) 「女」는 “여자”를 뜻합니다.","(소리부 겸 의미부) 疋는 여기서는 「正」(セイ)가 변형된 것으로, “바르다”라는 뜻입니다.","(의미부) 「月」는 “신체의 일부”를 뜻합니다.","婿는 “딸(女)의 몸(月)의 정당한(疋->正) 주인” -> “사위”라는 뜻의 글자입니다.","(疋->正는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1905/"},"慕":{"id":1894,"char":"慕","hun":"그릴 모","meaning":"“그릴 모”. 그리워하다, 사모하다","on":"ボ","kun":"した(う)","explanation":["慕 = 莫 + ⺗。","(소리부 겸 의미부) 「莫」(ボ)는 “없다”라는 뜻입니다.","(의미부) ⺗는 여기서는 「心」가 변형된 것으로, “마음”을 뜻합니다.","慕는 “옆에 없는 사람(莫)을 마음(心) 속으로 그리워하다” -> “그리워하다, 사모하다”라는 뜻의 글자입니다.","(莫는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1906/"},"罷":{"id":1895,"char":"罷","hun":"마칠 파","meaning":"“마칠 파”. 중지하다, 그만두다","on":"ヒ","kun":"","explanation":["罷 = 罒 + 能。","「罒」는 “그물”을 뜻합니다.","「能」는 본래 “곰”을 그린 글자입니다(링크 참조).","罷는 “곰(能)이 그물(罒)에 걸려 움직임을 멈추다” -> “중지하다, 그만두다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1907/"},"矯":{"id":1896,"char":"矯","hun":"바로잡을 교","meaning":"“바로잡을 교”. 바로잡다","on":"キョウ","kun":"た(める)","explanation":["矯 = 矢 + 喬。","(의미부) 「矢」는 “화살”을 뜻합니다.","(소리부 겸 의미부) 喬는 여기서는 「橋」(キョウ)가 축약된 것으로, “다리”를 뜻합니다.","矯는 “화살(矢)에 맞아 망가진 다리(喬->橋)를 수리하다” -> “바로잡다”라는 뜻의 글자입니다.","(喬->橋는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1908/"},"某":{"id":1897,"char":"某","hun":"아무 모","meaning":"“아무 모”. 아무개, 모~(모년, 모월, 모씨, 모국 등)","on":"ボウ","kun":"","explanation":["某 = 甘 + 木。","某는 본래 “달콤한(「甘」) 열매가 열리는 나무(「木」)” -> “매실나무”라는 뜻으로 만들어진 글자입니다.","“아무개”라는 뜻은 나중에 발음이 비슷하다는 이유로 추가된 것입니다.","즉, 某의 모양과 의미 사이에는 아무런 관계도 없습니다."],"sourceUrl":"https://nihongokanji.com/1909/"},"囚":{"id":1898,"char":"囚","hun":"가둘 수","meaning":"“가둘 수”. 가두다, 갇히다","on":"シュウ","kun":"","explanation":["囚 = 囗 + 人。","囗는 여기서는 “감옥”을 그린 모양자입니다.","「人」는 “사람”을 뜻합니다.","囚는 “감옥(囗)에 갇힌 사람(人)” -> “가두다, 갇히다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1910/"},"虹":{"id":1899,"char":"虹","hun":"무지개 홍","meaning":"“무지개 홍”. 무지개","on":"","kun":"にじ","explanation":["虹 = 虫 + 工。","(의미부) 「虫」는 “벌레”를 뜻합니다.","(소리부) 「工」(コウ)는 여기서는 소리부의 역할만 하고 있습니다.","(虹에는 정식 음독이 없으나, 본래의 음독은 コウ입니다.)","옛날 중국에서는 무지개를 하늘에 용이 나타난 것으로 여겼다고 합니다.","虹는 “하늘에 나타난 몸통이 긴 애벌레(虫)” -> “무지개”라는 뜻의 글자입니다(工는 소리부)."],"sourceUrl":"https://nihongokanji.com/1911/"},"泌":{"id":1900,"char":"泌","hun":"분비할 비","meaning":"“분비할 비”. 분비하다, 스며 나오다","on":"ヒツ、ヒ","kun":"","explanation":["泌 = 氵 + 必。","(의미부) 「氵」는 “물”을 뜻합니다.","(소리부 겸 의미부) 「必」(ヒツ)는 “필수적인, 반드시”라는 뜻입니다.","泌는 “생명 유지에 꼭 필요한(必) 분비물(氵)” -> “분비하다, 스며 나오다”라는 뜻의 글자입니다.","(必는 소리부(ヒツ -> ヒツ・ヒ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1912/"},"漸":{"id":1901,"char":"漸","hun":"점점 점","meaning":"“점점 점”. 차츰차츰, 점점","on":"ゼン","kun":"","explanation":["漸 = 氵 + 車 + 斤。","「氵」는 “물”을 뜻합니다.","「車」는 “수레, 차”를 뜻합니다.","「斤」는 “도끼”를 뜻합니다.","漸는 “물가(氵)의 나무를 하나씩 베어(斤) 수레(車)에 차곡차곡 싣다” -> “차츰차츰, 점점”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1913/"},"蚊":{"id":1902,"char":"蚊","hun":"모기 문","meaning":"“모기 문”. 모기","on":"","kun":"か","explanation":["蚊 = 虫 + 文。","「虫」는 “벌레”를 뜻합니다.","「文」는 본래 “몸에 문신이 있는 사람”을 그린 글자입니다(링크 참조).","蚊는 “물어서 몸에 물린 자국(文)을 남기는 벌레(虫)” -> “모기”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1914/"},"厄":{"id":1903,"char":"厄","hun":"액 액","meaning":"“액 액”. 재앙, 재액","on":"ヤク","kun":"","explanation":["厄 = 厂 + 㔾。","「厂」는 “절벽”을 뜻합니다.","「㔾」는 “무릎꿇은 사람”을 뜻합니다.","厄는 “절벽(厂) 아래로 굴러떨어진 사람(㔾)” -> “재앙을 당하다” -> “재앙, 재액”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1915/"},"藻":{"id":1904,"char":"藻","hun":"마름 조","meaning":"“마름 조”. 물풀, 수초","on":"ソウ","kun":"も","explanation":["藻 = 艹 + 氵 + 喿。","(의미부) 「艹」는 “풀”을 뜻합니다.","(의미부) 「氵」는 “물”을 뜻합니다.","(소리부 겸 의미부) 喿는 여기서는 「燥」(ソウ)가 축약된 것으로, “말리다”라는 뜻입니다.","藻는 “물(氵) 속에 난 수초(艹)를 채집해 말리다(燥)” -> “물풀, 수초”라는 뜻의 글자입니다.","(喿->燥는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1916/"},"嫡":{"id":1905,"char":"嫡","hun":"정실 적","meaning":"“정실 적”. 본처, 정실","on":"チャク","kun":"","explanation":["嫡 = 女 + 啇。","「女」는 “여자”를 뜻합니다.","啇는 여기서는 「適」가 축약된 것으로, “적합하다”라는 뜻입니다.","嫡는 “정실로 들이기 적합한(適) 여자(女)” -> “본처, 정실”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1917/"},"嚇":{"id":1906,"char":"嚇","hun":"성낼 혁","meaning":"“성낼 혁”. 성내다, 위협하다, 화내다","on":"カク","kun":"","explanation":["嚇 = 口 + 赤 + 赤。","「口」는 “입”을 뜻합니다.","「赤」는 “빨강”을 뜻합니다.","嚇는 “시뻘개진(赤赤) 얼굴로 마구 소리치다(口)” -> “성내다, 위협하다, 화내다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1918/"},"凸":{"id":1907,"char":"凸","hun":"볼록할 철","meaning":"“볼록할 철”. 볼록한","on":"トツ","kun":"","explanation":["凸는 “가운데가 볼록 솟아오른 모습”을 그린 상형문자입니다."],"sourceUrl":"https://nihongokanji.com/1919/"},"韻":{"id":1908,"char":"韻","hun":"운 운","meaning":"“운 운”. 운율, 운치","on":"イン","kun":"","explanation":["韻 = 音 + 員。","(의미부) 「音」는 “소리”를 뜻합니다.","(소리부) 「員」(イン)은 여기서는 소리부의 역할만 하고 있습니다.","韻는 “잔잔히 울려퍼지는 소리(音)” -> “운치, 운율”이라는 뜻의 글자입니다(員는 소리부)."],"sourceUrl":"https://nihongokanji.com/1920/"},"霜":{"id":1909,"char":"霜","hun":"서리 상","meaning":"“서리 상”. 서리","on":"ソウ","kun":"しも","explanation":["霜 = 雨 + 相。","(의미부) 「雨」는 “비”를 뜻합니다.","(소리부 겸 의미부) 「相」(ソウ)는 “모습, 모양”을 뜻합니다.","霜는 “공기 중의 빗방울(雨)이 얼어붙어 서리가 내린 모습(相)” -> “서리”라는 뜻의 글자입니다.","(相는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1921/"},"硝":{"id":1910,"char":"硝","hun":"화약 초","meaning":"“화약 초”. 화약, 초석(질산칼륨)","on":"ショウ","kun":"","explanation":["硝 = 石 + 肖。","(의미부) 「石」는 “돌”을 뜻합니다.","(소리부 겸 의미부) 肖는 여기서는 「消」(ショウ)가 축약된 것으로, “사라지다”라는 뜻입니다.","硝는 “바위(石)도 잘게 부수는(消) 화약” -> “화약, 초석(질산칼륨)”이라는 뜻의 글자입니다.","(肖는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1922/"},"勅":{"id":1911,"char":"勅","hun":"칙서 칙","meaning":"“칙서 칙”. 어명, 임금의 명령","on":"チョク","kun":"","explanation":["勅 = 束 + 力。","(소리부 겸 의미부) 「束」(ソク)는 “묶다”라는 뜻입니다.","(의미부) 「力」는 “힘”을 뜻합니다.","勅는 “구속력(束)과 강제력(力)을 가진 임금의 명령” -> “어명, 임금의 명령”이라는 뜻의 글자입니다.","(束는 소리부(ソク -> チョク)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1923/"},"棺":{"id":1912,"char":"棺","hun":"널 관","meaning":"“널 관”. 관","on":"カン","kun":"","explanation":["棺 = 木 + 官。","(의미부) 「木」는 “나무”를 뜻합니다.","(소리부 겸 의미부) 「官」(カン)은 “관청, 관직, 벼슬”을 뜻합니다.","옛날에는 관의 가격도 비쌌기에, 돈이 많거나 높은 지위에 있는 사람만 쓸 수 있었다고 합니다.","棺는 “죽은 벼슬아치(官)가 들어갈 나무관(木)” -> “관”이라는 뜻의 글자입니다.","(官는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1924/"},"儒":{"id":1913,"char":"儒","hun":"선비 유","meaning":"“선비 유”. 유교","on":"ジュ","kun":"","explanation":["儒 = 亻 + 需。","(의미부) 「亻」는 “사람”을 뜻합니다.","(소리부 겸 의미부) 「需」(ジュ)는 “필요한, 필수적인”이라는 뜻입니다.","儒는 “인간(亻)에게 꼭 필요한(需) 도덕을 가르치는 유교” -> “유교”라는 뜻의 글자입니다.","(需는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1925/"},"愁":{"id":1914,"char":"愁","hun":"근심 수","meaning":"“근심 수”. 우울한, 근심하는","on":"シュウ","kun":"うれ(える)、うれ(い)","explanation":["愁 = 秋 + 心。","(소리부 겸 의미부) 「秋」(シュウ)는 “가을”을 뜻합니다.","(의미부) 「心」는 “마음”을 뜻합니다.","愁는 “가을(秋)의 쓸쓸한 마음(心)” -> “우울한, 근심하는”이라는 뜻의 글자입니다.","(秋는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1926/"},"楼":{"id":1915,"char":"楼","hun":"다락 루","meaning":"“다락 루”. 다락, 망루","on":"ロウ","kun":"","explanation":["楼 = 木 + 娄。","「木」는 “나무”를 뜻합니다.","「娄」는 “쌓다, 겹치다”라는 뜻입니다.","楼는 “나무(木)로 쌓아올린(娄) 탑” -> “다락, 망루”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1927/"},"眉":{"id":1916,"char":"眉","hun":"눈썹 미","meaning":"“눈썹 미”. 눈썹","on":"ビ、ミ","kun":"まゆ","explanation":["眉 = 𠃜 + 目。","「目」는 “눈”을 뜻합니다.","𠃜는 여기서는 “길게 자란 눈썹”을 그린 모양자입니다.","眉는 “눈(目) 위의 눈썹(𠃜)” -> “눈썹”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1928/"},"薪":{"id":1917,"char":"薪","hun":"섶 신","meaning":"“섶 신”. 장작","on":"シン","kun":"たきぎ","explanation":["薪 = 艹 + 新。","(의미부) 「艹」는 “풀”을 뜻합니다.","(소리부 겸 의미부) 「新」(シン)은 여기서는 “도끼(斤)로 벤 나무(木)”라는 뜻으로 쓰인 것입니다.","薪는 “불을 지피기 위해 베어온 나무(新)와 짚단(艹)” -> “장작”이라는 뜻의 글자입니다.","(新는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1929/"},"褐":{"id":1918,"char":"褐","hun":"갈색 갈","meaning":"“갈색 갈”. 갈색","on":"カツ","kun":"","explanation":["褐 = 衤 + 曷。","(의미부) 「衤」는 “옷, 옷감”을 뜻합니다.","(소리부 겸 의미부) 「曷」(カツ)는 “허리를 굽혀 구걸하는 사람”을 뜻합니다.","褐는 “구걸하는 거지(曷)의 갈색으로 때가 찌든 옷(衤)” -> “갈색”이라는 뜻의 글자입니다.","(曷는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1930/"},"賜":{"id":1919,"char":"賜","hun":"줄 사","meaning":"“줄 사”. 주다, 하사하다","on":"シ","kun":"たまわ(る)","explanation":["賜 = 貝 + 易。","「貝」는 “돈, 재물”을 뜻합니다.","「易」는 본래 “접시의 물을 아래로 쏟아버리는 모습”을 그린 글자입니다(링크 참조).","賜는 “재물(貝)을 아래로 내려주다(易)” -> “주다, 하사하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1931/"},"繕":{"id":1920,"char":"繕","hun":"기울 선","meaning":"“기울 선”. 수선하다, 고치다","on":"ゼン","kun":"つくろ(う)","explanation":["繕 = 糸 + 善。","(의미부) 「糸」는 “실”을 뜻합니다.","(소리부 겸 의미부) 「善」(ゼン)은 “착하다, 좋다”라는 뜻입니다.","繕는 “찢어진 부분을 실(糸)로 꿰매서 좋게(善) 만들다” -> “수선하다, 고치다”라는 뜻의 글자입니다.","(善는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1932/"},"栓":{"id":1921,"char":"栓","hun":"마개 전","meaning":"“마개 전”. 마개","on":"セン","kun":"","explanation":["栓 = 木 + 全。","(의미부) 「木」는 “나무”를 뜻합니다.","(소리부 겸 의미부) 「全」(ゼン)은 여기서는 “나무못”을 그린 모양자로 쓰인 것입니다.","栓은 “구멍에 끼워 넣는 나무(木) 못(全)” -> “마개”라는 뜻의 글자입니다.","(全는 소리부(ゼン -> セン)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1933/"},"凹":{"id":1922,"char":"凹","hun":"오목할 요","meaning":"“오목할 요”. 오목한","on":"オウ","kun":"","explanation":["凹는 “중앙이 움푹 패인 모양”을 그린 상형문자입니다."],"sourceUrl":"https://nihongokanji.com/1934/"},"艶":{"id":1923,"char":"艶","hun":"고울 염","meaning":"“고울 염”. 고운, 요염한","on":"エン","kun":"つや","explanation":["艶 = 豊 + 色。","「豊」는 “풍부하다”라는 뜻입니다.","「色」는 “색, 색기”를 뜻합니다.","艶는 “색기(色)가 넘치는(豊) 여자” -> “고운, 요염한”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1935/"},"錬":{"id":1924,"char":"錬","hun":"단련할 련","meaning":"“단련할 련”. 단련하다, (금속을) 불리다","on":"レン","kun":"","explanation":["錬 = 金 + 東。","錬는 「練」(レン)에서 糸만 「金」로 바꾼 글자로, 음독도 같습니다.","“금속(金)을 연마하다(練)” -> “단련하다, 불리다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/1936/"},"衷":{"id":1925,"char":"衷","hun":"속마음 충","meaning":"“속마음 충”. 한가운데, 속마음","on":"チュウ","kun":"","explanation":["衷 = 中 + 衣。","(소리부 겸 의미부) 「中」(チュウ)는 “가운데”를 뜻합니다.","(의미부) 「衣」는 “옷”을 뜻합니다.","衷는 “옷(衣)의 가운데 부분(中)” -> “한가운데, 속마음”이라는 뜻의 글자입니다.","(中는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1937/"},"逐":{"id":1926,"char":"逐","hun":"쫓을 축","meaning":"“쫓을 축”. 쫓아내다","on":"チク","kun":"","explanation":["逐 = ⻌ + 豕。","「⻌」는 “길”을 뜻합니다.","「豕」는 “돼지”를 뜻합니다.","逐는 “사람에게 쫓겨 달아나는(⻌) 멧돼지(豕)” -> “쫓아내다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1938/"},"斥":{"id":1927,"char":"斥","hun":"물리칠 척","meaning":"“물리칠 척”. 물리치다, 배척하다","on":"セキ","kun":"","explanation":["斥 = 斤 + 丶。","「斤」는 “도끼”를 뜻합니다.","丶는 여기서는 “도끼에 베인 자국”을 그린 모양자입니다.","斥는 “도끼(斤)로 베어버리다(丶)” -> “내쫓다, 물리치다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1939/"},"詔":{"id":1928,"char":"詔","hun":"조서 조","meaning":"“조서 조”. 칙령, 조서","on":"ショウ","kun":"みことのり","explanation":["詔 = 言 + 召。","(의미부) 「言」는 “말하다”라는 뜻입니다.","(소리부 겸 의미부) 「召」(ショウ)는 “부르다, 소환”이라는 뜻입니다.","詔는 “황제가 신하를 불러서(召) 명령을 내리다(言)” -> “칙령, 조서”라는 뜻의 글자입니다.","(召는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1940/"},"憧":{"id":1929,"char":"憧","hun":"동경할 동","meaning":"“동경할 동”. 동경하다","on":"ショウ","kun":"あこが(れる)","explanation":["憧 = 忄 + 童。","「忄」는 “마음”을 뜻합니다.","「童」는 “아이”를 뜻합니다.","憧는 “어른을 동경하는 아이(童)의 마음(忄)” -> “동경하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1941/"},"宵":{"id":1930,"char":"宵","hun":"밤 소","meaning":"“밤 소”. 밤, 초저녁","on":"ショウ","kun":"よい","explanation":["宵 = 宀 + 肖。","(의미부) 「宀」는 “집”을 뜻합니다.","(소리부 겸 의미부) 「肖」(ショウ)는 여기서는 “달(月)에서 나는 빛(⺌)”을 표현한 모양자로 쓰인 것입니다.","宵는 “집(宀)에서 달빛(肖)을 올려다보다” -> “밤, 초저녁”이라는 뜻의 글자입니다.","(肖는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1942/"},"妄":{"id":1931,"char":"妄","hun":"망령될 망","meaning":"“망령될 망”. 망령된, 헛된","on":"モウ、ボウ","kun":"","explanation":["妄 = 亡 + 女。","(소리부 겸 의미부) 「亡」(モウ・ボウ)는 “망하다”라는 뜻입니다.","(의미부) 「女」는 “여자”를 뜻합니다.","妄는 “여자(女)의 망령된(亡) 생각” -> “망령된, 헛된”이라는 뜻의 글자입니다.","(亡는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1943/"},"酌":{"id":1932,"char":"酌","hun":"술 부을 작","meaning":"“술 부을 작”. 술을 따르다","on":"シャク","kun":"く(む)","explanation":["酌 = 酉 + 勺。","「酉」는 “술, 술병”을 뜻합니다.","勺는 여기서는 “국자”를 그린 모양자입니다.","酌는 “술병의 술(酉)을 국자(勺)로 퍼서 따르다” -> “술을 따르다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1944/"},"蚕":{"id":1933,"char":"蚕","hun":"누에 잠","meaning":"“누에 잠”. 누에","on":"サン","kun":"かいこ","explanation":["蚕 = 天 + 虫。","「天」는 “하늘”을 뜻합니다.","「虫」는 “벌레”를 뜻합니다.","누에는 인간에게 명주실을 제공해주는 소중한 곤충입니다.","蚕는 “하늘(天)이 내려주신 벌레(虫)” -> “누에”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1945/"},"頒":{"id":1934,"char":"頒","hun":"나눌 반","meaning":"“나눌 반”. 나누어주다, 널리 펴다","on":"ハン","kun":"","explanation":["頒 = 分 + 頁。","(소리부 겸 의미부) 「分」(フン)은 “나누다”라는 뜻입니다.","(의미부) 「頁」는 “머리”를 뜻합니다.","頒는 “잘 생각해서(頁) 나누어주다(分)” -> “나누어주다, 널리 펴다”라는 뜻의 글자입니다.","(分는 소리부(フン -> ハン)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1946/"},"肢":{"id":1935,"char":"肢","hun":"팔다리 지","meaning":"“팔다리 지”. 팔다리, 사지","on":"シ","kun":"","explanation":["肢 = 月 + 支。","(의미부) 「月」는 “신체의 일부”를 뜻합니다.","(소리부 겸 의미부) 「支」(シ)는 “지탱하다, 지부”라는 뜻입니다.","肢는 “신체(月)에서 뻗어나온(支) 사지” -> “팔다리, 사지”라는 뜻의 글자입니다.","(支는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1947/"},"謄":{"id":1936,"char":"謄","hun":"베낄 등","meaning":"“베낄 등”. 베끼다, 복사하다","on":"トウ","kun":"","explanation":["謄 = 月 + 龹 + 言。","(소리부) 月+龹는 여기서는 「騰」(トウ)가 축약된 것으로, 소리부의 역할만 하고 있습니다.","(의미부) 「言」는 “말하다”라는 뜻입니다.","謄는 “말(言)을 그대로 받아적다” -> “베끼다, 복사하다”라는 뜻의 글자입니다(月+龹->騰는 소리부)."],"sourceUrl":"https://nihongokanji.com/1948/"},"嗣":{"id":1937,"char":"嗣","hun":"이을 사","meaning":"“이을 사”. 후사를 잇다","on":"シ","kun":"","explanation":["嗣 = 口 + 冊 + 司。","(의미부) 「口」는 “입”을 뜻합니다.","(의미부) 「冊」는 “책”을 뜻합니다.","(소리부 겸 의미부) 「司」(シ)는 “다스리다, 주관하다”라는 뜻입니다.","嗣는 “대를 이을 아들에게 책(冊)을 읽어주며(口) 직접 가르치다(司)” -> “후사를 잇다”라는 뜻의 글자입니다.","(司는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1949/"},"畝":{"id":1938,"char":"畝","hun":"이랑 묘","meaning":"“이랑 묘”. 이랑(토지 면적의 단위)","on":"","kun":"うね","explanation":["畝 = 亠 + 田 + 久。","「田」는 “밭”을 뜻합니다.","「久」는 “오래되다”라는 뜻입니다.","亠는 여기서는 “길이 측정용 자”를 그린 모양자입니다.","畝는 “오래 전(久) 부터 쓰여온, 밭(田)의 크기(亠)를 재는 단위” -> “이랑”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1950/"},"抄":{"id":1939,"char":"抄","hun":"뽑을 초","meaning":"“뽑을 초”. (일부를) 뽑아내다, (필요한 것만) 뽑아서 기록하다","on":"ショウ","kun":"","explanation":["抄 = 扌 + 少。","(의미부) 「扌」는 “손”을 뜻합니다.","(소리부 겸 의미부) 「少」(ショウ)는 “적다”라는 뜻입니다.","抄는 “조금만(少) 뽑아내다(扌)” -> “(일부를) 뽑아내다, (필요한 것만) 뽑아서 기록하다”라는 뜻의 글자입니다.","(少는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1951/"},"爽":{"id":1940,"char":"爽","hun":"시원할 상","meaning":"“시원할 상”. 시원하고 상쾌하다","on":"ソウ","kun":"さわ(やか)","explanation":["爽 = 大 + 爻 + 爻。","「大」는 “사람”을 그린 글자입니다.","양쪽의 爻는 여기서는 “수박”을 그린 모양자입니다.","爽는 “시원한 수박 네 덩이(爻爻)를 들고 온 사람(大)” -> “시원하고 상쾌하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1952/"},"惰":{"id":1941,"char":"惰","hun":"게으를 타","meaning":"“게으를 타”. 게으르다","on":"ダ","kun":"","explanation":["惰 = 忄 + 左 + 月。","(의미부) 「忄」는 “마음”을 뜻합니다.","(소리부) 「左」(サ)는 여기서는 소리부(サ -> ダ)의 역할만 하고 있습니다.","(의미부) 「月」는 “고기”를 뜻합니다.","惰는 “아무일도 안 하고 먹기만(月) 하는 게으른(忄) 놈” -> “게으르다”라는 뜻의 글자입니다(左는 소리부)."],"sourceUrl":"https://nihongokanji.com/1953/"},"蛮":{"id":1942,"char":"蛮","hun":"오랑캐 만","meaning":"“오랑캐 만”. 오랑캐, 야만, 미개","on":"バン","kun":"","explanation":["蛮 = 亦 + 虫。","「亦」는 “팔을 벌리고 걷는 사람”을 그린 글자입니다.","「虫」는 “벌레”를 뜻합니다.","蛮는 “벌레(虫)처럼 미개한 야만인(亦)” -> “오랑캐, 야만, 미개”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1954/"},"旺":{"id":1943,"char":"旺","hun":"왕성할 왕","meaning":"“왕성할 왕”. 왕성하다","on":"オウ","kun":"","explanation":["旺 = 日 + 王。","(의미부) 「日」는 “태양”을 뜻합니다.","(소리부 겸 의미부) 「王」(オウ)는 “왕, 제왕”을 뜻합니다.","旺는 “혈기가 넘치는(日) 젊은 왕(王)” -> “왕성하다”라는 뜻의 글자입니다.","(王는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1955/"},"壱":{"id":1944,"char":"壱","hun":"한 일","meaning":"“한 일”. 숫자 1(법률 문서 등에서 사용)","on":"イチ","kun":"","explanation":["壱는 법률 문서 등에서 혼동을 방지하기 위해 「一」 대신 쓰이는 글자입니다.","이 글자는 본래는 “술단지”를 그린 상형문자로, “1”이라는 뜻은 단순히 발음이 같다는 이유로 파생된 것입니다.","즉, 壱의 모양과 의미 사이에는 아무런 관계도 없습니다."],"sourceUrl":"https://nihongokanji.com/1956/"},"瑠":{"id":1945,"char":"瑠","hun":"맑은 유리 류","meaning":"“맑은 유리 류”. 유리","on":"ル","kun":"","explanation":["瑠 = 𤣩 + 留。","(의미부) 「𤣩」는 “구슬, 보석”을 뜻합니다.","(소리부) 「留」(ル)는 여기서는 소리부의 역할만 하고 있습니다.","瑠는 “투명한 유리구슬(𤣩)” -> “유리”라는 뜻의 글자입니다(留는 소리부)."],"sourceUrl":"https://nihongokanji.com/1957/"},"侯":{"id":1946,"char":"侯","hun":"제후 후","meaning":"“제후 후”. 제후, 후작","on":"コウ","kun":"","explanation":["侯는 “활을 당긴 채 조준하고 있는 사람”을 그린 글자로, 「候」(コウ)와 유래도 같고 음독도 같습니다(링크 참조).","“활을 쏘는 제후” -> “제후, 후작”이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/1958/"},"弧":{"id":1947,"char":"弧","hun":"활 호","meaning":"“활 호”. 호(곡선의 일부)","on":"コ","kun":"","explanation":["弧 = 弓 + 瓜。","(의미부) 「弓」는 “활”을 뜻합니다.","(소리부) 瓜는 여기서는 「孤」(コ)가 축약된 것으로, 소리부의 역할만 하고 있습니다.","弧는 “활(弓) 모양의 곡선” -> “호”라는 뜻의 글자입니다(瓜->孤는 소리부)."],"sourceUrl":"https://nihongokanji.com/1959/"},"附":{"id":1948,"char":"附","hun":"붙을 부","meaning":"“붙을 부”. 부속, 붙이다, 첨가하다","on":"フ","kun":"","explanation":["附 = ⻖ + 付。","(의미부) 「⻖」는 “언덕”을 뜻합니다.","(소리부 겸 의미부) 「付」(フ)는 “주다, 붙이다”라는 뜻입니다.","附는 “언덕(⻖)에 다닥다닥 붙어있는(付) 판자집” -> “부속, 붙이다, 첨가하다”라는 뜻의 글자입니다.","(付는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1960/"},"但":{"id":1949,"char":"但","hun":"다만 단","meaning":"“다만 단”. 다만, 조건부","on":"","kun":"ただ(し)","explanation":["但 = 亻 + 旦。","「亻」는 “사람”을 뜻합니다.","旦는 여기서는 “등에 진 봇짐”을 그린 모양자입니다.","但는 “짐(旦)을 들어주는(亻) 대신 조건이 있다” -> “다만, 조건부”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1961/"},"芋":{"id":1950,"char":"芋","hun":"토란 우","meaning":"“토란 우”. 감자, 토란","on":"","kun":"いも","explanation":["芋 = 艹 + 于。","「艹」는 “풀”을 뜻합니다.","于는 여기서는 “(감자의) 땅속줄기”를 그린 모양자입니다.","芋는 “감자의 원줄기(艹)와 땅속줄기(于)” -> “감자”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1962/"},"婆":{"id":1951,"char":"婆","hun":"할미 파","meaning":"“할미 파”. 할머니","on":"バ","kun":"","explanation":["婆 = 波 + 女。","(소리부 겸 의미부) 「波」(ハ)는 “물결, 파도”를 뜻합니다.","(의미부) 「女」는 “여자”를 뜻합니다.","婆는 “주름살(波) 투성이의 노파(女)” -> “할머니”라는 뜻의 글자입니다.","(波는 소리부(ハ -> バ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1963/"},"倣":{"id":1952,"char":"倣","hun":"본뜰 방","meaning":"“본뜰 방”. 모방하다, 본뜨다, 따르다","on":"ホウ","kun":"なら(う)","explanation":["倣 = 亻 + 放。","(의미부) 「亻」는 “사람”을 뜻합니다.","(소리부 겸 의미부) 「放」(ホウ)는 “내쫓다”라는 뜻입니다.","倣는 “자꾸 따라하는 사람(亻)을 내쫓아버리다(放)” -> “모방하다, 본뜨다, 따르다”라는 뜻의 글자입니다.","(放는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1964/"},"倹":{"id":1953,"char":"倹","hun":"검소할 검","meaning":"“검소할 검”. 검소한, 절약하는","on":"ケン","kun":"","explanation":["倹 = 亻 + 㑒。","(의미부) 「亻」는 “사람”을 뜻합니다.","(소리부 겸 의미부) 「㑒」(ケン)은 “날카롭다”라는 뜻입니다.","倹는 “돈 쓰는 데 민감한(㑒) 사람(亻)” -> “검소한, 절약하는”이라는 뜻의 글자입니다.","(㑒는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1965/"},"繭":{"id":1954,"char":"繭","hun":"고치 견","meaning":"“고치 견”. 고치","on":"ケン","kun":"まゆ","explanation":["繭 = 艹 + 巾 + 糸 + 虫。","「艹」는 “풀”을 뜻합니다.","「糸」는 “실”을 뜻합니다.","「虫」는 “벌레”를 뜻합니다.","巾는 여기서는 “(누에가 만든) 고치”를 그린 모양자입니다.","繭는 “누에(虫)가 뽕잎(艹)을 먹고 실(糸)을 뽑아 만든 고치(巾)” -> “고치”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1966/"},"且":{"id":1955,"char":"且","hun":"또 차","meaning":"“또 차”. 동시에, 또한","on":"","kun":"か(つ)","explanation":["且는 “비석”의 모습을 그린 상형문자입니다.","“제단에 여러 가지 음식을 동시에 올리다” -> “동시에, 또한” 이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/1967/"},"丙":{"id":1956,"char":"丙","hun":"셋째 천간 병","meaning":"“셋째 천간 병”. 병(‘갑을병’의 병)","on":"ヘイ","kun":"","explanation":["丙는 본래 “물고기의 꼬리”를 본따 그린 상형문자입니다.","그러나 이후 발음이 비슷하다는 이유로 “갑을병”의 “병”으로 쓰이게 된 것입니다.","즉, 丙의 모양과 의미 사이에는 아무런 관계도 없습니다."],"sourceUrl":"https://nihongokanji.com/1968/"},"伎":{"id":1957,"char":"伎","hun":"재간 기","meaning":"“재간 기”. 재주, 광대","on":"キ","kun":"","explanation":["伎 = 亻 + 支。","伎는 「技」에서 扌만 「亻」로 바꾼 글자입니다.","“재주(技)가 많은 사람(亻)” -> “재주, 광대”라는 의미입니다.","참고)","伎의 정식 음독은 キ이지만, 실제로는 아래의 伎ぎ楽がく와 같이 「ギ」로 읽는 단어도 꽤 있는 편입니다."],"sourceUrl":"https://nihongokanji.com/1969/"},"冶":{"id":1958,"char":"冶","hun":"풀무 야","meaning":"“풀무 야”. 주물, 제련","on":"ヤ","kun":"","explanation":["冶 = 冫 + 台。","「冫」는 “얼음”을 뜻합니다.","「台」는 “받침대”를 뜻합니다.","冶는 “금속을 녹인 다음 굳혀서(冫) 물건을 만드는 작업대(台)” -> “주물, 제련”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1970/"},"吏":{"id":1959,"char":"吏","hun":"벼슬아치 리","meaning":"“벼슬아치 리”. 관리","on":"リ","kun":"","explanation":["吏는 “제사를 지낼 때 쓰는 주술 도구를 든 손”을 그린 상형문자입니다.","“제사를 주관하는 제사장” -> “관리, 벼슬아치”라는 의미입니다.","참고)","「史」와 유래는 같으나 다른 글자입니다."],"sourceUrl":"https://nihongokanji.com/1971/"},"塑":{"id":1960,"char":"塑","hun":"흙 빚을 소","meaning":"“흙 빚을 소”. (흙을) 빚다","on":"ソ","kun":"","explanation":["塑 = 屰 + 月 + 土。","「屰」는 본래 “거꾸로 뒤집힌 사람”을 그린 글자입니다(링크 참조).","「月」는 “신체의 일부”를 뜻합니다.","「土」는 “흙”을 뜻합니다.","塑는 “흙(土)을 빚어서 사람(屰) 모양의 인형(月)을 만들다” -> “흙을 빚다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1972/"},"墾":{"id":1961,"char":"墾","hun":"개간할 간","meaning":"“개간할 간”. 개간하다","on":"コン","kun":"","explanation":["墾 = 貇 + 土。","貇는 “짐(豸)을 지고 있는 천민(艮)”을 그린 글자입니다(1292.「懇」 모양 해설 참조).","「土」는 “흙”을 뜻합니다.","墾는 “등에 짐을 진 채(貇) 열심히 땅을(土) 개간하고 있는 천민” -> “개간하다”라는 뜻의 글자입니다.","참고)","墾과 懇은 둘 다 「コン」을 음독으로 갖습니다."],"sourceUrl":"https://nihongokanji.com/1973/"},"弐":{"id":1962,"char":"弐","hun":"두 이","meaning":"“두 이”. 숫자 2","on":"ニ","kun":"","explanation":["弐는 「壱」와 마찬가지로 법률 문서 등에서 혼동을 방지하기 위해 「二」 대신 쓰는 글자입니다.","왼쪽 아래의 「二」는 “2”라는 뜻을 표현하기 위한 것이고, 나머지 부분은 장식으로 추가된 것입니다."],"sourceUrl":"https://nihongokanji.com/1974/"},"斤":{"id":1963,"char":"斤","hun":"도끼 근","meaning":"“도끼 근”. 도끼, 근(무게의 단위)","on":"キン","kun":"","explanation":["斤는 “도끼날(⺁)과 손잡이(丅)”를 그린 상형문자입니다.","“무거운 도끼” -> “도끼, 무게의 단위”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/1975/"},"旦":{"id":1964,"char":"旦","hun":"아침 단","meaning":"“아침 단”. 새벽, 아침","on":"タン、ダン","kun":"","explanation":["旦 = 日 + 一。","「日」는 “해”를 뜻합니다.","一는 여기서는 “지평선”을 그린 모양자입니다.","旦는 “아침해(日)가 지평선(一) 위로 떠오르다” -> “아침”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1976/"},"朕":{"id":1965,"char":"朕","hun":"나 짐","meaning":"“나 짐”. 짐(임금의 자칭)","on":"チン","kun":"","explanation":["朕 = 月 + 关。","「月」는 “달”을 뜻합니다.","「关」는 “웃음”을 뜻합니다.","朕는 “달(月)을 보며 웃는(关) 황제” -> “짐(임금의 자칭)”이라는 뜻의 글자입니다.","(朕을 처음 1인칭 대명사로 쓰기 시작한 황제는 진시황이라고 합니다.)"],"sourceUrl":"https://nihongokanji.com/1977/"},"汰":{"id":1966,"char":"汰","hun":"일 태","meaning":"“일 태”. 추려내다, (물에) 씻다","on":"タ","kun":"","explanation":["汰 = 氵 + 太。","(의미부) 「氵」는 “물”을 뜻합니다.","(소리부 겸 의미부) 「太」(タ)는 “크다”라는 뜻입니다.","汰는 “대량(太)의 알갱이를 물(氵)에 씻은 다음 깨끗한 것만 추려내다” -> “추려내다, 물에 씻다”라는 뜻의 글자입니다.","(太는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1978/"},"濫":{"id":1967,"char":"濫","hun":"넘칠 람","meaning":"“넘칠 람”. 넘치다, 범람하다","on":"ラン","kun":"","explanation":["濫 = 氵 + 監。","(의미부) 「氵」는 “물”을 뜻합니다.","(소리부 겸 의미부) 「監」(カン)은 본래 “그릇을 내려다보는 눈”을 그린 글자입니다(링크 참조).","濫는 “그릇의 물(氵)이 넘치지는 않는지 살펴보다(監)” -> “넘치다, 범람하다”라는 뜻의 글자입니다.","(監는 소리부(カン -> ラン)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1979/"},"爵":{"id":1968,"char":"爵","hun":"벼슬 작","meaning":"“벼슬 작”. 작위, 벼슬","on":"シャク","kun":"","explanation":["爵 = ⺤ + 罒 + 皀 + 寸。","「⺤」는 “손”을 뜻합니다.","罒는 여기서는 “(머리에 쓰는) 관”을 그린 모양자입니다.","皀는 여기서는 “술잔”을 그린 모양자입니다.","「寸」는 “손”을 뜻합니다.","爵는 “머리에 관(罒)을 쓰고(⺤) 왕이 따라주는(寸) 술잔(皀)을 받으며 작위를 수여받다” -> “작위, 벼슬”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1980/"},"璃":{"id":1969,"char":"璃","hun":"유리 리","meaning":"“유리 리”. 유리","on":"リ","kun":"","explanation":["璃 = 𤣩 + 离。","(의미부) 「𤣩」는 “구슬, 보석”을 뜻합니다.","(소리부) 离는 여기서는 「離」(リ)가 축약된 것으로, 소리부의 역할만 하고 있습니다.","璃는 “유리구슬(𤣩)” -> “유리”라는 뜻의 글자입니다(离->離는 소리부)."],"sourceUrl":"https://nihongokanji.com/1981/"},"痘":{"id":1970,"char":"痘","hun":"역질 두","meaning":"“역질 두”. 마마, 천연두","on":"トウ","kun":"","explanation":["痘 = 疒 + 豆。","(의미부) 「疒」는 “병, 질병”을 뜻합니다.","(소리부 겸 의미부) 「豆」(トウ)는 “콩”을 뜻합니다.","痘는 “콩(豆) 모양의 발진과 수포가 생기는 병(疒)” -> “마마, 천연두”라는 뜻의 글자입니다.","(豆는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1982/"},"瞭":{"id":1971,"char":"瞭","hun":"밝을 료","meaning":"“밝을 료”. 명료한, 분명한","on":"リョウ","kun":"","explanation":["瞭 = 目 + 尞。","(의미부) 「目」는 “눈”을 뜻합니다.","(소리부 겸 의미부) 「尞」(リョウ)는 “횃불”을 그린 글자입니다.","瞭는 “선명히 보이는(目) 밝게 타오르는 횃불(尞)” -> “명료한, 분명한”이라는 뜻의 글자입니다.","(尞는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1983/"},"箇":{"id":1972,"char":"箇","hun":"낱 개","meaning":"“낱 개”. 개수(셈을 할 때 사용)","on":"カ","kun":"","explanation":["箇 = 𥫗 + 固。","(의미부) 「𥫗」는 “대나무”를 뜻합니다.","(소리부 겸 의미부) 「固」(コ)는 “딱딱하다”라는 뜻입니다. 여기서는 “딱딱하다” -> “개체”라는 뜻으로 쓰인 것입니다.","먼 옛날에는 셈을 할 때 대나무로 만든 “산가지”라는 도구를 이용했다고 합니다.","箇는 “산가지(𥫗)로 개수(固)를 세다” -> “개수”라는 뜻의 글자입니다.","(固는 소리부(コ -> カ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1984/"},"耗":{"id":1973,"char":"耗","hun":"소모할 모","meaning":"“소모할 모”. 소모되다","on":"モウ、コウ","kun":"","explanation":["耗 = 耒 + 毛。","(의미부) 「耒」는 “쟁기”를 그린 글자입니다.","(소리부 겸 의미부) 「毛」(モウ)는 여기서는 “쟁기(耒)의 이가 나가고 휘어진 모습”을 그린 모양자로 쓰인 것입니다.","耗는 “오래 써서 닳고 휘어진(毛) 쟁기(耒)” -> “소모되다”라는 뜻의 글자입니다.","(毛는 소리부(モウ -> モウ・コウ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1985/"},"虞":{"id":1974,"char":"虞","hun":"염려할 우","meaning":"“염려할 우”. 우려하다, 근심하다","on":"","kun":"おそれ","explanation":["虞 = 虍 + 呉。","「虍」는 “호랑이”를 뜻합니다.","「呉」는 “머리가 기울어진 사람”을 그린 글자입니다.","虞는 “호랑이(虍)를 걱정하며 고개를 젓는 사람(呉)” -> “우려하다, 근심하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1986/"},"謁":{"id":1975,"char":"謁","hun":"뵐 알","meaning":"“뵐 알”. 알현하다, 배알하다","on":"エツ","kun":"","explanation":["謁 = 言 + 曷。","(의미부) 「言」는 “말하다”라는 뜻입니다.","(소리부 겸 의미부) 「曷」(カツ)는 “허리를 굽히고 구걸하는 사람”을 그린 글자입니다.","謁는 “윗사람을 찾아뵙고 허리를 굽히며(曷) 인사를 올리다(言)” -> “알현하다, 배알하다”라는 뜻의 글자입니다.","(曷는 소리부(カツ -> エツ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1987/"},"賦":{"id":1976,"char":"賦","hun":"부세 부","meaning":"“부세 부”. 부과하다","on":"フ","kun":"","explanation":["賦 = 貝 + 武。","(의미부) 「貝」는 “돈, 재물”을 뜻합니다.","(소리부 겸 의미부) 「武」(ブ)는 “무력”을 뜻합니다.","賦는 “무력(武)을 앞세워 강제로 세금(貝)을 부과하다” -> “부과하다”라는 뜻의 글자입니다.","(武는 소리부(ブ -> フ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1988/"},"遵":{"id":1977,"char":"遵","hun":"좇을 준","meaning":"“좇을 준”. (법칙/규칙 등을) 따르다, 준수하다","on":"ジュン","kun":"","explanation":["遵 = ⻌ + 尊。","(의미부) 「⻌」는 “길”을 뜻합니다.","(소리부 겸 의미부) 「尊」(ソン)은 “존경하다”라는 뜻입니다.","尊는 “존경하는(尊) 사람의 뒤를 따르다(⻌)” -> “따르다, 준수하다”라는 뜻의 글자입니다.","(尊는 소리부(ソン -> ジュン)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1989/"},"采":{"id":1978,"char":"采","hun":"풍채 채","meaning":"“풍채 채”. 풍채, 모습","on":"サイ","kun":"","explanation":["采 = ⺤ + 木。","「⺤」는 “손”을 뜻합니다.","「木」는 “나무”를 뜻합니다.","采는 “나무열매(木)를 따는(⺤) 모습” -> “풍채, 모습”이라는 뜻의 글자입니다.","참고)","采의 본래 뜻은 “따다, 뽑다”였습니다(모양자 「采」 참조).","그러나 이후 采가 “풍채, 모습”이라는 뜻으로 바뀌어 쓰이기 시작하면서, 「採」가 새로 만들어져 “뽑다”라는 뜻을 대신하게 된 것입니다."],"sourceUrl":"https://nihongokanji.com/1990/"},"璽":{"id":1979,"char":"璽","hun":"옥새 새","meaning":"“옥새 새”. 옥새","on":"ジ","kun":"","explanation":["璽 = 爾 + 玉。","「玉」는 “구슬, 보석”을 뜻합니다.","爾는 여기서는 “옥새로 찍은 도장”의 복잡한 문양을 표현한 모양자입니다.","璽는 “임금이 도장(爾)을 찍을 때 쓰는 귀중한 보물(玉)” -> “옥새”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1991/"},"挨":{"id":1980,"char":"挨","hun":"밀칠 애","meaning":"“밀칠 애”. 다가오다","on":"アイ","kun":"","explanation":["挨 = 扌 + 厶 + 矢。","「扌」는 “손”을 뜻합니다.","「矢」는 “화살”을 뜻합니다.","厶는 여기서는 “화살촉”을 강조해서 그린 모양자입니다.","挨는 “화살(矢)이 손(扌)으로 날아와 꽂히다(厶)” -> “다가오다”라는 뜻의 글자입니다.","참고)","이 한자는 실제로는 「挨拶あいさつ」(인사) 외에는 거의 쓰이지 않는 글자입니다."],"sourceUrl":"https://nihongokanji.com/1992/"},"宛":{"id":1981,"char":"宛","hun":"주소, ~앞으로 보내다","meaning":"주소, ~앞으로 보내다","on":"","kun":"あ(てる)","explanation":["宛 = 宀 + 夕 + 㔾。","「宀」는 “집”을 뜻합니다.","「夕」는 “저녁”을 뜻합니다.","「㔾」는 “무릎꿇은 사람”을 뜻합니다.","宛는 “저녁(夕)에 집(宀)에서 뒹굴거리고(㔾) 있는데 편지가 오다” -> “주소, ~앞으로 보내다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1993/"},"闇":{"id":1982,"char":"闇","hun":"숨을 암","meaning":"“숨을 암”. 어둡다, 암흑","on":"","kun":"やみ","explanation":["闇 = 門 + 音。","「門」는 “문”을 뜻합니다.","「音」는 “소리”를 뜻합니다.","闇는 “문(門)이 닫히고 소리(音)밖에 들리지 않는 어두침침한 곳” -> “어둡다, 암흑”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1994/"},"椅":{"id":1983,"char":"椅","hun":"의자 의","meaning":"“의자 의”. 의자","on":"イ","kun":"","explanation":["椅 = 木 + 奇。","(의미부) 「木」는 “나무”를 뜻합니다.","(소리부 겸 의미부) 「奇」(キ)는 본래 “짐보따리를 든 사람”을 그린 글자입니다(링크 참조).","椅는 “짐을 든 나그네(奇)가 나무등걸(木)에 걸터앉아 쉬다” -> “의자”라는 뜻의 글자입니다.","(奇는 소리부(キ -> イ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/1995/"},"畏":{"id":1984,"char":"畏","hun":"두려워할 외","meaning":"“두려워할 외”. 두려워하다, 공경하다","on":"イ","kun":"おそ(れる)","explanation":["畏는 “가면(田)을 쓴 제사장이 주술 도구를 들고 제사를 지내는 모습”을 그린 상형문자입니다.","“절대적 권위를 가진 제사장” -> “두려워하다, 공경하다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/1996/"},"萎":{"id":1985,"char":"萎","hun":"시들 위","meaning":"“시들 위”. 시들다, 생기를 잃다","on":"イ","kun":"な(える)","explanation":["萎 = 艹 + 委。","(의미부) 「艹」는 “풀”을 뜻합니다.","(소리부 겸 의미부) 「委」(イ)는 “맡기다, 위임하다”라는 뜻입니다.","萎는 “남에게 잠시 맡겨둔(委) 화초(艹)가 시들어버리다” -> “시들다”라는 뜻의 글자입니다.","(委는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1997/"},"茨":{"id":1986,"char":"茨","hun":"가시나무","meaning":"가시나무","on":"","kun":"いばら","explanation":["茨 = 艹 + 次。","「艹」는 “풀”을 뜻합니다.","「次」는 “다음”을 뜻합니다.","茨는 “아무리 나아가도(次) 끝이 없는 가시밭길(艹)” -> “가시나무”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/1998/"},"咽":{"id":1987,"char":"咽","hun":"목구멍 인","meaning":"“목구멍 인”. 목구멍","on":"イン","kun":"","explanation":["咽 = 口 + 因。","(의미부) 「口」는 “입”을 뜻합니다.","(소리부 겸 의미부) 「因」(イン)은 여기서는 “(입 안쪽의) 목구멍”을 그린 모양자로 쓰인 것입니다.","咽는 “입(口) 안쪽의 목구멍(因)” -> “목구멍”이라는 뜻의 글자입니다.","(因는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/1999/"},"淫":{"id":1988,"char":"淫","hun":"음란할 음","meaning":"“음란할 음”. 음란하다","on":"イン","kun":"みだ(ら)","explanation":["淫 = 氵 + 爫 + 壬。","「氵」는 “물”을 뜻합니다.","「爫」는 “손”을 뜻합니다.","壬는 여기서는 「王」가 변형된 것으로, “왕”을 뜻합니다.","淫는 “주색(氵)잡기(爫)에 빠진 음탕한 왕(壬)” -> “음란하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/2000/"},"臼":{"id":1989,"char":"臼","hun":"절구 구","meaning":"“절구 구”. 절구","on":"キュウ","kun":"うす","explanation":["臼는 “절구”를 그린 상형문자입니다."],"sourceUrl":"https://nihongokanji.com/2001/"},"餌":{"id":1990,"char":"餌","hun":"미끼 이","meaning":"“미끼 이”. 미끼","on":"ジ","kun":"えさ、え","explanation":["餌 = 食 + 耳。","(의미부) 왼쪽 글자는 「食」가 변형된 것으로, “먹다”라는 뜻입니다.","(소리부) 「耳」(ジ)는 여기서는 소리부의 역할만 하고 있습니다.","餌는 “미끼로 던진 먹이(食)” -> “미끼”라는 뜻의 글자입니다(耳는 소리부)."],"sourceUrl":"https://nihongokanji.com/2002/"},"怨":{"id":1991,"char":"怨","hun":"원망할 원","meaning":"“원망할 원”. 원망하다","on":"エン、オン","kun":"","explanation":["怨 = 夕 + 㔾 + 心。","「夕」는 “저녁”을 뜻합니다.","「㔾」는 “무릎꿇은 사람”을 뜻합니다.","「心」는 “마음”을 뜻합니다.","怨은 “밤늦게까지(夕) 잠 못 이루고 원통해하며(心) 바닥을 구르다(㔾)” -> “원망하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/2003/"},"岡":{"id":1992,"char":"岡","hun":"산등성이 강","meaning":"“산등성이 강”. 언덕(인명/지명한자)","on":"","kun":"おか","explanation":["岡 = 𦉰 + 山。","𦉰는 「罒」가 변형된 것으로, “쇠그물”을 뜻합니다.","「山」는 “산”을 뜻합니다.","岡는 “쇠그물(𦉰)이 쳐진 작은 산(山)” -> “언덕”이라는 뜻의 글자입니다.","(다만, 이 한자는 현재는 지명 혹은 인명에만 쓰이는 글자입니다.)"],"sourceUrl":"https://nihongokanji.com/2004/"},"臆":{"id":1993,"char":"臆","hun":"가슴 억","meaning":"“가슴 억”. 가슴, 마음, 겁내다","on":"オク","kun":"","explanation":["臆 = 月 + 意。","(의미부) 「月」는 “신체의 일부”를 뜻합니다.","(소리부 겸 의미부) 意는 여기서는 「憶」(オク)가 축약된 것으로, “기억”을 뜻합니다.","臆는 “가슴속(月)에 남아있는 무서운 기억(憶)” -> “가슴, 마음, 겁내다”라는 뜻의 글자입니다.","(意->憶는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/2005/"},"俺":{"id":1994,"char":"俺","hun":"나 암","meaning":"“나 암”. 나(남성의 1인칭)","on":"","kun":"おれ","explanation":["俺 = 亻 + 大 + 电。","「亻」는 “사람”을 뜻합니다.","「大」는 “크다”라는 뜻입니다.","「电」는 “번개”를 뜻합니다.","俺는 “번개(电)처럼 크고 강한(大) 남성(亻)” -> “나(남성의 1인칭)”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/2006/"},"苛":{"id":1995,"char":"苛","hun":"가혹할 가","meaning":"“가혹할 가”. 가혹하다","on":"カ","kun":"","explanation":["苛 = 艹 + 可。","(의미부) 「艹」는 “풀”을 뜻합니다.","(소리부) 「可」(カ)는 여기서는 소리부의 역할만 하고 있습니다.","苛는 “날카로운 가시덤불(艹)” -> “가혹하다”라는 뜻의 글자입니다(可는 소리부)."],"sourceUrl":"https://nihongokanji.com/2007/"},"牙":{"id":1996,"char":"牙","hun":"어금니 아","meaning":"“어금니 아”. 이, 엄니","on":"ガ、ゲ","kun":"きば","explanation":["牙는 “동물의 이가 서로 맞물리는 모습”을 그린 상형문자입니다."],"sourceUrl":"https://nihongokanji.com/2008/"},"崖":{"id":1997,"char":"崖","hun":"언덕 애","meaning":"“언덕 애”. 낭떠러지, 벼랑","on":"ガイ","kun":"がけ","explanation":["崖 = 山 + 厓。","(의미부) 「山」는 “산”을 뜻합니다.","(소리부 겸 의미부) 厓는 여기서는 「涯」(ガイ)가 축약된 것으로, “가장자리, 끝, 한계”를 뜻합니다.","崖는 “산맥(山) 가장자리(涯)의 낭떠러지” -> “낭떠러지, 벼랑”이라는 뜻의 글자입니다.","(厓->涯는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/2009/"},"蓋":{"id":1998,"char":"蓋","hun":"덮을 개","meaning":"“덮을 개”. 뚜껑, 덮개, 덮다","on":"ガイ","kun":"ふた","explanation":["蓋 = 艹 + 土 + 厶 + 皿。","「艹」는 “풀”을 뜻합니다.","「土」는 “땅”을 뜻합니다.","厶는 여기서는 “그릇의 뚜껑”을 그린 모양자입니다.","「皿」는 “그릇, 접시”를 뜻합니다.","蓋는 “그릇(皿)의 뚜껑(厶)을 닫아 땅(土) 속에 묻고 풀(艹)로 덮어두다” -> “뚜껑, 덮개, 덮다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/2010/"},"骸":{"id":1999,"char":"骸","hun":"뼈 해","meaning":"“뼈 해”. 뼈, 해골, 백골","on":"ガイ","kun":"","explanation":["骸 = 骨 + 亥。","「骨」는 “뼈”를 뜻합니다.","「亥」는 “도축, 가공된 돼지”를 뜻합니다.","骸는 “깔끔하게 해체되어(亥) 뼈만(骨) 남은 돼지” -> “뼈, 해골, 백골”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/2011/"},"柿":{"id":2000,"char":"柿","hun":"감나무 시","meaning":"“감나무 시”. 감나무, 감","on":"","kun":"かき","explanation":["柿 = 木 + 市。","(의미부) 「木」는 “나무”를 뜻합니다.","(소리부) 「市」(シ)는 여기서는 소리부의 역할만 하고 있습니다.","(柿에는 정식 음독이 없으나, 본래의 음독은 シ입니다.)","柿는 “감이 열리는 나무(木)” -> “감나무”라는 뜻의 글자입니다(市는 소리부)."],"sourceUrl":"https://nihongokanji.com/2012/"},"顎":{"id":2001,"char":"顎","hun":"턱 악","meaning":"“턱 악”. 턱","on":"ガク","kun":"あご","explanation":["顎 = 咢 + 頁。","「頁」는 “머리”를 뜻합니다.","咢는 “콧구멍(吅), 입(一), 턱(丂)”을 그린 모양자입니다.","顎는 “얼굴(頁) 아래쪽의 턱(咢)” -> “턱”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/2013/"},"葛":{"id":2002,"char":"葛","hun":"칡 갈","meaning":"“칡 갈”. 칡","on":"カツ","kun":"くず","explanation":["葛 = 艹 + 曷。","(의미부) 「艹」는 “풀”을 뜻합니다.","(소리부 겸 의미부) 「曷」(カツ)는 “허리를 굽혀 구걸하는 모습”을 그린 글자입니다.","葛는 “칡뿌리(艹)를 캐먹으며 연명하는 거지(曷)” -> “칡”이라는 뜻의 글자입니다.","(曷는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/2014/"},"釜":{"id":2003,"char":"釜","hun":"가마 부","meaning":"“가마 부”. 가마, 솥","on":"","kun":"かま","explanation":["釜 = 父 + 金。","「金」는 “쇠, 금속”을 뜻합니다.","父는 여기서는 “솥뚜껑”을 그린 모양자로 쓰인 것입니다.","釜는 “무쇠(金)로 된 솥뚜껑(父)” -> “가마, 솥”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/2015/"},"瓦":{"id":2004,"char":"瓦","hun":"기와 와","meaning":"“기와 와”. 기와","on":"ガ","kun":"かわら","explanation":["瓦는 “기왓장이 맞물려있는 모습”을 그린 상형문자입니다."],"sourceUrl":"https://nihongokanji.com/2016/"},"韓":{"id":2005,"char":"韓","hun":"한국 한","meaning":"“한국 한”. 한국","on":"カン","kun":"","explanation":["韓 = 𠦝 + 韋。","「𠦝」는 “떠오르는 아침해”를 그린 글자입니다.","「韋」는 “성 주위를 돌며 경계서는 발들”을 그린 글자입니다.","韓는 “떠오르는 아침해(𠦝)가 성(韋)을 비추다”라는 뜻입니다.","“아침의 나라” -> “조선” -> “한국”이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/2017/"},"玩":{"id":2006,"char":"玩","hun":"희롱할 완","meaning":"“희롱할 완”. 장난감, 즐기다","on":"ガン","kun":"","explanation":["玩 = 𤣩 + 元。","(의미부) 「𤣩」는 “구슬, 보석”을 뜻합니다.","(소리부) 「元」(ガン)은 여기서는 소리부의 역할만 하고 있습니다.","玩는 “구슬(𤣩)을 가지고 놀다” -> “장난감, 즐기다”라는 뜻의 글자입니다(元는 소리부)."],"sourceUrl":"https://nihongokanji.com/2018/"},"畿":{"id":2007,"char":"畿","hun":"경기 기","meaning":"“경기 기”. 수도 주위의 땅(지명한자)","on":"キ","kun":"","explanation":["畿 = 幾 + 田。","(소리부) 「幾」(キ)는 여기서는 소리부의 역할만 하고 있습니다.","(의미부) 「田」는 “밭”을 뜻합니다.","畿는 “수도 외곽의 곡창지대(田)” -> “수도 주변, 경기”라는 뜻의 글자입니다(幾는 소리부).","(이 한자는 지명한자로만 쓰이는 글자입니다.)"],"sourceUrl":"https://nihongokanji.com/2019/"},"僅":{"id":2008,"char":"僅","hun":"겨우 근","meaning":"“겨우 근”. 약간, 조금, 겨우","on":"キン","kun":"わず(か)","explanation":["僅 = 亻 + 堇。","(의미부) 「亻」는 “사람”을 뜻합니다.","(소리부 겸 의미부) 「堇」(キン)은 “처벌, 형벌”을 뜻합니다.","僅는 “처형(堇)당하기 직전인 사람(亻)”이라는 뜻입니다.","“죽기 직전이다, 살 날이 얼마 남지 않다” -> “약간, 조금, 겨우”라는 의미입니다.","(堇는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/2020/"},"巾":{"id":2009,"char":"巾","hun":"수건 건","meaning":"“수건 건”. 수건","on":"キン","kun":"","explanation":["巾은 “장대에 걸린 수건”의 모습을 그린 상형문자입니다."],"sourceUrl":"https://nihongokanji.com/2021/"},"串":{"id":2010,"char":"串","hun":"꼬챙이 관","meaning":"“꼬챙이 관”. 꼬챙이, 꼬치","on":"","kun":"くし","explanation":["串는 “꼬챙이에 꿰인 떡”을 그린 상형문자입니다."],"sourceUrl":"https://nihongokanji.com/2022/"},"窟":{"id":2011,"char":"窟","hun":"굴 굴","meaning":"“굴 굴”. 굴, 동굴","on":"クツ","kun":"","explanation":["窟 = 穴 + 屈。","(의미부) 「穴」는 “구멍”을 뜻합니다.","(소리부 겸 의미부) 「屈」(クツ)는 “굽히다”라는 뜻입니다.","窟는 “허리를 굽혀(屈) 굴(穴) 속으로 들어가다” -> “굴, 동굴”이라는 뜻의 글자입니다.","(屈는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/2023/"},"稽":{"id":2012,"char":"稽","hun":"상고할 계","meaning":"“상고할 계”. 자세히 생각하다, 고려하다, 헤아리다","on":"ケイ","kun":"","explanation":["稽 = 禾 + 尤 + 旨。","「禾」는 “곡식”을 뜻합니다.","尤는 여기서는 “짐을 메고 걷는 사람”을 그린 모양자입니다(1083.「就」 모양 해설 참조).","「旨」는 “뜻, 취지”를 뜻합니다.","稽는 “수확한 곡식(禾)을 들쳐메고 걷는 농부(尤)의 생각(旨)”이라는 뜻입니다.","“곡식을 누구에게 얼마에 팔지 고민하다” -> “자세히 생각하다, 고려하다, 헤아리다”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/2024/"},"詣":{"id":2013,"char":"詣","hun":"이를 예","meaning":"“이를 예”. 이르다, 도달하다, 참배하다","on":"ケイ","kun":"もう(でる)","explanation":["詣 = 言 + 旨。","「言」는 “말하다”라는 뜻입니다.","「旨」는 “뜻, 취지”라는 뜻입니다.","詣는 “뜻(旨)을 말하다(言)”라는 뜻입니다.","“깊은 뜻(旨)을 말(言)로 풀어낼 수 있는 경지에 도달하다” -> “이르다, 도달하다”","“신단에 참배하며 신령에 자신의 뜻(旨)을 아뢰다(言)” -> “참배하다”","라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/2025/"},"隙":{"id":2014,"char":"隙","hun":"틈 극","meaning":"“틈 극”. 틈, 간극","on":"ゲキ","kun":"すき","explanation":["隙 = ⻖ + 小 + 日 + 小。","「⻖」는 “언덕”을 뜻합니다.","「小」는 “작다”라는 뜻입니다.","「日」는 “태양”을 뜻합니다.","隙는 “언덕(⻖) 사이사이의 작은(小小) 틈새로 비쳐 들어오는 햇빛(日)” -> “틈, 간극”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/2026/"},"桁":{"id":2015,"char":"桁","hun":"자릿수, 규모","meaning":"자릿수, 규모","on":"","kun":"けた","explanation":["桁 = 木 + 行。","「木」는 “나무”를 뜻합니다.","「行」는 “가로(행)”을 뜻합니다.","桁는 본래 “가로질러 놓은 나무(횡목)”라는 뜻으로 만들어진 글자입니다.","늘어서 있는 각각의 횡목을 숫자의 “자릿수”에 해당하는 위치로 비유한 것입니다.","“나란히 늘어선 횡목” -> “자릿수” -> “규모”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/2027/"},"鍵":{"id":2016,"char":"鍵","hun":"열쇠 건","meaning":"“열쇠 건”. 열쇠","on":"ケン","kun":"かぎ","explanation":["鍵 = 金 + 建。","(의미부) 「金」는 “쇠, 금속”을 뜻합니다.","(소리부 겸 의미부) 「建」(ケン)은 “세우다, 건설하다”라는 뜻입니다.","鍵는 “건물(建)의 문을 열 수 있는 열쇠(金)” -> “열쇠”라는 뜻의 글자입니다.","(建는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/2028/"},"舷":{"id":2017,"char":"舷","hun":"뱃전 현","meaning":"“뱃전 현”. 뱃전(배의 양쪽 가장자리 부분)","on":"ゲン","kun":"","explanation":["舷 = 舟 + 玄。","(의미부) 「舟」는 “배”를 뜻합니다.","(소리부) 「玄」(ゲン)은 여기서는 소리부의 역할만 하고 있습니다.","舷은 “배(舟)의 옆면” -> “뱃전”이라는 뜻의 글자입니다(玄는 소리부)."],"sourceUrl":"https://nihongokanji.com/2029/"},"股":{"id":2018,"char":"股","hun":"넓적다리 고","meaning":"“넓적다리 고”. 넓적다리","on":"コ","kun":"また","explanation":["股 = 月 + 殳。","「月」는 “신체의 일부”를 뜻합니다.","「殳」는 “때리다, 휘두르다”라는 뜻입니다.","股는 “살이 많아 때리기(殳) 좋은 신체부위(月)” -> “넓적다리”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/2030/"},"乞":{"id":2019,"char":"乞","hun":"빌 걸","meaning":"“빌 걸”. 빌다, 구걸하다","on":"","kun":"こ(う)","explanation":["乞는 “무릎꿇고(乙) 손을 올려(𠂉) 구걸하는 사람”을 그린 상형문자입니다."],"sourceUrl":"https://nihongokanji.com/2031/"},"勾":{"id":2020,"char":"勾","hun":"굽을 구","meaning":"“굽을 구”. 굽다","on":"コウ","kun":"","explanation":["勾 = 勹 + 厶。","勾는 구부러진 모양의 글자 두 개(勹+厶)를 합쳐서 “굽다”라는 뜻을 표현한 글자입니다."],"sourceUrl":"https://nihongokanji.com/2032/"},"喉":{"id":2021,"char":"喉","hun":"목구멍 후","meaning":"“목구멍 후”. 목구멍, 인후","on":"コウ","kun":"のど","explanation":["喉 = 口 + 侯。","(의미부) 「口」는 “입”을 뜻합니다.","(소리부) 「侯」(コウ)는 여기서는 소리부의 역할만 하고 있습니다.","喉는 “입(口) 안쪽의 구멍” -> “목구멍, 인후”라는 뜻의 글자입니다(侯는 소리부)."],"sourceUrl":"https://nihongokanji.com/2033/"},"梗":{"id":2022,"char":"梗","hun":"줄기/막힐 경","meaning":"“줄기/막힐 경”. 줄기, 막히다","on":"コウ","kun":"","explanation":["梗 = 木 + 更。","(의미부) 「木」는 “나무”를 뜻합니다.","(소리부 겸 의미부) 「更」(コウ)는 “고치다”라는 뜻입니다.","梗는 “상처를 입어 막힌 나무줄기(木)를 잘라내 고치다(更)” -> “줄기, 막히다”라는 뜻의 글자입니다(更는 소리부)."],"sourceUrl":"https://nihongokanji.com/2034/"},"頃":{"id":2023,"char":"頃","hun":"이랑 경","meaning":"“이랑 경”. 때, 경, 무렵, 쯤, 시절","on":"","kun":"ころ","explanation":["頃 = 匕 + 頁。","「匕」는 “숟가락”을 뜻합니다.","「頁」는 “머리”를 뜻합니다.","頃는 “숟가락(匕)을 입으로(頁) 가져가다”라는 뜻입니다.","“식사할 때가 되다” -> “때, 경, 무렵, 쯤, 시절”이라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/2035/"},"痕":{"id":2024,"char":"痕","hun":"흔적 흔","meaning":"“흔적 흔”. 흔적, 자국, 흉터","on":"コン","kun":"あと","explanation":["痕 = 疒 + 艮。","(의미부) 「疒」는 “병, 질병”을 뜻합니다.","(소리부 겸 의미부) 「艮」(コン)은 “몸을 웅크린 천민”을 뜻합니다.","痕는 “천민(艮)의 등에 난 채찍 자국(疒)” -> “흔적, 자국, 흉터”라는 뜻의 글자입니다.","(艮는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/2036/"},"挫":{"id":2025,"char":"挫","hun":"꺾을 좌","meaning":"“꺾을 좌”. 꺾다, 꺾이다","on":"ザ","kun":"","explanation":["挫 = 扌 + 坐。","(의미부) 「扌」는 “손”을 뜻합니다.","(소리부 겸 의미부) 坐는 「座」(ザ)가 축약된 것으로, “앉다”라는 뜻입니다.","挫는 “땅에 손을 짚고(扌) 주저앉아(座) 좌절하다” -> “꺾다, 꺾이다”라는 뜻의 글자입니다.","(坐->座는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/2037/"},"塞":{"id":2026,"char":"塞","hun":"변방 새/막힐 색","meaning":"“변방 새/막힐 색”. 변방, 요새, 막히다","on":"ソク、サイ","kun":"ふさ(ぐ)、ふさ(がる)","explanation":["塞 = 𡨄 + 土。","𡨄는 여기서는 「寒」가 축약된 것으로, “춥다”라는 뜻입니다.","「土」는 “흙, 땅”을 뜻합니다.","塞는 “추운(寒) 변방의 고립된 땅(土)” -> “변방, 요새, 막히다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/2038/"},"阪":{"id":2027,"char":"阪","hun":"언덕 판","meaning":"“언덕 판”. 경사면, 비탈(지명한자)","on":"ハン","kun":"さか","explanation":["阪는 「坂」(ハン)에서 土만 「阝」로 바뀐 글자로, 음독도 훈독도 의미도 전부 같습니다.","“언덕(阝)의 비탈길(坂)” -> “경사면, 비탈”이라는 의미입니다.","(다만, 阪는 실제로는 거의 지명한자로만 쓰이는 글자입니다.)"],"sourceUrl":"https://nihongokanji.com/2039/"},"埼":{"id":2028,"char":"埼","hun":"갑 기","meaning":"“갑 기”. 곶, 산부리(지명한자)","on":"","kun":"さい","explanation":["埼 = 土 + 奇。","「土」는 “땅”을 뜻합니다.","「奇」는 “기묘한, 진기한”이라는 뜻입니다.","埼는 “기묘하게(奇) 튀어나온 땅(土)” -> “곶, 산부리”라는 뜻의 글자입니다.","(다만, 이 한자는 실제로는 지명한자로만 쓰이는 글자입니다.)"],"sourceUrl":"https://nihongokanji.com/2040/"},"柵":{"id":2029,"char":"柵","hun":"울타리 책","meaning":"“울타리 책”. 울타리","on":"サク","kun":"","explanation":["柵 = 木 + 冊。","(의미부) 「木」는 “나무”를 뜻합니다.","(소리부 겸 의미부) 「冊」(サク)는 여기서는 “울타리”를 그린 모양자로 쓰인 것입니다.","柵는 “나무(木)로 만든 울타리(冊)” -> “울타리”라는 뜻의 글자입니다.","(冊는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/2041/"},"拶":{"id":2030,"char":"拶","hun":"인사, 인사말","meaning":"인사, 인사말","on":"サツ","kun":"","explanation":["拶 = 扌 + 巛 + 夕。","「扌」는 “손”을 뜻합니다.","巛는 “흐르는 물살”을 그린 모양자입니다.","「夕」는 “저녁”을 뜻합니다.","拶는 “썰물이 빠지는(巛) 저녁에(夕) 손을 흔들어(扌) 작별 인사를 하다” -> “인사”라는 뜻의 글자입니다.","참고)","이 한자는 실제로는 「挨拶あいさつ」(인사) 외에는 거의 쓰이지 않는 글자입니다."],"sourceUrl":"https://nihongokanji.com/2042/"},"斬":{"id":2031,"char":"斬","hun":"벨 참","meaning":"“벨 참”. 베다, 베어 죽이다","on":"ザン","kun":"き(る)","explanation":["斬 = 車 + 斤。","「車」는 “수레, 차”를 뜻합니다.","「斤」는 “도끼”를 뜻합니다.","斬는 “전차(車)를 타고 도끼(斤)로 적들을 베어 죽이다” -> “베다, 베어 죽이다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/2043/"},"叱":{"id":2032,"char":"叱","hun":"꾸짖을 질","meaning":"“꾸짖을 질”. 꾸짖다, 야단치다","on":"シツ","kun":"しか(る)","explanation":["叱 = 口 + 𠤎。","(의미부) 「口」는 “입”을 뜻합니다.","(소리부 겸 의미부) 𠤎는 여기서는 「七」(シチ)가 살짝 변형된 것으로, 본래 “칼로 무언가를 내리치는 모습”을 그린 글자입니다(링크 참조).","叱는 “입(口)으로 베다(𠤎) -> “꾸짖다, 야단치다”라는 뜻의 글자입니다.","(𠤎->七는 소리부(シチ -> シツ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/2044/"},"嫉":{"id":2033,"char":"嫉","hun":"미워할 질","meaning":"“미워할 질”. 질투","on":"シツ","kun":"","explanation":["嫉 = 女 + 疾。","(의미부) 「女」는 “여자”를 뜻합니다.","(소리부 겸 의미부) 「疾」(シツ)는 “병, 질병”을 뜻합니다.","嫉는 “여자(女)의 고질병(疾)” -> “질투”라는 뜻의 글자입니다.","(疾는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/2045/"},"腫":{"id":2034,"char":"腫","hun":"종기 종","meaning":"“종기 종”. 종기","on":"シュ","kun":"は(れる)、は(らす)","explanation":["腫 = 月 + 重。","(의미부) 「月」는 “신체의 일부”를 뜻합니다.","(소리부 겸 의미부) 「重」(ジュウ)는 “무겁다”라는 뜻입니다.","腫는 “몸(月)에 무거운(重) 종기가 부어오르다” -> “종기”라는 뜻의 글자입니다.","(重는 소리부(ジュウ -> シュ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/2046/"},"呪":{"id":2035,"char":"呪","hun":"빌 주","meaning":"“빌 주”. 주문, 저주","on":"ジュ","kun":"のろ(う)","explanation":["呪 = 口 + 兄。","「口」는 “입”을 뜻합니다.","「兄」는 “형”을 뜻합니다. 여기서는 단순히 “사람”이라는 뜻으로 쓰인 것입니다.","呪는 “주문을 외우는(口) 제사장(兄)” -> “주문, 저주”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/2047/"},"蹴":{"id":2036,"char":"蹴","hun":"찰 축","meaning":"“찰 축”. 차다","on":"シュウ","kun":"け(る)","explanation":["蹴 = 足 + 就。","(의미부) 「足」는 “발”을 뜻합니다.","(소리부 겸 의미부) 「就」(シュウ)는 “나아가다, 이르다, 취임하다”라는 뜻입니다.","蹴는 “발(足)로 차서 날려보내다(就)” -> “차다”라는 뜻의 글자입니다.","(就는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/2048/"},"拭":{"id":2037,"char":"拭","hun":"씻을 식","meaning":"“씻을 식”. 씻다, 닦다","on":"ショク","kun":"ふ(く)、ぬぐ(う)","explanation":["拭 = 扌 + 式。","(의미부) 「扌」는 “손”을 뜻합니다.","(소리부 겸 의미부) 「式」(シキ)는 “형식, 의식”을 뜻합니다.","拭는 “중요한 의식(式)에 앞서 제단을 깨끗이 닦다(扌)” -> “씻다, 닦다”라는 뜻의 글자입니다.","(式는 소리부(シキ -> ショク)도 겸함)"],"sourceUrl":"https://nihongokanji.com/2049/"},"尻":{"id":2038,"char":"尻","hun":"꽁무니 고","meaning":"“꽁무니 고”. 엉덩이","on":"","kun":"しり","explanation":["尻 = 尸 + 九。","(의미부) 「尸」는 “앉아있는 사람”을 뜻합니다.","(소리부) 「九」(ク)는 여기서는 소리부(ク -> コウ)의 역할만 하고 있습니다.","(尻에는 정식 음독이 없으나, 본래의 음독은 コウ입니다.)","尻는 “엉덩이를 대고 앉다(尸)” -> “엉덩이”라는 뜻의 글자입니다(九는 소리부)."],"sourceUrl":"https://nihongokanji.com/2050/"},"芯":{"id":2039,"char":"芯","hun":"골풀 심","meaning":"“골풀 심”. 심지, 심","on":"シン","kun":"","explanation":["芯 = 艹 + 心。","(의미부) 「艹」는 “풀”을 뜻합니다.","(소리부) 「心」(シン)은 여기서는 소리부의 역할만 하고 있습니다.","芯은 “식물(艹)의 줄기” -> “심지, 심”이라는 뜻의 글자입니다(心는 소리부)."],"sourceUrl":"https://nihongokanji.com/2051/"},"腎":{"id":2040,"char":"腎","hun":"콩팥 신","meaning":"“콩팥 신”. 신장, 콩팥","on":"ジン","kun":"","explanation":["腎 = 臣 + 又 + 月。","(소리부) 「臣」(ジン)은 여기서는 소리부의 역할만 하고 있습니다.","(의미부) 「又」는 “또, 다시, 재차”라는 뜻입니다.","(의미부) 「月」는 “신체의 일부”를 뜻합니다.","腎은 “몸에 두 개(又) 붙어있는 장기(月)” -> “신장”이라는 뜻의 글자입니다(臣는 소리부)."],"sourceUrl":"https://nihongokanji.com/2052/"},"裾":{"id":2041,"char":"裾","hun":"옷자락 거","meaning":"“옷자락 거”. 옷단, 옷자락","on":"","kun":"すそ","explanation":["裾 = 衤 + 居。","「衤」는 “옷”을 뜻합니다.","居는 여기서는 “옷자락을 땅에 늘어뜨리고(尸) 걷는 사람(古)”을 그린 모양자입니다.","裾는 “땅에 늘어진(居) 옷자락(衤)” -> “옷단, 옷자락”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/2053/"},"凄":{"id":2042,"char":"凄","hun":"쓸쓸할 처","meaning":"“쓸쓸할 처”. 쓸쓸한, 처량한, 처참한","on":"セイ","kun":"","explanation":["凄 = 冫 + 妻。","(의미부) 「冫」는 “얼음”을 뜻합니다.","(소리부 겸 의미부) 「妻」(サイ)는 “아내”를 뜻합니다.","凄는 “남편이 죽어 차가운(冫) 방 안에 홀로 쓸쓸히 남은 아내(妻)” -> “쓸쓸한, 처량한, 처참한”이라는 뜻의 글자입니다.","(妻는 소리부(サイ -> セイ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/2054/"},"醒":{"id":2043,"char":"醒","hun":"깰 성","meaning":"“깰 성”. (술을)깨다, 깨닫다, 각성","on":"セイ","kun":"","explanation":["醒 = 酉 + 星。","(의미부) 「酉」는 “술”을 뜻합니다.","(소리부 겸 의미부) 「星」(セイ)는 “별”을 뜻합니다.","醒는 “술(酉)이 깨고 밝은(星) 정신이 돌아오다” -> “(술을)깨다, 깨닫다, 각성”이라는 뜻의 글자입니다.","(星는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/2055/"},"戚":{"id":2044,"char":"戚","hun":"친척 척","meaning":"“친척 척”. 친척","on":"セキ","kun":"","explanation":["戚 = 戊 + 尗。","「戊」는 “창”을 뜻합니다.","「尗」는 “식물의 줄기와 뿌리”를 그린 글자입니다.","戚는 “하나의 혈통과 뿌리(尗)로 이어진 가족을 지키다(戊)” -> “친척”이라는 뜻의 글자입니다.","참고)","戚가 “친척”이라는 뜻으로 쓰이게 된 시기는 「叔」가 “숙부”라는 뜻으로 쓰이기 시작한 시기와 비슷합니다."],"sourceUrl":"https://nihongokanji.com/2056/"},"脊":{"id":2045,"char":"脊","hun":"등마루 척","meaning":"“등마루 척”. 등, 등뼈","on":"セキ","kun":"","explanation":["脊 = 二 + 人 + 二 + 月。","二+人+二는 여기서는 “등근육과 어깨뼈”를 본따 그린 모양자입니다.","「月」는 “신체의 일부”를 뜻합니다.","脊는 “등근육, 어깨뼈(二+人+二) + 신체의 일부(月)” -> “등, 등뼈”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/2057/"},"煎":{"id":2046,"char":"煎","hun":"달일 전","meaning":"“달일 전”. 달이다, 조리다, 굽다","on":"セン","kun":"い(る)","explanation":["煎 = 前 + 灬。","(소리부) 「前」(ゼン)은 여기서는 소리부(ゼン -> セン)의 역할만 하고 있습니다.","(의미부) 「灬」는 “불”을 뜻합니다.","煎은 “불(灬)에 오랫동안 달이다” -> “달이다, 조리다, 굽다”라는 뜻의 글자입니다(前는 소리부)."],"sourceUrl":"https://nihongokanji.com/2058/"},"羨":{"id":2047,"char":"羨","hun":"부러워할 선","meaning":"“부러워할 선”. 부러워하다","on":"セン","kun":"うらや(む)、うらや(ましい)","explanation":["羨 = 𦍌 + 氵 + 欠。","「𦍌」는 “양”을 뜻합니다.","「氵」는 “물”을 뜻합니다.","「欠」는 “입을 벌린 사람”을 뜻합니다.","羨는 “양고기(𦍌)를 보고 입을 벌린 채(欠) 침(氵)을 흘리며 탐내다” -> “부러워하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/2059/"},"腺":{"id":2048,"char":"腺","hun":"샘 선","meaning":"“샘 선”. 생물체 내의 분비선","on":"セン","kun":"","explanation":["腺 = 月 + 泉。","(의미부) 「月」는 “신체의 일부”를 뜻합니다.","(소리부 겸 의미부) 「泉」(セン)은 “샘, 샘물”을 뜻합니다.","腺은 “액체가 분비되는(泉) 신체 기관(月)” -> “생물체 내의 분비선”이라는 뜻의 글자입니다.","(泉는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/2060/"},"詮":{"id":2049,"char":"詮","hun":"설명할 전","meaning":"“설명할 전”. 자세히 조사하다","on":"セン","kun":"","explanation":["詮 = 言 + 全。","(의미부) 「言」는 “말하다”라는 뜻입니다.","(소리부 겸 의미부) 「全」(ゼン)은 “전부”라는 뜻입니다.","詮는 “자세히 뒷조사해서 전부(全) 일러바치다(言)” -> “자세히 조사하다”라는 뜻의 글자입니다.","(全는 소리부(ゼン -> セン)도 겸함)"],"sourceUrl":"https://nihongokanji.com/2061/"},"膳":{"id":2050,"char":"膳","hun":"반찬 선","meaning":"“반찬 선”. 차려진 요리, 밥상","on":"ゼン","kun":"","explanation":["膳 = 月 + 善。","(의미부) 「月」는 “고기”를 뜻합니다.","(소리부 겸 의미부) 「善」(ゼン)은 “착하다, 바르다”라는 뜻입니다.","膳는 “가지런히(善) 차려진 고기밥상(月)” -> “차려진 요리, 밥상”이라는 뜻의 글자입니다.","(善는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/2062/"},"曽":{"id":2051,"char":"曽","hun":"일찍 증","meaning":"“일찍 증”. 증조부","on":"ソウ","kun":"","explanation":["「曽」는 “쌓이다”라는 뜻입니다.","“여러 대에 걸쳐 쌓이며 이어져 내려온 가계도” -> “증조부”라는 의미입니다."],"sourceUrl":"https://nihongokanji.com/2063/"},"狙":{"id":2052,"char":"狙","hun":"엿볼 저","meaning":"“엿볼 저”. 노리다, 겨냥하다","on":"ソ","kun":"ねら(う)","explanation":["狙 = 犭 + 且。","(의미부) 「犭」는 “개, 짐승”을 뜻합니다.","(소리부 겸 의미부) 「且」(ソ)는 “비석”을 뜻합니다.","狙는 “비석(且) 뒤에 숨어서 사냥감을 노리는 들개(犭)” -> “노리다, 겨냥하다”라는 뜻의 글자입니다.","(且는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/2064/"},"遡":{"id":2053,"char":"遡","hun":"거스를 소","meaning":"“거스를 소”. 거슬러 올라가다","on":"ソ","kun":"さかのぼ(る)","explanation":["遡 = 逆 + 月。","「逆」는 “거꾸로”라는 뜻입니다.","「月」는 “달”을 뜻합니다.","遡는 “달빛(月)을 따라 거슬러 올라가다(逆)” -> “거슬러 올라가다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/2065/"},"痩":{"id":2054,"char":"痩","hun":"여윌 수","meaning":"“여윌 수”. 여위다, 마르다, 수척하다","on":"ソウ","kun":"や(せる)","explanation":["痩 = 疒 + 申 + 又。","(의미부) 「疒」는 “병, 질병”을 뜻합니다.","(소리부 겸 의미부) 申+又는 여기서는 「捜」(ソウ)가 축약된 것으로, “찾다, 수색하다”라는 뜻입니다.","痩는 “병(疒)의 원인을 찾지(捜) 못해 나날이 여위고 수척해지다” -> “여위다, 마르다, 수척하다”라는 뜻의 글자입니다.","(申+又->捜는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/2066/"},"捉":{"id":2055,"char":"捉","hun":"잡을 착","meaning":"“잡을 착”. 붙잡다, 붙들다","on":"ソク","kun":"とら(える)","explanation":["捉 = 扌 + 足。","(의미부) 「扌」는 “손”을 뜻합니다.","(소리부 겸 의미부) 「足」(ソク)는 “발”을 뜻합니다.","捉는 “도망치는 발(足)을 붙들다(扌)” -> “붙잡다, 붙들다”라는 뜻의 글자입니다.","(足는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/2067/"},"袖":{"id":2056,"char":"袖","hun":"소매 수","meaning":"“소매 수”. 옷소매","on":"シュウ","kun":"そで","explanation":["袖 = 衤 + 由。","(의미부) 「衤」는 “옷”을 뜻합니다.","(소리부) 「由」(ユウ)는 여기서는 소리부(ユウ -> シュウ)의 역할만 하고 있습니다.","袖는 “옷(衤)의 양쪽 소매” -> “옷소매”라는 뜻의 글자입니다(由는 소리부)."],"sourceUrl":"https://nihongokanji.com/2068/"},"遜":{"id":2057,"char":"遜","hun":"겸손할 손","meaning":"“겸손할 손”. 겸손하다","on":"ソン","kun":"","explanation":["遜 = 辶 + 孫。","(의미부) 辶는 「⻌」가 살짝 변형된 것으로, “길”을 뜻합니다.","(소리부 겸 의미부) 「孫」(ソン)은 “손자”를 뜻합니다.","遜은 “길(辶)에서 만난 손자(孫)가 공손히 인사하다” -> “겸손하다”라는 뜻의 글자입니다.","(孫는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/2069/"},"唾":{"id":2058,"char":"唾","hun":"침 타","meaning":"“침 타”. 침, 타액","on":"ダ","kun":"つば","explanation":["唾 = 口 + 垂。","「口」는 “입”을 뜻합니다.","「垂」는 “드리우다, 매달리다”라는 뜻입니다.","唾는 “입가(口)에 늘어진(垂) 침” -> “침, 타액”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/2070/"},"堆":{"id":2059,"char":"堆","hun":"쌓을 퇴","meaning":"“쌓을 퇴”. 높이 쌓임, 퇴적","on":"タイ","kun":"","explanation":["堆 = 土 + 隹。","「土」는 “흙”을 뜻합니다.","「隹」는 “새”를 뜻합니다.","堆는 “산더미처럼 쌓인(土) 새들의 시체(隹)” -> “높이 쌓임, 퇴적”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/2071/"},"戴":{"id":2060,"char":"戴","hun":"일 대","meaning":"“일 대”. 머리에 이다, 얹다, 받들다","on":"タイ","kun":"","explanation":["戴 = 𢦏 + 異。","(소리부 겸 의미부) 「𢦏」(サイ)는 “화려한 의장용 창”을 뜻합니다.","(의미부) 「異」는 본래 “머리에 가면을 쓴 사람”을 그린 글자입니다(링크 참조).","여기서는 단순히 “머리에 쓰다”라는 뜻으로 쓰인 것입니다.","戴는 “대관식”을 표현한 글자입니다.","“화려한 창(𢦏)을 들고 왕관을 머리에 쓰다(異)” -> “머리에 이다, 얹다, 받들다”라는 의미입니다.","(𢦏는 소리부(サイ -> タイ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/2072/"},"誰":{"id":2061,"char":"誰","hun":"누구 수","meaning":"“누구 수”. 누구","on":"","kun":"だれ","explanation":["誰 = 言 + 隹。","「言」는 “말하다”라는 뜻입니다.","「隹」는 “새”를 뜻합니다.","誰는 “저 이상하게 생긴 새(隹)는 이름이 무엇이냐(言)” -> “누구냐, 누구”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/2073/"},"綻":{"id":2062,"char":"綻","hun":"터질 탄","meaning":"“터질 탄”. 터지다, 벌어지다","on":"タン","kun":"ほころ(びる)","explanation":["綻 = 糸 + 定。","「糸」는 “실”을 뜻합니다.","「定」는 “정하다, 정해지다”라는 뜻입니다.","綻는 “실(糸)로 단단히 꿰맨(定) 부분이 다시 터지다” -> “터지다, 벌어지다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/2074/"},"酎":{"id":2063,"char":"酎","hun":"전국술 주","meaning":"“전국술 주”. 소주","on":"チュウ","kun":"","explanation":["酎 = 酉 + 寸。","「酉」는 “술, 술병”을 뜻합니다.","「寸」는 “손”을 뜻합니다.","酎는 “술(酉)을 따르는 손(寸)” -> “소주”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/2075/"},"捗":{"id":2064,"char":"捗","hun":"칠 척","meaning":"“칠 척”. 진척되다, 나아가다","on":"チョク","kun":"","explanation":["捗 = 扌 + 步。","「扌」는 “손”을 뜻합니다.","步는 「歩」가 살짝 변형된 것으로, “걷다”라는 뜻입니다.","捗는 “손(扌)으로 밀며 앞으로 나아가다(步)” -> “진척되다, 나아가다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/2076/"},"潰":{"id":2065,"char":"潰","hun":"무너질 궤","meaning":"“무너질 궤”. 무너지다, 으깨다","on":"カイ","kun":"つぶ(す)、つぶ(れる)","explanation":["潰 = 氵 + 貴。","(의미부) 「氵」는 “물”을 뜻합니다.","(소리부 겸 의미부) 「貴」(キ)는 “귀하다”라는 뜻입니다.","潰는 “귀한(貴) 물건들이 홍수(氵)에 전부 쓸려나가다” -> “무너지다, 으깨다”라는 뜻의 글자입니다.","(貴는 소리부(キ -> カイ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/2077/"},"爪":{"id":2066,"char":"爪","hun":"손톱 조","meaning":"“손톱 조”. 손톱, 발톱","on":"","kun":"つめ、つま","explanation":["爪는 “손톱으로 무언가를 긁는 모습”을 그린 상형문자입니다."],"sourceUrl":"https://nihongokanji.com/2078/"},"諦":{"id":2067,"char":"諦","hun":"살필 체","meaning":"“살필 체”. 진실, 포기하다","on":"テイ","kun":"あきら(める)","explanation":["諦 = 言 + 帝。","(의미부) 「言」는 “말하다”라는 뜻입니다.","(소리부 겸 의미부) 「帝」(テイ)는 “황제”를 뜻합니다.","諦는,","“황제(帝)에게 진실만을 남김없이 아뢰다(言)” -> “진실”","“황제(帝)의 명령(言)이 떨어져 거스르는 것을 단념하다” -> “포기하다”","라는 뜻의 글자입니다.","(帝는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/2079/"},"溺":{"id":2068,"char":"溺","hun":"빠질 익","meaning":"“빠질 익”. 빠지다","on":"デキ","kun":"おぼ(れる)","explanation":["溺 = 氵 + 弱。","「氵」는 “물”을 뜻합니다.","「弱」는 “약하다”라는 뜻입니다.","溺는 “물(氵)에 빠져 힘을 잃고(弱) 가라앉다” -> “빠지다, 가라앉다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/2080/"},"塡":{"id":2069,"char":"塡","hun":"메울 전","meaning":"“메울 전”. 메우다, 채우다","on":"テン","kun":"","explanation":["塡 = 土 + 眞。","「土」는 “흙, 땅”을 뜻합니다.","眞는 「真」가 살짝 변형된 것으로, “참, 진실”을 뜻합니다.","塡은 “진심(真)을 담아 무덤(土)에 정성껏 묻어주다” -> “메우다, 채우다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/2081/"},"貼":{"id":2070,"char":"貼","hun":"붙일 첩","meaning":"“붙일 첩”. 붙이다","on":"チョウ","kun":"は(る)","explanation":["貼 = 貝 + 占。","「貝」는 “조개”를 뜻합니다.","占는 여기서는 「粘」가 축약된 것으로, “끈적이다”라는 뜻입니다.","貼는 “끈적한 풀(粘)로 조개껍데기(貝)를 액자에 붙여 보관하다” -> “붙이다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/2082/"},"妬":{"id":2071,"char":"妬","hun":"샘낼 투","meaning":"“샘낼 투”. 질투","on":"ト","kun":"ねた(む)","explanation":["妬 = 女 + 石。","「女」는 “여자”를 뜻합니다.","「石」는 “돌”을 뜻합니다.","妬는 “질투에 가득찬 여자(女)가 상대방에게 돌(石)을 던지다” -> “질투하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/2083/"},"賭":{"id":2072,"char":"賭","hun":"내기 도","meaning":"“내기 도”. 내기, 도박","on":"ト","kun":"か(ける)","explanation":["賭 = 貝 + 者。","「貝」는 “돈, 재물”을 뜻합니다.","「者」는 “사람”을 뜻합니다.","賭는 “돈(貝)을 거는 사람(者)” -> “내기, 도박”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/2084/"},"栃":{"id":2073,"char":"栃","hun":"칠엽수(지명한자)","meaning":"칠엽수(지명한자)","on":"","kun":"とち","explanation":["栃 = 木 + 𠂆 + 万。","「木」는 “나무”를 뜻합니다.","𠂆는 여기서는 “나무그늘”을 그린 모양자입니다.","「万」는 “1만”을 뜻합니다.","栃는 “나무그늘(𠂆)에서 만 명(万)도 쉴 수 있을 듯한 거대한 나무(木)” -> “칠엽수”라는 뜻의 글자입니다.","(다만, 이 한자는 실제로는 거의 지명한자로만 쓰이는 글자입니다.)"],"sourceUrl":"https://nihongokanji.com/2085/"},"頓":{"id":2074,"char":"頓","hun":"조아릴 돈","meaning":"“조아릴 돈”. 조아리다, 갑자기, 정돈하다","on":"トン","kun":"","explanation":["頓 = 屯 + 頁。","(소리부 겸 의미부) 「屯」(トン)은 “뿌리깊은 나무”를 그린 글자입니다(링크 참조).","(의미부) 「頁」는 “머리”를 뜻합니다.","頓는 “머리(頁)를 땅에 깊숙이 박고(屯) 조아리다”라는 뜻입니다.","“황급히 머리를 조아리다” -> “조아리다, 갑자기”","“서열을 정돈하다” -> “정돈하다”","라는 의미입니다.","(屯는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/2086/"},"謎":{"id":2075,"char":"謎","hun":"수수께끼 미","meaning":"“수수께끼 미”. 수수께끼, 불가사의","on":"","kun":"なぞ","explanation":["謎 = 言 + 迷。","「言」는 “말하다”라는 뜻입니다.","「迷」는 “헤메다, 헷갈리다”라는 뜻입니다.","謎는 “헷갈리는(迷) 말(言)” -> “수수께끼, 불가사의”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/2087/"},"鍋":{"id":2076,"char":"鍋","hun":"냄비","meaning":"냄비","on":"","kun":"なべ","explanation":["鍋 = 金 + 咼。","「金」는 “쇠, 금속”을 뜻합니다.","「咼」는 “잘못되다, 어긋나다”라는 뜻입니다.","鍋는 “놋쇠(金)로 만든 찌그러진(咼) 냄비” -> “냄비”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/2088/"},"匂":{"id":2077,"char":"匂","hun":"향내 내","meaning":"“향내 내”. 냄새, 향기","on":"","kun":"にお(う)","explanation":["匂는 “코와 콧구멍”을 그린 상형문자입니다."],"sourceUrl":"https://nihongokanji.com/2089/"},"捻":{"id":2078,"char":"捻","hun":"비틀 염","meaning":"“비틀 염”. 비틀다, 꼬다","on":"ネン","kun":"","explanation":["捻 = 扌 + 念。","(의미부) 「扌」는 “손”을 뜻합니다.","(소리부) 「念」(ネン)은 여기서는 소리부의 역할만 하고 있습니다.","捻는 “손(扌)으로 잡아 비틀다” -> “비틀다, 꼬다”라는 뜻의 글자입니다(念는 소리부)."],"sourceUrl":"https://nihongokanji.com/2090/"},"罵":{"id":2079,"char":"罵","hun":"꾸짖을 매","meaning":"“꾸짖을 매”. 욕하다, 매도하다","on":"バ","kun":"ののし(る)","explanation":["罵 = 罒 + 馬。","(의미부) 「罒」는 “그물”을 뜻합니다.","(소리부 겸 의미부) 「馬」(バ)는 “말”을 뜻합니다.","罵는 “그물(罒)에 걸려 넘어진 말(馬)을 마구 비난하고 욕하다” -> “욕하다, 매도하다”라는 뜻의 글자입니다.","(馬는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/2091/"},"剝":{"id":2080,"char":"剝","hun":"벗길 박","meaning":"“벗길 박”. 벗겨내다, 빼앗다","on":"ハク","kun":"は(がす)、は(ぐ)、は(がれる)、は(げる)","explanation":["剝 = 彔 + 刂。","「彔」는 “염색하다, 물들이다”라는 뜻입니다.","「刂」는 “칼”을 뜻합니다.","剝는 “염료가 물든 부분(彔)을 칼(刂)로 긁어내다” -> “벗겨내다, 빼앗다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/2092/"},"箸":{"id":2081,"char":"箸","hun":"젓가락 저","meaning":"“젓가락 저”. 젓가락","on":"","kun":"はし","explanation":["箸 = 𥫗 + 者。","「𥫗」는 “대나무”를 뜻합니다.","「者」는 “사람”을 뜻합니다.","箸는 “대나무 젓가락(𥫗)을 쓰는 사람(者)” -> “젓가락”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/2093/"},"斑":{"id":2082,"char":"斑","hun":"아롱질 반","meaning":"“아롱질 반”. 얼룩지다, 반점","on":"ハン","kun":"","explanation":["斑 = 𤣩 + 文 + 𤣩。","「𤣩」는 “구슬, 보석”을 뜻합니다.","「文」는 본래 “커다란 문신이 있는 사람”을 그린 글자입니다(링크 참조).","斑은 “몸에 구슬(𤣩) 모양의 반점이 여럿 있는 사람(文)” -> “얼룩지다, 반점”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/2094/"},"氾":{"id":2083,"char":"氾","hun":"넘칠 범","meaning":"“넘칠 범”. 넘치다, 범람하다","on":"ハン","kun":"","explanation":["氾 = 氵 + 㔾。","「氵」는 “물”을 뜻합니다.","「㔾」는 “무릎꿇은 사람”을 뜻합니다.","氾은 “폭우로 강(氵)이 범람해 절망하는 주민(㔾)” -> “넘치다, 범람하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/2095/"},"汎":{"id":2084,"char":"汎","hun":"넓을 범","meaning":"“넓을 범”. 모든, 두루 아우르다","on":"ハン","kun":"","explanation":["汎 = 氵 + 凡。","(의미부) 「氵」는 “물”을 뜻합니다.","(소리부 겸 의미부) 「凡」(ハン)은 “평범하다”라는 뜻입니다.","汎는 “어디에나 있는 평범한(凡) 물(氵)” -> “모든, 두루 아우르다”라는 뜻의 글자입니다.","(凡는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/2096/"},"膝":{"id":2085,"char":"膝","hun":"무릎 슬","meaning":"“무릎 슬”. 무릎","on":"","kun":"ひざ","explanation":["膝 = 月 + 桼。","(의미부) 「月」는 “신체의 일부”를 뜻합니다.","(소리부) 桼는 여기서는 「漆」(シツ)가 축약된 것으로, 소리부의 역할만 하고 있습니다.","(膝에는 정식 음독이 없으나, 본래의 음독은 シツ입니다.)","膝는 “신체 부위(月)” -> “무릎”이라는 뜻의 글자입니다(桼->漆는 소리부)."],"sourceUrl":"https://nihongokanji.com/2097/"},"肘":{"id":2086,"char":"肘","hun":"팔꿈치 주","meaning":"“팔꿈치 주”. 팔꿈치","on":"","kun":"ひじ","explanation":["肘 = 月 + 寸。","「月」는 “신체의 일부”를 뜻합니다.","「寸」는 “손”을 뜻합니다.","肘는 “손(寸)과 이어진 신체부위(月)” -> “팔꿈치”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/2098/"},"阜":{"id":2087,"char":"阜","hun":"언덕 부","meaning":"“언덕 부”. 언덕(지명한자)","on":"フ","kun":"","explanation":["阜는 “나란히 늘어선 언덕”의 모습을 그린 상형문자입니다.","(다만, 이 한자는 거의 지명한자로만 쓰이는 글자입니다.)"],"sourceUrl":"https://nihongokanji.com/2099/"},"蔽":{"id":2088,"char":"蔽","hun":"덮을 폐","meaning":"“덮을 폐”. 덮다, 덮어 가리다","on":"ヘイ","kun":"","explanation":["蔽 = 艹 + 敝。","(의미부) 「艹」는 “풀”을 뜻합니다.","(소리부 겸 의미부) 「敝」(ヘイ)는 “두들겨 맞아서 찢어진 옷”을 뜻합니다.","蔽는 “맞아서 찢어진 옷(敝)을 짚(艹)으로 덮어 숨겨놓고 모른척하다” -> “덮다, 덮어 가리다”라는 뜻의 글자입니다.","(敝는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/2100/"},"蔑":{"id":2089,"char":"蔑","hun":"업신여길 멸","meaning":"“업신여길 멸”. 업신여기다, 멸시하다","on":"ベツ","kun":"さげす(む)","explanation":["蔑 = 艹 + 罒 + 戌。","艹는 여기서는 “눈썹”을 그린 모양자입니다.","罒는 여기서는 「目」가 옆으로 기울어진 것으로, “눈”을 뜻합니다.","「戌」는 “창을 든 손”을 뜻합니다.","蔑는 “창을 든 병사(戌)가 눈썹을 찡그리고(艹) 포로를 내려다보며(罒) 멸시하다” -> “업신여기다, 멸시하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/2101/"},"蜂":{"id":2090,"char":"蜂","hun":"벌 봉","meaning":"“벌 봉”. 벌, 꿀벌","on":"ホウ","kun":"はち","explanation":["蜂 = 虫 + 夆。","(의미부) 「虫」는 “벌레”를 뜻합니다.","(소리부 겸 의미부) 夆는 여기서는 「峰」(ホウ)가 축약된 것으로, “산봉우리”를 뜻합니다.","蜂는 “산봉우리(峰)에 집을 짓고 사는 벌(虫)” -> “벌, 꿀벌”이라는 뜻의 글자입니다.","(夆->峰는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/2102/"},"貌":{"id":2091,"char":"貌","hun":"모양 모","meaning":"“모양 모”. 모양, 용모, 겉모습","on":"ボウ","kun":"","explanation":["貌 = 豸 + 白 + 儿。","豸는 여기서는 “등짐”을 그린 모양자입니다(1292.「懇」모양 해설 참조)","「白」는 “흰색”을 뜻합니다.","儿는 「人」가 살짝 변형된 것으로, “사람”을 뜻합니다.","貌는 “머나먼 서역에서 교역품(豸)을 들고 온 하얀(白) 얼굴의 서양인(儿)의 특이한 용모” -> “모양, 용모, 겉모습”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/2103/"},"頬":{"id":2092,"char":"頬","hun":"뺨 협","meaning":"“뺨 협”. 뺨","on":"","kun":"ほお","explanation":["頬 = 夹 + 頁。","「夹」는 “끼다, 끼이다”라는 뜻입니다.","「頁」는 “얼굴”을 뜻합니다.","頬는 “얼굴(頁)을 사이에 끼고(夹) 있는 양쪽 뺨” -> “뺨”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/2104/"},"勃":{"id":2093,"char":"勃","hun":"일어날/노할 발","meaning":"“일어날/노할 발”. 갑자기 일어나다, 불끈 일어나다","on":"ボツ","kun":"","explanation":["勃 = 孛 + 力。","「十」는 “10”을 뜻합니다.","冖는 여기서는 「宀」가 축약된 것으로, “집”을 뜻합니다.","「子」는 “아이”를 뜻합니다.","「力」는 “힘”을 뜻합니다.","勃는 “열 살(十)밖에 안된 아이(子)가 집(冖)을 번쩍 들어올리다(力)” -> “갑자기 일어나다, 불끈 일어나다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/2105/"},"昧":{"id":2094,"char":"昧","hun":"어두울 매","meaning":"“어두울 매”. 어둡다, 어슴푸레하다","on":"マイ","kun":"","explanation":["昧 = 日 + 未。","(의미부) 「日」는 “태양”을 뜻합니다.","(소리부 겸 의미부) 「未」(ミ)는 “아직”이라는 뜻입니다.","昧는 “해(日)가 아직(未) 안 뜨다” -> “어둡다, 어슴푸레하다”라는 뜻의 글자입니다.","(未는 소리부(ミ -> マイ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/2106/"},"枕":{"id":2095,"char":"枕","hun":"베개 침","meaning":"“베개 침”. 베개","on":"","kun":"まくら","explanation":["枕 = 木 + 冘。","「木」는 “나무”를 뜻합니다.","冘는 여기서는 “베개(冖)를 베고 있는 사람(人)“을 그린 모양자입니다.","枕는 “나무(木)로 만든 베개를 베고 있는 사람(冘)” -> “베개”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/2107/"},"蜜":{"id":2096,"char":"蜜","hun":"꿀 밀","meaning":"“꿀 밀”. 꿀","on":"ミツ","kun":"","explanation":["蜜 = 宓 + 虫。","(소리부 겸 의미부) 宓는 여기서는 「密」(ミツ)가 축약된 것으로, “비밀의, 빈틈없는”이라는 뜻입니다.","(의미부) 「虫」는 “벌레”를 뜻합니다.","蜜는 “벌(虫)이 벌집 깊숙이 숨겨둔(密) 꿀” -> “꿀”이라는 뜻의 글자입니다.","(宓->密는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/2108/"},"冥":{"id":2097,"char":"冥","hun":"어두울 명","meaning":"“어두울 명”. 어둡다","on":"メイ、ミョウ","kun":"","explanation":["冥 = 冖 + 日 + 六。","冖는 여기서는 “덮다, 가리다”라는 뜻을 표현한 모양자입니다.","「日」는 “날짜”를 뜻합니다.","「六」는 “6”을 뜻합니다.","冥는 “한 달에 6일(六+日)은 달이 가려져(冖) 밤이 어두워진다” -> “어둡다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/2109/"},"麺":{"id":2098,"char":"麺","hun":"밀가루 면","meaning":"“밀가루 면”. 면, 국수","on":"メン","kun":"","explanation":["麺 = 麦 + 面。","(의미부) 「麦」는 “보리, 밀, 귀리”를 뜻합니다.","(소리부) 「面」(メン)은 여기서는 소리부의 역할만 하고 있습니다.","麺은 “밀가루(麦)로 만든 국수” -> “면, 국수”라는 뜻의 글자입니다(面는 소리부)."],"sourceUrl":"https://nihongokanji.com/2110/"},"餅":{"id":2099,"char":"餅","hun":"떡 병","meaning":"“떡 병”. 떡","on":"ヘイ","kun":"もち","explanation":["餅 = 食 + 并。","(의미부) 왼쪽 글자는 「食」가 변형된 것으로, “먹다”라는 뜻입니다.","(소리부) 并는 여기서는 「併」(ヘイ)가 축약된 것으로, 소리부의 역할만 하고 있습니다.","餅는 “먹기 좋은(食) 떡” -> “떡”이라는 뜻의 글자입니다(并->併는 소리부)."],"sourceUrl":"https://nihongokanji.com/2111/"},"妖":{"id":2100,"char":"妖","hun":"요사할 요","meaning":"“요사할 요”. 요염하다, 괴이하다","on":"ヨウ","kun":"あや(しい)","explanation":["妖 = 女 + 夭。","「女」는 “여자”를 뜻합니다.","夭는 「天」가 살짝 변형된 것으로, “하늘”을 뜻합니다.","妖는 “하늘(夭)에서 내려온 듯 요염하게 생긴 여자(女)” -> “요염하다, 괴이하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/2112/"},"沃":{"id":2101,"char":"沃","hun":"기름질 옥","meaning":"“기름질 옥”. 기름지다, 비옥하다","on":"ヨク","kun":"","explanation":["沃 = 氵 + 夭。","「氵」는 “물”을 뜻합니다.","夭는 「天」가 살짝 변형된 것으로, “하늘”을 뜻합니다.","沃는 “하늘(夭)이 내린 기름지고(氵) 비옥한 땅” -> “기름지다, 비옥하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/2113/"},"侶":{"id":2102,"char":"侶","hun":"짝 려","meaning":"“짝 려”. 벗, 친구, 동료","on":"リョ","kun":"","explanation":["侶 = 亻 + 呂。","(의미부) 「亻」는 “사람”을 뜻합니다.","(소리부 겸 의미부) 「呂」(ロ)는 본래 “여러 채의 집이 이어져있는 모습”을 그린 글자입니다(링크 참조).","侶는 “서로 긴밀하게 이어진(呂) 사람들(亻)” -> “벗, 친구, 동료”라는 뜻의 글자입니다.","(呂는 소리부(ロ -> リョ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/2114/"},"賂":{"id":2103,"char":"賂","hun":"뇌물 뢰","meaning":"“뇌물 뢰”. 뇌물","on":"ロ","kun":"","explanation":["賂 = 貝 + 各。","「貝」는 “돈, 재물”을 뜻합니다.","「各」는 “각각, 각자”라는 뜻입니다.","賂는 “각(各) 파의 핵심 인물들을 전부 빠짐없이 돈으로(貝) 매수하다” -> “뇌물”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/2115/"},"弄":{"id":2104,"char":"弄","hun":"희롱할 롱","meaning":"“희롱할 롱”. 즐기다, 희롱하다","on":"ロウ","kun":"もてあそ(ぶ)","explanation":["弄 = 王 + 廾。","王는 여기서는 「玉」가 잘못 변형된 것으로, “구슬, 보석”을 뜻합니다.","廾는 여기서는 “양 손을 치켜든 모습”을 그린 모양자입니다.","弄는 “양 손(廾)으로 옥구슬(玉)을 들고 만지작거리며 놀다” -> “즐기다, 희롱하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/2116/"},"麓":{"id":2105,"char":"麓","hun":"산기슭 록","meaning":"“산기슭 록”. 산기슭","on":"ロク","kun":"ふもと","explanation":["麓 = 林 + 鹿。","「林」는 “숲”을 뜻합니다.","「鹿」는 “사슴”을 뜻합니다.","麓는 “숲(林)을 나와 기슭까지 내려온 사슴(鹿)” -> “산기슭”이라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/2117/"},"脇":{"id":2106,"char":"脇","hun":"겨드랑이 협","meaning":"“겨드랑이 협”. 겨드랑이","on":"","kun":"わき","explanation":["脇 = 月 + 劦。","「月」는 “신체의 일부”를 뜻합니다.","劦는 「力」 세 개가 합쳐진 것으로, “힘”을 뜻합니다.","脇는 “힘을 많이(劦) 쓰면 땀이 나는 신체부위(月)” -> “겨드랑이”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/2118/"},"丼":{"id":2107,"char":"丼","hun":"덮밥","meaning":"덮밥","on":"","kun":"どんぶり、どん","explanation":["丼는 “밥 위에 고기(丶)가 올려져있는 밥그릇(井)”을 그린 상형문자입니다."],"sourceUrl":"https://nihongokanji.com/2119/"},"傲":{"id":2108,"char":"傲","hun":"거만할 오","meaning":"“거만할 오”. 거만하다, 오만하다","on":"ゴウ","kun":"","explanation":["傲 = 倣 + 土。","(소리부 겸 의미부) 「倣」(ホウ)는 “모방하다, 본뜨다, 따르다”라는 뜻입니다.","(의미부) 「土」는 “흙, 땅”을 뜻합니다.","傲는 “이 땅(土) 위에 내가 따라서 배울(倣) 만한 사람은 아무도 없다” -> “거만하다, 오만하다”라는 뜻의 글자입니다.","(倣는 소리부(ホウ -> ゴウ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/2120/"},"刹":{"id":2109,"char":"刹","hun":"절 찰","meaning":"“절 찰”. 절, 사찰","on":"サツ、セツ","kun":"","explanation":["刹 = 杀 + 刂。","(소리부 겸 의미부) 杀는 여기서는 「殺」(サツ・セツ)가 축약된 것으로, “죽이다”라는 뜻입니다.","(의미부) 「刂」는 “칼”을 뜻합니다.","刹는 “칼(刂)을 든 산적을 만나 살해당할(殺) 위기에 처한 사람이 절에 도망쳐 숨다” -> “절, 사찰”이라는 뜻의 글자입니다.","(杀->殺는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/2121/"},"哺":{"id":2110,"char":"哺","hun":"먹일 포","meaning":"“먹일 포”. 먹이다, 먹여 기르다","on":"ホ","kun":"","explanation":["哺 = 口 + 甫。","(의미부) 「口」는 “입”을 뜻합니다.","(소리부 겸 의미부) 「甫」(ホ)는 “채소밭”을 뜻합니다.","哺는 “채소밭(甫)에서 기른 채소로 가족을 먹여(口) 살리다” -> “먹이다, 먹여 기르다”라는 뜻의 글자입니다.","(甫는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/2122/"},"喩":{"id":2111,"char":"喩","hun":"깨우칠 유","meaning":"“깨우칠 유”. 비유하다","on":"ユ","kun":"","explanation":["喩 = 口 + 兪。","(의미부) 「口」는 “입”을 뜻합니다.","(소리부) 兪는 「俞」(ユ)와 같은 글자로, 여기서는 소리부의 역할만 하고 있습니다.","喩는 “빗대어 말하다(口)” -> “비유하다”라는 뜻의 글자입니다(兪는 소리부)."],"sourceUrl":"https://nihongokanji.com/2123/"},"嗅":{"id":2112,"char":"嗅","hun":"맡을 후","meaning":"“맡을 후”. 냄새를 맡다","on":"キュウ","kun":"か(ぐ)","explanation":["嗅 = 口 + 臭。","(의미부) 口는 여기서는 “콧구멍”을 그린 모양자입니다.","(소리부 겸 의미부) 「臭」(シュウ)는 “냄새”를 뜻합니다.","嗅는 “콧구멍(口)으로 냄새(臭)를 맡다” -> “냄새를 맡다”라는 뜻의 글자입니다.","(臭는 소리부(シュウ -> キュウ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/2124/"},"嘲":{"id":2113,"char":"嘲","hun":"비웃을 조","meaning":"“비웃을 조”. 비웃다, 조롱하다","on":"チョウ","kun":"あざけ(る)","explanation":["嘲 = 口 + 朝。","(의미부) 「口」는 “입”을 뜻합니다.","(소리부) 「朝」(チョウ)는 여기서는 소리부의 역할만 하고 있습니다.","嘲는 “비웃음을 날리다(口)” -> “비웃다, 조롱하다”라는 뜻의 글자입니다(朝는 소리부)."],"sourceUrl":"https://nihongokanji.com/2125/"},"毀":{"id":2114,"char":"毀","hun":"헐 훼","meaning":"“헐 훼”. 부수다, 훼손하다","on":"キ","kun":"","explanation":["毀 = 臼 + 土 + 殳。","「臼」는 “절구”를 뜻합니다.","「土」는 “땅”을 뜻합니다.","「殳」는 “때리다, 휘두르다”라는 뜻입니다.","毀는 “절구(臼)를 땅(土) 위에 놓고 때려부수다(殳)” -> “부수다, 훼손하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/2126/"},"彙":{"id":2115,"char":"彙","hun":"고슴도치/무리 휘","meaning":"“고슴도치/무리 휘”. 같은 종류, 동류","on":"イ","kun":"","explanation":["彙 = 彑 + 冖 + 果。","彑는 여기서는 「互」가 축약된 것으로, “서로, 상호간의”라는 뜻입니다.","冖는 여기서는 “바구니”를 그린 모양자입니다.","「果」는 본래 “나무열매”를 그린 글자입니다(링크 참조).","彙는 “서로(互) 같은 종류의 열매(果)만 따로 모아서 담다(冖)” -> “같은 종류, 동류”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/2127/"},"恣":{"id":2116,"char":"恣","hun":"마음대로/방자할 자","meaning":"“마음대로/방자할 자”. 마음대로, 제멋대로, 방자하다","on":"シ","kun":"","explanation":["恣 = 次 + 心。","(소리부 겸 의미부) 「次」(シ)는 “다음”을 뜻합니다.","(의미부) 「心」는 “마음”을 뜻합니다.","恣는 “마음(心) 내키는 대로 나아가다(次)” -> “마음대로, 제멋대로, 방자하다”라는 뜻의 글자입니다.","(次는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/2128/"},"惧":{"id":2117,"char":"惧","hun":"두려워할 구","meaning":"“두려워할 구”. 두려움, 걱정","on":"グ","kun":"","explanation":["惧 = 忄 + 具。","(의미부) 「忄」는 “마음”을 뜻합니다.","(소리부) 「具」(グ)는 여기서는 소리부의 역할만 하고 있습니다.","惧는 “두려워하는 마음(忄)” -> “두려움, 걱정”이라는 뜻의 글자입니다(具는 소리부)."],"sourceUrl":"https://nihongokanji.com/2129/"},"慄":{"id":2118,"char":"慄","hun":"떨릴 률","meaning":"“떨릴 률”. 떨리다, 두려워하다","on":"リツ","kun":"","explanation":["慄 = 忄 + 覀 + 木。","「忄」는 “마음”을 뜻합니다.","「覀」는 “덮다”라는 뜻입니다.","「木」는 “나무”를 뜻합니다.","慄는 “나무(木)를 뒤덮은(覀) 메뚜기떼를 보고 두려움(忄)에 떨다” -> “떨리다, 두려워하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/2130/"},"憬":{"id":2119,"char":"憬","hun":"동경할 경","meaning":"“동경할 경”. 동경하다","on":"ケイ","kun":"","explanation":["憬 = 忄 + 景。","(의미부) 「忄」는 “마음”을 뜻합니다.","(소리부 겸 의미부) 「景」(ケイ)는 “경치”를 뜻합니다.","憬는 “산속의 수려한 경치(景)를 동경하는 마음(忄)” -> “동경하다”라는 뜻의 글자입니다.","(景는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/2131/"},"拉":{"id":2120,"char":"拉","hun":"끌 납","meaning":"“끌 납”. 끌고 가다, 납치하다","on":"ラ","kun":"","explanation":["拉 = 扌 + 立。","「扌」는 “손”을 뜻합니다.","「立」는 “서다”라는 뜻입니다.","拉는 “서있는 사람(立)을 강제로 끌고가다(扌)” -> “끌고 가다, 납치하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/2132/"},"摯":{"id":2121,"char":"摯","hun":"잡을 지","meaning":"“잡을 지”. 진지함","on":"シ","kun":"","explanation":["摯 = 執 + 手。","(소리부 겸 의미부) 「執」(シツ)는 “꼭 붙잡다”라는 뜻입니다.","(의미부) 「手」는 “손”을 뜻합니다.","摯는 “손(手)으로 꼭 붙잡고(執) 놓아주지 않다” -> “진지하다”라는 뜻의 글자입니다.","(執는 소리부(シツ -> シ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/2133/"},"曖":{"id":2122,"char":"曖","hun":"희미할 애","meaning":"“희미할 애”. 희미하다, 애매하다","on":"アイ","kun":"","explanation":["曖 = 日 + 愛。","(의미부) 「日」는 “태양”을 뜻합니다.","(소리부 겸 의미부) 「愛」(アイ)는 “사랑”을 뜻합니다.","曖는 “마음속에 희미하게 남은 사랑(愛)의 열기(日)” -> “희미하다, 애매하다”라는 뜻의 글자입니다.","(愛는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/2134/"},"楷":{"id":2123,"char":"楷","hun":"본보기 해","meaning":"“본보기 해”. 해서체(한자 서체의 하나)","on":"カイ","kun":"","explanation":["楷 = 木 + 皆。","(의미부) 「木」는 “나무”를 뜻합니다.","(소리부 겸 의미부) 「皆」(カイ)는 “모두, 전부”라는 뜻입니다.","楷는 “잘 쓴 글씨를 나무(木)에 걸어놓아 모두(皆) 보고 배울 수 있도록 하다” -> “해서체”라는 뜻의 글자입니다.","(皆는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/2135/"},"鬱":{"id":2124,"char":"鬱","hun":"답답할 울","meaning":"“답답할 울”. 우울하다, 울적하다","on":"ウツ","kun":"","explanation":["鬱 = 林 + 缶 + 冖 + 鬯 + 彡。","「林」는 “숲”을 뜻합니다.","「缶」는 “양철통”을 뜻합니다.","冖는 여기서는 「宀」가 축약된 것으로, “집”을 뜻합니다.","鬯는 여기서는 “고급스런 무늬(𠚍)가 새겨진 술잔(匕)”을 그린 모양자입니다.","彡는 여기서는 “상처”를 그린 모양자입니다.","鬱는 “마음의 상처(彡)를 달래기 위해 숲(林) 속의 오두막(冖)에 틀어박혀서 양철통(缶)에 술(鬯)을 담아 혼자 마시다” -> “우울하다, 울적하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/2136/"},"璧":{"id":2125,"char":"璧","hun":"구슬 벽","meaning":"“구슬 벽”. 구슬, 둥근 옥","on":"ヘキ","kun":"","explanation":["璧 = 辟 + 玉。","(소리부) 「辟」(ヘキ)는 여기서는 소리부의 역할만 하고 있습니다.","(의미부) 「玉」는 “구슬, 보석”을 뜻합니다.","璧는 “둥근 옥구슬(玉)” -> “구슬, 둥근 옥”이라는 뜻의 글자입니다(辟는 소리부)."],"sourceUrl":"https://nihongokanji.com/2137/"},"瘍":{"id":2126,"char":"瘍","hun":"헐 양","meaning":"“헐 양”. 헐다, 종기, 부스럼","on":"ヨウ","kun":"","explanation":["瘍 = 疒 + 昜。","(의미부) 「疒」는 “병, 질병”을 뜻합니다.","(소리부 겸 의미부) 「昜」(ヨウ)는 “햇볕, 뜨거운 햇살”을 뜻합니다.","瘍는 “뜨겁게(昜) 부풀어오른 종기(疒)” -> “헐다, 종기, 부스럼”이라는 뜻의 글자입니다.","(昜는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/2138/"},"箋":{"id":2127,"char":"箋","hun":"편지지 전","meaning":"“편지지 전”. 쪽지, 편지","on":"セン","kun":"","explanation":["箋 = 𥫗 + 戈 + 戈。","「𥫗」는 “대나무 죽간”을 뜻합니다.","「戈」는 “창”을 뜻합니다.","箋은 “창(戈戈)을 든 전령이 가져온 편지(𥫗)” -> “편지, 쪽지”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/2139/"},"籠":{"id":2128,"char":"籠","hun":"대바구니 롱","meaning":"“대바구니 롱”. 틀어박히다, 가두다, 바구니","on":"ロウ","kun":"かご、こも(る)","explanation":["籠 = 𥫗 + 龍。","「𥫗」는 “대나무”를 뜻합니다.","龍는 “용”을 그린 글자입니다(1291.「襲」 모양 해설 참조).","籠는 “대나무 줄기(𥫗) 속에 숨어들어간 가느다란 새끼 용(龍)” -> “틀어박히다, 가두다, 바구니”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/2140/"},"緻":{"id":2129,"char":"緻","hun":"빽빽할 치","meaning":"“빽빽할 치”. 빽빽하다","on":"チ","kun":"","explanation":["緻 = 糸 + 致。","(의미부) 「糸」는 “실”을 뜻합니다.","(소리부) 「致」(チ)는 여기서는 소리부의 역할만 하고 있습니다.","緻는 “빽빽하게 꿰매진 실(糸)” -> “빽빽하다”라는 뜻의 글자입니다(致는 소리부)."],"sourceUrl":"https://nihongokanji.com/2141/"},"羞":{"id":2130,"char":"羞","hun":"부끄러울 수","meaning":"“부끄러울 수”. 수치, 부끄러움","on":"シュウ","kun":"","explanation":["羞 = 差 + ⺕。","(소리부 겸 의미부) 「差」(サ)는 여기서는 “가리다(差さす)”라는 뜻으로 쓰인 것입니다.","(의미부) 「⺕」는 “손”을 뜻합니다.","羞는 “부끄러워 손(⺕)으로 얼굴을 가리다(差)” -> “수치, 부끄러움”이라는 뜻의 글자입니다.","(差는 소리부(サ -> シュウ)도 겸함)"],"sourceUrl":"https://nihongokanji.com/2142/"},"訃":{"id":2131,"char":"訃","hun":"부고 부","meaning":"“부고 부”. 부고, 부음","on":"フ","kun":"","explanation":["訃 = 言 + 卜。","(의미부) 「言」는 “말하다”라는 뜻입니다.","(소리부 겸 의미부) 卜는 여기서는 「赴」(フ)가 축약된 것으로, “향해 가다, 달려가다”라는 뜻입니다.","訃는 “부고를 알리러(言) 급히 달려가다(赴)” -> “부고, 부음”이라는 뜻의 글자입니다.","(卜->赴는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/2143/"},"諧":{"id":2132,"char":"諧","hun":"화할 해","meaning":"“화할 해”. 조화하다, 화합하다, 잘 어울리다","on":"カイ","kun":"","explanation":["諧 = 言 + 皆。","(의미부) 「言」는 “말하다”라는 뜻입니다.","(소리부 겸 의미부) 「皆」(カイ)는 “모두, 전부”라는 뜻입니다.","諧는 “다 함께(皆) 즐겁게 이야기하다(言)” -> “조화하다, 화합하다, 잘 어울리다”라는 뜻의 글자입니다.","(皆는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/2144/"},"貪":{"id":2133,"char":"貪","hun":"탐낼 탐","meaning":"“탐낼 탐”. 탐욕, 탐내다, 욕심부리다","on":"ドン","kun":"むさぼ(る)","explanation":["貪 = 今 + 貝。","「今」는 “지금”을 뜻합니다.","「貝」는 “돈, 재물”을 뜻합니다.","貪는 “당장(今)의 이익(貝)에 눈이 멀어 탐욕을 부리다” -> “탐욕, 탐내다, 욕심부리다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/2145/"},"踪":{"id":2134,"char":"踪","hun":"자취 종","meaning":"“자취 종”. 자취, 흔적","on":"ソウ","kun":"","explanation":["踪 = 足 + 宗。","(의미부) 「足」는 “발”을 뜻합니다.","(소리부 겸 의미부) 「宗」(ソウ)는 “으뜸, 종교”를 뜻합니다.","踪는 “위대한 성인(宗)의 발자취(足)” -> “자취, 흔적”이라는 뜻의 글자입니다.","(宗는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/2146/"},"辣":{"id":2135,"char":"辣","hun":"매울 랄","meaning":"“매울 랄”. 잔혹하다","on":"ラツ","kun":"","explanation":["辣 = 辛 + 束。","「辛」는 “문신을 새기는 고문 도구”를 뜻합니다.","「束」는 “묶다”라는 뜻입니다.","辣는 “묶어놓고(束) 고문하다(辛)” -> “잔혹하다”라는 뜻의 글자입니다."],"sourceUrl":"https://nihongokanji.com/2147/"},"錮":{"id":2136,"char":"錮","hun":"막을 고","meaning":"“막을 고”. 가두다","on":"コ","kun":"","explanation":["錮 = 金 + 固。","(의미부) 「金」는 “쇠, 금속”을 뜻합니다.","(소리부 겸 의미부) 「固」(コ)는 “단단하다, 딱딱하다”라는 뜻입니다.","錮는 “단단한(固) 쇠창살(金) 안에 가두다” -> “가두다”라는 뜻의 글자입니다.","(固는 소리부도 겸함)"],"sourceUrl":"https://nihongokanji.com/2148/"}}};
